headers.__SA_FUNCS__:
float bass() {
  return uSpectrum0 * 0.3 + uSpectrum1 * 0.5 + uSpectrum2 * 0.2;
}
float mids() {
  return uSpectrum2 * 0.3 + uSpectrum3 * 0.4 + uSpectrum4 * 0.3;
}
float treble() {
  return uSpectrum5 * 0.2 + uSpectrum6 * 0.5 + uSpectrum7 * 0.3;
}

// Beat anticipation: ramps UP ~50ms before the beat lands, sharp decay after.
// Returns a 0-1 pulse that peaks at the downbeat moment.
// Use: multiply with brightness/scale for perceived perfect audio-visual sync.
float beatAnticipate() {
  float anticipation = smoothstep(0.85, 1.0, uBeat);
  float release = exp(-uBeat * 8.0);
  return max(anticipation, release * uOnset);
}

// Apply beat anticipation as brightness + scale modulation to a color.
// strength: 0-1, how much the beat affects the output.
vec3 applyBeatAnticipation(vec3 color, float strength) {
  float pulse = beatAnticipate();
  color *= 1.0 + pulse * strength * 0.3;
  return color;
}

// ═══════════════════════════════════════════════════════════════
// PSYCHEDELIC ENHANCEMENT FUNCTIONS
// Extreme DMT/LSD/psilocybin/mescaline-inspired color processing
// ═══════════════════════════════════════════════════════════════

// Rainbow color cycling — rotates hue continuously based on luminance + time
// Creates the classic psychedelic "everything is rainbow" effect
vec3 psychedelicColor(vec3 c) {
  float luma = dot(c, vec3(0.299, 0.587, 0.114));
  // Multi-frequency rainbow based on luminance, time, and audio
  vec3 rainbow = 0.5 + 0.5 * cos(6.2832 * (luma * 3.0 + uTime * 0.15 + vec3(0.0, 0.33, 0.67)));
  // Second rainbow layer for more complexity
  vec3 rainbow2 = 0.5 + 0.5 * cos(6.2832 * (luma * 1.5 - uTime * 0.08 + vec3(0.1, 0.5, 0.8)));
  vec3 blendedRainbow = mix(rainbow, rainbow2, 0.3 + uEnergy * 0.2);
  // Mix strength: 35-60% based on energy
  float mixAmt = 0.35 + uEnergy * 0.25;
  c = mix(c, blendedRainbow * max(length(c), 0.2) * 1.6, mixAmt);
  // Extreme saturation boost
  float grey = dot(c, vec3(0.299, 0.587, 0.114));
  c = mix(vec3(grey), c, 1.7 + uEnergy * 0.3);
  // Vibrancy punch via gamma
  c = pow(max(c, 0.0), vec3(0.85));
  return c;
}

// Psychedelic UV morphing — makes surfaces breathe and warp
// Creates the classic "walls are breathing" LSD effect
vec2 psychedelicUV(vec2 uv) {
  float morphStr = 0.04 + uEnergy * 0.02;
  uv += morphStr * vec2(
    sin(uTime * 0.7 + uv.y * 4.0 + sin(uTime * 0.3) * 2.0),
    cos(uTime * 0.6 + uv.x * 4.0 + cos(uTime * 0.25) * 2.0)
  );
  // Secondary finer ripple
  uv += 0.015 * vec2(
    sin(uTime * 1.3 + uv.y * 8.0),
    cos(uTime * 1.1 + uv.x * 8.0)
  );
  return uv;
}

headers.__SA_FBM__:
// Fractal dimension control via persistence
// persistence 0.5 → D≈1.3, 0.65 → D≈1.4, 0.7 → D≈1.5
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmControlledD(vec2 p, float persistence, int octaves) {
  float amplitude = 1.0;
  float frequency = 1.0;
  float value = 0.0;
  float maxVal = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    value += amplitude * noise2d(p * frequency);
    maxVal += amplitude;
    amplitude *= persistence;
    frequency *= 2.0;
  }
  return value / maxVal;
}

presets.frag:
varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm4(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = rot * p * 2.0; a *= 0.5; }
  return v;
}

vec3 iridescent(float t, float shift) {
  return 0.5 + 0.5 * cos(6.2832 * (t * vec3(1.0, 0.8, 0.6) + vec3(0.0 + shift, 0.33, 0.67)));
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float harmVal = uHarmonicity * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Gravitational lensing distortion — bends space near center
  float lensStr = 0.3 + bassVal * 1.0;
  vec2 lensedP = p;
  if (r > 0.01) {
    float bend = lensStr * 0.15 / (r * r + 0.05);
    lensedP = p * (1.0 + bend);
  }
  float lensR = length(lensedP);
  float lensAngle = atan(lensedP.y, lensedP.x);

  // Deep void background
  vec3 col = vec3(0.01, 0.005, 0.02);

  // Distant stars warped by gravity — spread across full viewport
  for (float i = 0.0; i < 40.0; i++) {
    vec2 starPos = vec2(hash21(vec2(i, 7.3)), hash21(vec2(7.3, i))) * 3.0 - 1.5;
    float starDist = length(lensedP - starPos);
    float starBright = exp(-starDist * 80.0) * 0.15;
    col += vec3(0.7, 0.8, 1.0) * starBright;
  }

  // Event horizon — absolute black core
  float eventR = 0.12 + kickVal * 0.03;
  float bhMask = smoothstep(eventR + 0.02, eventR - 0.01, r);
  col *= (1.0 - bhMask);

  // Photon ring — bright ring at event horizon edge
  float photonRing = exp(-abs(r - eventR * 1.4) * 40.0);
  col += vec3(1.0, 0.85, 0.6) * photonRing * 0.8;

  // DMT fractal spiral arms — use smoothed angle to avoid atan seam
  float spiralCount = 5.0 + uChaos * 3.0;
  float spiralAngle = lensAngle + time * 0.6 + uBpmSin * 0.5;
  float logSpiral = spiralAngle * spiralCount - log(max(lensR, 0.001)) * 8.0;
  // Seamless wrap: use cos instead of sin to avoid discontinuity at +/-PI
  float spiral = cos(logSpiral + time * 2.2) * 0.5 + 0.5;
  spiral = pow(spiral, 2.0);

  // Disk region mask — extends to screen edges
  float diskInner = 0.15;
  float diskOuter = 1.8 + bassVal * 0.4;
  float diskMask = smoothstep(diskInner, diskInner + 0.08, r) * smoothstep(diskOuter, diskOuter - 0.3, r);

  // Fractal turbulence in the disk
  float turb = fbm4(vec2(lensAngle * 3.0, lensR * 6.0) + time * 0.5);
  float turb2 = fbm4(vec2(lensAngle * 5.0 + 10.0, lensR * 12.0) - time * 0.3);

  // Iridescent matter streams — violet/gold/cyan shifting
  float streamPhase = lensR * 3.0 + turb * 2.0 + uPalette * 0.5 + time * 0.35;
  vec3 streamCol = iridescent(streamPhase, fluxVal * 0.5);

  // DMT neon violet/gold/cyan palette override
  vec3 violet = vec3(0.8, 0.15, 1.0);
  vec3 gold = vec3(1.0, 0.85, 0.3);
  vec3 cyan = vec3(0.15, 1.0, 0.9);
  float palPhase = fract(streamPhase * 0.3);
  vec3 dmtCol = palPhase < 0.33 ? mix(violet, gold, palPhase * 3.0)
              : palPhase < 0.67 ? mix(gold, cyan, (palPhase - 0.33) * 3.0)
              : mix(cyan, violet, (palPhase - 0.67) * 3.0);
  streamCol = mix(streamCol, dmtCol, 0.75);

  // Combine spiral structure with turbulence
  float diskBright = diskMask * (spiral * 0.7 + turb * 0.35 + 0.15);
  diskBright *= (0.5 + midsVal * 1.0);
  col += streamCol * diskBright * 2.0;

  // Secondary inner glow — hyperdimensional core
  float innerGlow = exp(-r * r * 6.0) * (0.5 + harmVal * 1.2);
  col += vec3(0.9, 0.35, 1.0) * innerGlow;

  // Treble sparkle particles in the disk
  float sparkle = pow(turb2, 4.0) * trebleVal * diskMask;
  col += vec3(1.0, 0.9, 0.7) * sparkle * 3.5;

  // Kick flash — matter accretion burst
  float kickFlash = kickVal * exp(-r * 3.0) * 1.6;
  col += vec3(1.0, 0.6, 0.2) * kickFlash;

  // Spectral flux drives iridescence shimmer
  col += streamCol * fluxVal * diskMask * 0.2;

  // Chaos warps the whole structure
  float chaosWarp = vnoise(p * 4.0 + time) * uChaos * 0.15;
  col *= 1.0 + chaosWarp;

  // Doppler beaming — one side brighter
  float doppler = 1.0 + 0.4 * sin(lensAngle + time * 0.75);
  col *= doppler;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFaceSize;
uniform float uSpiralTightness;
uniform float uWobbleAmount;
uniform float uTripIntensity;

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio-reactive modulators — 2x
  float bassPulse = bass() * uSensitivity * 1.0;
  float midsShift = mids() * uSensitivity * 0.6;
  float trebleFlash = treble() * uSensitivity * 1.2;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float kickHit = uKick * uSensitivity;

  // === PSYCHEDELIC BACKGROUND SPIRAL ===
  float bgDist = p.x * p.x + p.y * p.y + 0.0001;
  float bgRadius = bgDist;

  float invBgR = 1.0 / (bgDist + 0.01);
  float bgNormX = p.x * invBgR;
  float bgNormY = p.y * invBgR;
  float bgAngle = bgNormY * 3.14159 + bgNormX * sin(bgNormY * 1.5);

  float spiralVal = bgAngle * 1.0
    + bgRadius * uSpiralTightness * 3.0
    - time * 0.8
    + bassPulse * 2.0;

  float spiralHue = fract(spiralVal * 0.1 + uPalette * 0.1 + time * 0.06 + sin(uTime * 0.3) * 0.2);
  float bgR0 = abs(fract(spiralHue + 1.0) * 6.0 - 3.0) - 1.0;
  float bgG0 = abs(fract(spiralHue + 0.6667) * 6.0 - 3.0) - 1.0;
  float bgB0 = abs(fract(spiralHue + 0.3333) * 6.0 - 3.0) - 1.0;

  float ringVal = sin(bgRadius * 15.0 - time * 1.5) * 0.5 + 0.5;
  float ringMix = ringVal * (uTripIntensity * 0.3);

  float bgR = clamp(bgR0 + ringMix * 0.2, 0.0, 1.0);
  float bgG = clamp(bgG0 + ringMix * 0.15, 0.0, 1.0);
  float bgB = clamp(bgB0 + ringMix * 0.25, 0.0, 1.0);

  // === SMILEY FACE SDF ===
  float breathe = sin(time * 0.8) * 0.03 + 1.0;
  float faceRadius = uFaceSize * breathe + beatPulse * 0.04;

  float wobbleX = sin(p.y * 12.0 + time * 2.0) * uWobbleAmount;
  float wobbleY = cos(p.x * 10.0 + time * 1.7) * uWobbleAmount;
  float fpx = p.x + wobbleX;
  float fpy = p.y + wobbleY;

  float faceDist = fpx * fpx + fpy * fpy;
  float faceRadiusSq = faceRadius * faceRadius;
  float faceMask = smoothstep(faceRadiusSq + 0.005, faceRadiusSq - 0.005, faceDist);

  // === FACE COLOR ===
  float colorCycle = sin(time * 0.5) * (uTripIntensity * 0.15);
  float colorCycle2 = cos(time * 0.7) * (uTripIntensity * 0.1);
  float faceR = 1.0 + colorCycle2 * 0.3;
  float faceG = 0.85 + colorCycle * 0.4;
  float faceB = 0.1 - abs(colorCycle) * 0.05;

  // === EYES ===
  float eyeOffX = faceRadius * 0.3;
  float eyeOffY = faceRadius * 0.2;
  float eyeRadX = faceRadius * 0.09;
  float eyeRadY = faceRadius * 0.13;

  float leX = (fpx + eyeOffX) / eyeRadX;
  float leY = (fpy - eyeOffY) / eyeRadY;
  float leftEyeDist = leX * leX + leY * leY;
  float leftEyeMask = smoothstep(1.2, 0.8, leftEyeDist);

  float reX = (fpx - eyeOffX) / eyeRadX;
  float reY = (fpy - eyeOffY) / eyeRadY;
  float winkPhase = sin(time * 0.4) * 0.5 + 0.5;
  float winkTrigger = step(0.92, winkPhase);
  float rightEyeScale = 1.0 - winkTrigger * 0.8;
  float reYScaled = reY / max(rightEyeScale, 0.2);
  float rightEyeDistScaled = reX * reX + reYScaled * reYScaled;
  float rightEyeMask = smoothstep(1.2, 0.8, rightEyeDistScaled);

  float eyeMask = max(leftEyeMask, rightEyeMask);
  float eyeGlow = trebleFlash * eyeMask * 0.5;

  // === SINGING MOUTH — LIP SYNC ===
  // Three frequency bands control mouth shape:
  //   bass  -> wide open (O/A shape, jaw drops)
  //   mids  -> medium open (E shape)
  //   treble -> narrow/pursed (U/OO shape)
  float bassRaw = bass() * uSensitivity;
  float midsRaw = mids() * uSensitivity;
  float trebleRaw = treble() * uSensitivity;
  float audioMouth = bassRaw * 0.6 + uEnergy * uSensitivity * 0.4;
  float mouthOpen = smoothstep(0.05, 0.45, audioMouth); // 0=closed, 1=wide open

  // Lip-sync shape interpolation
  // bassShape: wide + tall (shouting "O" / "A"), midsShape: medium, trebleShape: narrow + tall (pursed "U")
  float totalFreq = bassRaw + midsRaw + trebleRaw + 0.001;
  float bassWeight = bassRaw / totalFreq;
  float midsWeight = midsRaw / totalFreq;
  float trebleWeight = trebleRaw / totalFreq;

  // Width multiplier: bass=wide, mids=medium, treble=narrow
  float lipWidthMult = bassWeight * 1.4 + midsWeight * 1.0 + trebleWeight * 0.5;
  // Height multiplier: bass=very tall, mids=medium, treble=tall-narrow
  float lipHeightMult = bassWeight * 1.5 + midsWeight * 0.8 + trebleWeight * 1.2;

  // Jaw drop: bottom of face shifts down with heavy bass
  float jawDrop = mouthOpen * bassWeight * faceRadius * 0.06;

  // === MOUTH (singing oval with lip-sync shapes) ===
  float mouthCenterX = sin(time * 2.5) * midsRaw * 0.005; // slight lateral wobble
  float mouthCenterY = -faceRadius * 0.3 - jawDrop; // positioned at lower face
  // Lip-sync: width and height morph based on frequency dominance
  // Closed: wide thin smile; open: oval mouth shape
  float mouthRadiusX = faceRadius * (0.22 + 0.10 * mouthOpen * lipWidthMult);
  float mouthRadiusY = faceRadius * (0.03 + 0.25 * mouthOpen * lipHeightMult);
  // Smooth oval SDF
  float mouthDx = (fpx - mouthCenterX) / max(mouthRadiusX, 0.001);
  float mouthDy = (fpy - mouthCenterY) / max(mouthRadiusY, 0.001);
  float mouthOvalDist = mouthDx * mouthDx + mouthDy * mouthDy;
  float mouthFill = smoothstep(1.2, 0.8, mouthOvalDist) * mouthOpen;

  // Lip outline — thicker, more visible lip ring
  float lipThickness = faceRadius * 0.06 * (0.6 + mouthOpen * 0.4);
  float mouthOutline = smoothstep(lipThickness * lipThickness * 0.5, 0.0,
    abs(mouthOvalDist - 1.0) * mouthRadiusX * mouthRadiusY * 0.5) * mouthOpen;

  // Upper lip curve (subtle, no horizontal line artifacts)
  float upperLipCurve = 0.0;

  // Lower lip (subtle, no horizontal line artifacts)
  float lowerLipCurve = 0.0;

  // === TONGUE (when mouth is wide open — bass-heavy) ===
  float tongueShow = smoothstep(0.4, 0.8, mouthOpen) * bassWeight;
  float tongueCX = sin(time * 3.0) * faceRadius * 0.02; // slight tongue wiggle
  float tongueCY = mouthCenterY - mouthRadiusY * 0.35;
  float tongueRX = faceRadius * 0.10;
  float tongueRY = faceRadius * 0.07 * tongueShow;
  float tongueDx = (fpx - tongueCX) / max(tongueRX, 0.001);
  float tongueDy = (fpy - tongueCY) / max(tongueRY, 0.001);
  float tongueDist = tongueDx * tongueDx + tongueDy * tongueDy;
  float tongueMask = smoothstep(1.3, 0.7, tongueDist) * tongueShow * mouthFill;

  // === TEETH (visible when mouth partially open) ===
  float teethShow = smoothstep(0.2, 0.5, mouthOpen);
  // Top teeth row
  float teethTopY = mouthCenterY + mouthRadiusY * 0.65;
  float teethHeight = faceRadius * 0.04 * teethShow;
  float teethTopMask = step(abs(fpy - teethTopY), teethHeight)
    * step(abs(fpx - mouthCenterX), mouthRadiusX * 0.7)
    * teethShow * mouthFill;
  // Tooth gaps (3 small gaps)
  float toothGap = step(0.95, fract(fpx * 30.0 / faceRadius)) * 0.8;
  teethTopMask *= (1.0 - toothGap);

  // Bottom teeth (subtle, when very open)
  float teethBotY = mouthCenterY - mouthRadiusY * 0.55;
  float teethBotMask = step(abs(fpy - teethBotY), teethHeight * 0.7)
    * step(abs(fpx - mouthCenterX), mouthRadiusX * 0.5)
    * smoothstep(0.5, 0.8, mouthOpen) * mouthFill;
  teethBotMask *= (1.0 - step(0.93, fract(fpx * 25.0 / faceRadius)) * 0.6);

  // Combine mouth features
  float smileMask = mouthOutline + mouthFill + upperLipCurve + lowerLipCurve;

  // === COMBINE SMILEY ===
  float featureMask = max(eyeMask, smileMask);

  // Base face colors with features as dark
  float smileyR = mix(faceR, 0.05 + eyeGlow, featureMask);
  float smileyG = mix(faceG, 0.05 + eyeGlow * 0.5, featureMask);
  float smileyB = mix(faceB, 0.05, featureMask);

  // Tongue: pink/red color inside mouth
  smileyR = mix(smileyR, 0.85, tongueMask);
  smileyG = mix(smileyG, 0.25, tongueMask);
  smileyB = mix(smileyB, 0.3, tongueMask);

  // Teeth: white inside mouth (top + bottom)
  float allTeeth = max(teethTopMask, teethBotMask);
  smileyR = mix(smileyR, 0.95, allTeeth);
  smileyG = mix(smileyG, 0.95, allTeeth);
  smileyB = mix(smileyB, 0.95, allTeeth);

  // Lips: subtle pink/red tint on lip outlines
  float lipColor = (upperLipCurve + lowerLipCurve) * mouthOpen;
  smileyR = mix(smileyR, 0.75, lipColor * 0.6);
  smileyG = mix(smileyG, 0.25, lipColor * 0.6);
  smileyB = mix(smileyB, 0.25, lipColor * 0.6);

  // Face outline
  float outlineWidth = 0.008;
  float outerFace = smoothstep(
    faceRadiusSq + outlineWidth,
    faceRadiusSq,
    faceDist
  );
  float outlineMask = outerFace * (1.0 - faceMask);

  // === BACKGROUND SMILEYS ===
  // Smiley 1
  float s1x = p.x + 0.35 - sin(time * 0.2) * 0.05;
  float s1y = p.y - 0.25 + cos(time * 0.15) * 0.04;
  float s1Dist = s1x * s1x + s1y * s1y;
  float s1Radius = 0.08;
  float s1RadSq = s1Radius * s1Radius;
  float s1Mask = smoothstep(s1RadSq + 0.002, s1RadSq - 0.002, s1Dist);
  float s1eyeRad = 0.015;
  float s1leVal = (s1x + s1Radius * 0.3) * (s1x + s1Radius * 0.3)
    + (s1y - s1Radius * 0.2) * (s1y - s1Radius * 0.2);
  float s1reVal = (s1x - s1Radius * 0.3) * (s1x - s1Radius * 0.3)
    + (s1y - s1Radius * 0.2) * (s1y - s1Radius * 0.2);
  float s1eyeMask = max(
    smoothstep(s1eyeRad, s1eyeRad * 0.3, s1leVal),
    smoothstep(s1eyeRad, s1eyeRad * 0.3, s1reVal)
  );
  float s1feat = 1.0 - s1eyeMask;

  // Smiley 2
  float s2x = p.x - 0.3 + cos(time * 0.18) * 0.06;
  float s2y = p.y + 0.3 - sin(time * 0.22) * 0.04;
  float s2Dist = s2x * s2x + s2y * s2y;
  float s2Radius = 0.06;
  float s2RadSq = s2Radius * s2Radius;
  float s2Mask = smoothstep(s2RadSq + 0.002, s2RadSq - 0.002, s2Dist);

  // Smiley 3
  float s3x = p.x - 0.25 - sin(time * 0.25) * 0.04;
  float s3y = p.y - 0.35 + cos(time * 0.12) * 0.05;
  float s3Dist = s3x * s3x + s3y * s3y;
  float s3Radius = 0.07;
  float s3RadSq = s3Radius * s3Radius;
  float s3Mask = smoothstep(s3RadSq + 0.002, s3RadSq - 0.002, s3Dist);

  float smallSmileyColor1 = sin(time * 0.3) * 0.1 + 0.9;
  float smallSmileyColor2 = cos(time * 0.4) * 0.1 + 0.85;

  // === COMPOSITE ALL LAYERS ===
  float layerR0 = bgR * (uIntensity * 0.8);
  float layerG0 = bgG * (uIntensity * 0.8);
  float layerB0 = bgB * (uIntensity * 0.8);

  float smBgR1 = mix(layerR0, smallSmileyColor1 * s1feat, s1Mask * 0.7);
  float smBgG1 = mix(layerG0, 0.8 * s1feat, s1Mask * 0.7);
  float smBgB1 = mix(layerB0, 0.1 * s1feat, s1Mask * 0.7);

  float smBgR2 = mix(smBgR1, smallSmileyColor2, s2Mask * 0.6);
  float smBgG2 = mix(smBgG1, 0.82, s2Mask * 0.6);
  float smBgB2 = mix(smBgB1, 0.12, s2Mask * 0.6);

  float smBgR3 = mix(smBgR2, 0.95, s3Mask * 0.6);
  float smBgG3 = mix(smBgG2, 0.88, s3Mask * 0.6);
  float smBgB3 = mix(smBgB2, 0.15, s3Mask * 0.6);

  float composR = mix(smBgR3, smileyR, faceMask);
  float composG = mix(smBgG3, smileyG, faceMask);
  float composB = mix(smBgB3, smileyB, faceMask);

  float outR = composR - outlineMask * 0.5;
  float outG = composG - outlineMask * 0.5;
  float outB = composB - outlineMask * 0.5;

  // Kick invert — more extreme
  float invertAmount = kickHit * 0.9;
  float invR = mix(outR, 1.0 - outR, invertAmount);
  float invG = mix(outG, 1.0 - outG, invertAmount);
  float invB = mix(outB, 1.0 - outB, invertAmount);

  float finalR = invR + onsetFlash * 0.2;
  float finalG = invG + onsetFlash * 0.2;
  float finalB = invB + onsetFlash * 0.2;

  float midsOverR = finalR + midsShift * 0.05;
  float midsOverG = finalG - midsShift * 0.02;
  float midsOverB = finalB + midsShift * 0.03;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(midsOverR, midsOverG, midsOverB)); midsOverR = _pc.r; midsOverG = _pc.g; midsOverB = _pc.b; }
  gl_FragColor = vec4(
    clamp(midsOverR, 0.0, 1.0),
    clamp(midsOverG, 0.0, 1.0),
    clamp(midsOverB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uWarpDepth;
uniform float uFlowRate;
uniform float uColorDensity;
uniform float uInterference;

// HSV to RGB
vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0) * uFlowRate;

  // Audio-reactive modulators — 2x
  float bassWarp = bass() * uSensitivity * 1.6;
  float midsHue = mids() * uSensitivity * 0.6;
  float energyBright = uEnergy * uSensitivity * 1.0;
  float onsetSpike = uOnset * uSensitivity * 3.0;

  // --- Domain warping layer 1 ---
  float warpStrength1 = uWarpDepth * 0.3 + bassWarp * 0.5 + onsetSpike * 0.3;
  float w1x = sin(p.y * 2.5 + time * 0.7 + uChaos * sin(time * 0.2)) * warpStrength1;
  float w1y = cos(p.x * 2.3 + time * 0.6) * warpStrength1;
  float p1x = p.x + w1x;
  float p1y = p.y + w1y;

  // --- Domain warping layer 2 ---
  float warpStrength2 = uWarpDepth * 0.25 + bassWarp * 0.3 + onsetSpike * 0.2;
  float w2x = sin(p1y * 3.7 + time * 0.5 + p1x * 1.3) * warpStrength2;
  float w2y = cos(p1x * 3.1 - time * 0.4 + p1y * 0.9) * warpStrength2;
  float p2x = p1x + w2x;
  float p2y = p1y + w2y;

  // --- Domain warping layer 3 ---
  float warpStrength3 = uWarpDepth * 0.2 + bassWarp * 0.2;
  float w3x = sin(p2y * 5.1 + time * 0.3 + p2x * 2.1) * warpStrength3;
  float w3y = cos(p2x * 4.7 - time * 0.35 + p2y * 1.7) * warpStrength3;
  float p3x = p2x + w3x;
  float p3y = p2y + w3y;

  // --- Domain warping layer 4 (high frequency detail) ---
  float warpStrength4 = uWarpDepth * 0.15 + onsetSpike * 0.4;
  float w4x = sin(p3y * 7.3 + time * 0.2) * warpStrength4;
  float w4y = cos(p3x * 6.9 - time * 0.25) * warpStrength4;
  float finalX = p3x + w4x;
  float finalY = p3y + w4y;

  // --- Interference pattern ---
  float pattern1 = sin(finalX * uColorDensity + finalY * (uColorDensity * 0.8) + time * 0.3) * 0.5 + 0.5;
  float pattern2 = sin(finalX * (uColorDensity * 1.3) - finalY * (uColorDensity * 1.1) + time * 0.4) * 0.5 + 0.5;
  float pattern3 = sin((finalX + finalY) * (uColorDensity * 0.7) + time * 0.5) * 0.5 + 0.5;

  float interfereBlend = mix(pattern1, pattern2, uInterference * 0.6);
  float combined = mix(interfereBlend, pattern3, uInterference * 0.4);

  // --- HSV color from interference — faster cycling ---
  float hue = fract(
    combined * 0.8
      + uPalette * 0.1
      + time * 0.05
      + midsHue
      + sin(uTime * 0.3) * 0.2
  );

  float sat = 0.75 + combined * 0.2 + energyBright * 0.1;

  float val = uIntensity
    + energyBright * 0.3
    + onsetSpike * 0.15;
  val *= combined * 0.7 + 0.3;

  vec3 col = hsvToRgb(hue, clamp(sat, 0.0, 1.0), clamp(val, 0.0, 1.0));

  // Beat pulse — 2x
  float beatPulse = uBeat * uSensitivity * 0.3;
  col += vec3(beatPulse);

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uShardCount;
uniform float uDecayRate;
uniform float uAggressionLevel;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float x) {
  return fract(sin(x * 127.1) * 43758.5453);
}

// Sharp triangle shard SDF
float shard(vec2 p, float angle, float len, float width) {
  float cs = cos(angle), sn = sin(angle);
  p = mat2(cs, -sn, sn, cs) * p;
  p.y -= len * 0.5;
  float d = max(abs(p.x) - width * (1.0 - p.y / len), -p.y);
  d = max(d, p.y - len);
  return d;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  float r = length(p);
  float a = atan(p.y, p.x);

  vec3 col = vec3(0.02); // Near-black background

  // Number of shard rays
  float shards = floor(8.0 + uShardCount * 16.0);

  // Spike extension driven by onset
  float spikeExtend = onsetVal + kickVal * 0.5;
  float decay = uDecayRate * 8.0 + 2.0;

  for (float i = 0.0; i < 24.0; i++) {
    if (i >= shards) break;

    float shardAngle = i * 6.2832 / shards;
    // Jitter angle with spectral flux
    shardAngle += (hash1(i) - 0.5) * fluxVal * 0.5;
    // Slight rotation over time
    shardAngle += sin(time * 0.5 + i) * uChaos * 0.2;

    // Shard length: base + spike extension with fast decay — fills full screen
    float phase = fract(time * 2.0 + hash1(i + 100.0));
    float shardLength = 0.3 + spikeExtend * (1.2 + hash1(i) * 0.8);
    shardLength *= exp(-phase * decay);
    shardLength += 0.12; // Minimum visible

    // Width varies per shard — larger for full-screen presence
    float shardWidth = 0.025 + hash1(i + 50.0) * 0.04;
    shardWidth += bassVal * 0.02;

    // Distance to shard
    float d = shard(p, shardAngle, shardLength, shardWidth);

    // Sharp edge glow — wider for larger spikes
    float glow = exp(-max(d, 0.0) * 40.0);
    float edge = smoothstep(0.01, 0.0, abs(d)) * 0.5;

    // Color: black/white with red aggression
    float brightness = glow + edge;
    vec3 shardColor = vec3(brightness);

    // Red tint based on aggression
    float redAmount = uAggressionLevel * spikeExtend;
    shardColor.r += redAmount * brightness * 0.5;
    shardColor.gb -= redAmount * brightness * 0.2;

    col += shardColor * 0.15;
  }

  // Central impact flash — wider blast radius
  float flash = (onsetVal + kickVal) * exp(-r * 3.0);
  vec3 flashColor = mix(vec3(1.0), vec3(1.0, 0.2, 0.1), uAggressionLevel);
  col += flash * flashColor * 1.5;

  // Radial cracks (thin bright lines) — extend further
  float cracks = pow(abs(sin(a * shards * 0.5 + r * 12.0)), 30.0);
  cracks *= spikeExtend * 0.7;
  col += cracks * vec3(0.9, 0.85, 0.8);

  // High-frequency jitter overlay
  float jitter = hash(p * 50.0 + time * 100.0);
  col += jitter * fluxVal * 0.1;

  // Spectral band glow (bass = red, mids = white, treble = blue)
  col.r += bassVal * 0.08 * uAggressionLevel;
  col += midsVal * 0.04;
  col.b += trebleVal * 0.06;

  // BPM pulse: sharp brightness oscillation
  float bpmSharp = pow(uBpmSin4 * 0.5 + 0.5, 4.0);
  col *= 0.9 + bpmSharp * 0.2;

  // Palette shift
  col = mix(col, col.gbr, uPalette * 0.15);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
