uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uAlphaFreq;
uniform float uRingSpacing;
uniform float uDepthGlow;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3; // Very slow

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float harmonicityVal = uHarmonicity;
  float warmthVal = uWarmth;
  float bpmSinVal = uBpmSin;

  float r = length(p);
  float a = atan(p.y, p.x);

  // Alpha frequency: 8-12Hz band
  float alphaHz = 8.0 + uAlphaFreq * 4.0;
  float alphaOsc = sin(uTime * alphaHz * 6.2832) * 0.5 + 0.5;

  // Ring spacing
  float spacing = 0.1 + uRingSpacing * 0.3;

  // Bass displacement: rings breathe with bass
  float bassDisplace = bassVal * 0.05;

  vec3 col = vec3(0.02, 0.01, 0.04); // Deep dark indigo

  // Multiple concentric rings
  for (float i = 0.0; i < 20.0; i++) {
    float ringR = (i + 1.0) * spacing;

    // Expansion/contraction cycle
    float breathCycle = sin(time * 2.0 + i * 0.3) * 0.02;
    float displacedR = ringR + breathCycle + bassDisplace * sin(i * 0.5);

    // BPM-synced expansion
    displacedR += bpmSinVal * 0.01 * (1.0 + i * 0.1);

    // Ring shape
    float ringDist = abs(r - displacedR);
    float ringThickness = 0.005 + i * 0.001;
    float ring = smoothstep(ringThickness, 0.0, ringDist);

    // Alpha wave opacity modulation per ring (phase offset per ring)
    float alphaPhase = sin(uTime * alphaHz * 6.2832 + i * 0.5);
    float alphaOpacity = alphaPhase * 0.5 + 0.5;
    ring *= alphaOpacity;

    // Color: deep indigo to violet gradient
    float colorT = i / 20.0 + uPalette * 0.2;
    vec3 ringColor = vec3(
      0.15 + 0.1 * sin(colorT * 6.28 + 0.0),
      0.05 + 0.1 * sin(colorT * 6.28 + 2.0),
      0.4 + 0.3 * sin(colorT * 6.28 + 1.0)
    );

    // Harmonicity: more coherent colors
    ringColor = mix(ringColor, vec3(0.3, 0.2, 0.6), harmonicityVal * 0.3);

    col += ring * ringColor * 0.8;
  }

  // Depth glow: inner radial gradient
  float depthGlow = exp(-r * r * 3.0) * uDepthGlow;
  vec3 glowColor = vec3(0.2, 0.1, 0.5) + vec3(0.1, 0.05, 0.2) * alphaOsc;
  col += depthGlow * glowColor;

  // Soft outer haze
  float outerHaze = smoothstep(1.5, 0.5, r) * 0.1;
  col += outerHaze * vec3(0.1, 0.05, 0.25);

  // Treble: subtle shimmer
  float shimmer = noise(p * 40.0 + time * 2.0) * trebleVal * 0.1;
  col += shimmer * vec3(0.5, 0.4, 0.8);

  // Mids: slight warmth in mid-rings
  col += midsVal * 0.03 * vec3(0.3, 0.15, 0.4);

  // Warmth: shifts palette slightly warmer
  col.r += warmthVal * 0.03;

  // Energy: overall pulsing
  col *= 0.85 + energyVal * 0.2;

  // Alpha modulation on overall brightness
  col *= 0.8 + alphaOsc * 0.25;

  // Chaos: slight angle distortion
  float chaosOffset = noise(vec2(a * 3.0, r * 5.0) + time) * uChaos * 0.05;
  col *= 1.0 + chaosOffset;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
