uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBlobCount;
uniform float uViscosity;
uniform float uTransparency;
uniform float uNucleusSize;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.05;
  float breathe = 1.0 + sin(uTime * 0.5) * 0.1;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float flatness = uSpectralFlatness * uSensitivity;

  // Background: dark microscope view
  vec3 col = vec3(0.01, 0.01, 0.02);

  // Metaball field
  float field = 0.0;
  vec3 blobColorAccum = vec3(0.0);
  float numBlobs = 4.0 + uBlobCount * 6.0;

  // Store blob centers for nucleus rendering
  vec2 blobCenters[10];
  float blobRadii[10];

  for (float i = 0.0; i < 10.0; i++) {
    if (i >= numBlobs) break;
    float id = i;
    float speed = (1.0 - uViscosity) * 0.8 + 0.2;

    // Organic movement — pseudopod-like, full-screen range
    vec2 center = vec2(
      sin(time * speed * 0.4 + id * 2.399) * 0.9 + sin(time * speed * 0.17 + id * 5.0) * 0.4 + sin(time * 0.2 + id * 3.0) * 0.15,
      cos(time * speed * 0.35 + id * 1.7) * 0.8 + cos(time * speed * 0.23 + id * 3.0) * 0.3 + cos(time * 0.18 + id * 4.1) * 0.12
    );

    // Bass expansion — larger blobs
    float radius = 0.35 + bassVal * 0.25;
    // Treble splitting — push apart
    center *= 1.0 + trebleVal * 0.45;

    blobCenters[int(i)] = center;
    blobRadii[int(i)] = radius;

    // Metaball contribution
    float d = length(p - center);
    float contribution = radius * radius / (d * d + 0.001);
    field += contribution;

    // Color per blob
    float hue = id * 0.15 + uPalette * 0.1;
    vec3 blobCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.5, 0.7)));
    blobColorAccum += blobCol * contribution;
  }

  // Normalize color
  blobColorAccum /= max(field, 0.001);

  // Metaball threshold
  float threshold = 1.5;
  float blobMask = smoothstep(threshold - 0.2, threshold + 0.2, field);

  // Edge membrane
  float edge = exp(-abs(field - threshold) * 5.0);

  // Interior with transparency
  vec3 blobCol = blobColorAccum;
  float alpha = mix(0.3, 0.8, 1.0 - uTransparency);
  col = mix(col, blobCol * 0.5, blobMask * alpha);

  // Membrane glow (cyan/magenta)
  vec3 membraneCol = mix(vec3(0.1, 0.9, 1.0), vec3(1.0, 0.35, 0.9), sin(time * 0.7) * 0.5 + 0.5);
  col += membraneCol * edge * 0.75;

  // Nuclei inside blobs
  for (float i = 0.0; i < 10.0; i++) {
    if (i >= numBlobs) break;
    vec2 center = blobCenters[int(i)];
    float d = length(p - center);
    float nucR = uNucleusSize * 0.08;

    // Nuclear membrane
    float nucMembrane = exp(-abs(d - nucR) * 60.0);
    col += vec3(0.3, 0.1, 0.5) * nucMembrane * blobMask * 0.5;

    // Nucleolus
    float nucleolus = exp(-d * 40.0) * blobMask;
    col += vec3(0.5, 0.15, 0.6) * nucleolus * 0.4;
  }

  // Internal organelle particles — spread across full screen
  for (float i = 0.0; i < 30.0; i++) {
    vec2 orgPos = vec2(
      sin(time * 0.5 + i * 3.7) * 1.1,
      cos(time * 0.4 + i * 2.3) * 0.9
    );
    orgPos += vec2(noise(vec2(i, time * 0.3)), noise(vec2(time * 0.3, i))) * 0.5 * uChaos;
    float od = length(p - orgPos);
    float organelle = exp(-od * 50.0) * blobMask * 0.3;
    vec3 orgCol = mix(vec3(0.0, 0.5, 0.3), vec3(0.8, 0.3, 0.0), hash(vec2(i)));
    col += orgCol * organelle * (0.5 + midsVal * 0.8);
  }

  // Pseudopod extensions on kick
  float pseudoField = 0.0;
  for (float i = 0.0; i < 10.0; i++) {
    if (i >= numBlobs) break;
    vec2 ext = blobCenters[int(i)] + vec2(cos(i * 5.0 + time), sin(i * 7.0 + time)) * 0.6 * kickVal;
    float d = length(p - ext);
    pseudoField += 0.03 / (d * d + 0.01);
  }
  float pseudoMask = smoothstep(0.8, 1.2, pseudoField);
  col += blobColorAccum * pseudoMask * 0.3 * kickVal;

  // Spectral flux shimmer
  col += col * fluxVal * 0.3;

  // Flatness → iridescence
  col += vec3(0.05, 0.02, 0.08) * flatness * blobMask;

  // Kick flash
  col = mix(col, col * 1.5 + vec3(0.02, 0.05, 0.08), kickVal * 0.3);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

