// Circle inversion: reflect point through a circle
vec2 circleInvert(vec2 p, vec2 center, float radius) {
  vec2 d = p - center;
  float r2 = dot(d, d);
  return center + d * (radius * radius) / r2;
}

// Distance to nearest circle in the gasket
float apollonianDE(vec2 p, float time, float bassVal, float chaos) {
  float scale = 1.0;
  float minDist = 1e10;
  float orbitTrap = 0.0;

