    vec2 invCenter = vec2(1.0, 0.0);
    p = circleInvert(p, invCenter, invRadius);
    p -= invCenter;

    scale *= invRadius * invRadius / dot(p + invCenter - invCenter, p + invCenter - invCenter + vec2(0.001));

