  greenCol += vec3(0.6, 1.0, 0.7) * headFlash * glyph;

  // Cyan mode
  vec3 cyanCol = vec3(0.1, 0.8, 1.0) * bright;
  cyanCol += vec3(0.5, 0.9, 1.0) * headFlash * glyph;

