}

// Aurora color based on height
vec3 auroraColor(float height, float paletteShift) {
  float h = clamp(height + paletteShift * 0.08, 0.0, 1.0);

  vec3 deepGreen = vec3(0.08, 0.8, 0.2);
  vec3 brightGreen = vec3(0.3, 1.0, 0.4);
  vec3 cyan = vec3(0.15, 0.85, 0.95);
  vec3 purple = vec3(0.6, 0.2, 0.9);
  vec3 pink = vec3(0.95, 0.25, 0.6);
  vec3 red = vec3(0.85, 0.15, 0.2);

  float s1 = smoothstep(0.0, 0.15, h);
  float s2 = smoothstep(0.15, 0.35, h);
  float s3 = smoothstep(0.35, 0.55, h);
  float s4 = smoothstep(0.55, 0.75, h);
  float s5 = smoothstep(0.75, 1.0, h);

  vec3 c1 = mix(deepGreen, brightGreen, s1);
  vec3 c2 = mix(c1, cyan, s2);
  vec3 c3 = mix(c2, purple, s3);
  vec3 c4 = mix(c3, pink, s4);
  return mix(c4, red, s5);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);
  // Wave speed modulated by energy
  float energySpeedMod = 1.0 + uEnergy * uSensitivity * 1.4;
  float waveTime = time * uWaveSpeed * energySpeedMod;

  // Audio influences -- using raw spectrum for direct control
  float bassRaw = uSpectrum0 * uSensitivity;
  float subBass = uSpectrum1 * uSensitivity;
  float bassVal = (bassRaw * 0.5 + subBass * 0.5);
  float midsRaw3 = uSpectrum3 * uSensitivity;
  float midsRaw4 = uSpectrum4 * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // === BASS-REACTIVE CURTAIN HEIGHT/INTENSITY ===
  // Bass directly controls curtain vertical extent and brightness
  float bassHeight = bassRaw * 0.3 + subBass * 0.24;
  float bassBright = 1.0 + bassVal * 1.2;

  // === MIDS-DRIVEN COLOR SHIFT ===
  // Mids spectrum bands shift the aurora color palette
  float midsColorShift = (midsRaw3 * 0.5 + midsRaw4 * 0.5) * 0.6;

  // Sky gradient: dark at top, slightly lighter at horizon — fills full screen
  float skyGrad = smoothstep(-1.0, 1.0, p.y);
  float skyR = mix(0.0, 0.025, skyGrad);
  float skyG = mix(0.01, 0.05, skyGrad);
  float skyB = mix(0.04, 0.10, skyGrad);

  // Accumulate curtain light (additive)
  float accR = skyR;
  float accG = skyG;
  float accB = skyB;

  // --- Curtain 0: lowest, brightest green ---
  // Height responds directly to bass
  float curtainH0 = uCurtainHeight * 1.5 + bassHeight;
  float baseY0 = -0.3 + midsVal * 0.1;
  float noiseDisp0 = (valueNoise(vec2(p.x * 2.0 + waveTime * 0.7, waveTime * 0.3)) - 0.5) * 0.3 * (uChaos + 0.5);
  float waveDisp0 = sin(p.x * 4.0 + waveTime * 1.2) * 0.08;
  float curtainY0 = baseY0 + noiseDisp0 + waveDisp0;
  float dist0 = abs(p.y - curtainY0);
  float band0 = smoothstep(curtainH0, 0.0, dist0);
  float intensity0 = band0 * (0.8 + bassVal * 0.5) * bassBright;
  float heightNorm0 = clamp(p.y + 0.5 + midsColorShift, 0.0, 1.0);
  vec3 col0 = auroraColor(heightNorm0, uPalette + midsColorShift);
  accR += col0.x * intensity0;
  accG += col0.y * intensity0;
  accB += col0.z * intensity0;

  // --- Curtain 1: mid-low, green-cyan ---
  float curtainH1 = uCurtainHeight * 1.3 + bassHeight * 0.8;
  float baseY1 = -0.15 + midsVal * 0.08;
  float noiseDisp1 = (valueNoise(vec2(p.x * 2.5 + waveTime * 0.5 + 17.3, waveTime * 0.25)) - 0.5) * 0.35 * (uChaos + 0.5);
  float waveDisp1 = sin(p.x * 3.0 + waveTime * 0.9 + 1.5) * 0.1;
  float curtainY1 = baseY1 + noiseDisp1 + waveDisp1;
  float dist1 = abs(p.y - curtainY1);
  float band1 = smoothstep(curtainH1, 0.0, dist1);
  float intensity1 = band1 * (0.65 + bassVal * 0.4) * bassBright;
  float heightNorm1 = clamp(p.y + 0.5 + 0.15 + midsColorShift * 0.8, 0.0, 1.0);
  vec3 col1 = auroraColor(heightNorm1, uPalette + midsColorShift * 0.7);
  accR += col1.x * intensity1;
  accG += col1.y * intensity1;
  accB += col1.z * intensity1;

  // --- Curtain 2: mid-high, cyan-purple ---
  float curtainH2 = uCurtainHeight * 1.1 + bassHeight * 0.6;
  float baseY2 = 0.0 + midsVal * 0.06;
  float noiseDisp2 = (valueNoise(vec2(p.x * 1.8 + waveTime * 0.6 + 53.1, waveTime * 0.35)) - 0.5) * 0.28 * (uChaos + 0.5);
  float waveDisp2 = sin(p.x * 5.0 + waveTime * 1.5 + 3.7) * 0.06;
  float curtainY2 = baseY2 + noiseDisp2 + waveDisp2;
  float dist2 = abs(p.y - curtainY2);
  float band2 = smoothstep(curtainH2, 0.0, dist2);
  float intensity2 = band2 * (0.5 + bassVal * 0.3) * bassBright;
  // Color responds to mid spectrum
  float heightNorm2 = clamp(p.y + 0.5 + 0.3 + midsRaw3 * 0.2, 0.0, 1.0);
  vec3 col2 = auroraColor(heightNorm2, uPalette + midsRaw4 * 0.5);
  accR += col2.x * intensity2;
  accG += col2.y * intensity2;
  accB += col2.z * intensity2;

  // --- Curtain 3: high, purple-pink ---
  float curtainH3 = uCurtainHeight * 1.0 + bassHeight * 0.4;
  float baseY3 = 0.15 + midsVal * 0.04;
  float noiseDisp3 = (valueNoise(vec2(p.x * 3.0 + waveTime * 0.4 + 97.2, waveTime * 0.2)) - 0.5) * 0.22 * (uChaos + 0.5);
  float waveDisp3 = sin(p.x * 2.5 + waveTime * 0.7 + 5.1) * 0.07;
  float curtainY3 = baseY3 + noiseDisp3 + waveDisp3;
  float dist3 = abs(p.y - curtainY3);
  float band3 = smoothstep(curtainH3, 0.0, dist3);
  float intensity3 = band3 * (0.4 + bassVal * 0.25) * bassBright;
  float heightNorm3 = clamp(p.y + 0.5 + 0.45 + midsRaw3 * 0.15, 0.0, 1.0);
  vec3 col3 = auroraColor(heightNorm3, uPalette + midsRaw4 * 0.3);
  accR += col3.x * intensity3;
  accG += col3.y * intensity3;
  accB += col3.z * intensity3;

  // --- Curtain 4: highest, faint pink-red ---
  float curtainWeight = smoothstep(3.5, 4.5, uCurtainCount);
  float curtainH4 = uCurtainHeight * 0.9 + bassHeight * 0.3;
  float baseY4 = 0.3;
  float noiseDisp4 = (valueNoise(vec2(p.x * 2.2 + waveTime * 0.3 + 137.5, waveTime * 0.15)) - 0.5) * 0.18 * (uChaos + 0.5);
  float waveDisp4 = sin(p.x * 3.5 + waveTime * 0.5 + 7.8) * 0.05;
  float curtainY4 = baseY4 + noiseDisp4 + waveDisp4;
  float dist4 = abs(p.y - curtainY4);
  float band4 = smoothstep(curtainH4, 0.0, dist4);
  float intensity4 = band4 * 0.3 * curtainWeight * bassBright;
  float heightNorm4 = clamp(p.y + 0.5 + 0.6, 0.0, 1.0);
  vec3 col4 = auroraColor(heightNorm4, uPalette);
  accR += col4.x * intensity4;
  accG += col4.y * intensity4;
  accB += col4.z * intensity4;

  // --- Treble shimmer: fine vertical rays ---
  float shimmerNoise = valueNoise(vec2(p.x * 30.0, time * 3.0));
  float shimmerMask = accG + accR + accB; // only shimmer where aurora exists
  float shimmer = shimmerNoise * trebleVal * 0.3 * clamp(shimmerMask, 0.0, 1.0);
  accR += shimmer * 0.7;
  accG += shimmer;
  accB += shimmer * 0.5;

  // === ONSET-TRIGGERED SPARKLE/SHIMMER ===
  // Hash-based sparkle points that flash on onset
  float sparkleLayer = 0.0;
  vec2 sparkP = vUv * 80.0;
  float sparkHash = hash21(floor(sparkP));
  vec2 sparkFrac = fract(sparkP) - 0.5;
  float sparkDist = length(sparkFrac);
  // Sparkle only where aurora is visible
  float auroraPresence = clamp(shimmerMask * 3.0, 0.0, 1.0);
  float sparkThresh = 0.92 - onsetFlash * 0.2;
  float sparkVal = smoothstep(0.035, 0.0, sparkDist) * step(sparkThresh, sparkHash) * auroraPresence;
  // Rapid flash animation
  float sparkFlash = sin(uTime * 15.0 + sparkHash * 80.0) * 0.5 + 0.5;
  sparkleLayer = sparkVal * sparkFlash * (0.5 + onsetFlash * 3.0);
  // Second sparkle layer at different scale for depth
  vec2 sparkP2 = vUv * 150.0;
  float sparkHash2 = hash21(floor(sparkP2));
  vec2 sparkFrac2 = fract(sparkP2) - 0.5;
  float sparkDist2 = length(sparkFrac2);
  float sparkVal2 = smoothstep(0.02, 0.0, sparkDist2) * step(0.95 - onsetFlash * 0.15, sparkHash2) * auroraPresence;
  float sparkFlash2 = sin(uTime * 20.0 + sparkHash2 * 60.0) * 0.5 + 0.5;
  sparkleLayer += sparkVal2 * sparkFlash2 * (0.3 + onsetFlash * 2.0);
  // Sparkle color: white-green-cyan
  accR += sparkleLayer * 0.7;
  accG += sparkleLayer * 1.0;
  accB += sparkleLayer * 0.85;

  // --- Stars in dark sky areas ---
  vec2 starP = vUv * 120.0;
  float starHash = hash21(floor(starP));
  vec2 starFrac = fract(starP) - 0.5;
  float starDist = starFrac.x * starFrac.x + starFrac.y * starFrac.y;
  float starBright = smoothstep(0.003, 0.0, starDist) * smoothstep(0.5, 0.9, starHash);
  // Twinkle
  float twinkle = sin(time * 3.0 + starHash * 100.0) * 0.5 + 0.5;
  float starVal = starBright * twinkle * (1.0 - clamp(shimmerMask * 2.0, 0.0, 1.0));
  accR += starVal * 0.8;
  accG += starVal * 0.85;
  accB += starVal;

  // === BEAT/KICK BRIGHTNESS PULSE ===
  // Strong kick pulse across the whole aurora
  float kickBright = kickPulse * 0.5 * clamp(shimmerMask * 2.0, 0.0, 1.0);
  accR += kickBright * 0.4;
  accG += kickBright * 0.8;
  accB += kickBright * 0.5;

  // Beat pulse brightness
  float beatFlash = beatPulse * 0.15;
  accR += beatFlash * 0.5;
  accG += beatFlash;
  accB += beatFlash * 0.7;

  // --- Onset flash: bright burst across aurora ---
  float flashVal = onsetFlash * 0.3;
  accR += flashVal * 0.4;
  accG += flashVal * 1.2;
  accB += flashVal * 0.7;

  // === ENERGY-DRIVEN OVERALL VIBRANCY ===
  float energyVibrancy = 1.0 + energyVal * 0.6;

  // Final intensity
  float brightness = uIntensity * 1.3 + energyVal * 0.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(accR, accG, accB)); accR = _pc.r; accG = _pc.g; accB = _pc.b; }
  gl_FragColor = vec4(
    clamp(accR * brightness * energyVibrancy, 0.0, 1.0),
    clamp(accG * brightness * energyVibrancy, 0.0, 1.0),
    clamp(accB * brightness * energyVibrancy, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCurtainLayers;
uniform float uFoldDepth;
uniform float uShimmerRate;
uniform float uDrapeSway;

vec3 auroraPalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.15, 0.35)));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.2;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numLayers = min(uCurtainLayers, 8.0);
  vec3 color = vec3(0.0);

  // Each curtain layer hangs from the top and drapes downward
  for (float i = 0.0; i < 8.0; i += 1.0) {
    if (i >= numLayers) break;

    float layerFrac = i / numLayers;
    float depth = 1.0 - layerFrac * 0.5; // front layers are brighter

    // Curtain fold pattern: sinusoidal folds along x
    float foldFreq = 3.0 + i * 1.5;
    float sway = sin(time * 0.75 + i * 1.1) * uDrapeSway * 0.4;
    sway += bassVal * sin(i * 0.8 + time * 0.45) * 0.3;

    // The curtain surface: x displacement as function of position
    float foldX = sin(p.x * foldFreq + sway + time * 0.3 * (1.0 + i * 0.2));
    foldX += sin(p.x * foldFreq * 2.3 + time * 0.5) * 0.3 * uFoldDepth;

    // Vertical shimmer along the drape
    float shimmer = sin(p.y * 8.0 + time * uShimmerRate * 3.0 + i * 2.0);
    shimmer += sin(p.y * 15.0 - time * uShimmerRate * 2.0 + midsVal * 2.0) * 0.5;

    // The curtain's "surface normal" approximation for lighting
    float foldGrad = cos(p.x * foldFreq + sway + time * 0.3 * (1.0 + i * 0.2)) * foldFreq;
    float lighting = 0.5 + 0.5 * foldGrad / (foldFreq + 1.0);

    // Curtain is brightest at folds (edges catch light)
    float foldEdge = abs(foldX);
    float edgeGlow = exp(-foldEdge * 3.0 / uFoldDepth);

    // Vertical variation: gentle modulation across full height, no hard cutoff
    float verticalFade = 0.7 + 0.3 * sin(p.y * 2.0 + time * 0.2 + i * 1.5);

    // Ripple waves along curtain bottom edge — extends to screen bottom
    float bottomEdge = -0.9 - i * 0.05;
    float ripple = sin(p.x * 10.0 + time * 2.0 + i * 3.0) * 0.05;
    float bottomGlow = exp(-abs(p.y - bottomEdge - ripple) * 15.0);

    // Combined curtain brightness
    float curtainBright = (edgeGlow * 0.6 + lighting * 0.4) * verticalFade * depth;
    curtainBright += bottomGlow * 0.3;
    curtainBright *= 1.0 + shimmer * 0.2;

    // Audio-reactive shimmer boost on onsets
    curtainBright += onsetVal * edgeGlow * 0.6 * exp(-i * 0.5);

    // Color per layer
    float hue = layerFrac * 0.4 + uPalette * 0.1 + time * 0.015 + p.y * 0.1;
    vec3 curtainColor = auroraPalette(hue, uPalette * 0.05 + i * 0.05);

    // Chaos: color shift between layers
    curtainColor = mix(curtainColor, curtainColor.gbr, uChaos * sin(i * 2.1 + time * 0.2) * 0.3);

    color += curtainColor * curtainBright * 0.7;
  }

  // Subtle background glow (dark sky with faint aurora wash)
  float bgWash = smoothstep(-0.5, 0.5, p.y) * 0.05;
  vec3 bgColor = auroraPalette(time * 0.01 + p.x * 0.1, uPalette * 0.1 + 0.5);
  color += bgColor * bgWash;

  // Treble sparkle (stars behind the curtain)
  float sparkle = sin(p.x * 60.0 + time * 4.0) * sin(p.y * 60.0 - time * 3.5);
  sparkle = pow(max(sparkle, 0.0), 25.0);
  color += vec3(sparkle * trebleVal * 0.4);

  // Intensity and energy
  color *= uIntensity * 1.5 + uEnergy * uSensitivity * 0.6;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.04);

  // Kick punch
  color = mix(color, color * 1.8, kickVal * 0.4);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.1));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCurtainCount;
uniform float uWaveAmplitude;
uniform float uShimmerRate;
uniform float uColorRange;

// Helper: compute one aurora curtain contribution
float curtain(vec2 pos, float xCenter, float freq1, float freq2, float speed1, float speed2, float phase, float width, float waveAmp, float time) {
  float wave = sin(pos.y * freq1 + time * speed1 + phase) * waveAmp
    + sin(pos.y * freq2 + time * speed2 + phase * 1.3) * (waveAmp * 0.45);
  float curtainPos = pos.x - wave - xCenter;
  float curtainVal = smoothstep(width, 0.0, abs(curtainPos));
  // Vertical fade: stronger at top, softer at bottom
  float vertFade = smoothstep(-0.8, 0.0, pos.y) * 0.4 + 0.6;
  return curtainVal * vertFade;
}

// HUE to RGB helper
vec3 hue2rgb(float hue) {
  return vec3(
    abs(fract(hue + 1.0) * 6.0 - 3.0) - 1.0,
    abs(fract(hue + 0.6667) * 6.0 - 3.0) - 1.0,
    abs(fract(hue + 0.3333) * 6.0 - 3.0) - 1.0
  );
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.5 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.0);

  // Audio-reactive modulators
  float bassWave = bass() * uSensitivity * 1.0;
  float midsColor = mids() * uSensitivity * 0.6;
  float onsetBright = uOnset * uSensitivity * 3.0;
  float energyMod = uEnergy * uSensitivity;

  // Wave amplitude with audio
  float waveAmp = uWaveAmplitude * 0.2 + bassWave * 0.12;

  // Hue base
  float hueBase = uPalette * 0.12 + midsColor;

  // === 10 CURTAINS spread across full viewport ===
  // Positions spread from -0.9 to +0.9 to cover edges and corners
  // Each curtain has wide smoothstep radius (0.25-0.35) to fill gaps

  float c1 = curtain(p, -0.85, 3.0, 5.0, 0.40, 0.70, 0.0, 0.30, waveAmp, time);
  float c2 = curtain(p, -0.60, 2.5, 4.0, 0.35, 0.50, 1.0, 0.28, waveAmp, time);
  float c3 = curtain(p, -0.38, 3.5, 6.0, 0.30, 0.60, 2.5, 0.26, waveAmp, time);
  float c4 = curtain(p, -0.15, 2.0, 4.5, 0.45, 0.55, uChaos, 0.28, waveAmp, time);
  float c5 = curtain(p,  0.05, 2.8, 5.2, 0.38, 0.48, 3.7, 0.30, waveAmp, time);
  float c6 = curtain(p,  0.25, 3.2, 4.8, 0.32, 0.62, 1.8, 0.26, waveAmp, time);
  float c7 = curtain(p,  0.45, 2.3, 5.5, 0.42, 0.52, 4.2, 0.28, waveAmp, time);
  float c8 = curtain(p,  0.65, 3.8, 4.2, 0.28, 0.58, 5.5, 0.30, waveAmp, time);
  float c9 = curtain(p,  0.85, 2.6, 5.8, 0.36, 0.46, 0.7, 0.28, waveAmp, time);
  float c10 = curtain(p, -1.0, 3.3, 4.6, 0.33, 0.53, 2.0, 0.32, waveAmp, time);

  // === SHIMMER ===
  float shimmer = sin(
    p.x * 60.0 + p.y * 40.0 + time * (uShimmerRate * 5.0)
  ) * 0.5 + 0.5;
  float shimmer2 = cos(
    p.x * 45.0 - p.y * 55.0 + time * (uShimmerRate * 3.0)
  ) * 0.5 + 0.5;
  float shimmerEffect = shimmer * shimmer2 * 0.15 * (uChaos + 0.2);

  // === CURTAIN COLORS (10 hues spread across the spectrum) ===
  float h1 = 0.33 + hueBase * 0.1 + sin(time * 0.05) * (uColorRange * 0.05);
  float h2 = 0.50 + hueBase * 0.1 + cos(time * 0.04) * (uColorRange * 0.05);
  float h3 = 0.75 + hueBase * 0.1;
  float h4 = 0.90 + hueBase * 0.1;
  float h5 = 0.15 + hueBase * 0.1 + sin(time * 0.06) * (uColorRange * 0.04);
  float h6 = 0.42 + hueBase * 0.1 + cos(time * 0.03) * (uColorRange * 0.06);
  float h7 = 0.58 + hueBase * 0.1;
  float h8 = 0.67 + hueBase * 0.1 + sin(time * 0.07) * (uColorRange * 0.03);
  float h9 = 0.83 + hueBase * 0.1;
  float h10 = 0.25 + hueBase * 0.1;

  vec3 col1 = clamp(hue2rgb(h1), 0.0, 1.0);
  vec3 col2 = clamp(hue2rgb(h2), 0.0, 1.0);
  vec3 col3 = clamp(hue2rgb(h3), 0.0, 1.0);
  vec3 col4 = clamp(hue2rgb(h4), 0.0, 1.0);
  vec3 col5 = clamp(hue2rgb(h5), 0.0, 1.0);
  vec3 col6 = clamp(hue2rgb(h6), 0.0, 1.0);
  vec3 col7 = clamp(hue2rgb(h7), 0.0, 1.0);
  vec3 col8 = clamp(hue2rgb(h8), 0.0, 1.0);
  vec3 col9 = clamp(hue2rgb(h9), 0.0, 1.0);
  vec3 col10 = clamp(hue2rgb(h10), 0.0, 1.0);

  // === COMBINE (additive) ===
  float brightness = uIntensity * 1.4 + energyMod * 0.6;

  vec3 total = (col1 * c1 + col2 * c2 + col3 * c3 + col4 * c4
    + col5 * c5 + col6 * c6 + col7 * c7 + col8 * c8
    + col9 * c9 + col10 * c10)
    * brightness + vec3(shimmerEffect);

  // Onset flash
  float totalCurtain = c1 + c2 + c3 + c4 + c5 + c6 + c7 + c8 + c9 + c10;
  float flash = onsetBright * totalCurtain * 0.3;

  // Beat pulse
  float beatPulse = uBeat * uSensitivity * 0.08 * totalCurtain;

  // === PSYCHEDELIC ENHANCEMENT ===
  total = psychedelicColor(total);
  gl_FragColor = vec4(
    clamp(total.r + flash + beatPulse, 0.0, 1.0),
    clamp(total.g + flash + beatPulse, 0.0, 1.0),
    clamp(total.b + flash + beatPulse, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBoltFrequency;
uniform float uZigzagAmplitude;
uniform float uFlashPower;

float hash(float x) {
  return fract(sin(x * 127.1) * 43758.5453);
}

float hash2(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash2(i), hash2(i + vec2(1,0)), f.x),
             mix(hash2(i + vec2(0,1)), hash2(i + vec2(1,1)), f.x), f.y);
}

// Lightning bolt along a direction
float bolt(vec2 p, vec2 dir, float seed, float time, float zigzag) {
  // Project p onto bolt direction
  float along = dot(p, dir);
  float perp = dot(p, vec2(-dir.y, dir.x));

  // Zigzag displacement along the bolt
  float segments = 15.0;
  float segPos = along * segments;
  float segIdx = floor(segPos);
  float segFrac = fract(segPos);

  // Random offset per segment
  float offset1 = (hash(segIdx + seed * 100.0) - 0.5) * zigzag;
  float offset2 = (hash(segIdx + 1.0 + seed * 100.0) - 0.5) * zigzag;
  float zigzagOffset = mix(offset1, offset2, smoothstep(0.0, 1.0, segFrac));

  // Distance to zigzag line
  float dist = abs(perp - zigzagOffset);

  // Bolt core + glow
  float core = exp(-dist * dist * 2000.0);
  float glow = exp(-dist * dist * 200.0);

  // Fade at ends
  float endFade = smoothstep(-0.6, -0.3, along) * smoothstep(0.6, 0.3, along);

  return (core + glow * 0.3) * endFade;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.02, 0.01, 0.03); // Dark storm sky

  // Beta frequency: 15-20Hz rapid patterns
  float betaHz = 15.0 + energyVal * 5.0;
  float betaOsc = sin(uTime * betaHz * 6.2832) * 0.5 + 0.5;

  // Number of active bolts
  float numBolts = floor(3.0 + uBoltFrequency * 8.0 + energyVal * 3.0);
  float zigzag = uZigzagAmplitude * 0.3 + fluxVal * 0.15;

  for (float i = 0.0; i < 14.0; i++) {
    if (i >= numBolts) break;

    // Each bolt has random direction and timing
    float boltSeed = i + floor(time * (2.0 + i * 0.3));
    float boltAngle = hash(boltSeed) * 6.2832;
    vec2 boltDir = vec2(cos(boltAngle), sin(boltAngle));

    // Bolt origin offset
    vec2 origin = vec2(
      (hash(boltSeed + 50.0) - 0.5) * 1.5,
      (hash(boltSeed + 100.0) - 0.5) * 1.5
    );

    // Bolt lifetime (rapid flashes)
    float boltLife = fract(time * (1.0 + i * 0.2) + hash(i) * 10.0);
    float boltAlpha = exp(-boltLife * 8.0); // Fast decay

    float b = bolt(p - origin, boltDir, boltSeed, time, zigzag) * boltAlpha;

    // Color: white/yellow/magenta
    vec3 boltColor;
    float colorSel = hash(boltSeed + 200.0);
    if (colorSel < 0.33) {
      boltColor = vec3(1.0, 1.0, 0.95); // White
    } else if (colorSel < 0.66) {
      boltColor = vec3(1.0, 0.9, 0.3); // Yellow
    } else {
      boltColor = vec3(1.0, 0.3, 0.8); // Magenta
    }

    // Palette shift
    boltColor = mix(boltColor, boltColor.gbr, uPalette * 0.15);

    col += b * boltColor * 0.4;
  }

  // Branching sub-bolts (smaller, more complex with flux)
  for (float i = 0.0; i < 6.0; i++) {
    float subSeed = i + 100.0 + floor(time * 5.0);
    float subAngle = hash(subSeed) * 6.2832;
    vec2 subDir = vec2(cos(subAngle), sin(subAngle));
    vec2 subOrigin = vec2(hash(subSeed + 30.0) - 0.5, hash(subSeed + 60.0) - 0.5) * 2.0;
    float subLife = fract(time * 3.0 + hash(subSeed) * 10.0);
    float subAlpha = exp(-subLife * 12.0);
    float sub = bolt(p - subOrigin, subDir, subSeed, time, zigzag * 0.5) * subAlpha * 0.3;
    col += sub * vec3(0.7, 0.6, 0.9);
  }

  // Beta oscillation overlay: rapid brightness modulation
  col *= 0.7 + betaOsc * 0.4;

  // Kick flash: full-screen bright blast
  float flash = kickVal * uFlashPower;
  col += flash * vec3(1.0, 0.95, 0.9) * 0.6;

  // Storm background: dark swirling clouds
  float cloud = noise(p * 3.0 + time * 0.3);
  col += cloud * 0.04 * vec3(0.2, 0.15, 0.3);

  // Bass: distant rumble glow
  col += bassVal * 0.06 * vec3(0.4, 0.3, 0.5);

  // Treble: sharp edge enhancement
  col += trebleVal * 0.03 * vec3(0.8, 0.7, 1.0);

  // Mids: ambient storm haze
  col += midsVal * 0.03 * vec3(0.5, 0.4, 0.6);

  // Chaos: cloud turbulence
  col *= 1.0 + uChaos * 0.2 * (noise(p * 8.0 + time * 2.0) - 0.5);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uExpansionRate;
uniform float uCoolingSpeed;
uniform float uStructureScale;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 6; i++) {
    val += amp * noise(p);
    p *= 2.1;
    amp *= 0.5;
  }
  return val;
}

vec3 temperatureColor(float t) {
  // Black body radiation: hot white -> blue -> yellow -> orange -> red -> dark
  if (t > 0.9) return mix(vec3(0.8, 0.85, 1.0), vec3(1.0, 1.0, 1.0), (t - 0.9) * 10.0);
  if (t > 0.7) return mix(vec3(0.4, 0.6, 1.0), vec3(0.8, 0.85, 1.0), (t - 0.7) * 5.0);
  if (t > 0.5) return mix(vec3(1.0, 0.8, 0.3), vec3(0.4, 0.6, 1.0), (t - 0.5) * 5.0);
  if (t > 0.3) return mix(vec3(1.0, 0.4, 0.1), vec3(1.0, 0.8, 0.3), (t - 0.3) * 5.0);
  if (t > 0.1) return mix(vec3(0.3, 0.05, 0.02), vec3(1.0, 0.4, 0.1), (t - 0.1) * 5.0);
  return mix(vec3(0.02, 0.01, 0.03), vec3(0.3, 0.05, 0.02), t * 10.0);
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetPulse = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Cyclic expansion phase (loops through big bang phases)
  float expansionPhase = fract(time * uExpansionRate * 0.2);
  float expansion = expansionPhase * (1.0 + bassVal * 1.0);

  // Expansion wave front
  float waveFront = expansion * 2.0;
  float behindFront = smoothstep(waveFront + 0.1, waveFront - 0.2, r);

  // Temperature: hot near center and at wave front, cooling behind
  float distFromFront = abs(r - waveFront);
  float frontHeat = exp(-distFromFront * distFromFront * 8.0);
  float centerHeat = exp(-r * r * 2.0) * (1.0 - expansion * 0.8);
  float temperature = clamp(frontHeat + centerHeat, 0.0, 1.0);

  // Cooling creates structure
  float cooled = (1.0 - temperature) * behindFront;
  float cooling = uCoolingSpeed * (1.0 + midsVal * 0.3);

  // === EXPANSION WAVE: bright plasma ===
  vec3 plasmaCol = temperatureColor(temperature);
  float plasmaIntensity = temperature * (1.8 + bassVal * 1.0);

  // === LARGE-SCALE STRUCTURE: cosmic web filaments ===
  float structNoise = fbm(p * uStructureScale * 5.0 + time * 0.05);
  float structNoise2 = fbm(p * uStructureScale * 8.0 - time * 0.03 + 50.0);

  // Filament detection: find ridges in noise
  float filament = smoothstep(0.45, 0.55, structNoise) * smoothstep(0.55, 0.45, structNoise);
  filament += smoothstep(0.48, 0.52, structNoise2) * smoothstep(0.52, 0.48, structNoise2);
  filament *= cooled * cooling;

  // Galaxy cluster nodes at noise peaks
  float nodes = smoothstep(0.65, 0.75, structNoise) * cooled * cooling;

  vec3 filamentCol = vec3(0.3, 0.45, 1.0) * filament * 3.0;
  vec3 nodeCol = vec3(1.0, 0.95, 0.7) * nodes * 4.5;

  // === CMB: cosmic microwave background in cooled regions ===
  float cmbNoise = fbm(p * 3.0 + 100.0);
  float cmb = cmbNoise * cooled * (1.0 - temperature) * 0.3;
  // CMB color: warm orange-ish glow
  vec3 cmbCol = mix(vec3(0.1, 0.05, 0.15), vec3(0.3, 0.15, 0.05), cmbNoise) * cmb;
  // Kick pulses create CMB fluctuation highlights
  cmbCol += vec3(0.3, 0.15, 0.08) * kickPulse * cmb * 6.0;

  // === PARTICLE SPARKLE (treble) ===
  float sparkle = 0.0;
  vec2 sparkGrid = floor(p * 80.0);
  float sparkH = hash(sparkGrid);
  if (sparkH > 0.97) {
    vec2 sparkFrac = fract(p * 80.0) - 0.5;
    float sparkDist = dot(sparkFrac, sparkFrac);
    sparkle = exp(-sparkDist * 800.0) * trebleVal * behindFront;
  }
  vec3 sparkleCol = vec3(0.9, 0.95, 1.0) * sparkle;

  // === EXPANSION RINGS (beat-triggered) ===
  float ringPhase = fract(time * 0.5);
  float ring = exp(-pow((r - ringPhase * 2.0) * 10.0, 2.0)) * beatPulse * 1.0;
  vec3 ringCol = vec3(0.6, 0.4, 1.0) * ring;

  // === SINGULARITY CORE ===
  float core = exp(-r * r * 50.0) * (0.5 + beatPulse * 0.5);
  vec3 coreCol = vec3(1.0, 1.0, 1.0) * core;

  // === RADIAL CHAOS RAYS ===
  float rays = 0.0;
  for (int i = 0; i < 12; i++) {
    float rayAngle = float(i) * 0.5236 + time * 0.2;
    float angleDiff = abs(mod(angle - rayAngle + 3.14159, 6.28318) - 3.14159);
    float ray = smoothstep(0.05 + uChaos * 0.08, 0.0, angleDiff) *
                smoothstep(waveFront + 0.3, waveFront - 0.1, r) *
                (1.0 - smoothstep(0.0, 0.05, r));
    rays += ray * (0.5 + hash(vec2(float(i), 3.7)) * 0.5);
  }
  vec3 rayCol = temperatureColor(0.8) * rays * 0.4;

  // === ONSET FLASH ===
  vec3 onsetCol = vec3(1.0, 0.95, 0.9) * onsetPulse * 0.5 * exp(-r * 2.0);

  // Palette shift
  float palShift = uPalette * 0.2;

  // === COMBINE ===
  vec3 col = plasmaCol * plasmaIntensity +
             filamentCol + nodeCol + cmbCol +
             sparkleCol + ringCol + coreCol + rayCol + onsetCol;

  // Palette rotation
  col = vec3(
    col.r * cos(palShift) - col.b * sin(palShift),
    col.g,
    col.r * sin(palShift) + col.b * cos(palShift)
  );

  // Energy modulation
  col *= (0.8 + uEnergy * uSensitivity * 0.6);
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

