float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm3(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 4; i++) { v += a * vnoise(p); p = rot * p * 2.0; a *= 0.5; }
  return v;
}

// Caustic pattern — underwater light refraction
float caustic(vec2 p, float time) {
  float c = 0.0;
  for (float i = 1.0; i <= 3.0; i++) {
    float t = time * (0.3 + i * 0.1);
    vec2 q = p * i * 1.5;
    q += vec2(sin(t + q.y * 0.5), cos(t + q.x * 0.5)) * 0.8;
    c += 1.0 / (1.0 + 40.0 * abs(sin(q.x) * sin(q.y)));
  }
  return c / 3.0;
}

// Jellyfish-like orb
float jellyfishOrb(vec2 p, vec2 center, float sz, float phase) {
  vec2 d = p - center;
  // Bell shape — wider at top, tapered at bottom
  float bellR = sz * (1.0 + 0.3 * sin(phase * 2.0));
  float bell = length(d / vec2(bellR, bellR * 0.7));
  float body = exp(-bell * bell * 3.0);

  // Pulsing tentacles below
  float tentacleY = d.y + sz * 0.5;
  if (tentacleY > 0.0) {
    float tentacles = sin(d.x * 20.0 + phase * 3.0) * 0.5 + 0.5;
    tentacles *= exp(-tentacleY * 5.0) * exp(-abs(d.x) * 8.0);
    body += tentacles * 0.3;
  }
  return body;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.4) * 0.08;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float warmthVal = uWarmth * uSensitivity;

  // Deep ocean background — gradient from deep blue to deep black
  float depthGrad = vUv.y;
  vec3 col = mix(vec3(0.0, 0.02, 0.08), vec3(0.0, 0.005, 0.02), depthGrad);

  // Underwater current flow distortion
  vec2 flowP = p;
  float currentStr = 0.4 + bassVal * 0.45;
  flowP.x += sin(p.y * 2.0 + time * 0.5) * currentStr + sin(time * 0.2 + p.y) * 0.06;
  flowP.y += cos(p.x * 1.5 + time * 0.3) * currentStr * 0.5 + cos(time * 0.18 + p.x) * 0.05;

  // Neon liquid currents — flowing streams of color
  float stream1 = fbm3(flowP * 1.5 + vec2(time * 0.2, 0.0));
  float stream2 = fbm3(flowP * 2.0 + vec2(0.0, time * 0.15) + 10.0);
  float stream3 = fbm3(flowP * 1.0 + vec2(-time * 0.1, time * 0.1) + 20.0);

  // Cyan/magenta/green neon streams
  vec3 cyanStream = vec3(0.1, 0.9, 1.0) * pow(stream1, 1.8) * 0.5;
  vec3 magentaStream = vec3(0.9, 0.15, 0.7) * pow(stream2, 1.8) * 0.4;
  vec3 greenStream = vec3(0.15, 1.0, 0.4) * pow(stream3, 2.2) * 0.35;

  col += cyanStream * (0.5 + midsVal * 0.5);
  col += magentaStream * (0.4 + trebleVal * 0.6);
  col += greenStream * (0.3 + bassVal * 0.7);

  // Caustic light patterns — underwater sun refraction
  float caust = caustic(flowP * 1.5, time);
  vec3 causticCol = vec3(0.2, 0.7, 0.6) * caust * 0.25;
  causticCol += vec3(0.1, 0.3, 0.1) * caust * trebleVal * 0.3;
  col += causticCol;

  // Bioluminescent jellyfish orbs
  for (float i = 0.0; i < 8.0; i++) {
    float seed = i * 7.3;
    vec2 orbPos = vec2(
      sin(time * 0.2 + seed) * 1.2 + cos(seed * 0.7) * 0.5,
      sin(time * 0.15 + seed * 1.3) * 0.8 + cos(time * 0.1 + seed) * 0.3
    );
    float orbPhase = time * (0.8 + hash21(vec2(i, 2.0)) * 0.4);
    float orbSize = 0.1 + hash21(vec2(i, 5.0)) * 0.12;

    // Pulse with specific audio bands
    float bandPulse = i < 2.0 ? bassVal : i < 5.0 ? midsVal : trebleVal;
    orbSize *= 1.0 + bandPulse * 0.4;

    float orb = jellyfishOrb(flowP, orbPos, orbSize, orbPhase);

    // Bioluminescent color — shifts with palette
    vec3 orbCol = 0.5 + 0.5 * cos(6.28 * (vec3(0.6, 0.3, 0.1) + i * 0.12 + uPalette * 0.3));
    orbCol = mix(orbCol, vec3(0.0, 1.0, 0.8), 0.3); // Bias towards cyan-green

    col += orbCol * orb * (0.3 + bandPulse * 0.5);
  }

  // Floating particle plankton
  for (float i = 0.0; i < 20.0; i++) {
    vec2 partPos = vec2(hash21(vec2(i, 11.0)), hash21(vec2(11.0, i))) * 4.0 - 2.0;
    partPos += vec2(sin(time * 0.3 + i), cos(time * 0.2 + i * 1.5)) * 0.3;
    partPos = mod(partPos + 2.0, 4.0) - 2.0;
    float partDist = length(p - partPos);
    col += vec3(0.3, 0.9, 0.5) * exp(-partDist * 40.0) * 0.1;
