// Cinematic accretion disk color: hot white/blue near center -> orange/red at distance
vec3 accretionColor(float temp, float angle) {
  float doppler = sin(angle) * 0.3;
  float effTemp = clamp(temp + doppler, 0.0, 1.0);
  vec3 col;
  if (effTemp > 0.8) {
    col = mix(vec3(0.9, 0.85, 1.0), vec3(0.95, 0.97, 1.0), (effTemp - 0.8) * 5.0);
  } else if (effTemp > 0.5) {
    col = mix(vec3(0.4, 0.6, 1.0), vec3(0.9, 0.85, 1.0), (effTemp - 0.5) / 0.3);
  } else if (effTemp > 0.25) {
    col = mix(vec3(1.0, 0.4, 0.05), vec3(1.0, 0.7, 0.2), (effTemp - 0.25) / 0.25);
  } else {
    col = mix(vec3(0.4, 0.02, 0.0), vec3(1.0, 0.4, 0.05), effTemp / 0.25);
  }
