  vec2 warpedP = p;
  vec3 glowTotal = vec3(0.0);
  vec3 photonRings = vec3(0.0);
  float totalDarkness = 0.0;
  float totalSparkle = 0.0;
  float totalRingGlow = 0.0;

  float ringRadius = 0.12 + bassVal * 0.04;
  float ringWidth = 0.04 + midsVal * 0.015;

  // Store lens positions for merge detection
  vec2 lensPositions[8];

  for (int i = 0; i < 8; i++) {
    if (i > numLenses) break; // include one extra for smooth blend
    float fi = float(i);
    float h1 = hash1(fi + 1.0);
    float h2 = hash1(fi + 7.0);
    float h3 = hash1(fi + 13.0);

    // Strength: last lens fades in/out for smooth split/merge
    float strengthMult = 1.0 / (1.0 + fi * 0.15);
    if (i == numLenses) strengthMult *= lensBlend; // partial lens

    // Each lens gets unique orbit speed, phase offset, and radius multiplier
    float orbitSpeed = 0.3 + h1 * 0.5;
    float phaseOffset = fi * 6.2832 / max(dynamicCount, 1.0) + h2 * 1.0;
    float radiusMult = 0.7 + h3 * 0.6;

    // Orbit position — each drifts along a unique Lissajous-like path
    float freqX = orbitSpeed * (1.0 + h2 * 0.4);
    float freqY = orbitSpeed * (0.8 + h1 * 0.5);
    vec2 gravPos = vec2(
      cos(time * freqX + phaseOffset) * uOrbitRadius * radiusMult,
      sin(time * freqY + phaseOffset + h3 * 3.14) * uOrbitRadius * radiusMult
    );

    // When merging (low dynamicCount), pull lenses toward each other
    float mergeForce = smoothstep(2.5, 1.0, dynamicCount);
    gravPos *= 1.0 - mergeForce * 0.6; // Collapse toward center when merging

    // Chaos perturbation — audio-reactive drift
    gravPos += vec2(
      sin(time * (1.0 + h1) + fi * 2.0) * uChaos * 0.1,
      cos(time * (0.8 + h2) + fi * 1.5) * uChaos * 0.1
    );

    // Bass pushes lenses outward from center (splitting)
    gravPos *= 1.0 + bassVal * 0.15;

    // Mids shift positions laterally
    gravPos.x += sin(time * 0.7 + fi * 1.3) * midsVal * 0.05;

    lensPositions[i] = gravPos;

    // Check proximity to other lenses — when close, boost both
    float proxBoost = 1.0;
    for (int j = 0; j < 8; j++) {
      if (j >= i) break;
      float proxDist = length(gravPos - lensPositions[j]);
      proxBoost += smoothstep(0.2, 0.0, proxDist) * 0.5; // merge glow
    }

    // Apply gravitational lensing warp
    vec2 delta = warpedP - gravPos;
    float dist = length(delta);
    warpedP += normalize(delta + vec2(0.0001)) * effStrength * 0.15 * strengthMult * proxBoost / (dist * dist + 0.02);

    float angle = atan(delta.y, delta.x);

    // Accretion disk ring — grows when lenses merge
    float effRingRadius = ringRadius * (1.0 + (proxBoost - 1.0) * 0.3);
    float ring = smoothstep(effRingRadius + ringWidth * 2.0, effRingRadius, dist) *
                 smoothstep(effRingRadius - ringWidth, effRingRadius, dist);

    // Temperature
    float temp = clamp(1.0 - (dist - effRingRadius * 0.5) / (ringWidth * 4.0), 0.0, 1.0);

    // Disk rotation + turbulence
    float diskAngle = angle + time * (1.5 + h1);
    float turbulence = sin(diskAngle * (3.0 + fi) + dist * (18.0 + fi * 2.0) + time * (0.8 + h2)) * 0.15 + 0.85;

    // Cinematic accretion disk color
    float brightness = 2.5 * strengthMult * proxBoost;
    glowTotal += accretionColor(temp, diskAngle) * ring * brightness * turbulence;

    // Photon ring (Einstein ring)
    float photonRing = exp(-pow((dist - effRingRadius * 0.7) / 0.008, 2.0)) * (1.5 * strengthMult);
    photonRings += vec3(0.9, 0.95, 1.0) * photonRing;

    // Event horizon
    float eventHorizon = smoothstep(effRingRadius * 0.35, effRingRadius * 0.2, dist);
    totalDarkness = max(totalDarkness, eventHorizon);

    // Sparkle
    totalSparkle += trebleVal * (0.2 * strengthMult) / (dist + 0.03);

    // Ring glow accumulator for onset flash
    totalRingGlow += ring * strengthMult;
  }

  vec3 sparkleCol = vec3(0.8, 0.85, 1.0) * totalSparkle * 0.4;

  // === BACKGROUND: dark space with subtle blue/purple starfield ===
  float n1 = fbm(warpedP * 3.0 + time * 0.1);
  float n2 = fbm(warpedP * 5.0 - time * 0.08 + 10.0);

  vec3 bg = vec3(0.0);
  bg.r = n1 * 0.03 + 0.005;
  bg.g = n1 * 0.01 + 0.003;
  bg.b = n1 * 0.06 + n2 * 0.04 + 0.015;

  // Background star field
  float starGrid = 150.0;
  float sgx = floor(p.x * starGrid);
  float sgy = floor(p.y * starGrid);
  float sh = hash(vec2(sgx, sgy));
  if (sh > 0.985) {
    float scx = fract(p.x * starGrid) - hash(vec2(sgx + 5.0, sgy + 3.0));
    float scy = fract(p.y * starGrid) - hash(vec2(sgx + 7.0, sgy + 11.0));
    float sd = scx * scx + scy * scy;
    float sGlow = exp(-sd * 1500.0) * 0.5;
    float starTemp = hash(vec2(sgx + 13.0, sgy + 17.0));
    bg.r += sGlow * (0.5 + starTemp * 0.3);
    bg.g += sGlow * (0.5 + starTemp * 0.2);
    bg.b += sGlow * (0.7 + starTemp * 0.3);
  }

  // === ONSET FLASH ===
  vec3 onsetCol = vec3(1.0, 0.95, 0.9) * onsetPulse * 0.15 * totalRingGlow;

  // === COMBINE ===
  vec3 col = bg + glowTotal + photonRings + sparkleCol + onsetCol;

  // Apply event horizon darkness (black void)
  col *= (1.0 - totalDarkness * 0.95);

  // Energy-driven brightness modulation
  col *= (0.8 + uEnergy * uSensitivity * 0.3);

  // Overall intensity
  col *= uIntensity * 1.2;

  // Beat pulse — warm flash
  col += vec3(0.3, 0.15, 0.05) * beatPulse * 0.15;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSymmetryOrder;
uniform float uBreathDepth;
uniform float uDetailLevel;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.1 + 0.5;
    a *= 0.5;
  }
  return v;
}

// Kaleidoscope fold
vec2 kaleido(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle + 6.2832, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.75;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float harmonicityVal = uHarmonicity;
  float bpmSinVal = uBpmSin;
  float energyVal = uEnergy * uSensitivity;
  float centroidVal = uSpectralCentroid;

  // Breathing: expand/contract with BPM
  float breathCycle = bpmSinVal * 0.5 + 0.5; // 0 to 1
  float breathScale = 1.0 + breathCycle * uBreathDepth * 0.55 + bassVal * uBreathDepth * 0.35 + sin(uTime * 0.3) * 0.06;

  // Apply breathing scale
  p /= breathScale;

  // Symmetry order: 6-16 folds, harmonicity increases it
  float folds = floor(6.0 + uSymmetryOrder * 10.0 + harmonicityVal * 4.0);

  // Kaleidoscope fold
  vec2 kp = kaleido(p, folds);
  float r = length(p);
  float kr = length(kp);

  // Detail layers based on detailLevel + treble
  float detail = uDetailLevel + trebleVal * 0.3;
  int layers = int(3.0 + detail * 5.0);

  float pattern = 0.0;
  float amp = 1.0;

  for (int i = 0; i < 8; i++) {
    if (i >= layers) break;
    float fi = float(i);

    // Geometric pattern layer
    float freq = 3.0 + fi * 4.0;
    float geom = sin(kp.x * freq + time * (0.5 + fi * 0.2)) *
                 cos(kp.y * freq * 0.7 - time * 0.3);
    geom = abs(geom);

    // Ring component
    float ring = abs(sin(kr * (5.0 + fi * 3.0) - time * 0.5));
    ring = pow(ring, 2.0);

    // Diamond lattice
    float diamond = abs(kp.x + kp.y) + abs(kp.x - kp.y);
    diamond = abs(sin(diamond * (4.0 + fi * 2.0) + time * 0.3));

    pattern += (geom * 0.4 + ring * 0.3 + diamond * 0.3) * amp;
    amp *= 0.6;
  }

  pattern /= 2.0; // Normalize

  // Coloring: jewel tones rotating with time
  float hue = pattern * 0.6 + time * 0.08 + r * 0.3 + uPalette * 0.3;
  vec3 jewel1 = vec3(0.9, 0.25, 0.55); // Ruby
  vec3 jewel2 = vec3(0.25, 0.7, 1.0); // Sapphire
  vec3 jewel3 = vec3(0.35, 0.9, 0.45); // Emerald
  vec3 jewel4 = vec3(1.0, 0.8, 0.25); // Topaz

  float h4 = fract(hue) * 4.0;
  vec3 col;
  if (h4 < 1.0) col = mix(jewel1, jewel2, fract(h4));
  else if (h4 < 2.0) col = mix(jewel2, jewel3, fract(h4));
  else if (h4 < 3.0) col = mix(jewel3, jewel4, fract(h4));
  else col = mix(jewel4, jewel1, fract(h4));

  col *= pattern;

  // Edge glow on mandala structure
  float edges = abs(sin(kr * 20.0 - time));
  edges = pow(edges, 8.0);
  col += edges * 0.15 * vec3(1.0, 0.8, 0.6);

  // Center jewel
  float centerJewel = exp(-r * r * 8.0);
  vec3 centerColor = mix(jewel1, jewel4, sin(time * 0.5) * 0.5 + 0.5);
  col += centerJewel * centerColor * 0.4 * (1.0 + kickVal * 0.5);

  // Breathing brightness modulation
  col *= 0.8 + breathCycle * 0.3;

  // Mids: color richness
  col *= 1.0 + midsVal * 0.15;

  // Centroid: shifts warm/cool
  col = mix(col, col * vec3(1.1, 0.9, 0.8), centroidVal * 0.2);

  // Chaos: organic noise overlay
  float chaosNoise = fbm(p * 5.0 + time * 0.5) * uChaos * 0.2;
  col *= 1.0 + chaosNoise;

  // Energy brightness
  col *= 0.85 + energyVal * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBreathDepth;
uniform float uVeinDensity;
uniform float uSurfaceTension;

// Simplex-like noise from hash
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  vec2 shift = vec2(100.0);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

// Voronoi for vein patterns
float voronoi(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = vec2(hash(i + neighbor), hash(i + neighbor + vec2(37.0, 17.0)));
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      minDist = min(minDist, dist);
    }
  }
  return minDist;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 0.6);

  // Audio influences
  float bassBreath = bass() * uSensitivity;
  float midsRipple = mids() * uSensitivity;
  float trebleShimmer = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Radial distance from center
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Primary breath cycle: center bulges out, edges pull in
  float breathCycle = sin(time * 1.2 + bassBreath * 3.0) * 0.5 + 0.5;
  float breathDisp = uBreathDepth * breathCycle * (1.0 - smoothstep(0.0, 1.5, r)) + sin(uTime * 0.3) * 0.05;

  // Secondary ripples from mids
  float ripple = sin(r * 8.0 - time * 3.0 + midsRipple * 4.0) * 0.1 * uBreathDepth;
  ripple *= smoothstep(0.0, 0.3, r) * smoothstep(2.0, 0.5, r);

  // Displaced coordinates for coloring
  float totalDisp = breathDisp + ripple;
  vec2 dp = p * (1.0 + totalDisp * 0.3);

  // Subsurface veins using Voronoi
  float veinScale = uVeinDensity * 2.0;
  float veins = voronoi(dp * veinScale + vec2(time * 0.1, time * 0.15));
  veins = smoothstep(0.0, 0.15, veins); // thin bright veins
  float veinGlow = (1.0 - veins) * (0.5 + bassBreath * 0.5);

  // Surface normal approximation for lighting
  float eps = 0.01;
  float hCenter = fbm(dp * 3.0 + time * 0.2) + totalDisp;
  float hRight = fbm((dp + vec2(eps, 0.0)) * 3.0 + time * 0.2) + totalDisp;
  float hUp = fbm((dp + vec2(0.0, eps)) * 3.0 + time * 0.2) + totalDisp;
  vec3 normal = normalize(vec3(hCenter - hRight, hCenter - hUp, eps * 2.0));

  // Fresnel-like rim lighting
  float fresnel = pow(1.0 - abs(normal.z), 3.0);

  // Surface tension shimmer on treble
  float shimmer = sin(angle * 12.0 + r * 20.0 - time * 5.0) * 0.5 + 0.5;
  shimmer *= trebleShimmer * uSurfaceTension;

  // Color palette: organic flesh tones to alien
  float hue = fract(
    0.0 + uPalette * 0.1
    + totalDisp * 0.2
    + veinGlow * 0.1
    + time * 0.02
  );
  float palettePhase = hue * 6.2832;
  vec3 baseColor = 0.5 + 0.5 * cos(palettePhase + vec3(0.0, 2.1, 4.2));

  // Darken edges (subsurface scattering feel)
  float sss = smoothstep(2.0, 0.0, r) * 0.8 + 0.2;

  // Vein color: warmer, more saturated
  vec3 veinColor = 0.5 + 0.5 * cos(palettePhase + vec3(0.3, 1.5, 3.8));
  veinColor *= 1.8;

  // Combine
  vec3 col = baseColor * sss;
  col += veinColor * veinGlow * 0.4;
  col += fresnel * vec3(0.3, 0.5, 0.7) * uSurfaceTension;
  col += shimmer * vec3(0.4, 0.6, 0.8);

  // Breathing brightness modulation
  col *= 0.6 + breathCycle * 0.4 * uIntensity;

  // Beat pulse glow
  col += vec3(beatPulse * 0.1, beatPulse * 0.08, beatPulse * 0.12);

  // Onset flash
  col += vec3(onsetFlash * 0.15);

  // Chaos adds noise distortion
  float chaosNoise = fbm(p * (3.0 + uChaos * 10.0) + time) * uChaos * 0.3;
  col += chaosNoise * baseColor;

  // Final intensity
  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uJuliaSpeed;
uniform float uFlameIntensity;
uniform float uIterCount;

#define PI 3.14159265359
#define TAU 6.28318530718

// Fire palette
vec3 burningPalette(float t, float offset) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 0.7, 0.4);
  vec3 d = vec3(0.0 + offset * 0.1, 0.15, 0.3);
  return a + b * cos(TAU * (c * t + d));
}

vec3 coolAccent(float t, float offset) {
  return 0.5 + 0.5 * cos(TAU * (vec3(0.8, 1.0, 1.2) * t + vec3(0.5 + offset * 0.1, 0.6, 0.7)));
}

// Julia C parameter path through interesting space
vec2 juliaC(float t) {
  float angle = t * TAU * 0.1;
  float r = 0.7 + 0.15 * sin(t * 0.7);
  vec2 base = vec2(r * cos(angle), r * sin(angle));
  base += vec2(0.1 * sin(t * 2.3), 0.1 * cos(t * 1.9));
  return base;
}

void main() {
  vec2 uv = (vUv - 0.5) * (uZoom * 4.0 + 2.0);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.65;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onsetFlash = uOnset * uSensitivity * 1.5;
  float kickVal = uKick * uSensitivity * 1.5;

  // Slow rotation
  float rotAngle = time * 0.15 + uChaos * sin(time * 0.1) * 0.3;
  float cr = cos(rotAngle), sr = sin(rotAngle);
  uv = vec2(uv.x * cr - uv.y * sr, uv.x * sr + uv.y * cr);

  // Julia C parameter: drifts through space
  float drift = uJuliaSpeed * 2.0 + 0.5;
  vec2 c = juliaC(time * drift * 0.3);
  c += vec2(bassVal * 0.15, midsVal * 0.1);
  c += vec2(sin(beatPulse * 5.0), cos(beatPulse * 5.0)) * beatPulse * 0.1;

  // Iteration
  float maxIterF = 80.0 * uIterCount + trebleVal * 40.0;
  int maxIter = int(min(maxIterF, 150.0));

  vec2 z = uv;
  float iter = 0.0;
  float trap = 1e10;
  float edgeTrap = 1e10;

  for (int i = 0; i < 150; i++) {
    if (i >= maxIter) break;
    if (dot(z, z) > 256.0) break;

    // Burning Ship: abs of both components before squaring
    z = vec2(abs(z.x), abs(z.y));
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;

    float r2 = dot(z, z);
    trap = min(trap, length(z));
    edgeTrap = min(edgeTrap, abs(z.x * z.y));
    iter += 1.0;
  }

  float r2 = dot(z, z);
  bool escaped = r2 > 256.0;

  // Smooth iteration
  float smoothIter = iter;
  if (escaped) {
    float log_zn = log(r2) * 0.5;
    float nu = log(log_zn / log(2.0)) / log(2.0);
    smoothIter = iter + 1.0 - nu;
  }

  vec3 col;
  float contrast = uFlameIntensity * 1.5 + 0.5;

  if (escaped) {
    float colorT = fract(smoothIter * 0.025 + time * 0.05 + bassVal * 0.08 + sin(uTime * 0.2) * 0.15);
    col = burningPalette(colorT, uPalette);
    float brightness = pow(1.0 - smoothIter / float(maxIter), contrast);
    col *= 0.2 + brightness * 0.8;

    // Edge detail
    float edgeGlow = exp(-edgeTrap * 20.0);
    col += burningPalette(fract(colorT + 0.3), uPalette) * edgeGlow * (0.3 + trebleVal * 0.7);

    float bands = sin(smoothIter * 0.3) * 0.5 + 0.5;
    col *= 0.8 + bands * 0.2;
  } else {
    // Interior: cool colors with orbit trap
    float trapColor = fract(trap * 3.0 + time * 0.02);
    col = coolAccent(trapColor, uPalette) * 0.15;
    float innerGlow = exp(-edgeTrap * 10.0);
    col += coolAccent(fract(trapColor + 0.4), uPalette) * innerGlow * 0.3;
    col += burningPalette(fract(trap * 5.0 + time * 0.01), uPalette) * 0.05;
  }

  // Mids color shift
  col = mix(col, burningPalette(fract(smoothIter * 0.01 + midsVal), uPalette) * length(col) * 1.5, midsVal * 0.2);

  // Beat bright flash
  col += burningPalette(fract(time * 0.1), uPalette) * beatPulse * 0.25;

  // Onset surge
  col += vec3(onsetFlash * 0.1, onsetFlash * 0.06, onsetFlash * 0.04);

  // Kick brightness
  col *= 1.0 + kickVal * 0.3;

  col *= uIntensity * 1.5;

  // Vignette
  float vig = 1.0 - smoothstep(0.5, 1.2, length(vUv - 0.5) * 1.4);
  col *= vig;

  col += vec3(0.008, 0.005, 0.01);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

