// Hash functions
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Neon color palette: cycles through pink, cyan, green, gold
vec3 neonColor(float idx, float paletteOffset) {
  float t = fract(idx + paletteOffset * 0.25);
  float tau = 6.28318;
  // Vibrant neon colors
  float r = 0.5 + 0.5 * sin(tau * t + 0.0);
  float g = 0.5 + 0.5 * sin(tau * t + 2.09);
  float b = 0.5 + 0.5 * sin(tau * t + 4.19);
  // Boost saturation
  float mx = max(r, max(g, b));
  float mn = min(r, min(g, b));
  float sat = (mx - mn) / (mx + 0.001);
  r = mix(mx, r, 0.8 + sat * 0.2);
  g = mix(mx, g, 0.8 + sat * 0.2);
  b = mix(mx, b, 0.8 + sat * 0.2);
  return vec3(r, g, b);
}

// Single rain layer
float rainLayer(vec2 uv, float layerScale, float layerSpeed, float time, float density, float dropLen, float bassVal) {
  // Scale UV to create grid cells
  float gridX = layerScale * (8.0 + density * 16.0);
  float gridY = 3.0 + dropLen * 4.0;

  vec2 gridUV = vec2(uv.x * gridX, uv.y * gridY);

  // Cell IDs
  float cellX = floor(gridUV.x);
  float cellY = floor(gridUV.y);

  // Random per-column properties
  float colRand = hash11(cellX * 127.1 + layerScale * 43.7);
  float colPhase = hash11(cellX * 311.7 + layerScale * 91.3);
  float colBright = 0.5 + colRand * 0.5;

  // Rain drop position within cell (falls downward)
  float fallSpeed = layerSpeed * (1.0 + bassVal * 2.0) * (0.7 + colRand * 0.6);
  float dropY = fract(colPhase + time * fallSpeed * 0.5);

  // Local coordinates within cell
  vec2 localUV = fract(gridUV);

  // Drop shape: narrow in X, elongated in Y
  float dropWidth = 0.08 + 0.04 * colRand;
  float dropHeight = 0.15 + dropLen * 0.3;

  // Horizontal centering
  float xDist = abs(localUV.x - 0.5);
  float xMask = smoothstep(dropWidth, dropWidth * 0.3, xDist);

  // Vertical: moving drop with trail
  float yPos = 1.0 - dropY;
  float yDist = localUV.y - yPos;
  float yMask = smoothstep(0.0, -dropHeight, yDist) * smoothstep(-dropHeight - 0.05, -dropHeight, yDist - 0.02);

  // Combine into drop shape
  float drop = xMask * yMask * colBright;

  // Bright tip at leading edge
  float tipGlow = smoothstep(0.02, 0.0, abs(yDist)) * xMask * 1.5;
  drop += tipGlow;

  return drop;
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * (uSpeed * 2.2);

  // Audio signals (boosted reactivity)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  // Apply zoom
  vec2 centeredUv = (uv - 0.5) * (uZoom * 2.0 + 0.5) + 0.5;

  // Chaos adds horizontal sway
  float sway = sin(centeredUv.y * 3.0 + time * 0.5) * uChaos * 0.03;
  centeredUv.x += sway;

  // Background: dark with subtle gradient
  float bgGrad = 0.02 + centeredUv.y * 0.03;
  vec3 bgColor = vec3(bgGrad * 0.3, bgGrad * 0.2, bgGrad * 0.5);

  // Accumulate rain from 4 layers (back to front)
  vec3 rainColor = vec3(0.0);

  // Layer 1 (far back, slow, dim)
  float r1 = rainLayer(centeredUv, 0.6, 0.6, time, uRainDensity * 0.7, uDropLength * 0.8, bassVal);
  vec3 c1 = neonColor(0.0, uPalette);
  rainColor += c1 * r1 * 0.3;

  // Layer 2 (mid-far)
  float r2 = rainLayer(centeredUv + vec2(0.33, 0.0), 0.8, 0.8, time, uRainDensity * 0.85, uDropLength * 0.9, bassVal);
  vec3 c2 = neonColor(0.25, uPalette);
  rainColor += c2 * r2 * 0.5;

  // Layer 3 (mid-near)
  float r3 = rainLayer(centeredUv + vec2(0.67, 0.0), 1.0, 1.0, time, uRainDensity, uDropLength, bassVal);
  vec3 c3 = neonColor(0.5, uPalette);
  rainColor += c3 * r3 * 0.7;

  // Layer 4 (closest, fastest, brightest)
  float r4 = rainLayer(centeredUv + vec2(0.17, 0.0), 1.3, 1.3, time, uRainDensity * 1.2, uDropLength * 1.1, bassVal);
  vec3 c4 = neonColor(0.75, uPalette);
  rainColor += c4 * r4 * 1.0;

  // Treble sparkle: bright dots at random positions
  float sparkleGrid = 40.0 + trebleVal * 20.0;
  vec2 sparkleCell = floor(centeredUv * sparkleGrid);
  float sparkleRand = hash21(sparkleCell);
  float sparkleThresh = 0.92 - trebleVal * 0.1;
  float sparkle = smoothstep(sparkleThresh, 1.0, sparkleRand) * trebleVal;
  vec3 sparkleCol = neonColor(sparkleRand * 4.0, uPalette) * sparkle * 2.0;
  // Flicker sparkles
  float flicker = sin(time * 20.0 + sparkleRand * 100.0) * 0.5 + 0.5;
  sparkleCol *= flicker;

  // Beat splash ripples at bottom
  float splashY = 1.0 - centeredUv.y; // Distance from bottom
  float splashWave = sin(splashY * 30.0 - beatPulse * 10.0) * 0.5 + 0.5;
  float splashMask = smoothstep(0.3, 0.0, splashY) * beatPulse;
  vec3 splashColor = neonColor(time * 0.1, uPalette) * splashWave * splashMask * 0.8;

  // Onset flash: horizontal scan line
  float scanLine = smoothstep(0.02, 0.0, abs(centeredUv.y - fract(onset * 3.0 + time * 0.1)));
  vec3 scanColor = vec3(1.0, 0.8, 1.0) * scanLine * onset * 0.5;

  // Combine everything
  vec3 finalCol = bgColor + rainColor * uIntensity * 1.5 + sparkleCol + splashColor + scanColor;

  // Energy boost
  finalCol *= 1.0 + energy * 0.2;

  // Kick pulse: brief overall brightness
  finalCol += vec3(kick * 0.05, kick * 0.03, kick * 0.07);

  // CRT-style scanlines for atmosphere
  float scanlines = sin(vUv.y * 600.0) * 0.03 + 0.97;
  finalCol *= scanlines;

  // Ensure never fully black
  finalCol += vec3(0.01, 0.005, 0.02);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

