uniform float uRippleScale;
uniform float uCausticsSharpness;

// Caustic layer: overlapping sine waves simulating refracted light convergence
float causticLayer(vec2 uv, float t, float freq, float phase) {
  // Multiple sine waves at different angles create the caustic network
  float c = 0.0;
  c += sin(uv.x * freq * 1.0 + t * 0.8 + phase);
  c += sin(uv.y * freq * 1.1 + t * 0.9 + phase * 1.3);
  c += sin((uv.x + uv.y) * freq * 0.7 + t * 0.7 + phase * 0.7);
  c += sin((uv.x - uv.y) * freq * 0.8 + t * 1.1 + phase * 1.1);
  // Diagonal waves
  float a1 = 0.7854; // 45 degrees
  c += sin((uv.x * cos(a1) + uv.y * sin(a1)) * freq * 0.9 + t * 0.6 + phase * 0.5);
  float a2 = 1.047;  // 60 degrees
  c += sin((uv.x * cos(a2) + uv.y * sin(a2)) * freq * 1.05 + t * 1.0 + phase * 1.5);

  c /= 6.0;
  return c;
}

void main() {
  float time = uTime * (uSpeed * 2.8);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Water depth affects pattern scale
  float depth = 1.0 + uWaterDepth * 3.0;
  float ripple = 3.0 + uRippleScale * 8.0 + midsVal * 3.0;

  // Bass makes patterns breathe
  float breathe = 1.0 + bassVal * 0.45 + sin(uTime * 0.4) * 0.08;
  vec2 uv = p * depth * breathe;

  // Layer 1: main caustic network
  float c1 = causticLayer(uv, time, ripple, 0.0);

  // Layer 2: secondary at different scale/speed
  float c2 = causticLayer(uv * 1.3, time * 0.8, ripple * 0.8, 3.7);

  // Layer 3: fine detail (treble-reactive)
  float c3 = causticLayer(uv * 2.0, time * 1.2, ripple * 1.5, 7.1);
  c3 *= 0.5 + trebleVal * 1.5;

  // Layer 4: chaos layer
  float c4 = causticLayer(uv * 0.7 + vec2(time * 0.1), time * 0.5, ripple * 0.6, 11.3);
  c4 *= uChaos;

  // Combine: caustics are the bright convergence points
  float caustic = c1 + c2 * 0.7 + c3 * 0.4 + c4 * 0.3;

  // Sharpen caustic lines
  float sharpness = 2.0 + uCausticsSharpness * 8.0;
  caustic = pow(max(0.0, caustic * 0.5 + 0.5), sharpness);

  // Normalize
  caustic = clamp(caustic * 2.0, 0.0, 1.0);

  // Water color palette
  float hueShift = uPalette * 0.15;
  vec3 deepWater = vec3(0.0 + hueShift * 0.1, 0.05 + hueShift * 0.05, 0.15);
  vec3 shallowWater = vec3(0.0, 0.2 + hueShift * 0.1, 0.35 + hueShift * 0.05);
  vec3 causticColor = vec3(0.7 + hueShift * 0.25, 0.95, 1.0);
  vec3 brightCaustic = vec3(1.0, 1.0, 0.95);

  // Color mapping
  vec3 col = mix(deepWater, shallowWater, caustic * 0.5);
  col = mix(col, causticColor, smoothstep(0.3, 0.7, caustic));
  col = mix(col, brightCaustic, smoothstep(0.7, 1.0, caustic));

  // Beat flash along caustic lines
  float beatFlash = beatPulse * caustic * 0.5;
  col += vec3(beatFlash * 0.3, beatFlash * 0.5, beatFlash * 0.6);

  // Kick pulse: bright burst
  col += vec3(0.1, 0.2, 0.25) * kickVal * caustic;

  // Onset: white flash
  col += vec3(onsetVal * 0.25);

  // Dappled light variation
  float dapple = sin(p.x * 20.0 + time * 0.5) * sin(p.y * 20.0 + time * 0.7) * 0.05;
  col += vec3(dapple * 0.5, dapple * 0.8, dapple);

  // Energy vibrancy
  col *= 1.0 + energyVal * 0.25;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

