// Hash function for Voronoi point generation
vec2 causticHash(float ix, float iy) {
  float d1 = ix * 127.1 + iy * 311.7;
  float d2 = ix * 269.5 + iy * 183.3;
  return vec2(
    fract(sin(d1) * 43758.5453),
    fract(sin(d2) * 43758.5453)
  );
}

// Single-scale Voronoi minimum distance
float voronoiDist(vec2 sp, float t, float speed) {
  float ipx = floor(sp.x);
  float ipy = floor(sp.y);
  float fpx = fract(sp.x) - 0.5;
  float fpy = fract(sp.y) - 0.5;
  float minDist = 10.0;

  for (int ox = -1; ox <= 1; ox++) {
    for (int oy = -1; oy <= 1; oy++) {
      float nx = ipx + float(ox);
      float ny = ipy + float(oy);
      vec2 h = causticHash(nx, ny);
      float ptX = float(ox) - 0.5 + sin(t * speed + h.x * 6.28) * 0.45;
      float ptY = float(oy) - 0.5 + cos(t * speed * 1.1 + h.y * 6.28) * 0.45;
      float dx = fpx - ptX;
      float dy = fpy - ptY;
      float d = pow(dx * dx + dy * dy, 0.5);
      minDist = min(minDist, d);
    }
  }
  return minDist;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.8);

  // Audio influences
  float bassInfluence = bass() * uSensitivity;
  float midsInfluence = mids() * uSensitivity;
  float trebleInfluence = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  // Domain warp for organic water motion
  float warpStr = uRoughness * 0.14 + bassInfluence * 0.13;
  float wx = sin(p.y * 3.0 + time * 0.5) * warpStr + sin(uTime * 0.2 + p.y) * 0.03;
  float wy = cos(p.x * 2.5 - time * 0.4) * warpStr + cos(uTime * 0.18 + p.x) * 0.025;

  // === CAUSTIC LAYER 1 (large scale) ===
  float s1 = 4.0 + bassInfluence * 2.0 + uChaos;
  vec2 sp1 = vec2((p.x + wx) * s1, (p.y + wy) * s1);
  float minDist1 = voronoiDist(sp1, time, 0.3);
  float caustic1 = pow(1.0 - smoothstep(0.0, 0.5, minDist1), 6.0);

  // === CAUSTIC LAYER 2 (medium scale) ===
  float s2 = 7.0 + bassInfluence + uChaos * 1.5;
  vec2 sp2 = vec2((p.x + wx * 0.7) * s2 + 13.7, (p.y + wy * 0.7) * s2 + 7.3);
  float minDist2 = voronoiDist(sp2, time, 0.5);
  float caustic2 = pow(1.0 - smoothstep(0.0, 0.45, minDist2), 7.0);

  // === CAUSTIC LAYER 3 (fine scale) ===
  float s3 = 11.0 + uChaos * 2.0;
  vec2 sp3 = vec2((p.x + wx * 0.5) * s3 + 31.1, (p.y + wy * 0.5) * s3 + 47.9);
  float minDist3 = voronoiDist(sp3, time, 0.7);
  float caustic3 = pow(1.0 - smoothstep(0.0, 0.4, minDist3), 8.0);

  // === COMBINE CAUSTIC LAYERS ===
  float totalCaustic = caustic1 * 0.5 + caustic2 * 0.35 + caustic3 * 0.15;
  float causticBright = totalCaustic * uLightInt * uIntensity;

  // Water base: deep blue-green, modulated by depth and mids
  float depthDarken = 1.0 / (uDepth + 0.5);
  float waterHueShift = midsInfluence * 0.15 + uPalette * 0.1;

  float waterR = (0.02 + waterHueShift * 0.05) * depthDarken;
  float waterG = (0.12 + waterHueShift * 0.1) * depthDarken;
  float waterB = (0.18 - waterHueShift * 0.03) * depthDarken;
  // Subtle underwater color variation
  float colorWave = sin(p.x * 3.0 + p.y * 2.0 + time * 0.2) * 0.03;
  float baseR = waterR + colorWave;
  float baseG = waterG + colorWave * 1.5;
  float baseB = waterB + colorWave * 0.5;

  float causticR = causticBright * 0.9;
  float causticG = causticBright * 1.0;
  float causticB = causticBright * 0.95;

  // Beat splash ripple + treble sparkle
  float dist = pow(p.x * p.x + p.y * p.y, 0.5);
  float splashRing = sin(dist * 25.0 - time * 4.0) * 0.5 + 0.5;
  float splash = splashRing * beatPulse * smoothstep(1.0, 0.0, dist) * 0.3;
  float sparkle = pow(totalCaustic, 3.0) * trebleInfluence * 0.8;

  // Final composite
  float outR = baseR + causticR + splash + sparkle;
  float outG = baseG + causticG + splash + sparkle;
  float outB = baseB + causticB + splash + sparkle;

  // Beat pulse overall brightness
  float beatBright = beatPulse * 0.12;
  float energyGlow = uEnergy * uSensitivity * 0.08;

  float finalR = outR + beatBright + energyGlow;
  float finalG = outG + beatBright + energyGlow;
  float finalB = outB + beatBright + energyGlow;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

