uniform float uIntensity;
uniform float uChaos;

uniform float uEdgeThickness;
uniform float uGlowStrength;
uniform float uShapeComplexity;

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// SDF for hexagon
float sdHexagon(vec2 p, float r) {
  vec2 q = abs(p);
  return max(q.x - r * 0.866, (q.x * 0.5 + q.y * 0.866) - r);
}

// Procedural scene function - returns a flat "ID" value for cel shading
float scene(vec2 uv, float t, float complexity, float bassPulse) {
  float val = 0.0;

  // Layer 1: tiled hexagons
  float hexScale = 3.0 + complexity * 4.0;
  vec2 hexUV = uv * hexScale;
  vec2 hexID = floor(hexUV);
  vec2 hexF = fract(hexUV) - 0.5;
  float hexDist = sdHexagon(hexF, 0.35 + bassPulse * 0.1);
  float hex = step(0.0, -hexDist);
  float hexCol = hash21(hexID) * 0.3 + 0.1;
  val += hex * hexCol;

  // Layer 2: concentric rings
  float r = length(uv);
  float rings = sin(r * 15.0 - t * 2.0) * 0.5 + 0.5;
  rings = step(0.5 + bassPulse * 0.1, rings);
  val += rings * 0.25;

  // Layer 3: diagonal stripes
  float stripes = sin((uv.x + uv.y) * 10.0 + t * 1.5 + sin(uv.x * 3.0) * complexity * 2.0);
  stripes = step(0.3, stripes) * 0.15;
  val += stripes;

  // Layer 4: floating circles
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    vec2 cPos = vec2(
      sin(t * 0.3 + fi * 1.7) * 0.6,
      cos(t * 0.4 + fi * 2.3) * 0.4
    );
    float cDist = length(uv - cPos);
    float circle = step(cDist, 0.15 + bassPulse * 0.05 + fi * 0.03);
    val += circle * (0.4 + fi * 0.1);
  }

  return clamp(val, 0.0, 1.0);
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Sample scene at pixel and neighbors for Sobel
  float texelSize = uEdgeThickness * 0.008 + 0.002;
  float tl = scene(p + vec2(-texelSize,  texelSize), time, uShapeComplexity, bassVal);
  float tc = scene(p + vec2( 0.0,        texelSize), time, uShapeComplexity, bassVal);
  float tr = scene(p + vec2( texelSize,  texelSize), time, uShapeComplexity, bassVal);
  float ml = scene(p + vec2(-texelSize,  0.0),       time, uShapeComplexity, bassVal);
  float mc = scene(p,                                 time, uShapeComplexity, bassVal);
  float mr = scene(p + vec2( texelSize,  0.0),       time, uShapeComplexity, bassVal);
  float bl = scene(p + vec2(-texelSize, -texelSize), time, uShapeComplexity, bassVal);
  float bc = scene(p + vec2( 0.0,       -texelSize), time, uShapeComplexity, bassVal);
  float br = scene(p + vec2( texelSize, -texelSize), time, uShapeComplexity, bassVal);

  // Sobel operators
  float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
  float gy = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
  float edge = sqrt(gx * gx + gy * gy);
  edge = smoothstep(0.05, 0.2, edge);

  // Neon edge color: cycles through hot pink, electric cyan, lime
  float hueTime = time * 0.3 + uPalette * 0.5 + onsetVal * 0.5;
  float hue = fract(hueTime + mc * 0.3 + length(p) * 0.1);
  // HSV to RGB (S=1, V=1)
  float h6 = hue * 6.0;
  vec3 neonCol = vec3(
    abs(mod(h6, 6.0) - 3.0) - 1.0,
    abs(mod(h6 + 4.0, 6.0) - 3.0) - 1.0,
    abs(mod(h6 + 2.0, 6.0) - 3.0) - 1.0
  );
  neonCol = clamp(neonCol, 0.0, 1.0);
  // Boost saturation toward neon
  neonCol = neonCol * 0.6 + 0.4;

  // Glow: softer wider version of edge
  float glow = smoothstep(0.02, 0.4, edge) * uGlowStrength * (0.8 + trebleVal * 1.0);

  // Dark cel-shaded fill: quantize scene value
  float quant = floor(mc * 4.0) / 4.0;
  vec3 fillCol = vec3(quant * 0.12, quant * 0.08, quant * 0.15);
  // Tint fill slightly with palette
  fillCol += vec3(0.02, 0.01, 0.03) * sin(uPalette * 3.0 + vec3(0.0, 2.0, 4.0));

  // Composite: fill + neon edges + glow
  vec3 col = fillCol;
  col = mix(col, neonCol * 1.3, edge * 0.9);
  col += neonCol * glow * 0.5;

  // Beat flash on edges
  col += neonCol * beatPulse * edge * 0.4;

  // Onset white flash
  col += vec3(onsetVal * 0.3);

  // Energy vibrancy
  col *= 1.0 + energyVal * 0.25;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

