}

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Smooth Voronoi for cell bodies
float smoothVoronoi(vec2 p, float smoothness) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float res = 0.0;

  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      res += exp(-dist / smoothness);
    }
  }

  return -smoothness * log(res);
}

// Voronoi cell ID and distance
vec3 voronoiCell(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  vec2 nearestCell = vec2(0.0);

  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      if (dist < minDist) {
        minDist = dist;
        nearestCell = i + neighbor;
      }
    }
  }

  return vec3(minDist, nearestCell);
}

// Psychedelic HSV to RGB
vec3 hsv2rgb(vec3 c) {
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 0.4);

  // Audio influences
  float bassDivision = bass() * uSensitivity;
  float midsMetab = mids() * uSensitivity;
  float trebleDetail = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Cell animation: cells drift, deform, and MUTATE over time
  float metabSpeed = uMetabolism * (1.0 + midsMetab * 0.5);

  // Discrete time steps for cellular automata mutation — faster mutation rate
  float stepInterval = 0.35 / (uDivisionRate + 0.1);
  float stepTime = floor(time / stepInterval);
  float stepFrac = fract(time / stepInterval);
  float smoothStep = stepFrac * stepFrac * (3.0 - 2.0 * stepFrac);

  // Dynamic cell scale — oscillates over time for breathing/pulsing cells
  float dynamicScale = uCellScale * (1.0 + 0.4 * sin(time * 0.7 + bassDivision * 3.0));
  dynamicScale += beatPulse * 0.8; // beat makes cells suddenly bigger/smaller

  // Grid position shifts over time — drifting pan effect
  vec2 gridShift = vec2(
    sin(time * 0.23 + stepTime * 0.5) * 0.8,
    cos(time * 0.17 + stepTime * 0.7) * 0.8
  ) + vec2(sin(time * 0.05), cos(time * 0.07)) * 1.5;

  vec2 cellP = (p + gridShift) * dynamicScale;

  // Time-evolving cell positions: Voronoi seeds drift + jump at mutation steps
  float mutationPhase = stepTime * 2.3;
  // Stronger drift and mutation-driven displacement
  cellP += vec2(
    sin(time * metabSpeed * 0.4 + p.y * 2.5) * 0.25 + sin(mutationPhase) * 0.2,
    cos(time * metabSpeed * 0.35 + p.x * 2.5) * 0.25 + cos(mutationPhase * 0.7) * 0.2
  );

  // Cell division: periodically split cells (bass-triggered) + mutation drift
  float divPhase = time * uDivisionRate * 0.8 + bassDivision * 3.0 + stepTime * 0.5;
  float divisionWave = sin(divPhase) * 0.5 + 0.5;
  cellP.x += sin(cellP.y * 3.0 + divPhase) * divisionWave * 0.2;
  cellP.y += cos(cellP.x * 2.5 + divPhase * 1.3) * divisionWave * 0.15;

  // Strong temporal mutation: cells rearrange dramatically between steps
  cellP += vec2(sin(stepTime * 2.3), cos(stepTime * 1.9)) * 0.25 * smoothStep;
  // Extra swirl mutation
  float swirlAngle = stepTime * 0.8 + time * 0.15;
  mat2 swirl = mat2(cos(swirlAngle * 0.3), -sin(swirlAngle * 0.3), sin(swirlAngle * 0.3), cos(swirlAngle * 0.3));
  cellP = swirl * cellP;

  // Smooth Voronoi for blobby cell bodies — variable smoothness
  float voronoiSmooth = 0.12 + bassDivision * 0.08 + sin(stepTime * 1.2) * 0.04;
  float cellDist = smoothVoronoi(cellP, voronoiSmooth);

  // Cell membrane: ring around each cell — pulses more dramatically
  float membraneThick = 0.10 + sin(stepTime * 3.0 + cellDist * 10.0) * 0.04 + beatPulse * 0.03;
  float membrane = smoothstep(0.08, membraneThick, cellDist) - smoothstep(membraneThick + 0.02, membraneThick + 0.08, cellDist);

  // Cell interior — size changes dramatically per mutation step
  float interiorSize = 0.18 + sin(stepTime * 1.5) * 0.06 + bassDivision * 0.05;
  float interior = smoothstep(interiorSize, 0.0, cellDist);

  // Cell ID for per-cell coloring — evolves with time
  vec3 cellInfo = voronoiCell(cellP);
  // Cell IDs shift MORE each mutation step for dramatic color changes
  float cellId = hash(cellInfo.yz + stepTime * 0.3);
  float cellIdSlow = hash(cellInfo.yz + floor(stepTime * 0.5) * 0.2); // slower changing id

  // Nucleus: bright spot near cell center — pulsing size
  float nucleusDist = cellInfo.x;
  float nucleusSize = 0.10 + sin(time * 2.0 + cellId * 6.28) * 0.04 + beatPulse * 0.03;
  float nucleus = smoothstep(nucleusSize + 0.02, nucleusSize * 0.3, nucleusDist);
  float nucleusRing = smoothstep(0.06, 0.09, nucleusDist) - smoothstep(0.09, 0.15, nucleusDist);

  // Flagella/detail on treble — more animated
  float flagella = noise(cellP * 8.0 + time * 3.0) * trebleDetail;
  float flagellaDetail = noise(cellP * 16.0 - time * 4.0) * trebleDetail * 0.5;
  // Wriggling tendrils
  float tendril = noise(cellP * 12.0 + vec2(time * 5.0, -time * 3.0)) * trebleDetail * 0.3;

  // === PSYCHEDELIC COLOR SYSTEM ===
  // Global hue rotation over time
  float globalHue = time * 0.08 + uPalette * 0.5;
  // Per-cell hue that shifts with mutation steps
  float cellHue = fract(cellId * 0.618 + globalHue + stepTime * 0.15 + energyVal * 0.1);
  // Secondary hue for gradients within cells
  float cellHue2 = fract(cellHue + 0.33 + sin(time * 0.5 + cellIdSlow * 6.28) * 0.15);

  // Vivid psychedelic cell color via HSV
  float saturation = 0.7 + 0.3 * sin(time * 1.5 + cellId * 4.0);
  float brightness = 0.6 + 0.4 * sin(time * 0.8 + cellId * 3.0);
  vec3 cellColor = hsv2rgb(vec3(cellHue, saturation, brightness));
  // Mix with complementary for psychedelic gradient
  vec3 cellColor2 = hsv2rgb(vec3(cellHue2, 0.8, 0.7));
  cellColor = mix(cellColor, cellColor2, 0.3 + 0.2 * sin(cellDist * 15.0 + time));

  // Membrane color — contrasting hue
  vec3 membraneColor = hsv2rgb(vec3(fract(cellHue + 0.5), 0.9, 0.9));

  // Nucleus color: bright, shifting
  vec3 nucleusColor = hsv2rgb(vec3(fract(cellHue + 0.15 + time * 0.05), 0.4, 1.0));
  nucleusColor += vec3(0.2) * beatPulse;

  // Background: deep dark with slow color wash
  vec3 bgColor = hsv2rgb(vec3(fract(globalHue * 0.3 + 0.7), 0.3, 0.03));
  bgColor += noise(p * 15.0 + time * 0.3) * 0.015;

  // Combine
  vec3 col = bgColor;

  // Cell interior with translucency — more vivid
  col = mix(col, cellColor * 0.6, interior * 0.7);

  // Internal organelle-like patterns
  float organelle = noise(cellP * 6.0 + time * 1.5 + stepTime * 0.5) * interior;
  col += cellColor2 * organelle * 0.25;

  // Cell membrane (bright ring) — psychedelic membrane color
  col += membraneColor * membrane * 1.5;

  // Nucleus
  col = mix(col, nucleusColor, nucleus * 0.85);
  col += membraneColor * nucleusRing * 0.6;

  // Flagella details
  col += cellColor * flagella * 0.25 * interior;
  col += cellColor2 * flagellaDetail * 0.2;
  col += membraneColor * tendril * 0.15;

  // Metabolism pulsing: cells brighten rhythmically — stronger
  float metabPulse = sin(time * metabSpeed * 2.5 + cellId * 6.2832) * 0.5 + 0.5;
  col *= 0.75 + metabPulse * 0.25 * interior;

  // Color wave across the field — psychedelic wash
  float colorWave = sin(p.x * 3.0 + p.y * 2.0 + time * 1.2) * 0.5 + 0.5;
  col += hsv2rgb(vec3(fract(globalHue + colorWave * 0.3), 0.5, 0.08)) * interior;

  // Beat pulse: all cells flash with shifting color
  vec3 flashColor = hsv2rgb(vec3(fract(time * 0.3), 0.8, 1.0));
  col += flashColor * beatPulse * 0.15 * interior;

  // Onset: bright psychedelic flash
  vec3 onsetColor = hsv2rgb(vec3(fract(time * 0.7 + 0.5), 0.6, 1.0));
  col += onsetColor * onsetFlash * 0.2;

  // Chaos: add distortion and extra organisms — more psychedelic
  float chaosNoise = noise(p * (8.0 + uChaos * 25.0) + time * 1.5) * uChaos;
  vec3 chaosColor = hsv2rgb(vec3(fract(chaosNoise * 2.0 + time * 0.1), 0.9, 0.5));
  col += chaosColor * chaosNoise * 0.25;

  // Energy reactive glow — spreads color across cells
  col += cellColor * energyVal * 0.08;

  // Radial vignette — very soft, barely noticeable
  float r = length(p);
  float vignette = smoothstep(3.0, 1.0, r);
  col *= vignette;

  // Final intensity
  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTearFrequency;
uniform float uRgbSplit;

// Hash functions
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(float px, float py) {
  float h = px * 127.1 + py * 311.7;
  return fract(sin(h) * 43758.5453);
}

vec3 hash23(float px, float py) {
  float h1 = fract(sin(px * 127.1 + py * 311.7) * 43758.5453);
  float h2 = fract(sin(px * 269.5 + py * 183.3) * 43758.5453);
  float h3 = fract(sin(px * 419.2 + py * 371.9) * 43758.5453);
  return vec3(h1, h2, h3);
}

// Simple 2D noise
float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  fx = fx * fx * (3.0 - 2.0 * fx);
  fy = fy * fy * (3.0 - 2.0 * fy);
  float a = hash21(ix, iy);
  float b = hash21(ix + 1.0, iy);
  float c = hash21(ix, iy + 1.0);
  float d = hash21(ix + 1.0, iy + 1.0);
  return mix(mix(a, b, fx), mix(c, d, fx), fy);
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // === PIXEL DISPLACEMENT ===
  // Displace certain rows horizontally
  float rowIdx = floor(vUv.y * 80.0);
  float displaceHash = hash11(rowIdx + floor(time * 2.0) * 0.1);
  float displaceActive = step(0.85 - onsetVal * 0.3 - uChaos * 0.15, displaceHash);
  float displaceAmount = (hash11(rowIdx * 7.3 + time) - 0.5) * 0.08 * displaceActive;
  displaceAmount *= (1.0 + bassVal * 2.0);

  vec2 uv = vUv;
  uv.x += displaceAmount;

  // Re-center for pattern
  vec2 pp = (uv - 0.5) * (uZoom * 4.0 + 1.0);

  // === WEAVE PATTERN ===
  float weaveFreq = 12.0 + uChaos * 8.0;
  float warpX = fract(pp.x * weaveFreq);
  float warpY = fract(pp.y * weaveFreq);
  float bandX = step(0.5, warpX);
  float bandY = step(0.5, warpY);
  // XOR creates checkerboard weave
  float weave = abs(bandX - bandY);

  // Weave cell index for coloring
  float cellX = floor(pp.x * weaveFreq);
  float cellY = floor(pp.y * weaveFreq);

  // Dark saturated textile colors based on weave direction + palette
  float hueBase = uPalette * 0.3;
  // Horizontal bands: deep blue to wine red
  float hue1 = fract(hueBase + 0.6 + cellY * 0.02 + sin(time * 0.1) * 0.05);
  // Vertical bands: forest green to deep purple
  float hue2 = fract(hueBase + 0.3 + cellX * 0.015 + cos(time * 0.08) * 0.05);

  // HSV to RGB inline (dark, saturated)
  float sat = 0.75 + midsVal * 0.15;
  float val1 = 0.2 + midsVal * 0.05;
  float val2 = 0.25 + midsVal * 0.05;

  // Simple HSV->RGB
  float h1 = hue1 * 6.0;
  float h2 = hue2 * 6.0;
  vec3 weaveCol1 = vec3(
    abs(mod(h1, 6.0) - 3.0) - 1.0,
    abs(mod(h1 + 4.0, 6.0) - 3.0) - 1.0,
    abs(mod(h1 + 2.0, 6.0) - 3.0) - 1.0
  );
  weaveCol1 = clamp(weaveCol1, 0.0, 1.0);
  weaveCol1 = mix(vec3(1.0), weaveCol1, sat) * val1;

  vec3 weaveCol2 = vec3(
    abs(mod(h2, 6.0) - 3.0) - 1.0,
    abs(mod(h2 + 4.0, 6.0) - 3.0) - 1.0,
    abs(mod(h2 + 2.0, 6.0) - 3.0) - 1.0
  );
  weaveCol2 = clamp(weaveCol2, 0.0, 1.0);
  weaveCol2 = mix(vec3(1.0), weaveCol2, sat) * val2;

  // Thread highlight on weave edges
  float edgeHighlight = smoothstep(0.48, 0.5, warpX) * smoothstep(0.52, 0.5, warpX)
    + smoothstep(0.48, 0.5, warpY) * smoothstep(0.52, 0.5, warpY);
  edgeHighlight *= 0.08;

  vec3 fabricCol = mix(weaveCol1, weaveCol2, weave) + edgeHighlight;

  // === GLITCH TEARS ===
  // Block-based tear regions
  float blockSize = 6.0 + uTearFrequency * 10.0;
  float blockX = floor(pp.x * blockSize);
  float blockY = floor(pp.y * blockSize * 0.5);
  // Time-varying block hash
  float tearTime = floor(time * 3.0 + bassVal * 2.0);
  float tearHash = hash21(blockX + tearTime * 0.37, blockY + tearTime * 0.53);

  // Lower threshold = more tears. Beat and bass lower it.
  float tearThreshold = 0.82 - uTearFrequency * 0.25 - beatPulse * 0.2 - bassVal * 0.15 - uChaos * 0.1;
  float isTear = step(tearThreshold, tearHash);

  // Tear jitter: small UV offset within tear
  float tearJitterX = (hash11(blockX * 3.7 + tearTime) - 0.5) * 0.02 * isTear;
  float tearJitterY = (hash11(blockY * 2.3 + tearTime) - 0.5) * 0.01 * isTear;

  // Neon colors inside tears
  vec3 tearSeed = hash23(blockX + tearTime * 0.7, blockY + tearTime * 0.3);
  float tearHue = fract(tearSeed.x + uPalette * 0.2 + time * 0.05);
  float th = tearHue * 6.0;
  vec3 neonCol = vec3(
    abs(mod(th, 6.0) - 3.0) - 1.0,
    abs(mod(th + 4.0, 6.0) - 3.0) - 1.0,
    abs(mod(th + 2.0, 6.0) - 3.0) - 1.0
  );
  neonCol = clamp(neonCol, 0.0, 1.0);
  // Make it neon bright
  neonCol = neonCol * 0.5 + 0.5;
  neonCol *= 1.2;
  // Pulsing glow inside tears
  neonCol *= 0.8 + 0.4 * sin(time * 5.0 + tearSeed.y * 6.28);

  // === RGB SPLIT at tear edges ===
  float splitAmount = uRgbSplit * 0.015 * (1.0 + trebleVal * 3.0);
  // Only near tear edges
  float nearTearX = floor((pp.x + 1.0 / blockSize) * blockSize);
  float nearTearY = floor((pp.y + 1.0 / (blockSize * 0.5)) * blockSize * 0.5);
  float neighborTear = hash21(nearTearX + tearTime * 0.37, nearTearY + tearTime * 0.53);
  float atEdge = abs(isTear - step(tearThreshold, neighborTear));

  // Sample at offset UVs for R and B channels
  vec2 uvR = uv + vec2(splitAmount * atEdge, 0.0);
  vec2 uvB = uv - vec2(splitAmount * atEdge, 0.0);

  // Recompute weave at offset positions for R and B
  vec2 ppR = (uvR - 0.5) * (uZoom * 4.0 + 1.0);
  vec2 ppB = (uvB - 0.5) * (uZoom * 4.0 + 1.0);
  float wR = abs(step(0.5, fract(ppR.x * weaveFreq)) - step(0.5, fract(ppR.y * weaveFreq)));
  float wB = abs(step(0.5, fract(ppB.x * weaveFreq)) - step(0.5, fract(ppB.y * weaveFreq)));

  // Color with RGB split
  vec3 baseCol = fabricCol;
  float splitR = mix(weaveCol1.r, weaveCol2.r, wR);
  float splitB = mix(weaveCol1.b, weaveCol2.b, wB);
  baseCol.r = mix(baseCol.r, splitR, atEdge * 0.7);
  baseCol.b = mix(baseCol.b, splitB, atEdge * 0.7);

  // === COMBINE FABRIC + TEARS ===
  vec3 col = mix(baseCol, neonCol, isTear);

  // === SCANLINES ===
  float scanline = sin(vUv.y * 600.0) * 0.03 + 0.97;
  col *= scanline;

  // === GLOBAL EFFECTS ===
  // Beat brightness flash
  col += beatPulse * 0.1;
  // Energy boost
  col += uEnergy * uSensitivity * 0.05;
  // Onset: extra displacement flash (brightens displaced rows)
  col += displaceActive * onsetVal * 0.15;

  // Intensity
  col *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSplitAmount;
uniform float uPulseDecay;
uniform float uJitter;

// Hash
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Procedural kaleidoscopic pattern that looks good when channels are split
float pattern(vec2 uv, float t) {
  float angle = atan(uv.y, uv.x);
  float r = length(uv);
  // 6-fold symmetry
  float sector = 3.14159265 / 3.0;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  vec2 folded = vec2(cos(angle), sin(angle)) * r;

  float n1 = valueNoise(folded * 4.0 + vec2(t * 0.3, t * 0.2));
  float n2 = valueNoise(folded * 8.0 - vec2(t * 0.5, t * 0.1));
  float n3 = sin(r * 12.0 - t * 2.0 + n1 * 6.0);
  float rings = sin(r * 20.0 - t * 3.0 + n2 * 4.0) * 0.5 + 0.5;
  float spiral = sin(angle * 6.0 + r * 10.0 - t * 1.5) * 0.5 + 0.5;

  return clamp(n1 * 0.4 + n3 * 0.3 + rings * 0.2 + spiral * 0.1, 0.0, 1.0);
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  float time = uTime * (uSpeed * 2.0);
  vec2 center = vUv - 0.5;
  float r = length(center);
  vec2 dir = normalize(center + 0.0001);

  // Audio
  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Split distance: radial, increases toward edges
  float baseSplit = uSplitAmount * 0.04;
  float beatSplit = beatPulse * 0.06 * (1.0 - uPulseDecay * 0.5);
  float kickSplit = kickVal * 0.08;
  float bassBump = bassVal * 0.03;
  float totalSplit = (baseSplit + beatSplit + kickSplit + bassBump) * (0.5 + r * 1.5);

  // Per-channel jitter from treble
  float jitterR = (valueNoise(vUv * 50.0 + time * 3.0) - 0.5) * uJitter * trebleVal * 0.02;
  float jitterG = (valueNoise(vUv * 50.0 + time * 3.0 + 17.3) - 0.5) * uJitter * trebleVal * 0.02;
  float jitterB = (valueNoise(vUv * 50.0 + time * 3.0 + 43.7) - 0.5) * uJitter * trebleVal * 0.02;

  // Offset UVs for each channel
  vec2 uvR = center + dir * (totalSplit + jitterR);
  vec2 uvG = center + dir * jitterG * 0.3;
  vec2 uvB = center - dir * (totalSplit + jitterB);

  // Scale by zoom
  float z = uZoom * 3.0 + 1.0;
  uvR *= z;
  uvG *= z;
  uvB *= z;

  // Sample pattern for each channel
  float pR = pattern(uvR, time + 0.0);
  float pG = pattern(uvG, time + 0.33);
  float pB = pattern(uvB, time + 0.67);

  // Color mapping with palette shift
  float hueShift = uPalette * 0.15 + time * 0.05;
  float colR = pR * (0.8 + 0.4 * sin(hueShift * 6.28));
  float colG = pG * (0.8 + 0.4 * sin(hueShift * 6.28 + 2.09));
  float colB = pB * (0.8 + 0.4 * sin(hueShift * 6.28 + 4.19));

  // Onset flash: white burst
  float flash = onsetVal * 0.4;
  colR += flash;
  colG += flash;
  colB += flash;

  // Energy vibrancy
