uniform float uIntensity;
uniform float uChaos;

uniform float uGearTeeth;
uniform float uDollySpeed;
uniform float uMechanicalSnap;

#define PI 3.14159265
#define TAU 6.28318530

vec3 metalPalette(float t, float offset) {
  // Metallic warm tones: copper, brass, steel, gold
  vec3 a = vec3(0.5, 0.4, 0.3);
  vec3 b = vec3(0.4, 0.35, 0.3);
  vec3 c = vec3(1.0, 0.8, 0.6);
  vec3 d = vec3(0.0 + offset * 0.25, 0.15 + offset * 0.1, 0.2 + offset * 0.15);
  return a + b * cos(TAU * (c * t + d));
}

float hash2d(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Gear SDF: circle with teeth
float gearSDF(vec2 p, float outerR, float innerR, float teeth, float rotation) {
  float r = length(p);
  float a = atan(p.y, p.x) + rotation;

  // Tooth profile
  float toothWave = cos(a * teeth) * 0.5 + 0.5;
  float toothR = mix(innerR, outerR, toothWave);

  // Main gear body
  float gearBody = r - toothR;

  // Center hole
  float hole = innerR * 0.35 - r;

  // Spokes
  float spoke = abs(sin(a * 3.0)) * innerR * 0.5 - 0.02;
  float spokeInner = max(r - innerR * 0.7, innerR * 0.4 - r);
  spoke = max(spoke, spokeInner);

  return max(gearBody, hole);
}

void main() {
  float time = uTime * (uSpeed * 1.5);
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Camera dolly forward
  float dolly = time * (uDollySpeed * 2.0) + kickVal * 0.5;

  // Grid scale with zoom
  float gridScale = 3.0 + uZoom * 4.0;
  vec2 gp = p * gridScale;

  // Parallax layers for depth
  vec3 color = vec3(0.02, 0.015, 0.01);

  float teeth = floor(6.0 + uGearTeeth * 18.0);

  for (int layer = 0; layer < 3; layer++) {
    float fl = float(layer);
    float layerDepth = 1.0 + fl * 0.5;
    float layerScale = 1.0 / layerDepth;

    vec2 lp = gp * layerScale + vec2(dolly * (0.3 + fl * 0.2), fl * 1.7);

    // Chaos distortion
    lp += vec2(sin(lp.y * 0.5 + time * 0.2), cos(lp.x * 0.5 + time * 0.3)) * uChaos * 0.2;

    // Tile into gear cells
    vec2 cellId = floor(lp);
    vec2 cellF = fract(lp) - 0.5;

    // Per-cell properties
    float cellHash = hash2d(cellId + fl * 100.0);
    float gearSize = 0.3 + cellHash * 0.15;
    float rotDir = cellHash > 0.5 ? 1.0 : -1.0;

    // Gear rotation: adjacent gears rotate in opposite directions
    float meshDir = mod(cellId.x + cellId.y, 2.0) > 0.5 ? 1.0 : -1.0;
    float rotSpeed = (1.0 + bassVal * 2.0) * meshDir * rotDir;

    // Mechanical snap: quantize rotation
    float rawRot = time * rotSpeed * 0.5;
    float snapAmount = uMechanicalSnap;
    float teethSnap = TAU / teeth;
    float snappedRot = mix(rawRot, floor(rawRot / teethSnap + 0.5) * teethSnap, snapAmount);

    // Beat click: advance one tooth
    snappedRot += beatPulse * teethSnap * meshDir;

    // Gear SDF
    float innerR = gearSize * 0.7;
    float d = gearSDF(cellF, gearSize, innerR, teeth, snappedRot);

    // Center axle
    float axle = length(cellF) - gearSize * 0.12;
    float axleMask = smoothstep(0.01, -0.01, axle);

    // Gear mask
    float gearMask = smoothstep(0.01, -0.01, d);

    // Center hole mask
    float holeMask = smoothstep(-0.01, 0.01, length(cellF) - innerR * 0.35);

    // Color
    float colorT = cellHash + midsVal * 0.3 + fl * 0.2 + time * 0.02;
    vec3 gearColor = metalPalette(colorT, uPalette);

    // Specular highlight on teeth
    float toothHighlight = abs(cos(atan(cellF.y, cellF.x) * teeth + snappedRot));
    toothHighlight = pow(toothHighlight, 8.0) * trebleVal;
    gearColor += toothHighlight * 0.4;

    // Depth shading
    gearColor *= (0.6 + 0.4 / layerDepth);

    // Apply masks
    float finalMask = max(gearMask * holeMask, axleMask) * layerScale;
    color = mix(color, gearColor, finalMask * 0.9);

    // Edge glow (gear outline)
    float edgeGlow = smoothstep(0.03, 0.0, abs(d)) * layerScale;
    color += edgeGlow * vec3(0.8, 0.6, 0.3) * (0.2 + trebleVal * 0.3);

    // Spark at teeth tips on beat
    if (beatPulse > 0.3) {
      float sparkAngle = atan(cellF.y, cellF.x) + snappedRot;
      float sparkPattern = pow(max(cos(sparkAngle * teeth), 0.0), 20.0);
      float sparkDist = smoothstep(gearSize + 0.02, gearSize - 0.01, length(cellF));
      color += sparkPattern * sparkDist * beatPulse * vec3(1.0, 0.8, 0.4) * 0.5;
    }
  }

  // Onset flash
  color += onsetVal * 0.12;

  // Vignette
  float vig = 1.0 - dot(p, p) * 0.3;
  color *= vig;

  // Intensity
  color *= uIntensity * 1.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

