vec2 particlePath(float t, float seed, float curvature) {
  float angle = seed * 6.28 + t * curvature;
  float decay = exp(-t * 0.35);
  float spiralR = t * 0.6 * decay;
  vec2 origin = vec2(hash11(seed * 3.0), hash11(seed * 7.0)) * 2.4 - 1.2;
  return origin + vec2(cos(angle), sin(angle)) * spiralR;
