      float forkLen = length(forkDelta);
      vec2 forkNorm = forkDelta / max(forkLen, 0.001);
      float proj = clamp(dot(p - forkPoint, forkNorm), 0.0, forkLen);
      vec2 closest = forkPoint + forkNorm * proj;
      float forkDist = length(p - closest);
      float fork = exp(-forkDist * forkDist * 500.0);
      col += trailCol * 0.5 * fork * onsetVal;
