  for (float b = 0.0; b < 3.0; b++) {
    float bloomPhase = mod(time * 0.5 + b * 1.3, 3.0);
    vec2 bloomCenter = vec2(hash11(b * 3.0 + floor(time * 0.5)) * 2.4 - 1.2,
