  col *= 1.0 + fluxVal * 0.3 * sin(time * 10.0);

  // Mids modulate fog density
  col += vec3(0.03, 0.04, 0.06) * midsVal * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

