  float bpm4 = uBpmSin4;

  // Dark space
  vec3 col = vec3(0.003, 0.003, 0.008);

  // Starfield background
  for (float i = 0.0; i < 80.0; i++) {
    vec2 star = vec2(hash(vec2(i, 2.0)), hash(vec2(2.0, i))) * 2.0 - 1.0;
    float sd = length(p - star);
    float twinkle = sin(time * 1.5 + i * 5.0) * 0.3 + 0.7;
    col += vec3(0.7, 0.75, 1.0) * exp(-sd * 250.0) * 0.08 * twinkle;
  }

  // Comets
  float numComets = 3.0 + uCometCount * 7.0;
  for (float i = 0.0; i < 10.0; i++) {
    if (i >= numComets) break;
    float id = i;

    // Comet trajectory
    float angle = hash(vec2(id, 7.0)) * 6.28 - 3.14;
    float cometSpeed = 0.3 + hash(vec2(id, 3.0)) * 0.4;
    vec2 dir = vec2(cos(angle), sin(angle));

    // Position cycling across screen
    float phase = fract(time * cometSpeed * 0.15 + hash(vec2(id, 1.0)));
    vec2 startPos = -dir * 1.5 + vec2(hash(vec2(id, 5.0)) - 0.5, hash(vec2(5.0, id)) - 0.5) * 0.8;
    vec2 cometPos = startPos + dir * phase * 4.0;

    // Beat-spawned acceleration
    cometPos += dir * beatVal * 0.2;

    // Nucleus
    float nucDist = length(p - cometPos);
    float nucleus = exp(-nucDist * 40.0);

    // Coma (fuzzy cloud around nucleus)
    float coma = exp(-nucDist * 12.0) * 0.5;

    // Color based on spectral centroid
    vec3 cometCol = mix(vec3(0.4, 0.7, 1.0), vec3(1.0, 0.8, 0.3), centroidVal);
    cometCol += vec3(0.1, 0.05, 0.0) * uPalette * 0.3;

    col += cometCol * nucleus * 2.5;
    col += cometCol * coma * 0.7;

    // Dust tail (curves away from "sun")
    float tailLen = uTailLength * (0.5 + energyVal * 0.5);
    vec2 tailDir = -dir; // Opposite to motion
    // Slight curve
    vec2 tailPerp = vec2(-tailDir.y, tailDir.x);

    for (float t = 0.0; t < 1.0; t += 0.02) {
      vec2 tailPos = cometPos + tailDir * t * tailLen;
      tailPos += tailPerp * sin(t * 3.0 + time * 2.0) * 0.05 * t;
      tailPos += vec2(noise(vec2(t * 5.0, id + time)) - 0.5) * 0.03 * t * uChaos;

      float td = length(p - tailPos);
      float tailGlow = exp(-td * (20.0 + t * 30.0)) * (1.0 - t);

      // Dust tail: yellowish
      vec3 dustCol = mix(vec3(0.8, 0.6, 0.3), vec3(0.5, 0.3, 0.1), t);
      col += dustCol * tailGlow * 0.25;
    }

    // Ion tail (straight, bluish)
    vec2 ionDir = vec2(1.0, 0.3); // Always points "away from sun"
    ionDir = normalize(ionDir);
    for (float t = 0.0; t < 1.0; t += 0.03) {
      vec2 ionPos = cometPos + ionDir * t * tailLen * 0.8;
      float id2 = length(p - ionPos);
      float ionTail = exp(-id2 * 40.0) * (1.0 - t) * uIonGlow;
      col += vec3(0.3, 0.5, 1.0) * ionTail * 0.2;
    }

    // Debris particles
    for (float d = 0.0; d < 10.0; d++) {
      float dPhase = fract(time * 0.5 + hash(vec2(id, d)) * 5.0);
      vec2 debrisPos = cometPos + tailDir * dPhase * tailLen * 0.5;
      debrisPos += vec2(hash(vec2(d, id)) - 0.5, hash(vec2(id * 3.0, d)) - 0.5) * 0.1 * dPhase;
      float dd = length(p - debrisPos);
      float debris = exp(-dd * 80.0) * (1.0 - dPhase) * uDebrisSparkle;
      col += vec3(1.0, 0.9, 0.7) * debris * trebleVal * 0.6;
    }
  }

  // Kick → meteor burst
  col = mix(col, col * 2.0 + vec3(0.05, 0.08, 0.12), kickVal * 0.5);

  // BPM ambient
  col += vec3(0.005, 0.005, 0.015) * max(bpm4, 0.0) * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCrackProgress;
uniform float uInnerRadiance;
uniform float uFragmentCount;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noise(p);
    p *= 2.1;
    amp *= 0.5;
  }
  return val;
}

// Voronoi for crack pattern
float voronoiCracks(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  float secondDist = 1.0;
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash(i + neighbor) * vec2(0.8, 0.8) + 0.1;
      // need a second hash for y
      point.y = hash(i + neighbor + 50.0) * 0.8 + 0.1;
      float d = length(f - neighbor - point);
      if (d < minDist) {
        secondDist = minDist;
        minDist = d;
      } else if (d < secondDist) {
        secondDist = d;
      }
    }
  }
  return secondDist - minDist;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Egg shape (elliptical SDF) — large, fills most of viewport
  vec2 eggP = p;
  eggP.y *= 0.8; // Slightly taller than wide
  float eggR = length(eggP);
  float eggDist = eggR - 1.2;

  // Egg shell surface
  float shellThick = 0.03;
  float onShell = smoothstep(shellThick, 0.0, abs(eggDist));
  float insideEgg = smoothstep(0.0, -shellThick, eggDist);

  // Crack pattern on shell
  float crackScale = 6.0 + trebleVal * 3.0;
  float cracks = voronoiCracks(p * crackScale + time * 0.1);
  float crackThreshold = uCrackProgress * (1.0 + beatPulse * 0.3);
  float crackMask = smoothstep(crackThreshold * 0.15, 0.0, cracks);

  // Shell color (pearlescent)
  float shellAngle = atan(p.y, p.x);
  float pearlescence = sin(shellAngle * 5.0 + eggR * 20.0 + time * 0.5) * 0.5 + 0.5;
  vec3 shellColor = mix(
    vec3(0.85, 0.8, 0.7),
    vec3(0.7, 0.75, 0.85),
    pearlescence
  );
  // Shell texture
  shellColor += noise(p * 30.0) * 0.05;
  shellColor *= onShell * (1.0 - crackMask * 0.8);

  // Inner radiance (visible through cracks and inside)
  float innerGlow = uInnerRadiance * (1.0 + bassVal * 1.0);
  float innerPulse = sin(time * 2.0 + eggR * 10.0) * 0.3 + 0.7;
  innerPulse *= innerGlow;

  // Inner energy swirl
  float swirlAngle = shellAngle + time * 2.2 + sin(eggR * 8.0 + time) * 0.7;
  float swirl = sin(swirlAngle * 3.0 + eggR * 15.0) * 0.5 + 0.5;
  swirl = pow(swirl, 2.0);

  float innerFbm = fbm(p * 4.0 + time * 0.3);
  float hueShift = uPalette * 0.5;
  vec3 innerColor = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.1, 0.2) + hueShift + innerFbm * 0.3));
  innerColor *= innerPulse * (0.8 + swirl * 0.4);

  // Inner light visible through cracks
  vec3 crackLight = innerColor * crackMask * onShell * 3.5;

  // Inner light for inside of egg
  vec3 insideLight = innerColor * insideEgg * 0.8;

  // Light rays emanating from cracks
  float rays = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float rayAngle = fi * 1.047 + time * 0.2 + sin(time * 0.5 + fi) * 0.3;
    vec2 rayDir = vec2(cos(rayAngle), sin(rayAngle));
    float rayDot = max(0.0, dot(normalize(p + 0.001), rayDir));
    float ray = pow(rayDot, 20.0) * crackThreshold;
    ray *= smoothstep(0.5, 0.8, eggR); // Only outside egg
    rays += ray;
  }
  vec3 rayColor = innerColor * rays * 0.8;

  // Floating shell fragments (kicked outward)
  float fragments = 0.0;
  int numFrags = 5 + int(uFragmentCount * 10.0);
  for (int i = 0; i < 15; i++) {
    if (i >= numFrags) break;
    float fi = float(i);
    float fragAngle = hash(vec2(fi, 0.0)) * 6.2832;
    float fragSpeed = 0.1 + hash(vec2(fi, 1.0)) * 0.3;
    float fragDist = 0.5 + fract(time * fragSpeed + fi * 0.1) * crackThreshold * 1.5;
    fragDist += kickPulse * 0.2;

    vec2 fragPos = vec2(cos(fragAngle), sin(fragAngle) * 0.8) * fragDist;
    float fragSize = 0.02 + hash(vec2(fi, 2.0)) * 0.03;
    // Rotation
    float fragRot = time * (1.0 + fi * 0.3);
    vec2 dp = p - fragPos;
    float fragCa = cos(fragRot);
    float fragSa = sin(fragRot);
    vec2 rotDp = vec2(dp.x * fragCa - dp.y * fragSa, dp.x * fragSa + dp.y * fragCa);
    // Triangular fragment shape approximation
    float fragShape = max(abs(rotDp.x), abs(rotDp.y) + abs(rotDp.x) * 0.5);
    float frag = smoothstep(fragSize, fragSize * 0.5, fragShape);
    frag *= crackThreshold; // Only visible when cracking
    fragments += frag;
  }
  vec3 fragColor = shellColor * 0.5 + vec3(0.3, 0.25, 0.2);
  fragColor *= fragments;

  // Background: cosmic void
  float bgNebula = fbm(p * 1.5 + time * 0.05);
  vec3 bgColor = vec3(0.02, 0.01, 0.04) + vec3(0.03, 0.01, 0.05) * bgNebula;

  // Stars
  float starGrid = 80.0;
  vec2 starUV = p * starGrid;
  vec2 starCell = floor(starUV);
  float starH = hash(starCell);
  if (starH > 0.96) {
    vec2 starF = fract(starUV) - 0.5;
    float starD = length(starF);
    bgColor += vec3(0.5, 0.6, 0.8) * exp(-starD * starD * 1000.0) * 0.3;
  }

  // Combine
  vec3 col = bgColor;
  col += insideLight;
  col += shellColor;
  col += crackLight;
  col += rayColor;
  col += fragColor;

  // Outer glow around egg
  float outerGlow = exp(-eggDist * eggDist * 10.0) * innerGlow * 0.2;
  col += innerColor * outerGlow;

  // Beat birth pulse
  col += vec3(0.4, 0.35, 0.2) * beatPulse * 0.3 * insideEgg;

  // Energy and intensity
  col *= (0.7 + uEnergy * uSensitivity * 0.8);
  col *= uIntensity * 1.6;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash22(vec2 p) {
  return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm4(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 4; i++) {
    v += a * noise2d(p);
    p = rot * p * 2.0 + vec2(5.3, 1.7);
    a *= 0.5;
  }
  return v;
}

// Multi-cell Voronoi returning distances + cell id
vec4 cosmicVoronoi(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float d1 = 10.0, d2 = 10.0;
  vec2 cell1 = vec2(0.0);
  vec2 nearestPt = vec2(0.0);
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 n = vec2(float(x), float(y));
      vec2 cellOff = hash22(i + n) * 0.75;
      vec2 pt = n + cellOff - f;
      float dist = dot(pt, pt);
      if (dist < d1) {
        d2 = d1;
        d1 = dist;
        cell1 = i + n;
        nearestPt = pt + f;
      } else if (dist < d2) {
        d2 = dist;
      }
    }
  }
  return vec4(sqrt(d1), sqrt(d2), hash21(cell1), hash21(cell1 + vec2(77.0, 33.0)));
}

vec3 cosmicPalette(float t, float shift) {
  // Gold / blue / white cosmic tones
  vec3 a = vec3(0.5, 0.4, 0.25);
  vec3 b = vec3(0.6, 0.55, 0.75);
  vec3 c = vec3(1.0, 0.85, 0.65);
  vec3 d = vec3(0.0, 0.2, 0.6);
  return a + b * cos(6.2832 * (c * (t + shift * 0.1) + d));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float harmonicityVal = uHarmonicity * uSensitivity;

  // Absolute void background
  vec3 col = vec3(0.002, 0.002, 0.008);

  // Subtle nebula background
  float nebula = fbm4(p * 0.5 + time * 0.01);
  col += vec3(0.01, 0.005, 0.02) * nebula;

  // Slow rotation for DMT hyperspace feel
  float rotAngle = time * 0.03 + uChaos * sin(time * 0.1) * 0.2;
  float cRot = cos(rotAngle);
  float sRot = sin(rotAngle);
  vec2 rp = mat2(cRot, -sRot, sRot, cRot) * p;

  // Multi-scale cosmic web
  float totalWeb = 0.0;
  vec3 webColor = vec3(0.0);

  for (float scale = 0.0; scale < 4.0; scale++) {
    float s = 2.5 + scale * 2.0;
    vec2 sp = rp * s + vec2(time * 0.05 * (1.0 + scale * 0.3), time * 0.03);

    vec4 v = cosmicVoronoi(sp);
    float edge = v.y - v.x;

    // Filaments along Voronoi edges
    float filWidth = 0.12 - scale * 0.015;
    float filament = smoothstep(filWidth, 0.0, edge);

    // Data pulses traveling along filaments
    float pulsePhase = noise2d(sp * 0.3 + vec2(time * 1.5, 0.0));
    float dataPulse = sin(pulsePhase * 18.85 + time * 5.0) * 0.5 + 0.5;
    dataPulse = dataPulse * dataPulse; // sharpen pulse
    float pulsingFilament = filament * (0.3 + dataPulse * 0.7 + bassVal * 1.0);

    // Galaxy cluster nodes
    float node = exp(-v.x * 10.0);
    float nodeFlicker = sin(time * 3.0 + v.z * 25.133) * 0.3 + 0.7;
    node *= nodeFlicker * (0.5 + midsVal * 1.0);

    // Scale color: gold (large scale) to blue (fine scale)
    float hue = scale * 0.25 + v.z * 0.1 + uPalette * 0.15 + time * 0.003;
    vec3 scaleCol = cosmicPalette(hue, uPalette);

    float layerFade = 1.0 / (scale + 1.0);
    totalWeb += (pulsingFilament + node * 1.2) * layerFade;
    webColor += scaleCol * (pulsingFilament + node * 1.5) * layerFade;

    // Void darkening inside cells
    float voidDark = smoothstep(0.0, 0.35, v.x);
    col *= 1.0 - voidDark * 0.05 * layerFade;
  }

  // Normalize and apply web
  webColor = totalWeb > 0.001 ? webColor / totalWeb : vec3(0.0);
  col += webColor * clamp(totalWeb * 0.5, 0.0, 1.0);

  // Bright galaxy cluster nodes at primary scale
  float primaryScale = 3.5;
  vec4 primaryV = cosmicVoronoi(rp * primaryScale);
  float clusterGlow = exp(-primaryV.x * 15.0);
  vec3 clusterCol = mix(
    vec3(1.0, 0.85, 0.5),   // warm gold
    vec3(0.5, 0.7, 1.0),     // cool blue
    primaryV.z
  );
  col += clusterCol * clusterGlow * 0.9 * (0.5 + midsVal * 1.0);

  // Gravitational lensing arcs near massive clusters
  for (float i = 0.0; i < 5.0; i++) {
    vec2 lensCenter = vec2(
      sin(i * 2.399 + time * 0.08) * 0.8,
      cos(i * 3.14159 * 0.7 + time * 0.06) * 0.6
    );
    float dist = length(rp - lensCenter);
    float arcR = 0.15 + sin(time * 0.2 + i * 1.5) * 0.05 + bassVal * 0.04;
    float arc = exp(-abs(dist - arcR) * 60.0);
    float arcAngle = atan(rp.y - lensCenter.y, rp.x - lensCenter.x);
    float arcMask = smoothstep(0.0, 0.6, sin(arcAngle * 2.0 + i * 2.0) * 0.5 + 0.5);
    col += vec3(0.4, 0.6, 1.0) * arc * arcMask * 0.3 * (0.5 + energyVal * 0.5);
  }

  // Individual galaxies: tiny sparkle points
  for (float i = 0.0; i < 60.0; i++) {
    vec2 galPos = vec2(
      hash21(vec2(i, 7.0)) * 4.0 - 2.0,
      hash21(vec2(7.0, i)) * 4.0 - 2.0
    );
    float galDist = length(rp - galPos);
    float galBright = exp(-galDist * 150.0) * 0.2;
    float galTwinkle = sin(time * 4.0 + i * 3.0) * 0.3 + 0.7;
    vec3 galCol = mix(vec3(1.0, 0.9, 0.6), vec3(0.4, 0.5, 1.0), hash21(vec2(i, 13.0)));
    col += galCol * galBright * galTwinkle * (0.5 + trebleVal * 0.5);
  }

  // DMT hyperspace geometry: sacred geometry overlay
  float sacred = 0.0;
  for (float i = 0.0; i < 6.0; i++) {
    float angle = i * 1.047197 + time * 0.05; // 60 degree increments
    vec2 lineDir = vec2(cos(angle), sin(angle));
    float lineDist = abs(dot(rp, vec2(-lineDir.y, lineDir.x)));
    sacred += exp(-lineDist * 30.0) * 0.05;
  }
  col += vec3(0.8, 0.7, 1.0) * sacred * harmonicityVal * 0.5;

  // Kick: void eruption
  col = mix(col, col * 2.2 + vec3(0.08, 0.06, 0.15), kickVal * 0.5);

  // Beat: network brightens
  col *= 1.0 + beatVal * 0.4;

  // Onset: white flash at web nodes
  col += vec3(0.08, 0.06, 0.12) * onsetVal * 0.4;

  // Spectral entropy: cosmic shimmer
  col += col * uSpectralEntropy * uSensitivity * 0.12;

  // BPM cosmic breath
  col *= 1.0 + uBpmSin * 0.05;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uHelixPitch;
uniform float uScaleDetail;
uniform float uUndulation;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === DOUBLE HELIX along the vertical axis ===
  // The helix is parameterized by vertical position
  // For each pixel, find distance to nearest point on each strand

  float serpentGlow1 = 0.0;
  float serpentGlow2 = 0.0;
  float rungGlow = 0.0;
  float scalePattern = 0.0;

  // Helix parameters — thick, prominent serpent
  float helixRadius = 0.35 + bassVal * 0.2;
  float rotSpeed = time * midsVal * 1.0 + time * 1.2;

  // Sample many points along the helix
  float bestDist1 = 100.0;
  float bestDist2 = 100.0;
  float bestT1 = 0.0;
  float bestT2 = 0.0;

  for (int i = 0; i < 60; i++) {
    float fi = float(i);
    float t = (fi / 60.0 - 0.5) * 3.0; // parameter along helix

    // Undulation of the central axis
    float axisX = sin(t * 2.0 + time * 0.75) * uUndulation * (1.0 + bassVal * 1.0);
    float axisY = t;

    // 3D helix projected to 2D
    float helixAngle = t * uHelixPitch + rotSpeed;
    float cosH = cos(helixAngle);
    float sinH = sin(helixAngle);

    // Strand 1
    float x1 = axisX + cosH * helixRadius;
    float y1 = axisY;
    // Depth for brightness modulation (z-component)
    float z1 = sinH * helixRadius;
    float depth1 = 0.7 + z1 * 0.3; // front brighter

    float d1 = length(p - vec2(x1, y1));
    if (d1 < bestDist1) {
      bestDist1 = d1;
      bestT1 = t;
    }

    // Strand 2 (180 degrees offset)
    float x2 = axisX + cos(helixAngle + 3.14159) * helixRadius;
    float y2 = axisY;
    float z2 = sin(helixAngle + 3.14159) * helixRadius;
    float depth2 = 0.7 + z2 * 0.3;

    float d2 = length(p - vec2(x2, y2));
    if (d2 < bestDist2) {
      bestDist2 = d2;
      bestT2 = t;
    }

    // Strand glow
    float thickness = 0.06 + beatPulse * 0.015;
    serpentGlow1 += exp(-d1 * d1 / (thickness * thickness)) * depth1 * 0.12;
    serpentGlow2 += exp(-d2 * d2 / (thickness * thickness)) * depth2 * 0.12;

    // === RUNGS between strands (base pairs) ===
    if (mod(fi, 6.0) < 1.0) {
      vec2 rungStart = vec2(x1, y1);
      vec2 rungEnd = vec2(x2, y2);
      // Closest point on rung line segment
      vec2 rungDir = rungEnd - rungStart;
      float rungLen = length(rungDir);
      vec2 rungNorm = rungDir / (rungLen + 0.001);
      float rungT = clamp(dot(p - rungStart, rungNorm), 0.0, rungLen);
      vec2 rungPoint = rungStart + rungNorm * rungT;
      float rungDist = length(p - rungPoint);
      float rungDepth = mix(depth1, depth2, rungT / (rungLen + 0.001));
      rungGlow += exp(-rungDist * rungDist * 300.0) * 0.4 * rungDepth;
    }
  }

  // === SERPENT COLORS ===
  // Strand 1: warm iridescent (greens, golds)
  vec3 color1 = 0.5 + 0.5 * cos(6.2832 * (bestT1 * 0.3 + uPalette * 0.1 + vec3(0.0, 0.15, 0.3)));
  color1 = mix(color1, vec3(0.25, 1.0, 0.5), 0.4); // green tint

  // Strand 2: cool iridescent (purples, blues)
  vec3 color2 = 0.5 + 0.5 * cos(6.2832 * (bestT2 * 0.3 + uPalette * 0.1 + 0.5 + vec3(0.0, 0.15, 0.3)));
  color2 = mix(color2, vec3(0.5, 0.25, 1.0), 0.4); // blue tint

  // === SCALE PATTERN ===
  // Near each strand, show scales
  if (bestDist1 < 0.1) {
    vec2 scaleUV = vec2(bestT1 * uScaleDetail, atan(p.y - bestT1, p.x) * uScaleDetail);
    float scaleH = hash(floor(scaleUV));
    float scaleBright = smoothstep(0.6, 0.4, fract(scaleUV.x)) * smoothstep(0.6, 0.4, fract(scaleUV.y));
    scalePattern += scaleBright * scaleH * trebleVal * 1.0;
  }
  if (bestDist2 < 0.1) {
    vec2 scaleUV = vec2(bestT2 * uScaleDetail, atan(p.y - bestT2, p.x) * uScaleDetail + 5.0);
    float scaleH = hash(floor(scaleUV));
    float scaleBright = smoothstep(0.6, 0.4, fract(scaleUV.x)) * smoothstep(0.6, 0.4, fract(scaleUV.y));
    scalePattern += scaleBright * scaleH * trebleVal * 1.0;
  }

  col += color1 * serpentGlow1;
  col += color2 * serpentGlow2;
  col += mix(color1, color2, 0.5) * rungGlow;
  col += vec3(0.9, 0.95, 1.0) * scalePattern;

  // === PHOSPHORESCENT PARTICLES trailing behind ===
  for (int i = 0; i < 30; i++) {
    float fi = float(i);
    float ph = hash(vec2(fi, fi * 0.7 + 1.0));
    float pt = fract(time * 0.3 + ph);
    float py = (pt - 0.5) * 3.0;
    float px = sin(py * uHelixPitch * 0.5 + time * 0.3 + fi * 1.3) * helixRadius * 1.5;
    px += sin(py * 2.0 + time * 0.5) * uUndulation;
    vec2 particlePos = vec2(px + (ph - 0.5) * 0.1, py);
    float d = length(p - particlePos);
    float particleGlow = exp(-d * d * 600.0) * 0.15 * (1.0 - pt);
    col += vec3(0.5 + ph * 0.5, 0.8, 0.4 + ph * 0.6) * particleGlow;
  }

  // === BACKGROUND: deep space with subtle nebula ===
  float bgNoise = noise(p * 3.0 + time * 0.1) * 0.04;
  col += vec3(0.01, 0.005, 0.02) + bgNoise * vec3(0.05, 0.02, 0.08);

  // Beat phosphorescent flash along strands
  col += (color1 * serpentGlow1 + color2 * serpentGlow2) * beatPulse * 4.0;

  // Onset flash
  col += vec3(0.5, 1.0, 0.7) * onsetFlash * 0.3;

  // Overall intensity — boosted for prominent serpent
  col *= uIntensity * 2.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCurvature;
uniform float uScanDensity;
uniform float uPhosphorDecay;
uniform float uFlickerRate;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

vec2 crtCurve(vec2 uv, float amount) {
  vec2 c = uv * 2.0 - 1.0;
  float r2 = dot(c, c);
  c *= 1.0 + r2 * amount * 0.15;
  return c * 0.5 + 0.5;
}

void main() {
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity * 1.4;

  // Apply CRT curvature
  vec2 uv = crtCurve(vUv, uCurvature);
  uv = psychedelicUV(uv); // breathing morph

  // Out of bounds = black border
  float inBounds = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);

  // === UNDERLYING PATTERN (burn-in content) ===
  float burnPattern = 0.0;
  // Circular burn marks
  for (float i = 0.0; i < 4.0; i++) {
    vec2 center = vec2(
      0.5 + sin(i * 1.7 + time * 0.2) * 0.3,
      0.5 + cos(i * 2.3 + time * 0.15) * 0.3
    );
    float d = length(uv - center);
    burnPattern += smoothstep(0.15 + midsVal * 0.05, 0.0, d) * 0.3;
  }
  // Text-like horizontal bands (burn-in)
  float textBurn = sin(uv.y * 20.0 + time * 0.1) * 0.5 + 0.5;
  textBurn *= smoothstep(0.2, 0.4, uv.x) * smoothstep(0.8, 0.6, uv.x);
  burnPattern += textBurn * 0.2;

  // Audio waveform display
  float wave = sin(uv.x * 25.0 + time * 3.0 + bassVal * 5.0) * 0.05 * (1.0 + midsVal);
  float waveDisplay = smoothstep(0.02, 0.0, abs(uv.y - 0.5 - wave));
  burnPattern += waveDisplay * 0.5;

  // Spectrum bars
  for (float i = 0.0; i < 8.0; i++) {
    float barX = (i + 0.5) / 8.0;
    float barH = 0.0;
    if (i < 1.0) barH = uSpectrum0;
    else if (i < 2.0) barH = uSpectrum1;
    else if (i < 3.0) barH = uSpectrum2;
    else if (i < 4.0) barH = uSpectrum3;
    else if (i < 5.0) barH = uSpectrum4;
    else if (i < 6.0) barH = uSpectrum5;
    else if (i < 7.0) barH = uSpectrum6;
    else barH = uSpectrum7;
    barH *= 0.4 * uSensitivity;
    float barMask = step(abs(uv.x - barX), 0.04) * step(uv.y, 0.15 + barH);
    burnPattern += barMask * 0.4;
  }

  burnPattern = clamp(burnPattern, 0.0, 1.0);

  // === PHOSPHOR COLOR ===
  // Green <-> Amber based on spectral centroid and palette
  float phosphorMode = clamp(uSpectralCentroid * 2.0 + uPalette * 0.5, 0.0, 1.0);
  vec3 greenPhosphor = vec3(0.1, 1.0, 0.3);
  vec3 amberPhosphor = vec3(1.0, 0.7, 0.1);
  vec3 phosphorColor = mix(greenPhosphor, amberPhosphor, phosphorMode);

  // Phosphor glow with decay trail
  float glow = burnPattern * (0.5 + uPhosphorDecay * 0.5);
  float halo = burnPattern * 0.3;
  vec3 phosphor = phosphorColor * glow;
  // Bloom halo
  phosphor += phosphorColor * halo * 0.4;

  // === SCAN LINES ===
  float scanY = uv.y * uScanDensity;
  float scanLine = sin(scanY * 3.14159) * 0.5 + 0.5;
  scanLine = pow(scanLine, 0.5);
  float scanBright = 0.6 + scanLine * 0.4;

  // Active scan beam
  float scanBeam = fract(time * 0.5);
  float beamDist = abs(uv.y - scanBeam);
  float beam = exp(-beamDist * 20.0) * 0.3;

  // === SCREEN FLICKER ===
  float flicker = 1.0 - bassVal * uFlickerRate * 0.15 * sin(time * 60.0);
  float staticNoise = noise(uv * 200.0 + time * 10.0) * kickVal * 0.2;

  // === RGB SUBPIXEL SEPARATION ===
  float subpixelX = fract(uv.x * uScanDensity * 0.33);
  vec3 subpixel = vec3(
    step(subpixelX, 0.33),
    step(0.33, subpixelX) * step(subpixelX, 0.66),
    step(0.66, subpixelX)
  );
  subpixel = mix(vec3(1.0), subpixel, 0.3);

  // === VIGNETTE (CRT edge darkening) ===
  vec2 vigUV = uv * 2.0 - 1.0;
  float vignette = 1.0 - dot(vigUV, vigUV) * 0.3;

  // === COMPOSITE ===
  vec3 col = phosphor * scanBright;
  col += beam * phosphorColor;
  col += staticNoise;
  col *= subpixel;
  col *= flicker;
  col *= vignette;
  col *= inBounds;

  // Edge glow (CRT bezel light leak)
  float edgeDist = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
  float edgeGlow = smoothstep(0.05, 0.0, edgeDist) * 0.15;
  col += edgeGlow * phosphorColor * inBounds;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRoadWidth;
uniform float uScrollSpeed;
uniform float uPalmCount;
uniform float uSunSize;

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  vec2 rawUv = vUv;
  float time = uTime * (uSpeed * 2.0);

  // Audio-reactive modulators
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kick = uKick * uSensitivity;
  float energy = uEnergy * uSensitivity;

  // Effective scroll time
  float scrollTime = time * uScrollSpeed * (1.0 + energy * 0.5);

  // Horizon line
  float horizonY = 0.45;

  // Bass-reactive road shake
  float roadShake = bassVal * 0.015 * sin(time * 8.0);
  float cx = rawUv.x - 0.5 - roadShake;

  // === SKY ===
  float skyT = smoothstep(horizonY, 1.0, rawUv.y);

  float horizonColorR = 0.95;
  float horizonColorG = 0.3;
  float horizonColorB = 0.05;
  float zenithColorR = 0.08 + uPalette * 0.02;
  float zenithColorG = 0.02;
  float zenithColorB = 0.2 + uPalette * 0.03;

  float skyR = mix(horizonColorR, zenithColorR, skyT);
  float skyG = mix(horizonColorG, zenithColorG, skyT);
  float skyB = mix(horizonColorB, zenithColorB, skyT);

  // === SUN ===
  float sunCenterX = 0.0;
  float sunCenterY = horizonY + 0.02;
  float sunDx = cx - sunCenterX;
  float sunDy = rawUv.y - sunCenterY;
  float sunDist = pow(sunDx * sunDx + sunDy * sunDy, 0.5);

  float sunRadius = uSunSize * (1.0 + beatPulse * 0.15);
  float sunDisc = smoothstep(sunRadius, sunRadius - 0.01, sunDist);

  float sunLineFreq = 40.0;
  float sunLinePhase = rawUv.y * sunLineFreq;
  float sunLine = step(0.5, fract(sunLinePhase)) * 0.3;
  float sunLowerHalf = smoothstep(sunCenterY, sunCenterY - sunRadius, rawUv.y);
  float sunWithLines = sunDisc * (1.0 - sunLine * sunLowerHalf);

  float sunGlow = smoothstep(sunRadius * 2.5, sunRadius, sunDist) * 0.3;
  float sunR = sunWithLines * 1.0 + sunGlow * 0.9;
  float sunG = sunWithLines * 0.7 + sunGlow * 0.3;
  float sunB = sunWithLines * 0.1 + sunGlow * 0.05;

  float aboveHorizon = smoothstep(horizonY - 0.01, horizonY + 0.01, rawUv.y);
  float skyFinalR = (skyR + sunR) * aboveHorizon * uIntensity;
  float skyFinalG = (skyG + sunG) * aboveHorizon * uIntensity;
  float skyFinalB = (skyB + sunB) * aboveHorizon * uIntensity;

  // === GROUND / ROAD ===
  float belowHorizon = 1.0 - aboveHorizon;
  float rawDepth = horizonY - rawUv.y + 0.001;
  float depth = 1.0 / (rawDepth * 10.0 + 0.1);

  float perspRoadWidth = uRoadWidth / (depth * 0.3 + 1.0);
  float onRoad = smoothstep(perspRoadWidth + 0.005, perspRoadWidth, abs(cx));
  float roadMask = 1.0 - onRoad;

  // Road stripes
  float stripeFreq = 8.0;
  float stripePhase = fract(depth * stripeFreq - scrollTime * 0.5);
  float stripeToggle = step(0.5, stripePhase);

  float kickFlash = kick * 0.15;

  float roadDarkR = 0.12 + kickFlash;
  float roadDarkG = 0.12 + kickFlash;
  float roadDarkB = 0.14 + kickFlash;
  float roadLightR = 0.18 + kickFlash;
  float roadLightG = 0.18 + kickFlash;
  float roadLightB = 0.20 + kickFlash;

  float roadBaseR = mix(roadDarkR, roadLightR, stripeToggle);
  float roadBaseG = mix(roadDarkG, roadLightG, stripeToggle);
  float roadBaseB = mix(roadDarkB, roadLightB, stripeToggle);

  // Center dashed line
  float centerLineWidth = 0.005 / (depth * 0.2 + 1.0);
  float centerLineMask = smoothstep(centerLineWidth, centerLineWidth * 0.5, abs(cx));
  float dashPhase = fract(depth * 15.0 - scrollTime);
  float dashOn = step(0.5, dashPhase);
  float centerLine = (1.0 - centerLineMask) * dashOn;

  // Edge lines
  float edgeLineWidth = 0.004 / (depth * 0.2 + 1.0);
  float edgePos = perspRoadWidth - edgeLineWidth;
  float leftEdge = smoothstep(edgeLineWidth, edgeLineWidth * 0.3, abs(cx - (-edgePos)));
  float rightEdge = smoothstep(edgeLineWidth, edgeLineWidth * 0.3, abs(cx - edgePos));
  float edgeLineMask = (1.0 - leftEdge) + (1.0 - rightEdge);

  float linesBright = (centerLine + edgeLineMask) * 0.8 * uIntensity;

  float roadR = roadBaseR + linesBright * 1.0;
  float roadG = roadBaseG + linesBright * 0.9;
  float roadB = roadBaseB + linesBright * 0.2;

  // Ground (off-road)
  float groundStripePhase = fract(depth * stripeFreq - scrollTime * 0.5);
  float groundStripeToggle = step(0.5, groundStripePhase);

  float groundR = mix(0.08, 0.1, groundStripeToggle);
  float groundG = mix(0.15, 0.2, groundStripeToggle);
  float groundB = mix(0.05, 0.07, groundStripeToggle);

  float surfaceR = mix(groundR, roadR, roadMask);
  float surfaceG = mix(groundG, roadG, roadMask);
  float surfaceB = mix(groundB, roadB, roadMask);

  // Fog near horizon
  float fogFactor = smoothstep(0.0, 0.08, rawDepth);
  float foggedR = mix(0.6, surfaceR, fogFactor);
  float foggedG = mix(0.25, surfaceG, fogFactor);
  float foggedB = mix(0.1, surfaceB, fogFactor);

  float groundFinalR = foggedR * belowHorizon * uIntensity;
  float groundFinalG = foggedG * belowHorizon * uIntensity;
  float groundFinalB = foggedB * belowHorizon * uIntensity;

  // === TELEPHONE POLES (rushing toward viewer) ===
  float poleSilhouette = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    // Poles repeat along the road at regular intervals
    float polePhase = fract(fi * 0.166 - scrollTime * 0.04);
    float poleDepthFactor = polePhase * 3.0 + 0.3;
    float poleScale = 1.0 / (poleDepthFactor * 0.5 + 0.3);
    float poleSide = mod(fi, 2.0) < 1.0 ? 1.0 : -1.0;
    float poleX = poleSide * (perspRoadWidth + 0.02 * poleScale);
    float poleY = horizonY - polePhase * 0.35;

    // Pole trunk: thin vertical rectangle
    float poleTrunkW = 0.003 * poleScale;
    float poleTrunkH = 0.08 * poleScale;
    float poleTrunkBottom = poleY;
    float poleTrunkTop = poleY + poleTrunkH;
    float poleTrunkMask = step(abs(cx - poleX), poleTrunkW)
      * step(poleTrunkBottom, rawUv.y) * step(rawUv.y, poleTrunkTop);

    // Crossbar at top
    float crossbarW = 0.015 * poleScale;
    float crossbarH = 0.002 * poleScale;
    float crossbarY = poleTrunkTop - 0.005 * poleScale;
    float crossbarMask = step(abs(cx - poleX), crossbarW)
      * step(abs(rawUv.y - crossbarY), crossbarH);

    // Wires drooping from crossbar (catenary curve)
    float wireY = crossbarY - 0.003 * poleScale * (1.0 + pow((cx - poleX) / (crossbarW + 0.001), 2.0) * 0.5);
    float wireMask = step(abs(rawUv.y - wireY), 0.001) * step(abs(cx - poleX), crossbarW * 1.5);

    float poleMask = max(max(poleTrunkMask, crossbarMask), wireMask);
    poleMask *= (polePhase + 0.2); // fade based on distance
    poleSilhouette = max(poleSilhouette, poleMask);
  }

  // === ONCOMING CARS ===
  float carColor_r = 0.0;
  float carColor_g = 0.0;
  float carColor_b = 0.0;
  float carMaskTotal = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float carSeed = fi * 3.7 + 1.0;

    // Car position: approaches from horizon, grows as it nears
    float carPhase = fract(carSeed * 0.13 - scrollTime * 0.06);
    float carDepthFactor = carPhase * 2.5 + 0.2;
    float carScale = 1.0 / (carDepthFactor * 0.4 + 0.3);

    // Lane position: cars in other lane (shifted to one side)
    float carLane = -0.06 - fi * 0.02;
    float carPerspX = carLane / (carDepthFactor * 0.3 + 1.0);
    float carY = horizonY - carPhase * 0.35;

    // Car body: rectangle that grows as it approaches
    float carW = 0.015 * carScale;
    float carH = 0.008 * carScale;
    float carMask = step(abs(cx - carPerspX - roadShake), carW)
      * step(abs(rawUv.y - carY), carH)
      * belowHorizon * onRoad;
    carMask *= smoothstep(0.0, 0.15, carPhase); // fade in from horizon

    // Per-car color from hash
    float carHue = fract(carSeed * 0.37);
    float cr = abs(fract(carHue + 0.0) * 6.0 - 3.0) - 1.0;
    float cg = abs(fract(carHue + 0.333) * 6.0 - 3.0) - 1.0;
    float cb = abs(fract(carHue + 0.666) * 6.0 - 3.0) - 1.0;
    cr = clamp(cr * 0.8 + 0.2, 0.0, 1.0);
    cg = clamp(cg * 0.8 + 0.2, 0.0, 1.0);
    cb = clamp(cb * 0.8 + 0.2, 0.0, 1.0);

    // Headlights (small bright spots at front)
    float hlY = carY + carH * 0.7;
    float hlDist1 = length(vec2(cx - carPerspX - roadShake - carW * 0.5, rawUv.y - hlY));
    float hlDist2 = length(vec2(cx - carPerspX - roadShake + carW * 0.5, rawUv.y - hlY));
    float headlight = (exp(-hlDist1 * hlDist1 * 8000.0) + exp(-hlDist2 * hlDist2 * 8000.0)) * carScale * 0.3;
    headlight *= belowHorizon;

    carColor_r += carMask * cr + headlight * 1.0;
    carColor_g += carMask * cg + headlight * 0.95;
    carColor_b += carMask * cb + headlight * 0.7;
    carMaskTotal = max(carMaskTotal, carMask);
  }

  // === PALM TREE SILHOUETTES ===
  // Palm tree 0
  float palm0Scroll = fract(0.05 * 3.0 - scrollTime * 0.02);
  float palm0Y = horizonY - palm0Scroll * 0.3;
  float palm0X = 1.0 * (uRoadWidth * 0.6 + 0.05) / (palm0Scroll * 2.0 + 0.5);
  float palm0Scale = 0.03 / (palm0Scroll + 0.3);
  float palm0TrunkDx = abs(cx - palm0X);
  float palm0TrunkW = palm0Scale * 0.1;
  float palm0TrunkH = palm0Scale * 1.5;
  float palm0TrunkBottom = palm0Y;
  float palm0TrunkTop = palm0Y + palm0TrunkH;
  float palm0TrunkMaskY = smoothstep(palm0TrunkBottom, palm0TrunkBottom + 0.005, rawUv.y)
    * smoothstep(palm0TrunkTop, palm0TrunkTop - 0.005, rawUv.y);
  float palm0TrunkMaskX = smoothstep(palm0TrunkW, palm0TrunkW * 0.3, palm0TrunkDx);
  float palm0Trunk = palm0TrunkMaskX * palm0TrunkMaskY;

  float palm0FrondCx = cx - palm0X;
  float palm0FrondCy = rawUv.y - palm0TrunkTop;
  float palm0F0Angle = palm0FrondCy - palm0FrondCx * 0.8 + palm0FrondCx * palm0FrondCx * 3.0;
  float palm0F0 = smoothstep(palm0Scale * 0.15, 0.0, abs(palm0F0Angle))
    * step(0.0, palm0FrondCx)
    * smoothstep(palm0Scale * 1.2, 0.0, abs(palm0FrondCx));
  float palm0F1Angle = palm0FrondCy + palm0FrondCx * 0.8 + palm0FrondCx * palm0FrondCx * 3.0;
  float palm0F1 = smoothstep(palm0Scale * 0.15, 0.0, abs(palm0F1Angle))
    * step(0.0, -palm0FrondCx)
    * smoothstep(palm0Scale * 1.2, 0.0, abs(palm0FrondCx));
  float palm0F2Angle = palm0FrondCy - palm0FrondCx * 0.3 + palm0FrondCx * palm0FrondCx * 4.0;
  float palm0F2 = smoothstep(palm0Scale * 0.12, 0.0, abs(palm0F2Angle))
    * step(0.0, palm0FrondCx)
    * smoothstep(palm0Scale * 1.4, 0.0, abs(palm0FrondCx));
  float palm0F3Angle = palm0FrondCy + palm0FrondCx * 0.3 + palm0FrondCx * palm0FrondCx * 4.0;
  float palm0F3 = smoothstep(palm0Scale * 0.12, 0.0, abs(palm0F3Angle))
    * step(0.0, -palm0FrondCx)
    * smoothstep(palm0Scale * 1.4, 0.0, abs(palm0FrondCx));
  float palm0Fronds = max(max(palm0F0, palm0F1), max(palm0F2, palm0F3));
  float palm0Silhouette = max(palm0Trunk, palm0Fronds) * (palm0Scroll + 0.3);

  // Palm tree 1
  float palm1Scroll = fract(0.4 + (-scrollTime * 0.025));
  float palm1Y = horizonY - palm1Scroll * 0.3;
  float palm1X = -1.0 * (uRoadWidth * 0.7 + 0.1) / (palm1Scroll * 2.0 + 0.5);
  float palm1Scale = 0.03 / (palm1Scroll + 0.3);
  float palm1TrunkDx = abs(cx - palm1X);
  float palm1TrunkW = palm1Scale * 0.1;
  float palm1TrunkH = palm1Scale * 1.3;
  float palm1TrunkBottom = palm1Y;
  float palm1TrunkTop = palm1Y + palm1TrunkH;
  float palm1TrunkMaskY = smoothstep(palm1TrunkBottom, palm1TrunkBottom + 0.005, rawUv.y)
    * smoothstep(palm1TrunkTop, palm1TrunkTop - 0.005, rawUv.y);
  float palm1TrunkMaskX = smoothstep(palm1TrunkW, palm1TrunkW * 0.3, palm1TrunkDx);
  float palm1Trunk = palm1TrunkMaskX * palm1TrunkMaskY;
  float palm1FrondCx = cx - palm1X;
  float palm1FrondCy = rawUv.y - palm1TrunkTop;
  float palm1F0Angle = palm1FrondCy - palm1FrondCx * 0.7 + palm1FrondCx * palm1FrondCx * 3.5;
  float palm1F0 = smoothstep(palm1Scale * 0.15, 0.0, abs(palm1F0Angle))
    * step(0.0, palm1FrondCx)
    * smoothstep(palm1Scale * 1.2, 0.0, abs(palm1FrondCx));
  float palm1F1Angle = palm1FrondCy + palm1FrondCx * 0.7 + palm1FrondCx * palm1FrondCx * 3.5;
  float palm1F1 = smoothstep(palm1Scale * 0.15, 0.0, abs(palm1F1Angle))
    * step(0.0, -palm1FrondCx)
    * smoothstep(palm1Scale * 1.2, 0.0, abs(palm1FrondCx));
  float palm1F2Angle = palm1FrondCy - palm1FrondCx * 0.4 + palm1FrondCx * palm1FrondCx * 4.0;
  float palm1F2 = smoothstep(palm1Scale * 0.12, 0.0, abs(palm1F2Angle))
    * step(0.0, palm1FrondCx)
    * smoothstep(palm1Scale * 1.4, 0.0, abs(palm1FrondCx));
  float palm1F3Angle = palm1FrondCy + palm1FrondCx * 0.4 + palm1FrondCx * palm1FrondCx * 4.0;
  float palm1F3 = smoothstep(palm1Scale * 0.12, 0.0, abs(palm1F3Angle))
    * step(0.0, -palm1FrondCx)
    * smoothstep(palm1Scale * 1.4, 0.0, abs(palm1FrondCx));
  float palm1Fronds = max(max(palm1F0, palm1F1), max(palm1F2, palm1F3));
  float palm1Silhouette = max(palm1Trunk, palm1Fronds) * (palm1Scroll + 0.3);

  // Palm tree 2
  float palm2Scroll = fract(0.7 + (-scrollTime * 0.018));
  float palm2Y = horizonY - palm2Scroll * 0.3;
  float palm2X = 1.0 * (uRoadWidth * 0.8 + 0.12) / (palm2Scroll * 2.0 + 0.5);
  float palm2Scale = 0.025 / (palm2Scroll + 0.3);
  float palm2TrunkDx = abs(cx - palm2X);
  float palm2TrunkW = palm2Scale * 0.1;
  float palm2TrunkH = palm2Scale * 1.4;
  float palm2TrunkBottom = palm2Y;
  float palm2TrunkTop = palm2Y + palm2TrunkH;
  float palm2TrunkMaskY = smoothstep(palm2TrunkBottom, palm2TrunkBottom + 0.005, rawUv.y)
    * smoothstep(palm2TrunkTop, palm2TrunkTop - 0.005, rawUv.y);
  float palm2TrunkMaskX = smoothstep(palm2TrunkW, palm2TrunkW * 0.3, palm2TrunkDx);
  float palm2Trunk = palm2TrunkMaskX * palm2TrunkMaskY;
  float palm2FrondCx = cx - palm2X;
  float palm2FrondCy = rawUv.y - palm2TrunkTop;
  float palm2F0Angle = palm2FrondCy - palm2FrondCx * 0.75 + palm2FrondCx * palm2FrondCx * 3.0;
  float palm2F0 = smoothstep(palm2Scale * 0.14, 0.0, abs(palm2F0Angle))
    * step(0.0, palm2FrondCx)
    * smoothstep(palm2Scale * 1.3, 0.0, abs(palm2FrondCx));
  float palm2F1Angle = palm2FrondCy + palm2FrondCx * 0.75 + palm2FrondCx * palm2FrondCx * 3.0;
  float palm2F1 = smoothstep(palm2Scale * 0.14, 0.0, abs(palm2F1Angle))
    * step(0.0, -palm2FrondCx)
    * smoothstep(palm2Scale * 1.3, 0.0, abs(palm2FrondCx));
  float palm2F2Angle = palm2FrondCy - palm2FrondCx * 0.35 + palm2FrondCx * palm2FrondCx * 3.8;
  float palm2F2 = smoothstep(palm2Scale * 0.12, 0.0, abs(palm2F2Angle))
    * step(0.0, palm2FrondCx)
    * smoothstep(palm2Scale * 1.5, 0.0, abs(palm2FrondCx));
  float palm2F3Angle = palm2FrondCy + palm2FrondCx * 0.35 + palm2FrondCx * palm2FrondCx * 3.8;
  float palm2F3 = smoothstep(palm2Scale * 0.12, 0.0, abs(palm2F3Angle))
    * step(0.0, -palm2FrondCx)
    * smoothstep(palm2Scale * 1.5, 0.0, abs(palm2FrondCx));
  float palm2Fronds = max(max(palm2F0, palm2F1), max(palm2F2, palm2F3));
  float palm2Silhouette = max(palm2Trunk, palm2Fronds) * (palm2Scroll + 0.3);

  float allPalms = max(max(palm0Silhouette, palm1Silhouette), palm2Silhouette);
  float palmVis = clamp(allPalms, 0.0, 1.0);

  // === FINAL COMPOSITION ===
  float compositeR = skyFinalR + groundFinalR;
  float compositeG = skyFinalG + groundFinalG;
  float compositeB = skyFinalB + groundFinalB;

  // Apply telephone pole silhouettes
  float poleDarken = 1.0 - clamp(poleSilhouette, 0.0, 1.0) * 0.9;
  compositeR *= poleDarken;
  compositeG *= poleDarken;
  compositeB *= poleDarken;

  // Apply car colors (overlay onto road)
  compositeR = mix(compositeR, carColor_r, clamp(carMaskTotal, 0.0, 1.0));
  compositeG = mix(compositeG, carColor_g, clamp(carMaskTotal, 0.0, 1.0));
  compositeB = mix(compositeB, carColor_b, clamp(carMaskTotal, 0.0, 1.0));
  // Add car headlights as additive glow
  compositeR += carColor_r * (1.0 - carMaskTotal);
  compositeG += carColor_g * (1.0 - carMaskTotal);
  compositeB += carColor_b * (1.0 - carMaskTotal);

  float palmDarken = 1.0 - palmVis * 0.85;
  float withPalmsR = compositeR * palmDarken;
  float withPalmsG = compositeG * palmDarken;
  float withPalmsB = compositeB * palmDarken;

  float hazeAmount = midsVal * 0.08 * smoothstep(0.1, 0.0, abs(rawUv.y - horizonY));

  float scanLine = sin(rawUv.y * 400.0) * 0.5 + 0.5;
  float scanEffect = 1.0 - scanLine * uChaos * 0.06;

  float sparkle = trebleVal * 0.1 * linesBright * roadMask * belowHorizon;

  float finalR = (withPalmsR + hazeAmount * 0.3 + sparkle) * scanEffect;
  float finalG = (withPalmsG + hazeAmount * 0.1 + sparkle * 0.5) * scanEffect;
  float finalB = (withPalmsB + hazeAmount * 0.5 + sparkle * 0.2) * scanEffect;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFacetSize;
uniform float uRefractionIndex;
uniform float uCrystalColor;
uniform float uLightDepth;

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Voronoi for crystal facets — returns vec3(distance, cellX, cellY)
vec3 voronoi(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  vec2 minCell = vec2(0.0);
  float minEdge = 1.0;
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      float d = dot(diff, diff);
      if (d < minDist) {
        minDist = d;
        minCell = i + neighbor;
      }
    }
  }
  // Edge distance
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      if (dot(diff, diff) > 0.0001) {
        vec2 midpoint = (diff + (hash2(minCell) + minCell - i - f)) * 0.5;
        float edgeDist = dot(midpoint, normalize(diff - (hash2(minCell) + minCell - i - f)));
        minEdge = min(minEdge, abs(edgeDist));
      }
    }
  }
  return vec3(sqrt(minDist), minCell);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.6;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Crystal facet grid via Voronoi
  float facetScale = 3.0 + (1.0 - uFacetSize) * 6.0;
  vec3 vor = voronoi(p * facetScale);
  float cellDist = vor.x;
  vec2 cellId = vor.yz;
  float cellHash = hash(cellId);

  // Facet edge detection
  // Approximate edge from gradient
  float eps = 0.01;
  vec3 vorR = voronoi((p + vec2(eps, 0.0)) * facetScale);
  vec3 vorU = voronoi((p + vec2(0.0, eps)) * facetScale);
  float edgeX = abs(vorR.x - vor.x) / eps;
  float edgeY = abs(vorU.x - vor.x) / eps;
  float edge = edgeX + edgeY;
  float edgeLine = smoothstep(1.5, 3.0, edge);

  // Crystal surface normal approximation per facet
  float facetAngle = cellHash * 6.28;
  float facetTilt = (hash(cellId + 100.0) - 0.5) * 0.8;
  vec2 facetNormal = vec2(cos(facetAngle), sin(facetAngle)) * facetTilt;

  // Internal light source — dynamic orbiting, pulsing with bass
  float lightOrbitA = time * 1.8 + sin(time * 0.7) * 0.5;
  float lightOrbitR = 0.3 + sin(time * 0.9) * 0.15 + bassVal * 0.1;
  vec2 lightPos = vec2(sin(lightOrbitA) * lightOrbitR, cos(lightOrbitA * 0.7 + 1.0) * lightOrbitR);
  lightPos *= uLightDepth;
  float lightDist = length(p - lightPos);
  float internalLight = exp(-lightDist * lightDist * 2.0) * (0.5 + bassVal * 1.1);

  // Second light source — faster, elliptical orbit
  float lightOrbitB = time * 2.5 + 3.0 + cos(time * 1.1) * 0.4;
  float lightOrbitR2 = 0.4 + cos(time * 1.3) * 0.12 + midsVal * 0.08;
  vec2 lightPos2 = vec2(cos(lightOrbitB) * lightOrbitR2, sin(lightOrbitB * 1.3 + 2.0) * lightOrbitR2 * 0.8);
  lightPos2 *= uLightDepth;
  float lightDist2 = length(p - lightPos2);
  float internalLight2 = exp(-lightDist2 * lightDist2 * 2.5) * (0.3 + bassVal * 0.5);

  // Third light source — slow drift with audio reactivity
  float lightOrbitC = time * 1.2 + 5.5 + sin(time * 0.5) * 0.8;
  vec2 lightPos3 = vec2(sin(lightOrbitC * 0.6) * 0.35, cos(lightOrbitC) * 0.25 + sin(time * 1.7) * 0.1);
  lightPos3 *= uLightDepth;
  float lightDist3 = length(p - lightPos3);
  float internalLight3 = exp(-lightDist3 * lightDist3 * 3.0) * (0.25 + trebleVal * 0.4);

  // Refraction: offset UV per facet based on "normal" and light direction
  vec2 refractOffset = facetNormal * uRefractionIndex * 0.1;
  float refractedLight = exp(-length(p + refractOffset - lightPos) * 2.0) * 0.5;
  float refractedLight2 = exp(-length(p + refractOffset - lightPos2) * 2.5) * 0.3;
  float refractedLight3 = exp(-length(p + refractOffset - lightPos3) * 2.0) * 0.35;

  // Prismatic rainbow on edges — treble enhances
  float rainbow = edgeLine * (0.3 + trebleVal * 0.5);
  float hue = fract(cellHash + time * 0.1 + dot(p, vec2(0.5, 0.3)));
  // HSV to RGB for rainbow
  vec3 rainbowColor;
  {
    float h = hue * 6.0;
    float f = fract(h);
    float q = 1.0 - f;
    int hi = int(floor(h));
    if (hi == 0) rainbowColor = vec3(1.0, f, 0.0);
    else if (hi == 1) rainbowColor = vec3(q, 1.0, 0.0);
    else if (hi == 2) rainbowColor = vec3(0.0, 1.0, f);
    else if (hi == 3) rainbowColor = vec3(0.0, q, 1.0);
    else if (hi == 4) rainbowColor = vec3(f, 0.0, 1.0);
    else rainbowColor = vec3(1.0, 0.0, q);
  }
  rainbowColor *= rainbow;

  // Crystal body color — amethyst/quartz/citrine
  vec3 amethyst = vec3(0.5, 0.18, 0.7);
  vec3 quartz = vec3(0.8, 0.72, 0.85);
  vec3 citrine = vec3(0.9, 0.7, 0.2);
  float crystalMix = uCrystalColor + midsVal * 0.3 + uPalette * 0.1;
  vec3 baseColor = mix(amethyst, quartz, smoothstep(0.0, 0.5, crystalMix));
  baseColor = mix(baseColor, citrine, smoothstep(0.5, 1.0, crystalMix));

  // Per-facet color variation
  baseColor *= 0.7 + cellHash * 0.5;

  // Lighting on crystal surface
  float surfaceLight = internalLight + internalLight2 + internalLight3 + refractedLight + refractedLight2 + refractedLight3;
  surfaceLight += 0.05; // ambient

  // Facet highlight — specular-like based on normal alignment with light
  float spec = pow(max(dot(normalize(lightPos - p), normalize(facetNormal)), 0.0), 8.0);
  float spec2 = pow(max(dot(normalize(lightPos2 - p), normalize(facetNormal)), 0.0), 6.0);
  float spec3 = pow(max(dot(normalize(lightPos3 - p), normalize(facetNormal)), 0.0), 7.0);
  float specular = (spec + spec2 + spec3) * 0.4;

  // Deep glow on onset
  float deepGlow = onsetFlash * exp(-length(p) * 1.5) * 0.8;
  vec3 deepGlowColor = baseColor * deepGlow;

  // Combine
  vec3 finalColor = baseColor * surfaceLight * uIntensity;
  finalColor += rainbowColor * 0.4;
  finalColor += vec3(1.0, 0.95, 0.9) * specular * 0.6;
  finalColor += vec3(0.2, 0.15, 0.3) * edgeLine * 0.3;
  finalColor += deepGlowColor;
  // Beat light burst
  finalColor += vec3(0.8, 0.7, 1.0) * beatPulse * exp(-lightDist * 3.0) * 0.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCrystalSharpness;
uniform float uRefractionIndex;
uniform float uIridescenceStrength;

// Iridescent palette: view angle drives rainbow cycling
vec3 iridescencePalette(float angle, float offset, float strength) {
  float tau = 6.28318;
  float t = angle * strength + offset * 0.1;
  float r = 0.5 + 0.5 * cos(tau * (1.0 * t + 0.0));
  float g = 0.5 + 0.5 * cos(tau * (1.0 * t + 0.33));
  float b = 0.5 + 0.5 * cos(tau * (1.0 * t + 0.67));
  return vec3(r, g, b);
}

// Crystal cavern SDF: sphere inversion + hexagonal fold + sharp box fold.
// Returns vec3(distance, trapColor, facetIndex).
vec3 crystalSDF(vec3 pos, float time, float bassVal, float sharpness) {
  float px = pos.x;
  float py = pos.y;
  float pz = pos.z;
  float trap = 100.0;

  // Sphere inversion
  float r2 = px * px + py * py + pz * pz;
  float invRadius = 2.0 + bassVal * 0.5;
  float invScale = invRadius * invRadius / max(r2, 0.001);
  px *= invScale;
  py *= invScale;
  pz *= invScale;

  // Hexagonal symmetry fold (60 degrees)
  float hex_nx = 0.866;
  float hex_ny = 0.5;
  float hexDot = px * hex_nx + py * hex_ny;
  float hexReflect = min(hexDot, 0.0) * 2.0;
  px -= hex_nx * hexReflect;
  py -= hex_ny * hexReflect;

  // Second hex fold at 120 degrees
  float hex2_nx = 0.866;
  float hex2_ny = -0.5;
  float hexDot2 = px * hex2_nx + py * hex2_ny;
  float hexReflect2 = min(hexDot2, 0.0) * 2.0;
  px -= hex2_nx * hexReflect2;
  py -= hex2_ny * hexReflect2;

  // Crystal fold iteration 1
  px = abs(px) - sharpness * 0.5;
  py = abs(py) - sharpness * 0.5;
  pz = abs(pz) - sharpness * 0.5;
  float cosR1 = cos(time * 0.15);
  float sinR1 = sin(time * 0.15);
  float rx1 = px * cosR1 - pz * sinR1;
  float rz1 = px * sinR1 + pz * cosR1;
  px = rx1;
  pz = rz1;
  px = px * sharpness - (sharpness - 1.0);
  py = py * sharpness - (sharpness - 1.0);
  pz = pz * sharpness - (sharpness - 1.0);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Crystal fold iteration 2
  px = abs(px) - sharpness * 0.4;
  py = abs(py) - sharpness * 0.4;
  pz = abs(pz) - sharpness * 0.4;
  float cosR2 = cos(time * 0.1 + 1.0);
  float sinR2 = sin(time * 0.1 + 1.0);
  float ry2 = py * cosR2 - pz * sinR2;
  float rz2 = py * sinR2 + pz * cosR2;
  py = ry2;
  pz = rz2;
  px = px * sharpness - (sharpness - 1.0);
  py = py * sharpness - (sharpness - 1.0);
  pz = pz * sharpness - (sharpness - 1.0);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Crystal fold iteration 3
  px = abs(px) - sharpness * 0.3;
  py = abs(py) - sharpness * 0.3;
  pz = abs(pz) - sharpness * 0.3;
  px = px * sharpness - (sharpness - 1.0);
  py = py * sharpness - (sharpness - 1.0);
  pz = pz * sharpness - (sharpness - 1.0);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Crystal fold iteration 4: chaos-influenced
  float chaosAngle = uChaos * 3.14159;
  float cosC = cos(chaosAngle);
  float sinC = sin(chaosAngle);
  float rx4 = px * cosC - py * sinC;
  float ry4 = px * sinC + py * cosC;
  px = abs(rx4) - sharpness * 0.2;
  py = abs(ry4) - sharpness * 0.2;
  pz = abs(pz) - sharpness * 0.2;
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Distance estimate
  float boxDist = max(max(abs(px), abs(py)), abs(pz)) - 0.3;
  float de = boxDist / pow(sharpness, 3.0) / invScale;

  return vec3(abs(de), trap, invScale);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.1);
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onset = uOnset * uSensitivity;
  float kick = uKick * uSensitivity;

  // Camera: orbit inside the crystal cavern
  float orbitAngle = time * 0.2;
  float camDist = 0.8 + sin(time * 0.1) * 0.3 + sin(uTime * 0.3) * 0.08;
  float camX = cos(orbitAngle) * camDist;
  float camZ = sin(orbitAngle) * camDist;
  float camY = sin(time * 0.13) * 0.5;
  vec3 ro = vec3(camX, camY, camZ);

  // Look-at slightly offset from center
  vec3 lookTarget = vec3(
    sin(time * 0.05) * 0.2,
    cos(time * 0.07) * 0.2,
    sin(time * 0.06) * 0.2
  );
  vec3 forward = normalize(lookTarget - ro);
  vec3 worldUp = vec3(0.0, 1.0, 0.0);
  vec3 right = normalize(cross(forward, worldUp));
  vec3 up = cross(right, forward);

  float fov = (uZoom + 0.5) * 1.2;
  vec3 rd = normalize(right * (p.x * fov) + up * (p.y * fov) + forward);

  // Sphere trace: 30 steps (3 x 10)
  float t = 0.01;
  float trap = 100.0;
  float steps = 0.0;
  float minDist = 100.0;
  vec3 lastPos = ro;

  for (int i = 0; i < 10; i++) {
    lastPos = ro + rd * t;
    vec3 result = crystalSDF(lastPos, time, bassVal, uCrystalSharpness);
    float d = result.x;
    minDist = min(minDist, d);
    trap = min(trap, result.y);
    t += d * 0.7;
    steps += 1.0;
  }
  for (int i = 0; i < 10; i++) {
    lastPos = ro + rd * t;
    vec3 result = crystalSDF(lastPos, time, bassVal, uCrystalSharpness);
    float d = result.x;
    minDist = min(minDist, d);
    trap = min(trap, result.y);
    t += d * 0.7;
    steps += 1.0;
  }
  for (int i = 0; i < 10; i++) {
    lastPos = ro + rd * t;
    vec3 result = crystalSDF(lastPos, time, bassVal, uCrystalSharpness);
    float d = result.x;
    minDist = min(minDist, d);
    trap = min(trap, result.y);
    t += d * 0.7;
    steps += 1.0;
  }

  // Approximate normal via gradient
  float eps = 0.002;
  float nxp = crystalSDF(lastPos + vec3(eps, 0.0, 0.0), time, bassVal, uCrystalSharpness).x;
  float nxn = crystalSDF(lastPos - vec3(eps, 0.0, 0.0), time, bassVal, uCrystalSharpness).x;
  float nyp = crystalSDF(lastPos + vec3(0.0, eps, 0.0), time, bassVal, uCrystalSharpness).x;
  float nyn = crystalSDF(lastPos - vec3(0.0, eps, 0.0), time, bassVal, uCrystalSharpness).x;
  float nzp = crystalSDF(lastPos + vec3(0.0, 0.0, eps), time, bassVal, uCrystalSharpness).x;
  float nzn = crystalSDF(lastPos - vec3(0.0, 0.0, eps), time, bassVal, uCrystalSharpness).x;
  vec3 normal = normalize(vec3(nxp - nxn, nyp - nyn, nzp - nzn));

  // Iridescence: view-angle-dependent color
  float viewDot = abs(dot(normal, -rd));
  float iridescentHue = viewDot * uIridescenceStrength + midsVal * 0.3 + uPalette * 0.1 + time * 0.02;
  vec3 iridColor = iridescencePalette(iridescentHue, uPalette, uIridescenceStrength);

  // Directional light + specular
  vec3 lightDir = normalize(vec3(sin(time * 0.3), 0.6, cos(time * 0.25)));
  float diff = max(dot(normal, lightDir), 0.0);

  // Specular: Fresnel-like from refraction index
  vec3 halfDir = normalize(lightDir - rd);
  float specAngle = max(dot(normal, halfDir), 0.0);
  float fresnel = (uRefractionIndex - 1.0) / (uRefractionIndex + 1.0);
  float fresnelSq = fresnel * fresnel;
  float specular = fresnelSq + (1.0 - fresnelSq) * pow(1.0 - viewDot, 5.0);
  float specHighlight = pow(specAngle, 32.0) * specular * (beatPulse * 0.5 + 0.8);

  // AO
  float ao = 1.0 - steps / 30.0 * 0.6;

  // Combine: iridescent surface + diffuse + specular
  vec3 surface = iridColor * (diff * 0.6 + 0.3) * ao;
  vec3 specCol = vec3(specHighlight, specHighlight * 0.9, specHighlight * 1.1);

  // Crystal sparkle from treble
  float sparkle = sin(lastPos.x * 50.0 + time * 3.0)
    * sin(lastPos.y * 50.0 - time * 2.5)
    * sin(lastPos.z * 50.0 + time * 2.0)
    * 0.5 + 0.5;
  float sparkleAmount = sparkle * trebleVal * smoothstep(0.02, 0.0, minDist) * 0.5;

  // Glow from near-miss
  float glow = 0.01 / (minDist + 0.003) * 0.08;
  vec3 glowCol = iridColor * glow;

  // Combine all
  vec3 combined = surface + specCol + glowCol + vec3(sparkleAmount, sparkleAmount * 0.8, sparkleAmount * 1.2);

  // Beat + onset pulse
  float pulse = beatPulse * 0.12 + onset * 0.25 + kick * 0.1;
  vec3 pulsed = combined + vec3(pulse, pulse * 0.7, pulse * 1.3);

  // Intensity
  vec3 lit = pulsed * (uIntensity * 1.5);

  // Fog inside cavern
  float fog = 1.0 - clamp(t / 6.0, 0.0, 1.0);
  vec3 fogged = lit * fog;

  // === PSYCHEDELIC ENHANCEMENT ===
  fogged = psychedelicColor(fogged);
  gl_FragColor = vec4(
    clamp(fogged.x, 0.0, 1.0),
    clamp(fogged.y, 0.0, 1.0),
    clamp(fogged.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLatticeScale;
uniform float uRefraction;
uniform float uFacetCount;

#define PI 3.14159265359
#define TAU 6.28318530718

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Hexagonal grid returns cell UV and cell ID
vec2 hexGrid(vec2 p, out vec2 cellId) {
  vec2 s = vec2(1.0, 1.732);
  vec2 h = s * 0.5;
  vec2 a = mod(p, s) - h;
  vec2 b = mod(p + h, s) - h;
  vec2 g = dot(a, a) < dot(b, b) ? a : b;
  cellId = p - g;
  return g;
}

// Prismatic refraction color from angle
vec3 prismaticColor(float angle, float palette) {
  float t = fract(angle / TAU + palette * 0.1);
  return 0.5 + 0.5 * cos(TAU * (t * 1.5 + vec3(0.0, 0.33, 0.67)));
}

// Polygon SDF for crystal facet
float facetSDF(vec2 p, float sides, float size) {
  float angle = atan(p.y, p.x);
  float slice = TAU / sides;
  float d = cos(floor(0.5 + angle / slice) * slice - angle) * length(p);
  return d - size;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 3.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Slow rotation of the lattice view
  float rot = time * 0.2;
  mat2 rotMat = mat2(cos(rot), -sin(rot), sin(rot), cos(rot));
  p = rotMat * p;

  // Lattice grid
  float scale = uLatticeScale * (1.0 + bassVal * 0.3);
  vec2 cellId;
  vec2 cellUV = hexGrid(p * scale, cellId);

  // Crystal facets
  float sides = floor(uFacetCount + 0.5);
  float facetRot = hash(cellId) * TAU + time * 0.5;
  mat2 facetRotMat = mat2(cos(facetRot), -sin(facetRot), sin(facetRot), cos(facetRot));
  vec2 rotCell = facetRotMat * cellUV;
  float crystalSize = 0.35 + 0.1 * sin(hash(cellId * 7.3) * TAU + time);
  crystalSize *= 1.0 + beatPulse * 0.2;
  float facet = facetSDF(rotCell, sides, crystalSize);

  // Facet edge glow
  float edgeGlow = smoothstep(0.02, 0.0, abs(facet)) * 1.5;

  // Interior refraction
  float interior = smoothstep(0.01, -0.15, facet);
  vec2 refractUV = cellUV + rotCell * uRefraction * 0.5;
  float refractAngle = atan(refractUV.y, refractUV.x) + midsVal * 2.0;
  float refractDist = length(refractUV);

  // Prismatic rainbow from refraction angle
  vec3 refractColor = prismaticColor(refractAngle + refractDist * 3.0, uPalette);

  // Internal light caustics
  float caustic1 = sin(refractUV.x * 15.0 + time * 2.0) * sin(refractUV.y * 15.0 + time * 1.7);
  float caustic2 = sin(refractUV.x * 23.0 - time * 1.3) * sin(refractUV.y * 19.0 + time * 2.1);
  float caustics = (caustic1 + caustic2) * 0.5 + 0.5;
  caustics = pow(caustics, 2.0) * uRefraction;

  // Sparkle highlights on treble
  float sparkle = 0.0;
  for (int i = 0; i < 5; i++) {
    vec2 sp = vec2(hash(cellId + float(i)), hash(cellId + float(i) + 37.0)) - 0.5;
    sp *= crystalSize * 0.8;
    float d = length(cellUV - sp);
    float flicker = sin(time * (10.0 + float(i) * 3.0) + hash(cellId + float(i) * 13.0) * TAU);
    sparkle += smoothstep(0.03, 0.0, d) * max(0.0, flicker) * trebleVal;
  }

  // Light rays between lattice points
  float ray = 0.0;
  for (int i = 0; i < 3; i++) {
    float a = float(i) * TAU / 3.0 + time * 0.4;
    vec2 dir = vec2(cos(a), sin(a));
    float d = abs(dot(cellUV, vec2(-dir.y, dir.x)));
    ray += smoothstep(0.02 + bassVal * 0.01, 0.0, d) * 0.3;
  }

  // Assemble color
  vec3 col = vec3(0.0);

  // Crystal body
  vec3 bodyColor = refractColor * (0.4 + caustics * 0.6);
  col += bodyColor * interior;

  // Edge glow: white/prismatic
  vec3 edgeColor = mix(vec3(1.0), refractColor, 0.5);
  col += edgeColor * edgeGlow;

  // Internal light rays
  col += refractColor * ray * interior * 0.5;

  // Sparkles
  col += vec3(1.0, 0.95, 0.9) * sparkle * 2.0;

  // Beat pulse: lattice brightens
  col += bodyColor * beatPulse * 0.3 * interior;

  // Onset: flash white
  col += vec3(onsetFlash * 0.15);

  // Background: dark deep blue
  vec3 bg = vec3(0.01, 0.01, 0.03) + vec3(0.02, 0.02, 0.04) * noise(p * 3.0 + time * 0.1);
  col = max(col, bg);

  // Chaos: distort grid
  float chaosNoise = noise(p * (5.0 + uChaos * 10.0) + time) * uChaos * 0.2;
  col += refractColor * chaosNoise * 0.3;

  col *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm3(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 3; i++) {
    v += a * noise2d(p);
    p = rot * p * 2.0;
    a *= 0.5;
  }
  return v;
}

// Regular polygon SDF with N sides
float sdPolygon(vec2 p, float sides, float radius) {
  float angle = atan(p.y, p.x);
  float seg = 6.2832 / sides;
  float halfSeg = seg * 0.5;
  float a = mod(angle + halfSeg, seg) - halfSeg;
  vec2 cp = vec2(cos(a), abs(sin(a))) * length(p);
  return cp.x - radius;
}

// Morphing crystal: blend between polygon shapes
float crystalSDF(vec2 p, float morphPhase, float radius) {
  // Cycle through platonic projections: 3, 4, 5, 6 sides
  float phase = fract(morphPhase);
  float sides1 = 3.0 + floor(mod(morphPhase, 4.0));
  float sides2 = 3.0 + floor(mod(morphPhase + 1.0, 4.0));

  // Smooth transition between shapes
  float d1 = sdPolygon(p, sides1, radius);
  float d2 = sdPolygon(p, sides2, radius);
  return mix(d1, d2, smoothstep(0.3, 0.7, phase));
}

// Prismatic dispersion: different refraction per color channel
vec3 prismaticRefract(vec2 p, vec2 normal2d, float ior, float dispersion) {
  vec3 refracted;
  float baseAngle = atan(normal2d.y, normal2d.x);

  // Red, green, blue at slightly different angles
  for (int ch = 0; ch < 3; ch++) {
    float chIor = ior + (float(ch) - 1.0) * dispersion * 0.05;
    float incident = atan(p.y, p.x) - baseAngle;
    float refAngle = asin(sin(incident) / chIor);
    vec2 refDir = vec2(cos(baseAngle + refAngle), sin(baseAngle + refAngle));
    float pattern = noise2d(refDir * 5.0 + p * 3.0);
    if (ch == 0) refracted.r = pattern;
    else if (ch == 1) refracted.g = pattern;
    else refracted.b = pattern;
  }
  return refracted;
}

// Internal fire caustics
float internalFire(vec2 p, float time) {
  float fire = 0.0;
  for (float i = 1.0; i < 5.0; i++) {
    vec2 q = p * i * 2.5 + vec2(time * 0.4 * i, time * 0.3);
    fire += sin(q.x + noise2d(q * 0.8)) * sin(q.y + noise2d(q * 1.1)) / i;
  }
  return fire * 0.5 + 0.5;
}

// Gem color palettes
vec3 gemColor(float t, float gemType) {
  // 0 = diamond (white/rainbow), 0.33 = ruby (red), 0.67 = sapphire (blue)
  vec3 diamond = vec3(0.95, 0.95, 1.0) + 0.35 * cos(6.2832 * t + vec3(0.0, 2.09, 4.19));
  vec3 ruby = vec3(0.9, 0.12, 0.18) + vec3(0.25, 0.06, 0.0) * cos(t * 6.2832);
  vec3 sapphire = vec3(0.12, 0.25, 0.95) + vec3(0.0, 0.12, 0.18) * cos(t * 6.2832);

  vec3 c = diamond;
  c = mix(c, ruby, smoothstep(0.2, 0.4, gemType));
  c = mix(c, sapphire, smoothstep(0.55, 0.75, gemType));
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float breathe = 1.0 + sin(uTime * 0.45) * 0.08;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float harmonicityVal = uHarmonicity * uSensitivity;

  // Morph phase: beat triggers transitions
  float morphPhase = time * 0.15 + beatVal * 0.5;

  // Crystal rotation
  float rotSpeed = time * 0.2 + bassVal * 0.3;
  float cr = cos(rotSpeed);
  float sr = sin(rotSpeed);
  vec2 rp = mat2(cr, -sr, sr, cr) * p;

  // Multiple concentric crystal shells
  vec3 col = vec3(0.01, 0.01, 0.02); // near-black background

  float totalCrystal = 0.0;
  vec3 crystalColor = vec3(0.0);

  for (float shell = 0.0; shell < 4.0; shell++) {
    float radius = 0.5 + shell * 0.22 + bassVal * 0.14;
    float shellPhase = morphPhase + shell * 0.7;

    // Rotate each shell differently
    float shellRot = time * (0.1 + shell * 0.05) * (mod(shell, 2.0) < 1.0 ? 1.0 : -1.0);
    float scr = cos(shellRot);
    float ssr = sin(shellRot);
    vec2 shellP = mat2(scr, -ssr, ssr, scr) * rp;

    float dist = crystalSDF(shellP, shellPhase, radius);

    // Faceted surface — larger to match scaled crystal
    float facet = sdPolygon(shellP, 3.0 + shell * 2.0, radius * 1.15);
    float facetPattern = smoothstep(0.01, -0.01, facet) * 0.3;

    // Crystal body
    float body = smoothstep(0.01, -0.01, dist);
    float shellEdge = exp(-abs(dist) * 40.0);

    // Gem type cycles with palette
    float gemType = fract(uPalette * 0.33 + shell * 0.25);

    // Surface normal approximation
    vec2 eps = vec2(0.003, 0.0);
    float dx = crystalSDF(shellP + eps.xy, shellPhase, radius) - dist;
    float dy = crystalSDF(shellP + eps.yx, shellPhase, radius) - dist;
    vec2 normal2d = normalize(vec2(dx, dy) + 0.0001);

    // Lighting
    vec3 lightDir = normalize(vec3(sin(time * 0.3), cos(time * 0.25), 1.0));
    vec3 normal3d = normalize(vec3(normal2d, 0.6));
    float diffuse = max(dot(normal3d, lightDir), 0.0);
    float specular = pow(max(dot(reflect(-lightDir, normal3d), vec3(0.0, 0.0, 1.0)), 0.0), 32.0 + shell * 16.0);

    // Prismatic refraction inside crystal
    vec3 prism = prismaticRefract(shellP, normal2d, 1.5 + shell * 0.1, 1.0 + trebleVal * 2.0);

    // Internal fire
    float fire = internalFire(shellP * (2.0 + shell), time + shell * 3.0);

    // Combine crystal appearance
    vec3 surfCol = gemColor(time * 0.02 + shell * 0.15 + prism.r * 0.2, gemType);
    surfCol *= 0.3 + diffuse * 0.5;
    surfCol += prism * 0.25 * body;
    surfCol += fire * 0.15 * body * gemColor(fire + time * 0.05, gemType);

    float shellAlpha = body * (0.6 - shell * 0.1) + shellEdge * 0.3;
    totalCrystal += shellAlpha;
    crystalColor += surfCol * shellAlpha + vec3(1.0, 0.98, 0.95) * specular * body * 0.4;
  }

  // Apply crystal layers
  col = mix(col, crystalColor / max(totalCrystal, 0.001), clamp(totalCrystal, 0.0, 1.0));

  // Rainbow caustic light rays emanating from crystal — extend to screen edges
  for (float i = 0.0; i < 8.0; i++) {
    float rayAngle = i * 0.7854 + time * 0.1 + morphPhase * 0.3;
    vec2 rayDir = vec2(cos(rayAngle), sin(rayAngle));
    float rayDist = abs(dot(p, vec2(-rayDir.y, rayDir.x)));
    float rayLen = dot(p, rayDir);
    float ray = exp(-rayDist * 15.0) * smoothstep(0.0, 0.4, rayLen) * smoothstep(3.0, 0.4, rayLen);

    // Rainbow along ray
    vec3 rayCol = 0.5 + 0.5 * cos(6.2832 * (i * 0.125 + time * 0.05) + vec3(0.0, 2.09, 4.19));
    col += rayCol * ray * 0.1 * (0.3 + trebleVal * 0.7);
  }

  // Facet sparkle particles — spread across full screen
  for (float i = 0.0; i < 25.0; i++) {
    float sparkAngle = hash21(vec2(i, 9.0)) * 6.2832;
    float sparkR = 0.4 + hash21(vec2(9.0, i)) * 0.8;
    vec2 sparkPos = vec2(cos(sparkAngle + time * 0.2), sin(sparkAngle + time * 0.2)) * sparkR;
    float sparkDist = length(p - sparkPos);
    float sparkle = exp(-sparkDist * 120.0) * 0.3;
    float twinkle = sin(time * 8.0 + i * 5.0) * 0.5 + 0.5;
    col += vec3(1.0, 0.95, 0.9) * sparkle * twinkle * trebleVal;
  }

  // Kick: flash white through crystal
  col = mix(col, col * 2.0 + vec3(0.1, 0.08, 0.12), kickVal * 0.35);

  // Beat: morph pulse brightness
  col *= 1.0 + beatVal * 0.25;

  // Onset: prismatic burst
  col += vec3(0.1, 0.05, 0.15) * onsetVal * 0.4;

  // Harmonicity: crystal clarity (more harmonics = clearer facets)
  col *= 0.9 + harmonicityVal * 0.2;

  // Energy: overall luminance
  col *= 0.85 + energyVal * 0.25;

  // Chaos: distort crystal form
  float chaosDistort = noise2d(p * 3.0 + time * 0.5) * uChaos * 0.08;
  col += col * chaosDistort;

  // Spectral flux shimmer
  col += col * uSpectralFlux * uSensitivity * 0.15;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.04;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFacetCount;
uniform float uRotationRate;
uniform float uRefractionStrength;
uniform float uEdgeGlow;

// Gem palettes: each returns a sophisticated crystal color
// Sapphire: deep blues, silver, ice
vec3 sapphirePalette(float t) {
  vec3 a = vec3(0.15, 0.2, 0.45);
  vec3 b = vec3(0.3, 0.35, 0.55);
  vec3 c = vec3(1.0, 1.0, 1.2);
  vec3 d = vec3(0.55, 0.62, 0.78);
  return a + b * cos(6.2832 * (c * t + d));
}

// Emerald: rich greens, gold flecks, jade
vec3 emeraldPalette(float t) {
  vec3 a = vec3(0.1, 0.35, 0.15);
  vec3 b = vec3(0.25, 0.45, 0.2);
  vec3 c = vec3(1.0, 0.8, 1.2);
  vec3 d = vec3(0.2, 0.55, 0.35);
  return a + b * cos(6.2832 * (c * t + d));
}

// Amethyst: purples, violets, rose gold
vec3 amethystPalette(float t) {
  vec3 a = vec3(0.3, 0.12, 0.35);
  vec3 b = vec3(0.4, 0.2, 0.45);
  vec3 c = vec3(1.1, 0.9, 1.0);
  vec3 d = vec3(0.65, 0.35, 0.7);
  return a + b * cos(6.2832 * (c * t + d));
}

// Diamond: white, silver, prismatic rainbow flashes
vec3 diamondPalette(float t) {
  vec3 a = vec3(0.45, 0.45, 0.5);
  vec3 b = vec3(0.25, 0.25, 0.3);
  vec3 c = vec3(2.0, 2.0, 2.0);
  vec3 d = vec3(0.0, 0.1, 0.2);
  return a + b * cos(6.2832 * (c * t + d));
}

// Ruby: deep reds, wine, warm gold
vec3 rubyPalette(float t) {
  vec3 a = vec3(0.4, 0.08, 0.1);
  vec3 b = vec3(0.5, 0.15, 0.15);
  vec3 c = vec3(1.0, 1.2, 0.8);
  vec3 d = vec3(0.0, 0.15, 0.3);
  return a + b * cos(6.2832 * (c * t + d));
}

// Opal: iridescent pastels
vec3 opalPalette(float t) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.3, 0.3, 0.3);
  vec3 c = vec3(1.0, 1.5, 2.0);
  vec3 d = vec3(0.0, 0.33, 0.67);
  return a + b * cos(6.2832 * (c * t + d));
}

// Spectral blend: mix between two palettes with smooth crossfade
vec3 blendPalettes(float t, float paletteMix) {
  // Cycle through 6 palettes
  float totalPalettes = 6.0;
  float idx = mod(paletteMix, totalPalettes);
  float fIdx = floor(idx);
  float frac2 = smoothstep(0.0, 1.0, fract(idx));

  vec3 c1, c2;

  // First palette
  if (fIdx < 1.0) { c1 = sapphirePalette(t); }
  else if (fIdx < 2.0) { c1 = emeraldPalette(t); }
  else if (fIdx < 3.0) { c1 = amethystPalette(t); }
  else if (fIdx < 4.0) { c1 = diamondPalette(t); }
  else if (fIdx < 5.0) { c1 = rubyPalette(t); }
  else { c1 = opalPalette(t); }

  // Second palette (next in cycle)
  float fIdx2 = mod(fIdx + 1.0, totalPalettes);
  if (fIdx2 < 1.0) { c2 = sapphirePalette(t); }
  else if (fIdx2 < 2.0) { c2 = emeraldPalette(t); }
  else if (fIdx2 < 3.0) { c2 = amethystPalette(t); }
  else if (fIdx2 < 4.0) { c2 = diamondPalette(t); }
  else if (fIdx2 < 5.0) { c2 = rubyPalette(t); }
  else { c2 = opalPalette(t); }

  return mix(c1, c2, frac2);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.0) * uRotationRate;

  // Audio-reactive modulators
  float bassRefract = bass() * uSensitivity * 0.5;
  float midsRotate = mids() * uSensitivity * 0.4;
  float trebleDetail = treble() * uSensitivity * 0.3;
  float onsetFlash = uOnset * uSensitivity * 1.5;
  float energyBright = uEnergy * uSensitivity;
  float kickPunch = uKick * uSensitivity;
  float spectralCent = uSpectralCentroid;

  // Palette cycling: slow automatic + audio-driven shifts
  float paletteCycle = time * 0.04 + uPalette * 1.0 + bassRefract * 0.5;

  // Rotate the crystal slowly
  float angle = time + midsRotate * 0.5;
  float cosA = cos(angle);
  float sinA = sin(angle);
  float rx = p.x * cosA - p.y * sinA;
  float ry = p.x * sinA + p.y * cosA;

  // === FACET PATTERN ===
  float angularPattern = sin(rx * uFacetCount * 3.14159) *
    cos(ry * uFacetCount * 3.14159);

  // Second layer: rotated facets for more complexity
  float rx2 = rx * cos(0.5) - ry * sin(0.5);
  float ry2 = rx * sin(0.5) + ry * cos(0.5);
  float angularPattern2 = sin(rx2 * (uFacetCount * 0.7) * 3.14159) *
    cos(ry2 * (uFacetCount * 0.7) * 3.14159);

  // Combined facet pattern
  float facet = angularPattern * 0.6 + angularPattern2 * 0.4;

  // === FACET EDGES ===
  float facetDx = sin((rx + 0.01) * uFacetCount * 3.14159) *
    cos(ry * uFacetCount * 3.14159) - angularPattern;
  float facetDy = sin(rx * uFacetCount * 3.14159) *
    cos((ry + 0.01) * uFacetCount * 3.14159) - angularPattern;
  float edgeStrength = abs(facetDx * 50.0) + abs(facetDy * 50.0);
  float edge = smoothstep(0.5, 1.5, edgeStrength) * uEdgeGlow;

  // === REFRACTION with gem palettes ===
  float refractionOffset = facet * uRefractionStrength + bassRefract * 0.2;

  // Palette parameter: combines facet position + time drift
  float palT = refractionOffset * 0.5 + 0.5 + time * 0.03;

  // Main facet color from blended gem palettes
  vec3 facetColor = blendPalettes(palT, paletteCycle);

  // === IRIDESCENT / OPALESCENT shift based on viewing angle ===
  // Simulate thin-film interference: color shifts based on angle from center
  float viewAngle = atan(p.y, p.x);
  float viewDist = length(p);
  float iridescence = sin(viewAngle * 3.0 + viewDist * 8.0 + time * 0.5) * 0.5 + 0.5;
  // Use opal palette for iridescent overlay
  vec3 iriColor = opalPalette(iridescence + spectralCent * 0.3 + time * 0.02);
  // Blend iridescence at edges and on facet boundaries
  float iriStrength = edge * 0.4 + smoothstep(0.3, 0.8, viewDist) * 0.2
    + trebleDetail * 0.15;
  facetColor = mix(facetColor, iriColor, iriStrength);

  // === EDGE COLOR: separate palette with spectral shift ===
  float edgePalT = palT + 0.15 + edge * 0.3;
  vec3 edgeColor = blendPalettes(edgePalT, paletteCycle + 1.5) * edge;
  // Add diamond-like prismatic flash at edges
  vec3 prismFlash = diamondPalette(edgePalT * 3.0 + spectralCent) * edge * trebleDetail * 0.5;
  edgeColor += prismFlash;

  // === INTERNAL LIGHT CAUSTICS ===
  float caustic = sin(rx * 20.0 + time * 0.5) *
    cos(ry * 18.0 - time * 0.3) * 0.5 + 0.5;
  // Audio-driven caustic shimmer
  caustic *= uChaos * 0.2 + bassRefract * 0.1;
  vec3 causticColor = blendPalettes(caustic + time * 0.01, paletteCycle + 3.0) * caustic;

  // === COMBINE ===
  float brightness = uIntensity * 1.0 + energyBright * 0.3;

  vec3 finalColor = (facetColor * 0.5 + edgeColor * 1.5 + causticColor) * brightness;

  // Onset flash at edges — uses diamond palette for white-ish flash
  vec3 flashColor = diamondPalette(time * 0.1) * onsetFlash * edge * 0.5;
  finalColor += flashColor;

  // Kick: brief brightness surge with palette emphasis
  float kickBoost = kickPunch * 0.15 * (edge + 0.3);
  finalColor += finalColor * kickBoost;

  // Beat pulse — subtle warm addition
  float beatPulse = uBeat * uSensitivity * 0.08 * (edge + 0.2);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.r + beatPulse, 0.0, 1.0),
    clamp(finalColor.g + beatPulse, 0.0, 1.0),
    clamp(finalColor.b + beatPulse, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPlateMode;
uniform float uDisplacement;
uniform float uSandDensity;

#define PI 3.14159265
#define TAU 6.28318530

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// Chladni pattern: cos(n*pi*x)*cos(m*pi*y) - cos(m*pi*x)*cos(n*pi*y)
float chladni(vec2 p, float n, float m) {
  return cos(n * PI * p.x) * cos(m * PI * p.y) - cos(m * PI * p.x) * cos(n * PI * p.y);
}

// Circular plate mode (Bessel function approximation)
float circularMode(vec2 p, float m, float n) {
  float r = length(p);
  float theta = atan(p.y, p.x);

  // Simplified Bessel-like radial function
  float radial = cos(n * PI * r) * exp(-r * r * 0.5);
  float angular = cos(m * theta);

  return radial * angular;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.3;

  // Plate shape (circular)
  float plateR = length(p);
  float plateMask = smoothstep(1.0, 0.98, plateR);

  // Mode numbers driven by pitch and plate mode param
  float modeBase = 1.0 + uPlateMode * 6.0;
  float pitchMode = 1.0 + uPitch * 0.01; // Pitch influences mode
  float n = floor(modeBase + pitchMode * 0.5);
  float m = floor(modeBase * 0.7 + 1.0);

  // Mix between square and circular plate patterns
  float square = chladni(p, n, m);
  float circular = circularMode(p, m, n);
  float pattern = mix(square, circular, 0.5 + uChaos * 0.5);

  // Additional modes for complexity
  float n2 = n + 1.0;
  float m2 = m + 1.0;
  float pattern2 = chladni(p, n2, m2) * 0.5;
  pattern += pattern2 * trebleVal * 0.5;

  // Displacement driven by bass
  float disp = uDisplacement + bassVal * 0.3;
  pattern *= disp;

  // Vibration animation
  float vibration = sin(time * 5.0 + uBpmSin * 3.0);
  float animatedPattern = pattern * vibration;

  // Node lines: where pattern = 0, sand accumulates
  float nodeDist = abs(pattern);
  float nodeLines = smoothstep(0.08, 0.02, nodeDist);

  // Sand particles at nodes
  float sand = 0.0;
  if (uSandDensity > 0.1) {
    // Multiple sand grain layers
    for (int i = 0; i < 3; i++) {
      float fi = float(i);
      float scale = 30.0 + fi * 20.0;
      float grainNoise = noise(p * scale + time * 0.05 * fi);
      float grain = smoothstep(0.4, 0.6, grainNoise) * nodeLines;
      sand += grain * uSandDensity * 0.4;
    }
  }

  // Plate surface color
  vec3 plateCol = vec3(0.02, 0.02, 0.025); // Black plate

  // Sand color: white/cream
  vec3 sandCol = vec3(0.85, 0.82, 0.75);

  // Spectrum bands add subtle color to sand
  sandCol.r += uSpectrum0 * uSensitivity * 0.1;
  sandCol.g += uSpectrum3 * uSensitivity * 0.08;
  sandCol.b += uSpectrum6 * uSensitivity * 0.06;

  vec3 col = mix(plateCol, sandCol, sand);

  // Vibrating surface highlight
  float surfaceVib = abs(animatedPattern) * 0.15;
  col += vec3(0.05, 0.06, 0.08) * surfaceVib * (1.0 - nodeLines);

  // Antinode glow (maximal vibration points)
  float antinodeDist = abs(abs(pattern) - 1.0);
  float antinodeGlow = smoothstep(0.3, 0.0, antinodeDist) * abs(vibration);
  col += vec3(0.1, 0.12, 0.15) * antinodeGlow * 0.3;

  // Beat: whole plate pulses
  col += vec3(0.05, 0.06, 0.08) * uBeat * uSensitivity * 0.2;

  // Kick: mode change flash
  col += vec3(0.15, 0.14, 0.12) * uKick * uSensitivity * 0.2;

  // Onset: sand scatter effect
  float scatter = noise(p * 50.0 + time * 10.0) * uOnset * uSensitivity * sand;
  col += vec3(0.3, 0.28, 0.25) * scatter * 0.3;

  // Node line highlight for treble
  col += vec3(0.15, 0.14, 0.12) * nodeLines * trebleVal * 0.2;

  // Apply plate mask
  col *= plateMask;

  // Plate edge ring
  float edgeRing = smoothstep(1.0, 0.98, plateR) * smoothstep(0.95, 0.98, plateR);
  col += vec3(0.1, 0.1, 0.12) * edgeRing;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFlameCount;
uniform float uFlameHeight;
uniform float uFlickerRate;
uniform float uSwayAmount;

vec3 flamePalette(float t, float offset) {
  // Warm flame colors: yellows, oranges, reds, transitioning to blues at tips
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.1, 0.2)));
}

// Simple pseudo-noise
float noise1D(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(fract(sin(i * 127.1) * 43758.5453), fract(sin((i + 1.0) * 127.1) * 43758.5453), f);
}

float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

void main() {
  // Map to full-screen coordinates: x spans ~[-1,1], y spans [0,~2] (bottom-anchored)
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  p.x = (p.x - 0.5) * (uZoom * 2.0 + 2.0); // full width
  p.y = p.y * (uZoom * 2.0 + 2.0);          // anchor at bottom, extend upward
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numFlames = min(uFlameCount, 12.0);
  vec3 color = vec3(0.0);

  // Pre-compute flame positions and sizes for coalescence checks
  float flameXs[12];
  float flameWidths[12];
  float flameHeights[12];

  for (int idx = 0; idx < 12; idx++) {
    float fi = float(idx);
    if (fi >= numFlames) break;
    float frac = fi / numFlames;
    flameXs[idx] = (frac - 0.5) * 3.6;
    float seed = fi * 7.3;
    float audioH = mix(bassVal, midsVal, frac) * 0.3 + 0.1;
    flameHeights[idx] = uFlameHeight * 3.5 * (0.5 + hash(seed) * 0.5) + audioH + onsetVal * 0.2;
    flameWidths[idx] = 0.18 + hash(seed + 2.0) * 0.06;

    // Sway adjusts position
    float swayPhase = time * (1.0 + hash(seed + 1.0) * 0.5) + seed;
    float sway = sin(swayPhase) * uSwayAmount * 0.15;
    sway += sin(swayPhase * 2.3 + 1.0) * uSwayAmount * 0.08;
    sway += midsVal * sin(time * 2.0 + fi * 1.5) * 0.08;
    flameXs[idx] += sway * 0.5;
  }

  for (float i = 0.0; i < 12.0; i += 1.0) {
    if (i >= numFlames) break;
    int ii = int(i);

    float frac = i / numFlames;
    float flameX = flameXs[ii];

    // Unique seed per flame
    float seed = i * 7.3;

    // Full-screen height flames
    float height = flameHeights[ii];

    // Vertical: y from 0 (base) upward
    float yNorm = p.y / height; // 0 at base, 1 at tip

    // Only render where flame exists
    if (p.y < -0.2 || yNorm > 1.4) continue;

    // Sway: flame bends laterally
    float swayPhase = time * (1.0 + hash(seed + 1.0) * 0.5) + seed;
    float sway = sin(swayPhase) * uSwayAmount * 0.15;
    sway += sin(swayPhase * 2.3 + 1.0) * uSwayAmount * 0.08;
    sway += midsVal * sin(time * 2.0 + i * 1.5) * 0.08;

    // Sway increases with height
    float xOffset = sway * yNorm * yNorm;

    // Flicker: rapid brightness variation
    float flickerPhase = time * uFlickerRate * 8.0 + seed * 3.1;
    float flicker = noise1D(flickerPhase) * 0.3 + 0.7;
    flicker *= noise1D(flickerPhase * 1.7 + 10.0) * 0.3 + 0.7;

    // Flame width narrows toward the tip
    float baseWidth = flameWidths[ii];

    // === COALESCENCE: widen flame when neighbors are close ===
    float coalesceBoost = 0.0;
    for (int j = 0; j < 12; j++) {
      if (j == ii || float(j) >= numFlames) continue;
      float neighborDist = abs(flameXs[ii] - flameXs[j]);
      // When flames are close, they merge — widen both
      coalesceBoost += smoothstep(0.25, 0.05, neighborDist) * 0.5;
    }
    baseWidth *= (1.0 + coalesceBoost);

    float widthAtY = baseWidth * (1.0 - yNorm * yNorm * 0.8);
    widthAtY = max(widthAtY, 0.005);

    // Turbulent displacement
    float turbX = noise1D(p.y * 5.0 + time * 3.0 + seed) * 0.03;
    turbX += noise1D(p.y * 10.0 - time * 4.0 + seed + 50.0) * 0.015;
    turbX *= uChaos + 0.5;

    // Distance from flame centerline
    float dx = p.x - flameX - xOffset - turbX;
    float distToCenter = abs(dx) / widthAtY;

    // Flame profile: exponential falloff from center
    float flameProfile = exp(-distToCenter * distToCenter * 2.0);

    // Vertical fade at tip
    float tipFade = smoothstep(1.2, 0.4, yNorm);
    // Fade at base (slight)
    float baseFade = smoothstep(-0.2, 0.05, p.y);

    float flameBright = flameProfile * tipFade * baseFade * flicker;

    // Core: brighter, thinner
    float coreBright = exp(-distToCenter * distToCenter * 8.0) * tipFade * baseFade;

    // Color: hot white/yellow at base, orange in middle, red/blue at tip
    float tempGradient = yNorm; // 0 = base (hot), 1 = tip (cool)
    float hue = tempGradient * 0.25 + uPalette * 0.1 + frac * 0.05;
    vec3 flameColor = flamePalette(hue, uPalette * 0.05);

    // Base is brighter/whiter
    flameColor = mix(vec3(1.0, 0.95, 0.8), flameColor, smoothstep(0.0, 0.4, tempGradient));

    // Coalesced flames glow brighter
    flameColor *= (1.0 + coalesceBoost * 0.4);

    // Chaos shifts flame color
    flameColor = mix(flameColor, flameColor.bgr, uChaos * sin(i * 2.5 + time * 0.3) * 0.2);

    float totalBright = flameBright * 0.8 + coreBright * 1.5;
    color += flameColor * totalBright;

    // === CHILD FLAMES: spawn smaller flames that separate from parent ===
    float childPhase = fract(time * 0.15 + hash(seed + 10.0));
    if (childPhase > 0.3 && childPhase < 0.9 && coalesceBoost > 0.1) {
      float childAge = (childPhase - 0.3) / 0.6; // 0 to 1
      float childDir = (hash(seed + 20.0 + floor(time * 0.15)) > 0.5) ? 1.0 : -1.0;
      float childX = flameX + childDir * childAge * 0.2;
      float childH = height * 0.4 * (1.0 - childAge * 0.5);
      float childYN = p.y / childH;
      if (childYN > 0.0 && childYN < 1.2) {
        float childW = baseWidth * 0.4 * (1.0 - childYN * childYN);
        childW = max(childW, 0.003);
        float cdx = abs(p.x - childX) / childW;
        float childBright = exp(-cdx * cdx * 3.0) * smoothstep(1.1, 0.3, childYN) * baseFade;
        childBright *= flicker * (1.0 - childAge * 0.5);
        vec3 childColor = flamePalette(hue + 0.05, uPalette * 0.05);
        childColor = mix(vec3(1.0, 0.9, 0.7), childColor, smoothstep(0.0, 0.3, childYN));
        color += childColor * childBright * 0.6;
      }
    }
  }

  // Ember glow at the base — wider, full screen width
  float emberY = 0.05;
  float emberDist = abs(p.y - emberY);
  float emberGlow = exp(-emberDist * 3.0) * smoothstep(2.5, 0.0, abs(p.x));
  vec3 emberColor = vec3(0.8, 0.3, 0.05);
  color += emberColor * emberGlow * (0.3 + bassVal * 0.4);

  // Heat shimmer across full height
  float sparkle = sin(p.x * 40.0 + time * 6.0) * sin(p.y * 30.0 + time * 8.0);
  sparkle = pow(max(sparkle, 0.0), 15.0);
  sparkle *= smoothstep(0.0, 0.3, p.y);
  color += vec3(1.0, 0.8, 0.5) * sparkle * trebleVal * 0.15;

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.04);

  // Kick punch: brighten
  color = mix(color, color * 1.5, kickVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.1));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash22(vec2 p) {
  return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm6(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) {
    v += a * noise2d(p);
    p = rot * p * 2.0 + vec2(3.7, 1.9);
    a *= 0.5;
  }
  return v;
}

// Dark matter flow field
vec2 flowField(vec2 p, float time) {
  float angle = fbm6(p * 0.8 + time * 0.05) * 6.2832;
  angle += sin(length(p) * 2.0 - time * 0.3) * 1.5;
  return vec2(cos(angle), sin(angle));
}

// Void tendrils: dark wisps reaching outward
float voidTendril(vec2 p, float time, float idx) {
  float angle = idx * 1.2566 + time * 0.1 + sin(time * 0.2 + idx * 2.0) * 0.3;
  vec2 tendrilDir = vec2(cos(angle), sin(angle));
  vec2 perp = vec2(-tendrilDir.y, tendrilDir.x);

  float along = dot(p, tendrilDir);
  float across = dot(p, perp);

  // Wispy width that narrows with distance
  float width = 0.08 * exp(-along * 0.5);
  width += noise2d(vec2(along * 3.0, idx) + time * 0.5) * 0.03;

  float tendril = smoothstep(width, 0.0, abs(across));
  tendril *= smoothstep(-0.1, 0.3, along) * smoothstep(2.0, 0.5, along);

  return tendril;
}

// Energy eruption: radial burst
float energyBurst(vec2 p, float time, float trigger) {
  float dist = length(p);
  float burstPhase = fract(time * 0.5);
  float burstRadius = burstPhase * 1.5;
  float burstWidth = 0.1 + trigger * 0.2;

  float ring = exp(-abs(dist - burstRadius) / burstWidth * 3.0);
  float fade = 1.0 - burstPhase;
  fade = fade * fade; // quadratic fade

  return ring * fade * trigger;
}

vec3 voidPalette(float t, float shift) {
  // Purple / black / electric blue
  vec3 a = vec3(0.2, 0.08, 0.35);
  vec3 b = vec3(0.4, 0.2, 0.65);
  vec3 c = vec3(0.9, 0.7, 1.3);
  vec3 d = vec3(0.7, 0.25, 0.9);
  return a + b * cos(6.2832 * (c * (t + shift * 0.1) + d));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  // Near-total darkness as base
  vec3 col = vec3(0.005, 0.003, 0.01);

  // Subtle dark matter texture: barely visible swirling
  float darkMatter = fbm6(p * 1.5 + time * 0.02);
  col += vec3(0.01, 0.005, 0.015) * darkMatter;

  // Flow field distortion
  vec2 flow = flowField(p, time);
  vec2 flowedP = p + flow * 0.15 * (1.0 + uChaos);

  // Dark matter particle streams
  for (float i = 0.0; i < 80.0; i++) {
    vec2 particleStart = vec2(
      hash21(vec2(i, 3.0)) * 4.0 - 2.0,
      hash21(vec2(3.0, i)) * 4.0 - 2.0
    );

    // Advect particle along flow
    vec2 pPos = particleStart;
    for (int s = 0; s < 3; s++) {
      vec2 fl = flowField(pPos, time);
      pPos += fl * 0.1;
    }
    pPos += vec2(sin(time * 0.3 + i * 0.7), cos(time * 0.25 + i * 0.9)) * 0.1;

    float dist = length(flowedP - pPos);
    float particle = exp(-dist * 60.0) * 0.08;

    // Very dim: dark matter is mostly invisible
    float visibility = 0.1 + bassVal * 0.3 + energyVal * 0.2;
    vec3 pCol = voidPalette(i * 0.05 + time * 0.005, uPalette) * visibility;
    col += pCol * particle;
  }

  // Void tendrils: dark wisps
  for (float i = 0.0; i < 5.0; i++) {
    float tendril = voidTendril(flowedP, time, i);
    vec3 tendrilCol = voidPalette(i * 0.2 + time * 0.01, uPalette) * 0.3;
    // Tendrils are dimly visible, brightened by mids
    col += tendrilCol * tendril * (0.2 + midsVal * 0.5);
  }

  // Invisible attractors: gravitational distortion points
  for (float i = 0.0; i < 3.0; i++) {
    vec2 attractor = vec2(
      sin(time * 0.15 + i * 2.094) * 0.8,
      cos(time * 0.12 + i * 2.094) * 0.6
    );
    float dist = length(p - attractor);
    // Dark halo around attractor
    float halo = exp(-dist * 3.0) * 0.03;
    col += voidPalette(i * 0.33 + time * 0.005, uPalette) * halo * (0.3 + energyVal * 0.5);

    // Accretion ring
    float ringR = 0.2 + sin(time * 0.3 + i) * 0.05;
    float ring = exp(-abs(dist - ringR) * 30.0) * 0.06;
    col += voidPalette(dist * 2.0 + time * 0.02, uPalette) * ring * (0.2 + midsVal * 0.5);
  }

  // ENERGY ERUPTIONS on kick: bright bursts from darkness
  float eruptionStrength = kickVal * 4.0 + onsetVal * 2.0;
  if (eruptionStrength > 0.05) {
    // Central eruption
    float burst = energyBurst(p, time, eruptionStrength);
    vec3 burstCol = voidPalette(time * 0.1, uPalette) * 5.0;
    burstCol += vec3(0.3, 0.15, 0.7) * eruptionStrength; // electric blue boost
    col += burstCol * burst;

    // Radial lightning from eruption
    for (float i = 0.0; i < 8.0; i++) {
      float boltAngle = i * 0.7854 + hash21(vec2(i, floor(time * 2.0))) * 0.5;
      vec2 boltDir = vec2(cos(boltAngle), sin(boltAngle));
      vec2 boltPerp = vec2(-boltDir.y, boltDir.x);

      float along = dot(p, boltDir);
      float across = dot(p, boltPerp);
      // Jagged bolt path
      across += noise2d(vec2(along * 8.0, i + time * 3.0)) * 0.08;

      float bolt = exp(-abs(across) * 50.0);
      bolt *= smoothstep(0.0, 0.1, along) * smoothstep(1.5, 0.3, along);
      bolt *= eruptionStrength;

      vec3 boltCol = vec3(0.3, 0.15, 1.0) + vec3(0.5, 0.0, 0.3) * hash21(vec2(i, 17.0));
      col += boltCol * bolt * 0.4;
    }

    // Particle shower from eruption
    for (float i = 0.0; i < 30.0; i++) {
      float pAngle = hash21(vec2(i, 23.0)) * 6.2832;
      float pSpeed = 0.5 + hash21(vec2(23.0, i)) * 1.5;
      float pTime = fract(time * 0.8 + hash21(vec2(i, 37.0)));
      vec2 pPos2 = vec2(cos(pAngle), sin(pAngle)) * pSpeed * pTime;

      float pDist = length(p - pPos2);
      float pGlow = exp(-pDist * 80.0) * (1.0 - pTime) * eruptionStrength * 0.3;
      vec3 pCol = voidPalette(i * 0.06 + time * 0.02, uPalette) * 2.0;
      col += pCol * pGlow;
    }
  }

  // Secondary eruptions at attractors on onset
  for (float i = 0.0; i < 3.0; i++) {
    vec2 attractor = vec2(
      sin(time * 0.15 + i * 2.094) * 0.8,
      cos(time * 0.12 + i * 2.094) * 0.6
    );
    float localBurst = energyBurst(p - attractor, time + i * 0.7, onsetVal * 1.5);
    col += voidPalette(i * 0.33 + 0.5, uPalette) * localBurst * 1.5;
  }

  // Treble: tiny energy sparks
  float sparkGrid = 80.0;
  vec2 sparkCell = floor(p * sparkGrid);
  float sparkId = hash21(sparkCell);
  float sparkActive = step(0.95 - trebleVal * 0.04, sparkId);
  float sparkFlash = sin(time * 12.0 + sparkId * 18.85) * 0.5 + 0.5;
  sparkFlash = sparkFlash * sparkFlash * sparkFlash; // sharp flash
  col += vec3(0.4, 0.2, 1.0) * sparkActive * sparkFlash * trebleVal * 0.1;

  // Beat: subtle overall brightening
  col *= 1.0 + beatVal * 0.3;

  // Bass: deep vibration effect
  float vibration = sin(length(p) * 15.0 - time * 6.0) * 0.5 + 0.5;
  col += vec3(0.02, 0.01, 0.04) * vibration * bassVal * 0.3;

  // Spectral flux: energy shimmer
  col += col * fluxVal * 0.6;

  // Entropy: chaos in the void
  col += vec3(0.01, 0.005, 0.02) * uSpectralEntropy * uSensitivity * 0.3;

  // BPM: void breathing
  col *= 1.0 + uBpmSin * 0.03;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

float hash1(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash1(i);
  float b = hash1(i + vec2(1.0, 0.0));
  float c = hash1(i + vec2(0.0, 1.0));
  float d = hash1(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Multi-layer Voronoi returning (cellDist, edgeDist, cellID)
vec3 voronoiField(vec2 p, float jitter) {
  vec2 n = floor(p);
  vec2 f = fract(p);
  float md1 = 8.0;
  float md2 = 8.0;
  vec2 nearCell = vec2(0.0);
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 o = hash2(n + g) * jitter;
      vec2 r = g + o - f;
      float d = dot(r, r);
      if (d < md1) {
        md2 = md1;
        md1 = d;
        nearCell = n + g;
      } else if (d < md2) {
        md2 = d;
      }
    }
  }
  return vec3(sqrt(md1), md2 - md1, hash1(nearCell));
}

// Gossamer thread brightness from edge proximity
float threadGlow(float edgeDist, float width) {
  return exp(-edgeDist * edgeDist / (width * width * 0.005));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.25;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Drift the web slowly with chaos-modulated turbulence
  vec2 drift = vec2(sin(time * 0.13) * 0.4, cos(time * 0.09) * 0.3) * uChaos;
  vec2 webP = p * (3.0 + uChaos * 2.0) + drift + time * vec2(0.07, 0.05);
  webP += vec2(midsVal * 0.08, -midsVal * 0.06);

  // Three-scale Voronoi for depth
  vec3 v1 = voronoiField(webP, 0.95);
  vec3 v2 = voronoiField(webP * 0.45 + vec2(33.7, 71.2), 0.9);
  vec3 v3 = voronoiField(webP * 1.8 + vec2(-17.3, 44.9), 0.85);

  // Fine-scale filaments: barely visible base, flash on peaks
  float baseVis = 0.04; // nearly invisible at rest
  float peakBoost = bassVal * 1.4 + trebleVal * 1.8 + onsetFlash * 2.4;
  float filVis = baseVis + peakBoost;

  // Primary filament threads
  float tw1 = 0.12 + bassVal * 0.04;
  float fil1 = threadGlow(v1.y, tw1) * filVis;
  float fil2 = threadGlow(v2.y, 0.18) * filVis * 0.5;
  float fil3 = threadGlow(v3.y, 0.08) * filVis * 0.7;

  // Pulse wave traveling along filaments on bass
  float travelPulse = sin(v1.y * 25.0 - time * 4.0 + bassVal * 3.0) * 0.5 + 0.5;
  fil1 *= (0.5 + travelPulse * 0.5);

  // Treble sparkle on thread intersections
  float intersect = fil1 * fil3;
  float trebleSpark = intersect * trebleVal * 8.0;

  // Silver-indigo filament color
  vec3 indigoSilver = mix(
    vec3(0.12, 0.1, 0.35),   // deep indigo
    vec3(0.7, 0.75, 0.9),    // silver
    0.3 + trebleVal * 0.4
  );

  // Palette rotation
  float palAngle = uPalette * 0.4;
  vec3 filCol = vec3(
    indigoSilver.r * cos(palAngle) - indigoSilver.b * sin(palAngle),
    indigoSilver.g,
    indigoSilver.r * sin(palAngle) + indigoSilver.b * cos(palAngle)
  );

  vec3 threadColor = filCol * fil1
    + filCol * 0.6 * fil2
    + vec3(0.5, 0.55, 0.8) * fil3;

  // Treble sparkle as bright white flash at junctions
  threadColor += vec3(0.9, 0.92, 1.0) * trebleSpark;

  // Node clusters at Voronoi centers — tiny bright dots
  float nodeR = 0.06 * (1.0 + kickVal * 0.4);
  float node = exp(-v1.x * v1.x / (nodeR * nodeR));
  float nodeFlicker = 0.6 + 0.4 * sin(v1.z * 80.0 + time * 2.5);
  float nodeBright = node * nodeFlicker * (0.2 + energyVal * 1.2 + beatPulse * 1.6);
  vec3 nodeCol = mix(vec3(0.4, 0.45, 0.8), vec3(0.9, 0.88, 1.0), v1.z) * nodeBright;

  // Beat shockwave radiating from center
  float shockR = length(p);
  float shockPhase = fract(time * 0.35);
  float shockRing = exp(-pow((shockR - shockPhase * 3.5) * 5.0, 2.0));
  vec3 shockCol = vec3(0.25, 0.2, 0.55) * shockRing * beatPulse * 0.5 * (fil1 + 0.1);

  // Onset burst: full web lights up briefly
  vec3 onsetCol = filCol * 1.5 * onsetFlash * (fil1 + fil2 + fil3) * 0.4;

  // Background: near-black void with faint noise fog
  float bgFog = vnoise(p * 4.0 + time * 0.02) * 0.008;
  vec3 bg = vec3(0.003 + bgFog, 0.002 + bgFog * 0.5, 0.008 + bgFog * 1.2);

  // Distant star pinpricks
  float starScale = 180.0;
  vec2 starCell = floor(p * starScale);
  float starH = hash1(starCell);
  if (starH > 0.992) {
    vec2 starOff = vec2(hash1(starCell + 5.0), hash1(starCell + 11.0));
    vec2 starFrac = fract(p * starScale) - starOff;
    float sDist = dot(starFrac, starFrac);
    bg += vec3(0.4, 0.42, 0.6) * exp(-sDist * 3000.0) * 0.15;
  }

  // Gravitational lensing arcs near bright nodes
  float lensArc = smoothstep(nodeR * 4.0, nodeR * 1.5, v1.x)
    * (sin(atan(p.y, p.x) * 8.0 + v1.z * 25.0 + time * 0.5) * 0.5 + 0.5);
  vec3 lensCol = vec3(0.15, 0.18, 0.35) * lensArc * node * 0.25;

  // Combine all layers
  vec3 col = bg + threadColor + nodeCol + shockCol + onsetCol + lensCol;

  // Energy global brightness
  col *= (0.7 + energyVal * 0.8);
  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCorruptionLevel;
uniform float uBlockSize;
uniform float uScanFreq;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

// Underlying "clean" signal
vec3 cleanSignal(vec2 uv, float time) {
  float n = fbm(uv * 4.0 + time * 0.1);
  float n2 = fbm(uv * 6.0 - time * 0.15 + vec2(5.0, 3.0));
  vec3 c = 0.5 + 0.5 * cos(6.2832 * (vec3(n, n2, n * 0.5 + n2 * 0.5) + vec3(0.0, 0.33, 0.67)));
  float grid = step(0.95, sin(uv.x * 30.0) * sin(uv.y * 30.0));
  c += vec3(0.3) * grid;
  return c;
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.75;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickPulse = uKick * uSensitivity * 1.4;
  float energyVal = uEnergy * uSensitivity;
  float onsetFlash = uOnset * uSensitivity * 1.5;

  // Time quantization for glitch timing
  float glitchTime = floor(time * (4.0 + uChaos * 8.0));

  // Corruption intensity modulated by audio
  float corruption = uCorruptionLevel + bassVal * 0.3 + kickPulse * 0.4;
  corruption = clamp(corruption, 0.0, 1.0);

  // === BLOCK DISPLACEMENT ===
  float bSize = uBlockSize * 0.1 + 0.02 + midsVal * 0.03;
  vec2 blockCoord = floor(p / bSize);
  float blockRand = hash(blockCoord + glitchTime);
  float blockActive = step(1.0 - corruption, blockRand);

  float dispX = (hash(blockCoord + glitchTime + vec2(17.0, 0.0)) - 0.5) * 0.15 * blockActive;
  float dispY = (hash(blockCoord + glitchTime + vec2(0.0, 31.0)) - 0.5) * 0.08 * blockActive;

  // Row-based horizontal tearing
  float tearRow = floor(p.y * (20.0 + midsVal * 10.0));
  float tearRand = hash(vec2(tearRow, glitchTime));
  float tearActive = step(1.0 - corruption * 0.6, tearRand);
  float tearDisp = (tearRand - 0.5) * 0.2 * tearActive;

  vec2 displaced = p + vec2(dispX + tearDisp, dispY);

  // Zoom
  vec2 zp = (displaced - 0.5) * (uZoom * 2.0 + 1.0) + 0.5;

  // === RGB CHANNEL SEPARATION ===
  float chromaSep = corruption * 0.03 * (1.0 + kickPulse * 2.0);
  float rOff = chromaSep * (hash(vec2(glitchTime, 1.0)) - 0.5) * 2.0;
  float gOff = chromaSep * (hash(vec2(glitchTime, 2.0)) - 0.5) * 2.0;
  float bOff = chromaSep * (hash(vec2(glitchTime, 3.0)) - 0.5) * 2.0;

  float r = cleanSignal(zp + vec2(rOff, 0.0), time).r;
  float g = cleanSignal(zp + vec2(0.0, gOff), time).g;
  float b = cleanSignal(zp + vec2(-bOff, bOff * 0.5), time).b;

  vec3 col = vec3(r, g, b);

  // === SCAN LINES ===
  float scanSpeed = time * 2.0;
  float scanLine = sin(p.y * uScanFreq * 500.0 + scanSpeed) * 0.5 + 0.5;
  scanLine = smoothstep(0.3, 0.7, scanLine);
  col *= 0.85 + scanLine * 0.15 * (1.0 + trebleVal);

  // Moving scan bar
  float scanBar = smoothstep(0.0, 0.02, abs(p.y - fract(time * 0.3)));
  scanBar = 1.0 - (1.0 - scanBar) * corruption * 0.3;
  col *= scanBar;

  // === NOISE INJECTION ===
  float staticNoise = hash(p * 500.0 + time * 100.0);
  float noiseAmount = corruption * 0.15 * (1.0 + kickPulse);
  col = mix(col, vec3(staticNoise), noiseAmount);

  // === COLOR QUANTIZATION (bit-crush) ===
  float levels = mix(256.0, 8.0, corruption * 0.5);
  col = floor(col * levels) / levels;

  // === DATA BLOCK COLORING ===
  float wrongColor = step(1.0 - corruption * 0.3, hash(blockCoord + glitchTime + vec2(53.0, 71.0)));
  vec3 wrongData = vec3(
    hash(blockCoord + glitchTime + vec2(100.0, 0.0)),
    hash(blockCoord + glitchTime + vec2(0.0, 100.0)),
    hash(blockCoord + glitchTime + vec2(100.0, 100.0))
  );
  col = mix(col, wrongData, wrongColor * 0.6);

  // === INTERLACE ARTIFACT ===
  float interlace = mod(floor(p.y * 400.0), 2.0);
  float interlaceShift = interlace * 0.002 * corruption;
  col.r = mix(col.r, cleanSignal(zp + vec2(interlaceShift, 0.0), time).r, interlace * corruption * 0.3);

  // Palette color shift
  float palShift = uPalette * 0.2;
  col = mix(col, col.gbr, palShift * 0.3);

  // Onset: major corruption burst
  float burstNoise = hash(p * 200.0 + onsetFlash * 50.0);
  col = mix(col, vec3(burstNoise), onsetFlash * 0.3);

  // Global intensity
  col *= uIntensity * 1.1 + energyVal * 0.15;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col.r, 0.0, 1.0), clamp(col.g, 0.0, 1.0), clamp(col.b, 0.0, 1.0), 1.0);
}

