  fishG += 0.0001 / fd18 * 0.7;
  fishB += 0.0001 / fd18 * 0.5;

  float fx19 = school2x + sin(time * 0.8 + 19.8) * 0.11;
  float fy19 = school2y + cos(time * 0.85 + 19.2) * 0.083;
  float fdx19 = p.x - fx19;
  float fdy19 = p.y - fy19;
  float fd19 = fdx19 * fdx19 + fdy19 * fdy19 + 0.0001;
  fishG += 0.0001 / fd19 * 0.75;
  fishB += 0.0001 / fd19 * 0.55;

  // Scale fish by bioluminescence
  fishR = fishR * uBioluminescence * uIntensity;
  fishG = fishG * uBioluminescence * uIntensity;
  fishB = fishB * uBioluminescence * uIntensity;

  // === WATER CAUSTICS ===
  float caustX = p.x * 8.0 + time * 0.3;
  float caustY = p.y * 8.0 - time * 0.2;
  float caustic1 = sin(caustX + sin(caustY * 0.8)) * 0.5 + 0.5;
  float caustic2 = sin(caustX * 1.3 - caustY * 0.7 + time * 0.4) * 0.5 + 0.5;
  float causticPattern = caustic1 * caustic2;
  float causticGlow = causticPattern * 0.03 * (uChaos + 0.3);

  // === PLANKTON SPARKLES ===
  float planktonGrid = 80.0;
  float pgx = p.x * planktonGrid;
  float pgy = p.y * planktonGrid;
  float pcx = fract(pgx) - 0.5;
  float pcy = fract(pgy) - 0.5;
  float pidx = pgx - pcx - 0.5;
  float pidy = pgy - pcy - 0.5;
  float ph = hash2d(pidx, pidy);
  float sparkleThresh = 0.96 - trebleSparkle * 0.04;
  float sparkle = smoothstep(sparkleThresh, 1.0, ph);
  float sparkleTwinkle = sin(time * 5.0 + ph * 6.28) * 0.5 + 0.5;
  float sparkleGlow = sparkle * sparkleTwinkle * 0.4;

  // === COMBINE ===
  float finalR = 0.005;
  float finalG = 0.008;
  float finalB = 0.025;

  // Add caustics
  finalR += causticGlow * 0.3;
  finalG += causticGlow * 0.5;
  finalB += causticGlow * 0.6;

  // Add bioluminescent creatures
  finalR += glowR;
  finalG += glowG;
  finalB += glowB;

  // Add predator-prey fish
  finalR += fishR;
  finalG += fishG;
  finalB += fishB;

  // Add plankton sparkles
  finalR += sparkleGlow * 0.5;
  finalG += sparkleGlow * 0.8;
  finalB += sparkleGlow * 1.0;

  // Beat pulse brightness
  float pulse = beatPulse * 0.12;
  finalR += pulse * 0.05;
  finalG += pulse * 0.08;
  finalB += pulse * 0.12;

  // Onset flash — bright underwater flash
  float flash = onsetFlash * 0.2;
  finalR += flash * 0.3;
  finalG += flash * 0.6;
  finalB += flash * 0.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uDistortionDepth;
uniform float uDesaturationWave;
uniform float uEdgeWaver;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p *= 2.1;
    a *= 0.5;
  }
  return v;
}

// Procedural "reality" scene: rooms, sky, objects
vec3 realityScene(vec2 uv, float time) {
  // Sky gradient
  vec3 sky = mix(vec3(0.4, 0.5, 0.7), vec3(0.15, 0.2, 0.4), uv.y * 0.5 + 0.5);

  // Horizon line
  float horizon = smoothstep(-0.02, 0.02, uv.y + 0.1);

  // Ground: tiled floor receding
  if (uv.y < -0.08) {
    float depth = 1.0 / (-uv.y + 0.01);
    float gx = uv.x * depth;
    float gz = depth + time * 0.5;

    // Checkerboard
    float checker = mod(floor(gx) + floor(gz), 2.0);
    vec3 floorCol = mix(vec3(0.3, 0.28, 0.25), vec3(0.45, 0.42, 0.38), checker);

    // Fade with distance
    float dist = min(depth / 20.0, 1.0);
    floorCol = mix(floorCol, sky, dist);

    return floorCol;
  }

  // Simple buildings / rectangles on horizon
  float buildingX = floor(uv.x * 5.0) / 5.0;
  float buildingHeight = hash(vec2(buildingX, 0.0)) * 0.3;
  float building = step(uv.y, buildingHeight - 0.1) * step(-0.1, uv.y);
  vec3 buildingCol = vec3(0.2, 0.2, 0.22) + hash(vec2(buildingX, 1.0)) * 0.1;

  // Windows
  float winX = fract(uv.x * 20.0);
  float winY = fract(uv.y * 15.0);
  float window = step(0.2, winX) * step(winX, 0.8) * step(0.2, winY) * step(winY, 0.8);
  float lit = step(0.5, hash(vec2(floor(uv.x * 20.0), floor(uv.y * 15.0))));
  vec3 windowColor = vec3(0.8, 0.7, 0.3) * window * lit * building;

  vec3 col = mix(sky, buildingCol, building);
  col += windowColor;

  // Clouds
  float cloud = fbm(vec2(uv.x * 2.0 + time * 0.05, uv.y * 3.0 + 0.5));
  cloud = smoothstep(0.4, 0.7, cloud) * step(0.0, uv.y);
  col = mix(col, vec3(0.7, 0.72, 0.75), cloud * 0.5);

  return col;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.5;
  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.2) * 0.04, cos(p.x * 3.5 + time * 0.15) * 0.04);

  // Audio-reactive modulators — 2x
  float bassVal = bass() * uSensitivity * 1.6;
  float midsVal = mids() * uSensitivity * 1.4;
  float trebleVal = treble() * uSensitivity * 1.6;
  float beatPulse = uBeat * uSensitivity * 2.0;
  float kickPulse = uKick * uSensitivity * 2.0;

  // === SCALE PULSING: subtly wrong zoom ===
  float scalePulse = 1.0 + sin(time * 0.7) * uDistortionDepth * 0.03;
  scalePulse += bassVal * uDistortionDepth * 0.02;
  scalePulse += sin(time * 2.3) * uDistortionDepth * 0.01;
  vec2 scaledP = p * scalePulse * (0.8 + uZoom * 0.4);

  // === EDGE WAVERING: slight displacement at edges ===
  float edgeAmount = uEdgeWaver * (0.5 + trebleVal);
  float waveX = sin(p.y * 15.0 + time * 3.0) * edgeAmount * 0.01;
  float waveY = cos(p.x * 12.0 + time * 2.5) * edgeAmount * 0.01;
  // More wavering at edges of screen
  float edgeDist = max(abs(p.x), abs(p.y));
  float edgeMult = smoothstep(0.3, 1.0, edgeDist);
  waveX *= edgeMult;
  waveY *= edgeMult;

  vec2 waveredP = scaledP + vec2(waveX, waveY);

  // === BREATHING DISTORTION: slow domain warp ===
  float breatheX = sin(waveredP.y * 3.0 + time * 0.5) * uDistortionDepth * 0.02;
  float breatheY = cos(waveredP.x * 2.5 + time * 0.4) * uDistortionDepth * 0.015;
  breatheX += bassVal * sin(time * 1.5) * 0.01;
  vec2 distortedP = waveredP + vec2(breatheX, breatheY);

  // === CHROMATIC ABERRATION that breathes ===
  float aberration = uDistortionDepth * 0.008 * (1.0 + sin(time * 0.8) * 0.5);
  aberration *= (0.5 + edgeDist); // stronger at edges
  aberration += kickPulse * 0.005; // kick reduces it briefly

  vec2 rUV = distortedP + normalize(distortedP + 0.001) * aberration;
  vec2 gUV = distortedP;
  vec2 bUV = distortedP - normalize(distortedP + 0.001) * aberration;

  // Sample reality scene
  vec3 rSample = realityScene(rUV, time);
  vec3 gSample = realityScene(gUV, time);
  vec3 bSample = realityScene(bUV, time);

  vec3 col = vec3(rSample.r, gSample.g, bSample.b);

  // === DESATURATION WAVES ===
  float desatWave = sin(p.y * 5.0 + time * 1.5) * 0.5 + 0.5;
  desatWave *= sin(p.x * 3.0 - time * 0.8) * 0.3 + 0.7;
  float desatAmount = uDesaturationWave * desatWave * (0.5 + midsVal);
  float gray = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(col, vec3(gray), desatAmount * 0.5);

  // === SUBTLE BRIGHTNESS PULSING ===
  float brightPulse = sin(time * 1.2) * 0.05 + sin(time * 3.7) * 0.02;
  col *= 1.0 + brightPulse;

  // === FOG OF UNREALITY: vignette that breathes ===
  float vigRadius = 0.8 + sin(time * 0.5) * 0.1 + bassVal * 0.1;
  float vig = smoothstep(vigRadius + 0.3, vigRadius - 0.2, length(p));
  col *= vig;

  // === BEAT: momentary blur/clarity shift ===
  // On beat: brief sharpening (remove aberration effect momentarily)
  vec3 cleanSample = realityScene(distortedP, time);
  col = mix(col, cleanSample, beatPulse * 0.3);

  // === KICK: reality snap back ===
  vec3 normalScene = realityScene(p * (0.8 + uZoom * 0.4), time);
  col = mix(col, normalScene, kickPulse * 0.5);

  // === COLOR SHIFT: palette driven — faster cycling ===
  col.r *= 1.0 + sin(time * 0.3 + uPalette + sin(uTime * 0.3) * 0.2) * 0.1;
  col.b *= 1.0 + cos(time * 0.25 + uPalette * 2.0 + sin(uTime * 0.3) * 0.2) * 0.1;

  // === NOISE FILM GRAIN ===
  float grain = (hash(p * 500.0 + fract(time * 60.0)) - 0.5) * 0.04 * uChaos;
  col += grain;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  // Intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

// Diamond distance (L1 norm)
float diamondDist(vec2 pp) {
  return abs(pp.x) + abs(pp.y);
}

// Zigzag wave
float zigzag(float x, float freq) {
  return abs(fract(x * freq) - 0.5) * 2.0;
}

// Huichol palette: hot pink, electric blue, sacred green, golden yellow
vec3 huicholColor(float t, float paletteShift) {
  t = fract(t + paletteShift * 0.25);
  vec3 colors[5];
  colors[0] = vec3(1.0, 0.08, 0.58);   // hot pink
  colors[1] = vec3(0.0, 0.45, 1.0);    // electric blue
  colors[2] = vec3(0.1, 0.85, 0.3);    // sacred green
  colors[3] = vec3(1.0, 0.85, 0.0);    // golden yellow
  colors[4] = vec3(1.0, 0.08, 0.58);   // wrap to pink
  float idx = t * 4.0;
  int i0 = int(floor(idx));
  float f = fract(idx);
  if (i0 == 0) return mix(colors[0], colors[1], f);
  if (i0 == 1) return mix(colors[1], colors[2], f);
  if (i0 == 2) return mix(colors[2], colors[3], f);
  return mix(colors[3], colors[4], f);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float bpmPulse = uBpmSin * uSensitivity;

  vec3 col = vec3(0.02, 0.01, 0.03);

  // Breathing scale
  float breathe = 1.0 + bpmPulse * 0.08 + bassVal * 0.05;
  vec2 bp = p / breathe;

  // Layer 1: Concentric diamonds pulsing outward
  float diamR = diamondDist(bp);
  float diamRings = sin(diamR * 12.0 - time * 2.0 + bassVal * 3.0) * 0.5 + 0.5;
  float diamSharp = smoothstep(0.48, 0.5, diamRings) - smoothstep(0.5, 0.52, diamRings);
  float diamWide = smoothstep(0.3, 0.5, diamRings);
  vec3 diamCol = huicholColor(diamR * 0.3 + time * 0.1, uPalette) * diamSharp * 1.5;
  diamCol += huicholColor(diamR * 0.5 - time * 0.05, uPalette + 0.5) * diamWide * 0.2;
  col += diamCol;

  // Layer 2: Zigzag antler lines (4-fold symmetry)
  vec2 ap = abs(bp);
  float antlerAngle = atan(ap.y, ap.x);
  float antlerR = length(ap);
  float zigFreq = 6.0 + midsVal * 4.0;
  float zig1 = zigzag(antlerAngle * 2.0 + time * 0.5, zigFreq);
  float zig2 = zigzag(antlerAngle * 3.0 - time * 0.3 + 1.0, zigFreq * 0.7);
  float antlerPattern = smoothstep(0.02, 0.0, abs(antlerR - zig1 * 0.5 - 0.3));
  antlerPattern += smoothstep(0.02, 0.0, abs(antlerR - zig2 * 0.4 - 0.6));
  vec3 antlerCol = huicholColor(antlerAngle * 0.5 + time * 0.15, uPalette + 0.25);
  col += antlerCol * antlerPattern * (1.0 + trebleVal * 0.8);

  // Layer 3: Radiating sun motif at center
  float sunAngle = atan(bp.y, bp.x);
  float sunR = length(bp);
  float rays = sin(sunAngle * 8.0 + time * 1.5) * 0.5 + 0.5;
  rays = pow(rays, 2.0 + bassVal * 3.0);
  float sunMask = smoothstep(0.6, 0.0, sunR);
  float sunCore = smoothstep(0.15, 0.0, sunR);
  vec3 sunCol = vec3(1.0, 0.85, 0.0) * rays * sunMask * 0.6;
  sunCol += vec3(1.0, 0.5, 0.1) * sunCore * (1.0 + kickVal * 2.0);
  col += sunCol;

  // Layer 4: Rotating sacred geometry overlay
  vec2 gp = rot2(time * 0.2 + energyVal * 0.5) * bp;
  float geoR = length(gp);
  float geoA = atan(gp.y, gp.x);
  float geo6fold = sin(geoA * 6.0) * 0.5 + 0.5;
  float geoRings = sin(geoR * 20.0 - time * 3.0) * 0.5 + 0.5;
  float geoLine = smoothstep(0.03, 0.0, abs(geoRings - 0.5)) * geo6fold;
  float geoRadial = smoothstep(0.01, 0.0, abs(sin(geoA * 12.0 + time)));
  geoRadial *= smoothstep(1.2, 0.2, geoR);
  vec3 geoCol = huicholColor(geoA * 0.3 + geoR * 0.2 + time * 0.1, uPalette + 0.7);
  col += geoCol * (geoLine + geoRadial * 0.3) * 0.5;

  // Layer 5: Peyote button circles
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float pAngle = fi * 1.2566 + time * 0.15;
    float pDist = 0.8 + sin(time * 0.3 + fi) * 0.15;
    vec2 pCenter = vec2(cos(pAngle), sin(pAngle)) * pDist;
    float pR = length(bp - pCenter);
    float pButton = smoothstep(0.18, 0.15, pR);
    float pRings = sin(pR * 30.0 - time * 2.0) * 0.5 + 0.5;
    float pDetail = smoothstep(0.48, 0.5, pRings);
    vec3 pCol = huicholColor(fi * 0.2 + pR * 2.0, uPalette) * (pButton * 0.4 + pDetail * 0.6);
    col += pCol * 0.5;
  }

  // Audio-reactive color wash
  col += huicholColor(time * 0.05, uPalette) * energyVal * 0.15;

  // Chaos: pattern distortion
  float chaosWarp = sin(p.x * 8.0 + p.y * 6.0 + time * 2.0) * uChaos * 0.1;
  col *= 1.0 + chaosWarp;

  // Spectral centroid hue shift
  float centroidShift = uSpectralCentroid * uSensitivity * 0.1;
  col.r += centroidShift * 0.05;
  col.g -= centroidShift * 0.03;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSlitCount;
uniform float uGratingAngle;
uniform float uOrderBrightness;

// Diffraction intensity for N slits: I = (sin(N*beta)/sin(beta))^2 / N^2
// where beta = pi * d * sin(theta) / lambda
float diffractionIntensity(float sinTheta, float d, float lambda, float N) {
  float pi = 3.14159265;
  float beta = pi * d * sinTheta / lambda;
  float sinBeta = sin(beta);
  float sinNBeta = sin(N * beta);

  // Handle zero division at principal maxima
  if (abs(sinBeta) < 0.001) return 1.0;

  float ratio = sinNBeta / (sinBeta * N);
  return ratio * ratio;
}

// Single slit envelope: sinc^2
float slitEnvelope(float sinTheta, float a, float lambda) {
  float pi = 3.14159265;
  float alpha = pi * a * sinTheta / lambda;
  if (abs(alpha) < 0.001) return 1.0;
  float s = sin(alpha) / alpha;
  return s * s;
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Slit count: 4 to 20, modulated by treble
  float N = floor(4.0 + uSlitCount * 16.0 + trebleVal * 6.0);

  // Grating angle: slow rotation + onset burst
  float angle1 = uGratingAngle * 3.14159 + time * 0.1 + onsetVal * 1.5;
  float angle2 = angle1 + 1.047; // +60 degrees
  float angle3 = angle1 + 2.094; // +120 degrees

  // Slit spacing modulated by bass
  float d = 2.0 + bassVal * 1.5;
  float a = 0.8; // slit width

  // For each grating orientation, compute diffraction
  // Grating 1
  float cosA1 = cos(angle1);
  float sinA1 = sin(angle1);
  float proj1 = p.x * cosA1 + p.y * sinA1;
  float sinTheta1 = proj1 * 0.5;

  // RGB wavelengths
  float lambdaR = 0.70;
  float lambdaG = 0.55;
  float lambdaB = 0.45;

  float envR1 = slitEnvelope(sinTheta1, a, lambdaR);
  float envG1 = slitEnvelope(sinTheta1, a, lambdaG);
  float envB1 = slitEnvelope(sinTheta1, a, lambdaB);

  float diffR1 = diffractionIntensity(sinTheta1, d, lambdaR, N) * envR1;
  float diffG1 = diffractionIntensity(sinTheta1, d, lambdaG, N) * envG1;
  float diffB1 = diffractionIntensity(sinTheta1, d, lambdaB, N) * envB1;

  // Grating 2 (rotated)
  float cosA2 = cos(angle2);
  float sinA2 = sin(angle2);
  float proj2 = p.x * cosA2 + p.y * sinA2;
  float sinTheta2 = proj2 * 0.5;

  float diffR2 = diffractionIntensity(sinTheta2, d * 1.1, lambdaR, N * 0.7) * slitEnvelope(sinTheta2, a, lambdaR);
  float diffG2 = diffractionIntensity(sinTheta2, d * 1.1, lambdaG, N * 0.7) * slitEnvelope(sinTheta2, a, lambdaG);
  float diffB2 = diffractionIntensity(sinTheta2, d * 1.1, lambdaB, N * 0.7) * slitEnvelope(sinTheta2, a, lambdaB);

  // Grating 3 (third angle, chaos-weighted)
  float cosA3 = cos(angle3);
  float sinA3 = sin(angle3);
  float proj3 = p.x * cosA3 + p.y * sinA3;
  float sinTheta3 = proj3 * 0.5;

  float chaosWeight = uChaos * 0.8;
  float diffR3 = diffractionIntensity(sinTheta3, d * 0.9, lambdaR, N * 0.5) * slitEnvelope(sinTheta3, a, lambdaR) * chaosWeight;
  float diffG3 = diffractionIntensity(sinTheta3, d * 0.9, lambdaG, N * 0.5) * slitEnvelope(sinTheta3, a, lambdaG) * chaosWeight;
  float diffB3 = diffractionIntensity(sinTheta3, d * 0.9, lambdaB, N * 0.5) * slitEnvelope(sinTheta3, a, lambdaB) * chaosWeight;

  // Combine gratings
  float colR = (diffR1 + diffR2 * uOrderBrightness + diffR3) * 0.4;
  float colG = (diffG1 + diffG2 * uOrderBrightness + diffG3) * 0.4;
  float colB = (diffB1 + diffB2 * uOrderBrightness + diffB3) * 0.4;

  // Palette hue shift
  float hueRot = uPalette * 0.2;
  float cosH = cos(hueRot);
  float sinH = sin(hueRot);
  float rr = colR * cosH - colG * sinH;
  float gg = colR * sinH + colG * cosH;
  colR = rr;
  colG = gg;

  // Beat pulse on central fringe
  float centralBoost = beatPulse * 0.4 * exp(-length(p) * 2.0);
  colR += centralBoost;
  colG += centralBoost;
  colB += centralBoost;

  // Onset flash
  colR += onsetVal * 0.2;
  colG += onsetVal * 0.2;
  colB += onsetVal * 0.25;

  // Energy vibrancy
  float vibrancy = 1.0 + energyVal * 0.3;
  colR *= vibrancy;
  colG *= vibrancy;
  colB *= vibrancy;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(colR, colG, colB)); colR = _pc.r; colG = _pc.g; colB = _pc.b; }
  gl_FragColor = vec4(
    clamp(colR * brightness, 0.0, 1.0),
    clamp(colG * brightness, 0.0, 1.0),
    clamp(colB * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGhostCount;
uniform float uPhaseSpeed;
uniform float uSeparation;

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p, float t) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * valueNoise(p * freq + vec2(t * 0.3 * float(i + 1)));
    freq *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Base scene: swirling fractal pattern
vec3 baseScene(vec2 uv, float t, float palette) {
  float n1 = fbm(uv * 3.0 + vec2(t * 0.2, t * 0.15), t);
  float n2 = fbm(uv * 3.0 + vec2(n1 * 2.0, t * 0.1), t * 0.7);
  float n3 = fbm(uv * 2.0 + vec2(n2 * 1.5, n1 * 1.5), t * 0.5);

  float r = length(uv);
  float swirl = sin(atan(uv.y, uv.x) * 3.0 + r * 8.0 - t * 1.5 + n3 * 4.0);
  swirl = swirl * 0.5 + 0.5;

  // Color from noise
  float hue = fract(n2 * 0.5 + palette * 0.2 + t * 0.02);
  float h6 = hue * 6.0;
  vec3 col = vec3(
    abs(mod(h6, 6.0) - 3.0) - 1.0,
    abs(mod(h6 + 4.0, 6.0) - 3.0) - 1.0,
    abs(mod(h6 + 2.0, 6.0) - 3.0) - 1.0
  );
  col = clamp(col, 0.0, 1.0);

  float val = n3 * 0.6 + swirl * 0.4;
  return col * val;
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  float phaseT = time * uPhaseSpeed;
  float sep = uSeparation * 0.15 * (1.0 + bassVal * 1.5 + onsetVal * 2.0);
  // Beat snaps ghosts together
  sep *= (1.0 - beatPulse * 0.6);

  // Ghost 0: center (main)
  vec3 ghost0 = baseScene(p, time, uPalette);

  // Ghost 1: offset by oscillating phase
  vec2 offset1 = vec2(
    sin(phaseT * 1.3 + 0.0) * sep,
    cos(phaseT * 0.9 + 1.0) * sep * 0.7
  );
  // Treble shimmer on offset
  offset1 += vec2(
    sin(time * 8.0) * trebleVal * 0.01,
    cos(time * 9.0) * trebleVal * 0.01
  );
  vec3 ghost1 = baseScene(p + offset1, time + 0.5, uPalette + 0.33);
  // Tint ghost1 toward cyan
  ghost1 *= vec3(0.5, 0.9, 1.0);

  // Ghost 2: opposite phase offset
  vec2 offset2 = vec2(
    sin(phaseT * 1.1 + 2.1) * sep * 1.2,
    cos(phaseT * 1.4 + 3.7) * sep * 0.9
  );
  offset2 += vec2(
    cos(time * 7.0) * trebleVal * 0.01,
    sin(time * 10.0) * trebleVal * 0.01
  );
  vec3 ghost2 = baseScene(p + offset2, time + 1.0, uPalette + 0.67);
  // Tint ghost2 toward magenta
  ghost2 *= vec3(1.0, 0.5, 0.85);

  // Blend: weight by ghost count
  float g1Weight = smoothstep(1.5, 2.0, uGhostCount);
  float g2Weight = smoothstep(2.5, 3.0, uGhostCount);

  vec3 col = ghost0 * 0.6;
  col += ghost1 * 0.5 * g1Weight;
  col += ghost2 * 0.4 * g2Weight;

  // Chaos: random per-pixel ghost jitter
  float chaosJitter = (hash21(vUv * 100.0 + time) - 0.5) * uChaos * 0.05;
  col += col * chaosJitter;

  // Beat brightness
  col += col * beatPulse * 0.3;

  // Onset flash
  col += vec3(onsetVal * 0.25);

  // Energy boost
  col *= 1.0 + energyVal * 0.2;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uDotSize;
uniform float uRotationSpeed;
uniform float uColorShift;
uniform float uGridDensity;

// HSV to RGB helper
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.25) * uRotationSpeed;

  // Audio-reactive modulators
  float bassPulse = bass() * uSensitivity * 1.0;
  float midsHue = mids() * uSensitivity * 0.5;
  float trebleSparkle = treble() * uSensitivity * 0.7;
  float onsetFlash = uOnset * uSensitivity * 2.5;
  float kickBurst = uKick * uSensitivity * 1.0;

  // Psychedelic distortion: warp the UV coordinates
  float warpAmt = uChaos * 0.15 + bassPulse * 0.08;
  vec2 wp = p;
  wp.x += sin(p.y * 4.0 + time * 1.2) * warpAmt;
  wp.y += cos(p.x * 3.5 + time * 0.9) * warpAmt;
  // Second warp layer for extra trippy feel
  wp.x += sin(wp.y * 8.0 - time * 0.7) * warpAmt * 0.3;
  wp.y += cos(wp.x * 7.0 + time * 0.5) * warpAmt * 0.3;

  // Rotate UV coordinates to simulate ball spinning
  float cosT = cos(time);
  float sinT = sin(time);
  float rx = wp.x * cosT - wp.y * sinT;
  float ry = wp.x * sinT + wp.y * cosT;

  // Second rotation layer (slower, different axis)
  float time2 = time * 0.3 + 1.5;
  float cosT2 = cos(time2);
  float sinT2 = sin(time2);
  float rx2 = rx * cosT2 - ry * sinT2;
  float ry2 = rx * sinT2 + ry * cosT2;

  // Third rotation layer for trippy effect
  float time3 = time * 0.17 + 3.7;
  float cosT3 = cos(time3);
  float sinT3 = sin(time3);
  float rx3 = rx2 * cosT3 - ry2 * sinT3 * 0.5;
  float ry3 = rx2 * sinT3 * 0.5 + ry2 * cosT3;

  // === DOT GRID ===
  float gridX = rx3 * uGridDensity;
  float gridY = ry3 * uGridDensity;

  // Cell coordinates (fractional part = position within cell)
  float cellX = fract(gridX) - 0.5;
  float cellY = fract(gridY) - 0.5;

  // Distance from cell center
  float cellDist = cellX * cellX + cellY * cellY;

  // Dot radius: base + audio pulse (more aggressive)
  float dotRadius = uDotSize * 0.06 + bassPulse * 0.05 + kickBurst * 0.03;
  float dotVal = smoothstep(dotRadius, dotRadius * 0.2, cellDist);

  // Soft glow halo around each dot (for afterglow/trails)
  float glowRadius = dotRadius * 4.0;
  float dotGlow = smoothstep(glowRadius, glowRadius * 0.1, cellDist) * 0.35;

  // === DOT COLOR ===
  float cellIdX = sin((gridX - cellX) * 127.1);
  float cellIdY = sin((gridY - cellY) * 311.7);
  float cellHash = fract(cellIdX * cellIdY * 43758.5453);

  // Rainbow hue rotation: cycle through full spectrum over time
  float rainbowCycle = time * 0.15;
  float dotHue = fract(
    cellHash * uColorShift
      + rainbowCycle
      + uPalette * 0.1
      + midsHue
      + sin(cellHash * 6.28 + time * 0.8) * 0.15  // individual shimmer
  );

  // High saturation for psychedelic colors
  float dotSat = 0.85 + sin(cellHash * 50.0 + time * 2.0) * 0.15;
  // Value pulses aggressively
  float dotBrightness = 0.8 + bassPulse * 0.3 + sin(cellHash * 80.0 + time * 4.0) * 0.2;

  vec3 dotColor = hsv2rgb(vec3(dotHue, dotSat, clamp(dotBrightness, 0.0, 1.0)));

  // === SPARKLE (more aggressive shimmer) ===
  float sparkle = sin(cellHash * 100.0 + time * 5.0) * 0.5 + 0.5;
  sparkle *= sin(cellHash * 77.0 + time * 3.7) * 0.5 + 0.5;
  float sparkleIntensity = sparkle * (uChaos * 0.6 + trebleSparkle * 0.5);

  // Second sparkle layer: fast flicker
  float sparkle2 = pow(sin(cellHash * 200.0 + time * 8.0) * 0.5 + 0.5, 4.0);
  sparkleIntensity += sparkle2 * trebleSparkle * 0.4;

  // === AFTERGLOW TRAILS (color smear from previous positions) ===
  // Offset UVs backward in rotation to sample "where dots were"
  float trailTime = time - 0.15;
  float cosTrail = cos(trailTime);
  float sinTrail = sin(trailTime);
  float trx = wp.x * cosTrail - wp.y * sinTrail;
  float ttry = wp.x * sinTrail + wp.y * cosTrail;
  float trailTime2 = trailTime * 0.3 + 1.5;
  float trx2 = trx * cos(trailTime2) - ttry * sin(trailTime2);
  float try2 = trx * sin(trailTime2) + ttry * cos(trailTime2);

  float tgx = trx2 * uGridDensity;
  float tgy = try2 * uGridDensity;
  float tcx = fract(tgx) - 0.5;
  float tcy = fract(tgy) - 0.5;
  float trailDist = tcx * tcx + tcy * tcy;
  float trail = smoothstep(dotRadius * 3.0, dotRadius * 0.3, trailDist) * 0.3;

  // Trail color (slightly shifted hue for motion rainbow)
  float trailHash = fract(sin((tgx - tcx) * 127.1) * sin((tgy - tcy) * 311.7) * 43758.5453);
  float trailHue = fract(trailHash * uColorShift + rainbowCycle - 0.05);
  vec3 trailColor = hsv2rgb(vec3(trailHue, 0.7, 0.6));

  // === COMBINE ===
  float brightness = uIntensity * 1.5 + onsetFlash * 0.4 + kickBurst * 0.3;

  vec3 finalColor = dotColor * dotVal * brightness
    + dotColor * dotGlow * brightness * 0.5
    + vec3(sparkleIntensity) * dotVal * 0.4
    + trailColor * trail * brightness * 0.6;

  // Beat pulse on all dots (rainbow white flash)
  float beatPulse = uBeat * uSensitivity * 0.15 * (dotVal + dotGlow * 0.5);

  // Kick: white burst
  float kickWhite = kickBurst * 0.15 * dotVal;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.r + beatPulse + kickWhite, 0.0, 1.0),
    clamp(finalColor.g + beatPulse + kickWhite, 0.0, 1.0),
    clamp(finalColor.b + beatPulse + kickWhite, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPetalLayers;
uniform float uBloomRate;
uniform float uJewelDensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Flower of life sacred geometry pattern
float flowerOfLife(vec2 p, float scale) {
  float d = 1e10;
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * 1.0472;
    vec2 center = vec2(cos(angle), sin(angle)) * scale;
    d = min(d, abs(length(p - center) - scale));
  }
  d = min(d, abs(length(p) - scale));
  return d;
}

// Metatron's cube: overlapping circles + lines
float metatronsCube(vec2 p, float scale) {
  float d = flowerOfLife(p, scale);
  // Add connecting lines (hexagonal)
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * 1.0472;
    vec2 dir = vec2(cos(angle), sin(angle));
    float lineDist = abs(dot(p, vec2(-dir.y, dir.x)));
    d = min(d, lineDist);
  }
  return d;
}

// Petal shape using polar coordinates
float petalShape(vec2 p, float petals, float phase) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float petal = abs(cos(a * petals * 0.5 + phase));
  petal = pow(petal, 0.5);
  return r - petal * 0.8;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);
  float r = length(p);
  float angle = atan(p.y, p.x);

  // === EXTRA DOMAIN WARPING ===
  p += vec2(sin(p.y * 3.0 + time * 0.7) * 0.06, cos(p.x * 3.5 + time * 0.6) * 0.06) * (1.0 + bassVal * 0.5);
  p += vec2(cos(length(p) * 5.0 - time * 0.4) * 0.03, sin(length(p) * 4.0 + time * 0.5) * 0.03);

  // === BREATHING ===
  float breathe = 1.0 + sin(time * 1.2 * uBloomRate) * 0.12 + bassVal * 0.3;
  p *= breathe;

  // === SLOW ROTATION ===
  float rot = time * 0.25;
  float cr = cos(rot); float sr = sin(rot);
  p = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

  // === PETAL LAYERS ===
  for (int i = 0; i < 10; i++) {
    if (float(i) >= uPetalLayers) break;
    float fi = float(i);
    float layerScale = 1.0 - fi * 0.08;
    float layerPhase = time * (0.2 + fi * 0.05) + fi * 0.523;

    // Bass triggers bloom — each layer unfolds at different bass thresholds
    float bloomThreshold = fi / uPetalLayers;
    float bloomAmt = smoothstep(bloomThreshold * 0.3, bloomThreshold * 0.3 + 0.2, bassVal + 0.5);

    // Petal count increases with layer depth
    float petalCount = 5.0 + fi * 2.0 + uChaos * 3.0;

    vec2 lp = p * layerScale;
    float layerRot = fi * 0.314 + time * 0.08 * (1.0 + fi * 0.1);
    float clr = cos(layerRot); float slr = sin(layerRot);
    lp = vec2(lp.x * clr - lp.y * slr, lp.x * slr + lp.y * clr);

    float lr = length(lp);
    float la = atan(lp.y, lp.x);

    // Petal shape
    float petal = abs(cos(la * petalCount * 0.5 + layerPhase));
    petal = pow(petal, 0.4 + fi * 0.1);
    float petalEdge = smoothstep(petal * (0.4 + bloomAmt * 0.4), petal * (0.4 + bloomAmt * 0.4) - 0.02, lr);
    float petalGlow = petalEdge * (1.0 - fi / 10.0) * 0.6;

    // Edge sparkle from treble — 2x audio reactivity
    float edgeDist = abs(lr - petal * (0.4 + bloomAmt * 0.4));
    float edgeSparkle = exp(-edgeDist * (40.0 + trebleVal * 120.0)) * trebleVal * 1.0;

    // Color per layer: deep purples -> magentas -> golds -> electric blues — faster cycling
    float hue = fi / uPetalLayers * 0.6 + uPalette * 0.1 + midsVal * 0.4 + time * 0.08 + sin(uTime * 0.3) * 0.2;
    vec3 petalCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.15, 0.4)));
    // Push toward purples/magentas/golds
    petalCol.r = petalCol.r * 0.8 + 0.2;
    petalCol.b = petalCol.b * 0.7 + 0.3;

    col += petalCol * petalGlow;
    col += vec3(0.95, 0.9, 1.0) * edgeSparkle;
  }

  // === SACRED GEOMETRY CORE ===
  float sacredScale = 0.25 + bassVal * 0.2;
  float flowerD = flowerOfLife(p, sacredScale);
  float sacredGlow = exp(-flowerD * 25.0) * 0.4;
  float metaD = metatronsCube(p, sacredScale * 0.6);
  float metaGlow = exp(-metaD * 20.0) * 0.3;

  vec3 sacredCol = vec3(1.0, 0.85, 0.5); // Gold
  col += sacredCol * (sacredGlow + metaGlow);

  // === JEWELED HIGHLIGHTS ===
  float jewels = 0.0;
  for (int i = 0; i < 24; i++) {
    float fi = float(i);
    float ja = fi * 0.618033 * 6.2832 + time * 0.3;
    float jr = 0.15 + fi * 0.035 + sin(time + fi * 1.7) * 0.03;
    vec2 jp = vec2(cos(ja), sin(ja)) * jr;
    float d = length(p - jp);
    jewels += exp(-d * d * (300.0 + uJewelDensity * 400.0)) * uJewelDensity;
  }
  // Jewel colors shift with mids
  vec3 jewelCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * (midsVal * 0.5 + time * 0.1) + vec3(0.0, 0.2, 0.5)));
  col += jewelCol * jewels * 0.6;

  // === CENTRAL GLOW ===
  float coreR = length(p);
  float core = exp(-coreR * coreR * 6.0) * (0.6 + bassVal * 0.6);
  col += vec3(1.0, 0.9, 0.95) * core;

  // === ONSET: reveal new layers flash ===
  col += vec3(1.0, 0.8, 0.9) * onsetFlash * 0.5;

  // === BEAT PULSE === — 2x reactivity
  col *= 1.0 + beatPulse * 0.3;

  // Extreme contrast curves
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.95), col);

  // Overall intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTunnelSpeed;
uniform float uGeometryComplexity;
uniform float uWarpAmount;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(41.1, 289.7))) * 13758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Fractal tilework pattern for tunnel walls
float tilework(vec2 p, float complexity) {
  float d = 0.0;
  float scale = 1.0;
  float amp = 1.0;
  for (int i = 0; i < 6; i++) {
    if (float(i) >= complexity) break;
    vec2 gp = fract(p * scale) - 0.5;
    // Hexagonal tile pattern
    float hex = max(abs(gp.x) * 0.866 + abs(gp.y) * 0.5, abs(gp.y));
    float tile = smoothstep(0.45, 0.47, hex);
    d += tile * amp;
    // Add cross pattern
    float crossP = min(abs(gp.x), abs(gp.y));
    d += smoothstep(0.03, 0.01, crossP) * amp * 0.3;
    scale *= 2.0;
    amp *= 0.5;
  }
  return d;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === EXTRA DOMAIN WARPING ===
  p += vec2(sin(p.y * 4.0 + time * 0.8) * 0.05, cos(p.x * 3.5 + time * 0.7) * 0.05) * (1.0 + bassVal * 0.5);
  p += vec2(cos(length(p) * 6.0 - time * 0.5) * 0.03, sin(length(p) * 5.0 + time * 0.4) * 0.03);

  // === TUNNEL COORDINATES ===
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Bass warps tunnel diameter — 2x audio reactivity
  float tunnelR = r * (1.0 + sin(angle * 3.0 + time) * uWarpAmount * (1.0 + bassVal * 1.0));

  // Tunnel depth — infinite zoom feeling — 2x audio
  float forwardSpeed = uTunnelSpeed * (1.0 + beatPulse * 1.0 + energyVal * 0.6);
  float depth = 1.0 / (tunnelR + 0.01) - time * forwardSpeed * 3.0;
  depth -= beatPulse * 0.8;

  // Tunnel UV for wall patterns
  vec2 tunnelUV = vec2(angle / 6.2832 + 0.5, fract(depth * 0.15));

  // === TUNNEL WALL PATTERNS === — 2x treble/energy reactivity
  float complexity = uGeometryComplexity + trebleVal * 4.0 + energyVal * 2.0;
  float wallPattern = tilework(tunnelUV * 4.0, complexity);

  // Rotating geometric overlay
  float geoAngle = angle + time * 0.2;
  float geoR = fract(depth * 0.3);
  float geo = 0.0;
  // Triangles
  float triAngle = mod(geoAngle, 2.094) - 1.047;
  geo += smoothstep(0.02, 0.0, abs(geoR - 0.5) - abs(triAngle) * 0.3) * 0.4;
  // Hexagons
  float hexAngle = mod(geoAngle, 1.047) - 0.524;
  geo += smoothstep(0.02, 0.0, abs(geoR - 0.3) - 0.15 + abs(hexAngle) * 0.1) * 0.3;

  // === TUNNEL WALL COLOR ===
  // Deep space blues/purples at low energy -> neon greens/cyans at high energy
  float energyHue = mix(0.7, 0.4, energyVal); // purple->cyan
  float hue = energyHue + uPalette * 0.1 + midsVal * 0.2 + fract(depth * 0.05) * 0.1 + sin(uTime * 0.3) * 0.2;
  vec3 wallCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.1, 0.2)));

  // Add neon green at high energy — 2x
  wallCol = mix(wallCol, vec3(0.2, 1.0, 0.6), energyVal * 0.6);

  // Wall illumination — brighter near center
  float wallLight = exp(-tunnelR * 2.0) * 0.5 + wallPattern * 0.4 + geo * 0.3;
  col += wallCol * wallLight;

  // === EDGE GLOW — neon lines on tunnel walls ===
  float edgeGlow = exp(-abs(tunnelR - 0.5) * 8.0) * 0.3;
  edgeGlow += exp(-abs(tunnelR - 0.3) * 12.0) * 0.2;
  vec3 edgeCol = vec3(0.3, 0.8, 1.0); // Cyan edge
  col += edgeCol * edgeGlow * (1.0 + trebleVal * 1.0);

  // === STREAKING STARS ===
  for (int i = 0; i < 20; i++) {
    float fi = float(i);
    float starAngle = hash21(vec2(fi, 0.0)) * 6.2832;
    float starR = hash21(vec2(fi, 1.0)) * 0.8 + 0.1;
    float starDepth = fract(hash21(vec2(fi, 2.0)) + time * forwardSpeed * 0.5);

    // Star position in tunnel space
    vec2 starPos = vec2(cos(starAngle), sin(starAngle)) * starR * (1.0 - starDepth);
    float d = length(p - starPos);

    // Streak along radial direction (motion blur)
    vec2 streakDir = normalize(starPos);
    float streakDist = abs(dot(p - starPos, vec2(-streakDir.y, streakDir.x)));
    float streakLen = dot(p - starPos, streakDir);
    float streak = exp(-streakDist * streakDist * 2000.0) *
                   smoothstep(0.15, 0.0, streakLen) *
                   smoothstep(-0.01, 0.0, streakLen + 0.15);
    streak *= starDepth; // Fade with depth

    col += vec3(0.9, 0.95, 1.0) * streak * 0.4;
    // Point star
    col += vec3(1.0) * exp(-d * d * 5000.0) * starDepth * 0.3;
  }

  // === FRACTAL GEOMETRY flying past ===
  float fractalD = fract(depth * 0.2);
  float fractalAngle = angle * (3.0 + sin(time * 0.3) * uChaos * 2.0);
  float fractal = sin(fractalAngle * 5.0) * sin(fractalD * 20.0);
  fractal = smoothstep(0.9, 1.0, fractal) * exp(-tunnelR * 3.0);
  col += vec3(0.5, 0.3, 1.0) * fractal * 0.3;

  // === CENTER BRIGHT CORE ===
  float core = exp(-r * r * 15.0) * (0.4 + beatPulse * 0.6);
  col += vec3(0.8, 0.9, 1.0) * core;

  // Onset flash — 2x
  col += vec3(0.6, 1.0, 0.8) * onsetFlash * 0.4;

  // Beat pulse — 2x
  col *= 1.0 + beatPulse * 0.3;

  // Extreme contrast curves
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  // Overall intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uHelixTwist;
uniform float uUnzipForce;
uniform float uBasePairGap;
uniform float uPhosphorGlow;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 chromaColor(float idx) {
  // Map chroma bins to colors (C=red through B=violet)
  float hue = idx / 12.0;
  vec3 c = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.33, 0.67)));
  return c;
}

float getChroma(float idx) {
  int i = int(mod(idx, 12.0));
  if (i == 0) return uChroma0;
  if (i == 1) return uChroma1;
  if (i == 2) return uChroma2;
  if (i == 3) return uChroma3;
  if (i == 4) return uChroma4;
  if (i == 5) return uChroma5;
  if (i == 6) return uChroma6;
  if (i == 7) return uChroma7;
  if (i == 8) return uChroma8;
  if (i == 9) return uChroma9;
  if (i == 10) return uChroma10;
  return uChroma11;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / max(uZoom * 0.8 + 0.3, 0.1);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float bpmVal = uBpmSin;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.005, 0.01, 0.03);

  // Helix parameters
  float twist = uHelixTwist * 8.0;
  float rotation = time * 0.5 + bpmVal * 0.5;
  float helixRadius = 0.25 + bassVal * 0.05;
  float numPairs = 30.0;
  float gap = uBasePairGap * 0.06;

  // Unzip zone: moves along helix with kick
  float unzipCenter = sin(time * 0.3) * 0.5;
  float unzipWidth = 0.3 + kickVal * uUnzipForce * 0.5;

  // Draw helix rungs (base pairs) along Y axis
  for (float i = 0.0; i < 30.0; i++) {
    float t = (i / numPairs) * 2.0 - 1.0; // -1 to 1 along helix
    float yPos = t * 1.2;

    // Twist angle at this position
    float angle = t * twist + rotation;
    float ca = cos(angle);
    float sa = sin(angle);

    // Two backbone positions
    vec2 strand1 = vec2(ca * helixRadius, yPos);
    vec2 strand2 = vec2(-ca * helixRadius, yPos);

    // Unzip separation
    float unzipDist = abs(t - unzipCenter);
    float unzipAmt = smoothstep(unzipWidth, 0.0, unzipDist) * (kickVal + energyVal * 0.3);
    float separation = unzipAmt * uUnzipForce * 0.3;

    strand1.x += separation;
    strand2.x -= separation;

    // Floating away when unzipped
    float drift = unzipAmt * sin(time * 2.0 + i * 3.0) * 0.1;
    strand1 += vec2(drift, drift * 0.5);
    strand2 -= vec2(drift, drift * 0.3);

    // Backbone spheres
    float d1 = length(p - strand1);
    float d2 = length(p - strand2);
    float backbone1 = exp(-d1 * 40.0) * uPhosphorGlow;
    float backbone2 = exp(-d2 * 40.0) * uPhosphorGlow;

    vec3 backboneCol = mix(vec3(0.1, 0.5, 0.9), vec3(0.2, 0.8, 1.0), sa * 0.5 + 0.5);
    col += backboneCol * (backbone1 + backbone2);

    // Base pair bridge (colored by chroma)
    if (unzipAmt < 0.5) {
      float chromaIdx = mod(i, 12.0);
      float chromaVal = getChroma(chromaIdx);
      vec3 baseCol = chromaColor(chromaIdx) * (0.3 + chromaVal * 0.7);

      // Line between strands
      vec2 midpoint = (strand1 + strand2) * 0.5;
      vec2 dir = normalize(strand2 - strand1);
      vec2 toP = p - strand1;
      float proj = clamp(dot(toP, dir), 0.0, length(strand2 - strand1));
      vec2 closest = strand1 + dir * proj;
      float lineDist = length(p - closest);
      float bridge = exp(-lineDist * 60.0) * (1.0 - unzipAmt * 2.0);

      col += baseCol * bridge * 0.6 * (0.5 + midsVal * 0.5);

      // Base pair nodes (A-T or G-C pairs)
      float pairOffset = gap + 0.03;
      vec2 nodeA = strand1 + dir * pairOffset;
      vec2 nodeB = strand2 - dir * pairOffset;
      float nA = exp(-length(p - nodeA) * 50.0);
      float nB = exp(-length(p - nodeB) * 50.0);
      col += baseCol * (nA + nB) * 0.5;
    }
  }

  // Backbone helix curves (continuous glow)
  for (float t = -1.0; t < 1.0; t += 0.02) {
    float angle = t * twist + rotation;
    vec2 s1 = vec2(cos(angle) * helixRadius, t * 1.2);
    vec2 s2 = vec2(-cos(angle) * helixRadius, t * 1.2);
    float d1 = length(p - s1);
    float d2 = length(p - s2);
    float curve = exp(-d1 * 30.0) + exp(-d2 * 30.0);
    col += vec3(0.05, 0.15, 0.3) * curve * 0.1;
  }

  // Floating nucleotide particles when unzipped
  for (float i = 0.0; i < 20.0; i++) {
    float driftT = fract(time * 0.2 + hash(vec2(i, 3.0)));
    vec2 pp = vec2(hash(vec2(i, 0.0)) * 2.0 - 1.0, hash(vec2(0.0, i)) * 2.0 - 1.0);
    pp += vec2(sin(time + i), cos(time * 0.7 + i)) * 0.3 * driftT;
    float pd = length(p - pp);
    float particle = exp(-pd * 50.0) * kickVal * 0.5;
    col += chromaColor(mod(i, 12.0)) * particle;
  }

  // Treble sparkle along backbone
  col += vec3(0.5, 0.8, 1.0) * trebleVal * 0.05;

  // Harmonicity glow
  col += vec3(0.02, 0.06, 0.1) * uHarmonicity * uSensitivity;

  // Kick flash
  col = mix(col, col * 1.8 + vec3(0.02, 0.05, 0.1), kickVal * 0.3);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uWarpStrength;
uniform float uLacunarity;
uniform float uGain;

// 2D hash-based noise (value noise)
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Smooth value noise 2D
float noise2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  // Smooth interpolation (cubic Hermite)
  vec2 u = f * f * (3.0 - f * 2.0);

  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// FBM with 5 octaves
float fbm(vec2 p, float time) {
  float value = 0.0;
  float amplitude = 0.5;

  // Octave 1
  vec2 p1 = p;
  float n1 = noise2(p1 + vec2(time * 0.1, time * 0.13));
  value += n1 * amplitude;
  vec2 p2 = p1 * uLacunarity;
  amplitude *= uGain;

  // Octave 2
  float n2 = noise2(p2 + vec2(time * 0.17, time * 0.11));
  value += n2 * amplitude;
  vec2 p3 = p2 * uLacunarity;
  amplitude *= uGain;

  // Octave 3
  float n3 = noise2(p3 + vec2(time * 0.07, -time * 0.09));
  value += n3 * amplitude;
  vec2 p4 = p3 * uLacunarity;
  amplitude *= uGain;

  // Octave 4
  float n4 = noise2(p4 + vec2(-time * 0.13, time * 0.06));
  value += n4 * amplitude;
  vec2 p5 = p4 * uLacunarity;
  amplitude *= uGain;

  // Octave 5
  float n5 = noise2(p5 + vec2(time * 0.03, -time * 0.05));
  value += n5 * amplitude;

  return value;
}

// Cosine palette (Inigo Quilez technique), component-wise.
// color(t) = a + b * cos(2pi(c*t + d))
vec3 cosinePalette(float t, float ax, float ay, float az,
                   float bx, float by, float bz,
                   float cx, float cy, float cz,
                   float dx, float dy, float dz) {
  float tau = 6.28318;
  float r = ax + bx * cos(tau * (cx * t + dx));
  float g = ay + by * cos(tau * (cy * t + dy));
  float b = az + bz * cos(tau * (cz * t + dz));
  return vec3(r, g, b);
}

void main() {
  vec2 p = (vUv - 0.5) * ((uZoom + 0.5) * 4.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio modulation
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  // Triple domain warp: p' = fbm(p + fbm(p + fbm(p)))
  // Layer 1: base warp
  float warp1Val = fbm(p, time);
  vec2 warp1 = vec2(warp1Val, fbm(p + vec2(5.2, 1.3), time));

  // Layer 2: warp the warp (with audio modulation)
  vec2 p2 = p + warp1 * uWarpStrength * (1.0 + bassVal * 0.5);
  float warp2Val = fbm(p2, time * 1.3);
  vec2 warp2 = vec2(warp2Val, fbm(p2 + vec2(1.7, 9.2), time * 1.3));

  // Layer 3: triple warp for maximum organic complexity
  vec2 p3 = p + warp2 * (uWarpStrength * (uChaos + 0.5)) * (1.0 + midsVal * 0.3);
  float finalNoise = fbm(p3, time * 0.8);

  // Displacement magnitude for coloring
  float displacement = warp2.x * warp2.x + warp2.y * warp2.y;

  // Cosine palette -- shifts with palette param and time
  float palOffset = uPalette * 0.1 + time * 0.02;
  float colorVal = finalNoise + displacement * 0.5 + palOffset;

  // Palette A: warm psychedelic (deep purple -> hot pink -> gold -> teal)
  vec3 baseColor = cosinePalette(
    colorVal,
    0.5, 0.5, 0.5,
    0.5, 0.5, 0.5,
    1.0, 1.0, 1.0,
    0.0, 0.33, 0.67
  );

  // Apply treble as sparkle highlights
  float sparkle = trebleVal * (finalNoise * 3.0 - 1.5);

  // Beat pulse brightens the whole thing
  vec3 finalCol = baseColor * (uIntensity * 1.5)
    + vec3(sparkle, sparkle * 0.8, sparkle * 0.6)
    + vec3(beatPulse * 0.15, beatPulse * 0.1, beatPulse * 0.2);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSnapSharpness;
uniform float uMandalaComplexity;
uniform float uChaosDepth;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p, int octaves) {
  float val = 0.0, amp = 0.5;
  for (int i = 0; i < 7; i++) {
    if (i >= octaves) break;
    val += amp * noise(p);
    p *= 2.1;
    amp *= 0.5;
  }
  return val;
}

float mandala(vec2 p, float folds, float detail) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  a = mod(a + 6.2832, sector);
  a = abs(a - sector * 0.5);
  vec2 mp = vec2(cos(a), sin(a)) * r;
  float pattern = 0.0;
  for (float i = 1.0; i <= 5.0; i += 1.0) {
    if (i > detail * 5.0 + 1.0) break;
    float ring = abs(sin(r * i * 8.0 - mp.x * 4.0));
    ring = pow(ring, 3.0);
    float petal = abs(sin(a * folds * i * 0.5));
    pattern += ring * petal / i;
  }
  return pattern;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  // Snap cycle: golden ratio intervals for dopamine hits
  float beatCount = floor(time * uBpm / 60.0 + 0.5);
  float snapPhase = fract(beatCount * 0.618033);
  float isSnap = smoothstep(0.78, 0.82, snapPhase) + kickVal * uSnapSharpness;
  isSnap = clamp(isSnap, 0.0, 1.0);

  // Chaotic morphing noise field
  float chaosAmount = (1.0 - isSnap) * uChaosDepth;
  vec2 warpedP = p;
  warpedP += vec2(
    fbm(p * 2.0 + time * 0.3, 5) - 0.5,
    fbm(p * 2.0 + time * 0.3 + 100.0, 5) - 0.5
  ) * chaosAmount * (1.0 + fluxVal * 2.0);

  float chaosField = fbm(warpedP * (3.0 + uChaos * 4.0) + time * 0.2, 6);
  chaosField += fbm(warpedP * 7.0 - time * 0.15, 4) * 0.3;

  // Crisp mandala geometry
  float folds = floor(6.0 + uMandalaComplexity * 10.0);
  float detail = uMandalaComplexity + trebleVal * 0.3;
  float crisp = mandala(p * (1.0 + bassVal * 0.3), folds, detail);

  // Blend chaos and crisp based on snap state
  float pattern = mix(chaosField, crisp, isSnap * uSnapSharpness);

  // Coloring
  float colorT = pattern * 0.6 + time * 0.05 + uPalette * 0.3;
  vec3 chaosColor = 0.5 + 0.5 * cos(6.2832 * (colorT + vec3(0.0, 0.33, 0.67)));
  vec3 snapColor = 0.5 + 0.5 * cos(6.2832 * (crisp * 0.4 + vec3(0.1, 0.4, 0.7) + uPalette * 0.2));
  snapColor = pow(snapColor, vec3(0.7)); // Brighter snaps

  vec3 col = mix(chaosColor * 0.7, snapColor * 1.3, isSnap);

  // Bass brightness pulse
  col += bassVal * 0.15;
  // Treble shimmer on snaps
  col += trebleVal * isSnap * 0.2 * vec3(0.8, 0.9, 1.0);
  // Energy glow
  col *= 1.0 + uEnergy * uSensitivity * 0.2;

  // Snap flash
  col += isSnap * kickVal * 0.4;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFlickerRate;
uniform float uPatternMix;
uniform float uFormConstant;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

// Klüver Form 1: Lattice/grid (honeycomb)
float lattice(vec2 p) {
  vec2 q = abs(fract(p) - 0.5);
  return smoothstep(0.4, 0.35, max(q.x, q.y));
}

// Klüver Form 2: Cobweb (radial + concentric)
float cobweb(vec2 p) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float radial = abs(sin(a * 8.0)) * 0.5;
  float concentric = abs(sin(r * 12.0)) * 0.5;
  return smoothstep(0.3, 0.0, min(radial, concentric) - 0.1);
}

// Klüver Form 3: Tunnel (polar depth)
float tunnel(vec2 p) {
  float r = length(p) + 0.001;
  float a = atan(p.y, p.x);
  float depth = 1.0 / r;
  return abs(sin(depth * 3.0 + a * 4.0));
}

// Klüver Form 4: Spiral
float spiral(vec2 p) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float spiralD = abs(sin(a * 2.0 + r * 10.0 - 3.14159));
  return smoothstep(0.4, 0.0, spiralD);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.5) * 0.05, cos(p.x * 3.5 + time * 0.4) * 0.05);

  // Audio-reactive modulators — 2x
  float bassVal = bass() * uSensitivity * 1.6;
  float midsVal = mids() * uSensitivity * 1.4;
  float trebleVal = treble() * uSensitivity * 1.6;
  float entropyVal = uSpectralEntropy;
  float energyVal = uEnergy * uSensitivity * 1.4;
  float bpmSinVal = uBpmSin;
  float centroidVal = uSpectralCentroid;

  // Flicker frequency: 8-12Hz alpha band range
  float flickerHz = 8.0 + uFlickerRate * 4.0;
  // BPM modulates flicker rate slightly
  flickerHz += bpmSinVal * 0.5;

  // Flicker intensity (square wave-ish for stronger effect)
  float flicker = sin(time * flickerHz * 6.2832);
  flicker = smoothstep(-0.2, 0.2, flicker); // Sharpen to near-square

  // Select and blend form constants
  float form = uFormConstant * 3.0;
  float f1 = lattice(p * (3.0 + entropyVal * 3.0) + time * 0.3);
  float f2 = cobweb(p * (1.0 + entropyVal * 2.0));
  float f3 = tunnel(p);
  float f4 = spiral(p + vec2(cos(time * 0.2), sin(time * 0.2)) * 0.3);

  // Crossfade based on formConstant
  float pattern;
  if (form < 1.0) {
    pattern = mix(f1, f2, fract(form));
  } else if (form < 2.0) {
    pattern = mix(f2, f3, fract(form));
  } else {
    pattern = mix(f3, f4, fract(form));
  }

  // Add complexity layers based on entropy
  float complexity = noise(p * (5.0 + entropyVal * 10.0) + time * 0.5);
  pattern = mix(pattern, pattern * complexity, uPatternMix * 0.5);

