vec3 drostePalette(float t, float offset) {
  return 0.5 + 0.5 * cos(TAU * (vec3(1.0) * t + vec3(0.0 + offset * 0.1, 0.33, 0.67)));
}

// Generate a pattern for each recursion layer
vec3 layerPattern(vec2 uv, float time, float layer, float palette) {
  // Warped concentric rings
  float r = length(uv);
  float a = atan(uv.y, uv.x);

  float rings = sin(r * 12.0 - time * 2.0 + layer * 1.5) * 0.5 + 0.5;
  float spiral = sin(a * 3.0 + r * 8.0 - time * 1.5 + layer * 0.7) * 0.5 + 0.5;
  float pattern = mix(rings, spiral, 0.5 + 0.3 * sin(time * 0.3 + layer));

  // Noise detail
