  float colorT = fract(pattern * 0.8 + layer * 0.15 + time * 0.08 + sin(time * 0.3) * 0.15);
  vec3 col = drostePalette(colorT, palette);
  col *= smoothstep(0.0, 0.3, pattern) * (0.6 + 0.4 * pattern);

  return col;
}

