  vec2 uv = (vUv - 0.5) * 2.0;
  uv = psychedelicUV(uv); // breathing morph
  float aspect = 1.0;
  float time = uTime * uSpeed * 1.2;

  // Audio (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  // Log-polar transform for Droste effect
  float r = length(uv);
  float theta = atan(uv.y, uv.x);

  // Prevent log(0)
  r = max(r, 0.001);

  // Log-polar coordinates
  float logR = log(r);
  float spiralTight = uSpiralTightness * 4.0 + 1.0;
  float twist = uRecursionTwist * TAU;

  // Droste spiral: combine angle and log-radius
  // The key formula: map (logR, theta) to a repeating strip
  float zoomSpeed = time * 0.5 + bassVal * 0.3 + beatPulse * 0.5;
  float drosteAngle = theta + logR * spiralTight + twist * sin(time * 0.1);

  // Make it tile: fract the log-radius to create infinite recursion
