  float recurseTheta = drosteAngle + zoomSpeed * 0.3;

  // Chaos adds wobble to recursion
  recurseR += sin(recurseTheta * 3.0 + time) * uChaos * 0.1;
  recurseTheta += cos(recurseR * 5.0 + time * 0.7) * uChaos * 0.2;

  // Convert back to cartesian for pattern generation
