  float edgeGlow = smoothstep(1.0, 0.85, edgeDist);
  vec3 edgeCol = drostePalette(fract(layer * 0.2 + time * 0.1), uPalette);
  col += edgeCol * (1.0 - edgeGlow) * 0.5 * trebleVal;

  // Spiral arm highlight
  float armAngle = mod(drosteAngle, TAU / 3.0) / (TAU / 3.0);
  float armGlow = smoothstep(0.1, 0.0, abs(armAngle - 0.5) - 0.1);
  col += drostePalette(fract(time * 0.05 + r), uPalette) * armGlow * 0.3 * midsVal;

