  col += vec3(centerBright) * drostePalette(fract(time * 0.2), uPalette);

  // Onset flash
  col += vec3(onset * 0.15);

  // Kick pulse
  col *= 1.0 + kick * 0.3;

  // Intensity and energy
  col *= uIntensity * 1.5;
  col *= 1.0 + energy * 0.2;

  // Vignette
  float vig = 1.0 - smoothstep(0.5, 1.2, length(vUv - 0.5) * 1.4);
  col *= vig;

  // Minimum brightness
  col += vec3(0.01, 0.008, 0.015);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

