  vec2 p = (vUv - 0.5) * (1.5 + uZoom * 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetPulse = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // === CENTRAL STAR ===
  float starBright = uStarPower * (1.8 + bassVal * 2.0 + kickPulse * 1.0);
  float starCore = exp(-r * r * 12.0) * starBright * 3.0;
  float starGlow = exp(-r * r * 1.5) * starBright * 0.8;
  float starCorona = exp(-r * 0.6) * starBright * 0.2;

  // Star surface detail
