  vec3 starCol = vec3(1.0, 0.95, 0.85) * starCore;
  starCol += vec3(1.0, 0.8, 0.5) * starGlow;
  starCol += vec3(0.8, 0.5, 0.2) * starCorona;
  starCol += vec3(1.0, 0.7, 0.3) * starFlare;

  // === DYSON LATTICE ===
  float latticeFreq = 6.0 + uLatticeScale * 10.0;

  // Rotate lattice slowly with mids influence
  float latAngle = time * 0.2 + midsVal * 0.3;
  float cosA = cos(latAngle);
  float sinA = sin(latAngle);
  vec2 rotP = vec2(p.x * cosA - p.y * sinA, p.x * sinA + p.y * cosA);

  // Hex lattice fills the full screen — no sphere radius constraint
  float sphereRadius = 1.5;
  float onSphere = smoothstep(sphereRadius + 0.4, sphereRadius - 0.1, r);

  // Project to lattice coordinates
  vec4 hex = hexCoords(rotP * latticeFreq);
  vec2 hexGV = hex.xy;
  vec2 hexID = hex.zw;
  float hexD = hexDist(hexGV);

  // Panel presence: some panels are gaps
  float panelHash = hash(hexID);
  float gapThreshold = uGapSize * (0.5 + uChaos * 0.3);
  float isPanel = step(gapThreshold, panelHash);
  float isGap = 1.0 - isPanel;

  // Beat triggers panel reconfiguration
  float reconfig = sin(panelHash * 50.0 + time * 2.0 + beatPulse * 5.0) * 0.5 + 0.5;

  // Lattice structure: hex edges
  float edgeWidth = 0.05;
  float latticeEdge = smoothstep(edgeWidth, edgeWidth * 0.3, hexD) * onSphere;
  float panelFill = smoothstep(0.0, edgeWidth * 2.0, hexD) * onSphere * isPanel;

  // Panel color: dark metallic
  vec3 panelCol = vec3(0.08, 0.09, 0.12) * panelFill;
  // Panel detail: subtle circuit pattern
  float circuitNoise = noise(hexGV * 20.0 + hexID * 10.0);
  panelCol += vec3(0.02, 0.04, 0.06) * smoothstep(0.5, 0.6, circuitNoise) * panelFill;

  // Lattice frame: metallic silver
  vec3 frameCol = vec3(0.3, 0.32, 0.35) * latticeEdge;

  // === ENERGY COLLECTORS: treble-activated glow on panels ===
  float collectorActive = trebleVal * isPanel * onSphere * reconfig;
  vec3 collectorCol = vec3(0.15, 0.5, 1.0) * collectorActive * 0.8;
  collectorCol += vec3(0.0, 0.2, 0.5) * smoothstep(0.4, 0.5, circuitNoise) * collectorActive;

  // === STARLIGHT THROUGH GAPS ===
  float gapLight = isGap * onSphere * starBright * 0.3;
  // Light rays streaming through gaps
  float rayAngle = atan(hexGV.y, hexGV.x);
  float lightRay = gapLight * (0.7 + 0.3 * sin(rayAngle * 3.0 + time));
  // Kick pulses starlight
  lightRay *= (1.0 + kickPulse * 4.0);

  vec3 gapLightCol = vec3(1.0, 0.9, 0.7) * lightRay;

  // === LIGHT/SHADOW PATTERN beyond sphere ===
  // Shadows cast by lattice panels
  float shadowPattern = isPanel * onSphere;
  float lightPattern = (1.0 - shadowPattern) * smoothstep(sphereRadius + 0.8, sphereRadius - 0.3, r);

  // === SCATTERED STARLIGHT (for areas not blocked) ===
  vec3 scatteredLight = starCol * (1.0 - onSphere * isPanel * 0.8);

  // === BACKGROUND: space with stars ===
  vec3 bg = vec3(0.005, 0.003, 0.01);
  float starGrid = 130.0;
  vec2 starCell = floor(p * starGrid);
  float starH = hash(starCell);
  if (starH > 0.987) {
    vec2 starFrac = fract(p * starGrid) - vec2(hash(starCell + 5.0), hash(starCell + 11.0));
    float sDist = dot(starFrac, starFrac);
    bg += vec3(0.5, 0.55, 0.7) * exp(-sDist * 1500.0) * 0.2;
  }

  // === SPHERE RIM GLOW ===
  float rimDist = abs(r - sphereRadius);
  float rim = exp(-rimDist * 8.0) * 0.3;
  vec3 rimCol = vec3(0.3, 0.4, 0.5) * rim;

  // === ONSET FLASH ===
  vec3 onsetCol = vec3(1.0, 0.9, 0.6) * onsetPulse * 0.2 * exp(-r * 1.0);

  // Palette shift
  float palShift = uPalette * 0.2;

  // === COMBINE ===
  vec3 col = bg + scatteredLight + panelCol + frameCol + collectorCol +
             gapLightCol + rimCol + onsetCol;

  col = vec3(
    col.r * cos(palShift) - col.b * sin(palShift),
    col.g,
    col.r * sin(palShift) + col.b * cos(palShift)
  );

  col *= (0.8 + uEnergy * uSensitivity * 0.6);
  col *= uIntensity * 1.5;

  // Beat structural pulse
  col += vec3(0.05, 0.08, 0.15) * beatPulse * 0.15 * onSphere;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

