uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uEchoCount;
uniform float uEchoDecay;
uniform float uEchoSpacing;
uniform float uRotationDrift;

vec2 rotate2d(vec2 p, float a) {
  float s = sin(a);
  float c = cos(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec3 palette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.33, 0.67)));
}

// Generate a geometric pattern at time t
float geometricPattern(vec2 p, float t) {
  // Hexagonal grid
  float scale = 3.0;
  vec2 q = p * scale;
  vec2 r = fract(q) - 0.5;
  vec2 id = floor(q);

  // Animated shape per cell
  float cellPhase = sin(id.x * 3.7 + id.y * 2.3 + t * 0.5);
  float shape = length(r) - 0.3 - cellPhase * 0.15;

  // Star pattern overlay
  float angle = atan(r.y, r.x);
  float star = sin(angle * 6.0 + t * 2.0 + length(p) * 4.0) * 0.15;
  shape += star;

  // Ring pulse
  float ring = abs(length(p) - fract(t * 0.3) * 2.0) - 0.05;

  return min(smoothstep(0.02, 0.0, shape), 1.0) + smoothstep(0.04, 0.0, ring) * 0.5;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // Accumulate echo layers
  vec3 color = vec3(0.0);
  float maxEchoes = min(uEchoCount, 12.0);

  for (float i = 0.0; i < 12.0; i += 1.0) {
    if (i >= maxEchoes) break;

    float echoFrac = i / maxEchoes;

    // Time offset for this echo
    float timeDelay = i * uEchoSpacing * (1.0 + bassVal * 0.5);
    float echoTime = time - timeDelay;

    // Progressive rotation
    float rot = i * uRotationDrift * (1.0 + uChaos * sin(time * 0.2));
    rot += onsetVal * 0.3 * i;
    vec2 rp = rotate2d(p, rot);

    // Progressive scale (echoes shrink slightly)
    float scaleFactor = 1.0 + i * 0.05;
    rp *= scaleFactor;

    // Generate pattern at echo time
    float pattern = geometricPattern(rp, echoTime);

    // Each echo gets a shifted hue
    float hueShift = echoFrac * 0.4 + uPalette * 0.1 + midsVal * 0.15;
    vec3 echoColor = palette(pattern * 0.3 + echoTime * 0.02, hueShift);
    echoColor *= pattern;

    // Exponential decay
    float opacity = exp(-i * uEchoDecay);

    // Treble adds shimmer to later echoes
    opacity += trebleVal * 0.1 * echoFrac;

    color += echoColor * opacity;
  }

  // Normalize
  color *= 0.3;

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat pulse glow
  float beatGlow = uBeat * uSensitivity * 0.1;
  color += vec3(beatGlow * 0.8, beatGlow * 0.5, beatGlow);

  // Onset flash
  color = mix(color, color + vec3(0.15, 0.1, 0.2), onsetVal * 0.5);

  // Soft contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.2));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

