  geoColor *= 0.7 + geoPulse * 0.3;

  // === Static/noise (the dissolved state) ===
  vec2 noiseCoord = p * 50.0 + time * 20.0;
  float staticNoise = hash21(floor(noiseCoord));
  float fineStatic = hash21(floor(noiseCoord * 3.0 + time * 100.0));

  // Dissolving edge particles
  float edgeNoise = noiseVal(p * 8.0 + time * 2.0);
  float edgeParticles = smoothstep(0.6, 0.8, edgeNoise) * dissolution;

  vec3 staticColor = vec3(staticNoise * 0.15 + fineStatic * 0.05);
  staticColor += vec3(0.1, 0.08, 0.05) * edgeParticles;

  // === Dissolving geometry: fragments breaking away ===
  float fragmentNoise = noiseVal(p * 15.0 + time * 0.5);
  float fragmentMask = smoothstep(dissolution - 0.1, dissolution + 0.1, fragmentNoise);

  // Geometry fragments still visible during dissolution
  vec3 fragmentColor = geoColor * geometry * fragmentMask;
  float fragmentGlow = smoothstep(0.4, 0.6, dissolution) * (1.0 - dissolution);
  fragmentColor += vec3(1.0, 0.9, 0.6) * fragmentGlow * geometry * 0.3;

  // === Combine: geometry vs static based on dissolution ===
  vec3 col = mix(
    geoColor * geometry + vec3(0.005), // ordered state (near-black bg)
    staticColor,                        // dissolved state
    dissolution
  );
  col += fragmentColor * 0.5;

  // Rebuild wave: golden light sweeping inward
  if (rebuildPulse > 0.0) {
    float rebuildWave = smoothstep(0.0, 0.3, rebuildPulse);
    float rebuildR = (1.0 - rebuildPulse) * 2.0;
    float rebuildGlow = smoothstep(0.3, 0.0, abs(centerDist - rebuildR));
    col += vec3(1.0, 0.9, 0.5) * rebuildGlow * rebuildWave * 0.5;
  }

  // Onset: bright dissolution burst — 2x
  col += vec3(0.4, 0.35, 0.2) * onsetVal * dissolution * 1.0;

  // Void breathing
  float voidBreath = sin(time * 0.5) * 0.5 + 0.5;
  col *= 0.85 + voidBreath * 0.15;

  // Chaos amplifies dissolution
  dissolution = clamp(dissolution + uChaos * 0.3, 0.0, 1.0);

  // Palette shift — faster cycling
  col = mix(col, col.gbr, uPalette * 0.15 + sin(uTime * 0.3) * 0.1);

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

