    vec3(0.8, 0.7, 0.5),
    vec3(1.0, 0.9, 0.6),
    trebleVal
  );
  col += edgeColor * edgeAccum * uEdgeGlow * 0.4;

  // Warm ambient glow
  float ambientGlow = exp(-dot(p, p) * 0.8);
  col += vec3(0.15, 0.1, 0.05) * ambientGlow;

  // Onset flash
  col += vec3(0.2, 0.15, 0.1) * uOnset * uSensitivity * 0.4;

  // Kick shadow pulse
  col *= 1.0 + uKick * uSensitivity * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
