uniform float uBloomRate;
uniform float uColorWarmth;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

// Petal shape SDF
float petal(vec2 p, float width, float len) {
  p.y -= len * 0.3;
  float d = length(p / vec2(width, len)) - 1.0;
  return smoothstep(0.05, -0.05, d);
}

// Single bloom flower
float bloom(vec2 p, float petals, float openness, float phase) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float result = 0.0;

  // Petals with unfolding animation
  for (float i = 0.0; i < 12.0; i++) {
    if (i >= petals) break;
    float petalAngle = i * 6.2832 / petals + phase;
    float cs = cos(petalAngle), sn = sin(petalAngle);
    vec2 rp = mat2(cs, -sn, sn, cs) * p;
    float petalShape = petal(rp, 0.15 * openness, 0.5 * openness);
    // Inner curve
    petalShape *= smoothstep(0.0, 0.15 * openness, rp.y);
    result = max(result, petalShape * (0.7 + 0.3 * sin(i * 2.0 + phase)));
  }

  // Center pistil
  float center = smoothstep(0.1, 0.0, r) * 0.8;
  result = max(result, center);

  return result;
}

