  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float centroidVal = uSpectralCentroid * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // Multiple bloom layers at different positions and phases
  float petals = floor(5.0 + uPetalCount * 8.0);

  for (float layer = 0.0; layer < 5.0; layer++) {
    float t = time * uBloomRate + layer * 2.5;
    float lifePhase = fract(t * 0.15);

    // Bloom grows from center outward
    float openness = smoothstep(0.0, 0.4, lifePhase) * (1.0 + bassVal * 0.5);
    openness *= smoothstep(1.0, 0.7, lifePhase); // Fade out

    // Position offset per layer
    float angle = layer * 2.399 + time * 0.1;
    float dist = layer * 0.25 * lifePhase;
    vec2 offset = vec2(cos(angle), sin(angle)) * dist;

    // Scale per layer
    float scale = 1.5 + layer * 0.3;

    vec2 bp = (p - offset) * scale;

    // Rotation
    float rot = time * 0.3 * (1.0 + layer * 0.2) + layer;
    float cs = cos(rot), sn = sin(rot);
    bp = mat2(cs, -sn, sn, cs) * bp;

    // Petal complexity from spectral centroid
    float layerPetals = petals + centroidVal * 3.0;
    float b = bloom(bp, layerPetals, openness, time * 0.5 + layer);
    b *= openness;

    // Color per layer
    float hue = layer * 0.15 + time * 0.02 + uPalette * 0.3;

    // Warm golden-pink palette
    vec3 warmCol = vec3(
      0.9 + 0.1 * sin(hue * 6.28),
      0.5 + 0.3 * sin(hue * 6.28 + 1.0),
      0.3 + 0.2 * sin(hue * 6.28 + 2.0)
    );

    // Cool electric blue
    vec3 coolCol = vec3(
      0.1 + 0.2 * sin(hue * 6.28 + 3.0),
      0.4 + 0.3 * sin(hue * 6.28 + 1.5),
      0.9 + 0.1 * sin(hue * 6.28)
    );

    // Shift to cool on drops (high energy)
    float warmMix = uColorWarmth * (1.0 - energyVal * 0.5);
    vec3 layerCol = mix(coolCol, warmCol, warmMix);

    col += b * layerCol * 0.5;
  }

  // Treble sparkle
  float sparkle = noise(p * 30.0 + time * 5.0) * trebleVal;
  col += sparkle * 0.2 * vec3(1.0, 0.9, 0.8);

  // Kick bloom flash
  col += kickVal * 0.3 * vec3(1.0, 0.8, 0.6) * exp(-length(p) * 2.0);

  // Bass pulsing glow from center
  col += bassVal * 0.15 * exp(-length(p) * 3.0) * vec3(1.0, 0.6, 0.8);

  // Chaos: organic noise displacement
  col *= 1.0 + (noise(p * 5.0 + time) - 0.5) * uChaos * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
