  streaks *= spaghetti * 0.8;

  vec3 streakColor = vec3(0.6, 0.4, 0.8) * streaks;
  streakColor += vec3(0.8, 0.3, 0.2) * streaks * bassVal;

  // === CHAOTIC LIGHT beyond horizon ===
  float insideHorizon = smoothstep(ehRadius, ehRadius * 0.3, r);
  float chaoticNoise = fbm(vec2(angle * 5.0 + time * 3.0, r * 10.0 - time * 5.0));
  vec3 chaoticLight = vec3(0.0);
  chaoticLight.r = chaoticNoise * 0.8 * insideHorizon;
  chaoticLight.g = fbm(vec2(angle * 7.0 - time * 2.0, r * 8.0)) * 0.4 * insideHorizon;
  chaoticLight.b = fbm(vec2(angle * 3.0 + time * 4.0, r * 12.0)) * 0.9 * insideHorizon;
  chaoticLight *= uChaos + 0.3;

  // === EVENT HORIZON DARKNESS ===
  float darkness = smoothstep(ehRadius * 0.5, ehRadius * 0.15, r);

  // === ACCRETION GLOW ===
  float accretionDist = abs(r - ehRadius * 1.2);
  float accretion = exp(-accretionDist * 15.0) * (1.0 + midsVal * 1.0);
  float accAngle = angle + time * 1.5;
  float accTurbulence = sin(accAngle * 4.0 + r * 20.0) * 0.3 + 0.7;
  vec3 accretionColor = vec3(1.0, 0.6, 0.2) * accretion * accTurbulence;
  accretionColor += vec3(0.3, 0.5, 1.0) * accretion * (1.0 - accTurbulence) * 0.5;

