  float starGrid = 120.0;
  vec2 starCell = floor(p * starGrid);
  float starH = hash(starCell);
  vec3 stars = vec3(0.0);
  if (starH > 0.985) {
    vec2 starOffset = vec2(hash(starCell + 5.0), hash(starCell + 11.0));
    vec2 starFrac = fract(p * starGrid) - starOffset;
    float starDist = dot(starFrac, starFrac);
    float starGlow = exp(-starDist * 2000.0) * 0.4;
    stars = vec3(0.8, 0.85, 1.0) * starGlow;
  }

  // === ONSET FLASH ===
  vec3 onsetCol = vec3(1.0, 0.9, 0.8) * onsetPulse * 0.2 * (1.0 - darkness);

  // === COMBINE ===
