  // Apply darkness inside event horizon
  col = mix(col, chaoticLight * 0.3, darkness * 0.9);

  // Beat warm flash
  col += vec3(0.3, 0.15, 0.4) * beatPulse * 0.3;

  // Energy modulation
  col *= (0.8 + uEnergy * uSensitivity * 0.6);
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSwarmSize;
uniform float uPulseRate;
uniform float uFlockTightness;
uniform float uTrailLength;

vec3 fireflyPalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.05, 0.15, 0.3)));
}

// 2D pseudo-random
vec2 hash2(float n) {
  return fract(sin(vec2(n, n + 1.0)) * vec2(43758.5453, 22578.1459));
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453123);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numFireflies = min(uSwarmSize, 80.0);
  vec3 color = vec3(0.0);

  // Swarm center drifts slowly
  vec2 swarmCenter = vec2(
    sin(time * 0.2) * 0.3 + cos(time * 0.15) * 0.2,
    cos(time * 0.18) * 0.3 + sin(time * 0.12) * 0.15
  );
  // Bass pulls swarm center
  swarmCenter += vec2(bassVal * 0.1, midsVal * 0.08);

  for (float i = 0.0; i < 80.0; i += 1.0) {
    if (i >= numFireflies) break;

    // Each firefly has a unique "home" position — spread across full screen
    vec2 home = hash2(i * 7.3) * 3.2 - 1.6;

    // Flocking: gently pull toward swarm center — reduced pull for full coverage
    vec2 flockTarget = mix(home, swarmCenter, uFlockTightness * 0.4);

    // Individual movement: orbit around target with unique phase
    float orbitSpeed = 0.3 + hash1(i * 3.1) * 0.4;
    float orbitRadius = 0.15 + hash1(i * 5.7) * 0.25;
    orbitRadius *= 1.0 + trebleVal * 0.5; // scatter on treble

    float phase = i * 2.399 + time * orbitSpeed;
    vec2 flyPos = flockTarget + vec2(
      cos(phase) * orbitRadius + sin(phase * 1.3 + i) * 0.05 * uChaos,
      sin(phase) * orbitRadius * 0.8 + cos(phase * 0.7 + i * 0.5) * 0.04 * uChaos
    );

    // Onset: briefly scatter outward
    float scatterAngle = hash1(i * 11.3) * 6.2832;
    flyPos += vec2(cos(scatterAngle), sin(scatterAngle)) * onsetVal * 0.15;

    // Distance from pixel to firefly
    float dist = length(p - flyPos);

    // Individual pulse: each firefly blinks at its own rate
    float pulsePhase = i * 1.618 + time * uPulseRate * 2.0;
    float pulse = sin(pulsePhase) * 0.5 + 0.5;
    pulse = pulse * pulse; // sharpen the pulse

    // Glow
    float glow = exp(-dist * 30.0) * pulse;
    float core = exp(-dist * 80.0) * pulse;

    // Trail: small glow behind the firefly along its movement direction
    if (uTrailLength > 0.01) {
      vec2 prevPos = flockTarget + vec2(
        cos(phase - 0.1) * orbitRadius,
        sin(phase - 0.1) * orbitRadius * 0.8
      );
      vec2 trailDir = flyPos - prevPos;
      for (float t = 1.0; t < 4.0; t += 1.0) {
        vec2 trailPt = flyPos - trailDir * t * 2.0;
        float tDist = length(p - trailPt);
        float tFade = exp(-t * 0.8);
        glow += exp(-tDist * 25.0) * tFade * uTrailLength * pulse * 0.3;
      }
    }

    // Color: warm yellows/greens for fireflies, varied by individual
    float hue = hash1(i * 4.2) * 0.15 + 0.1 + uPalette * 0.1;
    vec3 flyColor = fireflyPalette(hue, uPalette * 0.05);

    // Some fireflies shift color with chaos
    flyColor = mix(flyColor, flyColor.gbr, uChaos * hash1(i * 8.8) * 0.4);

    float brightness = core * 2.5 + glow * 0.8;
    color += flyColor * brightness;
  }

  // Ambient background: very subtle dark blue/green
  vec3 ambient = vec3(0.01, 0.015, 0.02) * uIntensity;
  color += ambient;

  // Treble sparkle dust
  float sparkle = sin(p.x * 70.0 + time * 5.0) * sin(p.y * 70.0 - time * 4.5);
  sparkle = pow(max(sparkle, 0.0), 25.0);
  color += vec3(0.8, 0.9, 0.5) * sparkle * trebleVal * 0.15;

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.03);

  // Kick punch
  color = mix(color, color * 1.5, kickVal * 0.25);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.1));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

