vec3 fireworkColor(float id) {
  float t = fract(id * 0.618 + uPalette * 0.2);
  vec3 gold = vec3(1.0, 0.85, 0.3);
  vec3 red = vec3(1.0, 0.15, 0.1);
  vec3 blue = vec3(0.2, 0.4, 1.0);
  vec3 green = vec3(0.1, 1.0, 0.3);
  vec3 silver = vec3(0.9, 0.92, 1.0);
  vec3 magenta = vec3(1.0, 0.2, 0.8);
  vec3 cyan = vec3(0.1, 0.9, 1.0);
  vec3 orange = vec3(1.0, 0.5, 0.05);
  float idx = t * 8.0;
  if (idx < 1.0) return gold;
  if (idx < 2.0) return red;
  if (idx < 3.0) return blue;
  if (idx < 4.0) return green;
  if (idx < 5.0) return silver;
  if (idx < 6.0) return magenta;
  if (idx < 7.0) return cyan;
  return orange;
}

