        if (expType < 1.0) {
          // Sphere: uniform radial
          sparkSpeed *= 0.8 + hash(j * 13.7) * 0.4;
        } else if (expType < 2.0) {
          // Ring: sparks concentrate at a fixed radius
          sparkSpeed *= 0.9 + sin(explodeAge * 3.14) * 0.1;
        } else if (expType < 3.0) {
          // Willow: long drooping trails
          sparkSpeed *= 0.5 + hash(j * 7.3) * 0.3;
        } else if (expType < 4.0) {
          // Palm: upward burst then droop
          sparkAngle = sparkAngle * 0.5 + 1.57;
          sparkSpeed *= 0.6 + hash(j * 19.1) * 0.8;
        } else if (expType < 5.0) {
          // Chrysanthemum: dense, tight burst
          sparkSpeed *= 0.3 + hash(j * 23.7) * 0.7;
        } else {
          // Crossette: sparks split into sub-bursts
          sparkSpeed *= 0.6 + hash(j * 11.3) * 0.4;
        }

        float sparkDist = sparkSpeed * explodeAge;
        float grav = explodeAge * explodeAge * (expType < 3.0 ? 0.4 : 0.8);
        vec2 sparkPos = center + vec2(cos(sparkAngle), sin(sparkAngle)) * sparkDist;
        sparkPos.y -= grav;

        float d = length(p - sparkPos);
        float sparkle = hash2(vec2(j, i) + floor(vec2(time * 15.0))) * uSparkleIntensity * (0.5 + trebleVal);
        float glow = smoothstep(0.015, 0.0, d) * fadeOut;
        glow += smoothstep(0.04, 0.0, d) * fadeOut * sparkle * 0.5;

        col += fwColor * glow;

        // Child explosions: 4 sparks spawn sub-bursts at age 0.3-0.6
        if (mod(j, 12.0) < 1.0 && explodeAge > 0.3 && explodeAge < 0.8) {
          float childAge = (explodeAge - 0.3) / 0.5;
          float childFade = (1.0 - childAge) * (1.0 - childAge);
          vec3 childColor = fireworkColor(i + j * 0.1);
          for (float k = 0.0; k < 8.0; k++) {
            float cAngle = k * 6.2832 / 8.0 + hash(k + j * 50.0) * 0.5;
            float cSpeed = 0.15 * burstR * (0.5 + hash(k * 71.3 + j) * 0.5);
            vec2 cPos = sparkPos + vec2(cos(cAngle), sin(cAngle)) * cSpeed * childAge;
            cPos.y -= childAge * childAge * 0.15;
            float cd = length(p - cPos);
            float cGlow = smoothstep(0.01, 0.0, cd) * childFade * fadeOut;
            col += childColor * cGlow * 0.7;
          }
        }
      }

      // Core flash — bigger
      float coreDist = length(p - center);
      float coreFlash = exp(-coreDist * 5.0) * max(0.0, 1.0 - explodeAge * 2.5);
      col += vec3(1.0, 0.95, 0.85) * coreFlash * 1.5;

      // Bloom ring for ring-type explosions
      if (expType >= 1.0 && expType < 2.0) {
        float ringR = burstR * explodeAge * 0.8;
        float ringD = abs(length(p - center) - ringR);
        col += fwColor * smoothstep(0.03, 0.0, ringD) * fadeOut * 0.5;
      }
    }
  }

  // Ambient glow from energy
  col += vec3(0.02, 0.01, 0.03) * uEnergy * uSensitivity;
  col += col * uOnset * uSensitivity * 0.4;
  col *= 1.0 + kickVal * 0.4;
  col *= 1.0 + bassVal * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBreathDepth;
uniform float uPetalCount;
uniform float uIntersectionGlow;

#define PI 3.14159265
#define TAU 6.28318530

vec2 rotate2d(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.5;

  // Breathing: all circles expand/contract together
  float breath = 1.0 + uBpmSin * uBreathDepth * 0.2 + bassVal * uBreathDepth * 0.15;

  vec3 col = vec3(0.01, 0.01, 0.03);

  // Flower of Life: concentric rings of 6 circles each
  int rings = 3 + int(uPetalCount * 4.0);
  float baseR = 0.25 * breath;

  float circleAccum = 0.0;
  float intersectAccum = 0.0;
  int circleIdx = 0;

  // Center circle
  float d0 = abs(length(p) - baseR) - 0.003;
  float c0 = smoothstep(0.005, 0.0, d0);
  col += vec3(0.8, 0.85, 1.0) * c0 * 0.4;

  // Rings of circles
  for (int ring = 1; ring <= 6; ring++) {
    if (ring > rings) break;
    int numCircles = ring * 6;
    float ringR = baseR * float(ring);

    for (int i = 0; i < 36; i++) {
      if (i >= numCircles) break;
      float fi = float(i);
      float angle = fi * TAU / float(numCircles) + time * 0.01 * float(ring);

      vec2 center = vec2(cos(angle), sin(angle)) * ringR;
      float d = abs(length(p - center) - baseR) - 0.002;
      float circle = smoothstep(0.004, 0.0, d);

      // Spectrum band per circle
      float specIdx = mod(float(circleIdx), 8.0);
      float specVal = 0.0;
      if (specIdx < 1.0) specVal = uSpectrum0;
      else if (specIdx < 2.0) specVal = uSpectrum1;
      else if (specIdx < 3.0) specVal = uSpectrum2;
      else if (specIdx < 4.0) specVal = uSpectrum3;
      else if (specIdx < 5.0) specVal = uSpectrum4;
      else if (specIdx < 6.0) specVal = uSpectrum5;
      else if (specIdx < 7.0) specVal = uSpectrum6;
      else specVal = uSpectrum7;

      // Ethereal white/blue/violet palette — more color variation
      float hue = fi / float(numCircles) + float(ring) * 0.3 + uPalette * 0.4 + time * 0.03;
      vec3 circCol = vec3(0.0);
      circCol.r = 0.6 + 0.3 * sin(hue * TAU + 0.0);
      circCol.g = 0.6 + 0.3 * sin(hue * TAU + 1.5);
      circCol.b = 0.8 + 0.2 * sin(hue * TAU + 3.0);

      circCol *= 0.3 + specVal * uSensitivity * 0.5;
      col += circCol * circle * 0.3;

      // Track intersections (where circle is close to integer distance from center)
      float distFromCenter = length(p);
      float intDist = abs(fract(distFromCenter / baseR + 0.5) - 0.5) * baseR;
      float nearIntersect = smoothstep(0.03, 0.0, intDist) * circle;
      intersectAccum += nearIntersect;

      circleIdx++;
    }
  }

  // Intersection points glow with treble
  vec3 intersectCol = vec3(0.9, 0.85, 1.0) * intersectAccum * uIntersectionGlow * 0.6;
  intersectCol *= 0.5 + trebleVal * 1.2;
  col += intersectCol;

  // Vesica piscis patterns at overlaps - petal shapes
  float petalPattern = 0.0;
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * TAU / 6.0;
    vec2 c1 = vec2(cos(angle), sin(angle)) * baseR * 0.5;
    vec2 c2 = -c1;
    float d1 = length(p - c1) - baseR * 0.6;
    float d2 = length(p - c2) - baseR * 0.6;
    float vesica = max(d1, d2);
    petalPattern += smoothstep(0.01, 0.0, vesica) * 0.1;
  }
  col += vec3(0.4, 0.3, 0.6) * petalPattern * (0.3 + midsVal * 0.3);

  // Central mandala glow
  float centerGlow = exp(-dot(p, p) * 3.0) * (0.3 + uBeat * uSensitivity * 0.4);
  col += vec3(0.5, 0.4, 0.8) * centerGlow;

  // Kick flash
  col += vec3(0.2, 0.18, 0.3) * uKick * uSensitivity * 0.3;

  // Harmonicity shimmer
  col += vec3(0.1, 0.08, 0.15) * uHarmonicity * uSensitivity * 0.2;

  // Outer fade
  float outerFade = smoothstep(1.2, 0.8, length(p));
  col *= outerFade;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
