__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uViscosity;
uniform float uVortexStrength;
uniform float uFlowScale;
uniform float uLayerCount;

// HSV to RGB
vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.8);
  float breathe = 1.0 + sin(uTime * 0.4) * 0.08;
  p *= breathe;

  // Audio-reactive modulators
  float bassVortex = bass() * uSensitivity * 1.1;
  float midsTurbulence = mids() * uSensitivity * 0.85;
  float trebleDetail = treble() * uSensitivity * 0.7;
  float energyBright = uEnergy * uSensitivity;
  float beatPump = uBeat * uSensitivity * 0.4;

  // Viscosity controls time damping
  float viscosityDamp = 1.0 - uViscosity * 0.7;
  float flowTime = time * viscosityDamp;

  // === FLOW LAYER 1: Large-scale vortices (bass-driven) ===
  float scale1 = uFlowScale * 1.0;
  float vortex1Strength = uVortexStrength * 0.4 + bassVortex * 0.5;

  float curl1x = sin(p.y * scale1 + flowTime * 0.3 +
    cos(p.x * (scale1 * 0.7) + flowTime * 0.2) * (uChaos + 0.3)
  ) * vortex1Strength;
  float curl1y = -(cos(p.x * scale1 - flowTime * 0.35 +
    sin(p.y * (scale1 * 0.8) - flowTime * 0.25) * (uChaos + 0.3)
  ) * vortex1Strength);

  float p1x = p.x + curl1x;
  float p1y = p.y + curl1y;

  float flowDirX = curl1x;
  float flowDirY = curl1y;

  // === FLOW LAYER 2: Medium turbulence (mids-driven) ===
  float scale2 = uFlowScale * 2.3;
  float vortex2Strength = uVortexStrength * 0.3 + midsTurbulence * 0.4;

  float layer2Weight = smoothstep(1.0, 2.0, uLayerCount);

  float curl2x = sin(p1y * scale2 + flowTime * 0.5 +
    p1x * (scale2 * 0.6)
  ) * vortex2Strength * layer2Weight;
  float curl2y = -(cos(p1x * scale2 - flowTime * 0.45 +
    p1y * (scale2 * 0.5)
  ) * vortex2Strength * layer2Weight);

  float p2x = p1x + curl2x;
  float p2y = p1y + curl2y;

  float flowDir2X = flowDirX + curl2x * 0.7;
  float flowDir2Y = flowDirY + curl2y * 0.7;

  // === FLOW LAYER 3: Fine detail (treble-driven) ===
  float scale3 = uFlowScale * 4.7;
  float vortex3Strength = uVortexStrength * 0.2 + trebleDetail * 0.3;

  float layer3Weight = smoothstep(2.0, 3.0, uLayerCount);

  float curl3x = sin(p2y * scale3 + flowTime * 0.7 +
    p2x * (scale3 * 0.8)
  ) * vortex3Strength * layer3Weight;
  float curl3y = -(cos(p2x * scale3 - flowTime * 0.65 +
    p2y * (scale3 * 0.7)
  ) * vortex3Strength * layer3Weight);

  float p3x = p2x + curl3x;
  float p3y = p2y + curl3y;

  float flowDir3X = flowDir2X + curl3x * 0.5;
  float flowDir3Y = flowDir2Y + curl3y * 0.5;

  // === FLOW LAYER 4: Ultra-fine micro-turbulence ===
  float scale4 = uFlowScale * 8.3;
  float vortex4Strength = uVortexStrength * 0.1 + trebleDetail * 0.15;

  float layer4Weight = smoothstep(3.0, 4.0, uLayerCount);

  float curl4x = sin(p3y * scale4 + flowTime * 0.9) * vortex4Strength * layer4Weight;
  float curl4y = -(cos(p3x * scale4 - flowTime * 0.85) * vortex4Strength * layer4Weight);

  float flowDir4X = flowDir3X + curl4x * 0.3;
  float flowDir4Y = flowDir3Y + curl4y * 0.3;

  float finalX = p3x + curl4x;
  float finalY = p3y + curl4y;

  // === FLOW DENSITY FIELD ===
  float density1 = sin(finalX * 3.0 + finalY * 2.5 + flowTime * 0.2) * 0.5 + 0.5;
  float density2 = sin(finalX * 5.0 - finalY * 4.0 + flowTime * 0.3) * 0.5 + 0.5;
  float density = density1 * 0.6 + density2 * 0.4;

  // === IRIDESCENT COLORING ===
  float flowMag = flowDir4X * flowDir4X + flowDir4Y * flowDir4Y;
  float flowMagNorm = smoothstep(0.0, 1.0, flowMag * 2.0);

  float flowAngle = sin(flowDir4X * 3.14159) * 0.5 +
    cos(flowDir4Y * 3.14159) * 0.5;

  float iridescentHue = fract(
    flowAngle * 0.3
      + density * 0.4
      + uPalette * 0.1
      + flowTime * 0.02
      + uChaos * (sin(flowTime * 0.3) * 0.15)
  );

  float iridescentSat = 0.8 + flowMagNorm * 0.2;

  float baseBrightness = uIntensity * 1.0 + energyBright * 0.5;
  float flowBrightness = density * 0.6 + 0.4;
  float iridescentVal = baseBrightness * flowBrightness;

  float beatBright = beatPump * density * 0.3;

  vec3 col = hsvToRgb(
    iridescentHue,
    clamp(iridescentSat, 0.0, 1.0),
    clamp(iridescentVal + beatBright, 0.0, 1.0)
  );

  // === VORTEX CENTER HIGHLIGHTS ===
  float vortexHighlight = smoothstep(0.7, 1.0, density) *
    (flowMagNorm * 0.5) * uIntensity;

  vec3 finalCol = vec3(
    col.x + vortexHighlight * 0.2,
    col.y + vortexHighlight * 0.15,
    col.z + vortexHighlight * 0.25
  );

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uVeinFrequency;
uniform float uTurbulence;
uniform float uWarpPasses;

// 2D hash noise
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Smooth value noise
float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - f * 2.0);

  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Mineral palette: deep navy -> royal blue -> gold -> cream -> dark vein
vec3 mineralColor(float t, float paletteShift) {
  float shifted = fract(t + paletteShift * 0.1);

  vec3 darkVein = vec3(0.02, 0.02, 0.05);
  vec3 navy = vec3(0.05, 0.08, 0.25);
  vec3 royal = vec3(0.15, 0.25, 0.55);
  vec3 gold = vec3(0.85, 0.68, 0.25);
  vec3 cream = vec3(0.95, 0.92, 0.88);

  float s1 = smoothstep(0.0, 0.2, shifted);
  float s2 = smoothstep(0.2, 0.4, shifted);
  float s3 = smoothstep(0.4, 0.6, shifted);
  float s4 = smoothstep(0.6, 0.85, shifted);
  float s5 = smoothstep(0.85, 1.0, shifted);

  vec3 c1 = mix(darkVein, navy, s1);
  vec3 c2 = mix(c1, royal, s2);
  vec3 c3 = mix(c2, gold, s3);
  vec3 c4 = mix(c3, cream, s4);
  return mix(c4, darkVein, s5);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.1);

  // Audio influences
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetShock = uOnset * uSensitivity;

  // Warp strength modulated by bass and onset
  float warpStr = uTurbulence + bassVal * 2.2 + onsetShock * 2.5 + sin(uTime * 0.3) * 0.15;

  // --- Domain warp pass 1 ---
  vec2 np1 = p * 3.0 + vec2(time * 0.1, time * 0.07);
  float w1x = (valueNoise(np1) - 0.5) * warpStr;
  float w1y = (valueNoise(np1 + vec2(5.2, 1.3)) - 0.5) * warpStr;
  vec2 p1 = vec2(p.x + w1x, p.y + w1y);

  // --- Domain warp pass 2 ---
  vec2 np2 = p1 * 4.0 + vec2(time * 0.13, -time * 0.09);
  float w2x = (valueNoise(np2 + vec2(17.3, 31.7)) - 0.5) * (warpStr * 0.7);
  float w2y = (valueNoise(np2 + vec2(43.1, 67.2)) - 0.5) * (warpStr * 0.7);
  vec2 p2 = vec2(p1.x + w2x, p1.y + w2y);

  // --- Domain warp pass 3 (more chaotic, scaled by uChaos) ---
  vec2 np3 = p2 * 5.0 + vec2(-time * 0.07, time * 0.11);
  float w3x = (valueNoise(np3 + vec2(71.5, 97.3)) - 0.5) * (warpStr * 0.5 * (uChaos + 0.3));
  float w3y = (valueNoise(np3 + vec2(113.7, 29.1)) - 0.5) * (warpStr * 0.5 * (uChaos + 0.3));
  vec2 p3 = vec2(p2.x + w3x, p2.y + w3y);

  // --- Domain warp pass 4 (finest detail, controlled by warpPasses) ---
  float passWeight = smoothstep(3.0, 4.0, uWarpPasses);
  vec2 np4 = p3 * 7.0 + vec2(time * 0.05, time * 0.03);
  float w4x = (valueNoise(np4 + vec2(137.2, 53.8)) - 0.5) * (warpStr * 0.3) * passWeight;
  float w4y = (valueNoise(np4 + vec2(173.1, 83.4)) - 0.5) * (warpStr * 0.3) * passWeight;
  vec2 p4 = vec2(p3.x + w4x, p3.y + w4y);

  // --- Marble bands: sin of warped y-coordinate ---
  float veinVal = sin(p4.y * uVeinFrequency + p4.x * (uVeinFrequency * 0.3)) * 0.5 + 0.5;

  // Add secondary thinner veins
  float thinVein = sin(p4.y * (uVeinFrequency * 3.0) + p4.x * (uVeinFrequency * 1.5)) * 0.5 + 0.5;
  float combinedVein = mix(veinVal, thinVein, 0.3 + trebleVal * 0.2);

  // Mids shift the color reading position
  float colorShift = midsVal * 0.3;
  float marbleT = fract(combinedVein + colorShift + time * 0.02);

  // Apply mineral color palette
  vec3 col = mineralColor(marbleT, uPalette);

  // Add subtle iridescence from treble
  float iridR = trebleVal * sin(p4.x * 20.0 + time) * 0.1;
  float iridG = trebleVal * sin(p4.y * 20.0 + time * 1.3) * 0.08;
  float iridB = trebleVal * sin((p4.x + p4.y) * 15.0 + time * 0.7) * 0.12;

  // Intensity and energy brightness
  float brightness = uIntensity * 1.3 + uEnergy * uSensitivity * 0.2;
  float litR = col.x * brightness + iridR;
  float litG = col.y * brightness + iridG;
  float litB = col.z * brightness + iridB;

  // Beat pulse brightness
  float flash = beatPulse * 0.15;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(litR, litG, litB)); litR = _pc.r; litG = _pc.g; litB = _pc.b; }
  gl_FragColor = vec4(
    clamp(litR + flash, 0.0, 1.0),
    clamp(litG + flash, 0.0, 1.0),
    clamp(litB + flash, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
