__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 pp) {
  vec2 i = floor(pp);
  vec2 f = fract(pp);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmVal(vec2 pp) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) {
    v += a * noiseVal(pp);
    pp = m * pp * 2.0;
    a *= 0.5;
  }
  return v;
}

// Dimension palette: each fold reveals different world colors
vec3 dimensionColor(float layer, float t, float paletteShift) {
  float h = fract(layer * 0.618 + t * 0.1 + paletteShift * 0.2);
