mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float warmthVal = uWarmth * uSensitivity;

  vec3 col = vec3(0.0);

  // Domain warp: fold reality
  vec2 warpedP = p;
  float foldDepth = 3.0 + bassVal * 4.0; // bass deepens folds
  float foldSharpness = 1.0 + trebleVal * 5.0; // treble sharpens creases

  // Multi-layer domain warping creates fold geometry
  vec2 warp1 = vec2(
    fbmVal(warpedP * 1.5 + time * 0.3),
    fbmVal(warpedP * 1.5 + vec2(5.2, 1.3) + time * 0.25)
  );
  warpedP += warp1 * 0.8 * (1.0 + bassVal * 0.5);

  vec2 warp2 = vec2(
    fbmVal(warpedP * 2.0 + warp1 * foldDepth + time * 0.15),
    fbmVal(warpedP * 2.0 + warp1 * foldDepth + vec2(1.7, 9.2) + time * 0.2)
  );
  warpedP += warp2 * 0.4;

  // Fold creases: where the warp gradient is steepest
  float warpMag = length(warp2 - warp1);
  float crease = pow(warpMag, foldSharpness);
  float creaseLine = smoothstep(0.0, 0.3, crease);

  // Multiple fold layers (accordion pages)
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float layerOffset = fi * 1.7 + time * 0.1;

    // Each layer has its own folding
    vec2 layerP = rot2(fi * 0.3 + time * 0.05) * warpedP;
    float foldPattern = sin(layerP.x * (3.0 + fi * 1.5) + layerOffset) * 0.5 + 0.5;
    foldPattern *= sin(layerP.y * (2.0 + fi * 1.2) - layerOffset * 0.7) * 0.5 + 0.5;

    // Accordion fold: sharp peaks and valleys
    float accordion = abs(sin(
      (layerP.x + layerP.y * 0.5) * (2.0 + fi + bassVal * 2.0) + time * 0.5 + fi
    ));
    accordion = pow(accordion, 0.5 + trebleVal * 2.0); // treble sharpens

    // Each fold page is a "dimension" with its own color
    float pageIdx = floor((layerP.x + layerP.y * 0.5) * (2.0 + fi) + time * 0.5 + fi + 0.5);
    vec3 dimColor = dimensionColor(pageIdx + fi, time, uPalette);

    // Fold interior pattern (each dimension has unique pattern)
    float dimPattern = fbmVal((layerP + fi * 3.0) * (2.0 + fi * 0.5));
    dimColor *= 0.5 + dimPattern * 0.5;

    // Crease highlight
    float foldCrease = smoothstep(0.02, 0.0, abs(accordion - 0.5)) * foldSharpness;

    float layerAlpha = foldPattern * accordion * (0.3 - fi * 0.04);
    col += dimColor * layerAlpha;
    col += vec3(1.0, 0.95, 0.9) * foldCrease * 0.2 * (1.0 - fi * 0.15);
  }

  // Central fold nexus: where all dimensions converge
  float nexusDist = length(warpedP);
  float nexusGlow = smoothstep(0.8, 0.0, nexusDist) * 0.3;
  vec3 nexusColor = vec3(1.0, 0.9, 0.8) * nexusGlow;
  nexusColor += dimensionColor(time * 0.3, 0.0, uPalette) * smoothstep(0.3, 0.0, nexusDist) * 0.4;
  col += nexusColor;

  // Crease highlights (bright lines where folds meet)
  col += vec3(1.0, 0.95, 0.85) * creaseLine * 0.15 * trebleVal;

  // Dimensional bleed: colors from adjacent folds leak through
  vec3 bleedColor = dimensionColor(warp1.x * 3.0, time, uPalette + 0.5);
  float bleed = smoothstep(0.3, 0.7, warpMag) * 0.2;
  col += bleedColor * bleed * midsVal;

  // Kick: fold collapse flash
  if (kickVal > 0.2) {
    float collapseWave = smoothstep(kickVal * 2.0, 0.0, nexusDist);
    col += vec3(0.8, 0.7, 0.5) * collapseWave * kickVal * 0.5;
  }

  // Spectral flux: dimension shimmer
  col += col * fluxVal * 0.3;

  // Warmth tint
  col += vec3(0.1, 0.05, 0.0) * warmthVal * 0.2;

  // Chaos: more extreme folding
  col *= 1.0 + sin(warpedP.x * 20.0 + warpedP.y * 15.0) * uChaos * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 pp) {
  vec2 i = floor(pp);
  vec2 f = fract(pp);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Palace ornament pattern
float ornament(vec2 pp, float scale) {
  pp *= scale;
  vec2 cell = fract(pp) - 0.5;
  float d = length(cell);
  float petal = cos(atan(cell.y, cell.x) * 4.0) * 0.3 + 0.2;
  float flower = smoothstep(petal + 0.02, petal, d);
  float ring = smoothstep(0.02, 0.0, abs(d - 0.35));
  return max(flower, ring);
}

// DMT jewel palette
vec3 palaceColor(float t, float paletteShift) {
  t = fract(t + paletteShift * 0.15);
  vec3 c;
  if (t < 0.25) c = mix(vec3(0.85, 0.65, 0.1), vec3(0.8, 0.1, 0.15), t * 4.0);    // gold -> ruby
  else if (t < 0.5) c = mix(vec3(0.8, 0.1, 0.15), vec3(0.05, 0.7, 0.35), (t - 0.25) * 4.0); // ruby -> emerald
  else if (t < 0.75) c = mix(vec3(0.05, 0.7, 0.35), vec3(0.1, 0.2, 0.9), (t - 0.5) * 4.0);  // emerald -> sapphire
  else c = mix(vec3(0.1, 0.2, 0.9), vec3(0.85, 0.65, 0.1), (t - 0.75) * 4.0);               // sapphire -> gold
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float kickVal = uKick * uSensitivity * 1.5;
  float beatVal = uBeat * uSensitivity * 1.5;
  float energyVal = uEnergy * uSensitivity * 1.5;
  float harmonicVal = uHarmonicity * uSensitivity * 1.5;

  // Forward motion through corridor
  float forwardSpeed = time * 1.5 + beatVal * 0.3 + kickVal * 0.8;

  // Tunnel coordinates
  float r = length(p);
  float angle = atan(p.y, p.x);
  float depth = 1.0 / (r + 0.001) - forwardSpeed;

  vec3 col = vec3(0.01, 0.005, 0.015);

  // Corridor walls: repeating arched sections
  float section = fract(depth * 0.15);
  float sectionIdx = floor(depth * 0.15);

  // Arch shape
  float archAngle = atan(p.y, abs(p.x));
  float archShape = smoothstep(0.0, 0.05, abs(sin(archAngle * 2.0)) - 0.3);

  // Wall ornaments: fractal flower patterns
  vec2 wallUV = vec2(angle / 6.2832 + 0.5, fract(depth * 0.3));
  float wallOrnament = ornament(wallUV, 6.0 + midsVal * 2.0);
  float wallOrnament2 = ornament(wallUV * 2.0 + 0.5, 8.0);

  // Floor/ceiling pattern: checkerboard with jewel inlays
  vec2 floorUV = vec2(angle / 6.2832, depth * 0.2);
  vec2 floorCell = fract(floorUV * 8.0) - 0.5;
  float checker = step(0.0, floorCell.x * floorCell.y);
  float jewel = smoothstep(0.2, 0.15, length(floorCell));

  // Perspective depth fade
  float depthFade = 1.0 / (1.0 + r * 0.5);
  float deepFade = exp(-r * 0.8);

  // Column pillars at regular angles
  float pillarAngle = fract(angle / 1.0472) - 0.5; // every 60 degrees
  float pillar = smoothstep(0.06, 0.03, abs(pillarAngle)) * depthFade;

  // Wall color per section
  vec3 wallColor = palaceColor(sectionIdx * 0.15 + section * 0.3, uPalette);
  wallColor *= 0.3 + wallOrnament * 0.7;
  wallColor += palaceColor(sectionIdx * 0.15 + 0.5, uPalette) * wallOrnament2 * 0.3;

  // Section transitions: golden arch separators
  float archSeparator = smoothstep(0.02, 0.0, abs(section - 0.5)) * 0.8;
  float archEdge = smoothstep(0.04, 0.0, min(section, 1.0 - section));

  // Ceiling mandala
  float ceilDist = abs(angle - 1.5708); // distance from top
  float mandala = 0.0;
  if (ceilDist < 0.8) {
    vec2 mandP = vec2(ceilDist * 3.0, depth * 0.2);
    mandP = rot2(time * 0.1) * mandP;
    float mandR = length(mandP);
    float mandA = atan(mandP.y, mandP.x);
    mandala = pow(cos(mandA * 8.0) * 0.5 + 0.5, 2.0) * smoothstep(1.0, 0.0, mandR);
  }

  // Assemble corridor
  col += wallColor * depthFade * 0.8;
  col += vec3(0.85, 0.65, 0.1) * archSeparator * depthFade; // gold arches
  col += vec3(1.0, 0.95, 0.8) * archEdge * depthFade * 0.3;
  col += vec3(0.2, 0.1, 0.0) * pillar; // dark pillars
  col += palaceColor(depth * 0.05 + time * 0.02, uPalette) * jewel * depthFade * 0.5;
  col += vec3(0.85, 0.7, 0.2) * mandala * deepFade * 0.4;

  // Floor reflection
  if (p.y < 0.0) {
    float floorReflect = smoothstep(0.0, -0.5, p.y);
    col *= 0.7 + checker * 0.3 * floorReflect;
  }

  // Fractal detail on walls (Mandelbrot-ish)
  vec2 fracP = wallUV * 3.0 - 1.5;
  vec2 z = fracP;
  float fracIter = 0.0;
  for (int i = 0; i < 16; i++) {
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + fracP;
    if (dot(z, z) > 4.0) break;
    fracIter += 1.0;
  }
  float fracColor = fracIter / 16.0;
  col += palaceColor(fracColor + time * 0.08 + sin(uTime * 0.2) * 0.15, uPalette) * fracColor * depthFade * 0.25;

  // Vanishing point glow
  float vpGlow = smoothstep(0.3, 0.0, r);
  col += vec3(1.0, 0.9, 0.7) * vpGlow * 0.3 * (1.0 + bassVal * 0.5);

  // Treble sparkle on ornaments
  float sparkle = pow(wallOrnament, 5.0) * trebleVal;
  col += vec3(1.0, 0.95, 0.85) * sparkle * depthFade * 0.3;

  // Kick: forward lurch flash
  col += vec3(0.3, 0.2, 0.05) * kickVal * 0.4 * vpGlow;

  // Harmonic resonance glow
  col += palaceColor(harmonicVal, uPalette) * harmonicVal * 0.1;

  // Chaos: ornament distortion
  col *= 1.0 + sin(depth * 10.0 + angle * 5.0) * uChaos * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uVariationMix;
uniform float uTendrilDensity;

#define PI 3.14159265
#define TAU 6.28318530

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Variation functions (from fractal flame algorithm)

// V0: Linear
vec2 vLinear(vec2 p) {
  return p;
}

// V1: Sinusoidal
vec2 vSinusoidal(vec2 p) {
  return vec2(sin(p.x), sin(p.y));
}

// V2: Spherical (1/r^2 inversion)
vec2 vSpherical(vec2 p) {
  float r2 = dot(p, p) + 0.0001;
  return p / r2;
}

// V3: Swirl
vec2 vSwirl(vec2 p) {
  float r2 = dot(p, p);
  float sr = sin(r2);
  float cr = cos(r2);
  return vec2(p.x * sr - p.y * cr, p.x * cr + p.y * sr);
}

// V4: Horseshoe
vec2 vHorseshoe(vec2 p) {
  float r = length(p) + 0.0001;
  return vec2((p.x - p.y) * (p.x + p.y), 2.0 * p.x * p.y) / r;
}

// V5: Polar
vec2 vPolar(vec2 p) {
  float r = length(p);
  float theta = atan(p.y, p.x);
  return vec2(theta / PI, r - 1.0);
}

// V6: Handkerchief
vec2 vHandkerchief(vec2 p) {
  float r = length(p);
  float theta = atan(p.y, p.x);
  return r * vec2(sin(theta + r), cos(theta - r));
}

// Mix variations based on parameter and audio
vec2 applyVariations(vec2 p, float mix1, float time, float beat) {
  vec2 v0 = vSinusoidal(p);
  vec2 v1 = vSpherical(p);
  vec2 v2 = vSwirl(p);
  vec2 v3 = vHorseshoe(p);
  vec2 v4 = vPolar(p);
  vec2 v5 = vHandkerchief(p);

  // Blend based on mix parameter and time
  float t = mix1 + sin(time * 0.2) * 0.2 + beat * 0.1;
  float phase = fract(t);

  // Crossfade between pairs of variations
  vec2 blend1 = mix(v0, v1, smoothstep(0.0, 0.5, phase));
  vec2 blend2 = mix(v2, v3, smoothstep(0.0, 0.5, phase));
  vec2 blend3 = mix(v4, v5, smoothstep(0.0, 0.5, phase));

  float sel = fract(t * 0.33);
  if (sel < 0.33) return mix(blend1, blend2, sel * 3.0);
  if (sel < 0.66) return mix(blend2, blend3, (sel - 0.33) * 3.0);
  return mix(blend3, blend1, (sel - 0.66) * 3.0);
}

// Flame palette
vec3 flamePalette(float t, float offset) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 0.7, 0.4);
  vec3 d = vec3(0.0 + offset * 0.1, 0.15, 0.2);
  return a + b * cos(TAU * (c * t + d));
}

void main() {
  vec2 uv = (vUv - 0.5) * (uZoom * 4.0 + 2.0);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.8;

  // Audio (boosted reactivity)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  vec3 col = vec3(0.0);
  float accumDensity = 0.0;
  float accumColor = 0.0;

  // Iterate the IFS (fractal flame iteration)
  // We run multiple points and accumulate density
  float density = uTendrilDensity * 2.0 + 0.5;

  for (int layer = 0; layer < 4; layer++) {
    float fl = float(layer);
    vec2 p = uv * (0.8 + fl * 0.15);

    // Initial rotation per layer
    float initAngle = fl * PI * 0.25 + time * 0.1;
    float ic = cos(initAngle), is2 = sin(initAngle);
    p = vec2(p.x * ic - p.y * is2, p.x * is2 + p.y * ic);

    float layerAccum = 0.0;
    float colorAccum = 0.0;

    // Iterate the flame function
    for (int i = 0; i < 10; i++) {
      float fi = float(i);

      // Apply affine transform (rotation + translation)
      float angle = time * (0.3 + fl * 0.1) + fi * 0.5 + bassVal * 0.5;
      float ca = cos(angle), sa = sin(angle);
      p = vec2(p.x * ca - p.y * sa, p.x * ca + p.y * sa) * 0.95;

      // Translate
      p += vec2(
        sin(time * 0.2 + fi * 1.7 + fl * 2.3) * 0.3,
        cos(time * 0.15 + fi * 2.1 + fl * 1.9) * 0.3
      ) * (1.0 + uChaos * 0.5);

      // Apply variation functions
      p = applyVariations(p, uVariationMix + fi * 0.1, time + fl * 0.5, beatPulse);

      // Accumulate density at this point
      float r = length(p);
      float localDensity = exp(-r * r * density);
      layerAccum += localDensity;
      colorAccum += fract(r * 2.0 + fi * 0.3 + fl * 0.25);
    }

    // Layer contribution
    float layerWeight = 1.0 / (fl + 1.0);
    accumDensity += layerAccum * layerWeight;
    accumColor += colorAccum * layerWeight;
  }

  // Normalize
  accumDensity *= 0.05;
  accumColor *= 0.03;

  // Color from accumulated flame
  float colorT = fract(accumColor + time * 0.04 + sin(uTime * 0.2) * 0.15);
  vec3 flameCol = flamePalette(colorT, uPalette);

  // Density mapping: log-density coloring (characteristic of fractal flames)
  float logDensity = log(1.0 + accumDensity * 5.0);
  col = flameCol * logDensity;

  // Treble enhances fine structure
  col += flamePalette(fract(colorT + 0.3), uPalette) * logDensity * trebleVal * 0.5;

  // Mids shift color
  col = mix(col, flamePalette(fract(colorT + midsVal * 0.4), uPalette) * logDensity, midsVal * 0.3);

  // Beat flash
  float beatGlow = beatPulse * exp(-length(uv) * 0.3);
  col += flamePalette(fract(time * 0.1), uPalette) * beatGlow * 0.5;

  // Onset surge
  col += vec3(onset * 0.08);

  // Kick brightness
  col *= 1.0 + kick * 0.3;

  // Intensity and energy
  col *= uIntensity * 1.8;
  col *= 1.0 + energy * 0.25;

  // Subtle background
  col += flamePalette(fract(length(vUv - 0.5) + time * 0.01), uPalette) * 0.01;

  // Vignette
  float vig = 1.0 - smoothstep(0.5, 1.2, length(vUv - 0.5) * 1.4);
  col *= vig;

  col += vec3(0.008, 0.005, 0.01);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFractalDepth;
uniform float uSpawnRate;
uniform float uContractionForce;
uniform float uColorCycleSpeed;

#define PI 3.14159265
#define TAU 6.28318530

// Domain coloring palette with psychedelic hue cycling
vec3 domainColor(float t, float shift) {
  float h = fract(t + shift);
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(0.0 + shift * 0.3, 0.33, 0.67);
  return a + b * cos(TAU * (c * h + d));
}

// Smooth iteration count for anti-aliased fractal coloring
float smoothEscape(float zr, float zi, float iter) {
  float mag = sqrt(zr * zr + zi * zi);
  return iter - log(log(mag)) / log(2.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.8;

  // Audio modulators (boosted reactivity)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float kickPulse = uKick * uSensitivity * 1.5;
  float onsetFlash = uOnset * uSensitivity * 1.5;
  float energyVal = uEnergy * uSensitivity * 1.5;

  // Deep zoom — bass contracts (zooms in), auto-zoom over time
  float zoomLevel = 1.5 + uZoom * 3.0;
  float breathe = sin(time * 0.3) * 0.2 * uContractionForce;
  float bassContract = bassVal * uContractionForce * 0.8;
  zoomLevel += breathe + bassContract + kickPulse * 0.5;

  // Zoom center slowly orbits around interesting regions
  float cx = -0.745 + sin(time * 0.05) * 0.01 + cos(time * 0.07) * 0.005;
  float cy = 0.186 + cos(time * 0.04) * 0.01 + sin(time * 0.06) * 0.005;

  // Beat shifts the fractal seed point
  cx += beatPulse * 0.002 * sin(time * 1.5);
  cy += beatPulse * 0.002 * cos(time * 1.7);

  // Apply zoom
  float scale = pow(2.0, -zoomLevel);
  float cr = cx + p.x * scale;
  float ci = cy + p.y * scale;

  // Chaos warps the c-plane
  float chaosWarp = uChaos * 0.02 * scale;
  cr += sin(p.y * 10.0 + time) * chaosWarp;
  ci += cos(p.x * 10.0 + time * 0.7) * chaosWarp;

  // Mandelbrot iteration with orbit traps
  int maxIter = int(uFractalDepth * 100.0 + 50.0);
  float zr = 0.0;
  float zi = 0.0;
  float iter = 0.0;
  float orbitTrapMin = 1e10;
  float orbitTrapCross = 1e10;
  float orbitAngleAccum = 0.0;

  // Child fractal accumulators
  float childGlow = 0.0;

  for (int i = 0; i < 150; i++) {
    if (i >= maxIter) break;
    float mag2 = zr * zr + zi * zi;
    if (mag2 > 256.0) break;

    // Standard Mandelbrot z = z^2 + c
    float newZr = zr * zr - zi * zi + cr;
    float newZi = 2.0 * zr * zi + ci;
    zr = newZr;
    zi = newZi;
    iter += 1.0;

    // Orbit trap: distance to origin (creates circular patterns)
    float trapDist = sqrt(zr * zr + zi * zi);
    orbitTrapMin = min(orbitTrapMin, trapDist);

    // Orbit trap: distance to axes (creates cross patterns)
    float crossDist = min(abs(zr), abs(zi));
    orbitTrapCross = min(orbitTrapCross, crossDist);

    // Angle accumulation for spiral coloring
    orbitAngleAccum += atan(zi, zr);

    // Child fractal spawning — treble makes the orbit glow at spawn points
    float spawnPhase = sin(float(i) * 0.5 + time * uSpawnRate * 2.0);
    float spawnTrigger = smoothstep(0.7, 1.0, spawnPhase) * trebleVal;
    childGlow += spawnTrigger * exp(-trapDist * 3.0) * 0.1;
  }

  // Smooth coloring
  float smoothIter = iter;
  if (zr * zr + zi * zi > 4.0) {
    smoothIter = smoothEscape(zr, zi, iter);
  }
  float normalizedIter = smoothIter / float(maxIter);

  // Color computation — domain coloring with multiple layers
  float colorTime = time * uColorCycleSpeed;

  // Layer 1: iteration-based coloring
  float t1 = fract(normalizedIter * 3.0 + colorTime * 0.15 + uPalette * 0.1 + sin(uTime * 0.2) * 0.15);
  vec3 iterColor = domainColor(t1, midsVal * 0.5);

  // Layer 2: orbit trap coloring
  float t2 = fract(orbitTrapMin * 2.0 + colorTime * 0.15);
  vec3 trapColor = domainColor(t2, uPalette * 0.15 + 0.33);

  // Layer 3: angle-based coloring for spiral patterns
  float t3 = fract(orbitAngleAccum * 0.02 + colorTime * 0.05);
  vec3 angleColor = domainColor(t3, uPalette * 0.2 + 0.67);

  // Interior vs exterior blending
  float isInterior = step(float(maxIter) - 0.5, iter);
  float exteriorMask = 1.0 - isInterior;

  // Exterior: smooth gradient coloring
  vec3 exteriorCol = mix(iterColor, trapColor, 0.4);
  exteriorCol = mix(exteriorCol, angleColor, 0.2);
  exteriorCol *= (0.5 + normalizedIter * 0.5);

  // Interior: deep, rich orbit trap coloring
  float interiorTrap = 1.0 - clamp(orbitTrapMin * 2.0, 0.0, 1.0);
  float interiorCross = 1.0 - clamp(orbitTrapCross * 5.0, 0.0, 1.0);
  vec3 interiorCol = domainColor(interiorTrap + colorTime * 0.08, 0.5);
  interiorCol += domainColor(interiorCross + colorTime * 0.1, 0.7) * interiorCross * 0.5;
  interiorCol *= 0.3 + interiorTrap * 0.7;

  // Mother breathing glow in the interior
  float motherBreath = sin(time * 0.6 + orbitTrapMin * 5.0) * 0.5 + 0.5;
  motherBreath *= bassVal * uContractionForce;
  interiorCol += domainColor(motherBreath + colorTime * 0.2, 0.0) * motherBreath * 0.3;

  // Combine interior and exterior
  vec3 col = mix(exteriorCol, interiorCol, isInterior);

  // Child fractal glow overlay (treble-reactive spawning)
  vec3 childColor = domainColor(childGlow * 3.0 + colorTime, trebleVal);
  col += childColor * childGlow * uSpawnRate * 2.0;

  // Kick: bright flash at fractal boundary
  float boundary = smoothstep(0.01, 0.0, abs(normalizedIter - 0.5)) * exteriorMask;
  col += vec3(1.0, 0.9, 0.7) * boundary * kickPulse * 0.5;

  // Onset: psychedelic color inversion pulse
  float invertAmt = onsetFlash * 0.4;
  col = mix(col, vec3(1.0) - col, invertAmt);

  // Energy brightness boost
  col *= 1.0 + energyVal * 0.3;

  // Beat pulse: radial glow from center
  float centerDist = length(p);
  float beatGlow = beatPulse * exp(-centerDist * centerDist * 2.0) * 0.3;
  col += domainColor(beatGlow + time * 0.3, 0.0) * beatGlow;

  // Final intensity
  col *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

