uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uArmCount;
uniform float uSpiralTightness;
uniform float uRotateRate;

// Psychedelic spiral palette
vec3 spiralPalette(float t, float paletteOffset) {
  float shifted = fract(t + paletteOffset * 0.12);
  float pi2 = 6.28318;
  float r = 0.5 + 0.5 * cos(pi2 * (shifted * 1.0 + 0.0));
  float g = 0.5 + 0.5 * cos(pi2 * (shifted * 1.0 + 0.25));
  float b = 0.5 + 0.5 * cos(pi2 * (shifted * 1.0 + 0.5));
  return vec3(r, g, b);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio-reactive modulators (boosted)
  float bassMod = bass() * uSensitivity * 2.0;
  float midsMod = mids() * uSensitivity * 1.8;
  float trebleMod = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onsetFlash = uOnset * uSensitivity * 1.5;
  float energyDrive = uEnergy * uSensitivity * 1.5;

  // Bass expands the spiral structure
  float expansion = 1.0 + bassMod * 0.3;

  // Initial polar-like coordinates
  float fx = p.x * expansion;
  float fy = p.y * expansion;

  // Accumulated angle and radius for coloring
  float angleAccum = 0.0;
  float radiusAccum = 0.0;

  // Rotation angle driven by time and audio
  float rotAngle = time * uRotateRate + midsMod * 0.5;

  // --- Fold iteration 1 ---
  float r1 = fx * fx + fy * fy + 0.0001;
  float spiralAngle1 = sin(fx * 3.14159 + fy * 0.5);
  angleAccum += spiralAngle1;
  float logR1 = r1 + 0.001;
  float spiralPhase1 = logR1 * (uSpiralTightness * 6.0) + spiralAngle1 * uArmCount;
  float foldVal1 = sin(spiralPhase1 + rotAngle);
  float cosR1 = cos(0.8 + uChaos * 0.3);
  float sinR1 = sin(0.8 + uChaos * 0.3);
  float fx1 = (fx * cosR1 - fy * sinR1) * 1.8 + foldVal1 * 0.3;
  float fy1 = (fx * sinR1 + fy * cosR1) * 1.8 + foldVal1 * 0.2;
  radiusAccum += foldVal1 * foldVal1;

  // --- Fold iteration 2 ---
  float r2 = fx1 * fx1 + fy1 * fy1 + 0.0001;
  float spiralAngle2 = sin(fx1 * 2.5 + fy1 * 0.7);
  angleAccum += spiralAngle2 * 0.8;
  float logR2 = r2 + 0.001;
  float spiralPhase2 = logR2 * (uSpiralTightness * 5.0) + spiralAngle2 * uArmCount;
  float foldVal2 = sin(spiralPhase2 + rotAngle * 1.3);
  float cosR2 = cos(0.65 + uChaos * 0.25);
  float sinR2 = sin(0.65 + uChaos * 0.25);
  float fx2 = (fx1 * cosR2 - fy1 * sinR2) * 1.6 + foldVal2 * 0.25;
  float fy2 = (fx1 * sinR2 + fy1 * cosR2) * 1.6 + foldVal2 * 0.15;
  radiusAccum += foldVal2 * foldVal2 * 0.8;

  // --- Fold iteration 3 ---
  float r3 = fx2 * fx2 + fy2 * fy2 + 0.0001;
  float spiralAngle3 = sin(fx2 * 2.0 + fy2 * 0.9);
  angleAccum += spiralAngle3 * 0.6;
  float logR3 = r3 + 0.001;
  float spiralPhase3 = logR3 * (uSpiralTightness * 4.0) + spiralAngle3 * uArmCount;
  float foldVal3 = sin(spiralPhase3 + rotAngle * 1.7);
  float cosR3 = cos(0.5 + uChaos * 0.2);
  float sinR3 = sin(0.5 + uChaos * 0.2);
  float fx3 = (fx2 * cosR3 - fy2 * sinR3) * 1.5 + foldVal3 * 0.2;
  float fy3 = (fx2 * sinR3 + fy2 * cosR3) * 1.5 + foldVal3 * 0.12;
  radiusAccum += foldVal3 * foldVal3 * 0.6;

  // --- Fold iteration 4 ---
  float r4 = fx3 * fx3 + fy3 * fy3 + 0.0001;
  float spiralAngle4 = sin(fx3 * 1.8 + fy3 * 1.1);
  angleAccum += spiralAngle4 * 0.4;
  float logR4 = r4 + 0.001;
  float spiralPhase4 = logR4 * (uSpiralTightness * 3.5) + spiralAngle4 * uArmCount;
  float foldVal4 = sin(spiralPhase4 + rotAngle * 2.1);
  float cosR4 = cos(0.4 + uChaos * 0.15);
  float sinR4 = sin(0.4 + uChaos * 0.15);
  float fx4 = (fx3 * cosR4 - fy3 * sinR4) * 1.4 + foldVal4 * 0.15;
  float fy4 = (fx3 * sinR4 + fy3 * cosR4) * 1.4 + foldVal4 * 0.1;
  radiusAccum += foldVal4 * foldVal4 * 0.4;

  // --- Fold iteration 5 ---
  float r5 = fx4 * fx4 + fy4 * fy4 + 0.0001;
  float spiralAngle5 = sin(fx4 * 1.5 + fy4 * 1.3);
  angleAccum += spiralAngle5 * 0.3;
  float logR5 = r5 + 0.001;
  float spiralPhase5 = logR5 * (uSpiralTightness * 3.0) + spiralAngle5 * uArmCount;
  float foldVal5 = sin(spiralPhase5 + rotAngle * 2.5);
  radiusAccum += foldVal5 * foldVal5 * 0.3;

  // --- Fold iteration 6 ---
  float cosR6 = cos(0.3 + uChaos * 0.12);
  float sinR6 = sin(0.3 + uChaos * 0.12);
  float fx6 = (fx4 * cosR6 - fy4 * sinR6) * 1.3 + foldVal5 * 0.1;
  float fy6 = (fx4 * sinR6 + fy4 * cosR6) * 1.3;
  float r6 = fx6 * fx6 + fy6 * fy6 + 0.0001;
  float spiralAngle6 = sin(fx6 * 1.2 + fy6 * 1.5);
  angleAccum += spiralAngle6 * 0.2;
  float logR6 = r6 + 0.001;
  float spiralPhase6 = logR6 * (uSpiralTightness * 2.5) + spiralAngle6 * uArmCount;
  float foldVal6 = sin(spiralPhase6 + rotAngle * 3.0);
  radiusAccum += foldVal6 * foldVal6 * 0.2;

  // Normalize accumulated values
  float normAngle = fract(angleAccum * 0.1 + time * 0.02);
  float normRadius = clamp(radiusAccum * 0.15, 0.0, 1.0);

  // Treble shimmer on fine detail
  float shimmer = trebleMod * (sin(radiusAccum * 20.0 + time * 5.0) * 0.5 + 0.5) * 0.2;

  // Color from angle + radius through palette
  float colorT = fract(normAngle + normRadius * 0.5 + midsMod * 0.3 + sin(uTime * 0.2) * 0.15);
  vec3 col = spiralPalette(colorT, uPalette);

  // Combine spiral brightness
  float spiralBright = normRadius + shimmer + energyDrive * 0.15;

  // Apply intensity
  float brightness = uIntensity * 1.3;
  vec3 litCol = vec3(
    col.x * spiralBright * brightness,
    col.y * spiralBright * brightness,
    col.z * spiralBright * brightness
  );

  // Beat pulse glow
  float beatGlow = beatPulse * 0.2 * spiralBright;
  vec3 glowCol = litCol + vec3(beatGlow, beatGlow, beatGlow);

  // Onset flash
  float flash = onsetFlash * 0.25;
  vec3 finalCol = glowCol + vec3(flash, flash, flash);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
__SA_FBM__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPersistence;

// Warm palette: reds, oranges, yellows
vec3 warmPalette(float t) {
  return 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * t + vec3(0.0, 0.1, 0.2)));
}

// Cool palette: blues, teals, purples
vec3 coolPalette(float t) {
  return 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * t + vec3(0.5, 0.6, 0.7)));
}

// Terrain height via D-controlled fBm
float terrainHeight(vec2 p) {
  return fbmControlledD(p * 0.3, uPersistence, 7) * 3.0;
}

// SDF: distance to terrain surface
float terrainSDF(vec3 p) {
  return p.y - terrainHeight(p.xz);
}

// Terrain normal via central differences
vec3 terrainNormal(vec3 p) {
  float eps = 0.02;
  float hC = terrainHeight(p.xz);
  float hR = terrainHeight(p.xz + vec2(eps, 0.0));
  float hU = terrainHeight(p.xz + vec2(0.0, eps));
  vec3 n = normalize(vec3(hC - hR, eps, hC - hU));
  return n;
}

void main() {
  vec2 uv = vUv * 2.0 - 1.0;
  uv = psychedelicUV(uv); // breathing morph
  uv.x *= 1.777; // Approximate 16:9 aspect

  float time = uTime * uSpeed * 0.8;

  // Audio-reactive persistence: 0.5 (smooth) → 0.7 (jagged) with energy
  float audioP = mix(0.5, 0.7, uEnergy * uSensitivity * 1.5);
  // uPersistence is set from update(), but we blend with audio here
  float persistence = mix(uPersistence, audioP, uSensitivity);

  // Camera setup — orbiting, breathing with BPM
  float camAngle = time * 0.3 + uChaos * sin(time * 0.1);
  float camRadius = 6.0 + uZoom * 4.0;
  float camHeight = 2.5 + uBpmSin * 0.4 * uSensitivity;

  vec3 camPos = vec3(
    cos(camAngle) * camRadius,
    camHeight,
    sin(camAngle) * camRadius
  );

  // Look at terrain center, slightly ahead of camera
  vec3 target = vec3(
    cos(camAngle + 0.3) * 2.0,
    0.8,
    sin(camAngle + 0.3) * 2.0
  );

  // Camera basis
  vec3 forward = normalize(target - camPos);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);

  // Ray direction
  vec3 rd = normalize(forward + uv.x * right * 0.8 + uv.y * up * 0.8);

  // Raymarching
  float t = 0.0;
  float maxDist = 80.0;
  vec3 hitPos = camPos;
  bool hit = false;

  for (int i = 0; i < 120; i++) {
    hitPos = camPos + rd * t;
    float d = terrainSDF(hitPos);
    if (d < 0.01) {
      hit = true;
      break;
    }
    if (t > maxDist) break;
    t += d * 0.5; // Conservative step for stability
  }

  vec3 color;

  if (hit) {
    vec3 normal = terrainNormal(hitPos);

    // Sun position: audio-reactive elevation
    float sunAngle = time * 0.1 + uPalette * 0.5;
    float sunElev = 0.4 + bass() * uSensitivity * 0.6;
    vec3 sunDir = normalize(vec3(cos(sunAngle), sunElev, sin(sunAngle)));

    // Diffuse lighting
    float diff = max(dot(normal, sunDir), 0.0);
    float ambient = 0.15;

    // Height-based color: low = dark, high = bright
    float h = hitPos.y / 3.0;

    // Palette from spectral centroid: warm (high centroid) vs cool (low)
    float centroidMix = clamp(uSpectralCentroid * uSensitivity * 2.0, 0.0, 1.0);
    vec3 warmCol = warmPalette(h * 0.5 + time * 0.02 + uPalette * 0.1);
    vec3 coolCol = coolPalette(h * 0.5 + time * 0.02 + uPalette * 0.1);
    vec3 baseColor = mix(coolCol, warmCol, centroidMix);

    // Apply lighting
    color = baseColor * (diff * 0.85 + ambient);

    // Height fog
    float fogDist = length(hitPos - camPos);
    float fog = 1.0 - exp(-fogDist * 0.03);
    vec3 fogColor = mix(vec3(0.05, 0.05, 0.12), vec3(0.15, 0.08, 0.2), centroidMix);
    color = mix(color, fogColor, fog);

    // Beat flash: brief luminance spike on peaks
    float beatFlash = uBeat * uSensitivity * 0.5;
    color += vec3(beatFlash);

    // Intensity control
    color *= uIntensity;
  } else {
    // Sky gradient
    float skyGrad = uv.y * 0.5 + 0.5;
    color = mix(vec3(0.02, 0.02, 0.06), vec3(0.08, 0.04, 0.15), skyGrad);
    color *= uIntensity * 0.5;
  }

  // Onset highlight — brief warm flash across scene
  color += vec3(0.15, 0.08, 0.02) * uOnset * uSensitivity * 1.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLatticeScale;
uniform float uGammaDepth;
uniform float uDeformStrength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

// Hexagonal lattice distance
float hexDist(vec2 p) {
  p = abs(p);
  return max(p.x * 0.866 + p.y * 0.5, p.y);
}

vec2 hexCenter(vec2 p) {
  vec2 s = vec2(1.0, 1.732);
  vec2 h = s * 0.5;
  vec2 a = mod(p, s) - h;
  vec2 b = mod(p - h, s) - h;
  if (dot(a, a) < dot(b, b)) return p - a;
  return p - b;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float bpmSinVal = uBpmSin;
  float centroidVal = uSpectralCentroid;
  float entropyVal = uSpectralEntropy;

  // Lattice scale
  float scale = 4.0 + uLatticeScale * 8.0;

  // Flux-driven deformation
  vec2 deform = vec2(
    sin(p.y * 3.0 + time * 2.0) * fluxVal * uDeformStrength * 0.2,
    cos(p.x * 3.0 - time * 1.5) * fluxVal * uDeformStrength * 0.2
  );
  vec2 dp = p + deform;

  // Hexagonal grid
  vec2 sp = dp * scale;
  vec2 cellCenter = hexCenter(sp);
  vec2 cellId = cellCenter;
  vec2 cellLocal = sp - cellCenter;
  float cellDist = hexDist(cellLocal);

  // Cell hash for variation
  float cellHash = hash(cellId);

  // Gamma spatial modulation: cells alternate between two states
  // 40Hz spatial frequency = checkerboard-like pattern modulated in space
  float gammaPhase = 40.0; // Spatial frequency
  float spatialGamma = sin((cellId.x + cellId.y) * gammaPhase + time * 0.5);
  spatialGamma *= uGammaDepth;

  // State A: filled / bright
  // State B: ring / dim
  float stateA = smoothstep(0.5, 0.2, cellDist); // Filled hexagon
  float stateB = smoothstep(0.45, 0.4, cellDist) - smoothstep(0.35, 0.3, cellDist); // Ring

  // Blend between states based on spatial gamma
  float gammaBlend = spatialGamma * 0.5 + 0.5;
  float cellPattern = mix(stateB, stateA, gammaBlend);

  // Color: electric purple and gold
  vec3 purple = vec3(0.5, 0.15, 0.9);
  vec3 gold = vec3(0.95, 0.8, 0.2);

  // Cells alternate purple/gold based on gamma state + position
  float colorPhase = cellHash + time * 0.05 + uPalette * 0.3;
  vec3 cellColor = mix(purple, gold, fract(colorPhase + gammaBlend * 0.3));

  // Edge glow
  float edgeGlow = smoothstep(0.5, 0.4, cellDist) * (1.0 - smoothstep(0.4, 0.35, cellDist));
  vec3 edgeColor = mix(gold, purple, 1.0 - gammaBlend);

  // Combine
  vec3 col = cellColor * cellPattern * 0.7;
  col += edgeColor * edgeGlow * 0.5;

  // Inner glow per cell
  float innerGlow = exp(-cellDist * cellDist * 20.0);
  col += innerGlow * mix(purple, gold, cellHash) * 0.2;

  // Bass: brightness pulse
  col *= 1.0 + bassVal * 0.25;

  // Treble: edge sparkle
  float sparkle = pow(noise(sp * 5.0 + time * 3.0), 6.0) * trebleVal;
  col += sparkle * vec3(0.8, 0.7, 1.0) * 0.3;

  // Mids: warm fill
  col += midsVal * 0.04 * vec3(0.6, 0.4, 0.3);

  // Kick: bright lattice flash
  col += kickVal * 0.2 * vec3(0.9, 0.85, 0.7);

  // Centroid: purple/gold balance shift
  col = mix(col, col * vec3(0.8, 0.7, 1.2), centroidVal * 0.2);

  // Entropy: lattice disorder
  col *= 1.0 + entropyVal * 0.1;

  // BPM breathing
  col *= 0.88 + (bpmSinVal * 0.5 + 0.5) * 0.15;

  // Energy brightness
  col *= 0.8 + energyVal * 0.3;

  // Chaos: noise overlay
  float chaosNoise = noise(sp + time * 2.0);
  col *= 1.0 + (chaosNoise - 0.5) * uChaos * 0.25;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

