__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSaturationPower;
uniform float uHueRotation;
uniform float uFieldSoftness;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 p = (vUv - 0.5 + 0.001) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.2; // Very slow rotation

  // Audio-reactive modulators — 2x
  float bassVal = bass() * uSensitivity * 1.6;
  float midsVal = mids() * uSensitivity * 1.4;
  float trebleVal = treble() * uSensitivity * 1.6;
  float energyVal = uEnergy * uSensitivity * 1.4;
  float centroidVal = uSpectralCentroid;
  float beatVal = uBeat * uSensitivity * 2.0;
  float warmthVal = uWarmth;
  float bpmSinVal = uBpmSin;
  float fluxVal = uSpectralFlux;

  // Base hue: faster rotation driven by time + spectral centroid
  float hue = time * uHueRotation * 0.5 + centroidVal * 0.6 + uPalette * 0.3 + sin(uTime * 0.3) * 0.2;

  // Ultra-soft spatial gradient (barely perceptible)
  float spatialGrad = length(p) * 0.1 * (1.0 - uFieldSoftness * 0.8);
  float angularGrad = atan(p.y, p.x) / 6.2832;

  // Extremely subtle noise for organic feel
  float softNoise = noise(p * (0.5 + uChaos * 2.0) + time * 0.5);
  softNoise = mix(0.5, softNoise, 0.1 + uChaos * 0.2);

  // Hue with subtle spatial variation
  float finalHue = hue + spatialGrad * 0.05 + angularGrad * 0.03 + softNoise * 0.05;

  // Saturation: driven by energy
  float sat = 0.5 + uSaturationPower * 0.4 + energyVal * 0.2;
  sat = clamp(sat, 0.0, 1.0);

  // Brightness: beat-modulated
  float brightness = 0.6 + beatVal * 0.3 + bpmSinVal * 0.1;
  brightness = clamp(brightness, 0.3, 1.0);

  // Convert to RGB
  vec3 col = hsv2rgb(vec3(fract(finalHue), sat, brightness));

  // Neon boost: push colors toward vivid neon
  col = pow(col, vec3(0.8)); // Gamma push for neon vibrancy
  col *= 1.2;

