  // Generate Apollonian gasket via circle inversions
  // Start with 3 mutually tangent circles + their Soddy circle
  float outerR = 1.0;
  float innerR = outerR / (1.0 + sqrt(3.0));

  // Three tangent circles
  for (int k = 0; k < 3; k++) {
    float angle = float(k) * TAU / 3.0 + time * 0.05;
