    float circR = innerR / scale;
    float dist = length(z) - innerR;
    float edge = smoothstep(0.01 / scale, 0.0, abs(dist) - 0.003 / scale);

    float fi = float(i);
    float hue = fi * 0.618033 + uPalette * 0.5 + time * 0.06 + sin(uTime * 0.2) * 0.15;
    vec3 circCol = 0.5 + 0.5 * cos(TAU * (hue + vec3(0.0, 0.33, 0.67)));

