  col += vec3(0.5, 0.4, 0.6) * smoothstep(0.005, 0.0, outerDist) * 0.5;

  // Ambient glow from accumulated circles
  col += vec3(0.3, 0.2, 0.5) * totalGlow;

  // Beat flash
