  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Voronoi with cell ID, distance to edge, and nearest point
vec4 voronoi(vec2 p, float time, float separation, float chaos) {
  vec2 ip = floor(p);
  vec2 fp = fract(p);

  float minDist = 10.0;
  float secondDist = 10.0;
  vec2 nearestId = vec2(0.0);
  vec2 nearestPoint = vec2(0.0);

