    for (int i = -1; i <= 1; i++) {
      vec2 neighbor = vec2(float(i), float(j));
      vec2 cellId = ip + neighbor;
      vec2 randomOffset = hash2(cellId);

      // Animate cell centers
      vec2 point = neighbor + randomOffset;
      point += sin(time * 0.5 + randomOffset * 6.283) * 0.3 * chaos;

      // Separation: push points outward from center on beat
      vec2 fromCenter = (cellId + randomOffset - p) * 0.1;
      point += fromCenter * separation;

      float d = length(fp - point);
      if (d < minDist) {
        secondDist = minDist;
        minDist = d;
        nearestId = cellId;
        nearestPoint = point;
      } else if (d < secondDist) {
        secondDist = d;
