vec3 videoContent(vec2 uv, float time) {
  vec3 col = vec3(0.0);

  // Color bars
  float barIdx = floor(uv.x * 7.0);
  vec3 bars[7];
  bars[0] = vec3(1.0, 1.0, 1.0);
  bars[1] = vec3(1.0, 1.0, 0.0);
  bars[2] = vec3(0.0, 1.0, 1.0);
  bars[3] = vec3(0.0, 1.0, 0.0);
  bars[4] = vec3(1.0, 0.0, 1.0);
  bars[5] = vec3(1.0, 0.0, 0.0);
  bars[6] = vec3(0.0, 0.0, 1.0);

  int idx = int(mod(barIdx, 7.0));
  if (idx == 0) col = bars[0];
  else if (idx == 1) col = bars[1];
  else if (idx == 2) col = bars[2];
  else if (idx == 3) col = bars[3];
  else if (idx == 4) col = bars[4];
  else if (idx == 5) col = bars[5];
  else col = bars[6];

