  float g2 = clamp(abs(fract(hue2 + 2.0 / 3.0) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
  float b2 = clamp(abs(fract(hue2 + 1.0 / 3.0) * 6.0 - 3.0) - 1.0, 0.0, 1.0);

