  float brightness = uIntensity * 2.0 + bassLevel * 1.2 + energyDrive * 0.6;
  float totalLight = rayIntensity + rayIntensity2 + coreGlow * 1.5 + dustVisible;

  // Onset flash on rays
  float flashBoost = onsetFlash * (rayIntensity + coreGlow) * 0.5;

  // Kick brightness pulse: screen-wide brightness pop
  float kickFlash = kickPunch * 0.8 * (radialFalloff * 0.5 + 0.5);

  float finalR = colR * (rayIntensity + coreGlow * 1.5 + dustVisible) * brightness
    + r2 * rayIntensity2 * brightness
    + coreGlow * 1.0 + flashBoost + kickFlash;
  float finalG = colG * (rayIntensity + coreGlow * 1.5 + dustVisible) * brightness
    + g2 * rayIntensity2 * brightness
    + coreGlow * 0.9 + flashBoost + kickFlash * 0.8;
  float finalB = colB * (rayIntensity + coreGlow * 1.5 + dustVisible) * brightness
    + b2 * rayIntensity2 * brightness
    + coreGlow * 0.7 + flashBoost + kickFlash * 0.6;

