  float beatPulse = uBeat * uSensitivity * 0.15 * (radialFalloff * 0.6 + 0.4);

  // Chaos adds flicker
  float flicker = sin(time * 8.0 + uChaos * 10.0) * uChaos * 0.05 * rayIntensity;

