  gl_FragColor = vec4(
    clamp(finalR + beatPulse + flicker + ambient, 0.0, 1.0),
    clamp(finalG + beatPulse + flicker + ambient * 0.8, 0.0, 1.0),
    clamp(finalB + beatPulse + flicker + ambient * 0.6, 0.0, 1.0),
    1.0
