uniform float uGrowthRate;
uniform float uRectangleShow;

#define PI 3.14159265
#define TAU 6.28318530
#define PHI 1.6180339887

vec2 rotate2d(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float sdBox(vec2 p, vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.5;

  // Faster rotation
  p = rotate2d(p, time * 0.06);

  vec3 col = vec3(0.02, 0.025, 0.015);

  // Golden spiral: r = a * e^(b*theta)
  float r = length(p);
  float theta = atan(p.y, p.x);

  // Logarithmic spiral parameters
  float b = log(PHI) / (PI * 0.5) * (0.5 + uSpiralTightness * 0.5);
  float growth = 0.05 + uGrowthRate * 0.1;

  // Find closest point on spiral
  float spiralDist = 1e5;
  float spiralPhase = 0.0;

  for (int n = -12; n < 12; n++) {
    float th = theta + float(n) * TAU;
    float spiralR = growth * exp(b * th);
    float d = abs(r - spiralR);
    if (d < spiralDist) {
      spiralDist = d;
      spiralPhase = th;
    }
  }

