  spiralCol.r = 0.8 + 0.2 * sin(hue + 0.0);
  spiralCol.g = 0.65 + 0.2 * sin(hue + 0.8);
  spiralCol.b = 0.15 + 0.3 * sin(hue + 3.5);

  spiralCol *= 0.6 + midsVal * 0.4;
  col += spiralCol * (spiralLine + spiralGlow) * 0.8;

