    float rectAccum = 0.0;
    vec2 rp = p;
    float scale = 1.0;

    for (int i = 0; i < 12; i++) {
      float fi = float(i);
      float rectSize = 0.8 / pow(PHI, fi) * (0.5 + uGrowthRate * 0.5);

      // Each rectangle rotated 90 degrees and translated
      float rot = fi * PI * 0.5 + time * 0.02;
      vec2 offset = vec2(cos(rot), sin(rot)) * rectSize * 0.5;

      float d = sdBox(rp - offset, vec2(rectSize, rectSize / PHI));
      float edge = smoothstep(0.008, 0.002, abs(d));

      // Beat triggers new section appearance
      float appear = smoothstep(0.0, 0.5, time * 0.2 - fi * 0.3 + uBeat * 2.0);
      edge *= appear;

      // Spectrum band per rectangle
      float specIdx = mod(fi, 8.0);
      float specVal = 0.0;
      if (specIdx < 1.0) specVal = uSpectrum0;
      else if (specIdx < 2.0) specVal = uSpectrum1;
      else if (specIdx < 3.0) specVal = uSpectrum2;
      else if (specIdx < 4.0) specVal = uSpectrum3;
      else if (specIdx < 5.0) specVal = uSpectrum4;
      else if (specIdx < 6.0) specVal = uSpectrum5;
      else if (specIdx < 7.0) specVal = uSpectrum6;
      else specVal = uSpectrum7;

      vec3 rectCol = vec3(0.7, 0.6, 0.3) * (0.3 + specVal * uSensitivity * 0.5);
      col += rectCol * edge * uRectangleShow * 0.5;
    }
  }

  // Fibonacci number dots along spiral — more dots
  for (int i = 0; i < 13; i++) {
    float fi = float(i);
    float fibAngle = fi * PHI * TAU;
    float fibR = growth * exp(b * fibAngle);
    vec2 fibPos = vec2(cos(fibAngle), sin(fibAngle)) * fibR;

    float d = length(p - fibPos);
    float dotVal = exp(-d * d * 500.0) * (0.6 + uBeat * uSensitivity * 0.8);
    col += vec3(1.0, 0.9, 0.5) * dotVal * 0.6;
  }

