  col += vec3(0.3, 0.25, 0.1) * uKick * uSensitivity * 0.3;

  // BPM-synced rotation pulse
  float bpmPulse = smoothstep(0.8, 1.0, uBpmSin) * 0.15;
  col += vec3(0.2, 0.15, 0.05) * bpmPulse;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

