  return fract(sin(pp * 127.1) * 43758.5453);
}

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 pp) {
  vec2 i = floor(pp);
  vec2 f = fract(pp);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Neon paint color
vec3 neonColor(float idx, float paletteShift) {
  float h = fract(idx * 0.1618 + paletteShift * 0.2);
  vec3 c = 0.5 + 0.5 * cos(6.2832 * (h + vec3(0.0, 0.33, 0.67)));
  return pow(c, vec3(0.6)) * 1.5; // extra bright neon
}

// Drip shape: bulging at top, thin stream, droplet tip
float dripShape(vec2 pp, float streamX, float streamWidth, float dripLen, float time) {
  float dx = abs(pp.x - streamX);
  float dy = pp.y;

  // Main stream narrows as it flows down
  float yNorm = clamp((dy + 1.5) / dripLen, 0.0, 1.0);
  float width = streamWidth * (1.0 - yNorm * 0.6);
  width += sin(dy * 10.0 + time * 2.0) * streamWidth * 0.1; // wobble

  float stream = smoothstep(width, width * 0.5, dx);

  // Drip tip (rounded bulge at bottom)
  float tipY = -1.5 + (1.0 - dripLen) * 0.5;
  float tipDist = length(vec2(pp.x - streamX, pp.y - tipY));
  float tip = smoothstep(width * 1.5, 0.0, tipDist);

  // Pool at bottom
  float poolY = -1.5;
  float poolDist = length(vec2((pp.x - streamX) * 0.5, pp.y - poolY));
  float pool = smoothstep(streamWidth * 3.0, 0.0, poolDist) * smoothstep(poolY - 0.1, poolY, pp.y);

