    // Wobble from audio
    float wobble = sin(p.y * 5.0 + time * 2.0 + fi) * midsVal * 0.02;

    float drip = dripShape(
      vec2(p.x + wobble, p.y),
      streamX,
      streamWidth,
      dripLen,
