      vec2(p.x + wobble, p.y),
      streamX,
      streamWidth * 3.0,
      dripLen,
      time
    ) * 0.15;

    col += dripColor * drip * 0.6;
    col += (dripColor + vec3(0.3)) * core * 0.4;
    col += dripColor * outerGlow;

    // Treble sparkle on paint surface
