      float sparkGrid = 40.0;
      vec2 sparkCell = floor(vec2(p.x + wobble, p.y) * sparkGrid);
      float sparkH = hash21(sparkCell + fi);
      if (sparkH > 0.92) {
        float sparkDist = length(fract(vec2(p.x + wobble, p.y) * sparkGrid) - 0.5);
        float sparkle = smoothstep(0.2, 0.0, sparkDist) * trebleVal * 2.0;
        col += vec3(1.0, 1.0, 0.9) * sparkle;
      }
    }

    // Onset: new splash drops
    if (onsetVal > 0.3) {
      float splashAngle = hash11(seed + time * 0.1) * 6.2832;
      float splashR = onsetVal * 0.3;
      vec2 splashCenter = vec2(streamX, -1.3);
      vec2 splashP = splashCenter + vec2(cos(splashAngle), sin(splashAngle) * 0.3) * splashR;
      float splashDist = length(p - splashP);
