uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLayerCount;
uniform float uKaleidoFolds;
uniform float uChromaticSpread;
uniform float uBloomStrength;

float hash(float n) { return fract(sin(n) * 43758.5453); }
float hash2(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash2(i), hash2(i + vec2(1, 0)), f.x),
             mix(hash2(i + vec2(0, 1)), hash2(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = p * 2.1 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

vec2 kaleidoscope(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

float shockwave(vec2 p, float time, float idx) {
  float age = mod(time * 1.5 - idx * 0.4, 3.0);
  float radius = age * 0.7;
  float ring = abs(length(p) - radius);
  return smoothstep(0.04, 0.0, ring) * exp(-age * 1.5);
}

float particles(vec2 p, float time) {
  float v = 0.0;
  for (float i = 0.0; i < 20.0; i++) {
    float seed = hash(i * 127.31);
    float age = mod(time * 2.0 - seed * 5.0, 2.5);
    float angle = seed * 6.2832 + time * 0.3;
    float dist = age * (0.3 + seed * 0.5);
    vec2 pos = vec2(cos(angle), sin(angle)) * dist;
    pos.y -= age * age * 0.2;
    float d = length(p - pos);
    v += smoothstep(0.015, 0.0, d) * exp(-age * 1.5);
