  float hue = uTime * 0.1 + uChromaDominant / 12.0 + uPalette * 0.3;
  vec3 baseCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.33, 0.67) + kPattern * 0.3));

  vec3 col = baseCol * kPattern * 0.5;

