  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float bpmPulse = uBpmSin * uSensitivity;
  float harmonicVal = uHarmonicity * uSensitivity;

  vec3 col = vec3(0.01, 0.005, 0.02);

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Body silhouette (dark negative space)
  float body = bodySDF(p);
  float bodyMask = smoothstep(0.0, 0.02, body); // 1 outside body, 0 inside

  // Aura glow around body
  float auraDist = max(0.0, body);
  float auraClose = smoothstep(0.2, 0.0, auraDist);
  float auraMid = smoothstep(0.5, 0.0, auraDist);
  vec3 auraColor = astralColor(angle * 0.3 + time * 0.1, uPalette);
  col += auraColor * auraClose * 0.6 * bodyMask;
  col += auraColor * 0.5 * auraMid * 0.2 * bodyMask;

  // Concentric expanding rings
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float ringPhase = fract(time * 0.3 + fi * 0.125);
    float ringR = ringPhase * 2.5;
    float ringWidth = 0.015 + fi * 0.002;
    float ring = smoothstep(ringWidth, 0.0, abs(r - ringR));
    float ringFade = 1.0 - ringPhase;
    vec3 ringColor = astralColor(fi * 0.15 + time * 0.05, uPalette);
    col += ringColor * ring * ringFade * 0.5 * bodyMask;
  }

  // Beat-triggered expansion rings
  if (kickVal > 0.2) {
    float beatRing = smoothstep(0.03, 0.0, abs(r - kickVal * 1.5));
    col += vec3(1.0, 0.9, 0.6) * beatRing * kickVal * bodyMask;
  }

  // Upward-streaming particles (astral lift)
  for (int i = 0; i < 30; i++) {
    float fi = float(i);
    float seed = fi * 5.71;
    float particleX = (hash21(vec2(seed, 1.0)) - 0.5) * 2.0;
    float particleSpeed = 0.5 + hash21(vec2(seed, 2.0)) * 1.0;

    // Particles stream upward
    float particleY = fract(hash21(vec2(seed, 3.0)) + time * particleSpeed * 0.2) * 3.5 - 1.5;

    // Slight inward spiral
    float spiralAngle = particleY * 0.5 + time * 0.3;
    particleX += sin(spiralAngle + fi) * 0.1;

    vec2 particlePos = vec2(particleX, particleY);
    float pd = length(p - particlePos);
    float particleSize = 0.01 + hash21(vec2(seed, 4.0)) * 0.015;
    float particle = smoothstep(particleSize, 0.0, pd);

    // Glow
    float particleGlow = smoothstep(particleSize * 5.0, 0.0, pd) * 0.1;

    vec3 pColor = astralColor(fi * 0.05 + particleY * 0.3, uPalette);
    float yFade = smoothstep(-1.5, 1.0, particleY);
    col += pColor * (particle + particleGlow) * yFade * bodyMask;
  }

  // Crown chakra burst at top
  vec2 crownP = p - vec2(0.0, 0.5);
  float crownR = length(crownP);
  float crownAngle = atan(crownP.y, crownP.x);

  // Radial rays from crown
  float crownRays = pow(cos(crownAngle * 16.0 + time * 3.0) * 0.5 + 0.5, 4.0);
  float crownMask = smoothstep(0.8, 0.0, crownR) * smoothstep(-0.1, 0.3, crownP.y);
  vec3 crownColor = mix(vec3(1.0, 0.85, 0.3), vec3(0.8, 0.6, 1.0), crownR);
  col += crownColor * crownRays * crownMask * 0.4 * (0.5 + trebleVal);

  // Crown core glow
  float crownCore = smoothstep(0.15, 0.0, crownR);
  col += vec3(1.0, 0.95, 0.8) * crownCore * 0.5 * (1.0 + bpmPulse * 0.3);

  // Ethereal background rays
  float bgRays = pow(cos(angle * 6.0 + time * 0.5) * 0.5 + 0.5, 3.0);
  float bgFade = smoothstep(0.5, 2.0, r);
  col += astralColor(angle * 0.2, uPalette) * bgRays * bgFade * 0.08;

  // Body interior: subtle cosmic pattern
  if (bodyMask < 0.5) {
    float cosmicNoise = noiseVal(p * 20.0 + time * 0.5);
    float stars = smoothstep(0.7, 0.9, cosmicNoise);
    col += vec3(0.3, 0.2, 0.5) * stars * 0.3;
    col += vec3(0.05, 0.03, 0.08) * cosmicNoise;
  }

  // Onset: energy burst
  float onsetBurst = smoothstep(0.1, 0.0, abs(r - onsetVal * 2.0)) * onsetVal;
  col += vec3(0.9, 0.8, 1.0) * onsetBurst * 0.5;

  // Harmonic resonance
  col += astralColor(harmonicVal * 2.0, uPalette) * harmonicVal * 0.08;

  // Chaos: aura distortion
  float chaosN = noiseVal(p * 8.0 + time * 2.0);
  col *= 1.0 + (chaosN - 0.5) * uChaos * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

