__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGravityStrength;
uniform float uGridScale;
uniform float uWellCount;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Grid lines
float grid(vec2 p, float scale, float lineWidth) {
  vec2 g = abs(fract(p * scale) - 0.5);
  float line = min(g.x, g.y);
  return smoothstep(lineWidth, lineWidth * 0.3, line);
}

// Apply gravitational lensing from a single well
vec2 gravityWarp(vec2 uv, vec2 wellPos, float mass) {
  vec2 delta = uv - wellPos;
  float dist = length(delta);
  float strength = mass / (dist * dist + 0.05);
  return uv + normalize(delta + 0.0001) * strength * 0.05;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.5;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Gravity well positions: orbiting
  float wellCount = floor(uWellCount);
  vec2 well0 = vec2(cos(time * 0.4), sin(time * 0.4)) * 0.6;
  vec2 well1 = vec2(cos(time * 0.3 + 2.094), sin(time * 0.3 + 2.094)) * 0.5;
  vec2 well2 = vec2(cos(time * 0.5 + 4.189), sin(time * 0.5 + 4.189)) * 0.7;
  vec2 well3 = vec2(cos(time * 0.2 + 1.0), sin(time * 0.6 + 3.0)) * 0.4;

  // Chaos perturbation
  well0 += vec2(sin(time * 1.1), cos(time * 0.9)) * uChaos * 0.15;
  well1 += vec2(cos(time * 0.8), sin(time * 1.2)) * uChaos * 0.12;
  well2 += vec2(sin(time * 1.3), cos(time * 0.7)) * uChaos * 0.1;

  // Gravity mass: modulated by bass and beat
  float baseMass = uGravityStrength * (1.0 + bassVal * 0.8 + beatPulse * 1.2);

  // Apply gravitational lensing iteratively
  vec2 warpedP = p;
  warpedP = gravityWarp(warpedP, well0, baseMass * 1.0);
  warpedP = gravityWarp(warpedP, well1, baseMass * 0.8 * step(1.5, wellCount));
  warpedP = gravityWarp(warpedP, well2, baseMass * 0.6 * step(2.5, wellCount));
  warpedP = gravityWarp(warpedP, well3, baseMass * 0.5 * step(3.5, wellCount));

  // Kick ripple: expanding ring distortion
  float kickPhase = fract(uTime * 0.5);
  float rippleRadius = kickPhase * 2.0;
  float rippleDist = abs(length(p) - rippleRadius);
  float ripple = sin(rippleDist * 30.0 - time * 10.0) * exp(-rippleDist * 5.0) * kickPulse * 0.1;
  warpedP += normalize(p + 0.001) * ripple;

  // === GRID RENDERING ===
  float scale = uGridScale;

  // Primary grid
  float gridBright = grid(warpedP, scale, 0.02 + bassVal * 0.01);

  // Sub-grid (treble detail)
  float subGrid = grid(warpedP, scale * 4.0, 0.01) * trebleVal * 0.4;
  gridBright += subGrid;

  // Grid color: shift from blue to purple to cyan based on mids + palette
  float hue = 0.55 + midsVal * 0.15 + uPalette * 0.08;
  vec3 gridColor = 0.5 + 0.5 * cos(6.283 * (hue + vec3(0.0, 0.33, 0.67)));
  vec3 col = gridColor * gridBright * 0.6;

  // === DISTORTION INTENSITY VISUALIZATION ===
  // Show how warped the grid is: brighter = more distortion
  float distortion = length(warpedP - p);
  vec3 distortionColor = vec3(0.8, 0.4, 1.0) * distortion * 2.0;
  col += distortionColor * 0.3;

  // === EINSTEIN RINGS ===
  // Bright ring around each gravity well
  float ringWidth = 0.02 + midsVal * 0.01;
  float dist0 = length(p - well0);
  float ring0 = exp(-pow((dist0 - 0.15) / ringWidth, 2.0)) * 1.5;
  float dist1 = length(p - well1);
  float ring1 = exp(-pow((dist1 - 0.12) / ringWidth, 2.0)) * 1.2 * step(1.5, wellCount);
  float dist2 = length(p - well2);
  float ring2 = exp(-pow((dist2 - 0.1) / ringWidth, 2.0)) * 0.9 * step(2.5, wellCount);

  vec3 ringColor = vec3(1.0, 0.9, 0.7);
  col += ringColor * (ring0 + ring1 + ring2);

  // === GRAVITATIONAL GLOW ===
  // Soft glow around each well
  float glow0 = 0.03 / (dist0 * dist0 + 0.01);
  float glow1 = 0.025 / (dist1 * dist1 + 0.01) * step(1.5, wellCount);
  float glow2 = 0.02 / (dist2 * dist2 + 0.01) * step(2.5, wellCount);
  vec3 glowColor = vec3(0.3, 0.1, 0.6);
  col += glowColor * (glow0 + glow1 + glow2);

  // === BACKGROUND STARS ===
  float starGrid = 80.0;
  vec2 starCell = floor(warpedP * starGrid);
  float starHash = hash(starCell);
  if (starHash > 0.98) {
    vec2 starOffset = hash(starCell + 100.0) * vec2(1.0) - 0.5;
    float starDist = length(fract(warpedP * starGrid) - 0.5 - starOffset * 0.3);
    float star = exp(-starDist * starDist * 500.0) * 0.4;
    col += vec3(0.8, 0.85, 1.0) * star;
  }

  // Beat pulse
  col += gridColor * 0.05 * beatPulse;

  // Intensity
  col *= uIntensity * 1.5;

  // Vignette
  float vig = 1.0 - length(p * 0.4);
  col *= max(vig, 0.2);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Hash noise for initialization
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Cosine palette
vec3 cosPalette(float t, float paletteShift) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(paletteShift, paletteShift + 0.33, paletteShift + 0.67);
  return a + b * cos(6.2832 * (c * t + d));
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.3;

  // Scale UV by zoom
  vec2 p = (uv - 0.5) * (2.0 + uZoom * 2.0) + 0.5;

  // Pixel size for Laplacian stencil
  float px = 1.0 / 512.0;

  // Gray-Scott parameters — audio-reactive
  // Feed rate: spectral centroid maps f (0.02-0.06) — spots to stripes to waves
  float f = mix(0.02, 0.06, clamp(uSpectralCentroid * uSensitivity * 2.0, 0.0, 1.0));
  // Kill rate: energy maps k (0.05-0.065) — stable to chaotic patterns
  float k = mix(0.05, 0.065, clamp(uEnergy * uSensitivity, 0.0, 1.0));
  // Chaos parameter widens the kill range
  k += uChaos * 0.005;

  // Diffusion rates
  float Du = 0.21;
  float Dv = 0.105;
  float dt = 1.0;

  // Initialize U and V concentrations from spatial hash + audio
  float n = hash(p * 50.0 + time * 0.1);
  float U = 1.0 - 0.5 * smoothstep(0.45, 0.55, n + sin(time + p.x * 10.0) * 0.1);
  float V = 0.25 * smoothstep(0.47, 0.53, n + cos(time * 0.7 + p.y * 10.0) * 0.1);

  // Beat injection: high-V spots on beat
  float beatInject = uBeat * uSensitivity;
  if (beatInject > 0.5) {
    float spotDist = length(fract(p * 3.0 + time * 0.2) - 0.5);
    if (spotDist < 0.15) {
      V += 0.5 * beatInject;
    }
  }

  // Kick injection: localized V spike at center
  float kickVal = uKick * uSensitivity;
  if (kickVal > 0.3) {
    float kickDist = length(p - 0.5);
    V += 0.4 * kickVal * smoothstep(0.3, 0.0, kickDist);
  }

  // 12 Euler integration steps
  for (int step = 0; step < 12; step++) {
    // Laplacian via 5-point stencil (sample neighbors from hash-noise field)
    float stepSeed = float(step) * 0.01 + time * 0.05;
    vec2 pn = p;

    // Neighbor U and V values (approximated from spatial noise field)
    float nR = hash((pn + vec2(px, 0.0)) * 50.0 + stepSeed);
    float nL = hash((pn - vec2(px, 0.0)) * 50.0 + stepSeed);
    float nU = hash((pn + vec2(0.0, px)) * 50.0 + stepSeed);
    float nD = hash((pn - vec2(0.0, px)) * 50.0 + stepSeed);

    float Ur = 1.0 - 0.5 * smoothstep(0.45, 0.55, nR);
    float Ul = 1.0 - 0.5 * smoothstep(0.45, 0.55, nL);
    float Uu = 1.0 - 0.5 * smoothstep(0.45, 0.55, nU);
    float Ud = 1.0 - 0.5 * smoothstep(0.45, 0.55, nD);

    float Vr = 0.25 * smoothstep(0.47, 0.53, nR);
    float Vl = 0.25 * smoothstep(0.47, 0.53, nL);
    float Vu = 0.25 * smoothstep(0.47, 0.53, nU);
    float Vd = 0.25 * smoothstep(0.47, 0.53, nD);

    // Laplacian: sum of neighbors - 4*center
    float lapU = (Ur + Ul + Uu + Ud) - 4.0 * U;
    float lapV = (Vr + Vl + Vu + Vd) - 4.0 * V;

    // Gray-Scott equations
    float UVV = U * V * V;
    float dU = Du * lapU - UVV + f * (1.0 - U);
    float dV = Dv * lapV + UVV - (f + k) * V;

    U += dU * dt;
    V += dV * dt;

    U = clamp(U, 0.0, 1.0);
    V = clamp(V, 0.0, 1.0);
  }

  // Color mapping — map U through cosine palette
  float colorVal = 1.0 - U; // Invert so patterns are bright
  colorVal = colorVal * 0.8 + V * 0.4; // Blend in V for depth
  vec3 color = cosPalette(colorVal * 0.8 + time * 0.02, uPalette * 0.5);

  // Spectral flux adds shimmer
  color += vec3(0.05) * uSpectralFlux * uSensitivity;

  // Onset flash
  color += vec3(0.12, 0.06, 0.02) * uOnset * uSensitivity;

  // Intensity control
  color *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
