__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uHarmonicCount;
uniform float uRingWidth;
uniform float uOscillateAmp;
uniform float uPhaseOffset;

vec3 harmonicPalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.12, 0.28)));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numHarmonics = min(uHarmonicCount, 12.0);
  float dist = length(p);
  float angle = atan(p.y, p.x);

  vec3 color = vec3(0.0);

  // Base frequency for oscillation
  float baseFreq = 1.0;

  for (float i = 1.0; i <= 12.0; i += 1.0) {
    if (i > numHarmonics) break;

    float harmonic = i; // 1st, 2nd, 3rd harmonic etc.
    float frac = (i - 1.0) / numHarmonics;

    // Base ring radius: decreasing with harmonic number (or could be fixed)
    float baseRadius = 0.8 / harmonic * numHarmonics * 0.15;

    // Oscillate ring size at its harmonic frequency
    float oscFreq = baseFreq * harmonic;
    float phase = time * oscFreq + uPhaseOffset * i;

    // Audio-driven modulation: lower harmonics respond to bass, higher to treble
    float audioMod = mix(bassVal, trebleVal, frac) * 0.3 + midsVal * 0.15;

    float oscillation = sin(phase) * uOscillateAmp * 0.3 * (1.0 + audioMod);

    // Lissajous-like: offset center for higher harmonics
    vec2 center = vec2(0.0);
    if (uChaos > 0.01) {
      center = vec2(
        sin(time * 0.3 * harmonic + i * 1.5) * uChaos * 0.1,
        cos(time * 0.25 * harmonic + i * 2.1) * uChaos * 0.08
      );
    }

    float ringRadius = baseRadius + oscillation;
    float ringDist = abs(length(p - center) - abs(ringRadius));

    // Ring glow width
    float width = uRingWidth * 0.02 * (1.0 + 0.5 / harmonic);
    float glow = exp(-ringDist / width);
    float core = exp(-ringDist / (width * 0.3));

    // Onset: ring flash
    float flash = onsetVal * exp(-i * 0.3) * 0.5;

    // Angular modulation: create nodes on the ring — more pronounced
    float angularMod = 1.0 + sin(angle * harmonic * 3.0 + time * harmonic * 0.5) * 0.25;

    float brightness = (core * 1.5 + glow * 0.6) * angularMod + flash;

    // Color: each harmonic has a unique hue — more color spread
    float hue = frac * 0.8 + uPalette * 0.15 + time * 0.03 + sin(i * 0.7) * 0.1;
    vec3 ringColor = harmonicPalette(hue, uPalette * 0.05);

    // Interference brightness modulation
    float interference = sin(dist * 20.0 - time * harmonic * 0.5) * 0.1;
    brightness += interference * glow;

    color += ringColor * max(brightness, 0.0);
  }

  // Interference moire between all rings
  float moire = 0.0;
  for (float i = 1.0; i <= 12.0; i += 1.0) {
    if (i > numHarmonics) break;
    float r = 0.8 / i * numHarmonics * 0.15;
    float osc = sin(time * i + uPhaseOffset * i) * uOscillateAmp * 0.3;
    moire += sin((dist - abs(r + osc)) * 30.0);
  }
  moire /= numHarmonics;
  moire = moire * 0.5 + 0.5;

  vec3 moireColor = harmonicPalette(moire + time * 0.02, uPalette * 0.1 + 0.2);
  color += moireColor * moire * 0.06;

  // Center glow
  float centerGlow = exp(-dist * 8.0);
  vec3 centerColor = harmonicPalette(time * 0.03, uPalette * 0.1);
  color += centerColor * centerGlow * (0.2 + bassVal * 0.3);

  // Treble sparkle
  float sparkle = sin(p.x * 50.0 + time * 5.0) * sin(p.y * 50.0 - time * 4.0);
  sparkle = pow(max(sparkle, 0.0), 20.0);
  color += vec3(sparkle * trebleVal * 0.2);

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.05);

  // Kick punch
  color = mix(color, color * 1.5, kickVal * 0.25);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.15));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

