uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uScanDensity;
uniform float uJitterAmount;
uniform float uProjectionDepth;
uniform float uFlickerRate;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 rot(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// SDF for box
float sdBox(vec2 p, vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// SDF for regular polygon
float sdPoly(vec2 p, float r, float sides) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / sides;
  float d = cos(floor(0.5 + angle / sector) * sector - angle) * length(p);
  return d - r;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity * 1.4;
  float energyVal = uEnergy * uSensitivity;
  float beatVal = uBeat * uSensitivity * 1.3;

  // Hologram jitter
  float jitter = (hash(vec2(floor(time * 30.0), 0.0)) - 0.5) * uJitterAmount * 0.02;
  float jitterY = (hash(vec2(0.0, floor(time * 25.0))) - 0.5) * uJitterAmount * 0.01;
  p += vec2(jitter, jitterY) * (1.0 + bassVal);

