  float shape3 = sdBox(rot(p, mainRot * 0.3), vec2(0.15 + trebleVal * 0.05));

  // Inner diamond
  float shape4 = sdPoly(rot(p, time * 0.8), 0.08 + energyVal * 0.04, 4.0);

  // Wireframe rendering (edge glow only)
  float wire1 = exp(-abs(shape1) * 40.0) * 0.8;
  float wire2 = exp(-abs(shape2) * 50.0) * 0.6;
  float wire3 = exp(-abs(shape3) * 45.0) * 0.5;
  float wire4 = exp(-abs(shape4) * 60.0) * 0.7;

  // Interior fill (very faint)
  float fill1 = smoothstep(0.01, -0.1, shape1) * 0.05;
  float fill2 = smoothstep(0.01, -0.08, shape2) * 0.03;

  float wireTotal = wire1 + wire2 + wire3 + wire4;
  float fillTotal = fill1 + fill2;

  col += holoColor * wireTotal;
  col += holoHighlight * wire4;
  col += holoColor * fillTotal;

  // === DATA READOUT LINES (orbiting text-like lines) ===
  for (float i = 0.0; i < 4.0; i++) {
    float lineAngle = time * 0.3 + i * 1.5708;
    float lineR = 0.55 + i * 0.08;
    vec2 lineCenter = vec2(cos(lineAngle), sin(lineAngle)) * lineR;

    // Small horizontal line segments
    float segAngle = lineAngle + 1.5708;
    vec2 dir = vec2(cos(segAngle), sin(segAngle));
    vec2 d = p - lineCenter;
    float along = dot(d, dir);
    float perp = abs(dot(d, vec2(-dir.y, dir.x)));

    float line = smoothstep(0.003, 0.0, perp) * step(abs(along), 0.06);
    // Dashed
    line *= step(0.5, fract(along * 30.0));
    col += line * holoColor * 0.4;
  }

  // === SCAN LINES ===
  float scanFreq = 200.0 * uScanDensity;
  float scan = sin(vUv.y * scanFreq + time * 5.0) * 0.5 + 0.5;
  col *= 0.7 + scan * 0.3;

  // Moving scan beam
  float scanBeam = fract(time * 0.4);
  float beamDist = abs(vUv.y - scanBeam);
  col += exp(-beamDist * 30.0) * holoColor * 0.2;

  // === DISPLAY REFRESH ON BEAT ===
  float refreshFlash = beatVal * 0.3;
  col += refreshFlash * holoColor;
  // Horizontal glitch line on beat
  float glitchLine = step(abs(vUv.y - fract(time * 7.0)) , 0.005) * beatVal;
  col += glitchLine * vec3(0.5, 1.0, 1.0);

  // === PROJECTION CONE (base glow) ===
  float coneGlow = smoothstep(0.5, 0.0, abs(vUv.x - 0.5)) * smoothstep(0.1, 0.0, vUv.y);
  col += coneGlow * holoColor * 0.1 * uProjectionDepth;

  // === FLICKER ===
  float flicker = 1.0 - step(0.95, hash(vec2(floor(time * 20.0 * uFlickerRate), 0.0))) * 0.3;
  col *= flicker;

  // === CHROMATIC FRINGE (hologram edge color split) ===
  float dist = length(p);
  float fringe = smoothstep(0.5, 0.8, dist) * 0.15;
  col.r += fringe * col.g;
  col.b += fringe * col.g * 0.5;

  // Noise overlay (hologram static)
  float holoNoise = hash(vUv * 500.0 + time * 10.0) * 0.05;
  col += holoNoise * holoColor;

  // Vignette
  vec2 vigUV = vUv * 2.0 - 1.0;
  col *= 1.0 - dot(vigUV, vigUV) * 0.15;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uMetallicBase;
uniform float uPrismStrength;
uniform float uSparkleAmount;

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Spectral color from wavelength (approximate visible spectrum)
vec3 spectralColor(float t) {
  // t in [0,1] maps to violet -> blue -> cyan -> green -> yellow -> red
  vec3 col;
  if (t < 0.2) {
    col = mix(vec3(0.4, 0.0, 0.8), vec3(0.0, 0.0, 1.0), t / 0.2);
  } else if (t < 0.4) {
    col = mix(vec3(0.0, 0.0, 1.0), vec3(0.0, 1.0, 0.5), (t - 0.2) / 0.2);
  } else if (t < 0.6) {
    col = mix(vec3(0.0, 1.0, 0.5), vec3(0.0, 1.0, 0.0), (t - 0.4) / 0.2);
  } else if (t < 0.8) {
    col = mix(vec3(0.0, 1.0, 0.0), vec3(1.0, 1.0, 0.0), (t - 0.6) / 0.2);
  } else {
    col = mix(vec3(1.0, 1.0, 0.0), vec3(1.0, 0.0, 0.0), (t - 0.8) / 0.2);
  }
  return col;
}

void main() {
  float time = uTime * (uSpeed * 3.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity * 1.3;
  float onsetVal = uOnset * uSensitivity * 1.5;
  float kickVal = uKick * uSensitivity * 1.4;
  float energyVal = uEnergy * uSensitivity;

  // Simulated "viewing angle" from UV and time
  float angle = atan(p.y, p.x);
  float dist = length(p);

  // Surface normal perturbation (simulated bumpy foil)
  float bump1 = valueNoise(p * 8.0 + time * 0.3) * 0.5;
  float bump2 = valueNoise(p * 15.0 - time * 0.2) * 0.3;
  float bumpMap = bump1 + bump2;

  // Bass shifts apparent angle
  float angleShift = bassVal * 0.5 + time * 0.15;

  // Onset wave: prismatic shift propagating from center
  float onsetWave = sin(dist * 10.0 - time * 4.0) * onsetVal * 0.3;

  // Holographic grating layers (different orientations)
  float grating1 = sin((p.x * cos(0.0) + p.y * sin(0.0)) * 30.0 + angleShift * 5.0 + bumpMap * 3.0 + onsetWave);
  float grating2 = sin((p.x * cos(1.047) + p.y * sin(1.047)) * 25.0 + angleShift * 4.0 + bumpMap * 2.5);
  float grating3 = sin((p.x * cos(2.094) + p.y * sin(2.094)) * 35.0 + angleShift * 6.0 + bumpMap * 3.5);

  // Map grating values to spectral position
  float spectral1 = fract(grating1 * 0.5 + 0.5 + uPalette * 0.2 + time * 0.02);
  float spectral2 = fract(grating2 * 0.5 + 0.5 + uPalette * 0.2 + time * 0.015);
  float spectral3 = fract(grating3 * 0.5 + 0.5 + uPalette * 0.2 + time * 0.025);

  vec3 prism1 = spectralColor(spectral1);
  vec3 prism2 = spectralColor(spectral2);
  vec3 prism3 = spectralColor(spectral3);

  // Blend prismatic layers
  vec3 prismCol = (prism1 + prism2 * 0.7 + prism3 * 0.5) / 2.2;
  prismCol *= uPrismStrength + 0.3;

  // Metallic base: grey with slight warmth
  float metal = uMetallicBase * 0.6 + 0.2;
  vec3 metalCol = vec3(metal * 0.95, metal * 0.92, metal * 0.88);
  // Add subtle reflection variation
  metalCol *= 0.8 + bumpMap * 0.4;

  // Combine metallic base with prismatic overlay
  vec3 col = metalCol + prismCol;

  // Beat: metallic flash
  float flash = beatPulse * 0.4;
  col += vec3(flash * 0.8, flash * 0.75, flash * 0.7);

  // Kick: bright pulse
  col += vec3(kickVal * 0.2);

  // Sparkle: random bright points
  vec2 sparkleUV = vUv * 200.0;
  float sparkleHash = hash21(floor(sparkleUV));
  vec2 sparkleFrac = fract(sparkleUV) - 0.5;
  float sparkleDist = length(sparkleFrac);
  float sparkleThresh = 0.96 - uSparkleAmount * 0.08 - trebleVal * 0.05;
  float sparkle = smoothstep(0.03, 0.0, sparkleDist) * step(sparkleThresh, sparkleHash);
  float sparkleFlash = sin(time * 12.0 + sparkleHash * 60.0) * 0.5 + 0.5;
  sparkle *= sparkleFlash * (0.5 + trebleVal * 2.0);
  col += vec3(sparkle * 1.5);

  // Second sparkle layer
  vec2 sparkleUV2 = vUv * 350.0;
  float sparkleHash2 = hash21(floor(sparkleUV2));
  vec2 sparkleFrac2 = fract(sparkleUV2) - 0.5;
  float sparkleDist2 = length(sparkleFrac2);
  float sparkle2 = smoothstep(0.02, 0.0, sparkleDist2) * step(0.97, sparkleHash2) * uSparkleAmount;
  sparkle2 *= sin(time * 15.0 + sparkleHash2 * 80.0) * 0.5 + 0.5;
  col += spectralColor(fract(sparkleHash2 + time * 0.1)) * sparkle2 * 2.0;

  // Onset flash
  col += vec3(onsetVal * 0.15);

  // Energy
  col *= 1.0 + energyVal * 0.2;

  // Chaos: add noise variation
  col += (valueNoise(p * 5.0 + time) - 0.5) * uChaos * 0.1;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTileP;
uniform float uTileQ;
uniform float uMobiusSpeed;

// Procedural noise for texturing
float hash2(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

float vnoise(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  float ux = fx * fx * (3.0 - 2.0 * fx);
  float uy = fy * fy * (3.0 - 2.0 * fy);
  float a = hash2(ix, iy);
  float b = hash2(ix + 1.0, iy);
  float c = hash2(ix, iy + 1.0);
  float d = hash2(ix + 1.0, iy + 1.0);
  return mix(mix(a, b, ux), mix(c, d, ux), uy);
}

float fbm2(float x, float y) {
  float v = 0.0;
  v += vnoise(x, y) * 0.5;
  v += vnoise(x * 2.0, y * 2.0) * 0.25;
  v += vnoise(x * 4.0, y * 4.0) * 0.125;
  v += vnoise(x * 8.0, y * 8.0) * 0.0625;
  return v;
}

// Voronoi distance for procedural texture
float voronoi(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  float minDist = 1.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      float cellX = float(i) + hash2(ix + float(i), iy + float(j)) - fx;
      float cellY = float(j) + hash2(ix + float(i) + 7.0, iy + float(j) + 13.0) - fy;
      float d = cellX * cellX + cellY * cellY;
      minDist = min(minDist, d);
    }
  }
  return sqrt(minDist);
}

// HSV to RGB conversion
vec3 hsv2rgb(float h, float s, float v) {
  vec3 c = vec3(h, s, v);
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  vec2 rawP = (vUv - 0.5) * (uZoom * 3.0 + 1.5);
  float time = uTime * (uSpeed * 2.0);

  // Audio-reactive modulators
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float spectralHue = uSpectralCentroid * uSensitivity;
  float energySat = uEnergy * uSensitivity;

  float PI = 3.141592653589793;

  // Distance from center (Poincare disk radius)
  float r = sqrt(rawP.x * rawP.x + rawP.y * rawP.y);

  // Disk boundary mask -- outside is black
  float diskMask = smoothstep(0.98, 0.96, r);

  // --- Mobius transformation --- stronger
  float mobiusAmt = 0.3 + bassVal * 0.25;
  float mobiusAngle = time * uMobiusSpeed;
  float mx = mobiusAmt * cos(mobiusAngle);
  float my = mobiusAmt * sin(mobiusAngle);

  // Mobius transform: w = (z - a) / (1 - conj(a)*z)
  float numX = rawP.x - mx;
  float numY = rawP.y - my;
  float denReal = 1.0 - mx * rawP.x - my * rawP.y;
  float denImag = my * rawP.x - mx * rawP.y;
  float denSq = denReal * denReal + denImag * denImag + 0.0001;
  float px = (numX * denReal + numY * denImag) / denSq;
  float py = (numY * denReal - numX * denImag) / denSq;

  // Hyperbolic distance from origin: d = 2 * atanh(|z|)
  float pR = sqrt(px * px + py * py);
  float safeR = clamp(pR, 0.0, 0.999);
  // atanh(x) approximation
  float atanhVal = safeR + safeR * safeR * safeR / 3.0
    + safeR * safeR * safeR * safeR * safeR / 5.0;
  float hypDist = atanhVal * 2.0;

  // --- Hyperbolic tiling via angular + radial folding ---
  float angle = atan(py, px);

  // Angular tiling: divide into p sectors
  float sectorAngle = PI * 2.0 / uTileP;
  float sectorFrac = fract(angle / sectorAngle + 0.5);
  float mirroredSector = abs(sectorFrac - 0.5) * 2.0;

  // Radial tiling: band by hyperbolic distance
  float tileBandWidth = 0.8 + uTileQ * 0.15;
  float radialBand = fract(hypDist * tileBandWidth);
  float radialMirror = abs(radialBand - 0.5) * 2.0;

  // --- Tile edge detection ---
  float angularEdge = smoothstep(0.03, 0.0, mirroredSector - 0.96);
  float radialEdge = smoothstep(0.03, 0.0, radialBand)
    + smoothstep(0.97, 1.0, radialBand);
  float tileEdge = clamp(angularEdge + radialEdge, 0.0, 1.0);

  // --- Tile interior pattern with multi-frequency procedural textures ---
  float innerPattern = sin(radialMirror * PI * uTileQ) * 0.5 + 0.5;
  float crossHatch = sin(mirroredSector * PI * (uTileP * 0.5)) * 0.5 + 0.5;
  float tilePattern = innerPattern * crossHatch;

  // --- Per-tile color via hue cycling driven by hyperbolic distance ---
  float bandIndex = floor(hypDist * tileBandWidth);
  float sectorIndex = floor(angle / sectorAngle + 0.5);
  float tileHash = fract(sin(bandIndex * 127.1 + sectorIndex * 311.7) * 43758.5453);

  // Base hue: driven by hyperbolic distance for smooth rainbow cycling
  float baseHue = fract(hypDist * 0.15 + tileHash * 0.35 + time * 0.04);
  // Audio-reactive hue shift: spectral centroid drives hue
  float hue = fract(baseHue + spectralHue * 0.3 + uPalette * 0.12 + midsVal * 0.15);

  // Saturation: boosted by energy, always vibrant
  float sat = clamp(0.7 + energySat * 0.3 + tilePattern * 0.15, 0.5, 1.0);

  // Value/brightness from tile interior
  float val = tilePattern * 0.45 + 0.55;

  // Convert HSV to RGB for vibrant multi-hued tiles
  vec3 jewel = hsv2rgb(hue, sat, val);

  // --- Procedural noise texturing within tiles ---
  // Map tile-local coordinates to noise space
  float noiseFreq1 = 6.0 + uChaos * 4.0;
  float noiseFreq2 = 12.0 + uChaos * 8.0;
  float tileNoise1 = fbm2(px * noiseFreq1 + time * 0.15, py * noiseFreq1 - time * 0.1);
  float tileNoise2 = vnoise(px * noiseFreq2 + bandIndex * 3.7, py * noiseFreq2 + sectorIndex * 5.3);

  // Voronoi cell texture for organic depth
  float voroFreq = 4.0 + hypDist * 2.0;
  float voro = voronoi(px * voroFreq + time * 0.1, py * voroFreq);
  float voroEdge = smoothstep(0.02, 0.08, voro);

  // Combine textures for depth/layering
  vec3 texLayer = jewel * (0.7 + tileNoise1 * 0.4) * (0.8 + tileNoise2 * 0.3);
  texLayer *= (0.85 + voroEdge * 0.2);

  // Secondary hue layer at different frequency for iridescence
  float hue2 = fract(hue + 0.35 + tileNoise1 * 0.15 + hypDist * 0.08);
  vec3 iridescent = hsv2rgb(hue2, sat * 0.8, 0.3);
  texLayer += iridescent * (1.0 - voroEdge) * 0.25;

  // Edge glow: iridescent shifting color instead of plain white-gold
  float edgeHue = fract(hue + 0.5 + time * 0.06);
  vec3 edgeColor = hsv2rgb(edgeHue, 0.3, 1.0);

  // Treble shimmer at boundary
  float boundaryShimmer = smoothstep(0.85, 0.96, r)
    * (trebleVal * 1.5 + 0.3)
    * (sin(angle * uTileP * 3.0 + time * 2.0) * 0.5 + 0.5);

  // Beat ripple in hyperbolic space — faster
  float ripplePhase = hypDist * 6.0 - time * 3.0;
  float ripple = sin(ripplePhase) * 0.5 + 0.5;
  float beatRipple = ripple * beatPulse * 0.4;

  // --- Combine ---
  vec3 withEdge = mix(texLayer, edgeColor, tileEdge);

  // Intensity, chaos modulation, and disk mask
  float energyBright = energySat * 0.25 + 0.75;
  float brightScale = uIntensity * energyBright * diskMask;

  // Add shimmer and beat effects with color variation
  float shimmerHue = fract(angle * 0.5 / PI + time * 0.03);
  vec3 shimmerCol = hsv2rgb(shimmerHue, 0.6, 1.0);
  vec3 finalCol = withEdge * brightScale;
  finalCol += shimmerCol * boundaryShimmer * 0.35;
  finalCol += hsv2rgb(fract(hue + 0.2), 0.8, beatRipple);

  // Beat pulse brightness boost
  float beatBright = beatPulse * 0.12;
  finalCol += vec3(beatBright);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.r, 0.0, 1.0),
    clamp(finalCol.g, 0.0, 1.0),
    clamp(finalCol.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTileOrder;
uniform float uDiskCurvature;
uniform float uRotationSpeed;

#define PI 3.14159265
#define TAU 6.28318530

vec3 hyperPalette(float t, float offset) {
  return vec3(
    0.5 + 0.5 * cos(TAU * (t + 0.0 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.33 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.67 + offset * 0.25))
  );
}

// Mobius transformation for hyperbolic translation
vec2 mobiusTransform(vec2 z, vec2 w) {
  // (z - w) / (1 - conj(w) * z)
  float denom_r = 1.0 - w.x * z.x - w.y * z.y;
  float denom_i = w.y * z.x - w.x * z.y;
  float denom2 = denom_r * denom_r + denom_i * denom_i;
  if (denom2 < 0.0001) return z;
  float num_r = z.x - w.x;
  float num_i = z.y - w.y;
  return vec2(
    (num_r * denom_r + num_i * denom_i) / denom2,
    (num_i * denom_r - num_r * denom_i) / denom2
  );
}

// Rotation in 2D
vec2 rot2d(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Hyperbolic distance from origin
float hypDist(vec2 p) {
  float r = length(p);
  r = min(r, 0.999);
  return log((1.0 + r) / (1.0 - r));
}

// Tile the hyperbolic plane using reflections
vec3 hyperbolicTile(vec2 p, float order, float time, float bassVal, float midsVal) {
  float n = floor(4.0 + order * 6.0); // polygon sides: 4-10
  float k = floor(3.0 + order * 4.0); // tiles meeting at vertex: 3-7

  float sectorAngle = PI / n;
  float totalIter = 0.0;
  float colorAccum = 0.0;
  float parity = 1.0;

  // Iterative reflection to find tile position
  for (int i = 0; i < 20; i++) {
    float angle = atan(p.y, p.x);

    // Rotate into fundamental domain
    float sector = floor(angle / (2.0 * sectorAngle));
    p = rot2d(p, -sector * 2.0 * sectorAngle);

    // Reflect if in wrong half
    float a2 = atan(p.y, p.x);
    if (a2 < 0.0) {
      p.y = -p.y;
      parity *= -1.0;
    }
    if (a2 > sectorAngle) {
      // Reflect across the geodesic
      float ca = cos(2.0 * sectorAngle);
      float sa = sin(2.0 * sectorAngle);
      float dot2 = 2.0 * (p.x * ca + p.y * sa);
      p = vec2(dot2 * ca - p.x, dot2 * sa - p.y);
      parity *= -1.0;
    }

    // Hyperbolic reflection (inversion in a circle)
    float reflR = cos(PI / k) / cos(PI / n);
    reflR *= (1.0 + bassVal * 0.1);
    vec2 center = vec2(reflR, 0.0);
    float invRadius = sqrt(abs(reflR * reflR - 1.0));

    vec2 diff = p - center;
    float d2 = dot(diff, diff);
    if (d2 < invRadius * invRadius) {
      p = center + diff * (invRadius * invRadius / d2);
      parity *= -1.0;
      totalIter += 1.0;
    } else {
      break;
    }
    colorAccum += length(p) * 0.1;
  }

  // Distance to tile edge
  float hd = hypDist(p);
  float tileEdge = fract(hd * 2.0 + time * 0.1);

  // Color based on iteration depth and parity — more variation
  float colorT = colorAccum * 0.4 + totalIter * 0.18 + midsVal * 0.6 + time * 0.06;
  vec3 col = hyperPalette(colorT, 0.0);

  // Checkerboard parity coloring
  if (parity < 0.0) {
    col = col * 0.6 + 0.1;
  }

  // Tile edge glow
  float edgeDist = min(tileEdge, 1.0 - tileEdge);
  float edgeGlow = smoothstep(0.05, 0.0, edgeDist);

  return vec3(col + edgeGlow * 0.3);
}

void main() {
  float time = uTime * (uSpeed * 1.5);
  vec2 p = (vUv - 0.5) * 2.0 * (uZoom * 2.0 + 0.5);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Poincare disk boundary
  float diskR = length(p);

  // Rotation animation — faster
  float rotAngle = time * uRotationSpeed * 1.5 + kickVal * 0.8;
  p = rot2d(p, rotAngle);

  // Curvature warp
  float curvature = 0.5 + uDiskCurvature * 0.5;
  p *= curvature;

  // Chaos adds wobble
  p += vec2(sin(time * 0.3 + p.y * 2.0), cos(time * 0.4 + p.x * 2.0)) * uChaos * 0.05;

  vec3 color = vec3(0.0);

  if (diskR < 0.98) {
    // Inside the Poincare disk
    color = hyperbolicTile(p, uTileOrder, time, bassVal, midsVal);

    // Treble edge enhancement
    float edgeBright = trebleVal * 0.3;
    color += edgeBright;

    // Palette shift
    float lum = dot(color, vec3(0.299, 0.587, 0.114));
    vec3 tinted = hyperPalette(lum + uPalette * 0.25 + time * 0.02, uPalette);
    color = mix(color, tinted, 0.3);
  }

  // Disk boundary glow
  float boundaryGlow = smoothstep(0.02, 0.0, abs(diskR - 0.98));
  boundaryGlow *= 1.0 + beatPulse * 2.0;
  vec3 boundaryColor = hyperPalette(time * 0.1, uPalette + 0.3);
  color += boundaryGlow * boundaryColor;

  // Fade outside disk
  color *= smoothstep(1.05, 0.95, diskR);

  // Beat pulse brightness
  color += beatPulse * 0.1;

  // Onset color rotate
  color = mix(color, color.gbr, onsetVal * 0.2);

  // Intensity
  color *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSpiralArms;
uniform float uRotationLock;
uniform float uDepthPerspective;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.5) * 0.05, cos(p.x * 3.5 + time * 0.4) * 0.05);

  // Audio-reactive modulators — 2x
  float bassVal = bass() * uSensitivity * 1.6;
  float midsVal = mids() * uSensitivity * 1.4;
  float trebleVal = treble() * uSensitivity * 1.6;
  float kickVal = uKick * uSensitivity * 2.0;
  float energyVal = uEnergy * uSensitivity * 1.4;
  float bpmSinVal = uBpmSin;
  float bpmVal = max(uBpm, 60.0);

  // Center drift with mids
  vec2 center = vec2(
    sin(time * 0.3) * midsVal * 0.15,
    cos(time * 0.4) * midsVal * 0.15
  );
  p -= center;

  float r = length(p);
  float a = atan(p.y, p.x);

  // BPM-locked rotation
  float bpmRotation = time * bpmVal / 60.0 * 6.2832;
  float freeRotation = time * 2.0;
  float rotation = mix(freeRotation, bpmRotation, uRotationLock);

  // Number of spiral arms
  float arms = floor(2.0 + uSpiralArms * 6.0);

  // Bass: spiral width pulse
  float bassPulse = 1.0 + bassVal * 0.3;

  // Spiral pattern (logarithmic spiral)
  float spiralTightness = 3.0 + uDepthPerspective * 5.0;
  float spiralAngle = a * arms - log(r + 0.001) * spiralTightness + rotation;
  float spiral = sin(spiralAngle) * 0.5 + 0.5;

  // Sharpen spiral edges
  spiral = smoothstep(0.3, 0.7, spiral);

  // Depth: concentric rings for 3D illusion
  float depth = sin(r * 15.0 * uDepthPerspective - time * 5.0);
  depth = depth * 0.5 + 0.5;

  // Opponent colors: red/cyan alternating
  vec3 color1 = vec3(0.9, 0.15, 0.1); // Red
  vec3 color2 = vec3(0.1, 0.8, 0.85); // Cyan

  // Palette shift — faster cycling
  float paletteRot = uPalette * 0.5 + time * 0.06 + sin(uTime * 0.3) * 0.2;
  color1 = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + paletteRot));
  color2 = 0.5 + 0.5 * cos(6.2832 * (vec3(0.5, 0.83, 0.17) + paletteRot));

  // Apply spiral coloring
  vec3 col = mix(color1, color2, spiral);

  // Depth shading
  col *= 0.6 + depth * 0.4 * uDepthPerspective;

  // Radial brightness (brighter at center for tunnel effect)
  float radialBright = exp(-r * 0.5) * 0.3 + 0.7;
  col *= radialBright;

  // Second spiral layer (offset) for complexity
  float spiral2Angle = a * (arms + 1.0) - log(r + 0.001) * spiralTightness * 0.8 - rotation * 0.7;
  float spiral2 = sin(spiral2Angle) * 0.5 + 0.5;
  spiral2 = pow(spiral2, 3.0);
  vec3 accent = mix(color2, color1, spiral2) * 0.2;
  col += accent * (0.5 + trebleVal * 0.5);

  // Bass width pulsing
  col *= bassPulse;

  // Center vortex glow
  float vortexGlow = exp(-r * r * 4.0);
  vec3 glowColor = mix(color1, color2, sin(time * 2.0) * 0.5 + 0.5);
  col += vortexGlow * glowColor * 0.3;

  // Kick: bright center flash
  col += kickVal * 0.4 * exp(-r * 3.0) * vec3(1.0, 0.95, 0.9);

  // BPM sync brightness
  col *= 0.85 + (bpmSinVal * 0.5 + 0.5) * 0.2;

  // Energy overall glow
  col *= 0.8 + energyVal * 0.3;

  // Chaos: spiral wobble
  float wobble = noise(vec2(a * 3.0, time * 2.0)) * uChaos * 0.15;
  col *= 1.0 + wobble;

  // Mids: warmth
  col += midsVal * 0.04 * vec3(0.5, 0.3, 0.4);

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uShapeSelect;
uniform float uWireThickness;
uniform float uRotationAxis;

#define PI 3.14159265
#define TAU 6.28318530

vec3 impossiblePalette(float t, float offset) {
  return vec3(
    0.5 + 0.5 * cos(TAU * (t + 0.0 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.33 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.67 + offset * 0.25))
  );
}

// Rotation matrices
vec3 rotX(vec3 p, float a) {
  float c = cos(a); float s = sin(a);
  return vec3(p.x, p.y * c - p.z * s, p.y * s + p.z * c);
}
vec3 rotY(vec3 p, float a) {
  float c = cos(a); float s = sin(a);
  return vec3(p.x * c + p.z * s, p.y, -p.x * s + p.z * c);
}
vec3 rotZ(vec3 p, float a) {
  float c = cos(a); float s = sin(a);
  return vec3(p.x * c - p.y * s, p.x * s + p.y * c, p.z);
}

// Box SDF
float boxSDF(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// Beam SDF (box along an axis between two points)
float beamSDF(vec3 p, vec3 a, vec3 b, float thickness) {
  vec3 ab = b - a;
  float t = clamp(dot(p - a, ab) / dot(ab, ab), 0.0, 1.0);
  vec3 closest = a + ab * t;
  vec3 d = p - closest;
  return length(d) - thickness;
}

// Penrose triangle: 3 beams with impossible overlap
float penroseTriangleSDF(vec3 p, float thick, float bassVal) {
  float s = 1.1 + bassVal * 0.15;

  // Triangle vertices
  vec3 v0 = vec3(0.0, s, 0.0);
  vec3 v1 = vec3(-s * 0.866, -s * 0.5, 0.0);
  vec3 v2 = vec3(s * 0.866, -s * 0.5, 0.0);

  // The "impossible" part: each beam connects at a Z offset
  float zOff = thick * 2.5;
  vec3 a0 = v0 + vec3(0.0, 0.0, -zOff);
  vec3 b0 = v1 + vec3(0.0, 0.0, 0.0);
  vec3 a1 = v1 + vec3(0.0, 0.0, 0.0);
  vec3 b1 = v2 + vec3(0.0, 0.0, zOff);
  vec3 a2 = v2 + vec3(0.0, 0.0, zOff);
  vec3 b2 = v0 + vec3(0.0, 0.0, -zOff);

  float d0 = beamSDF(p, a0, b0, thick);
  float d1 = beamSDF(p, a1, b1, thick);
  float d2 = beamSDF(p, a2, b2, thick);

  return min(min(d0, d1), d2);
}

// Impossible cube: bars overlap at different depths
float impossibleCubeSDF(vec3 p, float thick, float bassVal) {
  float s = 0.8 + bassVal * 0.12;
  float d = 1e10;

  // 12 edges of a cube, but with Z-depth tricks
  // Front face
  d = min(d, beamSDF(p, vec3(-s, -s, -s), vec3(s, -s, -s), thick));
  d = min(d, beamSDF(p, vec3(s, -s, -s), vec3(s, s, -s), thick));
  d = min(d, beamSDF(p, vec3(s, s, -s), vec3(-s, s, -s), thick));
  d = min(d, beamSDF(p, vec3(-s, s, -s), vec3(-s, -s, -s), thick));
  // Back face
  d = min(d, beamSDF(p, vec3(-s, -s, s), vec3(s, -s, s), thick));
  d = min(d, beamSDF(p, vec3(s, -s, s), vec3(s, s, s), thick));
  d = min(d, beamSDF(p, vec3(s, s, s), vec3(-s, s, s), thick));
  d = min(d, beamSDF(p, vec3(-s, s, s), vec3(-s, -s, s), thick));
  // Connecting edges (the "impossible" ones — two cross each other)
  d = min(d, beamSDF(p, vec3(-s, -s, -s), vec3(-s, -s, s), thick));
  d = min(d, beamSDF(p, vec3(s, -s, -s), vec3(s, -s, s), thick));
  // These two get the impossible treatment
  d = min(d, beamSDF(p, vec3(s, s, -s), vec3(s * 0.3, s, s), thick));
  d = min(d, beamSDF(p, vec3(-s, s, -s * 0.3), vec3(-s, s, s), thick));

  return d;
}

// Scene SDF
vec2 sceneSDF(vec3 p, float shapeBlend, float thick, float bassVal) {
  float d1 = penroseTriangleSDF(p, thick, bassVal);
  float d2 = impossibleCubeSDF(p, thick, bassVal);

  // Blend between shapes
  float d = mix(d1, d2, smoothstep(0.3, 0.7, shapeBlend));
  return vec2(d, shapeBlend);
}

void main() {
  float time = uTime * (uSpeed * 1.0);
  vec2 uv = (vUv - 0.5) * 2.0 * (uZoom * 1.0 + 0.8);
  uv = psychedelicUV(uv); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float thick = 0.03 + uWireThickness * 0.1;

  // Camera — closer for screen-filling geometry
  float camDist = 1.8;
  vec3 ro = vec3(0.0, 0.0, camDist);
  vec3 rd = normalize(vec3(uv, -1.2));

  // Rotation — faster
  float rotSpeed = 0.5 + kickVal * 0.8;
  float axisBlend = uRotationAxis;

  // Mix rotation axes
  float rx = time * rotSpeed * (1.0 - axisBlend) * 0.7;
  float ry = time * rotSpeed * 0.5;
  float rz = time * rotSpeed * axisBlend * 0.7;

  // Apply rotation to ray (rotate scene)
  ro = rotX(ro, rx); rd = rotX(rd, rx);
  ro = rotY(ro, ry); rd = rotY(rd, ry);
  ro = rotZ(ro, rz); rd = rotZ(rd, rz);

  // Chaos wobble
  ro += vec3(sin(time * 0.7), cos(time * 0.5), sin(time * 0.3)) * uChaos * 0.2;

  // Shape morph: beat triggers transition
  float shapeSel = uShapeSelect + beatPulse * 0.2;

  // Raymarch
  float t = 0.0;
  float minDist = 1e10;
  vec3 hitPos = ro;

  for (int i = 0; i < 80; i++) {
    hitPos = ro + rd * t;
    vec2 result = sceneSDF(hitPos, shapeSel, thick, bassVal);
    float d = result.x;
    minDist = min(minDist, d);
    if (d < 0.001) break;
    if (t > 10.0) break;
    t += d * 0.8;
  }

  // Normal estimation
  float eps = 0.001;
  float nx = sceneSDF(hitPos + vec3(eps, 0.0, 0.0), shapeSel, thick, bassVal).x
           - sceneSDF(hitPos - vec3(eps, 0.0, 0.0), shapeSel, thick, bassVal).x;
  float ny = sceneSDF(hitPos + vec3(0.0, eps, 0.0), shapeSel, thick, bassVal).x
           - sceneSDF(hitPos - vec3(0.0, eps, 0.0), shapeSel, thick, bassVal).x;
  float nz = sceneSDF(hitPos + vec3(0.0, 0.0, eps), shapeSel, thick, bassVal).x
           - sceneSDF(hitPos - vec3(0.0, 0.0, eps), shapeSel, thick, bassVal).x;
  vec3 normal = normalize(vec3(nx, ny, nz));

  // Lighting
  vec3 lightDir = normalize(vec3(0.5, 0.8, 0.6));
  float diff = max(dot(normal, lightDir), 0.0);
  float spec = pow(max(dot(reflect(-lightDir, normal), -rd), 0.0), 32.0);

  // Color
  float colorT = dot(hitPos, vec3(0.3)) + midsVal * 0.4 + time * 0.05;
  vec3 baseColor = impossiblePalette(colorT, uPalette);

  vec3 color = vec3(0.0);
  if (t < 10.0) {
    // Hit
    color = baseColor * (diff * 0.6 + 0.3) + spec * 0.5 * vec3(1.0, 0.95, 0.9);
    color += trebleVal * spec * 0.3;
  }

  // Edge glow (near-miss glow) — stronger
  float glow = 0.015 / (minDist + 0.004);
  vec3 glowColor = impossiblePalette(colorT + 0.3, uPalette + 0.2);
  color += glow * glowColor * 0.2;

  // Beat flash
  color += beatPulse * 0.12;

  // Onset color shift
  color = mix(color, color.brg, onsetVal * 0.2);

  // Background gradient — fills screen with subtle color
  float bgGrad = length(uv) * 0.1;
  vec3 bg = impossiblePalette(time * 0.02 + 0.5, uPalette) * 0.08;
  color = max(color, bg * (1.0 - bgGrad * 0.5));

  // Intensity
  color *= uIntensity * 1.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uHallwayWidth;
uniform float uRepeatDistance;
uniform float uFlickerRate;

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float hash2d(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Box SDF
float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// Hallway SDF: repeating corridor with doors and side passages
float hallwaySDF(vec3 p, float time, float bassVal, float beatPulse) {
  // Width breathing
  float breathe = sin(time * 0.3) * 0.15 * bassVal + beatPulse * 0.1;
  float w = uHallwayWidth + breathe;
  float h = w * 0.7; // height proportional to width

  // Main corridor: infinite box tunnel along Z
  float corridor = -sdBox(p, vec3(w, h, 1e5));

  // Repeating segment along Z
  float repZ = mod(p.z + uRepeatDistance * 0.5, uRepeatDistance) - uRepeatDistance * 0.5;

  // Door frames: recessed alcoves on walls
  float doorWidth = w * 0.4;
  float doorHeight = h * 0.85;
  float doorDepth = 0.3;

  // Left door
  vec3 doorPosL = vec3(p.x - w + doorDepth * 0.5, p.y, repZ);
  float doorL = sdBox(doorPosL, vec3(doorDepth, doorHeight, doorWidth * 0.5));

  // Right door
  vec3 doorPosR = vec3(p.x + w - doorDepth * 0.5, p.y, repZ);
  float doorR = sdBox(doorPosR, vec3(doorDepth, doorHeight, doorWidth * 0.5));

  // Side passages (branching halls) -- deeper holes
  float passageDepth = 2.0 + sin(time * 0.2) * 0.5;
  vec3 passL = vec3(p.x - w - passageDepth * 0.5 + 0.1, p.y, repZ);
  float sideL = sdBox(passL, vec3(passageDepth, h * 0.6, doorWidth * 0.4));

  vec3 passR = vec3(p.x + w + passageDepth * 0.5 - 0.1, p.y, repZ);
  float sideR = sdBox(passR, vec3(passageDepth, h * 0.6, doorWidth * 0.4));

  // Ceiling light fixtures
  float lightW = 0.08;
  float lightFixture = sdBox(vec3(p.x, p.y - h + 0.05, repZ), vec3(w * 0.6, lightW, 0.3));

  // Floor tiles: subtle raised grid
  float tileSize = 0.5;
  vec2 tileP = mod(vec2(p.x, p.z), tileSize) - tileSize * 0.5;
  float tile = sdBox(vec3(tileP.x, p.y + h - 0.02, tileP.y), vec3(tileSize * 0.48, 0.02, tileSize * 0.48));

  // Combine: corridor minus doors and passages
  float d = corridor;
  d = max(d, -doorL);
  d = max(d, -doorR);
  d = max(d, -sideL);
  d = max(d, -sideR);
  d = min(d, lightFixture);
  d = min(d, tile);

  return d;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.6;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Camera: fly forward through the hallway
  float camZ = time * 4.0;
  float sway = sin(time * 0.4) * 0.2 * uChaos;
  vec3 ro = vec3(sway, -0.1 + sin(time * 0.3) * 0.1, camZ);

  // Look direction: slight sway
  float fov = 0.8 + uZoom * 0.6;
  vec3 rd = normalize(vec3(p.x * fov + sin(time * 0.15) * 0.03, p.y * fov + 0.02, 1.0));

  // Raymarch
  float t = 0.0;
  float minDist = 100.0;
  bool hit = false;

  for (int i = 0; i < 15; i++) {
    vec3 pos = ro + rd * t;
    float d = hallwaySDF(pos, time, bassVal, beatPulse);
    d = max(d, 0.001);
    minDist = min(minDist, d);
    if (d < 0.005) { hit = true; break; }
    t += d * 0.7;
    if (t > 80.0) break;
  }
  for (int i = 0; i < 15; i++) {
    vec3 pos = ro + rd * t;
    float d = hallwaySDF(pos, time, bassVal, beatPulse);
    d = max(d, 0.001);
    minDist = min(minDist, d);
    if (d < 0.005) { hit = true; break; }
    t += d * 0.7;
    if (t > 80.0) break;
  }
  for (int i = 0; i < 15; i++) {
    vec3 pos = ro + rd * t;
    float d = hallwaySDF(pos, time, bassVal, beatPulse);
    d = max(d, 0.001);
    minDist = min(minDist, d);
    if (d < 0.005) { hit = true; break; }
    t += d * 0.7;
    if (t > 80.0) break;
  }

  vec3 col = vec3(0.0);

  if (hit) {
    vec3 hitPos = ro + rd * t;

    // Normal
    float eps = 0.01;
    float nx = hallwaySDF(hitPos + vec3(eps, 0.0, 0.0), time, bassVal, beatPulse) -
               hallwaySDF(hitPos - vec3(eps, 0.0, 0.0), time, bassVal, beatPulse);
    float ny = hallwaySDF(hitPos + vec3(0.0, eps, 0.0), time, bassVal, beatPulse) -
               hallwaySDF(hitPos - vec3(0.0, eps, 0.0), time, bassVal, beatPulse);
    float nz = hallwaySDF(hitPos + vec3(0.0, 0.0, eps), time, bassVal, beatPulse) -
               hallwaySDF(hitPos - vec3(0.0, 0.0, eps), time, bassVal, beatPulse);
    vec3 n = normalize(vec3(nx, ny, nz));

    // Surface color: institutional off-white walls
    vec3 wallColor = vec3(0.35, 0.33, 0.3) + uPalette * 0.02;

    // Floor: slightly different tone
    float isFloor = step(0.5, n.y);
    wallColor = mix(wallColor, vec3(0.25, 0.22, 0.2), isFloor);

    // Ceiling
    float isCeiling = step(0.5, -n.y);
    wallColor = mix(wallColor, vec3(0.4, 0.38, 0.35), isCeiling);

    // Fluorescent lighting from ceiling fixtures
    float repZ = mod(hitPos.z + uRepeatDistance * 0.5, uRepeatDistance) - uRepeatDistance * 0.5;
    float lightDist = length(vec2(hitPos.x, repZ));
    float lightAtten = 1.0 / (lightDist * lightDist * 0.5 + 0.3);

    // Flicker: treble-driven
    float flicker = 1.0;
    float flickerSeed = floor(hitPos.z / uRepeatDistance);
    float flickerPhase = hash(flickerSeed) * 100.0 + time * uFlickerRate * 10.0;
    float flickerNoise = hash(floor(flickerPhase));
    flicker = 0.7 + 0.3 * step(0.15, flickerNoise);
    flicker *= 1.0 - trebleVal * 0.3 * step(0.7, hash(floor(flickerPhase * 3.0)));

    // Fluorescent color: slightly green-yellow tint
    vec3 lightColor = vec3(0.85, 0.9, 0.7) + midsVal * vec3(-0.1, 0.05, 0.1);
    float lighting = lightAtten * flicker;

    col = wallColor * lightColor * lighting;

    // Edge darkening in corners
    float corner = smoothstep(0.0, 0.5, abs(n.x) * abs(hitPos.y));
