float frameSDF(vec2 pp, vec2 sz, float thick) {
  vec2 d = abs(pp) - sz;
  float outer = max(d.x, d.y);
  vec2 dInner = abs(pp) - (sz - vec2(thick));
  float inner = max(dInner.x, dInner.y);
  return max(outer, -inner);
}

