float cornerOrnament(vec2 pp, float sz) {
  vec2 ap = abs(pp) - vec2(sz);
  float d = length(ap) - 0.03;
  float diamond = abs(ap.x) + abs(ap.y) - 0.05;
  return min(d, diamond);
}

