vec3 frameColor(float depth, float time, float paletteShift) {
  float h = fract(depth * 0.0618 + time * 0.05 + paletteShift * 0.2);
  vec3 c = 0.5 + 0.5 * cos(6.2832 * (h + vec3(0.0, 0.33, 0.67)));
