  return fract(sin(pp * 127.1) * 43758.5453);
}

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

// Neuron positions (precomputed from hash)
vec2 neuronPos(int idx, float time, float chaos) {
  float fi = float(idx);
  float angle = fi * 2.399 + time * 0.05; // golden angle spread
  float radius = 0.3 + hash11(fi * 7.31) * 0.9;
