  base.y += cos(time * 0.15 + fi * 1.7) * 0.05 * (1.0 + chaos);
  return base;
}

// Signal pulse along a connection
float signalPulse(vec2 pp, vec2 nodeA, vec2 nodeB, float time, float phase) {
  vec2 ab = nodeB - nodeA;
  float abLen = length(ab);
  if (abLen < 0.01) return 0.0;
  vec2 abDir = ab / abLen;
  vec2 ap = pp - nodeA;
  float along = dot(ap, abDir);
  float perpDist = abs(dot(ap, vec2(-abDir.y, abDir.x)));

  // Pulse position along the connection
  float pulsePos = fract(time * 0.8 + phase) * abLen;
  float pulseDist = abs(along - pulsePos);
  float pulse = smoothstep(0.06, 0.0, pulseDist) * smoothstep(abLen, 0.0, along) * step(0.0, along);

  // Connection line
  float lineMask = step(0.0, along) * step(along, abLen);
  float lineWidth = 0.004;
  float connLine = smoothstep(lineWidth * 2.0, 0.0, perpDist) * lineMask;

  return max(connLine * 0.15, pulse);
