    // Node size pulses with firing
    float nodeSize = 0.025 + firing * 0.02 + bpmPulse * 0.005;

    // Bright core
    float core = smoothstep(nodeSize, 0.0, nd);
    // Glow halo
    float glow = smoothstep(nodeSize * 4.0, 0.0, nd) * 0.2;
    // Outer dendrite halo
    float dendrite = smoothstep(nodeSize * 8.0, nodeSize * 2.0, nd) * 0.05;

    vec3 nodeColor = neuralColor(fi * 0.04, uPalette);
    float brightness = 0.3 + firing * 0.7;

    col += nodeColor * core * brightness;
    col += nodeColor * glow * brightness;
    col += nodeColor * dendrite * (0.5 + trebleVal * 0.5);

    // Firing flash: bright white burst
    if (firing > 0.5) {
      float flash = smoothstep(nodeSize * 2.0, 0.0, nd) * (firing - 0.5) * 2.0;
      col += vec3(1.0, 0.95, 0.9) * flash * 0.4;
    }
  }

  // Background: subtle neural web texture
  float bgPattern = hash21(floor(p * 20.0));
  float bgLine = smoothstep(0.02, 0.0, abs(fract(p.x * 5.0 + p.y * 3.0 + time * 0.1) - 0.5));
  col += vec3(0.02, 0.03, 0.06) * bgLine * bgPattern;

  // Kick: global flash
  col += vec3(0.15, 0.1, 0.2) * kickVal * 0.4;

  // Onset: ripple wave
  float onsetWave = smoothstep(0.02, 0.0, abs(length(p) - onsetVal * 2.0));
  col += vec3(0.4, 0.6, 1.0) * onsetWave * onsetVal * 0.5;

  // Spectral flux: synaptic shimmer
  col *= 1.0 + fluxVal * 0.15;

  // Mids: network breathing
  col *= 1.0 + midsVal * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

