uniform float uChaos;

uniform float uFilmThickness;
uniform float uRefractionIndex;
uniform float uSurfaceWarp;

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio influences
  float bassInfluence = bass() * uSensitivity;
  float midsInfluence = mids() * uSensitivity;
  float trebleInfluence = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  // Pseudo-viewing angle from distance to center
  float dist = pow(p.x * p.x + p.y * p.y, 0.5);
  float theta = smoothstep(0.0, 1.2, dist);
  float cosTheta = cos(theta * 1.2);

  // Domain warp: mids-driven surface distortion
  float warpX = sin(p.y * 5.0 + time * 0.7) * midsInfluence * uSurfaceWarp * 0.15;
  float warpY = cos(p.x * 5.0 - time * 0.6) * midsInfluence * uSurfaceWarp * 0.15;
  float wp_x = p.x + warpX;
  float wp_y = p.y + warpY;

  // Surface noise: layered sine waves for film thickness variation
  float noise1 = sin(wp_x * 4.0 + time * 0.3) * cos(wp_y * 3.5 - time * 0.25);
  float noise2 = sin(wp_x * 7.0 - time * 0.5 + wp_y * 6.0) * 0.5;
  float noise3 = sin(wp_x * 12.0 + wp_y * 11.0 + time * 0.8) * 0.25;
  float noise4 = sin(wp_x * 3.0 - wp_y * 5.0 - time * 0.15) * 0.7;
  float surfaceNoise = (noise1 + noise2 + noise3 + noise4) * 0.3;

  // Beat ripple: expanding ring from center on beat
  float beatRipple = sin(dist * 20.0 - time * 3.0) * beatPulse * 0.4;

  // Treble shimmer: high-frequency perturbation
  float shimmer = sin(wp_x * 25.0 + time * 4.0) * cos(wp_y * 22.0 - time * 3.5) * trebleInfluence * 0.15;

  // Total film thickness
  float thickness = uFilmThickness * 2.0
    + surfaceNoise * uSurfaceWarp
    + bassInfluence * 0.8
    + beatRipple
    + shimmer
    + uChaos * surfaceNoise * 0.5;

  // Optical path difference: 2 * n * d * cos(theta)
  float opd = 2.0 * uRefractionIndex * thickness * cosTheta;

  // Interference for each RGB wavelength
  float phaseBase = opd * 6.2832;
  float paletteShift = uPalette * 0.3;

  float intR = cos(phaseBase * 1.0 + paletteShift) * 0.5 + 0.5;
  float intG = cos(phaseBase * 1.32 + paletteShift + 0.5) * 0.5 + 0.5;
  float intB = cos(phaseBase * 1.5 + paletteShift + 1.0) * 0.5 + 0.5;

  // Fresnel-like edge brightening
  float fresnel = smoothstep(0.0, 1.0, theta) * 0.5 + 0.5;

  // Apply intensity and fresnel
  float brightness = uIntensity * 1.2;
  float colR = intR * fresnel * brightness;
  float colG = intG * fresnel * brightness;
  float colB = intB * fresnel * brightness;

  // Secondary iridescent layer at different scale
  float opd2 = 2.0 * (uRefractionIndex * 1.1) * (thickness * 2.3) * cosTheta;
  float phase2 = opd2 * 6.2832;
  float int2R = cos(phase2 * 1.0 + paletteShift + 2.0) * 0.5 + 0.5;
  float int2G = cos(phase2 * 1.32 + paletteShift + 2.5) * 0.5 + 0.5;
  float int2B = cos(phase2 * 1.5 + paletteShift + 3.0) * 0.5 + 0.5;

  // Blend layers
  float blendFactor = 0.3 + uChaos * 0.2;
  float blendR = mix(colR, int2R * brightness, blendFactor);
  float blendG = mix(colG, int2G * brightness, blendFactor);
  float blendB = mix(colB, int2B * brightness, blendFactor);

  // Specular highlight near center (soap bubble bright spot)
  float specular = pow(smoothstep(0.3, 0.0, dist), 3.0) * 0.3;

  // Energy brightening + beat pulse brightness
  float energyBoost = uEnergy * uSensitivity * 0.2;
  float beatBright = beatPulse * 0.15;

  float finalR = blendR + specular + energyBoost + beatBright;
  float finalG = blendG + specular + energyBoost + beatBright;
  float finalB = blendB + specular + energyBoost + beatBright;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
