uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash11(float pp) {
  return fract(sin(pp * 127.1) * 43758.5453);
}

float hash21(vec2 pp) {
  return fract(sin(dot(pp, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 pp) {
  vec2 i = floor(pp);
  vec2 f = fract(pp);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Jellyfish bell SDF (dome shape)
float bellSDF(vec2 pp, float radius, float squash) {
  pp.y *= squash;
  float dome = length(pp) - radius;
  // Flatten bottom
  float bottom = pp.y + radius * 0.3;
  return max(dome, bottom);
}

// Bioluminescent color palette
vec3 bioColor(float idx, float paletteShift) {
  float h = fract(idx * 0.3 + paletteShift * 0.15);
  vec3 cyan = vec3(0.1, 1.0, 1.0);
  vec3 magenta = vec3(1.0, 0.15, 0.9);
  vec3 green = vec3(0.15, 1.0, 0.55);
  if (h < 0.33) return mix(cyan, magenta, h * 3.0);
  if (h < 0.67) return mix(magenta, green, (h - 0.33) * 3.0);
  return mix(green, cyan, (h - 0.67) * 3.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.35) * 0.07;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float bpmPulse = uBpmSin * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float harmonicVal = uHarmonicity * uSensitivity;
  float warmthVal = uWarmth * uSensitivity;

