  float depthGrad = smoothstep(1.5, -1.5, p.y);
  vec3 col = mix(vec3(0.0, 0.02, 0.05), vec3(0.0, 0.005, 0.02), depthGrad);

  // Caustic light patterns (surface light filtering through water)
  float caustic1 = sin(p.x * 5.0 + time * 0.7) * cos(p.y * 4.0 + time * 0.5);
  float caustic2 = sin(p.x * 7.0 - time * 0.6 + 2.0) * cos(p.y * 6.0 - time * 0.4);
  float caustics = pow(max(0.0, caustic1 + caustic2) * 0.5, 2.0);
