    // Bell size and squash (pulsing with BPM)
    float bellRadius = 0.15 + hash11(seed + 4.0) * 0.08;
    float pulsePhase = time * 2.0 + bobPhase;
    float bellPulse = sin(pulsePhase) * 0.5 + 0.5;
    float squash = 1.2 + bellPulse * 0.4 + kickVal * 0.2;
    bellRadius *= 0.9 + bellPulse * 0.1;

