    bellCol += (jellyColor + vec3(0.3)) * bioGlow * 0.5;

    // Internal pattern: radial ribs
    float ribAngle = atan(localP.y, localP.x);
    float ribs = pow(cos(ribAngle * 8.0) * 0.5 + 0.5, 3.0);
    bellCol += jellyColor * 0.2 * ribs * bellMask;

    col += bellCol;

    // Tentacles: 5-8 wavy strands hanging below
    int numTentacles = 5 + int(hash11(seed + 5.0) * 3.0);
    for (int t = 0; t < 8; t++) {
      if (t >= numTentacles) break;
      float ft = float(t);
      float tentX = (ft / float(numTentacles - 1) - 0.5) * bellRadius * 1.6;

      // Tentacle start at bell bottom
      float tentStartY = -bellRadius * 0.3 / squash;

      // Wavy tentacle shape
      float tentLen = 0.3 + hash11(seed + ft * 3.0 + 10.0) * 0.25;
      float tentPhase = hash11(seed + ft * 3.0 + 20.0) * 6.2832;

      // Multiple points along tentacle
      float closestDist = 1e5;
      for (int seg = 0; seg < 8; seg++) {
        float fs = float(seg) / 7.0;
        float segY = tentStartY - fs * tentLen;
        float wave = sin(fs * 6.2832 + time * 2.0 + tentPhase + midsVal * 3.0) * 0.03 * (1.0 + fs);
        vec2 segPos = jellyCenter + vec2(tentX + wave, segY);
        float sd = length(p - segPos);
        closestDist = min(closestDist, sd);
      }

      float tentWidth = 0.005 + (1.0 - 0.0) * 0.003; // thin
      float tentacle = smoothstep(tentWidth * 3.0, 0.0, closestDist);
      float tentGlow = smoothstep(tentWidth * 8.0, 0.0, closestDist) * 0.1;

      col += jellyColor * tentacle * 0.3;
      col += jellyColor * tentGlow;
    }

    // Outer glow halo
    float outerGlow = smoothstep(bellRadius * 3.0, 0.0, length(localP)) * 0.04;
    col += jellyColor * outerGlow;
  }

  // Underwater particles (plankton/detritus)
  for (int i = 0; i < 25; i++) {
    float fi = float(i);
    float seed = fi * 3.17;
    vec2 particlePos = vec2(
      (hash11(seed) - 0.5) * 3.0,
      fract(hash11(seed + 1.0) - time * 0.05 * (0.5 + hash11(seed + 2.0))) * 3.0 - 1.5
    );
    float pd = length(p - particlePos);
    float particleSize = 0.005 + hash11(seed + 3.0) * 0.005;
    float particle = smoothstep(particleSize, 0.0, pd);
    float particleGlow = smoothstep(particleSize * 4.0, 0.0, pd) * 0.1;
    col += vec3(0.3, 0.6, 0.8) * (particle + particleGlow) * 0.3;
  }

  // Energy: overall bioluminescence boost
  col *= 1.0 + energyVal * 0.3;

  // Warmth: water color temperature
  col += vec3(0.03, 0.0, 0.0) * warmthVal * 0.3;
  col -= vec3(0.0, 0.0, 0.03) * warmthVal * 0.2;

  // Harmonic: resonance glow
  col += vec3(0.02, 0.04, 0.06) * harmonicVal * 0.3;

  // Chaos: current turbulence
  float turbulence = noiseVal(p * 5.0 + time * 1.5) - 0.5;
  col += vec3(0.0, 0.02, 0.03) * turbulence * uChaos * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
