uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFoldComplexity;
uniform float uGridScale;
uniform float uWarpStrength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Fold space around an axis at the given position
vec2 fold(vec2 p, float angle, vec2 center) {
  p -= center;
  float c = cos(angle);
  float s = sin(angle);
  float d = p.x * c + p.y * s;
  if (d < 0.0) {
    p -= 2.0 * d * vec2(c, s);
  }
  return p + center;
}

// Diamond/harlequin pattern
float diamond(vec2 p) {
  return step(1.0, mod(floor(p.x) + floor(p.y), 2.0));
}

// Jester color palette: neon green, purple, yellow
vec3 jesterColor(float t, float paletteShift) {
  t = fract(t + paletteShift * 0.15);
  if (t < 0.333) {
    return mix(vec3(0.1, 1.0, 0.2), vec3(0.6, 0.0, 1.0), t * 3.0);
  } else if (t < 0.666) {
    return mix(vec3(0.6, 0.0, 1.0), vec3(1.0, 0.95, 0.1), (t - 0.333) * 3.0);
  } else {
    return mix(vec3(1.0, 0.95, 0.1), vec3(0.1, 1.0, 0.2), (t - 0.666) * 3.0);
  }
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.8;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // === DOMAIN WARPING ===
  float warp = uWarpStrength * (1.0 + bassVal * 0.5);
  vec2 warpOffset = vec2(
    sin(p.y * 3.0 + time * 1.2) * warp * 0.3,
    cos(p.x * 3.0 + time * 0.9) * warp * 0.3
  );
  // Noise-based warp
  warpOffset += vec2(
    noise(p * 2.0 + time * 0.5) - 0.5,
    noise(p * 2.0 + time * 0.5 + 100.0) - 0.5
  ) * warp * 0.4;
  p += warpOffset;

  // === RECURSIVE FOLDING ===
  for (int i = 0; i < 8; i++) {
    if (float(i) >= uFoldComplexity) break;
    float fi = float(i);
    float foldAngle = time * 0.3 + fi * 1.1 + midsVal * 0.5;
    vec2 foldCenter = vec2(
      sin(time * 0.4 + fi * 2.1) * 0.3,
      cos(time * 0.3 + fi * 1.7) * 0.3
    );
    p = fold(p, foldAngle, foldCenter);
    // Scale down slightly each fold for fractal detail
    p *= 1.0 + trebleVal * 0.1;
  }

  // === ROTATING DIAMOND GRID ===
  float rotAngle = time * 0.2 + beatPulse * 0.5;
  float cr = cos(rotAngle);
  float sr = sin(rotAngle);
  vec2 rp = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

  float scale = uGridScale * (1.0 + sin(time * 0.5) * 0.2);
  vec2 gridP = rp * scale;

  // Diamond checkerboard
  float checker = diamond(gridP);

  // Second layer at 45 degrees for harlequin effect
  vec2 gridP2 = gridP * 0.707 + vec2(gridP.y, -gridP.x) * 0.707;
  float checker2 = diamond(gridP2 * 0.7 + time * 0.5);

  // === TRICKSTER FACE FORMATION ===
  // Radial symmetry creates face-like patterns
  float r = length(p);
  float angle = atan(p.y, p.x);
  float faceSymmetry = abs(sin(angle * 3.0 + time * 0.5));
  float eyePattern = smoothstep(0.3, 0.25, abs(r - 0.35)) *
                     smoothstep(0.2, 0.0, abs(abs(p.x) - 0.25)) * 0.5;
  float mouthPattern = smoothstep(0.05, 0.0, abs(r - 0.5 + sin(angle * 2.0) * 0.1)) * 0.3;

  // === COLOR ===
  float colorT = checker * 0.33 + checker2 * 0.33 + fract(r * 2.0 + time * 0.3) * 0.34;
  colorT += noise(rp * 3.0 + time * 0.3) * uChaos * 0.3;
  vec3 col = jesterColor(colorT, uPalette);

  // Contrast: invert sections on beat
  float invertZone = step(0.5, fract(length(p) * 2.0 + beatPulse * 2.0));
  col = mix(col, vec3(1.0) - col, invertZone * beatPulse * 0.5);

  // Add face-like glowing features
  col += vec3(1.0, 0.8, 0.2) * eyePattern;
  col += vec3(0.8, 0.2, 1.0) * mouthPattern * faceSymmetry;

  // Edge glow between checker regions
  vec2 gridFrac = fract(gridP);
  float edgeDist = min(min(gridFrac.x, 1.0 - gridFrac.x), min(gridFrac.y, 1.0 - gridFrac.y));
  float edgeGlow = exp(-edgeDist * 15.0) * 0.3 * (0.5 + trebleVal);
  col += vec3(0.5, 1.0, 0.3) * edgeGlow;

  // Onset flash
  col += vec3(1.0, 0.9, 0.5) * onsetFlash * 0.2;

  // Beat pulse brightness
  col *= 1.0 + beatPulse * 0.25;

  // Overall intensity
  col *= uIntensity * 1.1;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
