__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Psychedelic palette with rotating hue
vec3 psychPalette(float t, float shift) {
  return 0.5 + 0.5 * cos(6.2832 * (t * vec3(1.0, 0.8, 0.6) + vec3(shift, shift + 0.33, shift + 0.67)));
}

// Smooth iteration count for continuous coloring
float juliaSmooth(vec2 z, vec2 c, int maxIter) {
  float zLen2 = 0.0;
  float iterations = 0.0;
  for (int i = 0; i < 256; i++) {
    if (i >= maxIter) break;
    // z = z^2 + c
    float xNew = z.x * z.x - z.y * z.y + c.x;
    float yNew = 2.0 * z.x * z.y + c.y;
    z = vec2(xNew, yNew);
    zLen2 = z.x * z.x + z.y * z.y;
    if (zLen2 > 256.0) {
      // Smooth iteration count using renormalization
      float logZn = log(zLen2) * 0.5;
      float nu = log(logZn / log(2.0)) / log(2.0);
      iterations = float(i) + 1.0 - nu;
      return iterations;
    }
  }
  return -1.0; // Interior
}

// Domain warping for extra psychedelia
vec2 domainWarp(vec2 pt, float amt) {
  float ang = amt * sin(pt.x * 3.0) * cos(pt.y * 2.7);
  float ca = cos(ang);
  float sa = sin(ang);
  return vec2(ca * pt.x - sa * pt.y, sa * pt.x + ca * pt.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  // Audio reactivity (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float trebleVal = treble() * uSensitivity * 1.8;
  float midsVal = mids() * uSensitivity * 1.8;

  // Chaos-based domain warping
  p = domainWarp(p, uChaos * 0.3 + bassVal * 0.15);

  // Orbiting c parameter in a cardioid-like path
  float orbitSpeed = time * 0.2;
  float orbitRadius = 0.7885 + bassVal * 0.15 + uChaos * 0.1;
  float cAngle = orbitSpeed + sin(orbitSpeed * 0.37) * 0.5;
  vec2 c = vec2(
    orbitRadius * cos(cAngle) + sin(time * 0.13) * 0.05,
    orbitRadius * sin(cAngle) + cos(time * 0.17) * 0.05
  );

  // Modulate c with spectral features
  c.x += uSpectralFlux * uSensitivity * 0.1;
  c.y += uHarmonicity * uSensitivity * 0.08;

  // Compute Julia set with adaptive iterations
  int maxIter = 160 + int(trebleVal * 80.0);
  float iterResult = juliaSmooth(p, c, maxIter);

  vec3 col;
  if (iterResult < 0.0) {
    // Interior: pulsing dark with bass
    float interiorGlow = 0.05 + bassVal * 0.15;
    col = psychPalette(time * 0.1 + uPalette, time * 0.05) * interiorGlow;
  } else {
    // Exterior: smooth rainbow coloring
    float t = iterResult * 0.02 + uPalette * 0.3;
    t += time * 0.08 + sin(uTime * 0.2) * 0.15; // Rotating palette

    // Multi-layer palette blending
    vec3 col1 = psychPalette(t, time * 0.03);
    vec3 col2 = psychPalette(t * 1.5 + 0.5, time * 0.07 + 0.33);
    float blendFactor = sin(iterResult * 0.1 + time) * 0.5 + 0.5;
    col = mix(col1, col2, blendFactor);

    // Treble edge brightening
    float edgeBright = exp(-iterResult * 0.03) * trebleVal * 2.0;
    col += vec3(edgeBright * 0.5, edgeBright * 0.3, edgeBright * 0.8);

    // Kick flash - bright pulse on edges
    col += vec3(1.0, 0.9, 0.7) * uKick * uSensitivity * exp(-iterResult * 0.05) * 0.8;
  }

  // BPM breathing modulation
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Spectral centroid tints warm/cool
  col = mix(col, col * vec3(1.2, 0.9, 0.8), uSpectralCentroid * uSensitivity * 0.3);

  // Warmth influence
  col = mix(col, col * vec3(1.1, 0.95, 0.85), uWarmth * uSensitivity * 0.2);

  // Energy overall brightness
  col *= 0.8 + uEnergy * uSensitivity * 0.6;

  // Onset sparkle
  float sparkle = uOnset * uSensitivity * sin(vUv.x * 50.0 + vUv.y * 50.0 + time * 10.0) * 0.3;
  col += vec3(sparkle);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
