__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uNebulaScale;
uniform float uStarDensity;

// 2D hash
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Smooth value noise
float noise2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - f * 2.0);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// FBM with variable octaves controlled by amplitude
float fbm4(vec2 p, float t, float drift) {
  float val = 0.0;
  float amp = 0.5;
  // Octave 1
  val += amp * noise2(p + vec2(t * 0.1 + drift, t * 0.08));
  p = p * 2.03 + vec2(1.7, 9.2);
  amp *= 0.5;
  // Octave 2
  val += amp * noise2(p + vec2(-t * 0.07, t * 0.12 + drift));
  p = p * 2.01 + vec2(8.3, 2.8);
  amp *= 0.5;
  // Octave 3
  val += amp * noise2(p + vec2(t * 0.05 + drift, -t * 0.06));
  p = p * 2.02 + vec2(3.1, 7.4);
  amp *= 0.5;
  // Octave 4
  val += amp * noise2(p + vec2(-t * 0.09, t * 0.04 + drift));
  return val;
}

// Hot gas palette: reds, oranges, warm yellows
vec3 hotGasPalette(float t, float offset) {
  float tau = 6.28318;
  float s = fract(t + offset * 0.1);
  float r = 0.7 + 0.3 * cos(tau * (s * 0.8 + 0.0));
  float g = 0.3 + 0.3 * cos(tau * (s * 1.0 + 0.35));
  float b = 0.1 + 0.15 * cos(tau * (s * 1.2 + 0.6));
  return vec3(r, g, b);
}

// Cool gas palette: blues, purples, teals
vec3 coolGasPalette(float t, float offset) {
  float tau = 6.28318;
  float s = fract(t + offset * 0.1 + 0.5);
  float r = 0.2 + 0.2 * cos(tau * (s * 1.0 + 0.5));
  float g = 0.15 + 0.25 * cos(tau * (s * 0.9 + 0.3));
  float b = 0.6 + 0.4 * cos(tau * (s * 0.8 + 0.0));
  return vec3(r, g, b);
}

void main() {
  vec2 uv = (vUv - 0.5) * (uZoom * 3.0 + 1.5);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio signals (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  // Slow global rotation
  float rotAngle = time * 0.08 + uChaos * sin(time * 0.03);
  float cosR = cos(rotAngle);
  float sinR = sin(rotAngle);
  vec2 rotUv = vec2(
    uv.x * cosR - uv.y * sinR,
    uv.x * sinR + uv.y * cosR
  );

  // Bass makes nebula pulse/expand
  float expansion = 1.0 + bassVal * 0.2;
  rotUv *= expansion;

  // Nebula scale control
  float scale = uNebulaScale * 3.0 + 1.0;

  // ---- HOT GAS LAYER (reds/oranges) ----
  vec2 hotCoord = rotUv * scale;
  float hotNoise = fbm4(hotCoord, time * 0.5, 0.0);

  // Domain warp the hot gas
  float hotWarp1 = fbm4(hotCoord + vec2(5.2, 1.3), time * 0.4, 1.0);
  float hotWarp2 = fbm4(hotCoord + vec2(8.7, 3.1), time * 0.35, 2.0);
  vec2 hotWarped = hotCoord + vec2(hotWarp1 - 0.5, hotWarp2 - 0.5) * 1.5;
  float hotFinal = fbm4(hotWarped, time * 0.6, 0.5);

  // Shape the gas clouds
  float hotCloud = smoothstep(0.2, 0.8, hotFinal);
  hotCloud *= hotCloud; // Make it more contrasty

  // Color the hot gas
  float hotColorT = fract(hotFinal * 1.5 + time * 0.04 + sin(uTime * 0.2) * 0.15);
  vec3 hotColor = hotGasPalette(hotColorT, uPalette) * hotCloud;

  // ---- COOL GAS LAYER (blues/purples) ----
  vec2 coolCoord = rotUv * scale * 0.8 + vec2(3.7, 2.1);
  float coolNoise = fbm4(coolCoord, time * 0.4, 3.0);

  // Domain warp the cool gas (different direction)
  float coolWarp1 = fbm4(coolCoord + vec2(2.9, 7.4), time * 0.3, 4.0);
  float coolWarp2 = fbm4(coolCoord + vec2(6.1, 4.8), time * 0.25, 5.0);
  vec2 coolWarped = coolCoord + vec2(coolWarp1 - 0.5, coolWarp2 - 0.5) * 1.2;
  float coolFinal = fbm4(coolWarped, time * 0.45, 1.5);

  // Shape the cool gas
  float coolCloud = smoothstep(0.25, 0.75, coolFinal);
  coolCloud *= coolCloud;

  // Color the cool gas
  float coolColorT = fract(coolFinal * 1.3 + time * 0.025 + 0.3);
  vec3 coolColor = coolGasPalette(coolColorT, uPalette) * coolCloud;

  // ---- STELLAR POINTS (bright stars) ----
  float starScale = 25.0 + uStarDensity * 30.0;
  vec2 starCoord = rotUv * starScale;
  vec2 starCell = floor(starCoord);
  vec2 starLocal = fract(starCoord) - 0.5;

  float starRand = hash21(starCell);
  float starOffset = hash21(starCell + vec2(43.1, 17.3));

  // Star position jitter within cell
  float starX = (starOffset - 0.5) * 0.6;
  float starY = (hash21(starCell + vec2(71.9, 53.2)) - 0.5) * 0.6;
  float starDist = length(starLocal - vec2(starX, starY));

  // Star brightness threshold (higher density = lower threshold)
  float starThresh = 0.9 - uStarDensity * 0.2;
  float starBright = smoothstep(0.05, 0.0, starDist) * step(starThresh, starRand);

  // Treble boosts stellar points
  starBright *= 1.0 + trebleVal * 3.0;

  // Star twinkle
  float twinkle = sin(time * 5.0 + starRand * 50.0) * 0.3 + 0.7;
  starBright *= twinkle;

  // Star color: mostly white with slight color tint
  vec3 starColor = vec3(0.9, 0.85, 1.0) * starBright;
  // Add color tint from gas layers
  starColor += hotGasPalette(starRand, uPalette) * starBright * 0.3;

  // ---- BEAT FLASH IN CLUSTERS ----
  float flashRegion = fbm4(rotUv * 2.0 + vec2(time * 0.5, 0.0), time * 2.0, 7.0);
  float flashMask = smoothstep(0.5, 0.8, flashRegion);
  float flash = flashMask * beatPulse * 1.5;
  vec3 flashColor = hotGasPalette(fract(time * 0.1), uPalette) * flash;

  // ---- COMBINE LAYERS ----
  vec3 nebula = vec3(0.0);

  // Background: very dark with subtle color
  nebula += vec3(0.01, 0.005, 0.02);

  // Cool gas (background layer)
  nebula += coolColor * 0.8;

  // Hot gas (foreground layer, additive)
  nebula += hotColor * 0.9;

  // Mids shift the blend between hot and cool
  float hotCoolBlend = midsVal * 0.3;
  nebula += hotColor * hotCoolBlend - coolColor * hotCoolBlend * 0.5;

  // Stellar points on top
  nebula += starColor;

  // Beat flash
  nebula += flashColor;

  // Onset: bright surge across whole nebula
  float onsetSurge = onset * 0.3;
  nebula += vec3(onsetSurge * 0.5, onsetSurge * 0.3, onsetSurge * 0.7);

  // Kick: expansion already handled, add brightness kick
  nebula *= 1.0 + kick * 0.3;

  // Apply intensity
  nebula *= uIntensity * 1.5;

  // Energy drives overall luminosity
  nebula *= 1.0 + energy * 0.25;

  // Chaos adds noise grain
  float grain = (hash21(vUv * 500.0 + vec2(time * 100.0, 0.0)) - 0.5) * uChaos * 0.05;
  nebula += vec3(grain);

  // Vignette
  float dist = length(vUv - 0.5) * 1.4;
  float vignette = 1.0 - smoothstep(0.5, 1.2, dist);
  nebula *= vignette;

  // === PSYCHEDELIC ENHANCEMENT ===
  nebula = psychedelicColor(nebula);
  gl_FragColor = vec4(
    clamp(nebula.x, 0.0, 1.0),
    clamp(nebula.y, 0.0, 1.0),
    clamp(nebula.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFoldCount;
uniform float uRecursionDepth;
uniform float uRotationSpeed;
uniform float uPatternScale;

#define PI 3.14159265
#define TAU 6.28318530

// 2D rotation matrix
mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Kaleidoscopic fold
vec2 kaleidoFold(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = TAU / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

// Spectral palette
vec3 spectrum(float t, float palette) {
  float shift = palette * 0.25;
  vec3 a = vec3(0.5);
  vec3 b = vec3(0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(0.0 + shift, 0.1 + shift, 0.2 + shift);
  return a + b * cos(TAU * (c * t + d));
}

// FBM noise for base pattern
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = m * p;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = (vUv - 0.5) * 2.0 * (1.5 + uZoom);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  // Dynamic fold count modulated by bass — higher range
  float folds = floor(uFoldCount + bassVal * 3.0 + 0.5);
  folds = clamp(folds, 4.0, 20.0);

  // Global rotation — faster
  float rotSpeed = uRotationSpeed * 0.5 + beatVal * 0.2;
  uv = rot2(time * rotSpeed + midsVal * 0.5) * uv;

  // Kick radial zoom pulse — stronger
  float zoomPulse = 1.0 + kickVal * 0.5;

  vec2 p = uv * zoomPulse;
  float totalPattern = 0.0;
  vec3 colorAccum = vec3(0.0);

  // Recursive kaleidoscope iterations
  int maxDepth = int(uRecursionDepth + 0.5);
  maxDepth = min(maxDepth, 5);

  for (int depth = 0; depth < 5; depth++) {
    if (depth >= maxDepth) break;
    float depthF = float(depth);

    // Fold
    p = kaleidoFold(p, folds);

    // Rotate between recursions
    p = rot2(time * 0.2 * (depthF + 1.0) + depthF * 0.5) * p;

    // Scale into recursive level
    float scale = uPatternScale * (1.5 + depthF * 0.5);
    vec2 patternUV = p * scale;

    // Base pattern at this recursion level
    float pattern = fbm(patternUV + time * 0.3 * (depthF + 1.0));
    pattern += sin(length(patternUV) * 5.0 - time * 2.0) * 0.2;
    pattern += trebleVal * sin(patternUV.x * 20.0 + patternUV.y * 20.0) * 0.1;

    // Color for this depth
    float colorT = pattern + depthF * 0.3 + time * 0.05 + midsVal * 0.2;
    vec3 depthColor = spectrum(colorT, uPalette + depthF * 0.5);

    // Deeper levels are dimmer
    float depthBright = 1.0 / (1.0 + depthF * 0.5);

    colorAccum += depthColor * pattern * depthBright;
    totalPattern += pattern * depthBright;

    // Chaos adds distortion between levels
    p += vec2(sin(time + depthF), cos(time * 0.7 + depthF)) * uChaos * 0.2;
  }

  // Normalize
  vec3 color = colorAccum / max(totalPattern, 0.5);

  // Radial glow from center
  float r = length(uv);
  float centerGlow = exp(-r * 1.5) * 0.3;
  color += centerGlow * spectrum(time * 0.1, uPalette);

  // Beat pulse brightness
  color *= 1.0 + beatVal * 0.4;

  // Intensity
  color *= uIntensity * 1.4;

  // Gamma
  color = pow(clamp(color, 0.0, 1.0), vec3(0.9));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(color, 1.0);
}

