    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 m = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p * 2.0;
    a *= 0.5;
  }
  return v;
}

// Kaleidoscope fold
vec2 kaleidoFold(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float centroidVal = uSpectralCentroid * uSensitivity;

  // Rotation — faster
  float rot = time * uRotSpeed * 1.5 + uBpmSin * 0.8;
  float c = cos(rot), s = sin(rot);
  p = vec2(p.x * c - p.y * s, p.x * s + p.y * c);

  // Scale
  p *= uZoom + 0.5;

  // Kaleidoscope fold
  p = kaleidoFold(p, uFoldCount);

  // Secondary fold for extra complexity — higher
