  vec2 q = kaleidoFold(p * 2.0, subFold);

  // === DOMAIN WARPING ===
  float warpAmount = uWarpStrength * (1.0 + bassVal * 1.5);

  // Multi-layer domain warp
  vec2 warp1 = vec2(
    fbm(p * 3.0 + time * 0.3),
    fbm(p * 3.0 + vec2(5.2, 1.3) + time * 0.25)
  );

  vec2 warp2 = vec2(
    fbm(p * 3.0 + warp1 * warpAmount + vec2(1.7, 9.2) + time * 0.2),
    fbm(p * 3.0 + warp1 * warpAmount + vec2(8.3, 2.8) + time * 0.15)
