  vec2 p3 = p2 * 2.01;
  float n3 = noise2(p3 + vec2(-t * 0.07, t * 0.14)) * 0.125;
  vec2 p4 = p3 * 2.02;
  float n4 = noise2(p4 + vec2(t * 0.05, -t * 0.11)) * 0.0625;
