  vec2 p4 = p3 * 2.07;
  float n4 = noise2(p4 + vec2(-t * 0.09, t * 0.21)) * 0.1;
  return n1 + n2 + n3 + n4;
}

// Plasma temperature color: black -> deep red -> orange -> yellow -> white
// with extra vibrancy at arm cores
vec3 plasmaColor(float temp, float coreBoost) {
  float t = clamp(temp, 0.0, 1.0);
  float r = smoothstep(0.08, 0.35, t);
  float g = smoothstep(0.3, 0.65, t) * (1.0 + coreBoost * 0.2);
  float bChan = smoothstep(0.55, 0.9, t);
  float rBoosted = r * (1.0 + coreBoost * 0.4);
  return vec3(clamp(rBoosted, 0.0, 1.0), clamp(g, 0.0, 1.0), bChan);
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  vec2 rawP = (vUv - 0.5) * (uZoom * 3.0 + 1.5);
  float time = uTime * (uSpeed * 2.0);

  // Audio (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;

  // Polar coordinates
  float radius = sqrt(rawP.x * rawP.x + rawP.y * rawP.y);
  float angle = atan(rawP.y, rawP.x);

  // Vortex rotation: inner spins faster than outer
  float vortexAngle = uVortexTightness / (radius + 0.3);
  float spin = time * 1.5 + vortexAngle + bassVal * 2.0;

  // Breathing / pulsing: arms expand and contract
  float breathe = sin(time * 0.5) * 0.15 + bassVal * 0.3;

  // Organic arm computation
  // Use Cartesian-based noise coords for seamless angular wrapping
  float cosA = cos(angle);
  float sinA = sin(angle);

  // Arm 0
  float armPhase0 = angle + spin + 0.0;
  vec2 armNoiseCoord0 = vec2(cosA * radius * 0.5 + time * 0.11, sinA * radius * 0.5 + time * 0.13);
  float armDisplace0 = (fbm(armNoiseCoord0, time) - 0.5) * 1.2;
  float wave0 = sin(radius * 8.0 - time * 3.5 + 0.0) * 0.15;
  float displaced0 = armPhase0 + armDisplace0 + wave0;
  float armBase0 = sin(displaced0 * uArmCount) * 0.5 + 0.5;
  float taper0 = (1.0 - smoothstep(0.0, 1.8, radius)) * (1.0 + breathe);
  float arm0 = pow(armBase0, 2.0 + uChaos * 3.0) * taper0;

  // Arm 1 (offset by pi/2)
  float armPhase1 = angle + spin + 1.5708;
  vec2 armNoiseCoord1 = vec2(cosA * radius * 0.5 + time * 0.15, sinA * radius * 0.5 - time * 0.09);
  float armDisplace1 = (fbm(armNoiseCoord1, time * 1.1) - 0.5) * 1.2;
  float wave1 = sin(radius * 7.5 - time * 3.2 + 1.5708) * 0.17;
  float displaced1 = armPhase1 + armDisplace1 + wave1;
  float armBase1 = sin(displaced1 * uArmCount) * 0.5 + 0.5;
  float taper1 = (1.0 - smoothstep(0.0, 1.8, radius)) * (1.0 + breathe);
  float arm1 = pow(armBase1, 2.0 + uChaos * 3.0) * taper1;

  // Arm 2 (offset by pi)
  float armPhase2 = angle + spin + 3.14159;
  vec2 armNoiseCoord2 = vec2(cosA * radius * 0.5 - time * 0.07, sinA * radius * 0.5 + time * 0.14);
  float armDisplace2 = (fbm(armNoiseCoord2, time * 0.9) - 0.5) * 1.2;
  float wave2 = sin(radius * 8.5 - time * 3.8 + 3.14159) * 0.14;
  float displaced2 = armPhase2 + armDisplace2 + wave2;
  float armBase2 = sin(displaced2 * uArmCount) * 0.5 + 0.5;
  float taper2 = (1.0 - smoothstep(0.0, 1.8, radius)) * (1.0 + breathe);
  float arm2 = pow(armBase2, 2.0 + uChaos * 3.0) * taper2;

  // Arm 3 (offset by 3pi/2)
  float armPhase3 = angle + spin + 4.71239;
  vec2 armNoiseCoord3 = vec2(cosA * radius * 0.5 + time * 0.05, sinA * radius * 0.5 - time * 0.11);
  float armDisplace3 = (fbm(armNoiseCoord3, time * 1.05) - 0.5) * 1.2;
  float wave3 = sin(radius * 7.8 - time * 3.4 + 4.71239) * 0.16;
  float displaced3 = armPhase3 + armDisplace3 + wave3;
  float armBase3 = sin(displaced3 * uArmCount) * 0.5 + 0.5;
  float taper3 = (1.0 - smoothstep(0.0, 1.8, radius)) * (1.0 + breathe);
  float arm3 = pow(armBase3, 2.0 + uChaos * 3.0) * taper3;

  // Combine all arms -- take max for sharp arm separation
  float combinedArms = max(max(arm0, arm1), max(arm2, arm3));

  // Core intensity indicator for color vibrancy boost
  float coreIntensity = combinedArms * (1.0 - radius * 0.5);

  // Organic tendrils at tips (use Cartesian-based coords for seamless wrapping)
  float tipRegion = smoothstep(0.6, 1.4, radius);
  float tendrilAngularFreq = uPlasmaDensity * 1.25;
  vec2 tendrilCoord = vec2(
    cosA * radius * (uPlasmaDensity * 2.5) - time * 0.7,
    sinA * radius * (uPlasmaDensity * 2.0) + time * 0.4
  );
  float tendrilDetail = fbmFine(tendrilCoord, time * 1.3);
  float tipTendrils = tendrilDetail * tipRegion * (combinedArms + 0.15);

  // Additional wispy dissolution at the very tips
  vec2 wispCoord = vec2(
    cosA * radius * 12.0 + time * 1.2,
    sinA * radius * 12.0 - time * 0.8
  );
  float wisps = noise2(wispCoord) * smoothstep(1.0, 1.8, radius) * 0.3;

  // Plasma noise layer over the arms (Cartesian-based for seamless wrapping)
  vec2 noiseCoord = vec2(
    cosA * radius * uPlasmaDensity + time * 0.3,
    sinA * radius * uPlasmaDensity - time * 0.5
  );
  float plasmaNoiseVal = fbm(noiseCoord, time);

  // Combine arm structure with noise
  float plasmaField = combinedArms * (0.7 + plasmaNoiseVal * 0.6)
    + tipTendrils * 0.5
    + wisps;

  // Electric discharge: high-frequency flickers (Cartesian coords for seamless wrapping)
  vec2 dischargeSeed = vec2(
    cosA * radius * 8.0 + time * uDischargeRate,
    sinA * radius * 8.0 - time * (uDischargeRate * 0.7)
  );
  float dischargeRaw = noise2(dischargeSeed);
  float discharge = smoothstep(0.72, 0.95, dischargeRaw)
    * (trebleVal + 0.2)
    * (1.0 - smoothstep(0.0, 1.5, radius));

  // Radial falloff: bright core, fades outward
  float coreBright = exp(-radius * 1.5) * (1.0 + bassVal * 0.5);
  float edgeFade = 1.0 - smoothstep(1.0, 2.2, radius);

  // Temperature: combine all layers
  float temperature = plasmaField * edgeFade
    + coreBright * 0.4
    + discharge * 0.6
    + kick * 0.3 * coreBright;

  // Color
  vec3 baseColor = plasmaColor(temperature * (uIntensity * 1.3), coreIntensity);

  // Palette shift: allow cool colors via palette param
  float coolShift = uPalette * 0.1;
  vec3 shiftedColor = vec3(
    baseColor.x * (1.0 - coolShift * 0.5),
    baseColor.y + coolShift * baseColor.z * 0.3,
    baseColor.z + coolShift * baseColor.x * 0.7
  );

  // Mids add purple/magenta tint to mid-temperature regions
  float midTint = midsVal * 0.2 * smoothstep(0.3, 0.6, temperature);
  vec3 tintedColor = vec3(
    shiftedColor.x + midTint,
    shiftedColor.y,
    shiftedColor.z + midTint * 0.8
  );

  // Beat pulse
  float pulse = beatPulse * 0.12 + onset * 0.15;
  vec3 finalCol = tintedColor + vec3(pulse, pulse * 0.7, pulse * 1.3);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uInflation;
uniform float uGlassOpacity;
uniform float uRotationAxis;
uniform float uSurfaceRipple;

// Rotation matrices
vec3 rotX(vec3 p, float a) { float c=cos(a),s=sin(a); return vec3(p.x,p.y*c-p.z*s,p.y*s+p.z*c); }
vec3 rotY(vec3 p, float a) { float c=cos(a),s=sin(a); return vec3(p.x*c+p.z*s,p.y,p.z*c-p.x*s); }
vec3 rotZ(vec3 p, float a) { float c=cos(a),s=sin(a); return vec3(p.x*c-p.y*s,p.x*s+p.y*c,p.z); }

// Klein bottle SDF (figure-8 immersion approximation)
float kleinSDF(vec3 p, float inflate, float ripple, float time) {
  // Figure-8 Klein bottle parametric SDF
  float r = length(vec2(p.x, p.z));
  float theta = atan(p.z, p.x);

  // Major radius
  float R = 1.5 * inflate;
  // Minor radius varies with theta for Klein bottle topology
  float minorR = 0.3 + 0.1 * cos(theta * 2.0);
  minorR += ripple * 0.05 * sin(theta * 8.0 + time * 2.0);

  // Self-intersecting tube
  float tubeR = r - R * (1.0 + 0.3 * cos(theta));
  float tubeY = p.y - R * 0.5 * sin(theta);

  float d1 = length(vec2(tubeR, tubeY)) - minorR;

  // Neck of Klein bottle (the self-intersection)
  float neckR = 0.15 + ripple * 0.03 * sin(time * 3.0);
  float neckDist = length(vec2(r - R * 0.3, p.y - sin(theta) * 0.5)) - neckR;

  return min(d1, neckDist);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Camera
  float camDist = 3.0 / (uZoom + 1.0);
  vec3 ro = vec3(0.0, 0.0, camDist);

  // Rotation — faster
  float rotAngle1 = time * 0.5 + uBpmSin2 * 0.8;
  float rotAngle2 = time * 0.35 + uBpmSin * 0.5;

  ro = rotY(ro, rotAngle1);
  ro = rotX(ro, mix(0.3, rotAngle2, uRotationAxis));

  vec3 lookAt = vec3(0.0);
  vec3 forward = normalize(lookAt - ro);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);
  vec3 rd = normalize(forward + right * p.x + up * p.y);

  float inflate = 0.8 + uInflation * 0.4 + bassVal * 0.2;

  // === RAYMARCHING ===
  vec3 col = vec3(0.0);
  float totalAlpha = 0.0;
  float t = 0.0;

  // Multiple passes for glass transparency
  for (int pass = 0; pass < 2; pass++) {
    float passOffset = float(pass) * 0.05;
    t = passOffset;
    bool foundHit = false;

    for (int i = 0; i < 60; i++) {
      vec3 pos = ro + rd * t;
      // Rotate the space (object rotation)
      vec3 rp = rotY(pos, -rotAngle1);
      rp = rotX(rp, -mix(0.3, rotAngle2, uRotationAxis));

      float d = kleinSDF(rp, inflate, uSurfaceRipple, time);

      if (d < 0.003) {
        foundHit = true;
        // Normal
        vec2 e = vec2(0.002, 0.0);
        vec3 n = normalize(vec3(
          kleinSDF(rotX(rotY(pos + e.xyy, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time) -
          kleinSDF(rotX(rotY(pos - e.xyy, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time),
          kleinSDF(rotX(rotY(pos + e.yxy, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time) -
          kleinSDF(rotX(rotY(pos - e.yxy, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time),
          kleinSDF(rotX(rotY(pos + e.yyx, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time) -
          kleinSDF(rotX(rotY(pos - e.yyx, -rotAngle1), -mix(0.3, rotAngle2, uRotationAxis)), inflate, uSurfaceRipple, time)
        ));

        // Lighting
        vec3 lightDir = normalize(vec3(1.0, 2.0, 1.5));
        float diff = max(dot(n, lightDir), 0.0);
        float spec = pow(max(dot(reflect(-lightDir, n), -rd), 0.0), 64.0);
        float fresnel = pow(1.0 - abs(dot(n, -rd)), 3.0);

        // Inside vs outside coloring
        float facing = dot(n, -rd);
        vec3 outsideCol = mix(vec3(0.2, 0.5, 1.0), vec3(0.8, 0.2, 0.6), uPalette * 0.5);
        vec3 insideCol = mix(vec3(0.0, 0.8, 0.6), vec3(1.0, 0.6, 0.1), uPalette * 0.5);
        vec3 surfColor = mix(insideCol, outsideCol, step(0.0, facing));

        // Audio ripple
        float ripplePattern = sin(atan(rp.z, rp.x) * 12.0 + time * 4.5) * midsVal * 0.5;
        surfColor += ripplePattern * outsideCol;

        vec3 hitCol = surfColor * (0.3 + diff * 0.5);
        hitCol += spec * vec3(1.0) * 0.6;
        hitCol += fresnel * surfColor * 0.3;

        float alpha = uGlassOpacity * (0.3 + float(pass) * 0.2);
        col += hitCol * alpha * (1.0 - totalAlpha);
        totalAlpha += alpha * (1.0 - totalAlpha);

        t += 0.1; // Continue past for second layer
        break;
      }
      if (t > 10.0) break;
      t += d * 0.8;
    }
    if (!foundHit) break;
  }

  // Background
  vec3 bg = vec3(0.02, 0.01, 0.04);
  float bgGrad = length(p) * 0.3;
  bg += vec3(0.05, 0.02, 0.08) * (1.0 - bgGrad);
  col += bg * (1.0 - totalAlpha);

  // Energy glow
  col *= 0.8 + energyVal * 0.3;

  // Kick flash
  col += kickVal * vec3(0.1, 0.05, 0.15) * 0.4;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Psychedelic palette
vec3 hyperPalette(float t, float shift) {
  return 0.5 + 0.5 * cos(6.2832 * (t * vec3(1.0, 0.7, 0.5) + vec3(shift, shift + 0.25, shift + 0.5)));
}

// 4D rotation in XW plane
vec4 rotXW(vec4 v, float ang) {
  float ca = cos(ang); float sa = sin(ang);
  return vec4(ca * v.x - sa * v.w, v.y, v.z, sa * v.x + ca * v.w);
}

// 4D rotation in YZ plane
vec4 rotYZ(vec4 v, float ang) {
  float ca = cos(ang); float sa = sin(ang);
  return vec4(v.x, ca * v.y - sa * v.z, sa * v.y + ca * v.z, v.w);
}

// 4D rotation in ZW plane
vec4 rotZW(vec4 v, float ang) {
  float ca = cos(ang); float sa = sin(ang);
  return vec4(v.x, v.y, ca * v.z - sa * v.w, sa * v.z + ca * v.w);
}

// 4D rotation in XY plane
vec4 rotXY(vec4 v, float ang) {
  float ca = cos(ang); float sa = sin(ang);
  return vec4(ca * v.x - sa * v.y, sa * v.x + ca * v.y, v.z, v.w);
}

// Project 4D point to 2D with perspective
vec2 project4Dto2D(vec4 v, float d4, float d3) {
  float w4 = 1.0 / (d4 - v.w);
  vec3 p3 = v.xyz * w4;
  float w3 = 1.0 / (d3 - p3.z);
  return p3.xy * w3;
}

// Distance from point to line segment
float segDist(vec2 pt, vec2 a, vec2 b) {
  vec2 ab = b - a;
  vec2 ap = pt - a;
  float t = clamp(dot(ap, ab) / dot(ab, ab), 0.0, 1.0);
  return length(pt - (a + ab * t));
}

// Generate vertex index (i) as 4D hypercube vertex
vec4 cubeVertex(int idx) {
  float x = mod(float(idx), 2.0) * 2.0 - 1.0;
  float y = mod(floor(float(idx) / 2.0), 2.0) * 2.0 - 1.0;
  float z = mod(floor(float(idx) / 4.0), 2.0) * 2.0 - 1.0;
  float w = mod(floor(float(idx) / 8.0), 2.0) * 2.0 - 1.0;
  return vec4(x, y, z, w);
}

// Check if two vertices share an edge (differ in exactly 1 coordinate)
bool isEdge(int a, int b) {
  int xorVal = a ^ b;
  return xorVal == 1 || xorVal == 2 || xorVal == 4 || xorVal == 8;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 2.0;
  float trebleVal = treble() * uSensitivity * 1.8;
  float midsVal = mids() * uSensitivity * 1.8;

  // Rotation angles modulated by audio
  float a1 = time * 0.3 + bassVal * 0.5;
  float a2 = time * 0.23 + midsVal * 0.4;
  float a3 = time * 0.17 + trebleVal * 0.3;
  float a4 = time * 0.11 + uSpectralFlux * uSensitivity * 0.6;

  // Chaos adds wobble to rotations
  a1 += sin(time * 0.7) * uChaos * 0.5;
  a3 += cos(time * 0.5) * uChaos * 0.4;

  // Projection distances (closer = larger on screen)
  float d4 = 2.2 + bassVal * 0.4;
  float d3 = 2.8 + midsVal * 0.2;

  // Edge thickness modulated by audio — thicker for full-screen presence
  float edgeThick = 0.012 + trebleVal * 0.008 + uEnergy * uSensitivity * 0.005;

  // Vertex glow radius — larger for full-screen presence
  float vertexGlow = 0.07 + uKick * uSensitivity * 0.05;

  // Transform and project all 16 vertices
  vec2 projected[16];
  float depthVals[16];
  for (int i = 0; i < 16; i++) {
    vec4 v = cubeVertex(i);
    v = rotXW(v, a1);
    v = rotYZ(v, a2);
    v = rotZW(v, a3);
    v = rotXY(v, a4);
    depthVals[i] = v.w;
    projected[i] = project4Dto2D(v, d4, d3);
  }

  vec3 col = vec3(0.0);

  // Draw 32 edges
  for (int i = 0; i < 16; i++) {
    for (int j = i + 1; j < 16; j++) {
      if (!isEdge(i, j)) continue;

      float dist = segDist(p, projected[i], projected[j]);
      float edgeColor = float(i + j) / 30.0 + uPalette * 0.3;

      float avgDepth = (depthVals[i] + depthVals[j]) * 0.5;
      float depthBright = 0.5 + 0.5 * (avgDepth + 1.0) * 0.5;

      float edgeGlowVal = smoothstep(edgeThick * 3.0, 0.0, dist) * depthBright;
      float edgeCore = smoothstep(edgeThick, 0.0, dist) * depthBright;

      vec3 eCol = hyperPalette(edgeColor + time * 0.08 + sin(uTime * 0.2) * 0.15, uPalette * 0.5);
      col += eCol * edgeGlowVal * 0.3;
      col += vec3(1.0) * edgeCore * 0.5;
    }
  }

  // Draw 16 vertices
  for (int i = 0; i < 16; i++) {
    float dist = length(p - projected[i]);
    float vertBright = 0.5 + 0.5 * (depthVals[i] + 1.0) * 0.5;

    float glow = exp(-dist * dist / (vertexGlow * vertexGlow)) * vertBright;
    vec3 vCol = hyperPalette(float(i) / 16.0 + time * 0.1, uPalette);
    col += vCol * glow * 1.5;
  }

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.25 * uSensitivity;

  // Onset flash
  col += vec3(0.3, 0.2, 0.5) * uOnset * uSensitivity * 0.5;

  // Spectral centroid warm/cool tint
  col = mix(col, col * vec3(1.3, 0.9, 0.7), uSpectralCentroid * uSensitivity * 0.3);

  // Harmonicity adds structural shimmer
  col += col * uHarmonicity * uSensitivity * sin(time * 20.0) * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBeamCount;
uniform float uBeamWidth;
uniform float uSweepRange;
uniform float uHazeAmount;

float hash(float n) { return fract(sin(n) * 43758.5453); }

float laserBeam(vec2 p, vec2 origin, float angle, float width) {
  float c = cos(angle), s = sin(angle);
  vec2 dir = vec2(c, s);
  vec2 toP = p - origin;
  float along = dot(toP, dir);
  if (along < 0.0) return 0.0;
  float perp = abs(dot(toP, vec2(-s, c)));
  float beam = exp(-perp * perp / (width * width * 0.001));
  beam *= smoothstep(0.0, 0.1, along);
  return beam;
}

vec3 laserColor(float idx, float palette) {
  float t = fract(idx * 0.618 + palette * 0.3 + idx * 0.05);
  vec3 green = vec3(0.0, 1.0, 0.2);
  vec3 red = vec3(1.0, 0.0, 0.1);
  vec3 blue = vec3(0.0, 0.3, 1.0);
  vec3 purple = vec3(0.7, 0.0, 1.0);
  vec3 yellow = vec3(1.0, 0.9, 0.0);
  if (t < 0.2) return mix(green, red, t * 5.0);
  if (t < 0.4) return mix(red, blue, (t - 0.2) * 5.0);
  if (t < 0.6) return mix(blue, purple, (t - 0.4) * 5.0);
  if (t < 0.8) return mix(purple, yellow, (t - 0.6) * 5.0);
  return mix(yellow, green, (t - 0.8) * 5.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float beamW = uBeamWidth * mix(1.0, 3.0, bassVal) * mix(1.0, 0.3, trebleVal);

  vec3 col = vec3(0.0);

  // Main sweeping beams from bottom center
  for (float i = 0.0; i < 16.0; i++) {
    if (i >= uBeamCount) break;

    float id = i / uBeamCount;
    float baseAngle = 3.14159 * 0.5 + (id - 0.5) * 3.14159 * uSweepRange;
    float sweep = sin(time * (0.5 + hash(i * 7.3) * 0.5) + i * 0.7) * 0.3;
    sweep += uBpmSin * 0.15 * uSensitivity;
    float angle = baseAngle + sweep;

    vec2 origin = vec2((id - 0.5) * 1.5, -1.0);
    float beam = laserBeam(p, origin, angle, beamW);

    vec3 lCol = laserColor(i, uPalette);
    float chromaBoost = 1.0;
    int noteIdx = int(mod(i * 3.0, 12.0));
    if (noteIdx == int(uChromaDominant)) chromaBoost = 2.0;

    col += lCol * beam * 0.6 * chromaBoost;
  }

  // Starburst on kick: beams from center
  if (kickVal > 0.1) {
    for (float i = 0.0; i < 12.0; i++) {
      float starAngle = i * 6.2832 / 12.0 + time * 0.1;
      float beam = laserBeam(p, vec2(0.0), starAngle, beamW * 0.5);
      vec3 starCol = laserColor(i + 5.0, uPalette);
      col += starCol * beam * kickVal * 0.8;
    }
  }

  // Atmospheric haze (volumetric scattering simulation)
  float haze = 0.0;
  for (float i = 0.0; i < 16.0; i++) {
    if (i >= uBeamCount) break;
    float id = i / uBeamCount;
    float baseAngle = 3.14159 * 0.5 + (id - 0.5) * 3.14159 * uSweepRange;
    float sweep = sin(time * (0.5 + hash(i * 7.3) * 0.5) + i * 0.7) * 0.3 + uBpmSin * 0.15 * uSensitivity;
    float angle = baseAngle + sweep;
    vec2 origin = vec2((id - 0.5) * 1.5, -1.0);
    float beam = laserBeam(p, origin, angle, beamW * 3.0);
    haze += beam * 0.15;
  }
  col += vec3(0.15, 0.15, 0.2) * haze * uHazeAmount;

  // Chaos: random beam flutter
  col += col * sin(time * 20.0 + length(p) * 10.0) * uChaos * 0.1;

  col *= 1.0 + uEnergy * uSensitivity * 0.5;
  col += vec3(0.1) * uOnset * uSensitivity;
  col *= 1.0 + uSpectralFlux * uSensitivity * 0.4;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridSpacing;
uniform float uScrollSpeed;
uniform float uLineGlow;
uniform float uHorizonHeight;

// Neon color palette
vec3 neonColor(float t, float paletteOffset) {
  vec3 pink = vec3(1.0, 0.1, 0.6);
  vec3 cyan = vec3(0.0, 0.9, 1.0);
  vec3 purple = vec3(0.6, 0.1, 1.0);

  float shifted = fract(t + paletteOffset * 0.33);
  float step1 = smoothstep(0.0, 0.5, shifted);
  float step2 = smoothstep(0.5, 1.0, shifted);

  vec3 c1 = mix(pink, cyan, step1);
  return mix(c1, purple, step2);
}

// Rainbow palette
vec3 rainbowColor(float t) {
  float pi2 = 6.28318;
  float r = 0.5 + 0.5 * cos(pi2 * (t + 0.0));
  float g = 0.5 + 0.5 * cos(pi2 * (t + 0.33));
  float b = 0.5 + 0.5 * cos(pi2 * (t + 0.67));
  return vec3(r, g, b);
}

// Bird SDF -- realistic bird silhouette with V-shaped wings and flapping
float birdSdf(float bx, float by, float wingAngle, float flapPhase) {
  float absBx = abs(bx);

  // --- Wing flapping: angle oscillates to create up/down stroke ---
  float flapAmt = sin(flapPhase) * 0.35;
  float effectiveAngle = wingAngle + flapAmt;

  // --- Wing shape: curved V with tapered tips ---
  // Primary wing line (upper edge of wing)
  float wingCurve = effectiveAngle * absBx + 0.08 * absBx * absBx; // slight curve
  float wingUpper = by - wingCurve;
  // Lower edge of wing (thinner toward tip)
  float wingThickness = 0.06 * (1.0 - absBx * 0.7); // tapers toward tip
  float wingLower = by - wingCurve + wingThickness;

  // Wing fill: between upper and lower edges
  float inWing = smoothstep(0.02, 0.0, wingUpper) * smoothstep(-0.02, 0.0, wingLower);
  // Wing span mask (fade at tips)
  float spanMask = smoothstep(1.1, 0.3, absBx);
  float wingGlow = inWing * spanMask;

  // Wing edge glow (visible outline)
  float upperEdge = smoothstep(0.04, 0.0, abs(wingUpper)) * spanMask;
  float lowerEdge = smoothstep(0.04, 0.0, abs(wingLower)) * spanMask * 0.6;

  // --- Body: elongated oval ---
  float bodyX = bx * 3.0; // stretch horizontally
  float bodyY = (by - 0.02) * 8.0; // narrow vertically, offset down slightly
  float bodyDist = bodyX * bodyX + bodyY * bodyY;
  float bodyGlow = smoothstep(0.5, 0.0, bodyDist);

  // --- Head: small circle at front ---
  float headX = (bx + 0.12) * 10.0; // offset forward
  float headY = (by + 0.01) * 10.0;
  float headDist = headX * headX + headY * headY;
  float headGlow = smoothstep(0.8, 0.0, headDist) * 0.8;

  // --- Tail: small V behind body ---
  float tailX = bx - 0.15;
  float tailAbsY = abs(by - 0.01);
  float tailLine = tailAbsY - abs(tailX) * 0.4;
  float tailGlow = smoothstep(0.03, 0.0, abs(tailLine))
                 * smoothstep(0.0, 0.05, tailX)
                 * smoothstep(0.2, 0.05, tailX) * 0.5;

  return clamp(wingGlow * 0.7 + upperEdge * 0.5 + lowerEdge * 0.3
             + bodyGlow + headGlow + tailGlow, 0.0, 1.0);
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio-reactive modulators
  float bassPulse = bass() * uSensitivity;
  float energyNeon = uEnergy * uSensitivity;
  float beatLurch = uBeat * uSensitivity;
  float trebleSparkle = treble() * uSensitivity;
  float beatRaw = uBeat * uSensitivity;

  float screenX = p.x - 0.5;
  float screenY = p.y;

  // Horizon line
  float horizon = uHorizonHeight;

  // --- Sky region ---
  float aboveHorizon = smoothstep(horizon, horizon + 0.01, screenY);

  float skyGrad = (screenY - horizon) * 2.0;
  float skyR = 0.02 + skyGrad * 0.03;
  float skyG = 0.0 + skyGrad * 0.01;
  float skyB = 0.06 + skyGrad * 0.08;

  // Horizon glow
  float horizDist = abs(screenY - horizon);
  float horizGlow = smoothstep(0.08, 0.0, horizDist) * 0.4 * uIntensity;
  vec3 horizCol = neonColor(0.0, uPalette);

  // --- Ground grid ---
  float belowHorizon = smoothstep(horizon, horizon - 0.01, screenY);

  float rawDepth = horizon - screenY;
  float safeDepth = clamp(rawDepth, 0.001, 1.0);

  float zScale = 0.5 * (uZoom * 2.0 + 0.5);
  float invDepth = clamp((1.0 - safeDepth) * 10.0, 0.1, 50.0);
  float zVal = zScale * invDepth;

  float gridX = screenX * zVal;

  float scroll = time * uScrollSpeed + beatLurch * 2.0;
  float gridY = zVal + scroll;

  float spacing = uGridSpacing * 1.0;

  // Grid lines
  float hLine = fract(gridY * spacing);
  float hDist = abs(hLine - 0.5) * 2.0;
  float hGlowWidth = uLineGlow * 0.15 + bassPulse * 0.1;
  float hGlow = smoothstep(hGlowWidth, 0.0, 1.0 - hDist);

  float vLine = fract(gridX * spacing);
  float vDist = abs(vLine - 0.5) * 2.0;
  float vGlowWidth = uLineGlow * 0.15 + bassPulse * 0.1;
  float vGlow = smoothstep(vGlowWidth, 0.0, 1.0 - vDist);

  float gridGlow = clamp(hGlow + vGlow, 0.0, 1.0);

  float intersection = hGlow * vGlow;
  float sparkle = intersection * (trebleSparkle * 3.0);

  float distanceFade = smoothstep(0.0, 0.3, safeDepth);

  float lineColorT = fract(gridX * 0.1 + gridY * 0.05 + time * 0.02);
  vec3 lineCol = neonColor(lineColorT, uPalette);

  float gridBright = uIntensity * 2.0 + energyNeon * 0.7 + bassPulse * 0.5;

  float gridR = lineCol.x * gridGlow * gridBright * distanceFade + sparkle * 1.0;
  float gridG = lineCol.y * gridGlow * gridBright * distanceFade + sparkle * 1.0;
  float gridB = lineCol.z * gridGlow * gridBright * distanceFade + sparkle * 1.0;

  float groundR = 0.01;
  float groundG = 0.0;
  float groundB = 0.03;

  float belowR = groundR + gridR;
  float belowG = groundG + gridG;
  float belowB = groundB + gridB;

  // --- Mountain silhouette ---
  float mountainX = screenX * 8.0 + uChaos * 2.0;
  float mountain = sin(mountainX * 1.0) * 0.02
    + sin(mountainX * 2.3 + 1.0) * 0.01
    + sin(mountainX * 4.7 + 2.0) * 0.005;
  float mountainLine = horizon + mountain;
  float mountainMask = smoothstep(mountainLine + 0.005, mountainLine, screenY);
  vec3 mountainCol = neonColor(0.5, uPalette);
  float mountainGlow = smoothstep(0.02, 0.0, abs(screenY - mountainLine))
    * 0.3 * uIntensity;

  // --- LASER GRID COMPOSITE ---
  float baseR = mix(belowR, skyR, aboveHorizon)
    + horizGlow * horizCol.x
    + mountainGlow * mountainCol.x * belowHorizon
    + mountainMask * 0.02;
  float baseG = mix(belowG, skyG, aboveHorizon)
    + horizGlow * horizCol.y
    + mountainGlow * mountainCol.y * belowHorizon;
  float baseB = mix(belowB, skyB, aboveHorizon)
    + horizGlow * horizCol.z
    + mountainGlow * mountainCol.z * belowHorizon
    + mountainMask * 0.01;

  // =====================================================
  // PSYCHEDELIC FLYING BIRDS
  // =====================================================
  float birdBeatScale = 1.0 + beatRaw * 0.3;

  // Bird 0 - medium speed flap
  float b0cx = sin(time * 0.3 + 0.0) * 0.35;
  float b0cy = 0.75 + sin(time * 0.2 + 0.5) * 0.1;
  float b0px = (screenX - b0cx) * (8.0 / birdBeatScale);
  float b0py = (screenY - b0cy) * (8.0 / birdBeatScale);
  float b0wing = 0.3;
  float b0flap = time * 4.5 + 0.0; // flap speed & phase
  float b0glow = birdSdf(b0px, b0py, b0wing, b0flap);
  vec3 b0col = rainbowColor(fract(time * 0.15 + 0.0));

  // Bird 1 - faster flap
  float b1cx = sin(time * 0.25 + 2.1) * 0.4;
  float b1cy = 0.8 + sin(time * 0.18 + 1.2) * 0.08;
  float b1px = (screenX - b1cx) * (9.0 / birdBeatScale);
  float b1py = (screenY - b1cy) * (9.0 / birdBeatScale);
  float b1wing = 0.25;
  float b1flap = time * 5.2 + 1.5; // different speed & phase
  float b1glow = birdSdf(b1px, b1py, b1wing, b1flap);
  vec3 b1col = rainbowColor(fract(time * 0.15 + 0.25));

  // Bird 2 - slower flap
  float b2cx = sin(time * 0.35 + 4.2) * 0.3;
  float b2cy = 0.7 + sin(time * 0.22 + 3.0) * 0.12;
  float b2px = (screenX - b2cx) * (10.0 / birdBeatScale);
  float b2py = (screenY - b2cy) * (10.0 / birdBeatScale);
  float b2wing = 0.35;
  float b2flap = time * 3.8 + 3.0; // different speed & phase
  float b2glow = birdSdf(b2px, b2py, b2wing, b2flap);
  vec3 b2col = rainbowColor(fract(time * 0.15 + 0.5));

  // Bird 3 - medium-slow flap
  float b3cx = sin(time * 0.28 + 5.8) * 0.45;
  float b3cy = 0.85 + sin(time * 0.15 + 4.5) * 0.06;
  float b3px = (screenX - b3cx) * (7.0 / birdBeatScale);
  float b3py = (screenY - b3cy) * (7.0 / birdBeatScale);
  float b3wing = 0.28;
  float b3flap = time * 4.0 + 5.0; // different speed & phase
  float b3glow = birdSdf(b3px, b3py, b3wing, b3flap);
  vec3 b3col = rainbowColor(fract(time * 0.15 + 0.75));

  float birdR = b0glow * b0col.x + b1glow * b1col.x + b2glow * b2col.x + b3glow * b3col.x;
  float birdG = b0glow * b0col.y + b1glow * b1col.y + b2glow * b2col.y + b3glow * b3col.y;
  float birdB = b0glow * b0col.z + b1glow * b1col.z + b2glow * b2col.z + b3glow * b3col.z;

  // =====================================================
  // SMILING SUN
  // =====================================================
  float sunCX = 0.0;
  float sunCY = 0.88;
  float sunBaseRadius = 0.07;
  float sunRadius = sunBaseRadius * (1.0 + beatRaw * 0.25);

  float sunDX = screenX - sunCX;
  float sunDY = screenY - sunCY;
  float sunDist = pow(sunDX * sunDX + sunDY * sunDY, 0.5);

  float sunBodyGlow = smoothstep(sunRadius + 0.02, sunRadius - 0.01, sunDist);

  // Sun rays
  float sunAngle = atan(sunDY, sunDX);
  float rayCount = 12.0;
  float rayAngle = fract(sunAngle * rayCount / 6.28318);
  float rayPattern = smoothstep(0.4, 0.2, abs(rayAngle - 0.5));

  float rayDistFromSurface = sunDist - sunRadius;
  float rayFalloff = smoothstep(0.25, 0.0, rayDistFromSurface)
    * smoothstep(0.0, 0.01, rayDistFromSurface);
  float rayGlowVal = rayPattern * rayFalloff * 0.7;

  float rayColorT = fract(sunAngle / 6.28318 + time * 0.1);
  vec3 rayCol = rainbowColor(rayColorT);

  float rayBeatBright = 0.6 + beatRaw * 0.4;

  // Eyes
  float eyeLDX = screenX - (sunCX - 0.022);
  float eyeLDY = screenY - (sunCY + 0.015);
  float eyeLDist = pow(eyeLDX * eyeLDX + eyeLDY * eyeLDY, 0.5);
  float eyeRadius = 0.01 * (1.0 + beatRaw * 0.15);
  float eyeLGlow = smoothstep(eyeRadius, eyeRadius - 0.005, eyeLDist);

  float eyeRDX = screenX - (sunCX + 0.022);
  float eyeRDY = screenY - (sunCY + 0.015);
  float eyeRDist = pow(eyeRDX * eyeRDX + eyeRDY * eyeRDY, 0.5);
  float eyeRGlow = smoothstep(eyeRadius, eyeRadius - 0.005, eyeRDist);

  // Smile
  float smileCY = sunCY - 0.005;
  float smileRadius = 0.035 * (1.0 + beatRaw * 0.15);
  float smileDX = screenX - sunCX;
  float smileDY = screenY - smileCY;
  float smileDist = pow(smileDX * smileDX + smileDY * smileDY, 0.5);
  float smileRingDist = abs(smileDist - smileRadius);
  float smileRingGlow = smoothstep(0.006, 0.0, smileRingDist);
  float smileBottomMask = smoothstep(smileCY, smileCY - 0.005, screenY);
  float smileGlow = smileRingGlow * smileBottomMask;

  vec3 sunYellow = vec3(1.0, 0.85, 0.1);
  vec3 sunOrange = vec3(1.0, 0.55, 0.05);
  vec3 sunFaceCol = mix(sunYellow, sunOrange, beatRaw * 0.5);

  float faceCutout = clamp(eyeLGlow + eyeRGlow + smileGlow, 0.0, 1.0);
  float sunFaceBright = sunBodyGlow * (1.0 - faceCutout * 0.85);

  float sunR = sunFaceBright * sunFaceCol.x * uIntensity
    + rayGlowVal * rayCol.x * rayBeatBright * uIntensity;
  float sunG = sunFaceBright * sunFaceCol.y * uIntensity
    + rayGlowVal * rayCol.y * rayBeatBright * uIntensity;
  float sunB = sunFaceBright * sunFaceCol.z * uIntensity
    + rayGlowVal * rayCol.z * rayBeatBright * uIntensity;

  // =====================================================
  // FINAL COMPOSITE
  // =====================================================
  float finalR = baseR + birdR * uIntensity + sunR;
  float finalG = baseG + birdG * uIntensity + sunG;
  float finalB = baseB + birdB * uIntensity + sunB;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCrustThickness;
uniform float uEruptionForce;
uniform float uEmberDensity;
uniform float uFlowDirection;

// Hash functions
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

vec2 hash22(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

// Value noise
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM with rotation per octave for richer patterns
float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) {
    val += amp * vnoise(p * freq);
    p = rot * p;
    freq *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Domain-warped FBM for organic flow
float warpedFbm(vec2 p, float t) {
  vec2 q = vec2(fbm(p + vec2(t * 0.1, t * 0.05)),
                fbm(p + vec2(5.2, 1.3) + vec2(t * 0.08, -t * 0.06)));
  vec2 r = vec2(fbm(p + q * 4.0 + vec2(1.7, 9.2) + vec2(t * 0.05)),
                fbm(p + q * 4.0 + vec2(8.3, 2.8) + vec2(-t * 0.04)));
  return fbm(p + r * 2.0);
}

// Lava heat gradient: black crust -> deep red -> orange -> yellow -> white-hot
vec3 heatGradient(float heat, float paletteShift) {
  float h = clamp(heat, 0.0, 1.0);
  vec3 black = vec3(0.015, 0.005, 0.005);
  vec3 darkRed = vec3(0.4, 0.02, 0.0);
  vec3 red = vec3(0.8, 0.1, 0.0);
  vec3 orange = vec3(1.0, 0.55 + paletteShift * 0.12, 0.08);
  vec3 yellow = vec3(1.0, 0.9, 0.28);
  vec3 white = vec3(1.0, 0.97, 0.85);

  vec3 c = black;
  c = mix(c, darkRed, smoothstep(0.0, 0.15, h));
  c = mix(c, red, smoothstep(0.15, 0.3, h));
  c = mix(c, orange, smoothstep(0.3, 0.5, h));
  c = mix(c, yellow, smoothstep(0.5, 0.75, h));
  c = mix(c, white, smoothstep(0.75, 0.95, h));
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.9;

  // Audio modulators
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Flow direction vector
  float flowAngle = uFlowDirection * 6.2832;
  vec2 flowDir = vec2(cos(flowAngle), sin(flowAngle));

  // Apply flow motion to coordinate space
  vec2 flowP = p + flowDir * time * 0.3;

  // Domain-warped lava surface — multiple layers
  float lava1 = warpedFbm(flowP * 2.0, time * 0.8);
  float lava2 = warpedFbm(flowP * 3.5 + vec2(10.0), time * 0.6);
  float lava3 = fbm(flowP * 8.0 + vec2(time * 0.15, -time * 0.1));

  // Crack pattern: sharp edges from noise thresholding
  float crackNoise = warpedFbm(flowP * 4.0 + vec2(20.0, 5.0), time * 0.5);
  float crackPattern = abs(crackNoise - 0.5) * 2.0;
  crackPattern = pow(crackPattern, 1.5 + uCrustThickness * 2.0);

  // Mids widen cracks (reduce crust thickness dynamically)
  float dynamicCrust = uCrustThickness * (1.0 - midsVal * 0.3);
  float crackMask = 1.0 - smoothstep(0.0, 0.1 + dynamicCrust * 0.3, crackPattern);

  // Lava glow visible through cracks
  float lavaHeat = lava1 * 0.5 + lava2 * 0.3 + lava3 * 0.2;
  lavaHeat = lavaHeat * crackMask;

  // Bass eruption surges — pulses of heat
  float eruptionWave = sin(length(p) * 3.0 - time * 2.0 - bassVal * 5.0) * 0.5 + 0.5;
  float eruption = bassVal * uEruptionForce * eruptionWave * 0.75;
  lavaHeat += eruption * crackMask;

  // Kick: volcanic geyser — localized heat burst
  vec2 geyserPos = vec2(sin(time * 0.7) * 0.3, cos(time * 0.5) * 0.3);
  float geyserDist = length(p - geyserPos);
  float geyser = kickVal * uEruptionForce * exp(-geyserDist * geyserDist * 8.0) * 1.5;
  lavaHeat += geyser;

  // Beat: global heat pulse
  lavaHeat += beatPulse * 0.15;

  // Surface cooling — dark crust with subtle texture
  float crustTex = fbm(flowP * 12.0 + vec2(30.0)) * 0.3;
  float crustSurface = (1.0 - crackMask) * (0.02 + crustTex * 0.03);

  // Ambient glow bleeding through thin crust
  float ambientGlow = lava1 * 0.15 * (1.0 - uCrustThickness * 0.8);

  // Final heat value
  float heat = clamp(lavaHeat + crustSurface + ambientGlow, 0.0, 1.0);

  // Color from heat gradient
  vec3 col = heatGradient(heat, uPalette);

  // === EMBER PARTICLES ===
  float emberCount = 60.0 + uEmberDensity * 40.0;
  float emberAccum = 0.0;
  vec3 emberColor = vec3(0.0);

  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float seed = hash21(vec2(fi * 7.3, fi * 13.1));
    float emberTime = time * (1.5 + seed * 2.0);

    // Ember position — rises from lava surface
    vec2 emberOrigin = vec2(
      sin(seed * 50.0 + time * 0.3) * 0.8,
      -0.5 + mod(emberTime * 0.3, 2.0) - 0.5
    );
    // Wobble sideways
    emberOrigin.x += sin(emberTime * 2.0 + seed * 20.0) * 0.1;

    float emberDist = length(p - emberOrigin);
    float emberSize = 0.005 + seed * 0.008;
    float ember = smoothstep(emberSize, 0.0, emberDist);

    // Ember brightness — fades as it rises
    float riseFade = 1.0 - smoothstep(0.0, 1.5, mod(emberTime * 0.3, 2.0));
    ember *= riseFade * (0.5 + trebleVal * 1.5);

    // Treble burst: more embers visible
    ember *= step(1.0 - uEmberDensity - trebleVal * 0.3, seed);

    emberAccum += ember;
    float emberHue = 0.8 + seed * 0.15;
