  }

  col += emberColor;

  // === HEAT SHIMMER above the lava ===
  float shimmerNoise = vnoise(p * 20.0 + vec2(time * 3.0, time * 2.0));
  float shimmer = shimmerNoise * 0.03 * heat;
  col += vec3(shimmer * 0.8, shimmer * 0.3, shimmer * 0.05);

  // Onset: bright volcanic flash
  col += vec3(1.0, 0.7, 0.3) * onsetVal * 0.2;

