uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBlobCount;
uniform float uViscosity;
uniform float uGlossiness;

#define PI 3.14159265
#define TAU 6.28318530

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

// Smooth metaball potential
float metaball(vec2 p, vec2 center, float radius) {
  float d = length(p - center);
  return radius * radius / (d * d + 0.001);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.45) * 0.07;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.3;

  // Lamp container shape
  float lampX = abs(p.x);
  float lampShape = smoothstep(0.85, 0.8, lampX + abs(p.y) * 0.1);

  vec3 col = vec3(0.02, 0.01, 0.03);

  // Generate metaballs
  int numBlobs = 5 + int(uBlobCount * 8.0);
  float potential = 0.0;
  vec3 blobColor = vec3(0.0);
  float totalWeight = 0.0;

  float visc = 0.3 + uViscosity * 0.5 + uWarmth * uSensitivity * 0.2;

  for (int i = 0; i < 13; i++) {
    if (i >= numBlobs) break;
    float fi = float(i);
    float seed = fi * 1.618;

    // Blob position: rise and fall with bass
    float phase = hash(seed) * TAU;
    float yBase = sin(time * (0.2 + hash(seed + 1.0) * 0.3) + phase);
    float xBase = sin(time * (0.15 + hash(seed + 2.0) * 0.2) + phase * 1.3);

    // Bass pushes blobs upward
    yBase += bassVal * 0.45;

    vec2 blobPos = vec2(
      xBase * 0.5 * (1.0 - abs(yBase) * 0.3),
      yBase * 0.8
    );

    // Kick splits: shift positions on kick
    float kickSplit = uKick * uSensitivity * 0.15;
    blobPos += vec2(hash(seed + 3.0) - 0.5, hash(seed + 4.0) - 0.5) * kickSplit;

    float radius = 0.08 + hash(seed + 5.0) * 0.06;
    radius *= visc;
    radius += bassVal * 0.02;

    float mb = metaball(p, blobPos, radius);
    potential += mb;

    // Color per blob: neon pink / electric blue / lime green
    float colorPhase = mod(fi * 0.333 + uPalette * 0.5 + time * 0.05, 1.0);
    vec3 c;
    if (colorPhase < 0.33) {
      c = mix(vec3(1.0, 0.1, 0.6), vec3(0.0, 0.5, 1.0), colorPhase * 3.0);
    } else if (colorPhase < 0.66) {
      c = mix(vec3(0.0, 0.5, 1.0), vec3(0.2, 1.0, 0.3), (colorPhase - 0.33) * 3.0);
    } else {
      c = mix(vec3(0.2, 1.0, 0.3), vec3(1.0, 0.1, 0.6), (colorPhase - 0.66) * 3.0);
    }

    // Spectrum reactivity per blob
    float specIdx = mod(fi, 8.0);
    float specVal = 0.0;
    if (specIdx < 1.0) specVal = uSpectrum0;
    else if (specIdx < 2.0) specVal = uSpectrum1;
    else if (specIdx < 3.0) specVal = uSpectrum2;
    else if (specIdx < 4.0) specVal = uSpectrum3;
    else if (specIdx < 5.0) specVal = uSpectrum4;
    else if (specIdx < 6.0) specVal = uSpectrum5;
    else if (specIdx < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    c *= 0.6 + specVal * uSensitivity * 0.6;
    blobColor += c * mb;
    totalWeight += mb;
