  float threshold = 1.0;
  float blobMask = smoothstep(threshold - 0.1, threshold + 0.1, potential);

  if (totalWeight > 0.001) {
    blobColor /= totalWeight;
  }

  // Glossy surface
  float glossy = 0.0;
  if (blobMask > 0.1) {
    // Fake specular from gradient
    float dx = metaball(p + vec2(0.01, 0.0), vec2(0.0), 0.1) - potential;
    float dy = metaball(p + vec2(0.0, 0.01), vec2(0.0), 0.1) - potential;
    vec2 grad = normalize(vec2(dx, dy) + 0.001);
    float spec = pow(max(dot(grad, vec2(0.5, 0.8)), 0.0), 8.0 + uGlossiness * 20.0);
    glossy = spec * uGlossiness;
  }

  col = mix(col, blobColor, blobMask);
  col += vec3(1.0, 0.95, 0.9) * glossy * blobMask * 0.5;

  // Edge glow at blob boundary
  float edgeGlow = smoothstep(threshold + 0.3, threshold, potential) * smoothstep(threshold - 0.3, threshold, potential);
  col += blobColor * edgeGlow * 0.3;

  // Apply lamp container
  col *= lampShape;

  // Lamp glass tint
  col += vec3(0.02, 0.01, 0.03) * (1.0 - lampShape);

  // Beat pulse
  col += blobColor * uBeat * uSensitivity * 0.1 * blobMask;

  // Onset flash
  col += vec3(0.15, 0.1, 0.15) * uOnset * uSensitivity * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

