uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Neon palette for blobs
vec3 neonColor(float idx, float time, float palette) {
  float hue = fract(idx * 0.125 + palette * 0.3 + time * 0.02);
  vec3 c = vec3(hue, 0.95, 1.0);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

// Blob position with organic sinusoidal motion — full screen coverage
vec2 blobPos(float idx, float time, float chaos) {
  float phase = idx * 0.7854;
  float speed1 = 0.3 + idx * 0.05;
  float speed2 = 0.2 + idx * 0.07;
  float radius1 = 0.9 + chaos * 0.4 + sin(time * 0.1 + idx) * 0.3;
  float radius2 = 0.8 + chaos * 0.3 + cos(time * 0.13 + idx) * 0.25;
  return vec2(
    sin(time * speed1 + phase) * radius1 + sin(time * speed2 * 0.7 + phase * 2.3) * 0.3,
    cos(time * speed2 + phase * 1.3) * radius2 + cos(time * speed1 * 0.6 + phase * 1.7) * 0.3
  );
}

// Blob radius with pulsing — larger blobs to fill screen
float blobRadius(float idx, float time, float bassVal) {
  float baseRadius = 0.4 + idx * 0.03;
  float pulse = sin(time * 2.0 + idx * 1.5) * 0.08;
  float bassPulse = bassVal * 0.2;
  return baseRadius + pulse + bassPulse;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float breathe = 1.0 + sin(uTime * 0.4) * 0.08;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;

  // Compute metaball field
  float totalField = 0.0;
  vec3 weightedColor = vec3(0.0);
  float totalWeight = 0.0;

  // 8 metaball blobs
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    vec2 bPos = blobPos(fi, time, uChaos);
    float bRad = blobRadius(fi, time, bassVal);

    // Inflate with bass
    bRad *= 1.0 + bassVal * 0.45;

    vec2 diff = p - bPos;
    float dist2 = dot(diff, diff);
    float field = bRad * bRad / (dist2 + 0.01);

    totalField += field;

    // Weighted color contribution
    float weight = field * field;
    vec3 bColor = neonColor(fi, time, uPalette);

    // Audio-reactive color modulation per blob
    bColor += vec3(0.2, 0.1, 0.3) * uKick * uSensitivity * (mod(fi, 3.0) / 3.0);
    bColor += vec3(trebleVal * 0.2) * (1.0 - mod(fi, 2.0));

    weightedColor += bColor * weight;
    totalWeight += weight;
  }

  // Normalize weighted color
  vec3 col = weightedColor / (totalWeight + 0.001);

  // Metaball threshold with smooth edges
  float threshold = 0.8;
  float edge = smoothstep(threshold - 0.3, threshold + 0.1, totalField);
  float innerGlow = smoothstep(threshold, threshold + 2.0, totalField);

  // Surface color
  vec3 surfaceCol = col * edge;

  // Inner glow (brighter in center of blobs)
  surfaceCol += col * innerGlow * 0.5;

  // Edge highlight (treble shimmer)
  float edgeHighlight = smoothstep(0.05, 0.0, abs(totalField - threshold)) * trebleVal * 3.0;
  surfaceCol += vec3(1.0) * edgeHighlight;

  // Background glow
  vec3 bgGlow = col * 0.05 * totalField * 0.3;
  surfaceCol += bgGlow;

  // Lava internal flow patterns
  float flowPattern = sin(p.x * 5.0 + time * 2.0 + totalField * 3.0)
                    * cos(p.y * 4.0 - time * 1.5 + totalField * 2.0);
  surfaceCol += col * flowPattern * 0.1 * innerGlow;

  // Specular highlights
  float specular = pow(max(0.0, sin(totalField * 10.0 + time)), 8.0) * innerGlow;
  surfaceCol += vec3(1.0, 0.95, 0.9) * specular * 0.3;

  // BPM breathing
  surfaceCol *= 1.0 + uBpmSin * 0.12 * uSensitivity;

  // Spectral flux energy bursts
  surfaceCol += col * uSpectralFlux * uSensitivity * 0.3 * edge;

  // Harmonicity warms the palette
  surfaceCol = mix(surfaceCol, surfaceCol * vec3(1.2, 1.0, 0.8), uHarmonicity * uSensitivity * 0.3);

  // Onset flash
  surfaceCol += vec3(0.4, 0.3, 0.5) * uOnset * uSensitivity * 0.5;

  // Warmth tinting
  surfaceCol = mix(surfaceCol, surfaceCol * vec3(1.15, 1.0, 0.85), uWarmth * uSensitivity * 0.2);

  surfaceCol *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  surfaceCol = psychedelicColor(surfaceCol);
  gl_FragColor = vec4(clamp(surfaceCol, 0.0, 1.0), 1.0);
}

