uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uStreakLength;
uniform float uGhostCount;
uniform float uAberration;
uniform float uFlareSize;

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.0);

  // Audio-reactive modulators
  float bassBright = bass() * uSensitivity * 0.6;
  float midsPos = mids() * uSensitivity * 0.2;
  float onsetFlare = uOnset * uSensitivity * 2.0;

  // Flare source drifts slowly
  float srcX = sin(time * 0.1) * 0.15 + midsPos * 0.1;
  float srcY = cos(time * 0.08) * 0.05;

  // Position relative to flare source
  float fx = p.x - srcX;
  float fy = p.y - srcY;

  // === HORIZONTAL STREAK — extends across entire screen ===
  float streakFalloffY = smoothstep(0.02, 0.0, abs(fy));
  float streakFalloffX = smoothstep(uStreakLength * 3.0, 0.0, abs(fx));
  float streak = streakFalloffY * streakFalloffX * 0.8;

  // Streak is anamorphic: wider in x, tighter in y — full screen width
  float wideStreak = smoothstep(0.08, 0.0, abs(fy));
  float wideStreakX = smoothstep(uStreakLength * 5.0, 0.0, abs(fx));
  float streakWide = wideStreak * wideStreakX * 0.3;

  // === GHOST CIRCLES — larger and spread wider ===
  // Ghost 1: close to source, warm, larger
  float g1x = fx * 0.3;
  float g1y = fy * 0.3;
  float g1d = g1x * g1x + g1y * g1y;
  float ghost1 = smoothstep(uFlareSize * 0.15, 0.0, g1d);

  // Ghost 2: opposite side, cool, expanded
  float g2x = fx * -0.6 + 0.15;
  float g2y = fy * -0.6;
  float g2d = g2x * g2x + g2y * g2y;
  float ghost2 = smoothstep(uFlareSize * 0.12, 0.0, g2d);

  // Ghost 3: further out, ring, wider
  float g3x = fx * -1.0 + 0.05;
  float g3y = fy * -1.0;
  float g3d = g3x * g3x + g3y * g3y;
  float ghost3Ring = smoothstep(uFlareSize * 0.1, uFlareSize * 0.06, g3d);
  float ghost3 = ghost3Ring * (1.0 - smoothstep(uFlareSize * 0.1, uFlareSize * 0.14, g3d));

  // Ghost 4: small, bright
  float g4x = fx * 0.8 - 0.12;
  float g4y = fy * 0.8;
  float g4d = g4x * g4x + g4y * g4y;
  float ghost4 = smoothstep(uFlareSize * 0.06, 0.0, g4d);

  // Ghost 5: large, faint, covers wide area
  float g5x = fx * -1.5;
  float g5y = fy * -1.5;
  float g5d = g5x * g5x + g5y * g5y;
  float ghost5 = smoothstep(uFlareSize * 0.25, 0.0, g5d) * 0.4;

  // Ghost 6: very far out, large halo
  float g6x = fx * 1.8 + 0.1;
  float g6y = fy * 1.8;
  float g6d = g6x * g6x + g6y * g6y;
  float ghost6 = smoothstep(uFlareSize * 0.2, 0.0, g6d) * 0.3;

  // Ghost 7: ring ghost at edge of screen
  float g7x = fx * -2.0;
  float g7y = fy * -2.0;
  float g7d = g7x * g7x + g7y * g7y;
  float ghost7Ring = smoothstep(uFlareSize * 0.15, uFlareSize * 0.1, g7d);
  float ghost7 = ghost7Ring * (1.0 - smoothstep(uFlareSize * 0.15, uFlareSize * 0.2, g7d)) * 0.25;

  // === CHROMATIC ABERRATION ===
  float aberStr = uAberration * 0.03;

  // Red channel: shift right
  float streakR = smoothstep(0.02, 0.0, abs(fy - aberStr));
  float rStreak = streakR * streakFalloffX;

  // Blue channel: shift left
  float streakB = smoothstep(0.02, 0.0, abs(fy + aberStr));
  float bStreak = streakB * streakFalloffX;

  // === RADIAL LIGHT RAYS — extend across full screen ===
  float rayAngle = atan(fy, fx);
  float rayPattern = pow(abs(sin(rayAngle * 8.0 + time * 0.5)), 12.0);
  float rayFalloff = exp(-sqrt(fx * fx + fy * fy) * 0.8);
  float rays = rayPattern * rayFalloff * 0.2 * (1.0 + bassBright);

  // === AMBIENT HAZE — soft screen-filling glow ===
  float hazeDist = fx * fx * 0.5 + fy * fy * 2.0;
  float haze = exp(-hazeDist * 1.5) * 0.15;

  // === CENTRAL CORE ===
  float coreDist = fx * fx + fy * fy;
  float core = smoothstep(0.02, 0.0, coreDist) * 1.5;

  // === COMBINE ===
  float brightness = uIntensity * 1.3 + bassBright * 0.5 + onsetFlare * 0.3;

  // Warm ghost colors
  float ghostWarm = (ghost1 + ghost4 + ghost6) * brightness;
  float ghostCool = (ghost2 + ghost5 + ghost7) * brightness;
  float ghostMid = ghost3 * brightness;

  // Palette-shifted hue for variety
  float hueOff = uPalette * 0.1 + time * 0.02;

  float finalR = (streak * 0.9 + rStreak * 0.3 + streakWide * 0.8
    + core + ghostWarm * 1.0 + ghostCool * 0.3 + ghostMid * 0.7
    + rays * 1.0 + haze * 0.9)
    * brightness + sin(hueOff) * 0.05;

  float finalG = (streak * 0.85 + streakWide * 0.7
    + core * 0.9 + ghostWarm * 0.6 + ghostCool * 0.5 + ghostMid * 0.9
    + rays * 0.8 + haze * 0.85)
    * brightness + cos(hueOff) * 0.05;

  float finalB = (streak * 0.7 + bStreak * 0.3 + streakWide * 0.9
    + core * 0.8 + ghostWarm * 0.3 + ghostCool * 1.0 + ghostMid * 0.5
    + rays * 0.9 + haze * 1.0)
    * brightness;

  // Beat pulse
  float beatPulse = uBeat * uSensitivity * 0.1 * (streak + core);

  // Chaos: flicker
  float flicker = sin(time * 12.0 + uChaos * 8.0) * uChaos * 0.03;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR + beatPulse + flicker, 0.0, 1.0),
    clamp(finalG + beatPulse + flicker, 0.0, 1.0),
    clamp(finalB + beatPulse + flicker, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
