__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uStringCount;
uniform float uResonance;
uniform float uPluckDecay;
uniform float uHarmonicBlend;

vec3 harpPalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.15, 0.3)));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numStrings = min(uStringCount, 32.0);
  vec3 color = vec3(0.0);

  // Each string is a vertical line that vibrates horizontally
  for (float i = 0.0; i < 32.0; i += 1.0) {
    if (i >= numStrings) break;

    float frac = i / numStrings;
    float stringX = (frac - 0.5) * 2.2;

    // Natural frequency increases with string index (like harp strings)
    float natFreq = 0.8 + i * 0.15;

    // Standing wave: fundamental + harmonics
    float yNorm = p.y * 3.14159;
    float fundamental = sin(yNorm) * sin(time * natFreq + onsetVal * 3.0 * sin(i * 0.7));
    float harmonic2 = sin(yNorm * 2.0) * sin(time * natFreq * 2.0) * uHarmonicBlend;
    float harmonic3 = sin(yNorm * 3.0) * sin(time * natFreq * 3.0) * uHarmonicBlend * 0.5;

    // Combined vibration amplitude
    float vibration = fundamental + harmonic2 + harmonic3;

    // Audio drives amplitude: bass for low strings, treble for high strings
    float audioAmp = mix(bassVal, trebleVal, frac) * 0.15 + midsVal * 0.08;
    audioAmp += onsetVal * exp(-i * uPluckDecay * 0.1) * 0.2;

    // Resonance feedback
    float resonanceAmp = uResonance * sin(time * natFreq * 0.5 + i) * 0.05;

    float totalAmp = (audioAmp + resonanceAmp + 0.02);
    float displacement = vibration * totalAmp;

    // Distance from pixel to displaced string
    float dist = abs(p.x - stringX - displacement);

    // Soft glow falloff
    float glow = exp(-dist * 25.0);

    // String core (brighter, thinner)
    float core = exp(-dist * 80.0);

    // Vibration trails (ghosting effect)
    float trail = 0.0;
    for (float t = 1.0; t < 5.0; t += 1.0) {
      float trailTime = time - t * 0.03;
      float trailVib = sin(yNorm) * sin(trailTime * natFreq) * totalAmp;
      float trailDist = abs(p.x - stringX - trailVib);
      trail += exp(-trailDist * 20.0) * exp(-t * 0.6);
    }

    // Color per string
    float hue = frac + uPalette * 0.1 + time * 0.015;
    vec3 stringColor = harpPalette(hue, uPalette * 0.05);

    // Chaos shifts hue randomly per string
    stringColor = mix(stringColor, stringColor.brg, uChaos * sin(i * 2.3 + time * 0.2) * 0.3);

    float brightness = core * 2.0 + glow * 0.6 + trail * uResonance * 0.4;
    color += stringColor * brightness;
  }

  // Moire pattern from string interference
  float moire = 0.0;
  for (float i = 0.0; i < 32.0; i += 1.0) {
    if (i >= numStrings) break;
    float freq = 0.8 + i * 0.15;
    moire += sin(p.x * 12.0 + time * freq * 0.5 + p.y * 5.0);
  }
  moire /= numStrings;
  moire = moire * 0.5 + 0.5;
  vec3 moireColor = harpPalette(moire + time * 0.01, uPalette * 0.1 + 0.2);
  color += moireColor * moire * 0.05;

  // Treble sparkle
  float sparkle = sin(p.x * 50.0 + time * 6.0) * sin(p.y * 50.0 - time * 5.0);
  sparkle = pow(max(sparkle, 0.0), 20.0);
  color += vec3(sparkle * trebleVal * 0.25);

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.04);

  // Kick punch
  color = mix(color, color * 1.4, kickVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.1));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

