uniform float uThreadDensity;
uniform float uWeaveShift;
uniform float uThreadGlow;
uniform float uCrossFade;

vec3 loomPalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.1, 0.25)));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.2;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  vec3 color = vec3(0.0);
  float density = uThreadDensity;

  // === HORIZONTAL THREADS (warp) ===
  vec3 warpColor = vec3(0.0);
  float warpBright = 0.0;

  for (float i = 0.0; i < 20.0; i += 1.0) {
    if (i >= density) break;

    float frac = i / density;
    float threadY = (frac - 0.5) * 2.5;

    // Wave displacement along the thread
    float wave = sin(p.x * 4.0 + time * 0.8 + i * 0.7) * 0.03 * (1.0 + bassVal * 0.5);
    wave += sin(p.x * 8.0 - time * 0.5 + i * 1.3) * 0.015 * uWeaveShift;

    // Audio-driven undulation
    wave += midsVal * sin(p.x * 3.0 + i * 2.0) * 0.02;

    float dist = abs(p.y - threadY - wave);
    float glow = exp(-dist * 20.0 / uThreadGlow);
    float core = exp(-dist * 60.0);

    // Determine over/under at crossings
    float crossPhase = floor(p.x * density * 0.5 + time * uWeaveShift * 0.2 + i * 0.5);
    float isOver = step(0.5, fract(crossPhase * 0.5 + frac));

    float threadBrightness = (core * 1.5 + glow * 0.5) * mix(1.0, isOver, uCrossFade);

    float hue = frac * 0.5 + uPalette * 0.1 + time * 0.01;
    vec3 tColor = loomPalette(hue, uPalette * 0.05);
    tColor = mix(tColor, tColor.brg, uChaos * sin(i * 3.1 + time * 0.2) * 0.2);

    warpColor += tColor * threadBrightness;
    warpBright += threadBrightness;
  }

  // === VERTICAL THREADS (weft) ===
  vec3 weftColor = vec3(0.0);
  float weftBright = 0.0;

  for (float i = 0.0; i < 20.0; i += 1.0) {
    if (i >= density) break;

    float frac = i / density;
    float threadX = (frac - 0.5) * 2.5;

    // Wave displacement
    float wave = sin(p.y * 4.0 + time * 0.7 + i * 0.9) * 0.03 * (1.0 + midsVal * 0.5);
    wave += sin(p.y * 7.0 + time * 0.4 + i * 1.1) * 0.015 * uWeaveShift;

    // Audio-driven undulation
    wave += bassVal * sin(p.y * 2.5 + i * 1.8) * 0.02;

    float dist = abs(p.x - threadX - wave);
    float glow = exp(-dist * 20.0 / uThreadGlow);
    float core = exp(-dist * 60.0);

    // Over/under is complement of warp
    float crossPhase = floor(p.y * density * 0.5 + time * uWeaveShift * 0.2 + i * 0.5);
    float isOver = step(0.5, fract(crossPhase * 0.5 + frac + 0.5));

    float threadBrightness = (core * 1.5 + glow * 0.5) * mix(1.0, isOver, uCrossFade);

    float hue = frac * 0.5 + 0.3 + uPalette * 0.1 + time * 0.01;
    vec3 tColor = loomPalette(hue, uPalette * 0.05 + 0.15);
    tColor = mix(tColor, tColor.gbr, uChaos * sin(i * 2.7 + time * 0.15) * 0.2);

    weftColor += tColor * threadBrightness;
    weftBright += threadBrightness;
  }

  // Combine warp and weft
  color = warpColor + weftColor;

  // Moire interference at crossings
  float moireH = sin(p.y * density * 3.14159 + time * 0.3);
  float moireV = sin(p.x * density * 3.14159 + time * 0.25);
  float moire = moireH * moireV * 0.5 + 0.5;
  vec3 moireColor = loomPalette(moire + time * 0.02, uPalette * 0.1 + 0.3);
  color += moireColor * moire * 0.04;

  // Crossing nodes glow brighter
  float nodeGlowH = 0.0;
  float nodeGlowV = 0.0;
  for (float i = 0.0; i < 20.0; i += 1.0) {
    if (i >= density) break;
    float frac = i / density;
    nodeGlowH += exp(-abs(p.y - (frac - 0.5) * 2.5) * 15.0);
    nodeGlowV += exp(-abs(p.x - (frac - 0.5) * 2.5) * 15.0);
  }
  float nodeGlow = nodeGlowH * nodeGlowV * 0.02;
  color += vec3(nodeGlow) * onsetVal * 0.5;

  // Treble sparkle
  float sparkle = sin(p.x * 55.0 + time * 6.0) * sin(p.y * 55.0 - time * 5.0);
  sparkle = pow(max(sparkle, 0.0), 22.0);
  color += vec3(sparkle * trebleVal * 0.2);

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.04);

  // Kick punch
  color = mix(color, color * 1.4, kickVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.1));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Hash for pseudo-random values
float hashVal(float n) {
  return fract(sin(n) * 43758.5453123);
}

float hashVal2(vec2 uv) {
  return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453);
}

// Procedural glyph: cross shape
float glyphCross(vec2 uv) {
  float h = step(abs(uv.x), 0.12) * step(abs(uv.y), 0.4);
  float v = step(abs(uv.y), 0.12) * step(abs(uv.x), 0.4);
  return max(h, v);
}

// Procedural glyph: circle
float glyphCircle(vec2 uv) {
  float r = length(uv);
  return smoothstep(0.35, 0.3, r) - smoothstep(0.25, 0.2, r);
}

// Procedural glyph: square outline
float glyphSquare(vec2 uv) {
  vec2 a = abs(uv);
  float outer = step(a.x, 0.35) * step(a.y, 0.35);
  float inner = step(a.x, 0.25) * step(a.y, 0.25);
  return outer - inner;
}

// Procedural glyph: triangle
float glyphTriangle(vec2 uv) {
  uv.y += 0.15;
  float triBody = step(uv.y, 0.3) * step(-0.2, uv.y);
  float slopeVal = (uv.y + 0.2) * 0.7;
  float triShape = step(abs(uv.x), slopeVal) * triBody;
  float innerSlope = (uv.y + 0.2) * 0.5;
  float innerTri = step(abs(uv.x), innerSlope) * step(uv.y, 0.2) * step(-0.1, uv.y);
  return triShape - innerTri * 0.7;
}

// Select glyph by type
float renderGlyph(vec2 uv, float glyphType) {
  if (glyphType < 0.25) return glyphCross(uv);
  if (glyphType < 0.5) return glyphCircle(uv);
  if (glyphType < 0.75) return glyphSquare(uv);
  return glyphTriangle(uv);
}

// Rainbow column color
vec3 columnColor(float colIdx, float time, float palette) {
  float hue = fract(colIdx * 0.0618 + palette * 0.3 + time * 0.01);
  vec3 c = vec3(hue, 0.9, 1.0);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;

  // Bass distortion warps columns
  p.x += sin(p.y * 3.0 + time) * bassVal * 0.15;
  p.x += sin(p.y * 7.0 + time * 2.0) * uChaos * 0.05;

  // Grid parameters
  float numColumns = 20.0 + uChaos * 10.0;
  float cellWidth = 3.0 / numColumns;
  float cellHeight = cellWidth * 1.2;

  vec3 col = vec3(0.0);

  // Process each column
  float columnIdx = floor((p.x + 1.5) / cellWidth);

  // Multiple nearby columns for coverage
  for (int ci = -1; ci <= 1; ci++) {
    float cIdx = columnIdx + float(ci);
    float cX = (cIdx + 0.5) * cellWidth - 1.5;

    // Column properties
    float colSeed = hashVal(cIdx * 17.31);
    float fallSpeed = 1.0 + colSeed * 2.0 + midsVal * 1.5;
    float streamLen = 8.0 + hashVal(cIdx * 23.17) * 12.0;
    float startOffset = hashVal(cIdx * 7.93) * 20.0;

    // Fall position
    float fallPos = fract((time * fallSpeed * 0.2 + startOffset) * 0.1) * 20.0 - 10.0;

    // Process cells in this column
    for (int ri = -6; ri <= 6; ri++) {
      float rowY = fallPos + float(ri) * cellHeight;
      vec2 cellCenter = vec2(cX, rowY);
      vec2 localUV = (p - cellCenter) / cellHeight;

      if (abs(localUV.x) > 0.5 || abs(localUV.y) > 0.5) continue;

      // Glyph type per cell
      float glyphSeed = hashVal2(vec2(cIdx, float(ri) + floor(time * fallSpeed * 0.02)));
      float glyphType = fract(glyphSeed * 4.0);

      // Render glyph
      float glyph = renderGlyph(localUV, glyphType);

      // Stream position (0 = head, 1 = tail)
      float streamPos = float(ri + 6) / streamLen;
      streamPos = clamp(streamPos, 0.0, 1.0);

      // Head brightness (leading character is brightest)
      float headBright = exp(-streamPos * 3.0);
      float tailFade = 1.0 - streamPos;

      float brightness = glyph * headBright * tailFade;

      // Column color
      vec3 cCol = columnColor(cIdx, time, uPalette);

      // Head is white-hot
      vec3 glyphCol = mix(cCol, vec3(1.0), headBright * 0.7);

      // Treble brightens glyphs
      glyphCol += vec3(trebleVal * 0.3) * headBright;

      col += glyphCol * brightness * 0.5;
    }
  }

  // Background fog
  float fogDensity = 0.03 + bassVal * 0.02;
  vec3 fogColor = columnColor(floor(p.x / cellWidth), time, uPalette) * fogDensity;
  col += fogColor;

  // Scanline effect
  float scanline = sin(vUv.y * 800.0) * 0.03;
  col -= vec3(scanline);

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Kick flash
  col += vec3(0.1, 0.15, 0.2) * uKick * uSensitivity * 0.5;

  // Onset adds flashes
  col += vec3(0.2, 0.3, 0.4) * uOnset * uSensitivity * 0.4;

  // Spectral centroid tint
  col = mix(col, col * vec3(1.2, 1.0, 0.8), uSpectralCentroid * uSensitivity * 0.3);

  // Warmth
  col = mix(col, col * vec3(1.1, 1.0, 0.9), uWarmth * uSensitivity * 0.2);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBoltFrequency;
uniform float uBranchDepth;
uniform float uAfterglowTime;
uniform float uCloudDensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noise(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Lightning bolt: returns brightness at point p for a bolt from top to bottom
float bolt(vec2 p, float seed, float time, float branchDepth) {
  float brightness = 0.0;
  // Main bolt: spans full screen height
  float boltX = 0.0;
  float segments = 20.0;
  float prevX = 0.0;
  float prevY = 1.2;

  for (int seg = 0; seg < 20; seg++) {
    float t = float(seg) / segments;
    float nextY = 1.2 - t * 2.4;
    float jitter = (hash1(seed * 100.0 + float(seg) * 7.3 + floor(time * 3.0) * 17.0) - 0.5) * 0.25;
    jitter *= (1.0 + branchDepth);
    float nextX = prevX + jitter;

    // Segment line distance
    vec2 a = vec2(prevX, prevY);
    vec2 b = vec2(nextX, nextY);
    vec2 ab = b - a;
    float tProj = clamp(dot(p - a, ab) / dot(ab, ab), 0.0, 1.0);
    vec2 closest = a + ab * tProj;
    float d = length(p - closest);

    // Core brightness
    float core = exp(-d * d * 8000.0);
    float glow = exp(-d * d * 400.0) * 0.3;
    brightness += core + glow;

    // Branch at some segments
    if (seg > 3 && seg < 16 && hash1(seed * 50.0 + float(seg) * 13.1) > 0.6 - branchDepth * 0.3) {
      float branchAngle = (hash1(seed * 70.0 + float(seg) * 19.7) - 0.5) * 1.5;
      float branchLen = 0.1 + hash1(seed * 90.0 + float(seg) * 23.3) * 0.15;
      vec2 branchEnd = closest + vec2(branchAngle * branchLen, -branchLen);
      vec2 branchDir = branchEnd - closest;
      float tBranch = clamp(dot(p - closest, branchDir) / dot(branchDir, branchDir), 0.0, 1.0);
      vec2 branchClosest = closest + branchDir * tBranch;
      float bDist = length(p - branchClosest);
      brightness += exp(-bDist * bDist * 5000.0) * 0.6;
      brightness += exp(-bDist * bDist * 500.0) * 0.15;
    }

    prevX = nextX;
    prevY = nextY;
  }
  return brightness;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Storm cloud background
  vec3 skyColor = vec3(0.02, 0.02, 0.04);
  float clouds = fbm(vec2(p.x * 2.0 + time * 0.1, p.y * 1.5 + time * 0.05)) * uCloudDensity;
  float clouds2 = fbm(vec2(p.x * 3.0 - time * 0.08, p.y * 2.0 + time * 0.03) + 5.0) * uCloudDensity;
  float cloudMask = smoothstep(0.1, 0.5, clouds + clouds2);
  vec3 cloudColor = vec3(0.06, 0.06, 0.08) * cloudMask;

  // Cloud internal illumination from mids
  float cloudIllum = fbm(vec2(p.x * 4.0 + time * 0.3, p.y * 3.0)) * midsVal;
  cloudColor += vec3(0.1, 0.1, 0.15) * cloudIllum * cloudMask;

  // Lightning bolts
  float totalBolt = 0.0;

  // Bolt timing — active bolts flicker on/off
  float boltRate = 1.5 / (uBoltFrequency + 0.1);
  float branchD = uBranchDepth;

  // Bolt 0 — fires on beat, far left
  float bolt0time = floor(time / boltRate);
  float bolt0phase = fract(time / boltRate);
  float bolt0active = step(bolt0phase, 0.15 + beatPulse * 0.3);
  float bolt0afterglow = exp(-max(bolt0phase - 0.15, 0.0) / (uAfterglowTime * 0.5 + 0.05));
  vec2 bolt0p = p - vec2(-0.7 + sin(bolt0time * 3.7) * 0.3, 0.0);
  totalBolt += bolt(bolt0p, bolt0time * 7.1, time, branchD) * max(bolt0active, bolt0afterglow * 0.3);

  // Bolt 1 — offset timing, far right
  float bolt1time = floor((time + boltRate * 0.25) / boltRate);
  float bolt1phase = fract((time + boltRate * 0.25) / boltRate);
  float bolt1active = step(bolt1phase, 0.12 + bassVal * 0.2);
  float bolt1afterglow = exp(-max(bolt1phase - 0.12, 0.0) / (uAfterglowTime * 0.5 + 0.05));
  vec2 bolt1p = p - vec2(0.6 + sin(bolt1time * 5.3) * 0.35, 0.0);
  totalBolt += bolt(bolt1p, bolt1time * 11.3, time, branchD) * max(bolt1active, bolt1afterglow * 0.25);

  // Bolt 2 — center, faster
  float bolt2time = floor((time + boltRate * 0.5) / boltRate);
  float bolt2phase = fract((time + boltRate * 0.5) / boltRate);
  float bolt2active = step(bolt2phase, 0.1 + beatPulse * 0.25);
  float bolt2afterglow = exp(-max(bolt2phase - 0.1, 0.0) / (uAfterglowTime * 0.5 + 0.05));
  vec2 bolt2p = p - vec2(sin(bolt2time * 2.7) * 0.8, 0.0);
  totalBolt += bolt(bolt2p, bolt2time * 17.7, time, branchD) * max(bolt2active, bolt2afterglow * 0.2);

  // Bolt 3 — onset-triggered massive bolt, wide range
  float bolt3active = onsetFlash;
  vec2 bolt3p = p - vec2(sin(time * 1.3) * 0.5, 0.0);
  totalBolt += bolt(bolt3p, floor(time * 5.0) * 23.1, time, branchD * 1.5) * bolt3active * 2.0;

  // Bolt 4 — far left second
  float bolt4time = floor((time + boltRate * 0.75) / boltRate);
  float bolt4phase = fract((time + boltRate * 0.75) / boltRate);
  float bolt4active = step(bolt4phase, 0.13 + bassVal * 0.15);
  float bolt4afterglow = exp(-max(bolt4phase - 0.13, 0.0) / (uAfterglowTime * 0.5 + 0.05));
  vec2 bolt4p = p - vec2(-0.3 + sin(bolt4time * 4.1) * 0.4, 0.0);
  totalBolt += bolt(bolt4p, bolt4time * 29.3, time, branchD * 0.8) * max(bolt4active, bolt4afterglow * 0.25);

  // Bolt 5 — treble micro-bolts, wide range
  float microBoltTime = floor(time * 4.0);
  float microBoltPhase = fract(time * 4.0);
  float microActive = step(0.7 - trebleVal * 0.3, hash1(microBoltTime * 31.7));
  vec2 microP = p - vec2(sin(microBoltTime * 7.1) * 0.9, 0.0);
  float microBolt = bolt(microP * 1.3, microBoltTime * 37.3, time, branchD * 0.5);
  totalBolt += microBolt * microActive * 0.4 * smoothstep(0.3, 0.0, microBoltPhase);

  // Bolt 6 — second micro-bolt, opposite side
  float micro2Time = floor(time * 3.5 + 1.7);
  float micro2Phase = fract(time * 3.5 + 1.7);
  float micro2Active = step(0.65 - trebleVal * 0.25, hash1(micro2Time * 43.1));
  vec2 micro2P = p - vec2(cos(micro2Time * 5.3) * 0.85, -0.2);
  float micro2Bolt = bolt(micro2P * 1.3, micro2Time * 41.7, time, branchD * 0.4);
  totalBolt += micro2Bolt * micro2Active * 0.35 * smoothstep(0.3, 0.0, micro2Phase);

  // Lightning color: white-blue core
  vec3 boltColor = vec3(0.7 + uPalette * 0.05, 0.8, 1.0) * totalBolt;

  // Cloud illumination from lightning
  float lightningIllum = totalBolt * 0.3;
  cloudColor += vec3(0.15, 0.15, 0.25) * lightningIllum * cloudMask;

  // Rain/atmosphere glow
  float rainGlow = fbm(vec2(p.x * 20.0, p.y * 30.0 - time * 8.0)) * 0.02;
  rainGlow *= smoothstep(0.5, -0.5, p.y);

  vec3 finalColor = skyColor + cloudColor + boltColor * uIntensity * 1.5 + vec3(rainGlow * 0.4, rainGlow * 0.4, rainGlow * 0.6);

  // Beat flash — sky illumination
  finalColor += vec3(0.03, 0.03, 0.06) * beatPulse;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Hash for noise
float hashVal(vec2 pt) {
  return fract(sin(dot(pt, vec2(127.1, 311.7))) * 43758.5453);
}

// Value noise
float noiseVal(vec2 pt) {
  vec2 i = floor(pt);
  vec2 f = fract(pt);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM noise
float fbm(vec2 pt) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * noiseVal(pt * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Lightning bolt along a line with zigzag displacement
float lightning(vec2 pt, vec2 a, vec2 b, float thickness, float chaos, float time) {
  vec2 ab = b - a;
  float lineLen = length(ab);
  vec2 dir = ab / lineLen;
  vec2 norm = vec2(-dir.y, dir.x);

  // Project point onto line
  vec2 ap = pt - a;
  float t = dot(ap, dir) / lineLen;

  if (t < 0.0 || t > 1.0) return 0.0;

  // Zigzag displacement using noise
  float zigzag = fbm(vec2(t * 8.0 + time * 3.0, time * 0.5)) * 2.0 - 1.0;
  zigzag *= chaos * 0.15 * sin(t * 3.14159);

  // Sub-zigzag for fractal detail
  float subZig = noiseVal(vec2(t * 20.0 + time * 5.0, time)) * 2.0 - 1.0;
  zigzag += subZig * chaos * 0.05;

  // Distance from displaced line
  float dist = abs(dot(ap, norm) - zigzag * lineLen);

  // Glow falloff
  float core = exp(-dist / (thickness * 0.3));
  float glow = exp(-dist / (thickness * 2.0));

  return core * 0.8 + glow * 0.4;
}

// Mandala ring with petal symmetry
float mandalaRing(vec2 pt, float radius, float petalCount, float petalDepth, float thickness) {
  float r = length(pt);
  float ang = atan(pt.y, pt.x);

  // Petal modulation
  float petal = 1.0 + petalDepth * cos(ang * petalCount);
  float modRadius = radius * petal;

  float dist = abs(r - modRadius);
  return smoothstep(thickness, 0.0, dist);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;

  float r = length(p);
  float ang = atan(p.y, p.x);

  vec3 col = vec3(0.0);

  // 4 concentric mandala rings with different petal counts
  float ringRadii[4];
  ringRadii[0] = 0.3 + bassVal * 0.1;
  ringRadii[1] = 0.6 + midsVal * 0.08;
  ringRadii[2] = 0.9 + trebleVal * 0.06;
  ringRadii[3] = 1.2 + uEnergy * uSensitivity * 0.05;

  float petalCounts[4];
  petalCounts[0] = 6.0;
  petalCounts[1] = 8.0;
  petalCounts[2] = 12.0;
  petalCounts[3] = 16.0;

  // Ring rotation speeds
  float rotSpeeds[4];
  rotSpeeds[0] = time * 0.1;
  rotSpeeds[1] = -time * 0.07;
  rotSpeeds[2] = time * 0.05;
  rotSpeeds[3] = -time * 0.03;

  for (int i = 0; i < 4; i++) {
    float rotAng = rotSpeeds[i];
    vec2 rotP = vec2(
      cos(rotAng) * p.x - sin(rotAng) * p.y,
      sin(rotAng) * p.x + cos(rotAng) * p.y
    );

    float ring = mandalaRing(rotP, ringRadii[i], petalCounts[i], 0.15 + uChaos * 0.1, 0.02 + trebleVal * 0.01);

    // Color per ring: electric blue to purple
    float hue = 0.6 + float(i) * 0.05 + uPalette * 0.2 + time * 0.01;
    vec3 ringCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.1, 0.2)));
    col += ringCol * ring * 0.6;
  }

  // Lightning bolts along radial paths
  float boltCount = 6.0 + uChaos * 4.0;
  float boltVisibility = uBeat * uSensitivity * 1.2 + uKick * uSensitivity * 2.0;
  boltVisibility = clamp(boltVisibility, 0.0, 1.0);

  for (int i = 0; i < 10; i++) {
    if (float(i) >= boltCount) break;

    float boltAng = float(i) / boltCount * 6.2832 + time * 0.05;
    // Bolt from inner ring to outer ring
    vec2 boltStart = vec2(cos(boltAng), sin(boltAng)) * ringRadii[0];
    vec2 boltEnd = vec2(cos(boltAng), sin(boltAng)) * ringRadii[3];

    float bolt = lightning(p, boltStart, boltEnd, 0.03 + bassVal * 0.02, 1.0 + uChaos, time + float(i) * 1.37);

    // Electric blue/white bolt color
    vec3 boltCol = mix(vec3(0.3, 0.5, 1.0), vec3(1.0, 0.95, 1.0), bolt * 0.5);
    boltCol += vec3(0.5, 0.2, 0.8) * uPalette * 0.3;

    col += boltCol * bolt * boltVisibility * 0.4;
  }

  // Cross-bolts between rings (on onset)
  float crossBoltVis = uOnset * uSensitivity * 1.5;
  for (int i = 0; i < 4; i++) {
    float crossAng = float(i) * 1.5708 + time * 0.2;
    for (int j = 0; j < 3; j++) {
      vec2 cStart = vec2(cos(crossAng), sin(crossAng)) * ringRadii[j];
      vec2 cEnd = vec2(cos(crossAng + 0.3), sin(crossAng + 0.3)) * ringRadii[j + 1];
      float bolt = lightning(p, cStart, cEnd, 0.02, 1.5 + uChaos, time + float(i * 3 + j) * 2.17);
      col += vec3(0.6, 0.3, 1.0) * bolt * crossBoltVis * 0.3;
    }
  }

  // Center glow
  float centerGlow = exp(-r * r * 4.0) * (0.3 + bassVal * 0.5);
  col += vec3(0.4, 0.2, 0.8) * centerGlow;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.12 * uSensitivity;

  // Spectral flux adds energy sparks
  float sparkNoise = noiseVal(p * 10.0 + time * 5.0);
  col += vec3(0.5, 0.3, 1.0) * sparkNoise * uSpectralFlux * uSensitivity * 0.2;

  // Harmonicity modulates ring brightness
  col *= 1.0 + uHarmonicity * uSensitivity * 0.2;

  // Warmth tint
  col = mix(col, col * vec3(1.1, 0.95, 0.9), uWarmth * uSensitivity * 0.2);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCorridorDepth;
uniform float uFlickerRate;
uniform float uFogDensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Fluorescent flicker
float flicker(float time, float seed, float rate) {
  float base = sin(time * rate * 60.0) * 0.5 + 0.5;
  float buzz = sin(time * 120.0 + seed * 100.0) * 0.1;
  float random = hash1(floor(time * rate * 8.0 + seed));
  float cutout = step(0.15, random);
  float surge = smoothstep(0.95, 1.0, random) * 0.5;
  return (base * 0.3 + 0.7 + buzz + surge) * cutout;
}

// SDF: box
float sdBox(vec3 p, vec3 b) {
  vec3 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Room-based infinite backrooms layout
// Returns distance to nearest wall/floor/ceiling
float mapScene(vec3 pos, float bassVal) {
  // Room dimensions: corridor is 3 wide, 2.5 tall, repeating every 6 units in Z
  // With random openings in X direction
  float roomW = 1.5;
  float roomH = 1.25;
  float roomLen = 3.0;

  // Breathing walls: bass makes space pulse
  float breathe = 1.0 + bassVal * 0.08;
  roomW *= breathe;
  roomH *= breathe;

  // Tile space into rooms
  vec3 rp = pos;
  // Room cell ID
  float cellZ = floor(rp.z / roomLen);
  float cellX = floor((rp.x + roomW) / (roomW * 2.0));

  // Local position within room cell
  float localZ = mod(rp.z, roomLen) - roomLen * 0.5;
  float localX = rp.x;

  // Corridor walls (infinite corridor along Z)
  float walls = roomW - abs(localX);
  // Floor and ceiling
  float floorDist = rp.y + roomH;
  float ceilDist = roomH - rp.y;
  float corridor = min(walls, min(floorDist, ceilDist));

  // Cross-corridors at random intervals (based on cell hash)
  float crossHash = hash(vec2(cellZ, 0.0));
  if (crossHash > 0.4) {
    // Opening in the wall (doorway)
    float doorwayZ = abs(localZ);
    if (doorwayZ < 0.8) {
      // Extend walls outward (cross corridor)
      float crossWalls = roomW * 2.0 - abs(rp.y); // not great, just approximate
      corridor = max(corridor, 0.0);
    }
  }

  // Occasional pillars
  float pillarHash = hash(vec2(cellZ, cellX));
  if (pillarHash > 0.7) {
    float pillarX = (pillarHash - 0.7) * 6.0 - 0.9;
    float pillarZ = localZ;
    float pillarDist = length(vec2(localX - pillarX * roomW, pillarZ)) - 0.12;
    corridor = min(corridor, -pillarDist); // inverted so pillar is solid
  }

  return -corridor; // negate because we're inside the room
}

// Simplified raymarching map: carve out rooms from solid
float map(vec3 pos, float bassVal) {
  float roomW = 1.5 * (1.0 + bassVal * 0.08);
  float roomH = 1.25;
  float roomLen = 3.0;

  // Main corridor along Z
  float mainCorridor = sdBox(vec3(pos.x, pos.y, mod(pos.z + roomLen * 0.5, roomLen) - roomLen * 0.5),
    vec3(roomW, roomH, roomLen * 0.5));

  // Cross corridors at certain Z intervals
  float cellZ = floor(pos.z / roomLen);
  float crossHash = hash(vec2(cellZ, 0.0));
  float crossCorridor = sdBox(vec3(mod(pos.x + roomW, roomW * 2.0) - roomW, pos.y,
    pos.z - cellZ * roomLen - roomLen * 0.5), vec3(roomW * 2.0, roomH, 0.7));

  float d = mainCorridor;
  if (crossHash > 0.35) {
    d = min(d, crossCorridor);
  }

  // Additional perpendicular corridor (X direction) at some intervals
  float cellZ2 = floor(pos.z / (roomLen * 2.0));
  float perpHash = hash(vec2(cellZ2, 5.0));
  if (perpHash > 0.3) {
    float perpZ = cellZ2 * roomLen * 2.0 + roomLen;
    float perpCorridor = sdBox(vec3(pos.x, pos.y, pos.z - perpZ), vec3(roomW * 3.0, roomH, roomW));
    d = min(d, perpCorridor);
  }

  return -d; // we want to be INSIDE the rooms, so invert
}

// Calculate normal
vec3 calcNormal(vec3 pos, float bassVal) {
  vec2 e = vec2(0.005, 0.0);
  return normalize(vec3(
    map(pos + e.xyy, bassVal) - map(pos - e.xyy, bassVal),
    map(pos + e.yxy, bassVal) - map(pos - e.yxy, bassVal),
    map(pos + e.yyx, bassVal) - map(pos - e.yyx, bassVal)
  ));
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickPulse = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // === CAMERA: moving through the backrooms ===
  // Continuous forward movement with random turns
  float moveSpeed = time * 2.0 * uCorridorDepth + bassVal * 0.5;
  // Slow random turning (via smooth noise)
  float turnAngle = noise(vec2(time * 0.15, 0.0)) * 3.14159 * 0.5
    + sin(time * 0.08) * 0.8
    + midsVal * 0.3 * sin(time * 0.5);

  // Camera position: forward along a winding path
  float camX = sin(turnAngle) * moveSpeed * 0.3 + cos(time * 0.1) * 0.5;
  float camY = 0.0 + sin(moveSpeed * 2.0) * 0.03; // slight head bob
  float camZ = moveSpeed;
  vec3 camPos = vec3(camX, camY, camZ);

  // Camera direction: looking along the turning direction
  float lookAngle = turnAngle + noise(vec2(time * 0.2, 5.0)) * 0.3;
  vec3 camDir = normalize(vec3(sin(lookAngle) * 0.3, 0.0, 1.0));
  vec3 camUp = vec3(0.0, 1.0, 0.0);
  vec3 camRight = normalize(cross(camDir, camUp));
  vec3 trueUp = cross(camRight, camDir);

  // Ray direction
  float fov = 0.8 + uZoom * 0.3;
  vec3 rd = normalize(camDir * fov + camRight * p.x + trueUp * p.y);

  // === RAYMARCHING ===
  float totalDist = 0.0;
  float maxDist = 40.0;
  vec3 hitPos = camPos;
  bool hit = false;

  for (int i = 0; i < 80; i++) {
    hitPos = camPos + rd * totalDist;
    float d = map(hitPos, bassVal);
    if (d > -0.005) { // we're inside the wall (outside the room)
      hit = true;
      break;
    }
    totalDist += max(abs(d) * 0.5, 0.02); // march inside room
    if (totalDist > maxDist) break;
  }

  // === SHADING ===
  vec3 col = vec3(0.0);

  if (hit && totalDist < maxDist) {
    vec3 nor = calcNormal(hitPos, bassVal);

    // Determine surface type (floor, ceiling, or wall)
    float isFloor = smoothstep(-0.8, -1.0, nor.y);
    float isCeiling = smoothstep(0.8, 1.0, nor.y);
    float isWall = 1.0 - isFloor - isCeiling;

    // === TILE PATTERN (floor) ===
    float tileX = fract(hitPos.x * 0.5);
    float tileZ = fract(hitPos.z * 0.5);
    float tileGrid = step(0.03, tileX) * step(0.03, tileZ) *
                     step(tileX, 0.97) * step(tileZ, 0.97);
    float checker = mod(floor(hitPos.x * 0.5) + floor(hitPos.z * 0.5), 2.0);
    vec3 floorColor = mix(
      mix(vec3(0.35, 0.38, 0.3), vec3(0.6, 0.55, 0.4), uPalette * 0.3),
      mix(vec3(0.25, 0.28, 0.22), vec3(0.45, 0.4, 0.3), uPalette * 0.3),
      checker
    ) * tileGrid;

    // === WALL COLOR ===
    float wallNoise = noise(hitPos.xz * 0.5) * 0.15;
    vec3 wallColor = vec3(0.55, 0.58, 0.5) * (1.0 - wallNoise);
    // Wainscoting: lower wall is darker
    float wainscot = smoothstep(-0.3, -0.5, hitPos.y);
    wallColor = mix(wallColor, vec3(0.3, 0.28, 0.22), wainscot * 0.5);

    // === CEILING: stained acoustic tiles ===
    float ceilTileX = fract(hitPos.x * 0.8);
    float ceilTileZ = fract(hitPos.z * 0.8);
    float ceilGrid = step(0.02, ceilTileX) * step(0.02, ceilTileZ) *
                     step(ceilTileX, 0.98) * step(ceilTileZ, 0.98);
    vec3 ceilColor = vec3(0.5, 0.48, 0.42) * ceilGrid;
    // Stains
    float stain = noise(hitPos.xz * 2.0 + 10.0);
    ceilColor *= 0.8 + stain * 0.2;

    // Compose surface color
    vec3 surfaceColor = floorColor * isFloor + wallColor * isWall + ceilColor * isCeiling;

    // === FLUORESCENT LIGHTING ===
    float lightCellZ = floor(hitPos.z * 0.4);
    float lightCellX = floor(hitPos.x * 0.6);
    float lightSeed = lightCellZ * 7.0 + lightCellX * 13.0;
    float flickerVal = flicker(time, lightSeed, uFlickerRate * 2.0 + 1.0);
    // Treble makes lights buzz more
    flickerVal *= (1.0 + trebleVal * 0.4);

    // Light position: on ceiling at regular intervals
    float lightLocalZ = fract(hitPos.z * 0.4);
    float lightLocalX = fract(hitPos.x * 0.6);
    float lightProximity = smoothstep(0.3, 0.0, abs(lightLocalZ - 0.5))
      * smoothstep(0.3, 0.0, abs(lightLocalX - 0.5));

    // Sickly yellow fluorescent
    vec3 lightColor = vec3(0.95, 0.9, 0.65) * flickerVal;
    float ambientLight = 0.15 + lightProximity * 0.6 * flickerVal;

    // Directional: light comes from ceiling
    float ceilLight = max(dot(nor, vec3(0.0, 1.0, 0.0)), 0.0);
    col = surfaceColor * (ambientLight + ceilLight * 0.3 * flickerVal);
    col += lightColor * lightProximity * 0.3 * isCeiling;

    // === DOORWAY LIGHT ===
    float doorCellZ = floor(hitPos.z * 0.2);
    float doorHash = hash(vec2(doorCellZ, 3.0));
    if (doorHash > 0.5) {
      float doorLocalZ = fract(hitPos.z * 0.2);
      float doorGlow = smoothstep(0.1, 0.0, abs(doorLocalZ - 0.5)) * isWall;
      vec3 doorColor = vec3(1.0, 0.95, 0.8) * doorGlow * (0.15 + kickPulse * 0.6);
      col += doorColor;
    }

    // === FOG ===
    float fogAmount = 1.0 - exp(-totalDist * uFogDensity * 0.06);
    fogAmount = clamp(fogAmount, 0.0, 0.85);
    vec3 fogColor = vec3(0.35, 0.33, 0.28) * (0.8 + flickerVal * 0.2);
    col = mix(col, fogColor, fogAmount);

  } else {
    // Missed: deep fog
    col = vec3(0.3, 0.28, 0.24) * 0.5;
  }

  // === POST-PROCESSING ===
  // Treble: scanline interference (CRT/fluorescent)
  float interference = sin(p.y * 200.0 + time * 50.0) * trebleVal * 0.04;
  col += vec3(interference * 0.8, interference * 0.7, interference * 0.3);

  // Chaos: random static/glitch
  float staticPatch = hash(floor(p * 30.0) + floor(time * 3.0));
  col += vec3(staticPatch - 0.5) * uChaos * 0.1;

  // Onset: all lights surge
  col += vec3(0.6, 0.55, 0.4) * onsetFlash * 0.25;

  // Vignette (liminal dread)
  float vignette = 1.0 - dot(p * 0.5, p * 0.5);
  col *= 0.5 + vignette * 0.5;

  col *= uIntensity * 1.2 + energyVal * 0.15;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRippleCount;
uniform float uFresnelPower;
uniform float uSpecSharp;
uniform float uSurfTension;

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio influences
  float bassInfluence = bass() * uSensitivity;
  float midsInfluence = mids() * uSensitivity;
  float trebleInfluence = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickInfluence = uKick * uSensitivity;

  // Epsilon for central difference normal computation
  float eps = 0.005;

  // === HEIGHT FIELD ===
  float tension = uSurfTension + 0.1;

  // Wave 1: slow, large
  float amp1 = 0.3 / tension + bassInfluence * 0.2;
  float h1c = sin(p.x * 2.0 + time * 0.4 + p.y * 1.5) * amp1;
  float h1r = sin((p.x + eps) * 2.0 + time * 0.4 + p.y * 1.5) * amp1;
  float h1u = sin(p.x * 2.0 + time * 0.4 + (p.y + eps) * 1.5) * amp1;

  // Wave 2: medium, diagonal
  float amp2 = 0.2 / tension;
  float h2c = sin(p.x * 4.0 - p.y * 3.0 + time * 0.7) * amp2;
  float h2r = sin((p.x + eps) * 4.0 - p.y * 3.0 + time * 0.7) * amp2;
  float h2u = sin(p.x * 4.0 - (p.y + eps) * 3.0 + time * 0.7) * amp2;

  // Wave 3: faster, angular
  float amp3 = 0.15 / tension + midsInfluence * 0.08;
  float h3c = cos(p.x * 5.0 + p.y * 6.0 - time * 1.1) * amp3;
  float h3r = cos((p.x + eps) * 5.0 + p.y * 6.0 - time * 1.1) * amp3;
  float h3u = cos(p.x * 5.0 + (p.y + eps) * 6.0 - time * 1.1) * amp3;

  // Wave 4: chaotic high-freq
  float amp4 = (0.1 / tension) * (uChaos + 0.3);
  float h4c = sin(p.x * 8.0 - time * 1.5 + p.y * 7.0) * amp4;
  float h4r = sin((p.x + eps) * 8.0 - time * 1.5 + p.y * 7.0) * amp4;
  float h4u = sin(p.x * 8.0 - time * 1.5 + (p.y + eps) * 7.0) * amp4;

  // Wave 5: treble-driven fine detail
  float amp5 = trebleInfluence * 0.12;
  float h5c = sin(p.x * 12.0 + p.y * 10.0 + time * 2.0) * amp5;
  float h5r = sin((p.x + eps) * 12.0 + p.y * 10.0 + time * 2.0) * amp5;
  float h5u = sin(p.x * 12.0 + (p.y + eps) * 10.0 + time * 2.0) * amp5;

  // Wave 6: kick impact ripple from center
  float dist = pow(p.x * p.x + p.y * p.y, 0.5);
  float kickAmp = kickInfluence * 0.25;
  float h6c = sin(dist * 15.0 - time * 4.0) * kickAmp * smoothstep(1.5, 0.0, dist);
  float h6r = sin(pow((p.x + eps) * (p.x + eps) + p.y * p.y, 0.5) * 15.0 - time * 4.0) * kickAmp * smoothstep(1.5, 0.0, dist);
  float h6u = sin(pow(p.x * p.x + (p.y + eps) * (p.y + eps), 0.5) * 15.0 - time * 4.0) * kickAmp * smoothstep(1.5, 0.0, dist);

  // Total heights
  float hc = h1c + h2c + h3c + h4c + h5c + h6c;
  float hr = h1r + h2r + h3r + h4r + h5r + h6r;
  float hu = h1u + h2u + h3u + h4u + h5u + h6u;

  // === SURFACE NORMAL (central difference) ===
  float dhdx = (hr - hc) / eps;
  float dhdy = (hu - hc) / eps;
  vec3 normal = normalize(vec3(-dhdx, -dhdy, 1.0));

  // Procedural environment map
  vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
  vec3 reflDir = reflect(vec3(0.0, 0.0, -1.0), normal);

  // Environment color from reflected direction
  float envUp = reflDir.y * 0.5 + 0.5;
  float envHue = fract(reflDir.x * 0.2 + uPalette * 0.15 + midsInfluence * 0.3 + time * 0.01);

  // Sky: bright, saturated color at top; dark at horizon
  float skyR = abs(fract(envHue + 1.0) * 6.0 - 3.0) - 1.0;
  float skyG = abs(fract(envHue + 0.6667) * 6.0 - 3.0) - 1.0;
  float skyB = abs(fract(envHue + 0.3333) * 6.0 - 3.0) - 1.0;
  float skyBright = smoothstep(0.0, 1.0, envUp) * 0.8 + 0.2;
  float envR = clamp(skyR, 0.0, 1.0) * skyBright;
  float envG = clamp(skyG, 0.0, 1.0) * skyBright;
  float envB = clamp(skyB, 0.0, 1.0) * skyBright;

  // === FRESNEL ===
  float NdotV = max(dot(normal, viewDir), 0.0);
  float fresnel = pow(1.0 - NdotV, uFresnelPower);

  // Chrome base: dark metallic gray
  float chromeBase = 0.05;

  // Reflected environment weighted by fresnel
  float reflR = mix(chromeBase, envR, fresnel);
  float reflG = mix(chromeBase, envG, fresnel);
  float reflB = mix(chromeBase, envB, fresnel);

  // Specular highlight from virtual sun
  vec3 lightDir = normalize(vec3(
    sin(time * 0.1) * 0.5,
    cos(time * 0.08) * 0.3 + 0.7,
    1.0
  ));
  vec3 halfVec = normalize(lightDir + viewDir);
  float NdotH = max(dot(normal, halfVec), 0.0);
  float specular = pow(NdotH, uSpecSharp) * uIntensity;

  // === COMBINE ===
  float brightness = uIntensity * 1.3;
  float outR = reflR * brightness + specular;
  float outG = reflG * brightness + specular;
  float outB = reflB * brightness + specular;

  // Beat pulse brightness
  float beatBright = beatPulse * 0.2;
  float energyGlow = uEnergy * uSensitivity * 0.1;

  float finalR = outR + beatBright + energyGlow;
  float finalG = outG + beatBright + energyGlow;
  float finalB = outB + beatBright + energyGlow;

