  return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

// Complex power using polar form (for fractal power != 2)
vec2 cpow(vec2 z, float n) {
  float r = length(z);
  float a = atan(z.y, z.x);
  return pow(r, n) * vec2(cos(a * n), sin(a * n));
