    float t2 = iter2 / 16.0;
    float overlay = exp(-t2 * 4.0) * 0.15;
    vec3 overlayCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * (t2 + time * 0.2) + vec3(0.5, 0.3, 0.0)));
