vec3 hsvToRgb(float h, float s, float v) {
  vec3 c = vec3(h, s, v);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

// Draw a single branch segment and return glow
float drawBranch(vec2 pt, vec2 a, vec2 b, float thickness) {
  float dist = segmentDist(pt, a, b);
  float core = smoothstep(thickness, thickness * 0.3, dist);
  float glow = exp(-dist / (thickness * 4.0));
  return core + glow * 0.3;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;

  vec3 col = vec3(0.0);

  // Cosmic starfield background
  for (int i = 0; i < 80; i++) {
    vec2 starPos = vec2(
      hashStar(vec2(float(i), 1.0)) * 3.0 - 1.5,
      hashStar(vec2(float(i), 2.0)) * 3.0 - 1.5
    );
    float starBright = hashStar(vec2(float(i), 3.0));
    float twinkle = sin(time * (1.0 + starBright * 3.0) + float(i)) * 0.5 + 0.5;
    float dist = length(p - starPos);
    float starGlow = exp(-dist * dist * 500.0) * starBright * twinkle;
    vec3 starCol = hsvToRgb(hashStar(vec2(float(i), 4.0)), 0.3, 1.0);
    col += starCol * starGlow * 0.5;
  }

  // Wind sway
  float windPhase = sin(time * 0.5) * 0.15 * uChaos;

  // Tree drawing: recursive binary tree with 6 levels = 63 segments
  // We simulate the recursion iteratively
  vec3 trunkCol = vec3(0.85, 0.65, 0.2); // Gold
  float treeGlow = 0.0;
  vec3 treeColor = vec3(0.0);

  // Draw tree for both above (1.0) and below (roots, -1.0)
  for (int mirror = 0; mirror < 2; mirror++) {
    float yFlip = mirror == 0 ? 1.0 : -1.0;
    float mirrorDimming = mirror == 0 ? 1.0 : 0.5; // Roots are dimmer

    // Branch queue: encode start position, angle, depth, thickness
    // Level 0: trunk
    vec2 trunkBase = vec2(0.0, -1.2 * yFlip);
    float trunkLen = 0.5 + bassVal * 0.1;
    float baseAngle = 1.5708 * yFlip; // pi/2 up or -pi/2 down
    float baseThick = 0.04;

    // Level 0 (trunk)
    vec2 trunkTip = trunkBase + vec2(cos(baseAngle + windPhase * 0.2), sin(baseAngle + windPhase * 0.2)) * trunkLen;
    float seg = drawBranch(p, trunkBase, trunkTip, baseThick);
    treeGlow += seg * mirrorDimming;
    treeColor += trunkCol * seg * mirrorDimming;

    // Levels 1-5: iterate branches
    // We use a flat approach: 2 branches per level
    vec2 starts[64];
    float angles[64];
    float lengths[64];
    float thicks[64];
    int branchCount = 0;

    starts[0] = trunkTip;
    angles[0] = baseAngle;
    lengths[0] = trunkLen;
    thicks[0] = baseThick;
    branchCount = 1;

    for (int level = 1; level <= 6; level++) {
      int prevCount = branchCount;
      int newCount = 0;

      for (int bi = 0; bi < 32; bi++) {
        if (bi >= prevCount) break;

        vec2 startPt = starts[bi];
        float parentAng = angles[bi];
        float parentLen = lengths[bi];
        float parentThick = thicks[bi];

        float childLen = parentLen * (0.65 + midsVal * 0.1);
        float childThick = parentThick * 0.65;
        float spreadAng = 0.4 + uChaos * 0.3 + trebleVal * 0.1;

        // Wind sway increases with height
        float heightFactor = float(level) / 6.0;
        float sway = windPhase * heightFactor;

        // Left branch
        float angL = parentAng + spreadAng + sway;
        vec2 tipL = startPt + vec2(cos(angL), sin(angL)) * childLen;
        float segL = drawBranch(p, startPt, tipL, childThick);

        // Branch color: transition from gold to rainbow at tips
        float leafness = float(level) / 6.0;
        float leafHue = fract(float(bi) * 0.1618 + uPalette * 0.3 + time * 0.03);
        vec3 bCol = mix(trunkCol, hsvToRgb(leafHue, 0.9, 1.0), leafness);
        treeGlow += segL * mirrorDimming;
        treeColor += bCol * segL * mirrorDimming;

        // Right branch
        float angR = parentAng - spreadAng + sway;
        vec2 tipR = startPt + vec2(cos(angR), sin(angR)) * childLen;
        float segR = drawBranch(p, startPt, tipR, childThick);
        float leafHueR = fract(float(bi + 32) * 0.1618 + uPalette * 0.3 + time * 0.03);
        vec3 bColR = mix(trunkCol, hsvToRgb(leafHueR, 0.9, 1.0), leafness);
        treeGlow += segR * mirrorDimming;
        treeColor += bColR * segR * mirrorDimming;

        // Store for next level (limit to array size)
        if (newCount < 62) {
          starts[newCount] = tipL;
          angles[newCount] = angL;
          lengths[newCount] = childLen;
          thicks[newCount] = childThick;
          newCount++;
          starts[newCount] = tipR;
          angles[newCount] = angR;
          lengths[newCount] = childLen;
          thicks[newCount] = childThick;
          newCount++;
        }

        // Leaf orbs at terminals
        if (level >= 5) {
          float orbGlowL = exp(-length(p - tipL) * length(p - tipL) * 40.0);
          float orbGlowR = exp(-length(p - tipR) * length(p - tipR) * 40.0);
          float orbPulse = 0.5 + 0.5 * sin(time * 3.0 + float(bi));
          col += hsvToRgb(leafHue, 0.8, 1.0) * orbGlowL * orbPulse * 0.8 * mirrorDimming;
          col += hsvToRgb(leafHueR, 0.8, 1.0) * orbGlowR * orbPulse * 0.8 * mirrorDimming;
        }
      }

      branchCount = newCount;
      if (branchCount >= 32) branchCount = 32;
    }
  }

  // Combine tree glow with color
  col += treeColor * 0.8;

  // Ground line glow
  float groundGlow = exp(-abs(p.y + 1.2) * 10.0) * 0.3;
  col += vec3(0.3, 0.5, 0.2) * groundGlow;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Kick brightens whole tree
  col += treeColor * uKick * uSensitivity * 0.3;

  // Onset sparkles
  col += vec3(1.0, 0.9, 0.7) * uOnset * uSensitivity * 0.3;

  // Spectral centroid tint
  col = mix(col, col * vec3(1.2, 1.0, 0.8), uSpectralCentroid * uSensitivity * 0.2);

  // Warmth
  col = mix(col, col * vec3(1.15, 1.0, 0.85), uWarmth * uSensitivity * 0.2);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uEntityCount;
uniform float uMorphRate;
uniform float uTrailLength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float p) {
  return fract(sin(p * 127.1) * 43758.5453);
}

// SDF for a box (2D projection)
float boxSDF(vec2 p, vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// SDF for a triangle
float triSDF(vec2 p, float s) {
  p.x = abs(p.x) - s;
  p.y += s * 0.577;
  if (p.x + 1.732 * p.y > 0.0) {
    p = vec2(p.x - 1.732 * p.y, -1.732 * p.x - p.y) / 2.0;
  }
  p.x -= clamp(p.x, -2.0 * s, 0.0);
  return -length(p) * sign(p.y);
}

// SDF for a hexagon
float hexSDF(vec2 p, float s) {
  p = abs(p);
  float d = max(p.x * 0.866025 + p.y * 0.5, p.y) - s;
  return d;
}

// Morphing between shapes: returns SDF
float morphShape(vec2 p, float morph, float size) {
  float m = fract(morph);
  float d1, d2;

  // Cycle: circle -> square -> triangle -> hexagon -> circle
  float phase = mod(floor(morph), 4.0);
  if (phase < 1.0) {
    d1 = length(p) - size;
    d2 = boxSDF(p, vec2(size * 0.8));
  } else if (phase < 2.0) {
    d1 = boxSDF(p, vec2(size * 0.8));
    d2 = triSDF(p, size * 0.9);
  } else if (phase < 3.0) {
    d1 = triSDF(p, size * 0.9);
    d2 = hexSDF(p, size * 0.85);
  } else {
    d1 = hexSDF(p, size * 0.85);
    d2 = length(p) - size;
  }
  return mix(d1, d2, smoothstep(0.0, 1.0, m));
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.6;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === PSYCHEDELIC BACKGROUND: sacred geometry / DMT space ===
  float bgAngle = atan(p.y, p.x);
  float bgR = length(p);
  // Layered sacred geometry
  float bgPattern1 = sin(bgAngle * 6.0 + time * 0.3) * sin(bgR * 10.0 - time * 0.5);
  float bgPattern2 = sin(bgAngle * 8.0 - time * 0.2) * cos(bgR * 15.0 + time * 0.3);
  float bgPattern3 = sin((bgAngle + bgR * 3.0) * 5.0 + time * 0.4);
  float bgMix = bgPattern1 * 0.3 + bgPattern2 * 0.2 + bgPattern3 * 0.15;
  vec3 bgColor = vec3(0.03, 0.01, 0.05) + vec3(0.02, 0.015, 0.04) * (bgMix + 0.5);
  // Treble makes background shimmer
  bgColor += vec3(0.01, 0.005, 0.02) * trebleVal;
  col += bgColor;

  // === GRID-TILED ELF FIELD ===
  // Tile the screen into a grid so elves fill the entire space
  int gridSize = int(clamp(uEntityCount, 2.0, 5.0)); // 2x2 up to 5x5 grid (capped for GPU perf)
  float fGridSize = float(gridSize);
  float cellSize = (2.0 + uZoom * 2.0) / fGridSize;

  for (int gx = 0; gx < 5; gx++) {
    if (gx >= gridSize) break;
    for (int gy = 0; gy < 5; gy++) {
      if (gy >= gridSize) break;

      float fgx = float(gx);
      float fgy = float(gy);
      float cellIdx = fgx * fGridSize + fgy;
      float elfHash = hash1(cellIdx + 0.5);
      float elfHash2 = hash1(cellIdx + 7.0);
      float elfHash3 = hash1(cellIdx + 13.0);

      // Cell center
      vec2 cellCenter = vec2(
        (fgx + 0.5) / fGridSize - 0.5,
        (fgy + 0.5) / fGridSize - 0.5
      ) * (2.0 + uZoom * 2.0);

      // Dancing motion: elves orbit and circle each other like square dancers
      float bounceAmp = cellSize * 0.3 + bassVal * cellSize * 0.1;

      // Primary circular orbit around cell center
      float orbitSpeed = 0.4 + elfHash * 0.6;
      float orbitRadius = bounceAmp * (0.6 + 0.4 * sin(time * 0.3 + cellIdx * 1.7));
      float orbitAngle = time * orbitSpeed + cellIdx * 1.2566; // golden angle spacing
      vec2 orbitPos = vec2(cos(orbitAngle), sin(orbitAngle)) * orbitRadius;

      // Do-si-do: secondary orbit so pairs of elves swap positions
      float dosiSpeed = 0.25 + elfHash2 * 0.3;
      float dosiAngle = time * dosiSpeed + cellIdx * 3.14159; // PI offset for partner swap
      float dosiRadius = bounceAmp * 0.4 * sin(time * 0.2 + elfHash3 * 6.28);
      vec2 dosiPos = vec2(cos(dosiAngle), sin(dosiAngle)) * dosiRadius;

      // Figure-8 swing overlay for complex dance patterns
      float swingPhase = time * 0.35 + cellIdx * 0.8;
      vec2 swingPos = vec2(
        sin(swingPhase * 2.0) * bounceAmp * 0.2,
        sin(swingPhase) * bounceAmp * 0.15
      );

      vec2 elfPos = cellCenter + orbitPos + dosiPos + swingPos;

      // Beat jump — elves bounce on the beat
      elfPos.y += beatPulse * cellSize * 0.15 * sin(cellIdx * 3.7);

      // Relative position + early distance cull (skip ~80% of cells)
      vec2 ep = p - elfPos;
      if (length(ep) > cellSize * 1.5) continue;

      // Rotation: variable speed per elf
      float rotSpeed = 0.5 + elfHash * 2.5;
      float rot = time * rotSpeed + beatPulse * 1.5;
      float cr = cos(rot); float sr = sin(rot);
      ep = vec2(ep.x * cr - ep.y * sr, ep.x * sr + ep.y * cr);

      // === MORPHING BODY ===
      // Variable size per elf: some big, some small
      float sizeVariance = 0.5 + elfHash3 * 1.0; // 0.5x to 1.5x
      float morphPhase = time * uMorphRate * (0.5 + elfHash) + beatPulse * 2.0;
      float bodySize = cellSize * 0.15 * sizeVariance + midsVal * cellSize * 0.02;
      // Bass makes them pulse bigger
      bodySize += bassVal * cellSize * 0.04;
      float bodyDist = morphShape(ep, morphPhase, bodySize);

      // Glowing edge: treble increases glow sharpness — 2x treble
      float edgeGlow = exp(-abs(bodyDist) * (25.0 / max(cellSize, 0.1) + trebleVal * 30.0));
      // Fill
      float fill = smoothstep(0.005, 0.0, bodyDist) * 0.3;

      // Entity color: unique per elf, golden ratio spread
      float hue = fract(cellIdx * 0.618 + uPalette * 0.1 + time * 0.1 + sin(uTime * 0.3) * 0.2);
      vec3 elfCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.25, 0.5)));
      elfCol = mix(elfCol, vec3(1.0), 0.2); // brighter

      // Treble: fragment/multiply effect (creates ghost copies)
      float fragAmount = trebleVal * 0.5;
      float ghostGlow = 0.0;
      if (fragAmount > 0.1) {
        for (int g = 0; g < 3; g++) {
          float fg = float(g);
          float ghostAngle = fg * 2.094 + time * 3.0 + cellIdx;
          vec2 ghostOffset = vec2(cos(ghostAngle), sin(ghostAngle)) * bodySize * (0.5 + fragAmount);
          float ghostDist = morphShape(ep - ghostOffset, morphPhase + fg, bodySize * 0.6);
          ghostGlow += exp(-abs(ghostDist) * 30.0) * fragAmount * 0.3;
        }
      }

      col += elfCol * (edgeGlow * 0.6 + fill + ghostGlow);

      // === FACE FEATURES ===
      float eyeSpacing = bodySize * 0.4;
      float eyeY = bodySize * 0.15;
      float eyeSize = bodySize * 0.12;
      float leftEye = smoothstep(eyeSize, eyeSize * 0.5, length(ep - vec2(-eyeSpacing, eyeY)));
      float rightEye = smoothstep(eyeSize, eyeSize * 0.5, length(ep - vec2(eyeSpacing, eyeY)));
      col += vec3(1.0) * (leftEye + rightEye) * 0.5;

      // Mouth: arc
      float mouthY = -bodySize * 0.2;
      float mouthR = bodySize * 0.3;
      float mouthAngle = atan(ep.y - mouthY, ep.x);
      float mouthDist = abs(length(ep - vec2(0.0, mouthY)) - mouthR);
      float mouth = exp(-mouthDist * mouthDist / (bodySize * bodySize * 0.0002)) *
                    step(-0.5, sin(mouthAngle)) *
                    smoothstep(bodySize * 1.5, 0.0, length(ep));
      col += elfCol * 1.5 * mouth * 0.4;

      // === JUGGLED PARTICLES: between this elf and its neighbors ===
      // Connect to right neighbor and below neighbor
      for (int link = 0; link < 2; link++) {
        int nx = gx + (link == 0 ? 1 : 0);
        int ny = gy + (link == 1 ? 1 : 0);
        if (nx >= gridSize || ny >= gridSize) continue;

        float fnx = float(nx);
        float fny = float(ny);
        float neighborIdx = fnx * fGridSize + fny;
        float nHash = hash1(neighborIdx + 0.5);
        float nHash2 = hash1(neighborIdx + 7.0);
        vec2 neighborCell = vec2(
          (fnx + 0.5) / fGridSize - 0.5,
          (fny + 0.5) / fGridSize - 0.5
        ) * (2.0 + uZoom * 2.0);
        vec2 neighborPos = neighborCell + vec2(
          sin(time * (0.5 + nHash * 0.7) + neighborIdx * 2.1) * cellSize * 0.3,
          cos(time * (0.3 + nHash2 * 0.6) + neighborIdx * 1.7) * cellSize * 0.24
        );

        for (int j = 0; j < 2; j++) {
          float fj = float(j);
          float arcT = fract(time * 1.5 + fj * 0.5 + cellIdx * 0.2);
          vec2 arcPos = mix(elfPos, neighborPos, arcT);
          arcPos.y += sin(arcT * 3.14159) * cellSize * 0.15;

          float particleDist = length(p - arcPos);
          float particleGlow = exp(-particleDist * particleDist / (cellSize * cellSize * 0.001)) * 0.3;

          // Trail
          float trailGlow = 0.0;
          for (int k = 1; k <= 3; k++) {
            float tk = arcT - float(k) * 0.03 * uTrailLength;
            if (tk < 0.0) continue;
            vec2 trailPos = mix(elfPos, neighborPos, tk);
            trailPos.y += sin(tk * 3.14159) * cellSize * 0.15;
            float td = length(p - trailPos);
            trailGlow += exp(-td * td / (cellSize * cellSize * 0.0008)) * 0.08 * (1.0 - float(k) * 0.25);
          }

          col += elfCol * (particleGlow + trailGlow) * (0.4 + trebleVal);
        }
      }
    }
  }

  // Onset flash — 2x
  col += vec3(0.8, 0.9, 1.0) * onsetFlash * 0.3;

  // Beat brightness — 2x
  col *= 1.0 + beatPulse * 0.4;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  // Overall intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Hash for noise
float hashVal(vec2 pt) {
  return fract(sin(dot(pt, vec2(127.1, 311.7))) * 43758.5453);
}

// Value noise
float noiseVal(vec2 pt) {
  vec2 i = floor(pt);
  vec2 f = fract(pt);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM noise for cracks
float fbm(vec2 pt, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    val += amp * noiseVal(pt * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Temperature color ramp: black → red → orange → yellow → white
vec3 lavaRamp(float temp) {
  vec3 col = vec3(0.0);
  col = mix(vec3(0.1, 0.0, 0.0), vec3(0.8, 0.1, 0.0), smoothstep(0.0, 0.3, temp));
  col = mix(col, vec3(1.0, 0.5, 0.0), smoothstep(0.3, 0.5, temp));
  col = mix(col, vec3(1.0, 0.9, 0.3), smoothstep(0.5, 0.7, temp));
  col = mix(col, vec3(1.0, 1.0, 0.9), smoothstep(0.7, 1.0, temp));
  return col;
}

// SDF for equilateral triangle
float triangleSDF(vec2 pt, float radius) {
  pt.y += radius * 0.25;
  float k = sqrt(3.0);
  pt.x = abs(pt.x) - radius;
  pt.y = pt.y + radius / k;
  if (pt.x + k * pt.y > 0.0) pt = vec2(pt.x - k * pt.y, -k * pt.x - pt.y) / 2.0;
  pt.x -= clamp(pt.x, -2.0 * radius, 0.0);
  return -length(pt) * sign(pt.y);
}

// SDF for circle
float circleSDF(vec2 pt, float radius) {
  return length(pt) - radius;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;

  // Base noise for lava flow
  vec2 flowOffset = vec2(time * 0.1, time * 0.07);
  float lavaFlow = fbm(p * 2.0 + flowOffset, 5);
  float crackNoise = fbm(p * 4.0 - flowOffset * 0.5, 6);

  // Sri Yantra: nested rotating triangle pairs
  float sacredGeom = 0.0;

  // 4 pairs of upward/downward triangles at different scales
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float scale = 0.3 + fi * 0.2;
    float rotAng = time * (0.1 + fi * 0.03) * (mod(fi, 2.0) < 1.0 ? 1.0 : -1.0);
    rotAng += bassVal * 0.2 * fi;

    float ca = cos(rotAng);
    float sa = sin(rotAng);
    vec2 rotP = vec2(ca * p.x - sa * p.y, sa * p.x + ca * p.y);

    // Upward triangle
    float triUp = triangleSDF(rotP, scale);
    // Downward triangle (flip y)
    float triDown = triangleSDF(vec2(rotP.x, -rotP.y), scale * 0.95);

    // Edge glow
    float edgeUp = smoothstep(0.02 + trebleVal * 0.01, 0.0, abs(triUp));
    float edgeDown = smoothstep(0.02 + trebleVal * 0.01, 0.0, abs(triDown));

    sacredGeom += (edgeUp + edgeDown) * (1.0 - fi * 0.15);
  }

  // Flower of life: 6-fold circles
  float flowerGeom = 0.0;
  float flowerRadius = 0.4 + midsVal * 0.1;

  // Central circle
  float center = circleSDF(p, flowerRadius * 0.5);
  flowerGeom += smoothstep(0.02, 0.0, abs(center));

  // 6 surrounding circles
  for (int i = 0; i < 6; i++) {
    float ang = float(i) / 6.0 * 6.2832 + time * 0.05;
    vec2 offset = vec2(cos(ang), sin(ang)) * flowerRadius * 0.5;
    float circ = circleSDF(p - offset, flowerRadius * 0.5);
    flowerGeom += smoothstep(0.015, 0.0, abs(circ));
  }

  // Combine sacred geometry
  float geomMask = clamp(sacredGeom + flowerGeom * 0.7, 0.0, 1.0);

  // Lava temperature: geometry lines are hottest
  float temperature = lavaFlow * 0.4 + geomMask * 0.6;
  temperature += bassVal * 0.2; // Bass pulses lava brightness

  // Crack darkness (crust)
  float cracks = smoothstep(0.4, 0.6, crackNoise);
  temperature *= 1.0 - cracks * 0.5 * (1.0 - geomMask);

  // Energy adds overall heat
  temperature += uEnergy * uSensitivity * 0.15;
  temperature = clamp(temperature, 0.0, 1.0);

  // Color from temperature ramp
  vec3 col = lavaRamp(temperature);

  // Palette shift
  float hueShift = uPalette * 0.3;
  col = mix(col, col.gbr, hueShift * 0.3);

  // Geometry edge glow (extra bright white-hot)
  col += vec3(1.0, 0.9, 0.7) * geomMask * 0.3;

  // Subtle embers (floating particles)
  for (int i = 0; i < 15; i++) {
    float fi = float(i);
    vec2 emberPos = vec2(
      sin(time * 0.3 + fi * 2.1) * 1.2,
      cos(time * 0.25 + fi * 1.7) * 1.2 + mod(time * 0.5 + fi * 0.4, 3.0) - 1.5
    );
    float emberGlow = exp(-length(p - emberPos) * length(p - emberPos) * 20.0);
    col += vec3(1.0, 0.6, 0.1) * emberGlow * 0.3;
  }

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Kick flash
  col += vec3(1.0, 0.5, 0.1) * uKick * uSensitivity * 0.3;

  // Onset cracks widen
  col += lavaRamp(0.8) * uOnset * uSensitivity * cracks * 0.5;

  // Spectral flux adds heat shimmer
  col += vec3(0.2, 0.1, 0.0) * uSpectralFlux * uSensitivity * 0.3;

  // Warmth tint
  col = mix(col, col * vec3(1.15, 1.0, 0.85), uWarmth * uSensitivity * 0.2);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFieldStrength;
uniform float uPoleDistance;
uniform float uParticleDensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Magnetic field vector from a single pole
vec2 fieldFromPole(vec2 p, vec2 pole, float strength) {
  vec2 d = p - pole;
  float r2 = dot(d, d) + 0.001;
  return d * strength / (r2 * sqrt(r2));
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Two magnetic poles, distance modulated by beat
  float poleDist = uPoleDistance * (1.0 + beatPulse * 0.3);
  vec2 northPole = vec2(-poleDist * 0.5, sin(time * 0.3) * uChaos * 0.2);
  vec2 southPole = vec2(poleDist * 0.5, -sin(time * 0.3) * uChaos * 0.2);

  // Compute combined field (dipole)
  float strength = uFieldStrength * (1.0 + bassVal * 0.8);
  vec2 fieldN = fieldFromPole(p, northPole, strength);
  vec2 fieldS = fieldFromPole(p, southPole, -strength);
  vec2 field = fieldN + fieldS;
  float fieldMag = length(field);
  vec2 fieldDir = normalize(field + vec2(0.0001));

  // Field line visualization via stream function (angle difference)
  float angleN = atan(p.y - northPole.y, p.x - northPole.x);
  float angleS = atan(p.y - southPole.y, p.x - southPole.x);
  float fieldLines = sin((angleN - angleS) * 8.0 + uPalette * 3.0);
  fieldLines = pow(abs(fieldLines), 0.3) * 0.8;

  // Iron filings: particles aligned with field direction
  float filingScale = 40.0 + uParticleDensity * 60.0;
  vec2 filingUV = p * filingScale;
  vec2 cell = floor(filingUV);
  vec2 cellFrac = fract(filingUV) - 0.5;

  float filings = 0.0;
  for (int dx = -1; dx <= 1; dx++) {
    for (int dy = -1; dy <= 1; dy++) {
      vec2 neighbor = vec2(float(dx), float(dy));
      vec2 cellPos = cell + neighbor;
      vec2 particleOffset = vec2(hash(cellPos), hash(cellPos + 100.0)) - 0.5;
      particleOffset *= 0.8;
      vec2 diff = cellFrac - neighbor - particleOffset;

      // Align particle along local field direction
      vec2 localField = fieldFromPole((cellPos + particleOffset) / filingScale, northPole, strength)
                      + fieldFromPole((cellPos + particleOffset) / filingScale, southPole, -strength);
      vec2 localDir = normalize(localField + vec2(0.0001));

      // Elongated particle along field direction
      float along = dot(diff, localDir);
      float perp = dot(diff, vec2(-localDir.y, localDir.x));
      float filingShape = exp(-along * along * 80.0 - perp * perp * 600.0);

      // Shimmer with treble
      float shimmer = 0.7 + trebleVal * hash(cellPos + 200.0) * 0.6;
      filings += filingShape * shimmer;
    }
  }

  // Color the field lines
  float hueShift = uPalette * 0.5 + time * 0.1;
  vec3 lineColor = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + hueShift + fieldMag * 2.0));

  // Color the iron filings: metallic grays with colored highlights
  vec3 filingColor = mix(vec3(0.6, 0.6, 0.65), lineColor, 0.3 + midsVal * 0.3);

  // Pole glow
  float distN = length(p - northPole);
  float distS = length(p - southPole);
  vec3 northColor = vec3(0.2, 0.5, 1.0);
  vec3 southColor = vec3(1.0, 0.3, 0.2);
  vec3 glowCol = exp(-distN * distN * 8.0) * northColor + exp(-distS * distS * 8.0) * southColor;
  glowCol *= (1.0 + kickPulse * 1.5);

  // Ferrofluid spike effect near poles
  float spikeN = abs(sin(atan(p.y - northPole.y, p.x - northPole.x) * 8.0 + time * 2.0));
  spikeN = pow(spikeN, 3.0) * smoothstep(0.2, 0.0, distN) * 0.5;
  float spikeS = abs(sin(atan(p.y - southPole.y, p.x - southPole.x) * 8.0 - time * 2.0));
  spikeS = pow(spikeS, 3.0) * smoothstep(0.2, 0.0, distS) * 0.5;

  // Combine
  vec3 col = vec3(0.02, 0.02, 0.04);
  col += lineColor * fieldLines * 0.3;
  col += filingColor * filings * 1.2;
  col += glowCol * 2.0;
  col += northColor * spikeN + southColor * spikeS;

  // Beat flash
  col += vec3(0.15, 0.2, 0.35) * beatPulse * 0.2;

  // Onset disturbance ring
  float disturbR = uOnset * uSensitivity * 2.0;
  float disturbRing = abs(length(p) - disturbR);
  col += vec3(0.4, 0.5, 0.9) * exp(-disturbRing * disturbRing * 50.0) * uOnset * uSensitivity * 0.3;

  // Energy modulation
  col *= (0.7 + uEnergy * uSensitivity * 0.4);
  col *= uIntensity * 1.2;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridGlow;
uniform float uSunSize;

// Hash for sparkle/star effects
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Value noise
float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - f * 2.0);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Cosine palette for rich mandala colors
vec3 mandalaPalette(float t, float offset) {
  float tau = 6.28318;
  float s = fract(t + offset * 0.15);
  float r = 0.5 + 0.5 * cos(tau * (s + 0.0));
  float g = 0.5 + 0.5 * cos(tau * (s + 0.33));
  float b = 0.5 + 0.5 * cos(tau * (s + 0.67));
  return vec3(r, g, b);
}

// Mandala ring pattern with animation
float mandalaRing(float r, float ringR, float width) {
  return smoothstep(width, width * 0.1, abs(r - ringR));
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * (uSpeed * 1.0);

  // Audio signals
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onset = uOnset * uSensitivity;
  float kick = uKick * uSensitivity;
  float energy = uEnergy * uSensitivity;

  // Centered polar coordinates
  vec2 centered = (uv - 0.5) * (uZoom * 2.0 + 1.0);
  float r = length(centered);
  float angle = atan(centered.y, centered.x);

  // === PULSING/BREATHING SCALE ANIMATION ===
  float breathe = 1.0 + sin(time * 0.4) * 0.06 + sin(time * 0.23) * 0.04;
  float beatBreathe = 1.0 + beatPulse * 0.12;
  r *= breathe * beatBreathe;

  // === MANDALA LAYER 1: Inner ring pattern (fastest rotation) ===
  float rot1 = time * 0.8 + bassVal * 0.5;
  float a1 = angle + rot1;
  float folds1 = 12.0;
  float sector1 = mod(a1, 6.28318 / folds1);
  float symAngle1 = abs(sector1 - 3.14159 / folds1);
  float pattern1 = sin(symAngle1 * folds1 * 2.0 + r * 15.0 - time * 2.0) * 0.5 + 0.5;
  pattern1 *= smoothstep(0.5, 0.1, abs(r - 0.15 - sin(time * 0.7) * 0.03));
  float colorPhase1 = fract(r * 3.0 - time * 0.3 + symAngle1 * 0.5);
  vec3 col1 = mandalaPalette(colorPhase1, uPalette) * pattern1;

  // === MANDALA LAYER 2: Middle ring (medium rotation, opposite direction) ===
  float rot2 = -time * 0.5 + midsVal * 0.35;
  float a2 = angle + rot2;
  float folds2 = 16.0;
  float sector2 = mod(a2, 6.28318 / folds2);
  float symAngle2 = abs(sector2 - 3.14159 / folds2);
  float pattern2 = sin(symAngle2 * folds2 * 1.5 + r * 10.0 + time * 1.5) * 0.5 + 0.5;
  pattern2 *= sin(r * 20.0 - time * 1.2) * 0.3 + 0.7;
  pattern2 *= smoothstep(0.8, 0.15, abs(r - 0.3 - sin(time * 0.5) * 0.05));
  float colorPhase2 = fract(r * 2.0 + time * 0.2 + symAngle2 * 0.3);
  vec3 col2 = mandalaPalette(colorPhase2 + 0.33, uPalette) * pattern2 * 0.9;

  // === MANDALA LAYER 3: Outer ring (slow rotation, detailed) ===
  float rot3 = time * 0.15 + trebleVal * 0.15;
  float a3 = angle + rot3;
  float folds3 = 8.0 + floor(uChaos * 6.0);
  float sector3 = mod(a3, 6.28318 / folds3);
  float symAngle3 = abs(sector3 - 3.14159 / folds3);
  // Petal shape
  float petalR = 0.45 + sin(a3 * folds3) * 0.08 + cos(a3 * folds3 * 2.0 + time * 0.8) * 0.04;
  float pattern3 = smoothstep(0.12, 0.02, abs(r - petalR));
  pattern3 += smoothstep(0.08, 0.01, abs(r - petalR * 0.85)) * 0.5;
  float colorPhase3 = fract(symAngle3 * 2.0 + time * 0.15 + r * 1.5);
  vec3 col3 = mandalaPalette(colorPhase3 + 0.67, uPalette) * pattern3 * 0.85;

  // === MANDALA LAYER 4: Outermost decorative border (very slow, phase-shifted) ===
  float rot4 = -time * 0.08;
  float a4 = angle + rot4;
  float folds4 = 24.0;
  float sector4 = mod(a4, 6.28318 / folds4);
  float symAngle4 = abs(sector4 - 3.14159 / folds4);
  float dotPattern = smoothstep(0.03, 0.01, length(vec2(symAngle4, r - 0.6 - sin(time * 0.3) * 0.02) * vec2(3.0, 1.0)));
  dotPattern += smoothstep(0.025, 0.008, length(vec2(symAngle4, r - 0.68 - cos(time * 0.4) * 0.015) * vec2(4.0, 1.0))) * 0.7;
  float colorPhase4 = fract(angle * 0.5 / 3.14159 + time * 0.1);
  vec3 col4 = mandalaPalette(colorPhase4 + 0.5, uPalette + 1.0) * dotPattern * 0.8;

  // === COLOR WAVE ANIMATIONS (rippling outward) ===
  float colorWave = sin(r * 30.0 - time * 4.5) * 0.5 + 0.5;
  float colorWave2 = sin(r * 15.0 - time * 2.0 + 1.5) * 0.5 + 0.5;
  vec3 waveColor = mandalaPalette(fract(r * 2.0 - time * 0.5), uPalette + 0.5) * colorWave * 0.15;
  waveColor += mandalaPalette(fract(r * 1.5 + time * 0.3), uPalette + 1.5) * colorWave2 * 0.1;
  // Ripple from center on kick
  float kickRipple = sin(r * 30.0 - uTime * 8.0) * 0.5 + 0.5;
  kickRipple *= kick * smoothstep(0.8, 0.0, r);
  waveColor += vec3(kickRipple * 0.3, kickRipple * 0.15, kickRipple * 0.4);

  // === SPARKLE/PARTICLE EFFECTS ON BEAT ===
  float sparkle = 0.0;
  // Hash-based sparkle points that light up on beat
  vec2 sparkleP = vUv * 60.0;
  float sparkleHash = hash21(floor(sparkleP));
  vec2 sparkleFrac = fract(sparkleP) - 0.5;
  float sparkleDist = length(sparkleFrac);
  // Only sparkle near mandala patterns
  float mandalaPresence = clamp(pattern1 + pattern2 + pattern3 + dotPattern, 0.0, 1.0);
  float sparkleThreshold = 0.94 - onset * 0.15;
  float sparkleVal = smoothstep(0.04, 0.0, sparkleDist) * step(sparkleThreshold, sparkleHash) * mandalaPresence;
  // Animated flash
  float sparkleFlash = sin(uTime * 10.0 + sparkleHash * 50.0) * 0.5 + 0.5;
  sparkle = sparkleVal * sparkleFlash * (1.0 + beatPulse * 3.0);
  vec3 sparkleCol = vec3(1.0, 0.95, 0.85) * sparkle;

  // === BACKGROUND: subtle radial gradient ===
  vec3 bgInner = vec3(0.02, 0.01, 0.05);
  vec3 bgOuter = vec3(0.0, 0.0, 0.02);
  vec3 bg = mix(bgInner, bgOuter, smoothstep(0.0, 1.0, r));

  // === CONCENTRIC RING ACCENTS ===
  float ring1 = mandalaRing(r, 0.2 + sin(time * 0.6) * 0.02, 0.015 + bassVal * 0.01);
  float ring2 = mandalaRing(r, 0.38 + cos(time * 0.4) * 0.02, 0.012);
  float ring3 = mandalaRing(r, 0.55 + sin(time * 0.35) * 0.015, 0.01);
  float ring4 = mandalaRing(r, 0.7, 0.008);
  vec3 ringCol = mandalaPalette(fract(time * 0.1 + r), uPalette + 2.0);
  vec3 rings = ringCol * (ring1 + ring2 + ring3 + ring4) * (uGridGlow * 1.2);

  // === CENTER GLOW ===
  float centerGlow = smoothstep(0.15, 0.0, r) * (0.5 + bassVal * 0.5 + beatPulse * 0.3);
  vec3 centerCol = mandalaPalette(fract(time * 0.15), uPalette) * centerGlow * (uSunSize + 0.5);

  // === COMPOSE ===
  vec3 finalCol = bg;
  finalCol += col1;
  finalCol += col2;
  finalCol += col3;
  finalCol += col4;
  finalCol += waveColor;
  finalCol += rings;
  finalCol += centerCol;
  finalCol += sparkleCol;

  // Apply overall intensity
  finalCol *= uIntensity * 1.4;

  // Energy vibrancy
  finalCol *= 1.0 + energy * 0.2;

  // Onset flash: brief burst
  float flash = onset * 0.2;
  finalCol += vec3(flash * 0.6, flash * 0.4, flash * 0.8);

  // Slight vignette
  float vignette = 1.0 - smoothstep(0.5, 1.2, r);
  finalCol *= mix(0.6, 1.0, vignette);

  // Ensure never fully black at center
  finalCol += vec3(0.008, 0.005, 0.015);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uZoomDepth;
uniform float uIterScale;
uniform float uEscapeRadius;

#define PI 3.14159265359
#define TAU 6.28318530718

vec3 mandelbrotPalette(float t, float offset) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(0.0 + offset * 0.08, 0.1, 0.2);
  return a + b * cos(TAU * (c * t + d));
}

// Interesting zoom targets on the Mandelbrot boundary
vec2 zoomTarget(float idx) {
  if (idx < 1.0) return vec2(-0.7463, 0.1102);
  if (idx < 2.0) return vec2(0.2819, 0.0100);
  if (idx < 3.0) return vec2(-0.1011, 0.9563);
  if (idx < 4.0) return vec2(-1.7497, 0.0);
  return vec2(-0.1592, 1.0335);
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  float time = uTime * uSpeed * 0.5;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onsetFlash = uOnset * uSensitivity * 1.5;
  float kickVal = uKick * uSensitivity * 1.5;

  // Auto-zoom: cycle through interesting locations
  float locationCycle = time * 0.05;
  float locIdx = floor(mod(locationCycle, 5.0));
  float locBlend = smoothstep(0.0, 1.0, fract(locationCycle));
  vec2 target1 = zoomTarget(locIdx);
  vec2 target2 = zoomTarget(mod(locIdx + 1.0, 5.0));
  vec2 center = mix(target1, target2, locBlend);

  // Zoom depth: exponential, bass deepens
  float depth = uZoomDepth * 8.0 + 2.0;
  float zoomLevel = exp(mod(time * 0.5, depth)) * (uZoom * 0.5 + 0.5);
  zoomLevel += beatPulse * zoomLevel * 0.1;

  vec2 uv = (vUv - 0.5) * 2.0;

  // Rotation
  float rotAngle = time * 0.1 + uChaos * sin(time * 0.2) * 0.5;
  float cr = cos(rotAngle), sr = sin(rotAngle);
  uv = vec2(uv.x * cr - uv.y * sr, uv.x * sr + uv.y * cr);

  vec2 c = center + uv / zoomLevel;

  // Iteration count: treble adds detail
  float maxIterF = 100.0 * uIterScale + trebleVal * 50.0;
  int maxIter = int(min(maxIterF, 200.0));
  float escape = uEscapeRadius * uEscapeRadius;

  vec2 z = vec2(0.0);
  float iter = 0.0;
  float trap = 1e10;

  for (int i = 0; i < 200; i++) {
    if (i >= maxIter) break;
    if (dot(z, z) > escape) break;
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    float r2 = dot(z, z);

    // Orbit traps
    trap = min(trap, length(z - vec2(-1.0, 0.0)));
    trap = min(trap, abs(z.x));
    trap = min(trap, abs(z.y));

    iter += 1.0;
  }

  float r2 = dot(z, z);
  bool escaped = r2 > escape;

  // Smooth iteration count
  float smoothIter = iter;
  if (escaped) {
    float log_zn = log(r2) * 0.5;
    float nu = log(log_zn / log(2.0)) / log(2.0);
    smoothIter = iter + 1.0 - nu;
  }

  vec3 col;

  if (escaped) {
    float colorT = fract(smoothIter * 0.02 + time * 0.08 + bassVal * 0.15 + sin(uTime * 0.2) * 0.15);
    col = mandelbrotPalette(colorT, uPalette);

    float brightness = 1.0 - smoothstep(0.0, float(maxIter) * 0.5, smoothIter);
    col *= 0.3 + brightness * 0.7;

    // Treble enhances fine bands
    float bandDetail = sin(smoothIter * 0.5) * 0.5 + 0.5;
    col += mandelbrotPalette(fract(colorT + 0.3), uPalette) * bandDetail * trebleVal * 0.3;
  } else {
    // Interior: orbit trap coloring
    float trapColor = fract(trap * 2.0 + time * 0.03);
    col = mandelbrotPalette(trapColor, uPalette) * 0.2;
    col += mandelbrotPalette(fract(trap * 5.0), uPalette) * exp(-trap * 3.0) * 0.3;
  }

  // Mids color shift
  col = mix(col, mandelbrotPalette(fract(smoothIter * 0.01 + midsVal * 0.5), uPalette) * length(col), midsVal * 0.2);

  // Beat flash
  col += mandelbrotPalette(fract(time * 0.1), uPalette) * beatPulse * 0.2;

  // Onset
  col += vec3(onsetFlash * 0.08, onsetFlash * 0.05, onsetFlash * 0.1);

  // Kick brightness
  col *= 1.0 + kickVal * 0.2;

  col *= uIntensity * 1.5;

  // Vignette
  float vig = 1.0 - smoothstep(0.5, 1.2, length(vUv - 0.5) * 1.4);
  col *= vig;

  col += vec3(0.005, 0.003, 0.008);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFractalPower;
uniform float uOrbitSpeed;
uniform float uDetailLevel;
uniform float uGlowAmount;

// Mandelbulb distance estimator
vec2 mandelbulbDE(vec3 pos, float power) {
  vec3 z = pos;
  float dr = 1.0;
  float r = 0.0;
  float trap = 1e10;

  for (int i = 0; i < 10; i++) {
    r = length(z);
    if (r > 2.0) break;

    // Convert to polar
    float theta = acos(z.z / r);
    float phi = atan(z.y, z.x);
    dr = pow(r, power - 1.0) * power * dr + 1.0;

    // Scale and rotate
    float zr = pow(r, power);
    theta *= power;
    phi *= power;

    // Convert back
    z = zr * vec3(sin(theta) * cos(phi), sin(theta) * sin(phi), cos(theta));
    z += pos;

    trap = min(trap, length(z));
  }
  return vec2(0.5 * log(r) * r / dr, trap);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float kickVal = uKick * uSensitivity * 1.5;
  float energyVal = uEnergy * uSensitivity * 1.5;

  // Fractal power driven by bass
  float power = 6.0 + uFractalPower * 4.0 + bassVal * 2.0 + sin(time * 0.2) * 0.5;

  // Camera orbit
  float orbitAngle = time * uOrbitSpeed + uBpmSin * 0.3;
  float camDist = 2.0 / (uZoom + 1.0);
  float camHeight = sin(time * 0.15) * 0.5;

  // Kick triggers position jump
  float jumpAngle = kickVal * 0.5;
  orbitAngle += jumpAngle;

  vec3 ro = vec3(
    cos(orbitAngle) * camDist,
    camHeight + sin(orbitAngle * 0.7) * 0.3,
    sin(orbitAngle) * camDist
  );

  vec3 lookAt = vec3(0.0);
  vec3 forward = normalize(lookAt - ro);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);
  vec3 rd = normalize(forward + right * p.x + up * p.y);

  // === RAYMARCHING ===
  vec3 col = vec3(0.0);
  float t = 0.0;
  float glow = 0.0;
  float minDist = 1e10;

  for (int i = 0; i < 80; i++) {
    vec3 pos = ro + rd * t;
    vec2 de = mandelbulbDE(pos, power);
    float d = de.x;

    // Accumulate glow
    glow += 0.02 / (1.0 + d * d * 100.0);
    minDist = min(minDist, d);

    if (d < 0.001 * t) {
      // Hit! Estimate normal
      vec2 e = vec2(0.001, 0.0);
      vec3 n = normalize(vec3(
        mandelbulbDE(pos + e.xyy, power).x - mandelbulbDE(pos - e.xyy, power).x,
        mandelbulbDE(pos + e.yxy, power).x - mandelbulbDE(pos - e.yxy, power).x,
        mandelbulbDE(pos + e.yyx, power).x - mandelbulbDE(pos - e.yyx, power).x
      ));

      // Orbit trap coloring
      float trap = de.y;
      vec3 trapColor = 0.5 + 0.5 * cos(6.2832 * (trap * 2.0 + uPalette + vec3(0.0, 0.3, 0.6)));

      // Lighting
      vec3 lightDir = normalize(vec3(1.0, 1.0, -0.5));
      float diff = max(dot(n, lightDir), 0.0);
      float amb = 0.2 + 0.1 * n.y;
      float spec = pow(max(dot(reflect(-lightDir, n), -rd), 0.0), 16.0);

      // Treble reveals fine detail
      float detail = 1.0 + trebleVal * 0.5;
      float ao = 1.0 - float(64 - int(glow * 50.0)) * 0.01 * uDetailLevel;
      ao = clamp(ao, 0.3, 1.0);

      col = trapColor * (amb + diff * 0.6) * detail;
      col += spec * vec3(1.0, 0.9, 0.8) * 0.3;
      col *= ao;

      // Depth fog
      col = mix(col, vec3(0.01, 0.0, 0.03), 1.0 - exp(-t * 0.3));

      break;
    }
    if (t > 8.0) break;
    t += d * (0.5 + uDetailLevel * 0.3);
  }

  // Volumetric glow
  vec3 glowColor = 0.5 + 0.5 * cos(6.2832 * (time * 0.08 + uPalette + vec3(0.0, 0.33, 0.67) + sin(uTime * 0.2) * 0.15));
  col += glow * glowColor * uGlowAmount * 0.5;

  // Near-miss glow
  float nearGlow = exp(-minDist * 20.0) * 0.2 * uGlowAmount;
  col += nearGlow * glowColor;

  // Energy brightness
  col *= 0.7 + energyVal * 0.5;

  // BPM color shift
  col = mix(col, col.brg, uBpmSin2 * 0.1);

  // Kick flash
  col += kickVal * vec3(0.15, 0.05, 0.1) * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uColumnCount;
uniform float uTrailLength;
uniform float uFallSpeed;
uniform float uFlickerRate;

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

float hash21b(vec2 p) {
  float h = dot(p, vec2(269.5, 183.3));
  return fract(sin(h) * 28461.6521);
}

void main() {
  // Use raw UV (0-1) directly — no centering, no offset. Full screen coverage.
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 3.0);

  // Audio modulators
  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float beatPulse = uBeat * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Grid dimensions — higher density to fill the screen
  float cols = uColumnCount * (uZoom * 0.5 + 1.0);
  float rowScale = cols * 2.0;  // taller cells for better coverage
  float colIdx = floor(p.x * cols);
  float rowIdx = floor(p.y * rowScale);

  // Per-column randomness
  vec2 colSeed = vec2(colIdx, 0.0);
  float colRand = hash21(colSeed);
  float colRand2 = hash21b(colSeed);
  float colSpeed = (0.5 + colRand * 1.0) * uFallSpeed;
  float colPhase = colRand2 * 100.0;

  // Energy and bass influence on speed
  float speedMod = 1.0 + energyVal * 0.5;

  // Multiple rain layers per column (staggered heads) for denser fill
  float headRaw1 = fract(time * colSpeed * speedMod * 0.08 + colPhase);
  float headRaw2 = fract(time * colSpeed * speedMod * 0.08 + colPhase + 0.33);
  float headRaw3 = fract(time * colSpeed * speedMod * 0.08 + colPhase + 0.66);
  float headY1 = 1.0 - headRaw1;
  float headY2 = 1.0 - headRaw2;
  float headY3 = 1.0 - headRaw3;

  // Current cell fractional y position
  float cellY = rowIdx / rowScale;

  // Trail length influenced by bass
  float trailLen = uTrailLength + bassVal * 0.25;

  // Distance from each head (three overlapping rain trails per column)
  float wrappedDist1 = fract(headY1 - cellY + 1.0);
  float wrappedDist2 = fract(headY2 - cellY + 1.0);
  float wrappedDist3 = fract(headY3 - cellY + 1.0);

  // Trail brightness for each layer
  float trailFade1 = smoothstep(trailLen, 0.0, wrappedDist1);
  float trailFade2 = smoothstep(trailLen * 0.7, 0.0, wrappedDist2) * 0.6;
  float trailFade3 = smoothstep(trailLen * 0.5, 0.0, wrappedDist3) * 0.3;
  float trailFade = clamp(trailFade1 + trailFade2 + trailFade3, 0.0, 1.0);

  float headBright1 = smoothstep(0.02, 0.0, wrappedDist1);
  float headBright2 = smoothstep(0.02, 0.0, wrappedDist2) * 0.5;
  float headBright = clamp(headBright1 + headBright2, 0.0, 1.0);

  // Per-cell pseudo-random brightness
  vec2 cellSeed = vec2(colIdx, rowIdx);
  float cellRand = hash21(cellSeed);
  vec2 flickerSeed = vec2(colIdx + time * uFlickerRate, rowIdx + time * (uFlickerRate * 0.7));
  float flickerVal = hash21(flickerSeed);
  float cellBright = mix(cellRand, flickerVal, 0.5 + trebleVal * 0.5);

  float inTrail = trailFade;
  float charBright = cellBright * inTrail;

  // === COLOR ===
  float greenBase = 0.6 + trailFade * 0.4;
  float headWhite = headBright * 0.8;

  float matrixR = headWhite * charBright;
  float matrixG = greenBase * charBright + headWhite * charBright * 0.5;
  float matrixB = headWhite * charBright * 0.3 + uPalette * 0.02 * charBright;

  float colorR = matrixR * (uIntensity * 1.5);
  float colorG = matrixG * (uIntensity * 1.5);
  float colorB = matrixB * (uIntensity * 1.5);

  // Beat flash
  float flashGreen = beatPulse * 0.2 * inTrail;

  // Kick flash
  float kickFlash = kickVal * 0.15 * charBright;

  // Mids glow
  float midsGlow = midsVal * 0.08 * inTrail;

  // No vignette — full edge-to-edge coverage

  // Scanline (subtle CRT effect)
  float scanline = sin(p.y * rowScale * 3.14159) * 0.5 + 0.5;
  float scanMod = 0.88 + scanline * 0.12;

  // Chaos — random bright flashes in columns
  vec2 chaosSeed = vec2(colIdx, floor(time * 0.5));
  float chaosRand = hash21(chaosSeed);
  float chaosBright = smoothstep(1.0 - uChaos * 0.3, 1.0, chaosRand) * inTrail * 0.3;

  // Final composite
  float finalR = colorR + kickFlash + chaosBright * 0.3;
  float finalG = colorG + flashGreen + kickFlash + midsGlow + chaosBright;
  float finalB = colorB + kickFlash * 0.3 + chaosBright * 0.2;

  float outR = finalR * scanMod;
  float outG = finalG * scanMod;
  float outB = finalB * scanMod;

  float bgG = 0.005;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(outR, outG, outB)); outR = _pc.r; outG = _pc.g; outB = _pc.b; }
  gl_FragColor = vec4(
    clamp(outR, 0.0, 1.0),
    clamp(outG + bgG, 0.0, 1.0),
    clamp(outB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash1(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash1(i);
  float b = hash1(i + vec2(1.0, 0.0));
  float c = hash1(i + vec2(0.0, 1.0));
  float d = hash1(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm4(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 4; i++) {
    v += amp * vnoise(p);
    p = rot * p * 2.1 + vec2(5.3, 2.7);
    amp *= 0.5;
  }
  return v;
}

// Acid palette: neon green, hot pink, electric blue
vec3 acidPalette(float t, float shift) {
  float phase = t * 6.2832 + shift;
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 0.7, 0.4);
  vec3 d = vec3(0.0, 0.15, 0.2);
  vec3 base = a + b * cos(6.2832 * (c * t + d + shift));
  // Push toward neon green / hot pink / electric blue
  base.g = base.g * 0.7 + 0.3 * (0.5 + 0.5 * sin(phase * 1.3));
  base.r = base.r * 0.6 + 0.4 * (0.5 + 0.5 * sin(phase * 0.7 + 2.0));
  base.b = base.b * 0.6 + 0.4 * (0.5 + 0.5 * cos(phase * 0.9));
  return base;
}

// Grid pattern with adjustable softness
float gridPattern(vec2 p, float lineWidth) {
  vec2 g = abs(fract(p) - 0.5);
  float gx = smoothstep(lineWidth, lineWidth * 0.3, g.x);
  float gy = smoothstep(lineWidth, lineWidth * 0.3, g.y);
  return max(gx, gy);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.5) * 0.05, cos(p.x * 3.5 + time * 0.4) * 0.05);

  // Audio-reactive modulators — 2x
  float bassVal = bass() * uSensitivity * 1.6;
  float midsVal = mids() * uSensitivity * 1.4;
  float trebleVal = treble() * uSensitivity * 1.6;
  float beatPulse = uBeat * uSensitivity * 2.0;
  float onsetFlash = uOnset * uSensitivity * 2.0;
  float kickVal = uKick * uSensitivity * 2.0;
  float energyVal = uEnergy * uSensitivity * 1.4;

  // === DOMAIN WARP: the core melt effect ===
  float meltStrength = 0.3 + bassVal * 0.8 + uChaos * 0.4;

  // First warp layer: slow, large-scale melt
  vec2 warp1 = vec2(
    fbm4(p * 1.5 + time * vec2(0.1, -0.3)),
    fbm4(p * 1.5 + time * vec2(-0.2, 0.15) + vec2(50.0))
  );

  // Second warp layer: finer melt detail
  vec2 warp2 = vec2(
    fbm4((p + warp1 * meltStrength) * 2.5 + time * vec2(0.05, -0.2)),
    fbm4((p + warp1 * meltStrength) * 2.5 + time * vec2(-0.1, 0.08) + vec2(100.0))
  );

  // Gravity drip: bias warp downward
  float dripBias = 0.4 + bassVal * 0.5;
  warp2.y += dripBias * vnoise(vec2(p.x * 6.0, time * 0.5)) * meltStrength;

  // Combined warped position
  vec2 melted = p + warp1 * meltStrength * 0.5 + warp2 * meltStrength * 0.3;

  // === GEOMETRIC GRID (melting) ===
  float gridScale = 4.0 + midsVal;
  float lineW = 0.08 + trebleVal * 0.03;
  float grid = gridPattern(melted * gridScale, lineW);

  // Grid color from acid palette — faster cycling
  float colorIdx = fbm4(melted * 0.8 + time * 0.1) + sin(uTime * 0.3) * 0.2;
  vec3 gridCol = acidPalette(colorIdx, uPalette) * grid;

  // Grid cell fill with different hue
  float cellColor = fbm4(floor(melted * gridScale) * 0.3 + time * 0.05);
  vec3 cellFill = acidPalette(cellColor + 0.33, uPalette + 1.0) * 0.3 * (1.0 - grid);

  // === INDEPENDENT DRIP STREAKS ===
  float dripCount = 12.0;
  float dripTotal = 0.0;
  vec3 dripColorAccum = vec3(0.0);
  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float dripX = (fi / dripCount - 0.5) * 3.0 + sin(fi * 1.7 + time * 0.3) * 0.2;
    float dripSpeed = 0.5 + hash1(vec2(fi, 0.0)) * 1.5 + bassVal * 2.0;
    float dripY = fract(time * dripSpeed * 0.15 + hash1(vec2(fi, 5.0))) * 4.0 - 2.0;
    float dripW = 0.02 + hash1(vec2(fi, 10.0)) * 0.03;

    // Drip is a vertical smear
    float dx = abs(p.x - dripX);
    float dy = p.y - dripY;
    float dripLen = 0.3 + hash1(vec2(fi, 15.0)) * 0.5 + bassVal * 0.3;
    float streak = smoothstep(dripW, 0.0, dx) * smoothstep(dripLen, 0.0, dy) * smoothstep(-0.02, 0.05, dy);

    dripTotal += streak;
    vec3 dripHue = acidPalette(fi * 0.12 + time * 0.05, uPalette + 2.0);
    dripColorAccum += dripHue * streak;
  }

  // === BEAT SPLATTER ===
  float splatAngle = atan(p.y, p.x);
  float splatR = length(p);
  float splatNoise = vnoise(vec2(splatAngle * 4.0, splatR * 6.0) + time * 1.5);
  float splat = beatPulse * smoothstep(0.65, 1.0, splatNoise) * smoothstep(2.0, 0.0, splatR);
  vec3 splatCol = acidPalette(splatNoise + 0.5, uPalette + 3.0) * splat * 1.5;

  // === MELT GLOW: luminous edges where warp is strongest ===
  float warpMag = length(warp2) * meltStrength;
  float meltGlow = smoothstep(0.1, 0.6, warpMag) * 0.4;
  vec3 meltGlowCol = acidPalette(warpMag * 2.0 + time * 0.1, uPalette) * meltGlow;

  // === TREBLE MICRO-DRIPS ===
  float fineDrip = vnoise(vec2(p.x * 35.0, p.y * 3.0 - time * 3.0));
  fineDrip = smoothstep(0.82, 1.0, fineDrip) * trebleVal;
  vec3 fineDripCol = vec3(0.2, 1.0, 0.4) * fineDrip * 0.6;

  // === ONSET FLASH ===
  vec3 flashCol = vec3(1.0, 0.3, 0.8) * onsetFlash * 0.25;

  // === KICK RIPPLE ===
  float kickRipple = sin(length(p) * 15.0 - kickVal * 10.0) * kickVal * 0.15;
  vec3 kickCol = vec3(0.1, 0.4, 1.0) * kickRipple;

  // === COMBINE ===
  vec3 col = gridCol + cellFill + dripColorAccum * 0.7 + splatCol
    + meltGlowCol + fineDripCol + flashCol + kickCol;

  // Energy brightness boost
  col *= (0.7 + energyVal * 0.4);

  // Saturation boost for psychedelic feel — 2x
  float luma = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(luma), col, 2.0);

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCrossScale;

vec3 spongePalette(float t, float offset) {
  float tau = 6.28318;
  float shifted = t + offset * 0.1;
  float r = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.05));
  float g = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.35));
  float b = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.55));
  return vec3(r, g, b);
}

float crossSDF(float px, float py, float pz, float cs) {
  float crossXY = max(abs(px), abs(py)) - cs;
  float crossXZ = max(abs(px), abs(pz)) - cs;
  float crossYZ = max(abs(py), abs(pz)) - cs;
  return min(min(crossXY, crossXZ), crossYZ);
}

vec3 mengerSDF(vec3 pos, float bassVal) {
  float boxSize = 1.0;
  float px = pos.x;
  float py = pos.y;
  float pz = pos.z;

  // Box SDF
  float bx = abs(px) - boxSize;
  float by = abs(py) - boxSize;
  float bz = abs(pz) - boxSize;
  float d = min(max(max(bx, by), bz), 0.0)
    + length(vec3(max(bx, 0.0), max(by, 0.0), max(bz, 0.0)));

  float s = 1.0;
  float trap = 100.0;
  float crossScaleModulated = uCrossScale + bassVal * 0.2;

  // Iteration 1
  px = fract(px * s * 0.5 + 0.5) * 2.0 - 1.0;
  py = fract(py * s * 0.5 + 0.5) * 2.0 - 1.0;
  pz = fract(pz * s * 0.5 + 0.5) * 2.0 - 1.0;
  s *= 3.0;
  float cross1 = crossSDF(px, py, pz, crossScaleModulated / 3.0);
  d = max(d, -cross1 / s);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Iteration 2
  px = fract(px * 1.5 + 0.5) * 2.0 - 1.0;
  py = fract(py * 1.5 + 0.5) * 2.0 - 1.0;
  pz = fract(pz * 1.5 + 0.5) * 2.0 - 1.0;
  s *= 3.0;
  float cross2 = crossSDF(px, py, pz, crossScaleModulated / 3.0);
  d = max(d, -cross2 / s);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Iteration 3
  px = fract(px * 1.5 + 0.5) * 2.0 - 1.0;
  py = fract(py * 1.5 + 0.5) * 2.0 - 1.0;
  pz = fract(pz * 1.5 + 0.5) * 2.0 - 1.0;
  s *= 3.0;
  float cross3 = crossSDF(px, py, pz, crossScaleModulated / 3.0);
  d = max(d, -cross3 / s);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  // Iteration 4
  px = fract(px * 1.5 + 0.5) * 2.0 - 1.0;
  py = fract(py * 1.5 + 0.5) * 2.0 - 1.0;
  pz = fract(pz * 1.5 + 0.5) * 2.0 - 1.0;
  s *= 3.0;
  float cross4 = crossSDF(px, py, pz, crossScaleModulated / 3.0);
  d = max(d, -cross4 / s);
  trap = min(trap, abs(px) + abs(py) + abs(pz));

  return vec3(d, trap, 0.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.2);
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;

  // Camera: orbit around the sponge — close up to fill screen
  float orbitAngle = time * 0.25 + uChaos * sin(time * 0.07);
  float camDist = 1.6 + sin(time * 0.12) * 0.3;
  float camX = cos(orbitAngle) * camDist;
  float camZ = sin(orbitAngle) * camDist;
  float camY = sin(time * 0.1) * 1.5 + 0.5;
  vec3 ro = vec3(camX, camY, camZ);

  // Look-at camera
  vec3 target = vec3(0.0, 0.0, 0.0);
  vec3 forward = normalize(target - ro);
  vec3 worldUp = vec3(0.0, 1.0, 0.0);
  vec3 right = normalize(cross(forward, worldUp));
  vec3 up = cross(right, forward);

  float fov = (uZoom + 0.5) * 2.0;
  vec3 rd = normalize(right * p.x * fov + up * p.y * fov + forward);

  // Sphere trace: 25 steps
  float t = 0.01;
  float trap = 100.0;
  float minDist = 100.0;
  float steps = 0.0;
  vec3 lastPos = ro;

  for (int i = 0; i < 32; i++) {
    lastPos = ro + rd * t;
    vec3 result = mengerSDF(lastPos, bassVal);
    minDist = min(minDist, result.x);
    trap = min(trap, result.y);
    t += result.x * 0.9;
    steps += 1.0;
  }

  // Approximate normal via gradient (central difference)
  float eps = 0.002;
  float nxp = mengerSDF(lastPos + vec3(eps, 0.0, 0.0), bassVal).x;
  float nxn = mengerSDF(lastPos - vec3(eps, 0.0, 0.0), bassVal).x;
  float nyp = mengerSDF(lastPos + vec3(0.0, eps, 0.0), bassVal).x;
  float nyn = mengerSDF(lastPos - vec3(0.0, eps, 0.0), bassVal).x;
  float nzp = mengerSDF(lastPos + vec3(0.0, 0.0, eps), bassVal).x;
  float nzn = mengerSDF(lastPos - vec3(0.0, 0.0, eps), bassVal).x;
  vec3 normal = normalize(vec3(nxp - nxn, nyp - nyn, nzp - nzn));

  // Lighting: directional light + ambient
  vec3 lightDir = normalize(vec3(0.5, 0.8, -0.3));
  float diff = max(dot(normal, lightDir), 0.0);
  float ambient = 0.2;
  float lighting = diff * 0.7 + ambient;

  // AO
  float ao = 1.0 - steps / 25.0 * 0.6;

  // Color from trap + palette
  float palIdx = fract(trap * 0.25 + uPalette * 0.1 + time * 0.04 + sin(uTime * 0.2) * 0.15);
  vec3 baseColor = spongePalette(palIdx, uPalette);

  // Edge glow from treble
  float edgeGlow = 0.01 / (minDist + 0.003) * 0.1;
  vec3 glowCol = vec3(edgeGlow * trebleVal * 0.5, edgeGlow * 0.3, edgeGlow * midsVal * 0.4);

  // Combine
  vec3 surface = baseColor * lighting * ao + glowCol;

  // Beat + onset pulse
  float pulse = beatPulse * 0.15 + onset * 0.3;
  vec3 pulsed = surface + vec3(pulse, pulse * 0.8, pulse * 1.1);

  // Intensity
  vec3 lit = pulsed * (uIntensity * 1.5);

  // Fog
  float fog = 1.0 - clamp(t / 15.0, 0.0, 1.0);
  vec3 fogged = lit * fog;

  // === PSYCHEDELIC ENHANCEMENT ===
  fogged = psychedelicColor(fogged);
  gl_FragColor = vec4(
    clamp(fogged.x, 0.0, 1.0),
    clamp(fogged.y, 0.0, 1.0),
    clamp(fogged.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSurfaceTension;
uniform float uReflectivity;
uniform float uDropletSpray;

#define PI 3.14159265
#define TAU 6.28318530

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// Smooth metaball potential
float metaball(vec2 p, vec2 center, float radius) {
  float d2 = dot(p - center, p - center);
  return radius * radius / (d2 + 0.0001);
}

// Thin-film interference for rainbow edge colors
vec3 thinFilm(float thickness) {
  float d = thickness * TAU;
  return 0.5 + 0.5 * vec3(
    cos(d),
    cos(d + TAU / 3.0),
    cos(d + 2.0 * TAU / 3.0)
  );
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.3;

  vec3 col = vec3(0.05, 0.06, 0.07);

  // Main mercury drops
  float potential = 0.0;
  float totalColorWeight = 0.0;

  int numDrops = 6;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float seed = fi * 2.618;

    // Drop movement
    vec2 pos = vec2(
      sin(time * 0.3 + seed * 3.0) * 0.5 + sin(time * 0.17 + seed) * 0.2,
      cos(time * 0.25 + seed * 2.0) * 0.4 + cos(time * 0.13 + seed * 1.5) * 0.2
    );

    // Bass wobble
    float wobble = sin(time * 3.0 + fi * 1.5) * bassVal * 0.1;
    pos += vec2(wobble, wobble * 0.7);

    float radius = 0.12 + 0.04 * sin(time * 0.5 + fi);
    radius *= uSurfaceTension * 1.5 + 0.3;

    potential += metaball(p, pos, radius);
  }

  // Small spray droplets on treble
  if (uDropletSpray > 0.1) {
    for (int i = 0; i < 12; i++) {
      float fi = float(i);
      float seed = fi * 1.414 + 100.0;
      vec2 pos = vec2(
        sin(seed * 3.7 + time * 0.8) * 0.7,
        cos(seed * 2.9 + time * 0.6) * 0.7
      );
      float r = 0.02 + trebleVal * 0.02;
      potential += metaball(p, pos, r) * uDropletSpray * trebleVal;
    }
  }

  // Mercury surface
  float threshold = 1.2;
  float mercuryMask = smoothstep(threshold - 0.2, threshold + 0.1, potential);

  if (mercuryMask > 0.01) {
    // Calculate gradient for normal approximation
    float eps = 0.005;
    float px = 0.0, py = 0.0;
    for (int i = 0; i < 6; i++) {
      float fi = float(i);
      float seed = fi * 2.618;
      vec2 pos = vec2(
        sin(time * 0.3 + seed * 3.0) * 0.5 + sin(time * 0.17 + seed) * 0.2,
        cos(time * 0.25 + seed * 2.0) * 0.4 + cos(time * 0.13 + seed * 1.5) * 0.2
      );
      float wobble = sin(time * 3.0 + fi * 1.5) * bassVal * 0.1;
      pos += vec2(wobble, wobble * 0.7);
      float radius = 0.12 + 0.04 * sin(time * 0.5 + fi);
      radius *= uSurfaceTension * 1.5 + 0.3;
      px += metaball(p + vec2(eps, 0.0), pos, radius) - metaball(p - vec2(eps, 0.0), pos, radius);
      py += metaball(p + vec2(0.0, eps), pos, radius) - metaball(p - vec2(0.0, eps), pos, radius);
    }
    vec2 grad = normalize(vec2(px, py) + 0.001);

    // Chrome reflection
    float envAngle = atan(grad.y, grad.x) + time * 0.1;
    float envR = length(grad);

    // Environment map simulation
    float env = noise(vec2(envAngle * 3.0, envR * 2.0 + time * 0.2)) * 0.5 + 0.5;
    vec3 chrome = vec3(0.75, 0.78, 0.82) * (0.4 + env * 0.6) * uReflectivity;

    // Specular highlights
    float spec = pow(max(dot(grad, vec2(0.5, 0.7)), 0.0), 16.0 + uReflectivity * 30.0);
    chrome += vec3(1.0) * spec * uReflectivity * 0.8;

    // Rainbow edge from thin-film interference
    float edgeDist = abs(potential - threshold);
    float filmThick = edgeDist * 3.0 + time * 0.1 + uPalette;
    vec3 rainbow = thinFilm(filmThick) * 0.3;
    float edgeFactor = smoothstep(0.5, 0.0, edgeDist);
    chrome += rainbow * edgeFactor;

    // Spectrum bands affect reflection hue
    chrome.r += uSpectrum1 * uSensitivity * 0.1;
    chrome.g += uSpectrum3 * uSensitivity * 0.1;
    chrome.b += uSpectrum5 * uSensitivity * 0.1;

    col = mix(col, chrome, mercuryMask);
  }

  // Beat highlight
  col += vec3(0.15) * uBeat * uSensitivity * mercuryMask * 0.3;

  // Kick flash
  col += vec3(0.2, 0.22, 0.25) * uKick * uSensitivity * 0.2;

  // Dark surface below
  float surfaceReflect = 0.02 + 0.03 * noise(p * 3.0 + time * 0.1);
  col += vec3(surfaceReflect) * (1.0 - mercuryMask);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashMD(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseMD(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashMD(i);
  float b = hashMD(i + vec2(1.0, 0.0));
  float c = hashMD(i + vec2(0.0, 1.0));
  float d = hashMD(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Sand dune ripple pattern
float duneRipples(vec2 p, float time, float bassVal) {
  float ripple = 0.0;
  ripple += sin(p.x * 8.0 + p.y * 2.0 + time * 0.3) * 0.3;
  ripple += sin(p.x * 15.0 - p.y * 3.0 + time * 0.2) * 0.15;
  ripple += sin(p.x * 3.0 + time * 0.5) * 0.5 * bassVal;
  // Dune height
  float duneH = noiseMD(p * 2.0 + time * 0.05) * 0.3;
  duneH += noiseMD(p * 4.0 - time * 0.03) * 0.15;
  return ripple * 0.1 + duneH;
}

// Saguaro cactus silhouette
float cactus(vec2 p, vec2 base, float sz) {
  vec2 d = p - base;
  // Main trunk
  float trunk = smoothstep(sz * 0.08, sz * 0.03, abs(d.x));
  trunk *= smoothstep(-0.01, 0.0, d.y) * smoothstep(sz * 1.5, sz * 1.4, d.y);
  // Left arm
  vec2 armL = d - vec2(-sz * 0.06, sz * 0.7);
  float armLH = smoothstep(sz * 0.06, sz * 0.02, abs(armL.x));
  armLH *= smoothstep(-0.01, 0.0, armL.y) * smoothstep(sz * 0.5, sz * 0.4, armL.y);
  float armLConnector = smoothstep(sz * 0.06, sz * 0.02, abs(d.y - sz * 0.7));
  armLConnector *= smoothstep(-sz * 0.12, -sz * 0.04, d.x) * smoothstep(sz * 0.04, -sz * 0.04, d.x);
  // Right arm
  vec2 armR = d - vec2(sz * 0.06, sz * 0.5);
  float armRH = smoothstep(sz * 0.06, sz * 0.02, abs(armR.x));
  armRH *= smoothstep(-0.01, 0.0, armR.y) * smoothstep(sz * 0.6, sz * 0.5, armR.y);
  float armRConnector = smoothstep(sz * 0.06, sz * 0.02, abs(d.y - sz * 0.5));
  armRConnector *= smoothstep(sz * 0.12, sz * 0.04, d.x) * smoothstep(sz * 0.04, sz * 0.12, d.x);
  return max(trunk, max(armLH + armLConnector, armRH + armRConnector));
}

// Huichol art geometric pattern overlay
float huicholPattern(vec2 p, float time) {
  float pattern = 0.0;
  // Diamond eyes
  float angle = atan(p.y, p.x);
  float r = length(p);
  float diamonds = abs(sin(angle * 4.0 + time * 0.2)) * abs(cos(angle * 3.0 - time * 0.15));
  diamonds = smoothstep(0.3, 0.35, diamonds) * smoothstep(0.6, 0.55, diamonds);
  pattern += diamonds * smoothstep(1.5, 0.5, r);
  // Zigzag rings
  float zigR = fract(r * 3.0 - time * 0.1);
  float zigAngle = sin(angle * 8.0 + r * 5.0) * 0.1;
  float zig = smoothstep(0.0, 0.05, zigR + zigAngle) * smoothstep(0.1, 0.05, zigR + zigAngle);
  pattern += zig * 0.5;
  // Concentric circle of dots
  float dotRing = abs(fract(r * 5.0 + time * 0.05) - 0.5);
  float dotAngle = abs(fract(angle * 8.0 / 6.2832) - 0.5);
  float dots = smoothstep(0.1, 0.05, dotRing) * smoothstep(0.1, 0.05, dotAngle);
  pattern += dots * 0.4;
  return pattern;
}

// Psychedelic sunset gradient
vec3 sunsetGradient(float y, float time, float paletteShift) {
  // Bottom: deep orange -> middle: magenta -> top: violet -> turquoise
  vec3 ground = vec3(0.8, 0.3, 0.05);
  vec3 horizon = vec3(1.0, 0.4, 0.15);
  vec3 midSky = vec3(0.9, 0.15, 0.5);
  vec3 upperSky = vec3(0.4, 0.1, 0.6);
  vec3 zenith = vec3(0.1, 0.3, 0.5);

  float h = clamp(y, 0.0, 1.0);
  vec3 col = mix(ground, horizon, smoothstep(0.0, 0.15, h));
  col = mix(col, midSky, smoothstep(0.15, 0.35, h));
  col = mix(col, upperSky, smoothstep(0.35, 0.6, h));
  col = mix(col, zenith, smoothstep(0.6, 1.0, h));

  // Palette shift: rotate hues
  float shift = paletteShift * 0.4 + sin(time * 0.1) * 0.1;
  col.r = col.r * cos(shift) + col.b * sin(shift);
  col.b = col.b * cos(shift) - col.r * sin(shift) * 0.3;
  return max(col, 0.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // === EXTRA DOMAIN WARPING ===
  p += vec2(sin(p.y * 2.5 + time * 0.5) * 0.05, cos(p.x * 3.0 + time * 0.4) * 0.05) * (1.0 + bassVal * 0.5);
  p += vec2(cos(length(p) * 3.0 - time * 0.3) * 0.03, sin(length(p) * 2.5 + time * 0.35) * 0.03);

  // Horizon at y = -0.3
  float horizonY = -0.3;
  float skyFrac = clamp((p.y - horizonY) / 1.8, 0.0, 1.0);

  vec3 col = vec3(0.0);

  // Sky
  if (p.y > horizonY) {
    col = sunsetGradient(skyFrac, time, uPalette);

    // Giant sun near horizon
    vec2 sunPos = vec2(sin(time * 0.03) * 0.3, horizonY + 0.3);
    float sunR = length(p - sunPos);
    float sunDisc = smoothstep(0.35, 0.3, sunR);
    // Sun bands (heat distortion)
    float sunBands = sin(p.y * 30.0 - time * 1.5) * 0.5 + 0.5;
    sunBands = step(0.4, sunBands);
    vec3 sunCol = vec3(1.0, 0.6, 0.2) * sunDisc * sunBands;
    // Sun glow
    float sunGlow = exp(-sunR * 2.0) * 0.5;
    col += vec3(1.0, 0.4, 0.2) * sunGlow;
    col += sunCol;

    // Huichol art overlay in sky — faster cycling + 2x mids
    float huichol = huicholPattern(p * 0.8, time);
    vec3 huicholCol = 0.5 + 0.5 * cos(6.2832 * (huichol * 0.3 + time * 0.06 + uPalette * 0.2 + sin(uTime * 0.3) * 0.2 + vec3(0.0, 0.33, 0.67)));
    col += huicholCol * huichol * 0.4 * (0.5 + midsVal * 1.0);

    // Stars emerging in upper sky
    for (float i = 0.0; i < 20.0; i += 1.0) {
      vec2 starPos = vec2(hashMD(vec2(i, 0.0)) * 3.0 - 1.5, hashMD(vec2(i, 1.0)) * 1.0 + 0.5);
      float twinkle = sin(time * 3.0 + i * 5.7) * 0.4 + 0.6;
      float star = exp(-length(p - starPos) * 60.0) * twinkle;
      star *= smoothstep(0.3, 0.7, skyFrac); // Only in upper sky
      col += vec3(1.0, 0.9, 0.7) * star;
    }

    // Shooting stars on kick
    if (kickVal > 0.3) {
      float shootIdx = floor(time * 2.0);
      vec2 shootStart = vec2(hashMD(vec2(shootIdx, 3.0)) * 2.0 - 1.0, 1.0);
      vec2 shootDir = normalize(vec2(hashMD(vec2(shootIdx, 4.0)) - 0.5, -0.7));
      float shootProj = dot(p - shootStart, shootDir);
      float shootPerp = length((p - shootStart) - shootDir * shootProj);
      float shoot = exp(-shootPerp * 100.0) * smoothstep(0.0, 0.3, shootProj) * smoothstep(0.6, 0.3, shootProj);
      col += vec3(1.0, 0.8, 0.5) * shoot * kickVal;
    }
  }

  // Ground: desert sand dunes
  if (p.y <= horizonY + 0.1) {
    float dunes = duneRipples(p, time, bassVal);
    float groundY = horizonY + dunes * 0.1 - 0.05;

    if (p.y < groundY) {
      // Sand color with ripple shading
      vec3 sandCol = vec3(0.6, 0.35, 0.15);
      float rippleShade = sin(p.x * 20.0 + dunes * 10.0) * 0.1 + 0.9;
      sandCol *= rippleShade;
      // Distance fog
      float groundDepth = clamp((horizonY - p.y) / 1.0, 0.0, 1.0);
      sandCol = mix(sandCol, vec3(0.7, 0.3, 0.2), groundDepth * 0.5);
      col = mix(col, sandCol, smoothstep(groundY + 0.02, groundY - 0.02, p.y));
    }

    // Cactus silhouettes
    float cact1 = cactus(p, vec2(-0.8, horizonY - 0.05), 0.5);
    float cact2 = cactus(p, vec2(0.6, horizonY - 0.03), 0.35);
    float cact3 = cactus(p, vec2(-0.2, horizonY - 0.04), 0.25);
    float cact4 = cactus(p, vec2(1.1, horizonY - 0.02), 0.4);
    float cacti = max(max(cact1, cact2), max(cact3, cact4));
    col = mix(col, vec3(0.02, 0.01, 0.03), clamp(cacti, 0.0, 1.0));
  }

  // Onset: mescaline vision flash — 2x
  float visionPulse = onsetVal * 0.6;
  vec3 visionCol = 0.5 + 0.5 * cos(6.2832 * (length(p) * 0.3 + time * 0.1 + vec3(0.0, 0.33, 0.67)));
  col += visionCol * visionPulse;

  // Chaos: reality distortion — 2x
  float warp = sin(p.x * 5.0 + p.y * 3.0 + time * 2.0) * uChaos * 0.2;
  col += col * warp;

  // Treble sparkles — 2x
  col += col * trebleVal * sin(p.x * 30.0 + p.y * 20.0 + time * 5.0) * 0.16;

  // Beat pulse — 2x
  col *= 1.0 + uBeat * uSensitivity * 0.24;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridScale;
uniform float uMorphRate;
uniform float uLayerCount;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Hexagonal distance — returns (edge distance, cell center)
vec3 hexDist(vec2 p) {
  vec2 s = vec2(1.0, 1.732);
  vec2 h = s * 0.5;
  vec2 a = mod(p, s) - h;
  vec2 b = mod(p + h, s) - h;
  vec2 gv;
  if (length(a) < length(b)) gv = a;
  else gv = b;
  float edgeDist = 0.5 - max(
    abs(gv.x),
    abs(gv.x * 0.5 + gv.y * 0.866)
  );
  vec2 cellId = p - gv;
  return vec3(edgeDist, cellId);
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === GRID LAYERS ===
  for (int layer = 0; layer < 6; layer++) {
    if (float(layer) >= uLayerCount) break;
    float fl = float(layer);

    float scale = (3.0 + fl * 2.0) * uGridScale * (1.0 + bassVal * 0.6);
    float rot = time * 0.15 * (1.0 + fl * 0.2) + midsVal * 0.6 * (fl + 1.0);
    float cr = cos(rot); float sr = sin(rot);
    vec2 rp = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

    float morphTime = time * uMorphRate * (0.5 + fl * 0.1);
    rp += vec2(sin(morphTime), cos(morphTime * 0.7)) * 0.3;

    vec3 hd = hexDist(rp * scale);
    float edgeDist = hd.x;
    vec2 cellId = hd.yz;

    float cellHash = hash(cellId * 0.137 + vec2(fl * 7.0));
    float cellPhase = cellHash * 6.2832;

    // Cell breathing
    float cellBreathe = sin(time * 1.5 + cellPhase) * 0.3 + beatPulse * 0.4;
    float cellFill = smoothstep(0.15 + cellBreathe * 0.1, 0.05 + cellBreathe * 0.05, edgeDist);

    // Edge glow — 2x treble
    float edgeGlow = exp(-edgeDist * (20.0 + trebleVal * 60.0)) * 0.5;

    // Warm mescaline colors — faster cycling
    float hue = cellHash * 0.3 + fl * 0.15 + uPalette * 0.1 + time * 0.08 + sin(uTime * 0.3) * 0.2;
    vec3 cellCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.08, 0.2)));
    cellCol.r = cellCol.r * 0.6 + 0.4;
    cellCol.b *= 0.6;
    cellCol = mix(cellCol, cellCol.grb, midsVal * 0.2);

    // Inner pattern
    float innerR = length(rp * scale - cellId);
    float innerPattern = sin(innerR * 30.0 + time * 2.0 + cellPhase);
    innerPattern = innerPattern * 0.5 + 0.5;

    float layerAlpha = (1.0 - fl / uLayerCount) * 0.4;
    col += cellCol * cellFill * innerPattern * layerAlpha;
    col += cellCol * edgeGlow * layerAlpha * 1.5;

    // Treble detail
    float trebleDetail = sin(innerR * (50.0 + trebleVal * 40.0) + cellPhase);
    trebleDetail = smoothstep(0.8, 1.0, trebleDetail);
    col += vec3(1.0, 0.9, 0.7) * trebleDetail * trebleVal * layerAlpha * 0.3;
  }

  // Organic flow connecting cells
  float organicFlow = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float flowAngle = fi * 1.571 + time * 0.3;
    vec2 flowDir = vec2(cos(flowAngle), sin(flowAngle));
    float wave = sin(dot(p, flowDir) * (5.0 + fi * 2.0) + time * (1.0 + fi * 0.2));
    organicFlow += smoothstep(0.85, 1.0, wave) * (1.0 - fi * 0.2);
  }
  col += vec3(0.9, 0.6, 0.2) * organicFlow * 0.15;

  // Central mandala
  float r = length(p);
  float a = atan(p.y, p.x);
  float mandala = sin(a * 6.0 + time * 0.5) * sin(r * 15.0 - time * 2.0);
  mandala = smoothstep(0.7, 1.0, mandala) * exp(-r * 2.0);
  col += vec3(1.0, 0.8, 0.3) * mandala * 0.2;

  // Extra domain warping
  col += vec3(1.0, 0.7, 0.3) * onsetFlash * 0.5;
  col *= 1.0 + beatPulse * 0.3;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

