uniform float uOrganicDensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 6; i++) {
    v += a * noise(p);
    p = p * 2.0 + vec2(1.7, 3.2);
    a *= 0.5;
  }
  return v;
}

// Domain warped fbm — creates flowing organic forms
float warpedFbm(vec2 p, float time) {
  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0)),
    fbm(p + vec2(5.2, 1.3))
  );
  vec2 r = vec2(
    fbm(p + 4.0 * q + vec2(1.7, 9.2) + time * 0.15),
    fbm(p + 4.0 * q + vec2(8.3, 2.8) + time * 0.12)
  );
  return fbm(p + 4.0 * r);
}

// Vine/tendril pattern
float vine(vec2 p, float width, float time) {
  float wave = sin(p.x * 3.0 + time) * 0.3 + sin(p.x * 7.0 + time * 1.3) * 0.1;
  float dist = abs(p.y - wave);
  return smoothstep(width, width * 0.3, dist);
}

