  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === EXTRA DOMAIN WARPING ===
  p += vec2(sin(p.y * 3.0 + time * 0.5) * 0.06, cos(p.x * 3.5 + time * 0.4) * 0.06) * (1.0 + bassVal * 0.5);

  // === FLOWING COLOR RIVERS === — 2x bass
  float flowTime = time * uFlowSpeed * (1.0 + bassVal * 2.0);

  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float streamAngle = fi * 0.785 + time * 0.05 + uChaos * sin(time * 0.1 + fi);
    float ca = cos(streamAngle); float sa = sin(streamAngle);
    vec2 sp = vec2(p.x * ca - p.y * sa, p.x * sa + p.y * ca);

    sp.x += flowTime * (0.5 + fi * 0.2);
    float flow = warpedFbm(sp * (1.5 + fi * 0.3), flowTime);

    vec3 streamCol;
    if (fi < 1.0) streamCol = mix(vec3(0.85, 0.4, 0.1), vec3(1.0, 0.7, 0.2), flow);
    else if (fi < 2.0) streamCol = mix(vec3(0.7, 0.3, 0.15), vec3(0.9, 0.5, 0.2), flow);
    else if (fi < 3.0) streamCol = mix(vec3(0.9, 0.5, 0.2), vec3(1.0, 0.7, 0.3), flow);
    else streamCol = mix(vec3(0.3, 0.5, 0.25), vec3(0.5, 0.7, 0.3), flow);

    streamCol = mix(streamCol, streamCol.gbr, midsVal * 0.3 + sin(uTime * 0.3) * 0.1);
    float flowIntensity = smoothstep(0.3, 0.7, flow) * (1.0 - fi * 0.15);
    col += streamCol * flowIntensity * 0.35;
  }

  // === VINE-LIKE FRACTALS ===
  vec3 vineColor = vec3(0.0);
  for (int i = 0; i < 6; i++) {
    if (float(i) >= uBranchDepth * 10.0) break;
    float fi = float(i);
    float vineAngle = fi * 1.047 + time * 0.1;
    float ca = cos(vineAngle); float sa = sin(vineAngle);
    vec2 vp = vec2(p.x * ca - p.y * sa, p.x * sa + p.y * ca);

    float scale = 2.0 + fi * 1.5;
    vp *= scale;
    vp.x += flowTime * (0.3 + fi * 0.15);

    float width = 0.06 / (1.0 + fi * 0.3);
    float v = vine(vp, width, flowTime * 2.0 + fi);

    vec2 branchP = vp;
    branchP.x = fract(branchP.x * 0.5) - 0.25;
    float branch = vine(branchP * 2.0, width * 0.5, flowTime * 3.0 + fi * 2.0);
    v = max(v, branch * uBranchDepth);

    vec3 vc = mix(vec3(0.2, 0.4, 0.15), vec3(0.7, 0.5, 0.2), fi / 6.0);
    vineColor += vc * v * (1.0 - fi * 0.12);
  }
  col += vineColor * uOrganicDensity * 0.5;

  // === GROWTH PATTERN ===
  vec2 growthCenter = vec2(sin(time * 0.2) * 0.3, cos(time * 0.15) * 0.2);
  float growthR = length(p - growthCenter);
  float growthAngle = atan(p.y - growthCenter.y, p.x - growthCenter.x);
  float growthRadius = 0.3 + beatPulse * 0.2;
  growthRadius += sin(growthAngle * 5.0 + time * 0.5) * 0.1;
  growthRadius += noise(vec2(growthAngle * 2.0, time * 0.5)) * 0.15;
  float growthEdge = smoothstep(growthRadius, growthRadius - 0.05, growthR);
  float growthPattern = fbm(p * 8.0 + time * 0.2) * growthEdge;
  vec3 growthCol = mix(vec3(0.4, 0.6, 0.2), vec3(0.8, 0.6, 0.1), growthPattern);
  col += growthCol * growthPattern * 0.25;

  // Treble detail — 2x
  float fineDetail = fbm(p * (15.0 + trebleVal * 20.0) + time * 0.3);
  fineDetail = smoothstep(0.4, 0.7, fineDetail) * trebleVal;
  col += vec3(0.9, 0.7, 0.3) * fineDetail * 0.3;

  // Warm background
  float bgGlow = fbm(p * 1.5 + time * 0.05);
  col += vec3(0.15, 0.08, 0.03) * bgGlow;

  // Onset burst
  float burstR = length(p);
  float burstAngle = atan(p.y, p.x);
  float burst = sin(burstAngle * 8.0 + time * 5.0) * exp(-burstR * 3.0);
  col += vec3(1.0, 0.8, 0.3) * max(0.0, burst) * onsetFlash * 0.6;

  col *= 1.0 + beatPulse * 0.3;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

