uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPulseSpeed;
uniform float uConnectionGlow;
uniform float uSolidRotation;

#define PI 3.14159265
#define TAU 6.28318530

vec2 rotate2d(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Distance to line segment, also returns parametric t
float segDistT(vec2 p, vec2 a, vec2 b, out float t) {
  vec2 pa = p - a, ba = b - a;
  t = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * t);
}

// Circle glow
float circleGlow(vec2 p, vec2 center, float radius, float width) {
  float d = abs(length(p - center) - radius) - width;
  return smoothstep(0.005, 0.0, d);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.5;

  vec3 col = vec3(0.02, 0.01, 0.03);

  // 13 circles of Metatron's Cube
  // Center + 6 inner hexagon + 6 outer hexagon
  vec2 centers[13];
  centers[0] = vec2(0.0, 0.0); // Center
  float innerR = 0.35;
  float outerR = 0.7;

  for (int i = 0; i < 6; i++) {
    float angle = float(i) * TAU / 6.0 + time * uSolidRotation * 0.1;
    centers[i + 1] = vec2(cos(angle), sin(angle)) * innerR;
    centers[i + 7] = vec2(cos(angle), sin(angle)) * outerR;
  }

  // Draw circles
  float circR = 0.08 + bassVal * 0.02;
  for (int i = 0; i < 13; i++) {
    float glow = circleGlow(p, centers[i], circR, 0.003);

    // Different spectrum band per circle
    float specIdx = mod(float(i), 8.0);
    float specVal = 0.0;
    if (specIdx < 1.0) specVal = uSpectrum0;
    else if (specIdx < 2.0) specVal = uSpectrum1;
    else if (specIdx < 3.0) specVal = uSpectrum2;
    else if (specIdx < 4.0) specVal = uSpectrum3;
    else if (specIdx < 5.0) specVal = uSpectrum4;
    else if (specIdx < 6.0) specVal = uSpectrum5;
    else if (specIdx < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    // Gold/white/violet
    vec3 circCol = mix(
      vec3(0.85, 0.7, 0.2),  // gold
      vec3(0.6, 0.3, 0.9),    // violet
      float(i) / 13.0 + uPalette * 0.3
    );
    circCol *= 0.5 + specVal * uSensitivity * 0.8;
    circCol += vec3(1.0, 0.95, 0.85) * uBeat * uSensitivity * 0.2; // white flash

    col += circCol * glow;

    // Node point glow
    float nodeDist = length(p - centers[i]);
    float nodeGlow = exp(-nodeDist * nodeDist * 200.0) * (0.4 + specVal * 0.6);
    col += vec3(1.0, 0.9, 0.6) * nodeGlow * 0.5;
  }

  // Draw ALL connections between circles (Metatron's Cube has all 13 connected)
  for (int i = 0; i < 13; i++) {
    for (int j = i + 1; j < 13; j++) {
      float t;
      float d = segDistT(p, centers[i], centers[j], t);

      float lineWidth = 0.003 + uConnectionGlow * 0.002;
      float line = smoothstep(lineWidth, lineWidth * 0.3, d);

      // Energy pulse traveling along line
      float pulsePhase = fract(t - time * uPulseSpeed * 0.5 - float(i + j) * 0.1);
      float pulse = exp(-pow((pulsePhase - 0.5) * 6.0, 2.0));

      // Line color
      vec3 lineCol = mix(
        vec3(0.6, 0.5, 0.2),  // gold
        vec3(0.8, 0.6, 1.0),  // violet
        t + uPalette * 0.2
      );

      lineCol *= 0.15 + pulse * 0.6 * uConnectionGlow;
      lineCol += vec3(1.0, 0.9, 0.7) * uKick * uSensitivity * 0.5; // kick flash all

      col += lineCol * line * 0.4;
    }
  }

  // Inner platonic solid projections (rotating hexagrams) — more solids, faster
  for (int s = 0; s < 5; s++) {
    float solidRot = time * (0.15 + float(s) * 0.08) * uSolidRotation + uBpmSin2 * 0.35;
    float solidR = 0.12 + float(s) * 0.07;
    int sides = 3 + s; // triangle, square, pentagon, hexagon, heptagon

    for (int i = 0; i < 7; i++) {
      if (i >= sides) break;
      float a1 = float(i) * TAU / float(sides) + solidRot;
      float a2 = float(i + 1) * TAU / float(sides) + solidRot;
      vec2 v1 = vec2(cos(a1), sin(a1)) * solidR;
      vec2 v2 = vec2(cos(a2), sin(a2)) * solidR;

      float t;
      float d = segDistT(p, v1, v2, t);
      float edge = smoothstep(0.004, 0.001, d);
      col += vec3(0.9, 0.8, 1.0) * edge * 0.3 * (0.5 + midsVal * 0.7);
    }
  }

  // Spectral flux ambient shimmer
  col += vec3(0.05, 0.03, 0.08) * uSpectralFlux * uSensitivity * 0.3;

  // Overall sacred glow
  float centerGlow = exp(-dot(p, p) * 2.0);
  col += vec3(0.2, 0.15, 0.05) * centerGlow * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uNodeGlow;
uniform float uLineThickness;

#define PI 3.14159265359
#define TAU 6.28318530718
#define NODE_COUNT 13

// SDF line segment
float sdSegment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Rotation matrix
mat2 rot(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Simple hash for noise perturbation
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
  float time = uTime * uSpeed;
  vec2 uv = (vUv - 0.5) * 2.0;
  uv = psychedelicUV(uv); // breathing morph

  // Zoom — tighter range so geometry fills screen
  uv *= (1.0 + uZoom * 0.3);

  // BPM-driven rotation — faster
  float rotAngle = uBpmSin * 0.25 * uSensitivity + time * 0.18;
  uv = rot(rotAngle) * uv;

  // Audio values
  float energyVal = uEnergy * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float harmonicityVal = uHarmonicity;
  float centroidVal = uSpectralCentroid;

  // Noise perturbation: low at high harmonicity, high at low
  float noiseAmt = mix(0.08, 0.02, harmonicityVal) * energyVal + uChaos * 0.03;

  // === BUILD 13 NODE POSITIONS ===
  vec2 nodes[NODE_COUNT];
  // Center node
  nodes[0] = vec2(0.0, 0.0);

  float innerR = 0.55;
  float outerR = 1.05;

  // Inner ring: 6 nodes at 60-degree intervals
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * TAU / 6.0;
    vec2 base = vec2(cos(angle), sin(angle)) * innerR;
    // Subtle noise perturbation
    vec2 nOff = vec2(
      hash(base + time * 0.1) - 0.5,
      hash(base.yx - time * 0.1) - 0.5
    ) * noiseAmt;
    nodes[i + 1] = base + nOff;
  }

  // Outer ring: 6 nodes at 60-degree intervals, offset 30 degrees
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * TAU / 6.0 + PI / 6.0;
    vec2 base = vec2(cos(angle), sin(angle)) * outerR;
    vec2 nOff = vec2(
      hash(base + time * 0.13) - 0.5,
      hash(base.yx - time * 0.13) - 0.5
    ) * noiseAmt;
    nodes[i + 7] = base + nOff;
  }

  // === DRAW LINES ===
  // Line thickness based on param — thicker for larger geometry
  float lineW = (0.005 + uLineThickness * 0.01);
  float lineBrightness = 0.0;

  // Connect every node to every other node (78 edges)
  // Group edges by index sum for spectrum mapping
  int edgeIdx = 0;
  for (int i = 0; i < NODE_COUNT; i++) {
    for (int j = i + 1; j < NODE_COUNT; j++) {
      float d = sdSegment(uv, nodes[i], nodes[j]);
      float lineVal = smoothstep(lineW * 1.5, lineW * 0.3, d);

      // Map edge to spectrum band (8 bands)
      int band = edgeIdx * 8 / 78;
      float specVal = 0.5;
      if (band == 0) specVal = uSpectrum0;
      else if (band == 1) specVal = uSpectrum1;
      else if (band == 2) specVal = uSpectrum2;
      else if (band == 3) specVal = uSpectrum3;
      else if (band == 4) specVal = uSpectrum4;
      else if (band == 5) specVal = uSpectrum5;
      else if (band == 6) specVal = uSpectrum6;
      else specVal = uSpectrum7;

      // Brightness varies per edge group
      float edgeBright = 0.3 + specVal * 0.7 * uSensitivity;
      lineBrightness += lineVal * edgeBright;
      edgeIdx++;
    }
  }

  // === DRAW NODES ===
  float nodeBrightness = 0.0;
  float glowRadius = 0.04 + uNodeGlow * 0.05;

  for (int i = 0; i < NODE_COUNT; i++) {
    float d = length(uv - nodes[i]);
    // Solid core
    float core = smoothstep(glowRadius, glowRadius * 0.3, d);
    // Soft glow halo
    float glow = exp(-d * d / (glowRadius * glowRadius * 4.0));
    // Beat pulse expands glow — stronger
    float pulse = 1.0 + beatPulse * 1.3;
    nodeBrightness += (core + glow * 0.5) * pulse;
  }

  // === COLOR ===
  // Base: deep indigo background
  vec3 bgColor = vec3(0.02, 0.01, 0.06);

  // Line color: white/gold, shifted by spectral centroid for temperature
  float warmShift = centroidVal * 0.3 + uPalette * 0.25;
  vec3 lineColor = mix(
    vec3(1.0, 0.95, 0.8),   // warm gold
    vec3(0.8, 0.9, 1.0),    // cool white
    clamp(warmShift, 0.0, 1.0)
  );

  // Node color: bright white with beat-reactive warmth
  vec3 nodeColor = vec3(1.0, 0.97, 0.9) + beatPulse * vec3(0.3, 0.15, 0.0);

  // Compose
  vec3 col = bgColor;
  col += lineColor * lineBrightness * 0.6;
  col += nodeColor * nodeBrightness * 0.8;

  // Outer circle glow (Metatron's encompassing circle)
  float outerCircleDist = abs(length(uv) - outerR - 0.05);
  float outerCircle = smoothstep(lineW * 2.0, lineW * 0.3, outerCircleDist);
  col += outerCircle * lineColor * 0.3;

  // Inner circle
  float innerCircleDist = abs(length(uv) - innerR);
  float innerCircle = smoothstep(lineW * 2.0, lineW * 0.3, innerCircleDist);
  col += innerCircle * lineColor * 0.2;

  // Energy brightens overall
  col += energyVal * 0.04;

  // Intensity
  col *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

