    cellCenter += vec2(sin(time * 0.3 + id), cos(time * 0.4 + id * 1.3)) * 0.2;

    // Division cycle driven by kick accumulation
    float divPhase = fract(time * uDivisionRate * 0.3 + id * 0.618);
    float pinch = smoothstep(0.3, 0.5, divPhase) * (1.0 - smoothstep(0.5, 0.7, divPhase));
    pinch *= (1.0 + kickVal * 2.0);

    // Split offset - cells separate after pinch
    float splitAmt = smoothstep(0.5, 0.9, divPhase);
    vec2 splitDir = vec2(cos(id * 5.0), sin(id * 5.0));
    vec2 cell1 = cellCenter - splitDir * splitAmt * 0.25;
    vec2 cell2 = cellCenter + splitDir * splitAmt * 0.25;

    float radius = mix(0.22, 0.14, splitAmt) * (1.0 + bassVal * 0.3);
    float wobble = bassVal * uMembraneWobble + noise(p * 5.0 + time) * uChaos * 0.3;

    // Draw both daughter cells
    for (int d = 0; d < 2; d++) {
      vec2 cc = d == 0 ? cell1 : cell2;
      if (d == 1 && splitAmt < 0.1) continue;

      float cellR = d == 0 ? radius : radius * splitAmt;
      float sdf = cellSDF(p - cc, cellR, pinch * (1.0 - float(d)), wobble, id + float(d) * 100.0);

      // Membrane glow
      float membrane = exp(-abs(sdf) * 15.0 / uGlowRadius) * 0.8;
      // Inner glow
      float inner = exp(-max(sdf, 0.0) * 8.0) * smoothstep(0.0, -0.02, sdf);
      // Nucleus
      float nucleus = exp(-length(p - cc) * 30.0) * smoothstep(0.0, -0.01, sdf);

      float hue = id * 0.15 + uPalette * 0.1 + float(d) * 0.1;
      vec3 cellCol = bioLuminPalette(hue);
      vec3 nucleusCol = vec3(0.4, 0.9, 0.7);

      col += cellCol * membrane * (0.5 + midsVal * 0.5);
      col += cellCol * inner * 0.4 * (1.0 + trebleVal);
      col += nucleusCol * nucleus * 1.5;
    }
  }

  // Organelle particles
  for (float i = 0.0; i < 30.0; i++) {
    vec2 ppos = vec2(hash(vec2(i, 0.0)), hash(vec2(0.0, i))) * 2.4 - 1.2;
    ppos += vec2(sin(time + i), cos(time * 1.3 + i * 2.0)) * 0.5;
    float pd = length(p - ppos);
    float particle = exp(-pd * 60.0) * trebleVal;
    col += bioLuminPalette(i * 0.1 + time * 0.05) * particle * 0.3;
  }

  // Spectral flux shimmer
  col += col * uSpectralFlux * uSensitivity * 0.3;

  // Kick flash
  col = mix(col, col * 1.8 + vec3(0.05, 0.15, 0.1), kickVal * 0.4);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

#define PI 3.14159265
#define TAU 6.28318530

float hash1(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash1(i);
  float b = hash1(i + vec2(1.0, 0.0));
  float c = hash1(i + vec2(0.0, 1.0));
  float d = hash1(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm3(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 3; i++) {
    v += amp * vnoise(p);
    p = rot * p * 2.1 + vec2(3.7, 1.9);
    amp *= 0.5;
  }
  return v;
}

// Per-band color from index
vec3 bandColor(float idx, float t, float palShift) {
  float phase = idx * 0.15 + t * 0.15 + palShift;
  return 0.55 + 0.45 * cos(TAU * (phase + vec3(0.0, 0.33, 0.67)));
}

// Mobius twist: angle-dependent cross-section rotation
vec2 mobiusTwist(vec2 crossSection, float angle, float twistCount) {
  float twistAngle = angle * twistCount * 0.5;
  float ct = cos(twistAngle), st = sin(twistAngle);
  return vec2(crossSection.x * ct - crossSection.y * st,
              crossSection.x * st + crossSection.y * ct);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // BPM breathing: bands pulse in width — stronger
  float bpmBreath = 1.0 + uBpmSin * 0.18 + bassVal * 0.25;

  // Domain warp the input coordinates — stronger
  float warpStrength = 0.3 + bassVal * 0.6 + uChaos * 0.4;
  vec2 warp = vec2(
    fbm3(p * 1.5 + time * vec2(0.1, -0.2)),
    fbm3(p * 1.5 + time * vec2(-0.15, 0.1) + vec2(50.0))
  );
  vec2 wp = p + warp * warpStrength;

  // Polar coordinates for radial twist
  float angle = atan(wp.y, wp.x);
  float radius = length(wp);

  // Background
  float bgGrad = 1.0 - length(vUv - 0.5) * 0.5;
  vec3 col = vec3(0.015, 0.01, 0.03) * bgGrad;

  // === 7 TWISTED BANDS ===
  for (int band = 0; band < 7; band++) {
    float fBand = float(band);

    // Each band has a different base radius
    float bandR = 0.3 + fBand * 0.18;
    bandR *= bpmBreath;

    // Band width varies with treble
    float bandW = 0.08 + trebleVal * 0.02 + fBand * 0.005;

    // Mobius twist: cross-section rotates as you go around
    float twistCount = 1.0 + fBand * 0.5; // different twist amounts
    vec2 crossSection = vec2(radius - bandR, 0.0);
    vec2 twisted = mobiusTwist(crossSection, angle, twistCount);

    // Distance to twisted band
    float bandDist = abs(twisted.x) - bandW;

    // Smooth band edge
    float bandMask = smoothstep(bandW * 0.3, -bandW * 0.1, bandDist);

    if (bandMask < 0.01) continue;

    // === FLOWING WAVE PATTERN along the band ===
    float flowAngle = angle + time * (0.3 + fBand * 0.1);
    float flowParam = flowAngle * (3.0 + fBand) + twisted.y * 5.0;

    // Wave pattern: layered sine waves
    float wave1 = sin(flowParam * 2.0 + time * 1.5) * 0.5 + 0.5;
    float wave2 = sin(flowParam * 5.0 - time * 2.5 + fBand * 1.5) * 0.5 + 0.5;
    float wave3 = sin(flowParam * 11.0 + time * 0.7) * 0.5 + 0.5;
    float wavePattern = wave1 * 0.5 + wave2 * 0.3 + wave3 * 0.2;

    // Audio modulation: mids affect wave complexity
    wavePattern += midsVal * sin(flowParam * 7.0 + time) * 0.2;

    // FBM texture on the band surface
    vec2 bandUV = vec2(flowAngle * 2.0, twisted.x * 10.0);
    float bandTex = fbm3(bandUV + time * vec2(0.2, 0.0) + fBand * 20.0);

    // Per-band color cycling
    vec3 bCol = bandColor(fBand, time, uPalette);

    // Darken edges, brighten center
    float edgeFade = 1.0 - abs(twisted.x) / bandW;
    edgeFade = edgeFade * edgeFade;

    // Combine: base color * wave pattern * edge fade * texture
    vec3 bandCol = bCol * (0.3 + wavePattern * 0.7) * edgeFade;
    bandCol *= (0.7 + bandTex * 0.3);

    // Beat pulse brightens all bands
    bandCol += bCol * beatPulse * 0.2;

    // Treble sparkle at wave peaks
    float sparkle = smoothstep(0.85, 1.0, wavePattern) * trebleVal;
    bandCol += vec3(0.9, 0.95, 1.0) * sparkle * 0.4;

    // Edge glow: bright outline
    float edgeGlow = smoothstep(bandW * 0.5, bandW * 0.1, abs(bandDist));
    edgeGlow *= (1.0 - edgeFade) * 0.5;
    bandCol += bCol * edgeGlow * (0.3 + energyVal * 0.3);

    col += bandCol * bandMask;
  }

  // === KICK RIPPLE: radial wave from center ===
  float kickWave = sin(radius * 20.0 - kickVal * 15.0) * kickVal * 0.15;
  col += vec3(0.3, 0.2, 0.5) * kickWave;

  // === ONSET FLASH ===
  col += vec3(0.7, 0.6, 1.0) * onsetFlash * 0.2;

  // === CENTER GLOW ===
  float centerDist = length(p);
  float centerGlow = exp(-centerDist * centerDist * 3.0) * (0.15 + beatPulse * 0.15);
  col += vec3(0.5, 0.4, 0.8) * centerGlow;

  // === BACKGROUND PARTICLES ===
  for (int i = 0; i < 20; i++) {
    float fi = float(i);
    float pAngle = fi * TAU * 0.618033 + time * 0.05;
    float pR = 0.5 + fi * 0.08 + sin(time * 0.2 + fi) * 0.1;
    vec2 particlePos = vec2(cos(pAngle), sin(pAngle)) * pR;
    float pd = length(p - particlePos);
    float particle = exp(-pd * pd * 800.0);
    vec3 pCol = bandColor(fi, time, uPalette + 0.5) * 0.15;
    col += pCol * particle;
  }

  // Chaos: color channel shift
  if (uChaos > 0.2) {
    float shift = uChaos * 0.15 * sin(time * 0.5);
    col = vec3(col.r + shift, col.g, col.b - shift);
  }

  // Energy brightness
  col *= (0.7 + energyVal * 0.4);
  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLineFrequency;
uniform float uOffsetRate;
uniform float uPatternType;
uniform float uContrast;

// HSV to RGB
vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio modulators
  float bassOffset = bass() * uSensitivity;
  float midsRotate = mids() * uSensitivity;
  float energyThick = uEnergy * uSensitivity;
  float beatJump = uBeat * uSensitivity;

  // Line edge sharpness from contrast param
  float edgeWidth = 0.02 + 0.1 * (1.0 - uContrast);
  float thicknessOffset = energyThick * 0.05;

  // --- Layer 1: centered at origin ---
  float x1 = p.x;
  float y1 = p.y;
  float radius1 = pow(x1 * x1 + y1 * y1, 0.5);

  float circles1 = sin(radius1 * (uLineFrequency * 6.2831));
  float circleLines1 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    circles1
  );

  float lines1 = sin(x1 * (uLineFrequency * 6.2831));
  float lineStripes1 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    lines1
  );

  float pattern1 = mix(circleLines1, lineStripes1, uPatternType);

  // --- Layer 2: offset and rotated ---
  float offsetX = sin(time * uOffsetRate) * 0.05
    + bassOffset * 0.08
    + beatJump * 0.15;
  float offsetY = cos(time * (uOffsetRate * 0.7)) * 0.05
    + bassOffset * 0.05
    + beatJump * 0.1;

  float rotAngle = time * 0.1 + midsRotate * 0.8 + uChaos * sin(time * 0.2);
  float cosA = cos(rotAngle);
  float sinA = sin(rotAngle);

  float x2 = (p.x - offsetX) * cosA - (p.y - offsetY) * sinA;
  float y2 = (p.x - offsetX) * sinA + (p.y - offsetY) * cosA;
  float radius2 = pow(x2 * x2 + y2 * y2, 0.5);

  float circles2 = sin(radius2 * (uLineFrequency * 6.2831));
  float circleLines2 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    circles2
  );

  float lines2 = sin(x2 * (uLineFrequency * 6.2831));
  float lineStripes2 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    lines2
  );

  float pattern2 = mix(circleLines2, lineStripes2, uPatternType);

  // --- Layer 3: secondary interference layer ---
  float x3 = p.x + offsetX * 0.5;
  float y3 = p.y - offsetY * 0.5;
  float radius3 = pow(x3 * x3 + y3 * y3, 0.5);

  float circles3 = sin(radius3 * (uLineFrequency * 6.2831 * 0.7));
  float circleLines3 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    circles3
  );

  float diag3 = sin((x3 + y3) * (uLineFrequency * 6.2831 * 0.5));
  float diagStripes3 = smoothstep(
    0.0 - edgeWidth - thicknessOffset,
    edgeWidth + thicknessOffset,
    diag3
  );

  float pattern3 = mix(circleLines3, diagStripes3, uPatternType);

  // --- Moire interference ---
  float moireRaw = pattern1 * pattern2;
  float moireWithThird = mix(moireRaw, moireRaw * pattern3, uChaos * 0.5);

  // --- HSV color tinting ---
  float hue = fract(
    moireWithThird * 0.3
      + time * 0.03
      + uPalette * 0.1
      + midsRotate * 0.1
  );
  float sat = 0.6 + moireWithThird * 0.3;
  float val = moireWithThird * (uIntensity * 1.5);

  vec3 col = hsvToRgb(hue, clamp(sat, 0.0, 1.0), clamp(val, 0.0, 1.0));

  // Energy brightness boost
  float energyBoost = energyThick * 0.2;
  vec3 litCol = vec3(
    col.x + energyBoost * moireWithThird,
    col.y + energyBoost * moireWithThird,
    col.z + energyBoost * moireWithThird
  );

  // Beat flash
  float flashAmount = beatJump * 0.2 * moireWithThird;
  vec3 finalCol = litCol + vec3(flashAmount, flashAmount, flashAmount);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uHeatGradient;
uniform float uConvectionForce;
uniform float uSpecularPower;

#define PI 3.14159265

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 6; i++) {
    v += a * noise(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

// Domain warping for organic flow
float warpedFlow(vec2 p, float time) {
  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + time * 0.1),
    fbm(p + vec2(5.2, 1.3) + time * 0.08)
  );
  vec2 r = vec2(
    fbm(p + q * 4.0 + vec2(1.7, 9.2) + time * 0.06),
    fbm(p + q * 4.0 + vec2(8.3, 2.8) + time * 0.05)
  );
  return fbm(p + r * 2.0);
}

// Metal temperature to color
vec3 metalColor(float temp) {
  vec3 c;
  if (temp < 0.2) c = mix(vec3(0.2, 0.02, 0.0), vec3(0.5, 0.05, 0.0), temp * 5.0);
  else if (temp < 0.4) c = mix(vec3(0.5, 0.05, 0.0), vec3(0.9, 0.25, 0.0), (temp - 0.2) * 5.0);
  else if (temp < 0.6) c = mix(vec3(0.9, 0.25, 0.0), vec3(1.0, 0.55, 0.05), (temp - 0.4) * 5.0);
  else if (temp < 0.8) c = mix(vec3(1.0, 0.55, 0.05), vec3(1.0, 0.85, 0.3), (temp - 0.6) * 5.0);
  else c = mix(vec3(1.0, 0.85, 0.3), vec3(1.0, 0.98, 0.85), (temp - 0.8) * 5.0);
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.3;

  // Convection currents from bass
  vec2 convection = vec2(
    sin(p.y * 3.0 + time * 0.5) * uConvectionForce * 0.1,
    cos(p.x * 3.0 + time * 0.4) * uConvectionForce * 0.1
  );
  convection += vec2(bassVal * 0.05, -bassVal * 0.03);

  vec2 flowP = p + convection;

  // Multi-layered molten flow
  float flow1 = warpedFlow(flowP * 2.0, time);
  float flow2 = warpedFlow(flowP * 3.0 + 10.0, time * 1.2);
  float flow3 = fbm(flowP * 5.0 + time * 0.15);

  // Combined flow pattern
  float flow = flow1 * 0.5 + flow2 * 0.3 + flow3 * 0.2;

  // Temperature: driven by energy and heat gradient
  float temp = uHeatGradient * 0.5 + uEnergy * uSensitivity * 0.3;
  temp += flow * 0.3;
  temp += bassVal * 0.1;

  // Spectrum modulation of temperature zones
  temp += uSpectrum0 * uSensitivity * 0.05;
  temp += uSpectrum4 * uSensitivity * 0.05;

  temp = clamp(temp, 0.0, 1.0);

  vec3 col = metalColor(temp);

  // Surface tension creates organic boundaries
  float tension = abs(fract(flow * 5.0) - 0.5) * 2.0;
  float boundary = smoothstep(0.1, 0.05, tension);
  col += vec3(0.2, 0.1, 0.0) * boundary * 0.3;

  // Metallic specular highlights
  float eps = 0.01;
  float dx = warpedFlow((flowP + vec2(eps, 0.0)) * 2.0, time) - flow1;
  float dy = warpedFlow((flowP + vec2(0.0, eps)) * 2.0, time) - flow1;
  vec2 surfNormal = normalize(vec2(dx, dy) + 0.001);

  // Specular from multiple light angles
  float spec1 = pow(max(dot(surfNormal, normalize(vec2(0.5, 0.8))), 0.0), 8.0 + uSpecularPower * 40.0);
  float spec2 = pow(max(dot(surfNormal, normalize(vec2(-0.3, 0.6))), 0.0), 16.0 + uSpecularPower * 30.0);
  float totalSpec = (spec1 + spec2 * 0.5) * uSpecularPower;

  col += vec3(1.0, 0.9, 0.7) * totalSpec * (0.3 + trebleVal * 0.3);

  // Mids drive surface undulation
  col += metalColor(temp + 0.1) * midsVal * 0.1;

  // Kick creates convection surge
  col += vec3(0.2, 0.1, 0.0) * uKick * uSensitivity * 0.2;

  // Beat pulse brightens hot zones
  float hotZone = smoothstep(0.5, 0.8, temp);
  col += col * uBeat * uSensitivity * 0.15 * hotZone;

  // Onset sparks
  float spark = hash(floor(p * 25.0 + time * 8.0)) * uOnset * uSensitivity;
  col += vec3(1.0, 0.85, 0.5) * spark * 0.3 * hotZone;

  // Warmth tint
  col += vec3(0.03, 0.01, 0.0) * uWarmth * uSensitivity * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Neon rainbow palette
vec3 neonRainbow(float t) {
  return 0.5 + 0.5 * cos(6.2832 * (t + vec3(0.0, 0.33, 0.67)));
}

// Lissajous position for pendulum i at time t — larger swing to fill screen
vec2 lissajousPos(float i, float t, float amp) {
  float fx = 1.0 + i * 0.5;
  float fy = 1.0 + i * 0.37;
  float px = i * 1.047;
  float py = i * 0.618;
  return vec2(
    sin(t * fx + px) * amp * (0.7 + i * 0.1),
    sin(t * fy + py) * amp * (0.6 + i * 0.08)
  );
}

// Soft line segment SDF
float sdSegment(vec2 pt, vec2 a, vec2 b) {
  vec2 pa = pt - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Beat-synced phase accumulation
  float beatPhase = uBpmSin * 0.5 + uBpmSin2 * 0.3;
  float amplitude = 1.0 + energyVal * 1.0 + bassVal * 0.5;

  vec3 col = vec3(0.01, 0.005, 0.02); // deep dark background

  // 7 pendulums
  for (float i = 0.0; i < 7.0; i += 1.0) {
    float id = i / 7.0;
    float hue = id + uPalette * 0.1 + time * 0.02;

    // Current pendulum bob position (Lissajous)
    float phaseOffset = beatPhase * (1.0 + i * 0.2);
    vec2 bobPos = lissajousPos(i, time + phaseOffset, amplitude);

    // Pendulum bob glow — larger for full-screen presence
    float bobDist = length(p - bobPos);
    float bobGlow = 0.025 / (bobDist + 0.01);
    vec3 bobColor = neonRainbow(hue) * 1.5;

    // Kick flash on bob
    bobGlow += kickVal * 0.05 / (bobDist + 0.02);

    col += bobColor * bobGlow;

    // Draw persistent fading trail (16 history points)
    for (float j = 1.0; j < 16.0; j += 1.0) {
      float pastTime = time - j * 0.03;
      vec2 pastPos = lissajousPos(i, pastTime + phaseOffset, amplitude);
      vec2 prevPos = lissajousPos(i, pastTime + 0.03 + phaseOffset, amplitude);

      // Trail segment
      float segDist = sdSegment(p, pastPos, prevPos);
      float trailFade = 1.0 - j / 16.0;
      trailFade = trailFade * trailFade; // quadratic falloff
      float trailWidth = 0.005 + midsVal * 0.006;
      float trailGlow = smoothstep(trailWidth + 0.01, trailWidth, segDist) * trailFade;

      // Hue shifts along trail
      float trailHue = hue + j * 0.03 + trebleVal * 0.1;
      col += neonRainbow(trailHue) * trailGlow * 0.35;
    }

    // Thin connection line from center to bob
    float lineDist = sdSegment(p, vec2(0.0, 0.0), bobPos);
    float lineGlow = smoothstep(0.003, 0.0, lineDist) * 0.15;
    col += neonRainbow(hue + 0.5) * lineGlow;
  }

  // Central anchor glow
  float centerDist = length(p);
  float centerGlow = 0.02 / (centerDist + 0.02);
  col += vec3(0.8, 0.6, 1.0) * centerGlow * (0.3 + kickVal * 0.5);

  // Chaos: phase distortion adds wobble to the whole image
  float chaosWarp = sin(p.x * 5.0 + time * 2.0) * sin(p.y * 5.0 + time * 1.7) * uChaos * 0.1;
  col *= 1.0 + chaosWarp;

  // Spectral flux sparkle overlay
  float sparkle = fract(sin(dot(floor(p * 40.0), vec2(12.9898, 78.233))) * 43758.5453);
  col += vec3(1.0) * step(0.99, sparkle) * uSpectralFlux * uSensitivity * 0.5;

  // Energy-driven overall brightness boost
  col *= 1.0 + energyVal * 0.3;

  // Vignette
  float vig = 1.0 - dot(vUv - 0.5, vUv - 0.5) * 1.2;
  col *= vig;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash22(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

// Voronoi returning cell center, distance, and cell ID
vec3 voronoiFull(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minD = 10.0;
  vec2 minCell = vec2(0.0);
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 pt = hash22(i + neighbor);
      vec2 diff = neighbor + pt - f;
      float d = dot(diff, diff);
      if (d < minD) {
        minD = d;
        minCell = i + neighbor;
      }
    }
  }
  return vec3(minCell, sqrt(minD));
}

// Smooth value noise
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM
float fbm4(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    val += amp * vnoise(p);
    p = p * 2.1 + vec2(1.7, 3.2);
    amp *= 0.5;
  }
  return val;
}

// Mushroom cap concentric rings
float mushroomRings(float dist, float cellSeed, float time) {
  float rings = sin(dist * (20.0 + cellSeed * 15.0) + time * 0.5) * 0.5 + 0.5;
  rings = smoothstep(0.3, 0.7, rings);
  return rings;
}

// Bioluminescent palette: forest green/violet/amber
vec3 fungalPalette(float t, float shift) {
  vec3 a = vec3(0.15, 0.25, 0.1);
  vec3 b = vec3(0.35, 0.2, 0.3);
  vec3 c = vec3(1.0, 1.5, 0.8);
  vec3 d = vec3(0.15 + shift * 0.2, 0.55, 0.3);
  return a + b * cos(6.2832 * (c * t + d));
}

// Mycelium network lines
float myceliumNetwork(vec2 p, float time) {
  float network = 0.0;
  for (float i = 0.0; i < 5.0; i += 1.0) {
    vec2 offset = vec2(sin(i * 2.3 + time * 0.1), cos(i * 1.7 + time * 0.08));
    float n = vnoise(p * (3.0 + i * 1.5) + offset * 2.0);
    float line = smoothstep(0.48, 0.5, n) * smoothstep(0.52, 0.5, n);
    network += line * (1.0 - i * 0.15);
  }
  return network;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float breathe = 1.0 + sin(uTime * 0.4) * 0.08;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Breathing displacement from bass
  vec2 breatheDispDisp = p + vec2(sin(time * 0.3 + bassVal * 3.0), cos(time * 0.25)) * bassVal * 0.08 + vec2(sin(time * 0.15) * 0.03, cos(time * 0.12) * 0.025);

  // Voronoi mushroom caps at two scales
  vec3 vor1 = voronoiFull(breatheDisp * 3.0 + time * 0.02);
  vec3 vor2 = voronoiFull(breatheDisp * 6.0 + vec2(50.0) + time * 0.015);

  float cellSeed1 = hash21(vor1.xy);
  float cellSeed2 = hash21(vor2.xy);

  // Mushroom cap rings
  float rings1 = mushroomRings(vor1.z, cellSeed1, time);
  float rings2 = mushroomRings(vor2.z, cellSeed2, time * 0.8);

  // Cap shape — dome falloff from cell center
  float dome1 = smoothstep(0.7, 0.0, vor1.z);
  float dome2 = smoothstep(0.5, 0.0, vor2.z) * 0.5;

  // Mycelium background network
  float mycelium = myceliumNetwork(breatheDisp, time);

  // Organic noise background
  float organic = fbm4(breatheDisp * 2.0 + time * 0.05);

  // === COLOR ===
  vec3 col = vec3(0.02, 0.04, 0.02); // dark forest floor

  // Mycelium network: faint glowing threads
  vec3 myceliumCol = fungalPalette(organic + time * 0.01, uPalette * 0.1) * 0.3;
  col += myceliumCol * mycelium * (0.6 + midsVal * 1.1);

  // Organic substrate
  col += vec3(0.03, 0.06, 0.03) * organic;

  // Primary mushroom caps
  vec3 capCol1 = fungalPalette(cellSeed1 + uPalette * 0.1, uPalette * 0.1);
  float capPattern1 = mix(dome1, dome1 * rings1, 0.6);
  col += capCol1 * capPattern1 * 0.7;

  // Secondary smaller caps
  vec3 capCol2 = fungalPalette(cellSeed2 + 0.3 + uPalette * 0.1, uPalette * 0.1 + 0.2);
  float capPattern2 = mix(dome2, dome2 * rings2, 0.5);
  col += capCol2 * capPattern2 * 0.4;

  // Bioluminescent glow — pulsing from cap centers
  float bioGlow = dome1 * (0.3 + sin(time * 2.0 + cellSeed1 * 10.0) * 0.2);
  bioGlow += midsVal * dome1 * 0.4;
  col += fungalPalette(cellSeed1 + 0.5, 0.3) * bioGlow * 0.5;

  // Spores floating upward on kicks
  float sporeAccum = 0.0;
  vec3 sporeCol = vec3(0.0);
  for (float i = 0.0; i < 20.0; i += 1.0) {
    float seed = hash21(vec2(i * 13.7, i * 7.3));
    float sporeX = (seed - 0.5) * 3.0;
    float sporePhase = fract(time * 0.15 + seed);
    float sporeY = mix(-1.5, 1.5, sporePhase) + sin(time * 1.5 + i) * 0.1;
    float sporeLift = kickVal * 0.3; // kick boosts upward
    sporeY += sporeLift;

    vec2 sporePos = vec2(sporeX, sporeY);
    float sporeDist = length(p - sporePos);
    float sporeGlow = 0.003 / (sporeDist * sporeDist + 0.001);
    float sporeFade = sin(sporePhase * 3.14159) ; // fade in/out

    sporeAccum += sporeGlow * sporeFade;
    sporeCol += fungalPalette(seed + i * 0.1, 0.5) * sporeGlow * sporeFade;
  }
  col += sporeCol * 0.15;

  // Treble sparkle on cap edges
  float edgeGlow = smoothstep(0.3, 0.4, vor1.z) * smoothstep(0.5, 0.4, vor1.z);
  col += vec3(0.6, 0.3, 0.8) * edgeGlow * trebleVal * 0.6;

  // Onset flash — bioluminescent burst
  col += fungalPalette(time * 0.1, 0.0) * uOnset * uSensitivity * 0.3;

  // Chaos: mutation colors
  float chaosMut = vnoise(p * (4.0 + uChaos * 10.0) + time * 0.3);
  vec3 mutCol = 0.5 + 0.5 * cos(chaosMut * 6.2832 + vec3(1.5, 3.5, 5.5));
  col = mix(col, mutCol * 0.3, uChaos * 0.2);

  // Spectral centroid hue shift
  col *= 1.0 + vec3(-0.05, 0.1, 0.05) * uSpectralCentroid * uSensitivity;

  col *= 1.0 + energyVal * 0.25;
  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGrowthRate;
uniform float uBranchDensity;
uniform float uSporeSize;

#define PI 3.14159265359
#define TAU 6.28318530718

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p, int octaves) {
  float v = 0.0;
  float a = 0.5;
  vec2 shift = vec2(100.0);
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    v += a * noise(p);
    p = p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

// Voronoi cellular pattern for moss cells
float voronoi(vec2 p, out vec2 cellCenter) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float minDist = 1.0;
  cellCenter = vec2(0.0);
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = vec2(hash(i + neighbor), hash(i + neighbor + vec2(37.0, 17.0)));
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      if (dist < minDist) {
        minDist = dist;
        cellCenter = i + neighbor + point;
      }
    }
  }
  return minDist;
}

// Branching tendril pattern
float tendril(vec2 p, float time, float density) {
  float val = 0.0;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float scale = density * (1.0 + fi * 0.5);
    float t = fbm(p * scale + vec2(time * 0.1 * (fi + 1.0), fi * 17.3), 4);
    float branch = smoothstep(0.45, 0.5, t) * smoothstep(0.55, 0.5, t);
    val += branch * (1.0 / (1.0 + fi));
  }
  return val;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.45;
  float breathe = 1.0 + sin(uTime * 0.35) * 0.07;
  p *= breathe;

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Growth frontier — expands with time and bass
  float growthTime = time * uGrowthRate * (1.0 + bassVal * 1.2 + sin(uTime * 0.2) * 0.08);
  float growthRadius = mod(growthTime, 4.0); // cycles

  // Distance from center
  float r = length(p);
  float growthMask = smoothstep(growthRadius + 0.3, growthRadius - 0.5, r);

  // Reaction-diffusion-like moss pattern
  float density = uBranchDensity * (1.0 + midsVal * 0.5);
  vec2 mossP = p + fbm(p * 2.0 + time * 0.05, 3) * 0.2 * uChaos;
  float mossPattern = fbm(mossP * density, 6);

  // Threshold for moss coverage
  float mossCoverage = smoothstep(0.3 - growthMask * 0.2, 0.5, mossPattern);

  // Tendril branches at growth frontier
  float tendrils = tendril(p, growthTime, density * 0.8);
  float frontierDist = abs(r - growthRadius);
  float frontierMask = smoothstep(0.5, 0.0, frontierDist);
  tendrils *= frontierMask;

  // Voronoi cells for lichen texture
  vec2 cellCenter;
  float cellDist = voronoi(p * density * 1.5, cellCenter);
  float lichenEdge = smoothstep(0.05, 0.0, cellDist - 0.3) * growthMask;
  float lichenInner = smoothstep(0.3, 0.0, cellDist) * growthMask;

  // Spore particles floating above
  float spores = 0.0;
  for (int i = 0; i < 20; i++) {
    float fi = float(i);
    float sporeTime = time * (0.3 + hash(vec2(fi, 0.0)) * 0.4);
    vec2 sporePos = vec2(
      sin(fi * 1.618 + sporeTime * 0.7) * (0.5 + hash(vec2(fi, 1.0)) * 1.0),
      cos(fi * 2.314 + sporeTime * 0.5) * (0.5 + hash(vec2(fi, 2.0)) * 1.0)
    );
    sporePos += vec2(sin(sporeTime + fi), cos(sporeTime * 0.7 + fi)) * 0.1;
    float d = length(p - sporePos);
    float size = uSporeSize * 0.01 * (0.5 + hash(vec2(fi, 3.0)) * 0.5);
    float brightness = 0.5 + 0.5 * sin(sporeTime * 2.0 + fi);
    spores += smoothstep(size, size * 0.2, d) * brightness * trebleVal;
  }

  // Color palette: mossy greens, teals, earth tones
  float hueBase = 0.25 + uPalette * 0.08; // green-teal range
  float hueVar = mossPattern * 0.1 + cellDist * 0.05;

  vec3 mossColorDark = 0.5 + 0.5 * cos(TAU * (hueBase + hueVar + vec3(0.0, 0.15, 0.3)));
  vec3 mossColorLight = 0.5 + 0.5 * cos(TAU * (hueBase + hueVar + 0.1 + vec3(0.0, 0.1, 0.25)));
  vec3 tendrilColor = vec3(0.15, 0.6, 0.35) + vec3(0.07) * sin(time);
  vec3 sporeColor = vec3(0.7, 1.0, 0.6);

  // Assemble
  vec3 col = vec3(0.0);

  // Base moss
  col += mossColorDark * mossCoverage * 0.6;
  col += mossColorLight * lichenInner * 0.5;

  // Lichen edges glow
  col += tendrilColor * lichenEdge * 0.3;

  // Growth tendrils
  col += tendrilColor * tendrils * 1.5;

  // Spore particles
  col += sporeColor * spores * 1.5;

  // Depth/height shading
  float height = mossPattern * growthMask;
  col *= 0.5 + height * 0.5;

  // Beat pulse — growth frontier brightens
  col += tendrilColor * frontierMask * beatPulse * 0.5;

  // Onset — new growth burst
  col += mossColorLight * onsetFlash * 0.2 * growthMask;

  // Chaos adds organic distortion
  float chaosNoise = fbm(p * (4.0 + uChaos * 8.0) + time, 4) * uChaos * 0.3;
  col += mossColorDark * chaosNoise * 0.2;

  // Background: dark earth
  vec3 bg = vec3(0.02, 0.03, 0.02) + vec3(0.02, 0.03, 0.01) * noise(p * 5.0 + time * 0.05);
  col = max(col, bg);

  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPortalSize;
uniform float uMembraneRipple;
uniform float uDimensionBleed;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noise(p);
    p *= 2.1;
    amp *= 0.5;
  }
  return val;
}

// Warped FBM for organic flowing patterns
float warpFbm(vec2 p, float t) {
  vec2 q = vec2(fbm(p + t * 0.1), fbm(p + vec2(5.2, 1.3)));
  return fbm(p + q * 3.0);
}

void main() {
  vec2 p = (vUv - 0.5) * (1.5 + uZoom * 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.6;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetPulse = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // === PORTAL SHAPE: irregular oval with rippling edge — enlarged to fill screen ===
  float portalR = uPortalSize * 1.2 * (1.0 + bassVal * 0.6);

  // Rippling edge — use integer angle multipliers to avoid seam at atan boundary
  float rippleFreq = floor(5.0 + uMembraneRipple * 8.0 + 0.5);
  float rippleAmp = uMembraneRipple * 0.12 * (1.0 + midsVal * 1.0);
  float edgeRipple = sin(angle * rippleFreq + time * 3.0) * rippleAmp;
  float rippleFreq2 = floor(rippleFreq * 1.7 + 0.5);
  edgeRipple += sin(angle * rippleFreq2 - time * 2.0) * rippleAmp * 0.5;
  // Use sin/cos of angle for seamless noise sampling (no atan discontinuity)
  edgeRipple += noise(vec2(sin(angle * 3.0) * 3.0, cos(angle * 3.0) * 3.0 + time * 2.0)) * rippleAmp * 0.8;

  // Slight oval shape
  float ovalR = portalR * (1.0 + 0.1 * cos(angle * 2.0 + time * 0.3));
  float portalEdge = ovalR + edgeRipple;

  // Portal zones
  float insidePortal = smoothstep(portalEdge, portalEdge - 0.05, r);
  float atEdge = smoothstep(portalEdge + 0.08, portalEdge, r) *
                 smoothstep(portalEdge - 0.08, portalEdge, r);
  float outsidePortal = 1.0 - insidePortal;

  // === OUR UNIVERSE (outside portal): warm golden-orange ===
  float ourNoise = warpFbm(p * 2.0 + time * 0.1, time);
  float ourNoise2 = fbm(p * 4.0 - time * 0.08 + 20.0);

  vec3 ourUniverse = vec3(0.0);
  ourUniverse.r = ourNoise * 0.25 + ourNoise2 * 0.1 + 0.03;
  ourUniverse.g = ourNoise * 0.12 + ourNoise2 * 0.06 + 0.01;
  ourUniverse.b = ourNoise * 0.05 + 0.005;
  ourUniverse *= outsidePortal;

  // Stars in our universe
  float starGrid = 100.0;
  vec2 starCell = floor(p * starGrid);
  float starH = hash(starCell);
  if (starH > 0.985) {
    vec2 starFrac = fract(p * starGrid) - vec2(hash(starCell + 5.0), hash(starCell + 11.0));
    float sDist = dot(starFrac, starFrac);
    float starGlow = exp(-sDist * 1500.0) * 0.3;
    ourUniverse += vec3(0.8, 0.7, 0.5) * starGlow * outsidePortal;
  }

  // === ALTERNATE DIMENSION (inside portal): cool cyan-violet ===
  // Different physics: reversed time, different noise patterns
  float altTime = -time * 1.3; // reversed time flow
  vec2 altP = p * 1.5; // different scale
  // Rotate coordinates in alternate dimension
  float altAngle = time * 0.2;
  float ca = cos(altAngle);
  float sa = sin(altAngle);
  altP = vec2(altP.x * ca - altP.y * sa, altP.x * sa + altP.y * ca);

  float altNoise = warpFbm(altP * 2.0 + altTime * 0.15, altTime);
  float altNoise2 = fbm(altP * 3.0 + altTime * 0.1 + 50.0);
  float altNoise3 = fbm(altP * 6.0 - altTime * 0.2);

  vec3 altDimension = vec3(0.0);
  altDimension.r = altNoise2 * 0.12 + altNoise3 * 0.08;
  altDimension.g = altNoise * 0.22 + altNoise2 * 0.15 + 0.03;
  altDimension.b = altNoise * 0.45 + altNoise3 * 0.22 + 0.08;
  // Violet tones
  altDimension.r += altNoise3 * 0.18;
  altDimension *= insidePortal;

  // Alien stars in alternate dimension
  float altStarGrid = 80.0;
  vec2 altStarCell = floor(altP * altStarGrid);
  float altStarH = hash(altStarCell);
  if (altStarH > 0.982) {
    vec2 altStarFrac = fract(altP * altStarGrid) - vec2(hash(altStarCell + 5.0), hash(altStarCell + 11.0));
    float asDist = dot(altStarFrac, altStarFrac);
    float asGlow = exp(-asDist * 1200.0) * 0.4;
    altDimension += vec3(0.5, 0.85, 1.0) * asGlow * insidePortal;
  }

  // Strange geometric structures in alternate dimension
  float geomPattern = sin(altP.x * 10.0 + altTime) * sin(altP.y * 10.0 - altTime * 0.7);
  geomPattern = smoothstep(0.8, 0.95, abs(geomPattern));
  altDimension += vec3(0.15, 0.3, 0.55) * geomPattern * insidePortal * 0.45;

  // === PORTAL RIM: energy crackling ===
  float rimGlow = atEdge * (2.0 + trebleVal * 6.0 + onsetPulse * 4.0);

  // Electric crackle along rim
  float crackle = 0.0;
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float crackAngle = fi * 0.785 + time * 2.0;
    float crackNoise = noise(vec2(crackAngle * 3.0 + time * 10.0, fi * 7.0));
    float localAngle = mod(angle - crackAngle + 3.14159, 6.28318) - 3.14159;
    float spark = exp(-localAngle * localAngle * 50.0) * crackNoise * atEdge;
    crackle += spark;
  }
  crackle *= trebleVal * 4.0;

  vec3 rimCol = vec3(0.65, 0.4, 1.0) * rimGlow;
  rimCol += vec3(0.9, 0.95, 1.0) * crackle;
  rimCol += vec3(0.4, 0.7, 1.0) * atEdge * 0.7; // base rim color

  // === DIMENSION BLEED: colors leak across the boundary ===
  float bleedZone = smoothstep(portalEdge + 0.35, portalEdge, r) *
                    smoothstep(portalEdge - 0.35, portalEdge, r);
  float bleedAmount = uDimensionBleed * (1.0 + uChaos * 0.5);

  // Alt dimension colors bleeding outside
  vec3 bleedOut = vec3(0.05, 0.1, 0.2) * bleedAmount * bleedZone * outsidePortal;
  // Our colors bleeding inside
  vec3 bleedIn = vec3(0.15, 0.08, 0.02) * bleedAmount * bleedZone * insidePortal;

  // === REALITY FRAGMENTS: pieces drifting through portal ===
  float fragments = 0.0;
  for (int i = 0; i < 10; i++) {
    float fi = float(i);
    float fragAngle = fi * 0.628 + time * 0.5;
    float fragR = portalEdge + sin(time * 0.8 + fi * 2.0) * 0.25;
    vec2 fragPos = vec2(cos(fragAngle), sin(fragAngle)) * fragR;
    float fragDist = length(p - fragPos);
    float frag = exp(-fragDist * fragDist * 100.0) * (0.5 + beatPulse * 2.0);
    fragments += frag;
  }
  vec3 fragCol = mix(vec3(1.0, 0.75, 0.3), vec3(0.3, 0.65, 1.0), sin(time * 0.5) * 0.5 + 0.5) * fragments;

  // === ONSET BREACH FLASH ===
  float breach = exp(-r * r * 2.0) * onsetPulse * 1.0;
  vec3 breachCol = vec3(1.0, 0.9, 1.0) * breach;

  // === COMBINE ===
  vec3 col = ourUniverse + altDimension + rimCol + bleedOut + bleedIn + fragCol + breachCol;

  // Beat pulse
  col += vec3(0.15, 0.08, 0.22) * beatPulse * 0.2 * (atEdge + insidePortal * 0.3);

  col *= (0.8 + uEnergy * uSensitivity * 0.6);
  col *= uIntensity * 1.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uMushroomCount;
uniform float uSporeRate;
uniform float uMyceliumDensity;
uniform float uGlowPulse;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noise(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Lifecycle phase for each mushroom: 0-1 continuous, maps to sprout/grow/mature/wilt/decay
// Returns: 0=dead/seed, 0-0.2=sprouting, 0.2-0.5=growing, 0.5-0.75=mature, 0.75-0.95=wilting, 0.95-1.0=decaying
float mushroomLifecycle(float time, float offset, float cycleDuration) {
  return fract((time + offset) / cycleDuration);
}

// Growth scale based on lifecycle phase
float growthScale(float phase) {
  // Sprout: 0 -> 0.2 (tiny bud to small)
  float sprout = smoothstep(0.0, 0.2, phase);
  // Grow: 0.2 -> 0.5 (small to full size)
  float grow = smoothstep(0.2, 0.5, phase);
  // Full maturity is mix of sprout and grow
  float fullSize = sprout * 0.3 + grow * 0.7;
  // Wilt: 0.75 -> 0.95 (shrink and droop)
  float wilt = 1.0 - smoothstep(0.75, 0.95, phase) * 0.6;
  // Decay: 0.95 -> 1.0 (collapse to nothing)
  float decay = 1.0 - smoothstep(0.92, 1.0, phase);
  return fullSize * wilt * decay;
}

// Droop amount for wilting mushrooms
float droopAmount(float phase) {
  return smoothstep(0.7, 0.95, phase) * 0.15;
}

// Glow intensity varies with lifecycle — brightest at maturity, dim when young/dying
float lifecycleGlow(float phase) {
  float young = smoothstep(0.0, 0.3, phase);
  float mature = smoothstep(0.4, 0.55, phase) * (1.0 - smoothstep(0.55, 0.7, phase)) * 0.5 + 0.5;
  float dying = 1.0 - smoothstep(0.8, 1.0, phase) * 0.8;
  return young * mature * dying;
}

// Signed distance to a mushroom cap with lifecycle
float sdMushroomLife(vec2 p, vec2 center, float capW, float capH, float stemW, float stemH, float droop) {
  // Cap (upper ellipse) — droops to one side when wilting
  vec2 capP = p - center - vec2(droop, stemH);
  float capDist = length(capP / vec2(capW, capH)) - 1.0;
  // Stem (rectangle) — bends slightly when drooping
  vec2 stemP = p - center - vec2(droop * (p.y - center.y) / max(stemH, 0.01) * 0.5, 0.0);
  float stemDist = max(abs(stemP.x) - stemW * 0.3, max(stemP.y - stemH, -stemP.y));
  return min(capDist * capW, stemDist);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.9;
  float breathe = 1.0 + sin(uTime * 0.4) * 0.08;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Dark forest floor background — full screen
  float floorGrad = smoothstep(-1.0, 0.5, p.y);
  vec3 bgColor = mix(vec3(0.01, 0.005, 0.02), vec3(0.015, 0.008, 0.025), floorGrad);
  // Floor texture with more depth
  float floorNoise = fbm(p * 5.0 + time * 0.05) * 0.02;
  float floorNoise2 = fbm(p * 8.0 - time * 0.03) * 0.015;
  bgColor += vec3(floorNoise * 0.5, floorNoise + floorNoise2, floorNoise * 0.3 + floorNoise2 * 0.5);
  // Undergrowth glow (ambient bioluminescence on the ground)
  float underglow = fbm(p * 3.0 + vec2(time * 0.02, 0.0)) * 0.03;
  bgColor += vec3(0.0, underglow, underglow * 0.5);

  vec3 mushColor = vec3(0.0);
  vec3 sporeAccum = vec3(0.0);

  float palette = uPalette * 0.15;
  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.4) * 0.04, cos(p.x * 3.5 + time * 0.3) * 0.04) * (1.0 + bassVal * 0.3);

  float glowMod = uGlowPulse + bassVal * 0.8;

  // Bass-driven growth spurt multiplier — 2x
  float growthSpurt = 1.0 + bassVal * 0.8 + sin(uTime * 0.25) * 0.06;

  // 12 mushrooms with staggered lifecycles across the full screen
  // Each mushroom has a unique position, lifecycle offset, cycle duration, color, and size
  for (int mi = 0; mi < 12; mi++) {
    float fi = float(mi);
    // Unique seed per mushroom
    float seed = hash1(fi * 73.17 + 31.1);
    float seed2 = hash1(fi * 137.3 + 57.9);
    float seed3 = hash1(fi * 251.7 + 113.3);

    // Position spread across full screen — each generation shifts slightly
    float generation = floor((time + seed * 20.0) / (8.0 + seed * 12.0));
    float genSeed = hash1(fi * 47.3 + generation * 13.7);
    float genSeed2 = hash1(fi * 89.1 + generation * 23.1);

    float baseX = (seed - 0.5) * 2.2 + (genSeed - 0.5) * 0.3;
    float baseY = (seed2 - 0.5) * 1.8 + (genSeed2 - 0.5) * 0.15;
    vec2 mPos = vec2(baseX, baseY);

    // Lifecycle parameters
    float cycleDuration = 8.0 + seed * 12.0; // 8-20 second cycles
    float offset = seed * cycleDuration;       // staggered starts
    float phase = mushroomLifecycle(time, offset, cycleDuration);

    // Growth scale with bass spurts
    float scale = growthScale(phase) * growthSpurt;
    float droop = droopAmount(phase) * (seed3 > 0.5 ? 1.0 : -1.0); // droop left or right
    float glowLife = lifecycleGlow(phase);

    // Skip if essentially invisible
    if (scale < 0.01) continue;

    // Size varies per mushroom — larger to fill screen
    float sizeMult = 0.7 + seed3 * 1.3;
    float capW = 0.15 * sizeMult * scale;
    float capH = 0.07 * sizeMult * scale;
    float stemW = 0.14 * sizeMult * scale;
    float stemH = (0.25 + seed2 * 0.45) * sizeMult * scale + beatPulse * 0.04 * scale;

    float d = sdMushroomLife(p, mPos, capW, capH, stemW, stemH, droop * scale);
    float glow = exp(-max(d, 0.0) * (12.0 + seed * 8.0));

    // Color per mushroom — faster cycling through bioluminescent palette
    float hueBase = fi * 0.125 + palette + time * 0.06 + sin(uTime * 0.3) * 0.15;
    vec3 mCol = vec3(
      0.5 + 0.5 * sin(hueBase * 6.28),
      0.5 + 0.5 * sin(hueBase * 6.28 + 2.094),
      0.5 + 0.5 * sin(hueBase * 6.28 + 4.189)
    );
    // Boost saturation
    mCol = mix(vec3(dot(mCol, vec3(0.33))), mCol, 1.5);
    mCol = clamp(mCol, 0.0, 1.0);

    float pulse = sin(time * (1.0 + seed * 0.8) + seed * 6.28) * 0.3 + 0.7 + glowMod * 0.3;
    mushColor += mCol * glow * pulse * glowLife;

    // Spore release from cap when treble is high and mushroom is mature (phase 0.4-0.8)
    float sporePhase = smoothstep(0.4, 0.55, phase) * (1.0 - smoothstep(0.75, 0.9, phase));
    float sporeEmit = sporePhase * trebleVal * 1.5;
    if (sporeEmit > 0.05) {
      // Spore particles rising from cap position
      vec2 capPos = mPos + vec2(droop * scale, stemH);
      for (int si = 0; si < 4; si++) {
        float sf = float(si);
        float sHash = hash1(fi * 17.3 + sf * 7.1 + generation * 3.7);
        float sHash2 = hash1(fi * 23.1 + sf * 11.3 + generation * 5.1);
        vec2 sporeP = capPos + vec2(
          sin(time * 3.0 + sHash * 6.28) * 0.05 * (1.0 + sHash),
          mod(time * 0.4 + sHash * 2.0, 0.6) * (0.3 + sHash2 * 0.3)
        );
        float sporeDist = length(p - sporeP);
        float sporeGlow = exp(-sporeDist * sporeDist * 800.0) * sporeEmit;
        sporeAccum += mCol * 0.6 * sporeGlow * (0.5 + sin(time * 5.0 + sHash * 10.0) * 0.5);
      }
    }
  }

  // Mycelium network — dynamic connections between living mushrooms
  // Use a grid-based approach for organic underground network
  float mycelium = 0.0;
  float mycelGrid = 6.0 * uMyceliumDensity + 2.0;
  vec2 mycelUv = p * mycelGrid;
  vec2 mycelId = floor(mycelUv);
  vec2 mycelF = fract(mycelUv) - 0.5;

  for (int mx = -1; mx <= 1; mx++) {
    for (int my = -1; my <= 1; my++) {
      vec2 neighbor = mycelId + vec2(float(mx), float(my));
      float nHash = hash(neighbor);
      float nHash2 = hash(neighbor + vec2(37.0, 73.0));
      // Only some cells have mycelium nodes
      if (nHash > 0.55) continue;
      vec2 nodePos = vec2(float(mx), float(my)) + vec2(nHash, nHash2) - 0.5;
      float nodeDist = length(mycelF - nodePos);
      // Branching tendrils
      float tendril = noise(vec2(atan(mycelF.y - nodePos.y, mycelF.x - nodePos.x) * 3.0 + nHash * 10.0, nodeDist * 8.0 - time * 0.5));
      float tendrilLine = exp(-nodeDist * 8.0) * tendril;
      float pulse = sin(nodeDist * 15.0 - time * 2.5 + nHash * 6.28) * 0.4 + 0.6;
      pulse += trebleVal * 0.4;
      mycelium += tendrilLine * pulse * 0.15;
    }
  }
  // Mycelium across the full screen
  mycelium *= smoothstep(1.0, -0.5, p.y);
  vec3 myceliumColor = vec3(0.2, 0.6, 0.8) * mycelium;

  // Additional rising spore clouds (ambient)
  float spores = 0.0;
  float sporeGrid = 30.0 + uSporeRate * 20.0;
  vec2 sporeUv = vec2(p.x * sporeGrid, (p.y + time * 0.3) * sporeGrid * 0.7);
  vec2 sporeId = floor(sporeUv);
  vec2 sporeF = fract(sporeUv) - 0.5;
  float sporeH = hash(sporeId);
  float sporeOn = step(0.85 - midsVal * 0.08 - onsetFlash * 0.15, sporeH);
  float sporeDrift = sin(sporeH * 6.28 + time * 2.0) * 0.15;
  float sporeDist = length(sporeF - vec2(sporeDrift, 0.0));
  spores = sporeOn * exp(-sporeDist * sporeDist * 500.0);
  spores *= (0.5 + sin(time * 4.0 + sporeH * 12.0) * 0.5) * 0.5;
  spores *= smoothstep(-1.0, 0.2, p.y);
  vec3 sporeColor = vec3(0.3, 0.7, 0.25) * spores;

  // Combine
  vec3 finalColor = bgColor + mushColor * uIntensity + myceliumColor * uIntensity + sporeColor + sporeAccum + beatPulse * vec3(0.04, 0.08, 0.04);

  // Onset flash — massive spore burst brightness — 2x
  finalColor += onsetFlash * vec3(0.3, 0.6, 0.2);

  // Extreme contrast
  finalColor = pow(finalColor, vec3(0.85));
  finalColor = smoothstep(vec3(0.0), vec3(0.9), finalColor);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBranchDensity;
uniform float uGlowWidth;
uniform float uPulseSpeed;
uniform float uSporeAmount;

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

float hash1(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Voronoi with edge distance for branch patterns
vec3 voronoiEdges(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);

  float minDist1 = 1.0;
  float minDist2 = 1.0;
  vec2 nearestCell = vec2(0.0);

  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash2(i + neighbor);
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      if (dist < minDist1) {
        minDist2 = minDist1;
        minDist1 = dist;
        nearestCell = i + neighbor;
      } else if (dist < minDist2) {
        minDist2 = dist;
      }
    }
  }

  float edgeDist = minDist2 - minDist1;
  return vec3(edgeDist, nearestCell);
}

// Layered Voronoi for multi-scale branching
float branchNetwork(vec2 p, float time, float bassVal) {
  float branches = 0.0;

  // Large-scale branches
  vec3 v1 = voronoiEdges(p * 1.0 + vec2(time * 0.05, time * 0.03));
  branches += smoothstep(0.08, 0.0, v1.x) * 1.0;

  // Medium branches
  vec3 v2 = voronoiEdges(p * 2.2 + vec2(-time * 0.07, time * 0.04));
  branches += smoothstep(0.06, 0.0, v2.x) * 0.7;

  // Fine branches (audio reactive — appear on bass)
  vec3 v3 = voronoiEdges(p * 4.5 + vec2(time * 0.1, -time * 0.06));
  branches += smoothstep(0.05, 0.0, v3.x) * (0.4 + bassVal * 0.7);

  return branches;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 0.75);

  // Audio influences
  float bassGrowth = bass() * uSensitivity;
  float midsBranch = mids() * uSensitivity;
  float trebleSpore = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Radial growth: network expands from center on bass
  float r = length(p);
  float growthRadius = 1.5 + bassGrowth * 0.8 + sin(time * 0.3) * 0.3 + sin(uTime * 0.15) * 0.1;
  float growthMask = smoothstep(growthRadius, growthRadius * 0.3, r);

  // Scale branching by density param
  vec2 branchP = p * uBranchDensity;

  // Build multi-scale branch network
  float branches = branchNetwork(branchP, time, bassGrowth);

  // Expand glow width with param
  float glowBranches = 0.0;
  vec3 v1g = voronoiEdges(branchP * 1.0 + vec2(time * 0.05, time * 0.03));
  glowBranches += smoothstep(uGlowWidth * 2.0, 0.0, v1g.x);
  vec3 v2g = voronoiEdges(branchP * 2.2 + vec2(-time * 0.07, time * 0.04));
  glowBranches += smoothstep(uGlowWidth * 1.5, 0.0, v2g.x) * 0.6;

  // Nutrient pulse traveling along branches
  float pulseWave = sin(v1g.y * 3.0 + v1g.z * 2.0 - time * uPulseSpeed * 3.0 + beatPulse * 6.2832) * 0.5 + 0.5;
  float nutrientPulse = pulseWave * branches;

  // Spore particles (hash-based sparkle)
  float sporeGrid = 60.0;
  vec2 sporeCell = floor(p * sporeGrid);
  float sporeSeed = hash1(sporeCell);
  float sporeActive = step(1.0 - uSporeAmount * 0.15 - trebleSpore * 0.1, sporeSeed);
  float sporeTwinkle = sin(time * 4.0 + sporeSeed * 6.2832) * 0.5 + 0.5;
  vec2 sporeOffset = hash2(sporeCell) - 0.5;
  vec2 sporePos = (sporeCell + 0.5 + sporeOffset) / sporeGrid;
  float sporeDist = length(vUv - 0.5 - sporePos * 0.5 / (uZoom * 2.0 + 0.5));
  float sporeGlow = sporeActive * sporeTwinkle * smoothstep(0.01, 0.0, sporeDist) * 0.6;

  // Color: bioluminescent greens, cyans, and white-gold
  float hue = fract(
    0.3 + uPalette * 0.1
    + nutrientPulse * 0.1
    + r * 0.05
    + time * 0.01
  );
  float palettePhase = hue * 6.2832;
  vec3 branchColor = 0.5 + 0.5 * cos(palettePhase + vec3(0.0, 1.0, 2.5));
  branchColor *= 1.5; // boost saturation

  // Glow color: slightly warmer
  vec3 glowColor = 0.5 + 0.5 * cos(palettePhase + vec3(0.3, 0.8, 2.2));

  // Nutrient pulse: bright white-gold
  vec3 pulseColor = vec3(1.0, 0.95, 0.7) * nutrientPulse * 0.8;

  // Combine
  vec3 col = vec3(0.01, 0.005, 0.02); // dark background

  // Branch glow (soft outer)
  col += glowColor * glowBranches * 0.3 * growthMask;

  // Branch core (bright inner)
  col += branchColor * branches * 0.6 * growthMask;

  // Nutrient pulse
  col += pulseColor * growthMask;

  // Spore particles
  col += vec3(0.6, 0.9, 0.7) * sporeGlow;

  // Beat brightness on branches
  col += branchColor * beatPulse * 0.15 * branches * growthMask;

  // Onset: network-wide flash
  col += vec3(0.1, 0.2, 0.15) * onsetFlash * growthMask;

  // Chaos adds turbulent displacement
  float chaosWarp = sin(r * 10.0 * uChaos + time * 2.0) * uChaos * 0.1;
  col *= 1.0 + chaosWarp;

  // Final intensity
  col *= uIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGasCompression;
uniform float uStarIgnitionRate;
uniform float uTurbulenceScale;
uniform float uEmissionStrength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    val += amp * noise(p);
    p = rot * p * 2.0;
    amp *= 0.5;
  }
  return val;
}

// Domain warping for realistic gas dynamics
vec2 warpField(vec2 p, float t) {
  float n1 = fbm(p * 1.5 + vec2(t * 0.05, t * 0.03), 5);
  float n2 = fbm(p * 1.5 + vec2(5.2 + t * 0.04, 1.3 - t * 0.05), 5);
  return vec2(n1, n2) - 0.5;
}

// Nebula emission color based on ionized gas species
vec3 nebulaEmission(float t, float shift) {
  // Hydrogen-alpha: pink/red
  vec3 hAlpha = vec3(1.0, 0.25, 0.45);
  // Oxygen III: teal/cyan
  vec3 oIII = vec3(0.15, 0.85, 0.9);
  // Sulfur II: amber/gold
  vec3 sII = vec3(1.0, 0.8, 0.25);
  // Hot blue: young star radiation
  vec3 hotBlue = vec3(0.4, 0.5, 1.0);

  float phase = fract(t + shift);
  vec3 c = mix(hAlpha, oIII, smoothstep(0.0, 0.33, phase));
  c = mix(c, sII, smoothstep(0.33, 0.67, phase));
  c = mix(c, hotBlue, smoothstep(0.67, 1.0, phase));
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Slow cosmic rotation
  float rotAngle = time * 0.05;
  float cosR = cos(rotAngle);
  float sinR = sin(rotAngle);
  vec2 rp = vec2(p.x * cosR - p.y * sinR, p.x * sinR + p.y * cosR);

  // Bass compresses space toward center (gravitational collapse)
  float compression = 1.0 + bassVal * uGasCompression * 1.0;
  rp *= compression;

  // Turbulence scale
  float turbScale = 1.0 + uTurbulenceScale;

  // === MULTI-LAYER GAS CLOUDS ===

  // Domain warping — creates swirling gas dynamics
  vec2 warp1 = warpField(rp * turbScale, time);
  vec2 warp2 = warpField(rp * turbScale * 1.5 + warp1 * 2.0 + vec2(10.0), time * 0.8);
  vec2 warp3 = warpField(rp * turbScale * 0.7 + warp2 * 1.5 + vec2(20.0), time * 1.2);

  // Mids increase turbulence intensity
  float turbMult = 1.0 + midsVal * 1.0;
  vec2 warpedP1 = rp + warp1 * 0.3 * turbMult;
  vec2 warpedP2 = rp + warp2 * 0.4 * turbMult;
  vec2 warpedP3 = rp + warp3 * 0.25 * turbMult;

  // Gas density layers
  float gas1 = fbm(warpedP1 * 2.0 + vec2(time * 0.02), 6);
  float gas2 = fbm(warpedP2 * 3.0 + vec2(-time * 0.015, time * 0.02), 6);
  float gas3 = fbm(warpedP3 * 1.5 + vec2(time * 0.01), 5);
  float gas4 = fbm(rp * 5.0 + warp1 * 1.0 + vec2(30.0, time * 0.03), 4);

  // Composite gas density
  float density = gas1 * 0.4 + gas2 * 0.3 + gas3 * 0.2 + gas4 * 0.1;

  // Dense cores — regions of high gas concentration
  float core1Dist = length(rp - warp1 * 0.5 + vec2(0.2, -0.1));
  float core2Dist = length(rp - warp2 * 0.3 - vec2(0.3, 0.2));
  float core1 = exp(-core1Dist * core1Dist * 3.0) * 0.4;
  float core2 = exp(-core2Dist * core2Dist * 4.0) * 0.3;
  density += core1 + core2;

  // Beat compresses gas further
  density += beatPulse * 0.1 * exp(-length(rp) * 2.0);

  // === NEBULA COLORING ===
  // Different regions have different emission colors
  float colorRegion1 = fbm(rp * 0.8 + vec2(time * 0.01, 50.0), 4);
  float colorRegion2 = fbm(rp * 1.2 + vec2(60.0, -time * 0.008), 4);
  float colorMix = colorRegion1 * 0.6 + colorRegion2 * 0.4;

  vec3 emission1 = nebulaEmission(colorMix, uPalette * 0.1);
  vec3 emission2 = nebulaEmission(colorMix + 0.33, uPalette * 0.1 + 0.15);
  vec3 emission3 = nebulaEmission(colorMix + 0.67, uPalette * 0.1 + 0.3);

  // Blend emission colors by spatial region
  float regionBlend = fbm(rp * 1.0 + vec2(70.0), 3);
  vec3 nebulaCol = mix(emission1, emission2, smoothstep(0.3, 0.7, regionBlend));
  nebulaCol = mix(nebulaCol, emission3, smoothstep(0.5, 0.9, density));

  // Gas opacity and brightness
  float gasBright = density * uEmissionStrength * 2.2;
  gasBright = pow(gasBright, 0.8); // Gamma for richer midtones

  vec3 col = nebulaCol * gasBright;

  // Dark dust lanes (absorption)
  float dust = fbm(rp * 4.0 + warp1 * 2.0 + vec2(80.0), 5);
  float dustMask = smoothstep(0.35, 0.55, dust);
  col *= mix(0.3, 1.0, dustMask);

  // === STARS ===
  float starAccum = 0.0;
  vec3 starColorAccum = vec3(0.0);

  // Background star field
  for (int layer = 0; layer < 3; layer++) {
    float fl = float(layer);
    float starGrid = 25.0 + fl * 15.0;
    vec2 starUV = rp * starGrid;
    vec2 starId = floor(starUV);
    vec2 starF = fract(starUV) - 0.5;

    float starSeed = hash(starId + vec2(fl * 100.0));
    float starSize = 0.3 + starSeed * 0.7;

    // Star visible threshold — treble ignites more stars
    float threshold = 0.93 - uStarIgnitionRate * 0.04 - trebleVal * 0.03;
    float starOn = step(threshold, starSeed);

    float starDist = length(starF);
    float starBright = starOn * exp(-starDist * starDist * (800.0 + fl * 500.0)) * starSize;

    // Twinkle
    float twinkle = sin(time * (3.0 + starSeed * 5.0) + starSeed * 50.0) * 0.2 + 0.8;
    starBright *= twinkle;

    // New star ignition flash on treble
    float ignitionPhase = sin(time * 2.0 + starSeed * 30.0);
    float ignition = smoothstep(0.8, 1.0, ignitionPhase) * trebleVal * 2.0;
    starBright += starOn * ignition * exp(-starDist * starDist * 500.0);

    // Star color: blue-white for hot, yellow for cool
    vec3 starCol = mix(
      vec3(0.7, 0.8, 1.0),  // Blue-white
      vec3(1.0, 0.9, 0.6),  // Yellow
      step(0.6, fract(starSeed * 7.3))
    );
    // Very hot stars (rare)
    starCol = mix(starCol, vec3(0.5, 0.6, 1.0), step(0.95, starSeed));

    starAccum += starBright;
    starColorAccum += starCol * starBright;
  }

  // Stars behind gas (dimmed by density) and in front
  float starBehind = starAccum * (1.0 - density * 0.7);
  col += starColorAccum * (1.0 - density * 0.7);

  // Embedded bright stars (born inside the nebula)
  float embeddedGrid = 15.0;
  vec2 embUV = rp * embeddedGrid;
  vec2 embId = floor(embUV);
  vec2 embF = fract(embUV) - 0.5;
  float embSeed = hash(embId + vec2(999.0));
  float embOn = step(0.96 - uStarIgnitionRate * 0.03, embSeed);
  float embDist = length(embF);

  // Bright emission halo around embedded stars
  float embStar = embOn * exp(-embDist * embDist * 300.0) * 1.5;
  float embHalo = embOn * exp(-embDist * embDist * 30.0) * 0.3;

  // Ignition pulse
  float embIgnite = sin(time * 1.5 + embSeed * 20.0) * 0.3 + 0.7;
  embIgnite += midsVal * 0.5;

  vec3 embColor = mix(vec3(1.0, 0.95, 0.8), vec3(0.8, 0.9, 1.0), step(0.5, fract(embSeed * 3.7)));
  col += embColor * embStar * embIgnite;
  col += nebulaCol * 1.5 * embHalo * embIgnite; // Illuminated gas around star

  // === KICK: Supernova shockwave ===
  float shockCenter = length(rp);
  float shockRadius = kickVal * 4.0 + onsetVal * 3.0;
  float shockRing = abs(shockCenter - shockRadius * 0.5) - 0.03;
  float shock = exp(-shockRing * shockRing * 200.0) * (kickVal + onsetVal * 0.5) * 0.6;
  col += vec3(0.6, 0.7, 1.0) * shock;

  // Shockwave illuminates nearby gas
  float shockIllum = (kickVal + onsetVal * 0.3) * exp(-shockCenter * 3.0) * 0.2;
  col += nebulaCol * shockIllum;

  // === BEAT: emission brightness pulse ===
  col *= 1.0 + beatPulse * 0.4;

  // Energy overall glow
  col *= 1.0 + energyVal * 0.3;

  // Chaos adds extra turbulence and color variety
  float chaosColor = fbm(rp * 3.0 + vec2(time * 0.1, 90.0), 3) * uChaos;
  col += nebulaEmission(chaosColor, 0.5) * chaosColor * 0.1;

  // Ambient deep space glow
  col += nebulaCol * 0.02;

  // Intensity
  col *= uIntensity * 1.6;

  // Subtle vignette
  float vig = 1.0 - smoothstep(0.6, 1.5, length(vUv - 0.5) * 1.5);
  col *= 0.8 + vig * 0.2;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uDensity;
uniform float uStarBrightness;
uniform float uNebulaScale;
uniform float uRaySteps;

// 3D value noise hash
float hash3d(float x, float y, float z) {
  float d = x * 127.1 + y * 311.7 + z * 74.7;
  return fract(sin(d) * 43758.5453);
}

// 3D value noise with smooth interpolation
float noise3d(float x, float y, float z) {
  float ix = floor(x);
  float iy = floor(y);
  float iz = floor(z);
  float fx = fract(x);
  float fy = fract(y);
  float fz = fract(z);
  float ux = fx * fx * (3.0 - fx * 2.0);
  float uy = fy * fy * (3.0 - fy * 2.0);
  float uz = fz * fz * (3.0 - fz * 2.0);
  float n000 = hash3d(ix, iy, iz);
  float n100 = hash3d(ix + 1.0, iy, iz);
  float n010 = hash3d(ix, iy + 1.0, iz);
  float n110 = hash3d(ix + 1.0, iy + 1.0, iz);
  float n001 = hash3d(ix, iy, iz + 1.0);
  float n101 = hash3d(ix + 1.0, iy, iz + 1.0);
  float n011 = hash3d(ix, iy + 1.0, iz + 1.0);
  float n111 = hash3d(ix + 1.0, iy + 1.0, iz + 1.0);
  float nx00 = mix(n000, n100, ux);
  float nx10 = mix(n010, n110, ux);
  float nx01 = mix(n001, n101, ux);
  float nx11 = mix(n011, n111, ux);
  float nxy0 = mix(nx00, nx10, uy);
  float nxy1 = mix(nx01, nx11, uy);
  return mix(nxy0, nxy1, uz);
}

// 4-octave FBM using 3D value noise
float fbm3d(float x, float y, float z) {
  float acc = 0.0;
  acc += noise3d(x, y, z) * 0.5;
  acc += noise3d(x * 2.0, y * 2.0, z * 2.0) * 0.25;
  acc += noise3d(x * 4.0, y * 4.0, z * 4.0) * 0.125;
  acc += noise3d(x * 8.0, y * 8.0, z * 8.0) * 0.0625;
  return acc;
}

// 2D hash for star field
float hash2d(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

// Logarithmic spiral function — returns distance to nearest spiral arm
float spiralArm(float r, float angle, float armCount, float twist, float rotation) {
  float minDist = 1.0;
  for (int i = 0; i < 4; i++) {
    float armOffset = float(i) * 6.2832 / armCount;
    // Logarithmic spiral: r = a * exp(b * theta)
    float spiralAngle = log(r + 0.001) / twist + armOffset + rotation;
    float diff = mod(angle - spiralAngle + 3.14159, 6.2832) - 3.14159;
    float armDist = abs(diff) * r;
    minDist = min(minDist, armDist);
  }
  return minDist;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio influences
  float bassInfluence = bass() * uSensitivity;
  float midsInfluence = mids() * uSensitivity;
  float trebleInfluence = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlare = uOnset * uSensitivity;

  // --- Galaxy coordinate system ---
  float galR = sqrt(p.x * p.x + p.y * p.y);
  float galAngle = atan(p.y, p.x);

  // Subtle galaxy rotation
  float rotation = time * 0.03;
  float rotatedAngle = galAngle - rotation;

  // --- Spiral arm structure ---
  float armCount = 2.0 + uChaos;  // 2-3 spiral arms
  float twist = 0.35 + bassInfluence * 0.05;  // tighter twist with bass
  float spiralDist = spiralArm(galR, rotatedAngle, armCount, twist, 0.0);

  // Arm brightness: bright in arms, dim between
  float armWidth = 0.15 + bassInfluence * 0.05;
  float armBright = exp(-spiralDist * spiralDist / (armWidth * armWidth * 2.0));

  // Secondary (fainter) arm set, offset
  float spiralDist2 = spiralArm(galR, rotatedAngle, armCount, twist * 1.3, 3.14159 / armCount);
  float armBright2 = exp(-spiralDist2 * spiralDist2 / (armWidth * armWidth * 3.0)) * 0.4;

  float totalArm = armBright + armBright2;

  // --- Volumetric nebula within spiral arms ---
  float densityMul = uDensity + bassInfluence * 1.2;
  float rayOrigZ = -2.0 + time * 0.15;

  // Fewer but more targeted raymarch steps focused on spiral structure
  float accR = 0.0;
  float accG = 0.0;
  float accB = 0.0;
  float accA = 0.0;

  float stepSize = 0.25;
  for (int i = 0; i < 6; i++) {
    float tStep = stepSize * (float(i) * 1.5 + 0.5);
    float sx = p.x * tStep * uNebulaScale;
    float sy = p.y * tStep * uNebulaScale;
    float sz = (rayOrigZ + tStep) * uNebulaScale;
    float d = (fbm3d(sx + time * 0.08, sy + uChaos * 0.2 * float(i), sz) * densityMul - 0.25) * 2.0;
    float dens = clamp(d, 0.0, 1.0);

    // Modulate density by spiral arm proximity
    dens *= (0.3 + totalArm * 0.7);

    float tempShift = midsInfluence * 0.25;
    float colorT = clamp(dens + tempShift, 0.0, 1.0);

    // Deep space palette: blues, purples, with warm cores
    float nr = smoothstep(0.6, 1.0, colorT + uPalette * 0.1) * 0.6;  // warm only at high density
    float ng = smoothstep(0.3, 0.7, colorT) * 0.25;
    float nb = smoothstep(0.0, 0.4, colorT) * 0.9 + smoothstep(0.5, 0.8, colorT) * 0.3;  // strong blues

    // Add purple tones
    nr += smoothstep(0.2, 0.5, colorT) * 0.3;

    float alpha = dens * stepSize * 1.5 * (1.0 - accA);
    accR += nr * alpha * uIntensity;
    accG += ng * alpha * uIntensity;
    accB += nb * alpha * uIntensity;
    accA += alpha;
  }

  // --- Dust lanes (dark absorption along spiral arms) ---
  float dustNoise = fbm3d(p.x * 6.0 + time * 0.02, p.y * 6.0, rayOrigZ * 0.5);
  float dustLane = smoothstep(0.1, 0.0, spiralDist) * dustNoise * 0.6;
  // Dust absorbs light — darken where dust lanes are strong
  float dustAbsorption = 1.0 - dustLane * 0.7;
  accR *= dustAbsorption;
  accG *= dustAbsorption;
  accB *= dustAbsorption;

  // --- Star field (random bright points) ---
  // Dense star field across the background
  float starFieldR = 0.0;
  float starFieldG = 0.0;
  float starFieldB = 0.0;

  // Layer 1: bright stars (sparse)
  float starScale1 = 80.0;
  float sgx1 = floor(p.x * starScale1);
  float sgy1 = floor(p.y * starScale1);
  float sh1 = hash2d(sgx1, sgy1);
  float starThresh1 = 0.97 - trebleInfluence * 0.03;
  if (sh1 > starThresh1) {
    // Star position within cell
    float scx = (fract(p.x * starScale1) - hash2d(sgx1 + 5.0, sgy1 + 3.0));
    float scy = (fract(p.y * starScale1) - hash2d(sgx1 + 7.0, sgy1 + 11.0));
    float sd = scx * scx + scy * scy;
    float sGlow = exp(-sd * 800.0) * uStarBrightness;
    // Star color: warm white to blue based on hash
    float starTemp = hash2d(sgx1 + 13.0, sgy1 + 17.0);
    starFieldR += sGlow * (0.7 + starTemp * 0.3);
    starFieldG += sGlow * (0.8 + starTemp * 0.2);
    starFieldB += sGlow * 1.0;
  }

  // Layer 2: dim stars (dense background)
  float starScale2 = 200.0;
  float sgx2 = floor(p.x * starScale2);
  float sgy2 = floor(p.y * starScale2);
  float sh2 = hash2d(sgx2 + 100.0, sgy2 + 200.0);
  float starThresh2 = 0.985 - trebleInfluence * 0.02;
  if (sh2 > starThresh2) {
    float scx2 = (fract(p.x * starScale2) - hash2d(sgx2 + 15.0, sgy2 + 23.0));
    float scy2 = (fract(p.y * starScale2) - hash2d(sgx2 + 27.0, sgy2 + 31.0));
    float sd2 = scx2 * scx2 + scy2 * scy2;
    float sGlow2 = exp(-sd2 * 2000.0) * uStarBrightness * 0.4;
    float twinkle = sin(time * 3.0 + sh2 * 100.0) * 0.3 + 0.7;
    starFieldR += sGlow2 * 0.9 * twinkle;
    starFieldG += sGlow2 * 0.9 * twinkle;
    starFieldB += sGlow2 * 1.0 * twinkle;
  }

  // Layer 3: extra-bright core stars in spiral arms
  float starScale3 = 120.0;
  float sgx3 = floor(p.x * starScale3);
  float sgy3 = floor(p.y * starScale3);
  float sh3 = hash2d(sgx3 + 300.0, sgy3 + 400.0);
  float armStarThresh = 0.99 - totalArm * 0.04 - trebleInfluence * 0.02;
  if (sh3 > armStarThresh) {
    float scx3 = (fract(p.x * starScale3) - hash2d(sgx3 + 35.0, sgy3 + 43.0));
    float scy3 = (fract(p.y * starScale3) - hash2d(sgx3 + 47.0, sgy3 + 51.0));
    float sd3 = scx3 * scx3 + scy3 * scy3;
    float sGlow3 = exp(-sd3 * 600.0) * uStarBrightness * 1.5;
    // Hot blue-white stars in arms
    starFieldR += sGlow3 * 0.8;
    starFieldG += sGlow3 * 0.9;
    starFieldB += sGlow3 * 1.2;
  }

  // --- Galaxy core glow ---
  float coreDist = galR;
  float coreGlow = exp(-coreDist * coreDist * 8.0) * 0.4;
  // Warm bright core: white-yellow
  float coreR = coreGlow * 1.0;
  float coreG = coreGlow * 0.85;
  float coreB = coreGlow * 0.6;

  // --- Deep space background color ---
  // Very dark blue-purple background
  float bgR = 0.005 + 0.01 * fbm3d(p.x * 2.0, p.y * 2.0, time * 0.01);
  float bgG = 0.003;
  float bgB = 0.015 + 0.02 * fbm3d(p.x * 1.5 + 10.0, p.y * 1.5 + 10.0, time * 0.01);

  // --- Combine all layers ---
  float finalR = bgR + accR + starFieldR + coreR;
  float finalG = bgG + accG + starFieldG + coreG;
  float finalB = bgB + accB + starFieldB + coreB;

  // Beat pulse brightness
  float pulse = beatPulse * 0.3;
  finalR += pulse * 0.5;
  finalG += pulse * 0.4;
  finalB += pulse * 0.6;

  // Onset flare — bright white flash from core
  float flare = onsetFlare * 0.4 * exp(-coreDist * 4.0);
  finalR += flare;
  finalG += flare * 0.9;
  finalB += flare * 0.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridSpacing;
uniform float uPerspectiveAngle;
uniform float uGlowFalloff;
uniform float uScanSpeed;

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 3.0);

  // Audio-reactive modulators
  float bassPulse = bass() * uSensitivity;
  float trebleScan = treble() * uSensitivity;
  float beatShift = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Horizon position
  float horizon = 0.5 + uPerspectiveAngle * 0.15;
  float screenX = p.x - 0.5;
  float screenY = p.y;

  // === SUNSET SKY (above horizon) ===
  float aboveHorizon = smoothstep(horizon, horizon + 0.01, screenY);
  float skyHeight = screenY - horizon;

  // Gradient: dark top -> orange/pink at horizon
  float skyTopR = 0.02 + uPalette * 0.01;
  float skyTopG = 0.0;
  float skyTopB = 0.08;
  float skyMidR = 0.4 + beatShift * 0.2;
  float skyMidG = 0.05;
  float skyMidB = 0.35;
  float skyHorizR = 1.0;
  float skyHorizG = 0.35;
  float skyHorizB = 0.15;

  // Two-stage gradient
  float midBlend = smoothstep(0.0, 0.3, skyHeight);
  float topBlend = smoothstep(0.2, 0.5, skyHeight);

  float skyR = mix(skyHorizR, skyMidR, midBlend);
  float skyG = mix(skyHorizG, skyMidG, midBlend);
  float skyB = mix(skyHorizB, skyMidB, midBlend);
  float skyFinalR = mix(skyR, skyTopR, topBlend);
  float skyFinalG = mix(skyG, skyTopG, topBlend);
  float skyFinalB = mix(skyB, skyTopB, topBlend);

  // Sun orb near horizon
  float sunDist = sqrt(screenX * screenX + (skyHeight - 0.02) * (skyHeight - 0.02));
  float sunGlow = smoothstep(0.12, 0.0, sunDist) * 0.8;
  float sunR = sunGlow * 1.0;
  float sunG = sunGlow * 0.5;
  float sunB = sunGlow * 0.15;

  // === PERSPECTIVE GRID (below horizon) ===

  // Depth calculation
  float rawDepth = horizon - screenY;
  float safeDepth = clamp(rawDepth, 0.001, 1.0);
  float zScale = 0.6 * (uZoom * 2.0 + 0.5);
  // Perspective depth
  float perspPow = 1.0 + uPerspectiveAngle;
  float invDepth = pow(1.0 - safeDepth, perspPow) * 15.0 + 0.5;
  float zVal = zScale * invDepth;

  // Grid X (perspective spread)
  float gridX = screenX * zVal;
  // Grid Y (scrolling forward)
  float scroll = time * uGridSpacing + kickPulse * 3.0;
  float gridY = zVal + scroll;

  // Grid spacing
  float spacing = uGridSpacing * 1.5;

  // --- Horizontal grid lines ---
  float hLine = fract(gridY * spacing);
  float hDist = abs(hLine - 0.5) * 2.0;
  float hGlowRaw = 1.0 - hDist;
  float hGlow = pow(clamp(hGlowRaw, 0.0, 1.0), uGlowFalloff)
    * (1.0 + bassPulse * 1.0);

  // --- Vertical grid lines ---
  float vLine = fract(gridX * spacing);
  float vDist = abs(vLine - 0.5) * 2.0;
  float vGlowRaw = 1.0 - vDist;
  float vGlow = pow(clamp(vGlowRaw, 0.0, 1.0), uGlowFalloff)
    * (1.0 + bassPulse * 1.0);

  // Combined grid glow
  float gridGlow = clamp(hGlow + vGlow, 0.0, 1.0);

  // Distance fade (closer = brighter)
  float distFade = smoothstep(0.0, 0.25, safeDepth);

  // --- Kick shockwave ripple ---
  float shockPhase = zVal * 0.3 - time * 4.0;
  float shockWave = sin(shockPhase) * 0.5 + 0.5;
  float shockEffect = shockWave * kickPulse * 0.7 * distFade;

  // --- Scan lines ---
  float scanPhase = fract(gridY * 0.5 - time * (uScanSpeed * 2.0));
  float scanLine = smoothstep(0.02, 0.0, scanPhase)
    * (0.6 + trebleScan * 0.4);

  // --- Grid color: cyan/magenta shifting ---
  float colorPhase = fract(time * 0.12 + beatShift * 0.5 + uPalette * 0.15);
  vec3 cyan = vec3(0.0, 0.95, 1.0);
  vec3 magenta = vec3(1.0, 0.1, 0.7);
  vec3 lime = vec3(0.2, 1.0, 0.3);
  vec3 gridColor = colorPhase < 0.33 ? mix(cyan, magenta, colorPhase * 3.0) : colorPhase < 0.66 ? mix(magenta, lime, (colorPhase - 0.33) * 3.0) : mix(lime, cyan, (colorPhase - 0.66) * 3.0);

  // Grid final brightness
  float gridBright = gridGlow + shockEffect + scanLine;
  vec3 gridFinal = vec3(
    gridColor.x * gridBright * uIntensity * distFade * 2.0,
    gridColor.y * gridBright * uIntensity * distFade * 2.0,
    gridColor.z * gridBright * uIntensity * distFade * 2.0
  );

  // Dark ground base
  vec3 groundBase = vec3(0.01, 0.0, 0.03);

  // --- Horizon glow line ---
  float horizDist = abs(screenY - horizon);
  float horizGlow = exp(horizDist * -80.0) * 0.5 * uIntensity;

  // === COMPOSITE ===
  float belowR = groundBase.x + gridFinal.x;
  float belowG = groundBase.y + gridFinal.y;
  float belowB = groundBase.z + gridFinal.z;

  // Sky with sun
  float skyWithSunR = skyFinalR + sunR;
  float skyWithSunG = skyFinalG + sunG;
  float skyWithSunB = skyFinalB + sunB;

  // Mix sky and ground
  float finalR = mix(belowR, skyWithSunR, aboveHorizon)
    + horizGlow * gridColor.x;
  float finalG = mix(belowG, skyWithSunG, aboveHorizon)
    + horizGlow * gridColor.y;
  float finalB = mix(belowB, skyWithSunB, aboveHorizon)
    + horizGlow * gridColor.z;

  // Energy brightness and beat pulse
  float energyBright = energyVal * 0.2 + 0.8;
  float beatBright = beatShift * 0.1;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR * energyBright + beatBright, 0.0, 1.0),
    clamp(finalG * energyBright + beatBright, 0.0, 1.0),
    clamp(finalB * energyBright + beatBright, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTubeWidth;
uniform float uGlowRadius;
uniform float uPulseDepth;
uniform float uCrossAngle;

// HSV to RGB helper
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

// Compute neon tube intensity (core + glow) for a given distance-to-line
vec2 neonTube(float dist, float coreW, float glowW) {
  float core = smoothstep(coreW, 0.0, dist);
  float glow = smoothstep(glowW, 0.0, dist) * 0.4;
  return vec2(core, glow);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.25);

  // Audio-reactive modulators
  float bassPulse = bass() * uSensitivity * 1.2;
  float midsHue = mids() * uSensitivity * 0.5;
  float trebleSpark = treble() * uSensitivity * 0.6;
  float onsetFlash = uOnset * uSensitivity * 2.0;
  float beatPhase = uBeat;
  float kickPunch = uKick * uSensitivity;

  // Generate multiple pulse phases at different rates
  float pulse1 = sin(beatPhase * 6.28318) * 0.5 + 0.5;
  pulse1 = pulse1 * uPulseDepth + (1.0 - uPulseDepth);
  float pulse2 = cos(beatPhase * 6.28318 + 2.094) * 0.5 + 0.5;
  pulse2 = pulse2 * uPulseDepth + (1.0 - uPulseDepth);
  float pulse3 = sin(beatPhase * 6.28318 + 4.189) * 0.5 + 0.5;
  pulse3 = pulse3 * uPulseDepth + (1.0 - uPulseDepth);
  float pulse4 = cos(beatPhase * 3.14159 + 1.0) * 0.5 + 0.5;
  pulse4 = pulse4 * uPulseDepth + (1.0 - uPulseDepth);
  float pulse5 = sin(beatPhase * 6.28318 * 2.0) * 0.5 + 0.5;
  pulse5 = pulse5 * uPulseDepth * 0.7 + (1.0 - uPulseDepth * 0.7);

  // Tube core width and glow width
  float coreW = uTubeWidth * 0.012;
  float coreWThin = uTubeWidth * 0.007;
  float glowW = uGlowRadius * 0.12;
  float glowWSmall = uGlowRadius * 0.08;

  // Color palette offset
  float hueOff = uPalette * 0.12 + time * 0.04 + midsHue;

  // Accumulator for all neon tubes
  vec3 totalColor = vec3(0.0);
  float totalTube = 0.0;

  // === GROUP 1: Horizontal tubes (3 at different heights) ===
  // H1: Main horizontal, drifts up/down
  float h1y = p.y - sin(time * 0.2) * 0.15;
  vec2 h1 = neonTube(abs(h1y), coreW, glowW);
  float tube_h1 = (h1.x + h1.y) * pulse1 + bassPulse * h1.x * 0.3;
  totalColor += hsv2rgb(vec3(fract(0.95 + hueOff), 0.9, 1.0)) * tube_h1; // Hot pink

  // H2: Upper horizontal, pulses at different rate
  float h2y = p.y - 0.35 - sin(time * 0.15 + 1.0) * 0.08;
  vec2 h2 = neonTube(abs(h2y), coreWThin, glowWSmall);
  float tube_h2 = (h2.x + h2.y) * pulse3 * 0.8;
  totalColor += hsv2rgb(vec3(fract(0.55 + hueOff), 0.85, 1.0)) * tube_h2; // Teal

  // H3: Lower horizontal
  float h3y = p.y + 0.4 - cos(time * 0.18) * 0.06;
  vec2 h3 = neonTube(abs(h3y), coreWThin, glowWSmall);
  float tube_h3 = (h3.x + h3.y) * pulse4 * 0.7;
  totalColor += hsv2rgb(vec3(fract(0.15 + hueOff), 0.9, 1.0)) * tube_h3; // Orange

  // === GROUP 2: Vertical tubes (3) ===
  // V1: Center vertical
  float v1x = p.x - cos(time * 0.12) * 0.2;
  vec2 v1 = neonTube(abs(v1x), coreW, glowW);
  float tube_v1 = (v1.x + v1.y) * pulse2 * 0.85;
  totalColor += hsv2rgb(vec3(fract(0.75 + hueOff), 0.85, 1.0)) * tube_v1; // Purple

  // V2: Left vertical
  float v2x = p.x + 0.45 - sin(time * 0.14 + 2.0) * 0.05;
  vec2 v2 = neonTube(abs(v2x), coreWThin, glowWSmall);
  float tube_v2 = (v2.x + v2.y) * pulse5 * 0.65;
  totalColor += hsv2rgb(vec3(fract(0.33 + hueOff), 0.9, 1.0)) * tube_v2; // Green

  // V3: Right vertical
  float v3x = p.x - 0.5 + cos(time * 0.16 + 3.0) * 0.04;
  vec2 v3 = neonTube(abs(v3x), coreWThin, glowWSmall);
  float tube_v3 = (v3.x + v3.y) * pulse1 * 0.6;
  totalColor += hsv2rgb(vec3(fract(0.08 + hueOff), 0.95, 1.0)) * tube_v3; // Red

  // === GROUP 3: Diagonal tubes (4) crossing at different angles ===
  float angle_a = uCrossAngle * 1.5;
  float d1dist = abs(p.x * sin(angle_a) + p.y * cos(angle_a) - cos(time * 0.15) * 0.1);
  vec2 d1 = neonTube(d1dist, coreW, glowW);
  float tube_d1 = (d1.x + d1.y) * pulse2 + bassPulse * d1.x * 0.3;
  totalColor += hsv2rgb(vec3(fract(0.5 + hueOff), 0.9, 1.0)) * tube_d1; // Cyan

  float angle_b = uCrossAngle * -1.5 + 0.2;
  float d2dist = abs(p.x * sin(angle_b) + p.y * cos(angle_b) + sin(time * 0.18) * 0.12);
  vec2 d2 = neonTube(d2dist, coreW, glowW);
  float tube_d2 = (d2.x + d2.y) * pulse3 + bassPulse * d2.x * 0.3;
  totalColor += hsv2rgb(vec3(fract(0.33 + hueOff), 0.9, 1.0)) * tube_d2; // Lime green

  // Shallow diagonal (nearly horizontal)
  float angle_c = 0.2 + sin(time * 0.08) * 0.1;
  float d3dist = abs(p.x * sin(angle_c) + p.y * cos(angle_c) - 0.2 + sin(time * 0.22) * 0.08);
  vec2 d3 = neonTube(d3dist, coreWThin, glowWSmall);
  float tube_d3 = (d3.x + d3.y) * pulse4 * 0.75;
  totalColor += hsv2rgb(vec3(fract(0.85 + hueOff), 0.85, 1.0)) * tube_d3; // Magenta

  // Steep diagonal (nearly vertical)
  float angle_d = 1.3 + cos(time * 0.1) * 0.08;
  float d4dist = abs(p.x * sin(angle_d) + p.y * cos(angle_d) + 0.15 - cos(time * 0.2) * 0.06);
  vec2 d4 = neonTube(d4dist, coreWThin, glowWSmall);
  float tube_d4 = (d4.x + d4.y) * pulse5 * 0.7;
  totalColor += hsv2rgb(vec3(fract(0.42 + hueOff), 0.8, 1.0)) * tube_d4; // Aqua

  // === GROUP 4: Curved neon arcs (3) ===
  // Arc 1: circular arc, top area
  float arc1r = length(p - vec2(0.0, -0.8));
  float arc1dist = abs(arc1r - 0.6 - sin(time * 0.25) * 0.05);
  vec2 a1 = neonTube(arc1dist, coreW, glowW);
  // Only show upper half of the arc
  float arc1mask = smoothstep(-0.2, 0.1, p.y);
  float tube_a1 = (a1.x + a1.y) * pulse1 * 0.8 * arc1mask;
  totalColor += hsv2rgb(vec3(fract(0.6 + hueOff), 0.9, 1.0)) * tube_a1; // Blue

  // Arc 2: elliptical arc, bottom area
  float arc2r = length(p * vec2(1.0, 0.6) - vec2(0.0, 0.7));
  float arc2dist = abs(arc2r - 0.5 + cos(time * 0.2) * 0.04);
  vec2 a2 = neonTube(arc2dist, coreWThin, glowWSmall);
  float arc2mask = smoothstep(0.1, -0.1, p.y);
  float tube_a2 = (a2.x + a2.y) * pulse3 * 0.7 * arc2mask;
  totalColor += hsv2rgb(vec3(fract(0.12 + hueOff), 0.95, 1.0)) * tube_a2; // Yellow-orange

  // Arc 3: tight curve, mid-right
  float arc3r = length(p - vec2(0.6, 0.0));
  float arc3dist = abs(arc3r - 0.3 - sin(time * 0.3 + 1.5) * 0.03);
  vec2 a3 = neonTube(arc3dist, coreWThin, glowWSmall);
  float tube_a3 = (a3.x + a3.y) * pulse5 * 0.65;
  totalColor += hsv2rgb(vec3(fract(0.7 + hueOff), 0.85, 1.0)) * tube_a3; // Indigo

  // === GROUP 5: Grid accents — short segments forming grid feel (6 lines) ===
  // These are thin, subtle lines that create the dense grid/mesh feel
  for (float gi = 0.0; gi < 6.0; gi += 1.0) {
    float gridOffset = (gi - 2.5) * 0.22;
    float gPhase = sin(beatPhase * 6.28318 + gi * 1.047) * 0.5 + 0.5;
    gPhase = gPhase * uPulseDepth * 0.6 + (1.0 - uPulseDepth * 0.6);

    // Alternating horizontal and vertical
    float gDist;
    if (mod(gi, 2.0) < 1.0) {
      gDist = abs(p.y - gridOffset + sin(time * 0.1 + gi) * 0.03);
    } else {
      gDist = abs(p.x - gridOffset + cos(time * 0.1 + gi) * 0.03);
    }
    vec2 g = neonTube(gDist, coreWThin * 0.7, glowWSmall * 0.6);
    float tubeG = (g.x + g.y) * gPhase * 0.4;

    float gridHue = fract(gi * 0.167 + hueOff + 0.05);
    totalColor += hsv2rgb(vec3(gridHue, 0.75, 0.9)) * tubeG;
    totalTube += tubeG;
  }

  // === GROUP 6: Random fading shapes at random positions ===
  for (int si = 0; si < 12; si++) {
    float fsi = float(si);
    // Each shape has a different cycle length for variety
    float cycleLen = 2.0 + fsi * 0.3;
    float cycleSeed = floor(time / cycleLen + fsi * 0.37);
    float cyclePhase = fract(time / cycleLen + fsi * 0.37);

    // Fade in (0-0.2), hold (0.2-0.7), fade out (0.7-1.0) — pulsing appearance
    float fadeIn = smoothstep(0.0, 0.2, cyclePhase);
    float fadeOut = 1.0 - smoothstep(0.7, 1.0, cyclePhase);
    float alpha = fadeIn * fadeOut;

    // Random position from hash — spread across full screen
    vec2 seedVec1 = vec2(cycleSeed * 1.7, fsi * 3.7);
    vec2 seedVec2 = vec2(fsi * 5.1, cycleSeed * 2.3);
    float rx = (fract(sin(dot(seedVec1, vec2(127.1, 311.7))) * 43758.5453) - 0.5) * 2.2;
    float ry = (fract(sin(dot(seedVec2, vec2(127.1, 311.7))) * 43758.5453) - 0.5) * 1.6;

    // Random shape type: 0=circle, 1=diamond, 2=ring
    float shapeType = floor(fract(sin(dot(vec2(cycleSeed * 7.1, fsi * 11.3), vec2(127.1, 311.7))) * 43758.5453) * 3.0);
    float shapeSize = 0.03 + fract(sin(dot(vec2(fsi * 13.7, cycleSeed * 17.1), vec2(127.1, 311.7))) * 43758.5453) * 0.08;

    vec2 sp = p - vec2(rx, ry);
    float sDist;
    if (shapeType < 1.0) {
      sDist = length(sp); // circle
    } else if (shapeType < 2.0) {
      sDist = abs(sp.x) + abs(sp.y); // diamond
    } else {
      sDist = abs(length(sp) - shapeSize * 0.7); // ring
    }

    vec2 sn = neonTube(sDist, shapeSize * 0.3, shapeSize * 1.5);
    float shapeTube = (sn.x + sn.y) * alpha;

    float shapeHue = fract(fsi * 0.083 + hueOff + cycleSeed * 0.13);
    totalColor += hsv2rgb(vec3(shapeHue, 0.9, 1.0)) * shapeTube * 0.7;
    totalTube += shapeTube * 0.5;
  }

  // Sum up all main tubes for flash/beat calculations
  totalTube += tube_h1 + tube_h2 + tube_h3
    + tube_v1 + tube_v2 + tube_v3
    + tube_d1 + tube_d2 + tube_d3 + tube_d4
    + tube_a1 + tube_a2 + tube_a3;

  // === COMBINE (additive) ===
  float brightness = uIntensity * 1.5;
  vec3 result = totalColor * brightness;

  // Onset flash: white on all tubes
  float flashAmount = onsetFlash * min(totalTube, 3.0) * 0.12;

  // Kick: brightness surge
  float kickFlash = kickPunch * 0.08 * min(totalTube, 2.0);

  // Chaos: random flicker per frame
  float flicker = sin(time * 15.0 + uChaos * 20.0) * uChaos * 0.04;
  flicker += sin(time * 23.0 + uChaos * 13.0) * uChaos * 0.02;

  // Treble sparkle at intersection points (where multiple tubes overlap)
  float intersections = max(0.0, totalTube - 1.5) * trebleSpark * 0.15;

  // Beat pulse
  float beatBright = uBeat * uSensitivity * 0.05;

  // === PSYCHEDELIC ENHANCEMENT ===
  result = psychedelicColor(result);
  gl_FragColor = vec4(
    clamp(result.r + flashAmount + flicker + beatBright + kickFlash + intersections, 0.0, 1.0),
    clamp(result.g + flashAmount + flicker + beatBright + kickFlash + intersections, 0.0, 1.0),
    clamp(result.b + flashAmount + flicker + beatBright + kickFlash + intersections, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uDropDensity;
uniform float uTrailLength;
uniform float uGlowRadius;
uniform float uColorSpread;

// Pseudo-random
float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

float hash2(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Neon color from index
vec3 neonColor(float t, float palette) {
  float h = fract(t * 0.15 + palette * 0.15);
  // Saturated neon HSV->RGB
  vec3 c = vec3(h, 0.9, 1.0);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Single rain drop layer
float rainDrop(vec2 uv, float columnId, float time, float speed, float trail) {
  float dropSpeed = (0.5 + hash(columnId * 7.3) * 1.5) * speed;
  float dropPhase = hash(columnId * 13.7) * 6.2832;
  float yPos = fract(-time * dropSpeed + dropPhase);

  // Drop head position
  float dy = uv.y - yPos;

  // Trail: bright at head, fading behind (above)
  float trailMask = smoothstep(trail, 0.0, dy) * step(0.0, dy);

  // Head glow
  float headGlow = exp(-abs(dy) * 40.0);

  return trailMask * 0.6 + headGlow;
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 1.2;

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  float numColumns = 20.0 + uDropDensity * 60.0;
  float trailLen = uTrailLength * 0.4 + 0.1 + bassVal * 0.15;
  float glowRad = uGlowRadius * 0.02 + 0.005;

  vec3 totalColor = vec3(0.0);

  // Three layers of rain for depth
  for (int layer = 0; layer < 3; layer++) {
    float layerF = float(layer);
    float layerDepth = 1.0 - layerF * 0.25;
    float layerSpeed = 1.0 + layerF * 0.5;
    float layerColumns = numColumns * (1.0 + layerF * 0.3);
    float layerBright = layerDepth * layerDepth;

    // Quantize x into columns
    float scaledX = uv.x * layerColumns;
    float colId = floor(scaledX);
    float colFrac = fract(scaledX) - 0.5;

    // Check this column and neighbors for glow bleed
    for (int dx = -1; dx <= 1; dx++) {
      float checkCol = colId + float(dx);
      float colHash = hash(checkCol + layerF * 100.0);

      // Not all columns active
      if (colHash > 0.6 + uChaos * 0.3) continue;

      float dropX = (float(dx) - colFrac) / layerColumns;
      float xDist = abs(dropX);
      float xGlow = exp(-xDist * xDist / (glowRad * glowRad + bassVal * 0.001));

      float drop = rainDrop(uv, checkCol + layerF * 1000.0, time * layerSpeed, 1.0, trailLen);

      // Color per column
      float colorT = checkCol * uColorSpread + layerF * 0.33 + midsVal * 0.5;
      vec3 dropCol = neonColor(colorT, uPalette);

      // Treble sparkle at drop heads
      float sparkle = trebleVal * hash2(vec2(checkCol, floor(time * 10.0))) * 2.0;

      totalColor += dropCol * drop * xGlow * layerBright * (1.0 + sparkle);
    }
  }

  // Kick flash — burst of extra brightness
  totalColor *= 1.0 + kickVal * 2.5;

  // Beat pulse — subtle global glow
  totalColor += beatVal * 0.05 * neonColor(time * 0.5, uPalette);

  // Bottom reflection pool
  float poolY = smoothstep(0.15, 0.0, uv.y);
  vec3 poolReflect = totalColor * poolY * 0.3;
  // Flip for reflection
  vec2 reflUV = vec2(uv.x, 0.15 - uv.y);
  float reflNoise = hash2(reflUV * 50.0 + time) * 0.3;
  totalColor += poolReflect * (1.0 - reflNoise);

  // Intensity
  totalColor *= uIntensity * 1.6;

  // Dark background with slight blue tint
  vec3 bg = vec3(0.01, 0.01, 0.03);
  vec3 finalColor = bg + totalColor;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uIterations;
uniform float uFoldAngle;
uniform float uScale;
uniform float uOffset;

vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;

  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

void main() {
  // Center UV and apply zoom
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 0.5);

  // Audio-reactive modulation of IFS parameters
  float bassInfluence = bass() * uSensitivity;
  float trebleInfluence = treble() * uSensitivity;

  // Bass modulates fold angle, treble affects scale
  float foldAngle = uFoldAngle + bassInfluence * 0.5 + time * 0.1;
  float ifsScale = uScale + trebleInfluence * 0.3;

  // Beat shifts the fold pattern
  float beatShift = uBeat * uSensitivity * 0.2;

  // Precompute rotation components from fold angle + beat shift
  float cosA = cos(foldAngle + beatShift);
  float sinA = sin(foldAngle + beatShift);

  // IFS iteration: fold + rotate + scale + translate
  float px = p.x;
  float py = p.y;
  float colorAccum = 0.0;
  float minDist = 1000000.0;

  // Iteration 1
  float nx1 = abs(px * cosA - py * sinA);
  float ny1 = abs(nx1 * sinA + py * cosA);
  nx1 = clamp(nx1 * ifsScale - uOffset, -10.0, 10.0);
  ny1 = clamp(ny1 * ifsScale - uOffset, -10.0, 10.0);
  float d1 = nx1 * nx1 + ny1 * ny1;
  float c1 = 1.0 / (d1 + 0.1);
  px = nx1; py = ny1;
  colorAccum += c1;
  minDist = smoothstep(0.0, 2.0, d1) + minDist * 0.9;

  // Iteration 2
  float nx2 = abs(px * cosA - py * sinA);
  float ny2 = abs(nx2 * sinA + py * cosA);
  nx2 = clamp(nx2 * ifsScale - uOffset, -10.0, 10.0);
  ny2 = clamp(ny2 * ifsScale - uOffset, -10.0, 10.0);
  float d2 = nx2 * nx2 + ny2 * ny2;
  float c2 = 2.0 / (d2 + 0.1);
  px = nx2; py = ny2;
  colorAccum += c2;

  // Iteration 3
  float nx3 = abs(px * cosA - py * sinA);
  float ny3 = abs(nx3 * sinA + py * cosA);
  nx3 = clamp(nx3 * ifsScale - uOffset, -10.0, 10.0);
  ny3 = clamp(ny3 * ifsScale - uOffset, -10.0, 10.0);
  float d3 = nx3 * nx3 + ny3 * ny3;
  float c3 = 3.0 / (d3 + 0.1);
  px = nx3; py = ny3;
  colorAccum += c3;

  // Iteration 4
  float nx4 = abs(px * cosA - py * sinA);
  float ny4 = abs(nx4 * sinA + py * cosA);
  nx4 = clamp(nx4 * ifsScale - uOffset, -10.0, 10.0);
  ny4 = clamp(ny4 * ifsScale - uOffset, -10.0, 10.0);
  float d4 = nx4 * nx4 + ny4 * ny4;
  float c4 = 4.0 / (d4 + 0.1);
  px = nx4; py = ny4;
  colorAccum += c4;

  // Iteration 5
  float nx5 = abs(px * cosA - py * sinA);
  float ny5 = abs(nx5 * sinA + py * cosA);
  nx5 = clamp(nx5 * ifsScale - uOffset, -10.0, 10.0);
  ny5 = clamp(ny5 * ifsScale - uOffset, -10.0, 10.0);
  float d5 = nx5 * nx5 + ny5 * ny5;
  float c5 = 5.0 / (d5 + 0.1);
  colorAccum += c5;

  // Normalize accumulated color (5 iterations, damped)
  float normalizedColor = clamp(colorAccum * (1.0 / 20.0), 0.0, 2.0);

  // Apply chaos to add variation
  float chaosModulation = sin(normalizedColor * (uChaos * 10.0) + time) * 0.3 + 0.7;

  // Color based on iteration depth + distance estimate
  float hue = fract(
    normalizedColor * 0.15
      + uPalette * 0.1
      + time * 0.03
      + uEnergy * uSensitivity * 0.05
  );
  float sat = 0.65 + chaosModulation * 0.3;
  float val = normalizedColor * uIntensity
    * chaosModulation
    + uEnergy * uSensitivity * 0.2;

  vec3 col = hsvToRgb(hue, clamp(sat, 0.0, 1.0), clamp(val, 0.0, 1.0));

  // Beat pulse: brighten on beat
  float beatPulse = uBeat * uSensitivity * 0.15;
  float onsetFlash = uOnset * uSensitivity * 0.1;
  vec3 finalCol = col + vec3(
    beatPulse + onsetFlash,
    beatPulse + onsetFlash,
    beatPulse + onsetFlash
  );

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

