vec2 nodePos(float idx, float time) {
  float angle = idx * 0.9 + time * 0.05;
  float radius = 0.9 + sin(idx * 2.7 + time * 0.03) * 0.4;
  return vec2(cos(angle + sin(time * 0.1 + idx)), sin(angle + cos(time * 0.08 + idx * 1.3))) * radius;
}

// SDF line segment
float sdSeg(vec2 pt, vec2 a, vec2 b) {
  vec2 pa = pt - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Synapse color palette: white/blue/pink
vec3 synapsePalette(float t) {
  vec3 a = vec3(0.8, 0.85, 1.0);
  vec3 b = vec3(0.2, 0.15, 0.3);
  vec3 c = vec3(1.0, 0.7, 1.2);
  vec3 d = vec3(0.0, 0.15, 0.4);
  return a + b * cos(6.2832 * (c * t + d));
