    float branch = smoothstep(0.02, 0.0, abs(f.x) - 0.002) * step(0.5, n);
    branch += smoothstep(0.02, 0.0, abs(f.y) - 0.002) * step(0.7, n);
    d += branch * (1.0 - i * 0.2) * 0.15;
  }
