uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPolynomialOrder;
uniform float uRootDrift;

#define PI 3.14159265
#define TAU 6.28318530

// Complex multiplication
vec2 cmul(vec2 a, vec2 b) {
  return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

// Complex division
vec2 cdiv(vec2 a, vec2 b) {
  float d = dot(b, b) + 0.0001;
  return vec2(a.x * b.x + a.y * b.y, a.y * b.x - a.x * b.y) / d;
}

// Complex power (integer)
vec2 cpow3(vec2 z) {
  return cmul(cmul(z, z), z);
}

vec2 cpow4(vec2 z) {
  vec2 z2 = cmul(z, z);
  return cmul(z2, z2);
}

vec2 cpow5(vec2 z) {
  vec2 z2 = cmul(z, z);
  return cmul(z2, cmul(z2, z));
}

// Basin palette
vec3 basinPalette(float rootIdx, float iter, float palette, float time) {
  float hue = fract(rootIdx * 0.618033 + palette * 0.1 + time * 0.01);
  float sat = 0.7 + 0.3 * sin(iter * 0.5);
  float val = 0.4 + 0.6 * exp(-iter * 0.15);

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 uv = (vUv - 0.5) * (uZoom * 4.0 + 2.0);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.8;

  // Audio (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  // Define drifting roots based on polynomial order
  float drift = uRootDrift * 1.5 + 0.5;
  float order = uPolynomialOrder;

  // 5 roots that drift in circles
  vec2 roots[5];
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float angle = fi * TAU / 5.0 + time * 0.2 * drift;
    float radius = 1.0 + 0.3 * sin(time * 0.3 + fi * 1.5) * drift;
    radius += bassVal * 0.2;
    roots[i] = vec2(cos(angle), sin(angle)) * radius;
