  vec2 z = uv;
  float smoothIter = 0.0;
  int rootFound = -1;
  float edgeDist = 1e10;

  int numRoots = min(int(order * 3.0 + 2.0), 5);

  for (int i = 0; i < 32; i++) {
    // f(z) = product(z - root_i)
    vec2 f = vec2(1.0, 0.0);
    for (int j = 0; j < 5; j++) {
      if (j >= numRoots) break;
      f = cmul(f, z - roots[j]);
    }

    // f'(z) via logarithmic derivative: f'(z)/f(z) = Σ 1/(z - roots[k])
    // O(n) instead of O(n²) — replaces 20 cmul with 5 cdiv per iteration
    vec2 logDeriv = vec2(0.0, 0.0);
    for (int k = 0; k < 5; k++) {
      if (k >= numRoots) break;
      logDeriv += cdiv(vec2(1.0, 0.0), z - roots[k]);
    }
    vec2 df = cmul(f, logDeriv);

