    float relax = 1.0 + uChaos * sin(float(i) * 0.5 + time) * 0.3;
    vec2 nStep = cdiv(f, df) * relax;
    z -= nStep;

    float stepLen = length(nStep);
    edgeDist = min(edgeDist, stepLen);
    smoothIter += exp(-stepLen * 100.0);

    // Check convergence (dot() avoids 5 sqrt per iteration)
    for (int r = 0; r < 5; r++) {
      if (r >= numRoots) break;
      vec2 d = z - roots[r];
      if (dot(d, d) < 0.0001) {
        rootFound = r;
        break;
