    col = basinPalette(smoothIter * 0.1, smoothIter, uPalette, time) * 0.3;
  }

  // Edge highlighting: sharp boundaries between basins
  float edge = exp(-edgeDist * 50.0);
  vec3 edgeCol = basinPalette(fract(smoothIter * 0.2 + time * 0.08 + sin(uTime * 0.2) * 0.15), 1.0, uPalette, time);
  col += edgeCol * edge * (0.5 + trebleVal * 1.5);

  // Mids: shift basin colors
  col = mix(col, basinPalette(fract(float(rootFound) * 0.3 + midsVal), smoothIter, uPalette, time), midsVal * 0.2);

  // Beat flash on basin boundaries
  col += edgeCol * edge * beatPulse * 0.8;

  // Onset surge
  col += vec3(onset * 0.1, onset * 0.06, onset * 0.12);

  // Kick
  col *= 1.0 + kick * 0.25;

  // Intensity and energy
  col *= uIntensity * 1.5;
  col *= 1.0 + energy * 0.2;

  // Vignette
  float vig = 1.0 - smoothstep(0.5, 1.2, length(vUv - 0.5) * 1.4);
  col *= vig;

  col += vec3(0.008, 0.005, 0.012);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

