  float auroraAccum = 0.0;
  float colorIndex = 0.0;

  // Curtain 1: main green band — fills full screen height
  float sway1 = sin(p.x * 2.0 + time * 0.75 + bassVal * 4.0) * 0.4;
  sway1 += fbm(vec2(p.x * 1.5 + time * 0.45, time * 0.3), 4) * 0.5 * (1.0 + uChaos);
  float curtainY1 = p.y + 0.1 - sway1;
  float curtain1 = exp(-curtainY1 * curtainY1 / (uCurtainWidth * 0.8 + 0.15));
  float wave1 = fbm(vec2(p.x * 3.0 + time * 0.4, p.y * 2.0 + time * 0.15), 5);
  curtain1 *= 0.5 + wave1 * 0.8;
  auroraAccum += curtain1;

  // Curtain 2: purple band, offset — fills full screen height
  float sway2 = sin(p.x * 1.7 - time * 0.6 + bassVal * 3.0) * 0.45;
  sway2 += fbm(vec2(p.x * 1.2 - time * 0.38, time * 0.27 + 5.0), 4) * 0.45 * (1.0 + uChaos);
  float curtainY2 = p.y - 0.3 - sway2;
  float curtain2 = exp(-curtainY2 * curtainY2 / (uCurtainWidth * 0.7 + 0.12));
  float wave2 = fbm(vec2(p.x * 2.5 - time * 0.35, p.y * 1.8 + time * 0.12), 5);
  curtain2 *= 0.4 + wave2 * 0.7;

  // Curtain 3: pink band — fills full screen height
  float sway3 = sin(p.x * 2.3 + time * 0.9 + bassVal * 3.6) * 0.35;
  sway3 += fbm(vec2(p.x * 1.8 + time * 0.53, time * 0.33 + 10.0), 4) * 0.4 * (1.0 + uChaos);
  float curtainY3 = p.y + 0.4 - sway3;
  float curtain3 = exp(-curtainY3 * curtainY3 / (uCurtainWidth * 0.65 + 0.1));
  float wave3 = fbm(vec2(p.x * 3.5 + time * 0.45, p.y * 2.2 - time * 0.1), 5);
  curtain3 *= 0.3 + wave3 * 0.6;

  // Color assignment per curtain — shift with mids and palette
  float shift = uColorShift + midsVal * 0.5 + uPalette * 0.1;

  // Green aurora
  vec3 green = vec3(0.15, 1.0, 0.45) * (1.0 + shift * 0.3);
  // Purple aurora
  vec3 purple = vec3(0.7 + shift * 0.3, 0.15, 1.0);
  // Pink aurora
  vec3 pink = vec3(1.0, 0.3 + shift * 0.3, 0.7);

  vec3 auroraColor = green * curtain1 + purple * curtain2 + pink * curtain3;

  // Magnetic field lines — subtle vertical streaks — spread across full width
  float fieldLine = 0.0;
  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float fx = sin(fi * 1.7 + 3.0) * 1.2;
    float lineX = p.x - fx - sin(time * 0.2 + fi) * 0.15;
    float lineW = 0.006 + uFieldStrength * 0.012;
    float line = exp(-lineX * lineX / (lineW * lineW));
    float lineY = 1.0;
    fieldLine += line * lineY * 0.15 * (0.5 + sin(time * 0.3 + fi * 2.0) * 0.5);
  }
  vec3 fieldColor = vec3(0.4, 0.8, 1.0) * fieldLine;

  // Particle precipitation — tiny sparkles falling down
  float sparkle = 0.0;
  float gridScale = 40.0 + uParticleDensity * 30.0;
  vec2 sg = p * gridScale;
  vec2 si = floor(sg);
  vec2 sf = fract(sg) - 0.5;
  float sh = hash(si);
  float sparkleActive = step(0.92 - trebleVal * 0.05, sh);
  float fallSpeed = (0.5 + sh * 0.5) * time * 3.0;
  float sparkleY = fract(sh * 10.0 - fallSpeed);
  float sparkleDist = length(sf - vec2(0.0, sparkleY - 0.5));
  sparkle = sparkleActive * exp(-sparkleDist * sparkleDist * 800.0);
  sparkle *= 0.5 + sin(time * 8.0 + sh * 6.28) * 0.5;
  vec3 sparkleColor = vec3(0.9, 1.0, 1.0) * sparkle * 0.9;

  // Beat pulse — brighten aurora
  auroraColor *= 1.0 + beatPulse * 1.0;

  // Onset — solar wind burst
  float burstWave = sin(p.x * 4.0 + time * 3.0) * 0.5 + 0.5;
  vec3 burstColor = vec3(0.4, 1.0, 0.7) * onsetFlash * burstWave * 0.8;

  // Stars in background
  float starGrid = 120.0;
  vec2 starUv = p * starGrid;
  vec2 starId = floor(starUv);
  float starH = hash(starId + 100.0);
  float starOn = step(0.985, starH);
  float starTwinkle = sin(time * 2.0 + starH * 20.0) * 0.3 + 0.7;
  vec2 starF = fract(starUv) - 0.5;
  float starDist = length(starF);
  float star = starOn * exp(-starDist * starDist * 2000.0) * starTwinkle * 0.3;
  vec3 starColor = vec3(star);

  vec3 finalColor = skyColor + auroraColor * uIntensity * 1.5 + fieldColor + sparkleColor + burstColor + starColor;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float hash1(float n) { return fract(sin(n) * 43758.5453); }

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Jellyfish bell SDF
float jellyBell(vec2 p, float radius) {
  // Dome shape: upper half is round, lower half pinches in
  float dome = length(vec2(p.x, max(0.0, p.y))) - radius;
  float skirt = length(vec2(p.x * 0.7, min(0.0, p.y) + radius * 0.3)) - radius * 0.6;
  return min(dome, skirt);
}

// Tentacle — sinusoidal trailing curve
float tentacle(vec2 p, vec2 origin, float tentLen, float phase, float time) {
  float minD = 10.0;
  vec2 prev = origin;
  for (float t = 0.0; t < 8.0; t += 1.0) {
    float frac = t / 8.0;
    float xOff = sin(frac * 6.0 + phase + time * 1.5) * 0.04 * (1.0 + frac);
    vec2 cur = origin + vec2(xOff, -frac * tentLen);
    // Distance to segment
    vec2 pa = p - prev;
    vec2 ba = cur - prev;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    float d = length(pa - ba * h);
    float thick = 0.005 * (1.0 - frac * 0.8);
    minD = min(minD, d - thick);
    prev = cur;
  }
  return minD;
}

// Anglerfish lure glow
float anglerLure(vec2 p, vec2 pos, float time) {
  float d = length(p - pos);
  float pulse = 0.5 + 0.5 * sin(time * 3.0);
  return 0.008 * pulse / (d * d + 0.001);
}

// Deep ocean palette
vec3 abyssalPalette(float t) {
  return 0.5 + 0.5 * cos(6.2832 * (t + vec3(0.5, 0.7, 0.9)));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.35) * 0.07;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Deep ocean background gradient
  float depth = vUv.y;
  vec3 col = mix(vec3(0.0, 0.01, 0.04), vec3(0.0, 0.0, 0.01), depth);

  // Underwater caustics
  float caustic = vnoise(p * 3.0 + time * 0.2);
  caustic *= vnoise(p * 5.0 - time * 0.15);
  col += vec3(0.0, 0.06, 0.1) * caustic * (0.4 + bassVal * 0.45);

  // Bass pressure wave: ripple from center
  float pressureDist = length(p);
  float pressureWave = sin(pressureDist * 10.0 - time * 4.0) * bassVal * 0.03;
  vec2 warpedP = p + normalize(p + 0.001) * pressureWave;

  // 5 jellyfish
  for (float i = 0.0; i < 5.0; i += 1.0) {
    float seed = hash1(i * 17.3);
    float jellyX = sin(time * 0.15 + i * 2.0 + seed * 6.28) * 1.2;
    float jellyY = sin(time * 0.1 + i * 1.3) * 0.8 + cos(time * 0.07 + seed * 3.0) * 0.3;
    vec2 jellyPos = vec2(jellyX, jellyY);

    // Pulsing bell
    float pulseRate = 1.5 + midsVal * 2.0;
    float bellPulse = 0.12 + sin(time * pulseRate + i * 1.5) * 0.03;

    vec2 rel = warpedP - jellyPos;
    float bell = jellyBell(rel, bellPulse);
    float bellGlow = smoothstep(0.02, -0.02, bell);

    // Inner bell luminescence
    float innerGlow = smoothstep(bellPulse, 0.0, length(rel)) * 0.8;

    // Jellyfish color
    float hue = seed + uPalette * 0.1 + i * 0.15;
    vec3 jellyCol = abyssalPalette(hue);

    col += jellyCol * bellGlow * 0.75;
    col += jellyCol * innerGlow * 0.55;

    // Tentacles
    for (float t = 0.0; t < 4.0; t += 1.0) {
      float tentPhase = t * 1.5 + seed * 3.0;
      vec2 tentOrigin = jellyPos + vec2((t - 1.5) * 0.03, -bellPulse * 0.5);
      float tentDist = tentacle(warpedP, tentOrigin, 0.25 + i * 0.03, tentPhase, time);
      float tentGlow = smoothstep(0.01, 0.0, tentDist);
      col += jellyCol * 0.5 * tentGlow * 0.3;
    }

    // Bioluminescent halo
    float haloDist = length(warpedP - jellyPos);
    col += jellyCol * 0.015 / (haloDist + 0.05);
  }

  // 3 anglerfish-like lures in the deep
  for (float i = 0.0; i < 3.0; i += 1.0) {
    float seed = hash1(i * 31.7 + 100.0);
    vec2 anglerPos = vec2(
      sin(time * 0.08 + i * 3.0) * 1.0,
      -0.5 + sin(time * 0.06 + i * 2.0) * 0.3
    );

    // Dark body silhouette
    float bodyDist = length(warpedP - anglerPos);
    float bodyShape = smoothstep(0.08, 0.05, bodyDist);
    col *= 1.0 - bodyShape * 0.5; // darken body area

    // Lure light
    vec2 lurePos = anglerPos + vec2(0.0, 0.12);
    float lure = anglerLure(warpedP, lurePos, time + i * 2.0);
    vec3 lureCol = mix(vec3(0.3, 0.8, 1.0), vec3(1.0, 0.3, 0.8), seed);
    col += lureCol * lure * (0.6 + trebleVal * 1.5);

    // Teeth-like sparkles around mouth
    float teethAngle = atan(warpedP.y - anglerPos.y, warpedP.x - anglerPos.x);
    float teethRing = abs(bodyDist - 0.07);
    float teeth = step(0.7, sin(teethAngle * 12.0)) * smoothstep(0.01, 0.0, teethRing);
    col += vec3(0.8, 0.9, 1.0) * teeth * 0.15;
  }

  // Floating particles (marine snow)
  for (float i = 0.0; i < 15.0; i += 1.0) {
    float seed = hash1(i * 23.1 + 200.0);
    vec2 particlePos = vec2(
      fract(seed * 7.3 + time * 0.02) * 4.0 - 2.0,
      fract(seed * 11.7 - time * 0.03) * 4.0 - 2.0
    );
    float pDist = length(warpedP - particlePos);
    float pGlow = 0.001 / (pDist * pDist + 0.0005);
    col += vec3(0.4, 0.6, 0.8) * pGlow * 0.3;
  }

  // Kick: deep bass rumble flash
  col += vec3(0.0, 0.05, 0.1) * kickVal * 0.5;

  // Onset: pressure burst
  col += vec3(0.1, 0.2, 0.3) * uOnset * uSensitivity * 0.3;

  // Chaos: bioluminescent blooms
  float bloom = vnoise(warpedP * (3.0 + uChaos * 8.0) + time * 0.3);
  col += abyssalPalette(bloom + time * 0.05) * bloom * uChaos * 0.15;

  // Energy brightness
  col *= 1.0 + energyVal * 0.25;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Rotated FBM for organic flow
float fbm5(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) {
    val += amp * vnoise(p);
    p = rot * p * 2.02 + vec2(1.7, 3.2);
    amp *= 0.5;
  }
  return val;
}

// Triple domain warp for flow field
vec2 flowField(vec2 p, float time) {
  vec2 q = vec2(fbm5(p + time * 0.05), fbm5(p + vec2(5.2, 1.3) + time * 0.04));
  vec2 r = vec2(fbm5(p + q * 4.0 + time * 0.03), fbm5(p + q * 4.0 + vec2(1.7, 9.2) + time * 0.025));
  return r;
}

// Thin-film interference color from thickness
vec3 thinFilmColor(float thickness) {
  // Simulates constructive/destructive interference at different wavelengths
  float r = 0.5 + 0.5 * cos(thickness * 6.2832 * 2.0);
  float g = 0.5 + 0.5 * cos(thickness * 6.2832 * 2.0 + 2.094);
  float b = 0.5 + 0.5 * cos(thickness * 6.2832 * 2.0 + 4.189);
  return vec3(r, g, b);
}

// Multi-layer thin film (different thickness per layer)
vec3 multiLayerFilm(float base, float flow, float time) {
  vec3 col = vec3(0.0);
  for (float i = 0.0; i < 4.0; i += 1.0) {
    float layerThick = base + i * 0.15 + flow * (0.3 + i * 0.1);
    layerThick += sin(time * 0.5 + i * 1.2) * 0.1;
    vec3 layerCol = thinFilmColor(layerThick + i * 0.25);
    // Each layer blends on top
    float layerOpacity = 0.4 - i * 0.08;
    col = mix(col, layerCol, layerOpacity);
  }
  return col;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  // Flow field warping
  vec2 flow = flowField(p * 1.5, time);
  vec2 warpedP = p + flow * (0.5 + uChaos * 0.5);

  // Bass thickens oil (increases base thickness)
  float baseThickness = 0.3 + bassVal * 0.5 + uPalette * 0.2;

  // Flow intensity from the domain warp
  float flowIntensity = length(flow);

  // Main oil slick — multi-layer iridescence
  vec3 filmColor = multiLayerFilm(baseThickness, flowIntensity, time);

  // Viewing angle simulation (distance from center affects perceived thickness)
  float viewAngle = length(p) * 0.3;
  vec3 angleShift = thinFilmColor(baseThickness + viewAngle + time * 0.1);
  filmColor = mix(filmColor, angleShift, 0.3);

  // Dark water base
  vec3 waterBase = vec3(0.01, 0.015, 0.025);
  float waterNoise = vnoise(p * 2.0 + time * 0.1) * 0.5;

  // Oil patch coverage (flowing, not uniform)
  float oilCoverage = smoothstep(0.3, 0.6, fbm5(warpedP * 2.0 + time * 0.02));
  oilCoverage += kickVal * 0.2; // kicks spread oil patches
  oilCoverage = clamp(oilCoverage, 0.0, 1.0);

  // Combine water and oil
  vec3 col = mix(waterBase + waterNoise * 0.03, filmColor, oilCoverage);

  // Mids: flow speed modulation (more swirling)
  float swirl = sin(length(warpedP) * 8.0 + time * 2.0 + midsVal * 4.0) * 0.5 + 0.5;
  col += thinFilmColor(swirl + baseThickness) * 0.1 * midsVal;

  // Treble sparkle: bright highlight points
  float sparkleGrid = 50.0;
  vec2 sparkleCell = floor(warpedP * sparkleGrid);
  float sparkleSeed = hash21(sparkleCell);
  float sparkleActive = step(0.95, sparkleSeed);
  float sparkleFlash = pow(sin(time * 8.0 + sparkleSeed * 30.0) * 0.5 + 0.5, 10.0);
  col += vec3(1.0) * sparkleActive * sparkleFlash * trebleVal * 0.5;

  // Spectral flux: rapid color shifting
  vec3 fluxShift = thinFilmColor(baseThickness + fluxVal * 2.0 + time * 0.5);
  col = mix(col, fluxShift, fluxVal * 0.15);

  // Kick: ripple wave expanding from center
  float ripple = sin(length(p) * 20.0 - time * 8.0) * kickVal * 0.1;
  col += thinFilmColor(baseThickness + ripple) * abs(ripple);

  // Edge highlighting: Fresnel-like effect
  float edge = pow(length(p) / 2.0, 2.0);
  col += filmColor * edge * 0.15;

  // Onset: bright rainbow flash
  col += thinFilmColor(time * 0.3) * uOnset * uSensitivity * 0.25;

  // Harmonicity affects color coherence
  float harmShift = uHarmonicity * uSensitivity;
  col = mix(col, thinFilmColor(baseThickness + harmShift), harmShift * 0.1);

  // Energy brightness
  col *= 1.0 + energyVal * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLineFrequency;
uniform float uWaveAmplitude;
uniform float uMoireStrength;
uniform float uColorBleed;

#define PI 3.14159265
#define TAU 6.28318530

void main() {
  vec2 uv = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  float freq = 15.0 + uLineFrequency * 30.0 + midsVal * 10.0;
  float waveAmp = uWaveAmplitude * 0.3 + beatVal * 0.15;

  // === PATTERN 1: Wavy parallel lines ===
  // Horizontal lines with vertical wave distortion
  float wave1 = sin(uv.x * 4.0 + time * 2.0) * waveAmp;
  wave1 += sin(uv.x * 7.0 - time * 1.5) * waveAmp * 0.5;
  wave1 += bassVal * sin(uv.x * 2.0 + time) * 0.2;

  float lines1 = sin((uv.y + wave1) * freq);
  float pattern1 = smoothstep(-0.1, 0.1, lines1);

  // === PATTERN 2: Concentric circles ===
  float r = length(uv);
  float circleWave = sin(atan(uv.y, uv.x) * 3.0 + time) * waveAmp * 0.3;
  float circles = sin((r + circleWave) * freq * 0.8 - time * 1.0);
  float pattern2 = smoothstep(-0.1, 0.1, circles);

  // === PATTERN 3: Diagonal lines (for moire) ===
  float diag = uv.x * 0.707 + uv.y * 0.707;
  float diagWave = sin(uv.x * 3.0 + time * 1.5) * waveAmp * 0.5;
  float diags = sin((diag + diagWave) * freq * 1.1 + time * 0.5 + trebleVal * 5.0);
  float pattern3 = smoothstep(-0.15, 0.15, diags);

  // === MOIRE: Overlay creates interference ===
  float moire = abs(pattern1 - pattern3) * uMoireStrength;

  // Combine patterns
  float combined = mix(pattern1, pattern2, 0.3 + uChaos * 0.3);
  combined = combined + moire * 0.5;

  // Kick inversion
  float invert = step(0.5, kickVal);
  combined = mix(combined, 1.0 - combined, invert);

  // Add wave-like bulging distortion (Bridget Riley style)
  float bulge = sin(r * 6.0 - time * 2.0) * 0.5 + 0.5;
  float bulgeMask = exp(-r * 1.5);
  combined = mix(combined, combined * (0.5 + bulge * 0.5), bulgeMask * 0.4);

  // Base: black and white
  vec3 bw = vec3(combined * uIntensity);

  // === COLOR BLEED: On high energy, bleed in psychedelic color ===
  float colorAmount = uColorBleed * energyVal;

  // Color from pattern position
  float hue = fract(combined * 0.5 + r * 0.3 + time * 0.05 + uPalette * 0.15);
  vec3 chromatic = vec3(
    0.5 + 0.5 * cos(TAU * (hue + 0.0)),
    0.5 + 0.5 * cos(TAU * (hue + 0.33)),
    0.5 + 0.5 * cos(TAU * (hue + 0.67))
  );
  chromatic *= combined * uIntensity;

  vec3 color = mix(bw, chromatic, colorAmount);

  // Beat pulse — brief brightness flash
  color += beatVal * 0.1;

  // Treble shimmer at edges
  float edgeShimmer = abs(sin(combined * PI * 20.0)) * trebleVal * 0.1;
  color += edgeShimmer;

  // Vignette
  float vig = 1.0 - length(vUv - 0.5) * 0.5;
  color *= vig;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Kaleidoscopic fold: N-fold rotational symmetry
vec2 kaleidoFold(vec2 uv, float folds) {
  float angle = atan(uv.y, uv.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(uv);
  return vec2(cos(angle), sin(angle)) * r;
}

// Trap palettes
vec3 trapPalette(float t, float idx) {
  vec3 offsets[4];
  offsets[0] = vec3(0.0, 0.3, 0.6);   // circle trap: cyan/magenta
  offsets[1] = vec3(0.1, 0.5, 0.8);   // line trap: blue/yellow
  offsets[2] = vec3(0.3, 0.0, 0.5);   // cross trap: red/purple
  offsets[3] = vec3(0.5, 0.2, 0.0);   // point trap: orange/green
  int i = int(mod(idx, 4.0));
  vec3 off = offsets[0];
  if (i == 1) off = offsets[1];
  if (i == 2) off = offsets[2];
  if (i == 3) off = offsets[3];
  return 0.5 + 0.5 * cos(6.2832 * (t + off));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float kickVal = uKick * uSensitivity * 1.5;
  float energyVal = uEnergy * uSensitivity * 1.5;

  // Kaleidoscopic folding — fold count from 4 to 12 based on energy
  float foldCount = 6.0 + energyVal * 4.0 + uChaos * 2.0;
  vec2 kp = kaleidoFold(p, foldCount);

  // Julia set c parameter — modulated by audio
  float cReal = -0.4 + sin(time * 0.15) * 0.15 + bassVal * 0.1;
  float cImag = 0.6 + cos(time * 0.12) * 0.1 + midsVal * 0.08;
  cReal += uPalette * 0.05;

  // Orbit trap distances (track minimum distance to each trap)
  float trapCircle = 10.0;    // circle at radius 1
  float trapLineX = 10.0;     // horizontal line at y=0
  float trapCross = 10.0;     // cross: min of |x| and |y|
  float trapPoint = 10.0;     // point at origin

  // Julia set iteration
  vec2 z = kp;
  float escaped = 0.0;
  for (int i = 0; i < 26; i++) {
    // z = z^2 + c
    float zx = z.x * z.x - z.y * z.y + cReal;
    float zy = 2.0 * z.x * z.y + cImag;
    z = vec2(zx, zy);

    // Check escape
    float r2 = dot(z, z);
    if (r2 > 100.0) {
      escaped = float(i);
      break;
