    float circDist = abs(length(z) - 1.0);          // circle trap
    float lineDist = abs(z.y);                        // line trap
    float crossDist = min(abs(z.x), abs(z.y));       // cross trap
    float pointDist = length(z);                      // point trap

    trapCircle = min(trapCircle, circDist);
    trapLineX = min(trapLineX, lineDist);
    trapCross = min(trapCross, crossDist);
    trapPoint = min(trapPoint, pointDist);
  }

