  float timeShift = time * 0.08 + uPalette * 0.2 + sin(uTime * 0.2) * 0.15;

  vec3 colCircle = trapPalette(trapCircle * 2.0 + timeShift, 0.0);
  vec3 colLine = trapPalette(trapLineX * 3.0 + timeShift + 0.25, 1.0);
  vec3 colCross = trapPalette(trapCross * 4.0 + timeShift + 0.5, 2.0);
  vec3 colPoint = trapPalette(trapPoint * 1.5 + timeShift + 0.75, 3.0);

  // Weight traps — closer distance = stronger contribution
  float wCircle = exp(-trapCircle * 5.0);
  float wLine = exp(-trapLineX * 8.0);
  float wCross = exp(-trapCross * 6.0);
  float wPoint = exp(-trapPoint * 3.0);

  float totalW = wCircle + wLine + wCross + wPoint + 0.001;
  vec3 col = (colCircle * wCircle + colLine * wLine + colCross * wCross + colPoint * wPoint) / totalW;

  // Escaped pixels: dark with subtle color
  if (escaped > 0.0) {
    float smooth_iter = escaped - log(log(dot(z, z)) / log(100.0)) / log(2.0);
    vec3 escapeCol = trapPalette(smooth_iter * 0.05 + timeShift, 0.0) * 0.15;
    col = mix(col, escapeCol, 0.7);
  }

  // Beat: bright flash on trap boundaries
  float trapEdge = smoothstep(0.02, 0.0, trapCircle) + smoothstep(0.01, 0.0, trapLineX);
  col += vec3(1.0, 0.9, 0.8) * trapEdge * uBeat * uSensitivity * 0.5;

  // Kick: deep fractal zoom pulse
  col *= 1.0 + kickVal * 0.6;

  // Treble: sparkle on trap intersections
  float intersect = wCircle * wLine * 10.0;
  col += vec3(1.0) * intersect * trebleVal * 0.3;

  // Onset flash
  col += trapPalette(time * 0.1, 2.0) * uOnset * uSensitivity * 0.2;

  // Spectral centroid: shift hue temperature
  col = mix(col, col.gbr, uSpectralCentroid * uSensitivity * 0.1);

  // Energy brightness
  col *= 1.0 + energyVal * 0.3;

  // Chaos: more aggressive c modulation
  col += trapPalette(trapPoint + uChaos * 2.0, 3.0) * uChaos * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

