// Warm love palette: rose, gold, peach
vec3 lovePalette(float t) {
  vec3 a = vec3(0.8, 0.5, 0.5);
  vec3 b = vec3(0.2, 0.3, 0.2);
  vec3 c = vec3(1.0, 0.8, 0.7);
  vec3 d = vec3(0.0, 0.15, 0.3);
