  col += vec3(0.15, 0.05, 0.05) * bassVal * 0.3;

  // Onset: love flash
  col += vec3(1.0, 0.7, 0.8) * uOnset * uSensitivity * 0.25;

  // Warmth uniform: emphasize warm tones
  col += vec3(0.05, 0.02, 0.0) * warmthVal * 0.3;

  // Harmonicity: coherent golden glow
  col += vec3(0.3, 0.2, 0.1) * uHarmonicity * uSensitivity * 0.15;

