  vec2 warp2 = vec2(
    fbm(uv * 2.0 + flowOffset * 1.5 + time * 0.2, 5),
    fbm(uv * 2.0 + flowOffset * 1.5 + vec2(8.3, 2.8) + time * 0.15, 5)
  );

