  float cellScale = (3.0 + uCellSize * 4.0) + bassVal * 2.0;
  vec2 cellUV = uv * cellScale + warp2 * (2.0 + uChaos * 3.0);

  // Multiple paint layers
  float layer1 = fbm(cellUV, 5);
  float layer2 = fbm(cellUV * 1.3 + vec2(3.7, 7.1) + time * 0.1, 5);
  float layer3 = fbm(cellUV * 0.7 + vec2(11.3, 4.5) - time * 0.08, 4);

  // Cell boundaries — where layers cross threshold
  float cellEdge1 = abs(layer1 - 0.5) * 2.0;
  float cellEdge2 = abs(layer2 - 0.5) * 2.0;
  float cellBound = min(cellEdge1, cellEdge2);
  float separation = smoothstep(0.1, 0.0, cellBound) * uSeparationStrength;

  // Kick triggers new pour burst
  float pourBurst = kickVal * fbm(uv * 8.0 + time * 3.0, 3) * 0.5;

