  float t1 = layer1 + uPalette * 0.1 + time * 0.02;
  float t2 = layer2 + uPalette * 0.1 + 0.33 + time * 0.015;
  float t3 = layer3 + uPalette * 0.1 + 0.67 - time * 0.01;

  vec3 col1 = paintColor(t1, uPalette);
  vec3 col2 = paintColor(t2, uPalette + 1.0);
  vec3 col3 = paintColor(t3, uPalette + 2.0);

  // Blend layers based on fbm values
  float blend12 = smoothstep(0.4, 0.6, layer1 + midsVal * 0.3);
  float blend23 = smoothstep(0.3, 0.7, layer2 - midsVal * 0.2);

  vec3 mixed = mix(col1, col2, blend12);
  mixed = mix(mixed, col3, blend23 * step(2.0, numLayers));

