  // Slight vignette for depth
  float vig = 1.0 - length(vUv - 0.5) * 0.6;
  mixed *= vig;

  // === PSYCHEDELIC ENHANCEMENT ===
  mixed = psychedelicColor(mixed);
  gl_FragColor = vec4(clamp(mixed, 0.0, 1.0), 1.0);
}

