uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

#define PI 3.14159265
#define TAU 6.28318530

float hash21(vec2 co) {
  return fract(sin(dot(co, vec2(127.1, 311.7))) * 43758.5453);
}

vec2 hash22(vec2 co) {
  float n = sin(dot(co, vec2(127.1, 311.7)));
  return fract(vec2(n, n * 1.2345) * 43758.5453);
}

float valueNoise(vec2 co) {
  vec2 i = floor(co);
  vec2 f = fract(co);
  f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmNoise(vec2 co, int oct) {
  float val = 0.0;
  float amp = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 7; i++) {
    if (i >= oct) break;
    val += amp * valueNoise(co);
    co = rot * co * 2.0 + vec2(5.3, 1.7);
    amp *= 0.5;
  }
  return val;
}

float sdEllipse(vec2 co, vec2 rad) {
  vec2 q = co / rad;
  return (length(q) - 1.0) * min(rad.x, rad.y);
}

float sdDisk(vec2 co, float rad) {
  return length(co) - rad;
}

vec3 fleshPalette(float t, float shift) {
  vec3 a = vec3(0.55, 0.35, 0.28);
  vec3 b = vec3(0.35, 0.25, 0.2);
  vec3 c = vec3(1.0, 0.8, 0.6);
  vec3 d = vec3(0.1 + shift * 0.3, 0.2, 0.4);
  return a + b * cos(TAU * (c * t + d));
}

// Bilateral symmetric noise for face-like patterns
float symmetricField(vec2 co, float t) {
  vec2 symCo = vec2(abs(co.x), co.y);
  float n1 = fbmNoise(symCo * 2.5 + vec2(t * 0.1, 0.0), 5);
  float n2 = fbmNoise(symCo * 4.0 + vec2(0.0, t * 0.08), 4);
  float warp = fbmNoise(symCo * 1.5 + vec2(n1 * 2.0, n2 * 1.5), 5);
  return warp;
}

// Face feature SDF composite
float faceFeatures(vec2 co, float morphT, float alienFactor) {
  vec2 symCo = vec2(abs(co.x), co.y);
  float features = 0.0;

  // Face oval - morphs from round human to elongated alien
  vec2 ovalRad = mix(vec2(0.45, 0.6), vec2(0.32, 0.85), alienFactor);
  float faceOval = sdEllipse(co, ovalRad);
  features += smoothstep(0.05, -0.05, faceOval) * 0.1;

  // Eye sockets
  float eyeSpread = mix(0.18, 0.14, alienFactor);
  float eyeHeight = mix(0.12, 0.2, alienFactor);
  vec2 eyePos = vec2(eyeSpread + sin(morphT * 0.3) * 0.02,
                     eyeHeight + cos(morphT * 0.25) * 0.02);
  float eyeRad = mix(0.065, 0.09, alienFactor);
  float eyeDist = sdDisk(symCo - eyePos, eyeRad + sin(morphT * 0.4) * 0.01);
  features += smoothstep(0.02, -0.02, eyeDist) * 0.4;

  // Iris detail inside eyes
  float irisRad = eyeRad * 0.55;
  float irisDist = sdDisk(symCo - eyePos, irisRad);
  features += smoothstep(0.01, -0.01, irisDist) * 0.2;

  // Pupil
  float pupilRad = irisRad * 0.4 + sin(morphT * 0.6) * 0.005;
  float pupilDist = sdDisk(symCo - eyePos, pupilRad);
  features += smoothstep(0.005, -0.005, pupilDist) * 0.3;

  // Nose ridge (bilateral shadow)
  float noseLen = mix(0.1, 0.18, alienFactor);
  float noseDist = sdEllipse(co - vec2(0.0, -0.02), vec2(0.03, noseLen));
  features += smoothstep(0.02, -0.01, noseDist) * 0.15;

  // Mouth
  vec2 mouthPos = vec2(0.0, mix(-0.22, -0.35, alienFactor));
  float mouthWidth = mix(0.15, 0.1, alienFactor);
  float mouthCurve = co.y - mouthPos.y + pow(co.x - mouthPos.x, 2.0) * 3.0;
  float mouth = smoothstep(0.02, 0.0, abs(mouthCurve)) *
                smoothstep(mouthWidth, 0.0, abs(co.x - mouthPos.x));
  features += mouth * 0.12;

  return features;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  // Alien factor driven by chaos + energy
  float alienFactor = clamp(uChaos * 0.7 + energyVal * 0.3, 0.0, 1.0);

  // Morphing rate driven by mids
  float morphTime = time * (1.0 + midsVal * 0.5);

  // === BILATERAL SYMMETRIC NOISE FIELD ===
  float symField = symmetricField(p, morphTime);

  // === FACE FEATURES ===
  // Multiple face scales emerging from the noise
  float totalFace = 0.0;
  float eyeGlint = 0.0;

  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    // Face center drifts
    vec2 center = vec2(
      sin(morphTime * (0.08 + fi * 0.02) + fi * 2.0) * 0.3,
      cos(morphTime * (0.06 + fi * 0.03) + fi * 1.5) * 0.25
    );
    float scl = 0.8 + fi * 0.2 + sin(morphTime * 0.05 + fi) * 0.1;

    // Phase in/out -- pareidolia emergence
    float phase = sin(morphTime * (0.06 + fi * 0.01) + fi * 1.3);
    float blend = smoothstep(-0.3 - beatPulse * 0.2, 0.4, phase) *
                  smoothstep(1.1, 0.6 + beatPulse * 0.2, phase);
    blend *= 0.4 + uChaos * 0.3;
    blend += kickVal * 0.15;

    float face = faceFeatures((p - center) / scl, morphTime + fi * 4.0, alienFactor);
    totalFace += face * blend;

    // Eye glints
    vec2 fp = (p - center) / scl;
    vec2 symFp = vec2(abs(fp.x), fp.y);
    float eyeSpread = mix(0.18, 0.14, alienFactor);
    float eyeHeight = mix(0.12, 0.2, alienFactor);
    vec2 eyePos = vec2(eyeSpread, eyeHeight);
    float glintDist = length(symFp - eyePos - vec2(0.02, 0.02));
    eyeGlint += smoothstep(0.02, 0.0, glintDist) * blend * trebleVal;
  }

  // === THIRD EYE at high energy ===
  float thirdEyeStr = smoothstep(0.5, 0.9, energyVal);
  vec2 thirdEyePos = vec2(0.0, 0.35);
  float thirdEyeDist = sdDisk(p - thirdEyePos, 0.08 + sin(morphTime * 0.8) * 0.02);
  float thirdEye = smoothstep(0.02, -0.02, thirdEyeDist) * thirdEyeStr;
  float thirdEyeIris = smoothstep(0.01, -0.01, sdDisk(p - thirdEyePos, 0.04)) * thirdEyeStr;
  totalFace += thirdEye * 0.5;
  float thirdGlint = smoothstep(0.015, 0.0, length(p - thirdEyePos - vec2(0.015, 0.015))) * thirdEyeStr;
  eyeGlint += thirdGlint * 1.5;

  // === COMPOSITE ===
  float baseField = symField - totalFace;
  float shadows = 1.0 - baseField;
  shadows = pow(shadows, 1.0 + bassVal * 1.5);

  // Color: flesh/gold/void
  float hue = fract(baseField * 0.25 + uPalette * 0.1 + time * 0.015 + totalFace * 0.15);
  vec3 baseColor = fleshPalette(hue, uPalette * 0.1);

  // Gold highlights at face features
  vec3 goldTint = vec3(0.95, 0.78, 0.3);
  baseColor = mix(baseColor, goldTint, totalFace * 1.5);

  // Void darkness in eye sockets
  baseColor *= 1.0 - totalFace * 0.6;

  // Apply shadows
  vec3 col = baseColor * (0.3 + shadows * 0.7);

  // Alien tint: shift toward purple/green
  vec3 alienTint = mix(vec3(0.85, 0.75, 0.95), vec3(0.5, 0.9, 0.6), sin(morphTime * 0.1) * 0.5 + 0.5);
  col = mix(col, col * alienTint, alienFactor * 0.4);

  // Eye glints -- bright white/gold specular
  col += vec3(0.9, 0.85, 0.6) * eyeGlint * 3.0;

  // Third eye glow -- ethereal purple
  col += vec3(0.6, 0.2, 0.9) * thirdEyeIris * 2.0;

  // Fine noise texture
  float fineN = valueNoise(p * 15.0 + time * 0.5) * 0.04;
  col += vec3(fineN) * 0.3;

  // Beat: faces sharpen and glow
  col += fleshPalette(time * 0.1, 0.0) * beatPulse * 0.08 * (1.0 + totalFace * 3.0);

  // Onset: ethereal flash
  col += vec3(0.15, 0.1, 0.2) * onsetVal;

  // Kick: ripple through the face field
  float kickRipple = sin(length(p) * 10.0 - time * 5.0) * kickVal * 0.05;
  col += fleshPalette(kickRipple + time * 0.05, 0.3) * abs(kickRipple);

  // BPM breathing
  col *= 0.95 + uBpmSin * 0.05;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPendulumCount;
uniform float uPhaseSpread;
uniform float uOrbGlow;

float hash(float x) {
  return fract(sin(x * 127.1) * 43758.5453);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float entropyVal = uSpectralEntropy;
  float energyVal = uEnergy * uSensitivity;
  float bpmSinVal = uBpmSin;
  float centroidVal = uSpectralCentroid;

  int count = int(8.0 + uPendulumCount * 16.0);
  float fCount = float(count);

  vec3 col = vec3(0.01, 0.01, 0.02); // Dark background

  // Phase spread: entropy increases desynchronization
  float spread = uPhaseSpread * (1.0 + entropyVal * 0.5);

  // Kick: momentary phase reset (all align)
  float resetAmount = kickVal * 2.0;

  // Track alignment for flash effect
  float avgY = 0.0;
  float maxAlignment = 0.0;

  for (int i = 0; i < 24; i++) {
    if (i >= count) break;
    float fi = float(i);

    // Each pendulum has slightly different frequency
    // This creates the classic pendulum wave pattern
    float baseFreq = 1.0; // BPM-locked base
    float freqOffset = fi * spread * 0.05;
    float freq = baseFreq + freqOffset;

    // BPM-locked oscillation
    float bpmPhase = time * freq * 2.0;

    // Phase: desynchronized normally, reset on kick
    float phase = bpmPhase + fi * spread * 0.3;
    phase = mix(phase, bpmPhase, resetAmount); // Kick resets toward in-phase

    // Pendulum Y position (sine oscillation)
    float pendY = sin(phase) * (0.6 + bassVal * 0.2);

    // X position: evenly distributed
    float pendX = (fi / fCount - 0.5) * 1.8;

    avgY += pendY;

    // Orb position
    vec2 orbPos = vec2(pendX, pendY);
    float orbDist = length(p - orbPos);

    // Orb glow
    float orbSize = 0.03 + uOrbGlow * 0.02;
    float glow = exp(-orbDist * orbDist / (orbSize * orbSize));

    // String (thin line from top to orb)
    vec2 topPos = vec2(pendX, 0.9);
    vec2 toOrb = orbPos - topPos;
    float stringLen = length(toOrb);
    vec2 stringDir = toOrb / stringLen;
    vec2 toP = p - topPos;
    float projLen = dot(toP, stringDir);
    float perpDist = length(toP - stringDir * clamp(projLen, 0.0, stringLen));
    float string = exp(-perpDist * perpDist * 10000.0) * 0.3;

    // Color per pendulum: rainbow gradient
    float hue = fi / fCount + uPalette * 0.3 + time * 0.02;
    vec3 orbColor = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.33, 0.67)));

    // Brighter when moving fast (at center of swing)
    float velocity = abs(cos(phase));
    orbColor *= 0.7 + velocity * 0.5;

    col += glow * orbColor * 0.8;
    col += string * orbColor * 0.3;

    // Trail: fading afterimage
    for (float t = 1.0; t <= 3.0; t += 1.0) {
      float trailPhase = phase - t * 0.15;
      float trailY = sin(trailPhase) * (0.6 + bassVal * 0.2);
      vec2 trailPos = vec2(pendX, trailY);
      float trailDist = length(p - trailPos);
      float trailGlow = exp(-trailDist * trailDist / (orbSize * 2.0 * orbSize)) * 0.15 / t;
      col += trailGlow * orbColor * 0.4;
    }
  }

  // Alignment detection: when all pendulums are in phase, flash
  avgY /= fCount;
  float alignment = 1.0 - clamp(abs(avgY) * 3.0, 0.0, 1.0);
  alignment = pow(alignment, 4.0);

  // Alignment flash
  col += alignment * 0.3 * vec3(1.0, 0.95, 0.8);

  // Treble: sparkle on orbs
  col += trebleVal * 0.05 * vec3(0.8, 0.9, 1.0);

  // Mids: ambient glow
  col += midsVal * 0.03 * vec3(0.4, 0.3, 0.5);

  // Centroid: color temperature
  col = mix(col, col * vec3(1.1, 0.95, 0.85), centroidVal * 0.2);

  // Energy: brightness
  col *= 0.8 + energyVal * 0.3;

  // BPM breathing
  col *= 0.9 + (bpmSinVal * 0.5 + 0.5) * 0.12;

  // Chaos: slight position jitter
  col *= 1.0 + uChaos * 0.1 * sin(p.x * 20.0 + time * 5.0);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPendulumCount;
uniform float uFreqSpread;
uniform float uTrailGlow;
uniform float uPhaseWarp;

vec3 wavePalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.1, 0.2)));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numPendulums = min(uPendulumCount, 40.0);

  vec3 color = vec3(0.0);
  float totalGlow = 0.0;

  // Main pendulum wave array (horizontal arrangement)
  for (float i = 0.0; i < 40.0; i += 1.0) {
    if (i >= numPendulums) break;

    float frac = i / numPendulums;

    // Each pendulum has a slightly different frequency
    float baseFreq = 1.0 + i * uFreqSpread;
    float freq = baseFreq + bassVal * 0.2;

    // Phase warping: audio distorts the wave
    float warpedTime = time + sin(i * 0.5 + time * 0.1) * uPhaseWarp;
    warpedTime += midsVal * sin(i * 0.3) * 0.3;

    // Pendulum position (sinusoidal motion) — full screen height
    float pendulumY = sin(warpedTime * freq + onsetVal * sin(i * 0.7)) * 0.9;

    // Pendulum x position in the array — spread wider
    float pendulumX = (frac - 0.5) * 2.2;

    // Distance from this pixel to the pendulum bob
    vec2 pendulumPos = vec2(pendulumX, pendulumY);
    float dist = length(p - pendulumPos);

    // Bob glow — larger
    float bobGlow = exp(-dist * 10.0);

    // String from top to bob
    float stringX = abs(p.x - pendulumX);
    float stringY = p.y - pendulumY;
    float stringT = clamp((p.y - pendulumY) / (1.2 - pendulumY), 0.0, 1.0);
    float stringPos = mix(pendulumX, pendulumX, stringT); // straight string
    float stringDist = abs(p.x - stringPos);
    float stringGlow = exp(-stringDist * 60.0) * step(pendulumY, p.y) * step(p.y, 1.2);

    // Trail effect: multiple time samples — longer trails
    float trailAccum = 0.0;
    for (float t = 0.0; t < 8.0; t += 1.0) {
      float trailTime = warpedTime - t * 0.04;
      float trailY = sin(trailTime * freq) * 0.9;
      float trailDist = length(p - vec2(pendulumX, trailY));
      float fade = exp(-t * 0.5);
      trailAccum += exp(-trailDist * 10.0) * fade;
    }
    trailAccum *= uTrailGlow;

    // Color per pendulum
    float hue = frac + uPalette * 0.1 + time * 0.01;
    vec3 pendColor = wavePalette(hue, uPalette * 0.05);

    // Chaos: jitter pendulum hue
    pendColor = mix(pendColor, pendColor.gbr, uChaos * sin(i * 3.7 + time * 0.3) * 0.3);

    float brightness = bobGlow * 2.0 + stringGlow * 0.3 + trailAccum * 0.5;
    color += pendColor * brightness;
    totalGlow += brightness;
  }

  // Wave interference pattern (the beautiful part)
  // Render a secondary moire pattern from the collective motion
  float moirePattern = 0.0;
  for (float i = 0.0; i < 40.0; i += 1.0) {
    if (i >= numPendulums) break;
    float freq = 1.0 + i * uFreqSpread;
    float wave = sin(p.y * 8.0 + time * freq + p.x * 3.0);
    moirePattern += wave;
  }
  moirePattern /= numPendulums;
  moirePattern = moirePattern * 0.5 + 0.5;

  // Moire underlay — stronger for full-screen fill
  vec3 moireColor = wavePalette(moirePattern + time * 0.02, uPalette * 0.1 + 0.3);
  color += moireColor * moirePattern * 0.15;

  // Background fill so edges are not pure black
  color += wavePalette(time * 0.01 + length(p) * 0.1, uPalette * 0.1) * 0.025;

  // Treble sparkle
  float sparkle = sin(p.x * 60.0 + time * 5.0) * sin(p.y * 60.0 - time * 4.0);
  sparkle = pow(max(sparkle, 0.0), 20.0);
  color += vec3(sparkle * trebleVal * 0.2);

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.05);

  // Kick punch
  color = mix(color, color * 1.4, kickVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.15));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

#define PI 3.14159265
#define TAU 6.28318530

vec2 rotate2d(vec2 co, float ang) {
  float c = cos(ang), s = sin(ang);
  return vec2(co.x * c - co.y * s, co.x * s + co.y * c);
}

float hash21(vec2 co) {
  return fract(sin(dot(co, vec2(127.1, 311.7))) * 43758.5453);
}

// Stone-like procedural texture
float stoneTexture(vec2 co) {
  vec2 i = floor(co);
  vec2 f = fract(co);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  float n1 = mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  i = floor(co * 3.7);
  f = fract(co * 3.7);
  f = f * f * (3.0 - 2.0 * f);
  a = hash21(i + vec2(50.0));
  b = hash21(i + vec2(51.0, 0.0));
  c = hash21(i + vec2(50.0, 1.0));
  d = hash21(i + vec2(51.0, 1.0));
  float n2 = mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  return n1 * 0.6 + n2 * 0.4;
}

// Isometric staircase SDF -- infinite ascending stairs
float stairField(vec2 co, float shift) {
  // Isometric projection: skew coordinates
  vec2 iso = vec2(co.x + co.y * 0.5, co.y * 0.866);
  iso += vec2(shift, 0.0);

  // Stair steps: repeating ramps
  float stairPeriod = 0.5;
  float stairX = mod(iso.x, stairPeriod) - stairPeriod * 0.5;
  float stairY = mod(iso.y, stairPeriod) - stairPeriod * 0.5;

  // Each stair is a flat top with vertical riser
  float tread = abs(stairY) - 0.15;
  float riser = abs(stairX) - 0.18;
  float stairSDF = max(tread, riser);

  // Edge detection for neon outline
  return stairSDF;
}

// Pillar SDF -- isometric columns
float pillarField(vec2 co, float t) {
  float period = 1.2;
  vec2 cell = mod(co + 0.5 * period, period) - 0.5 * period;
  float pillarRad = 0.06 + sin(t * 0.5 + floor((co.x + 0.5 * period) / period) * 2.0) * 0.01;
  float pillar = length(cell) - pillarRad;
  return pillar;
}

// Impossible triangle outline
float impossibleTriangle(vec2 co, float sz, float barW) {
  float result = 1e5;
  for (int i = 0; i < 3; i++) {
    float ang = float(i) * TAU / 3.0 - PI / 2.0;
    float nextAng = float(i + 1) * TAU / 3.0 - PI / 2.0;
    vec2 a = vec2(cos(ang), sin(ang)) * sz;
    vec2 b = vec2(cos(nextAng), sin(nextAng)) * sz;
    // Line segment distance
    vec2 pa = co - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    float segDist = length(pa - ba * h);
    // Inner/outer bar edges
    float barDist = abs(segDist - barW * 0.5) - barW * 0.12;
    // Depth illusion: overlap priority per edge
    float depthBias = sin(float(i) * 2.094 + dot(co, vec2(2.0, 3.0))) * 0.003;
    result = min(result, barDist + depthBias);
  }
  return result;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Beat shifts perspective rotation — faster
  float perspAngle = time * 0.18 + beatPulse * 0.5 + uBpmSin * 0.25;
  vec2 rp = rotate2d(p, perspAngle);

  // === STONE BACKGROUND ===
  float stone = stoneTexture(rp * 3.0 + time * 0.05);
  vec3 stoneCol = mix(vec3(0.08, 0.06, 0.1), vec3(0.2, 0.18, 0.22), stone);

  // === INFINITE STAIRCASE ===
  float stairShift = time * 0.3;
  float stairs = stairField(rp * 2.5, stairShift);
  float stairEdge = smoothstep(0.02, 0.0, abs(stairs));
  float stairFill = smoothstep(0.0, -0.04, stairs);

  // Stair surface with stone texture
  vec3 stairSurface = mix(vec3(0.12, 0.1, 0.15), vec3(0.25, 0.22, 0.28), stone * 0.8);
  stairSurface += vec3(0.05) * sin(rp.x * 20.0 + rp.y * 15.0 + time) * 0.3; // subtle grain

  // === ISOMETRIC PILLARS ===
  float pillars = pillarField(rp * 1.5 + vec2(time * 0.05), time);
  float pillarEdge = smoothstep(0.015, 0.0, abs(pillars));
  float pillarFill = smoothstep(0.0, -0.02, pillars);

  vec3 pillarCol = mix(vec3(0.15, 0.12, 0.2), vec3(0.3, 0.28, 0.35), stone);

  // === IMPOSSIBLE TRIANGLES ===
  float triResult = 1e5;
  vec3 triGlowCol = vec3(0.0);

  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float triSize = 0.4 + fi * 0.2;
    float triRot = time * 0.14 * (mod(fi, 2.0) < 1.0 ? 1.0 : -1.0) + fi * 0.7;
    vec2 triP = rotate2d(p, triRot);
    triP += vec2(sin(time * 0.1 + fi * 2.0), cos(time * 0.12 + fi * 1.5)) * 0.3;
    float barW = 0.06 + fi * 0.012;
    float tri = impossibleTriangle(triP, triSize, barW);

    float triEdge = smoothstep(0.012, 0.0, abs(tri));
    float triFill = smoothstep(0.005, -0.005, tri);

    // Neon color per triangle layer
    float hue = fi / 5.0 + uPalette * 0.5 + time * 0.05;
    vec3 neonCol = 0.5 + 0.5 * cos(TAU * (hue + vec3(0.0, 0.33, 0.67)));
    neonCol *= 1.5; // overdrive for neon

    triGlowCol += neonCol * triEdge * (0.5 + trebleVal * 0.5);
    triGlowCol += neonCol * triFill * 0.15;
    triResult = min(triResult, tri);
  }

  // === COMPOSITE ===
  vec3 col = stoneCol;

  // Stair layer
  col = mix(col, stairSurface, stairFill * 0.7);
  // Neon stair edges
  vec3 stairNeon = 0.5 + 0.5 * cos(TAU * (time * 0.02 + uPalette * 0.3 + vec3(0.5, 0.7, 0.9)));
  col += stairNeon * stairEdge * (0.4 + midsVal * 0.4);

  // Pillar layer
  col = mix(col, pillarCol, pillarFill * 0.6);
  vec3 pillarNeon = 0.5 + 0.5 * cos(TAU * (time * 0.03 + uPalette * 0.4 + vec3(0.1, 0.4, 0.7)));
  col += pillarNeon * pillarEdge * (0.3 + trebleVal * 0.3);

  // Impossible triangle overlay
  col += triGlowCol;

  // === DEPTH FOG -- impossible depth illusion ===
  float depthFog = smoothstep(0.5, 2.5, length(p)) * 0.3;
  col = mix(col, vec3(0.05, 0.03, 0.08), depthFog);

  // === AUDIO REACTIONS ===
  // Bass: stone vibration (subtle warp visual)
  float bassWarp = sin(length(rp) * 8.0 - time * 3.0) * bassVal * 0.03;
  col += vec3(0.1, 0.08, 0.15) * abs(bassWarp);

  // Beat: perspective flash
  col += vec3(0.08, 0.06, 0.12) * beatPulse * 0.4;

  // Kick: impossible depth invert
  col = mix(col, 1.0 - col * 0.5, kickVal * 0.12);

  // Onset: architecture flash
  col += vec3(0.12, 0.1, 0.18) * onsetVal * 0.5;

  // Energy: neon intensity
  col *= 0.8 + energyVal * 0.3;

  // Chaos: subtle geometry distortion tint
  col += vec3(sin(p.x * 20.0 + time * 5.0) * cos(p.y * 20.0 - time * 3.0)) * uChaos * 0.02;

  // BPM breathing
  col *= 0.95 + uBpmSin * 0.05;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__
uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

#define PI 3.14159265
#define TAU 6.28318530
#define GOLDEN_RATIO 1.6180339887

float hash21(vec2 co) {
  return fract(sin(dot(co, vec2(127.1, 311.7))) * 43758.5453);
}

// Quasicrystal: sum of 5 plane waves at 36-degree intervals
// Returns raw wave sum and edge proximity
vec3 quasicrystal(vec2 co, float time, float morph) {
  float waveSum = 0.0;
  float edgeMin = 100.0;
  float tileIndex = 0.0;

  for (int i = 0; i < 7; i++) {
    float fi = float(i);
    float ang = fi * PI / 7.0;
    vec2 dir = vec2(cos(ang), sin(ang));

    // Project position onto wave direction
    float proj = dot(co, dir);

    // Golden ratio offset for true quasicrystal aperiodicity
    float offset = fi * GOLDEN_RATIO;

    // Audio morph per wave direction
    float waveMorph = morph * sin(time * 0.3 + fi * 1.2) * 0.15;

    // The wave
    float wave = cos(proj * TAU + offset + waveMorph);
    waveSum += wave;

    // Edge detection: fractional part of grid projection
    float gridVal = proj + offset / TAU;
    float gridFrac = fract(gridVal);
    float edgeDist = min(gridFrac, 1.0 - gridFrac);
    edgeMin = min(edgeMin, edgeDist);

    // Tile classification from floor values
    tileIndex += floor(gridVal) * pow(2.0, fi);
  }

  return vec3(waveSum / 7.0, edgeMin, tileIndex);
}

// Moire pattern from two interfering grids
float moireField(vec2 co, float freq1, float freq2) {
  float g1 = sin(co.x * freq1) * sin(co.y * freq1);
  float g2 = sin(co.x * freq2) * sin(co.y * freq2);
  return g1 * g2;
}

// Iridescent palette for tiles
vec3 tileColor(float idx, float offset, float time) {
  float hue = fract(idx * 0.1 + offset + time * 0.01);
  vec3 col = 0.5 + 0.5 * cos(TAU * (hue + vec3(0.0, 0.33, 0.67)));
  // Boost saturation
  float gray = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(gray), col, 1.4);
  return clamp(col, 0.0, 1.0);
}

// Audio band value for tile coloring
float audioBand(float bandIdx) {
  float b = mod(bandIdx, 8.0);
  if (b < 1.0) return uSpectrum0;
  else if (b < 2.0) return uSpectrum1;
  else if (b < 3.0) return uSpectrum2;
  else if (b < 4.0) return uSpectrum3;
  else if (b < 5.0) return uSpectrum4;
  else if (b < 6.0) return uSpectrum5;
  else if (b < 7.0) return uSpectrum6;
  else return uSpectrum7;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Faster rotation revealing symmetry
  float rotAngle = time * 0.08 + uBpmSin * 0.06;
  float cr = cos(rotAngle);
  float sr = sin(rotAngle);
  p = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

  // Chaos: domain warp
  p += vec2(sin(p.y * 2.5 + time * 0.2), cos(p.x * 2.5 + time * 0.25)) * uChaos * 0.08;

  // Scale for tiling density — higher
  float scale = 4.0 + bassVal * 0.8;
  vec2 scaledP = p * scale;

  // === QUASICRYSTAL ===
  float morphAmt = midsVal * 0.5 + uChaos * 0.3;
  vec3 qc = quasicrystal(scaledP, time, morphAmt);
  float waveField = qc.x;
  float edgeDist = qc.y;
  float tileIdx = qc.z;

  // === SECOND LAYER: slightly rotated for moire ===
  float rot2 = time * 0.015 + 0.618;
  vec2 p2 = vec2(p.x * cos(rot2) - p.y * sin(rot2), p.x * sin(rot2) + p.y * cos(rot2));
  vec3 qc2 = quasicrystal(p2 * scale * 1.05, time * 0.8, morphAmt * 0.7);
  float waveField2 = qc2.x;

  // === MOIRE INTERFERENCE ===
  float moire = moireField(p, scale * 1.0, scale * 1.05 + bassVal * 0.2);
  moire = abs(moire);

  // === TILE COLORING BY AUDIO BAND ===
  float bandIdx = mod(tileIdx, 8.0);
  float bandEnergy = audioBand(bandIdx) * uSensitivity;

  vec3 baseCol = tileColor(tileIdx, uPalette * 0.3, time);
  // Modulate brightness by band energy
  baseCol *= 0.5 + bandEnergy * 0.8;

  // === EDGE WIREFRAME ===
  float edgeGlow = smoothstep(0.06, 0.0, edgeDist);
  float edgeLine = smoothstep(0.015, 0.0, edgeDist);

  // Fill with edge darkening
  float fillBright = smoothstep(0.0, 0.1, edgeDist);
  vec3 col = baseCol * fillBright * 0.6;

  // Edge color -- treble-reactive neon
  vec3 edgeCol = tileColor(tileIdx + 5.0, uPalette * 0.4 + 0.5, time);
  col += edgeGlow * edgeCol * (0.3 + trebleVal * 0.5);
  col += edgeLine * vec3(1.0, 0.95, 0.9) * (0.2 + trebleVal * 0.3);

  // === MOIRE OVERLAY ===
  vec3 moireCol = 0.5 + 0.5 * cos(TAU * (moire * 2.0 + time * 0.05 + uPalette * 0.2 + vec3(0.0, 0.2, 0.5)));
  col += moireCol * moire * 0.15 * (0.5 + energyVal * 0.5);

  // === WAVE FIELD IRIDESCENCE ===
  float waveBlend = (waveField * 0.5 + 0.5);
  vec3 waveTint = 0.5 + 0.5 * cos(TAU * (waveBlend * 1.5 + uPalette * 0.1 + vec3(0.1, 0.3, 0.6)));
  col = mix(col, col * waveTint, 0.3);

  // Second wave layer creates depth
  float wave2Blend = (waveField2 * 0.5 + 0.5);
  col += waveTint * wave2Blend * 0.05;

  // === AUDIO REACTIONS ===
  // Beat: tile flash
  col += baseCol * beatPulse * 0.2;

  // Kick: brief inversion
  col = mix(col, vec3(1.0) - col * 0.5, kickVal * 0.2);

  // Onset: color channel shift
  col = mix(col, col.gbr, onsetVal * 0.15);

  // BPM sync breathing
  col *= 0.93 + uBpmSin * 0.07;

  // Sparkle at tile vertices (treble) — more intense
  float sparkle = pow(max(0.0, 1.0 - edgeDist * 12.0), 10.0) * trebleVal * 1.5;
  col += sparkle * vec3(1.0, 0.95, 0.85) * 0.4;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uNotchCount;
uniform float uSweepRate;
uniform float uSweepDepth;
uniform float uFeedback;

vec3 phaserPalette(float t, float offset) {
  // Electric/neon palette
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 0.5);
  vec3 d = vec3(0.8 + offset, 0.9 + offset, 0.3);
  return a + b * cos(6.2832 * (c * t + d));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // Base signal: a rich pattern to phase through
  float r = length(p);
  float angle = atan(p.y, p.x);

  float baseSignal = 0.0;
  baseSignal += sin(p.x * 8.0 + time * 1.5) * 0.3;
  baseSignal += sin(p.y * 6.0 - time * 1.2) * 0.3;
  baseSignal += sin((p.x + p.y) * 5.0 + time * 0.8) * 0.2;
  baseSignal += sin(r * 10.0 - time * 2.0) * 0.2;

  // Sweeping LFO for the phaser
  float sweepLFO = sin(time * uSweepRate + bassVal * 2.0) * uSweepDepth;
  sweepLFO += sin(time * uSweepRate * 0.5 + 0.5) * uSweepDepth * 0.5;

  // Apply phaser notch stages
  float phasedSignal = baseSignal;
  float maxNotches = min(uNotchCount, 10.0);

  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= maxNotches) break;

    // Each notch is at a different frequency, swept by the LFO
    float notchFreq = 3.0 + i * 2.5 + sweepLFO * 5.0;
    notchFreq += midsVal * sin(i * 1.3) * 2.0;

    // The allpass filter effect (phase shift without amplitude change)
    // Simulated by mixing original with phase-shifted version
    float shifted = sin(p.x * notchFreq + p.y * (notchFreq * 0.7) + time * (1.0 + i * 0.2));

    // Constructive/destructive interference
    float interference = cos(baseSignal * 3.14159 - shifted * 3.14159 + i * 0.5);

    // Feedback: the phased signal feeds back
    float fb = uFeedback * 0.8;
    phasedSignal = mix(phasedSignal, phasedSignal + interference * 0.3, 1.0 / (1.0 + i * 0.2));

    // Feedback adds resonance
    phasedSignal += interference * fb * 0.1;
  }

  // The visual comb filter: interference bands across screen
  float combPattern = 0.0;
  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= maxNotches) break;
    float freq = 4.0 + i * 3.0 + sweepLFO * 8.0;
    float band = sin(p.x * freq * cos(angle * 0.3) + p.y * freq * sin(angle * 0.3) + time);

    // Constructive (bright) and destructive (dark) bands
    combPattern += band / (1.0 + i * 0.3);
  }
  combPattern /= maxNotches;

  // Combine phased signal with comb pattern
  float combined = phasedSignal * 0.5 + combPattern * 0.5;

  // Chaos: randomize the sweep
  combined += sin(combined * 5.0 + time * 3.0) * uChaos * 0.2;

  // Map to color
  float colorVal = combined * 0.5 + 0.5;
  vec3 color = phaserPalette(colorVal, uPalette * 0.1);

  // Sweep position indicator: bright band where the sweep currently is
  float sweepPos = sweepLFO * 0.3;
  float sweepBand = exp(-pow((p.y - sweepPos) * 3.0, 2.0)) * 0.3;
  color += vec3(sweepBand * 0.3, sweepBand * 0.5, sweepBand);

  // Notch visualization: dark bands at notch frequencies
  float notchVis = 0.0;
  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= maxNotches) break;
    float notchPos = (3.0 + i * 2.5 + sweepLFO * 5.0) * 0.02;
    notchVis += exp(-pow((p.x - notchPos + 0.5) * 20.0, 2.0));
  }
  color *= 1.0 - notchVis * 0.15;

  // Treble reactive shimmer
  color += vec3(trebleVal * 0.1) * sin(p.x * 30.0 + time * 8.0) * sin(p.y * 30.0 - time * 7.0);

  // Onset: brief phase reset flash
  color = mix(color, vec3(0.8, 0.9, 1.0), onsetVal * 0.15);

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat pulse
  color += vec3(uBeat * uSensitivity * 0.06);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.2));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPhoenixParam;
uniform float uBreathAmount;
uniform float uSparkDensity;
uniform float uHeatIntensity;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Fire color palette
vec3 fireColor(float t) {
  // Black -> dark red -> orange -> yellow -> white
  vec3 c;
  if (t < 0.25) {
    c = mix(vec3(0.0), vec3(0.5, 0.0, 0.0), t * 4.0);
  } else if (t < 0.5) {
    c = mix(vec3(0.5, 0.0, 0.0), vec3(1.0, 0.4, 0.0), (t - 0.25) * 4.0);
  } else if (t < 0.75) {
    c = mix(vec3(1.0, 0.4, 0.0), vec3(1.0, 0.8, 0.2), (t - 0.5) * 4.0);
  } else {
    c = mix(vec3(1.0, 0.8, 0.2), vec3(1.0, 1.0, 0.9), (t - 0.75) * 4.0);
  }
  return c;
}

// Blue fire palette
vec3 blueFire(float t) {
  vec3 c;
  if (t < 0.25) {
    c = mix(vec3(0.0), vec3(0.0, 0.0, 0.4), t * 4.0);
  } else if (t < 0.5) {
    c = mix(vec3(0.0, 0.0, 0.4), vec3(0.0, 0.3, 0.8), (t - 0.25) * 4.0);
  } else if (t < 0.75) {
    c = mix(vec3(0.0, 0.3, 0.8), vec3(0.3, 0.7, 1.0), (t - 0.5) * 4.0);
  } else {
    c = mix(vec3(0.3, 0.7, 1.0), vec3(0.9, 0.95, 1.0), (t - 0.75) * 4.0);
  }
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Breathing — the fractal breathes with the music
  float breath = 1.0 + uBpmSin * uBreathAmount * 0.15;
  p *= breath / (uZoom + 0.5);

  // Slight rotation
  float rot = time * 0.1 + uBpmSin2 * 0.05;
  float cr = cos(rot), sr = sin(rot);
  p = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

  // Center offset
  p += vec2(-0.5, 0.0);

  // === PHOENIX FRACTAL ===
  // z(n+1) = z(n)^2 + c + p * z(n-1)
  // Where p is the "phoenix parameter" (memory term)
  float phoenix = -0.5 + uPhoenixParam * 0.6 + sin(time * 0.1) * 0.05;
  phoenix += midsVal * 0.05; // Audio modulation

  vec2 c = p;
  vec2 z = vec2(0.0);
  vec2 zPrev = vec2(0.0);

  int maxIter = int(60.0 + trebleVal * 30.0);
  float i = 0.0;
  float minDist = 1e10;
  float avgReal = 0.0;

  for (int n = 0; n < 120; n++) {
    if (n >= maxIter) break;
    if (dot(z, z) > 100.0) break;

    // Phoenix iteration
    vec2 zNew = vec2(
      z.x * z.x - z.y * z.y + c.x + phoenix * zPrev.x,
      2.0 * z.x * z.y + c.y + phoenix * zPrev.y
    );

    zPrev = z;
    z = zNew;
    i = float(n);

    float d = length(z);
    minDist = min(minDist, d);
    avgReal += z.x;
  }
  avgReal /= (i + 1.0);

  // Smooth iteration
  float smoothI = i;
  if (dot(z, z) > 100.0) {
    smoothI = i - log2(log2(dot(z, z))) + 4.0;
  }

  vec3 col = vec3(0.0);

  float t = smoothI / float(maxIter);
  bool escaped = dot(z, z) > 100.0;

  if (!escaped) {
    // Inside set — deep ember glow
    float innerGlow = 1.0 - clamp(minDist * 0.5, 0.0, 1.0);
    col = vec3(0.3, 0.05, 0.0) * innerGlow * uHeatIntensity;
    col += vec3(0.1, 0.0, 0.0) * bassVal;
