  float sparks = 0.0;
  for (float si = 0.0; si < 12.0; si++) {
    float sparkSpeed = 1.0 + hash(vec2(si, 0.0)) * 2.0;
    float sparkX = (hash(vec2(si, 1.0)) - 0.5) * 2.0;
