  float haze = sin(hazeDist * 30.0 + time * 5.0) * 0.02 * bassVal;
  col.r += haze * uHeatIntensity;

  // Kick explosion flash
  col += kickVal * vec3(1.0, 0.6, 0.1) * 0.3;

  // Beat pulse
  col += uBeat * uSensitivity * vec3(0.1, 0.04, 0.0) * 0.5;

  col *= uIntensity;
