#define PI 3.14159265
#define TAU 6.28318530
#define RING_COUNT 12

float hash21(vec2 co) {
  return fract(sin(dot(co, vec2(127.1, 311.7))) * 43758.5453);
}

// Hexagonal grid distance
vec4 hexGrid(vec2 co) {
  // Hex grid math
  vec2 s = vec2(1.0, 1.7320508); // 1, sqrt(3)
  vec2 halfS = s * 0.5;

  vec4 hC = floor(vec4(co, co - halfS) / s.xyxy) + 0.5;
  vec4 h = vec4(co - hC.xy * s, co - (hC.zw + 0.5) * s);

  float d1 = dot(h.xy, h.xy);
  float d2 = dot(h.zw, h.zw);
  if (d1 < d2) {
    return vec4(h.xy, hC.xy);
  } else {
    return vec4(h.zw, hC.zw + 0.5);
  }
}

// Hex cell edge distance
float hexEdge(vec2 co, float scale) {
  vec4 hx = hexGrid(co * scale);
  vec2 cellPos = hx.xy;
  // Distance to hex edge (approximation using max of 3 axes)
  vec2 absCo = abs(cellPos);
  float hexDist = max(absCo.x, absCo.y * 0.5773 + absCo.x * 0.5);
  float cellRad = 1.0 / scale * 0.5;
  return cellRad - hexDist;
}

