float brainwaveOsc(float t, float freq) {
  // Theta: 4-8 Hz, Alpha: 8-12 Hz
  // Sine wave with soft envelope
  float osc = sin(t * freq * TAU);
  return osc * 0.5 + 0.5;
}

// Indigo/violet/white palette
vec3 entrainPalette(float t, float shift) {
  // Deep indigo base
  vec3 indigo = vec3(0.15, 0.08, 0.35);
  // Violet mid
  vec3 violet = vec3(0.45, 0.15, 0.6);
  // Pure white peak
  vec3 white = vec3(0.95, 0.92, 1.0);
  // Pale blue accent
  vec3 paleBlue = vec3(0.4, 0.5, 0.85);

  float phase = fract(t + shift);
  vec3 col;
  if (phase < 0.33) {
    col = mix(indigo, violet, phase * 3.0);
  } else if (phase < 0.66) {
    col = mix(violet, white, (phase - 0.33) * 3.0);
  } else {
    col = mix(white, paleBlue, (phase - 0.66) * 3.0);
  }
  return col;
}

