    else if (bandIdx < 3.0) bandVal = uSpectrum2;
    else if (bandIdx < 4.0) bandVal = uSpectrum3;
    else if (bandIdx < 5.0) bandVal = uSpectrum4;
    else if (bandIdx < 6.0) bandVal = uSpectrum5;
    else if (bandIdx < 7.0) bandVal = uSpectrum6;
