  // Bass: ring system pulses outward
  col += ringCol * bassVal * 0.15;

  // Beat: concentric flash
  float beatRing = smoothstep(0.03, 0.0, abs(rad - mod(time * 2.0, 2.0) * 0.5));
  col += vec3(0.7, 0.5, 0.95) * beatRing * beatPulse * 0.5;

  // Kick: white flash from center
  col += vec3(0.8, 0.75, 0.95) * kickVal * centerGlow * 2.0;

  // Onset: violet halo
  col += vec3(0.3, 0.1, 0.5) * onsetVal * smoothstep(1.0, 0.3, rad) * 0.3;

