// Hash for procedural noise
float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmNoise(vec2 p, int oct) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= oct) break;
    val += amp * noiseVal(p * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Leaf venation: distance to nearest vein using Voronoi
vec3 leafVenation(vec2 p, float time) {
  vec2 cell = floor(p);
  vec2 frac = fract(p);
  float minDist = 10.0;
  float secondDist = 10.0;
  vec2 nearestPoint = vec2(0.0);
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 pt = vec2(
        hashVal(cell + neighbor),
        hashVal(cell + neighbor + vec2(31.0, 17.0))
      );
      pt = 0.5 + 0.4 * sin(time * 0.3 + 6.2832 * pt);
      vec2 diff = neighbor + pt - frac;
      float dist = length(diff);
      if (dist < minDist) {
        secondDist = minDist;
        minDist = dist;
        nearestPoint = cell + neighbor + pt;
      } else if (dist < secondDist) {
        secondDist = dist;
      }
    }
  }
  float veinWidth = secondDist - minDist;
  return vec3(minDist, secondDist, veinWidth);
}

// Chloroplast cell pattern
float chloroplastCell(vec2 p, float time) {
  float cellular = leafVenation(p * 3.0, time).z;
  float membrane = smoothstep(0.02, 0.08, cellular);
  float inner = smoothstep(0.08, 0.25, cellular);
  float thylakoid = sin(cellular * 40.0 + time) * 0.5 + 0.5;
  return membrane * (0.3 + 0.7 * inner) + thylakoid * 0.15 * inner;
}

// Photon particle streaming
float photonStream(vec2 p, float time, float bassVal) {
  float photons = 0.0;
  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float xOff = hashVal(vec2(fi, 0.0)) * 6.0 - 3.0;
    float speed = 0.5 + hashVal(vec2(fi, 1.0)) * 1.5;
    float yPos = fract(-time * speed * 0.3 + hashVal(vec2(fi, 2.0)));
    vec2 photonPos = vec2(xOff, (1.0 - yPos) * 4.0 - 2.0);
    float dist = length(p - photonPos);
    float glow = (0.02 + 0.03 * bassVal) / (dist * dist + 0.01);
    photons += glow * (0.3 + 0.7 * bassVal);
  }
  return photons;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Domain warp for organic feel
  vec2 warpedP = p + vec2(
    fbmNoise(p * 1.5 + time * 0.1, 4) - 0.5,
    fbmNoise(p * 1.5 + time * 0.1 + vec2(5.0), 4) - 0.5
  ) * (0.3 + uChaos * 0.5);

  // Fractal leaf venation at multiple scales
  vec3 vein1 = leafVenation(warpedP * 2.0, time);
  vec3 vein2 = leafVenation(warpedP * 5.0 + vec2(10.0), time * 0.7);
  float veinPattern = smoothstep(0.15, 0.02, vein1.z) * 0.6 +
                      smoothstep(0.08, 0.01, vein2.z) * 0.4;

  // Chloroplast cells
  float cells = chloroplastCell(warpedP, time);

  // Photon particles
  float photons = photonStream(p, time, bassVal);

  // Cell glow when hit by photons
  float cellGlow = cells * (0.3 + photons * 0.5 + bassVal * 0.8);

  // Color palette: green/gold/emerald
  vec3 greenDeep = vec3(0.05, 0.3, 0.08);
  vec3 emerald = vec3(0.1, 0.7, 0.2);
  vec3 gold = vec3(0.85, 0.75, 0.2);
  vec3 white = vec3(1.0, 0.98, 0.9);
  float palShift = uPalette * 0.3;

  vec3 veinColor = mix(greenDeep, emerald, veinPattern + palShift);
  vec3 cellColor = mix(emerald, gold, cellGlow * 0.6 + midsVal * 0.3);
  vec3 photonColor = mix(gold, white, photons * 0.5);

  // Combine layers
  vec3 col = veinColor * (0.4 + veinPattern * 0.6);
  col += cellColor * cellGlow * 0.8;
  col += photonColor * photons * 0.15;

  // Kick flash: bright golden pulse
  col += gold * uKick * uSensitivity * 0.4;

  // Treble sparkle on veins
  col += vec3(0.3, 0.8, 0.2) * trebleVal * veinPattern * 0.3;

  // Onset triggers photosynthesis burst
  col += emerald * uOnset * uSensitivity * 0.5;

  // BPM breathing on cell brightness
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Spectral flux modulates saturation
  float fluxBoost = uSpectralFlux * uSensitivity * 0.3;
  col = mix(col, col * vec3(0.8, 1.2, 0.9), fluxBoost);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

