float fbmVal(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noiseVal(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Generate underlying pattern to be "sorted"
vec3 sourcePattern(vec2 p, float time) {
  float n1 = fbmVal(p * 2.0 + time * 0.3);
  float n2 = fbmVal(p * 3.0 - time * 0.2 + vec2(5.0, 3.0));
  float n3 = fbmVal(p * 1.5 + vec2(sin(time * 0.5) * 2.0, cos(time * 0.4) * 2.0));

  vec3 col;
  float hue = fract(n1 * 0.8 + n2 * 0.3 + time * 0.05);
  float sat = 0.7 + n3 * 0.3;
  float val = 0.3 + n1 * 0.7;

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  col = c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
