  float band = sin(p.y * 15.0 + time * 2.0) * 0.5 + 0.5;
  float trigger = smoothstep(0.3, 0.7, band);
  // Onset creates new sort bands
  float onsetBand = sin(p.y * 30.0 + onsetVal * 20.0) * 0.5 + 0.5;
  trigger = max(trigger, onsetBand * onsetVal);
  trigger *= 0.5 + chaosVal * 0.5;
