  chromaCol.r = sourcePattern(sortedP + vec2(chromaShift, 0.0), time).r;
  chromaCol.g = sortedCol.g;
  chromaCol.b = sourcePattern(sortedP - vec2(chromaShift, 0.0), time).b;
