  if (i < 6.0) return vec3(0.0, 0.67, 0.67);        // teal
  if (i < 7.0) return vec3(0.67, 0.33, 0.0);        // brown/orange
  if (i < 8.0) return vec3(0.67, 0.67, 0.67);       // light gray
  if (i < 9.0) return vec3(0.33, 0.33, 0.33);       // dark gray
  if (i < 10.0) return vec3(0.33, 0.33, 1.0);       // blue
