  float colorIdx = 0.0;

  // Pattern 1: Concentric rings
  float rings = sin(length(displaced - 0.5) * 20.0 * uZoom - time * 3.0 + bassVal * 5.0);
  // Pattern 2: Diagonal stripes
  float stripes = sin((displaced.x + displaced.y) * 15.0 * uZoom - time * 2.0);
  // Pattern 3: Checkerboard
  float check = mod(floor(displaced.x * 10.0 * uZoom) + floor(displaced.y * 10.0 * uZoom + time), 2.0);
  // Pattern 4: Spiral
  float angle = atan(displaced.y - 0.5, displaced.x - 0.5);
  float spiral = sin(angle * 4.0 + length(displaced - 0.5) * 15.0 * uZoom - time * 3.0);

  // Mix patterns based on phase
  pattern = mix(rings, stripes, smoothstep(0.8, 1.2, patternType));
  pattern = mix(pattern, check * 2.0 - 1.0, smoothstep(1.8, 2.2, patternType));
  pattern = mix(pattern, spiral, smoothstep(2.8, 3.2, patternType));

  // Map pattern to color index
  colorIdx = floor((pattern * 0.5 + 0.5) * 8.0 + time * 2.0 + uPalette * 4.0);

  // Audio-reactive color cycling
  colorIdx += floor(bassVal * 4.0);
  colorIdx += floor(energyVal * 3.0);

  // Spectrum visualization overlay
  float specBar = 0.0;
  float colNorm = pixelUV.x;
  float specBand = floor(colNorm * 8.0);
  float specH = 0.0;
  if (specBand < 1.0) specH = uSpectrum0;
  else if (specBand < 2.0) specH = uSpectrum1;
  else if (specBand < 3.0) specH = uSpectrum2;
  else if (specBand < 4.0) specH = uSpectrum3;
  else if (specBand < 5.0) specH = uSpectrum4;
  else if (specBand < 6.0) specH = uSpectrum5;
  else if (specBand < 7.0) specH = uSpectrum6;
  else specH = uSpectrum7;
  specBar = step(pixelUV.y, specH * 0.5 * uSensitivity) * 0.5;

  colorIdx += specBar * 4.0;

  // Get palette color
  vec3 col = nesPalette(colorIdx);

  // Quantize colors to retro depth
  float levels = 2.0 + uColorDepth * 6.0;
  col = floor(col * levels) / levels;

  // Wipe transition overlay
  float wipePhase = fract(time * 0.1);
  float wipe = 0.0;
  if (uWipeStyle < 0.33) {
    // Horizontal wipe
    wipe = step(wipePhase, pixelUV.x) * step(pixelUV.x, wipePhase + 0.02);
  } else if (uWipeStyle < 0.66) {
    // Radial wipe
    float wipeAngle = atan(pixelUV.y - 0.5, pixelUV.x - 0.5) / 6.2832 + 0.5;
    wipe = step(abs(wipeAngle - wipePhase), 0.01);
  } else {
    // Diamond wipe
    float diamond = abs(pixelUV.x - 0.5) + abs(pixelUV.y - 0.5);
    wipe = step(abs(diamond - wipePhase), 0.02);
  }
  col += wipe * vec3(1.0) * 0.5;

  // Pixel grid lines
  vec2 pixFract = fract(p / pixSize);
  float pixBorder = step(pixFract.x, 0.05) + step(pixFract.y, 0.05);
  col *= 1.0 - pixBorder * 0.2;

  // Beat flash
  col += uBeat * uSensitivity * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTemperature;
uniform float uContainmentStrength;
uniform float uFieldVisibility;

#define PI 3.14159265
#define TAU 6.28318530

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

// Temperature to plasma color
vec3 plasmaColor(float temp) {
  // cool → red → orange → yellow → white
  vec3 c;
  if (temp < 0.25) c = mix(vec3(0.1, 0.0, 0.3), vec3(0.8, 0.1, 0.0), temp * 4.0);
  else if (temp < 0.5) c = mix(vec3(0.8, 0.1, 0.0), vec3(1.0, 0.5, 0.0), (temp - 0.25) * 4.0);
  else if (temp < 0.75) c = mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 0.9, 0.3), (temp - 0.5) * 4.0);
  else c = mix(vec3(1.0, 0.9, 0.3), vec3(1.0, 1.0, 0.95), (temp - 0.75) * 4.0);
  return c;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom * 0.5;

  vec3 col = vec3(0.01, 0.01, 0.03);

  // Toroidal containment shape
  float majorR = 0.7;
  float minorR = 0.4 + uContainmentStrength * 0.15;
  float angle = atan(p.y, p.x);
  float dist = length(p);
  float torusDist = length(vec2(dist - majorR, 0.0)) - minorR;

  // Bass disrupts containment - plasma leaks
  float disruption = bassVal * 0.1 * (1.0 - uContainmentStrength);
  minorR += disruption;

  // Inside containment field
  float containment = smoothstep(minorR + 0.05, minorR - 0.05, abs(dist - majorR));

  // Plasma flow along toroidal field lines
  float flowAngle = angle * 3.0 + time * 2.0;
  float poloidalAngle = atan(p.y, dist - majorR);

  // Plasma swirl pattern
  float plasma = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float freq = 2.0 + fi * 1.5;
    float phase = fi * 1.618;

    float swirl = sin(flowAngle * freq + poloidalAngle * (2.0 + fi) + time * (1.0 + fi * 0.3) + phase);
    swirl += fbm(vec2(flowAngle + time * 0.3, poloidalAngle + fi) * 2.0) * 0.5;

    // Spectrum bands drive different swirl patterns
    float specIdx = mod(fi * 2.0, 8.0);
    float specVal = 0.0;
    if (specIdx < 1.0) specVal = uSpectrum0;
    else if (specIdx < 2.0) specVal = uSpectrum1;
    else if (specIdx < 3.0) specVal = uSpectrum2;
    else if (specIdx < 4.0) specVal = uSpectrum3;
    else if (specIdx < 5.0) specVal = uSpectrum4;
    else if (specIdx < 6.0) specVal = uSpectrum5;
    else if (specIdx < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    plasma += swirl * (0.3 + specVal * uSensitivity * 0.4) / (1.0 + fi * 0.3);
  }

  plasma = 0.5 + 0.5 * plasma;

  // Temperature driven by energy + uniform
  float temp = uTemperature + uEnergy * uSensitivity * 0.3;
  temp += plasma * 0.2;
  temp = clamp(temp, 0.0, 1.0);

  vec3 plasmaCol = plasmaColor(temp);
  plasmaCol *= 0.5 + plasma * 0.5;

  // Apply to containment region
  col += plasmaCol * containment * 0.8;

  // Plasma instabilities on beats
  float instability = noise(vec2(angle * 5.0, time * 3.0)) * uBeat * uSensitivity * 1.5;
  col += plasmaCol * instability * containment * 0.3;

  // Magnetic field lines
  if (uFieldVisibility > 0.1) {
    // Toroidal field lines (circles around major axis)
    float toroidalLine = abs(sin(angle * 8.0 + time * 0.1));
    toroidalLine = smoothstep(0.02, 0.0, 1.0 - toroidalLine);

    // Poloidal field lines (loops through hole)
    float poloidalLine = abs(sin(poloidalAngle * 6.0 + time * 0.05));
    poloidalLine = smoothstep(0.02, 0.0, 1.0 - poloidalLine);

    vec3 fieldCol = vec3(0.1, 0.2, 0.4);
    float fieldMask = max(toroidalLine, poloidalLine) * uFieldVisibility * 0.3;
    col += fieldCol * fieldMask * (0.3 + midsVal * 0.3);
  }

  // Kick: containment breach flash
  float breachFlash = uKick * uSensitivity * 0.7;
  col += plasmaCol * breachFlash * exp(-abs(torusDist) * 5.0);

  // Onset sparks
  float spark = hash(floor(p * 20.0 + time * 10.0)) * uOnset * uSensitivity * containment;
  col += vec3(1.0, 0.9, 0.7) * spark * 0.3;

  // Ambient plasma glow
  float ambientGlow = exp(-torusDist * torusDist * 8.0) * 0.1;
  col += plasmaCol * ambientGlow * 0.3;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFilamentCount;
uniform float uBranchDepth;
uniform float uGlassReflection;

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Noise for filament displacement
float filamentNoise(float t, float seed, float time) {
  float n = 0.0;
  n += (hash11(t * 7.3 + seed + floor(time * 3.0) * 0.1) - 0.5) * 0.15;
  n += (hash11(t * 15.1 + seed * 3.0 + floor(time * 5.0) * 0.1) - 0.5) * 0.08;
  n += (hash11(t * 31.7 + seed * 7.0 + floor(time * 8.0) * 0.1) - 0.5) * 0.04;
  return n;
}

// Compute single filament contribution at point p
// Returns glow intensity
float filament(vec2 p, float targetAngle, float seed, float time, float thickness, float branchDetail) {
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Filament follows a noisy radial path toward targetAngle
  float t = r; // parameter along filament (0 = center, 1 = edge)

  // Angular displacement from noise
  float noiseDisp = filamentNoise(t, seed, time) * (1.0 + branchDetail * 0.5);
  noiseDisp += sin(t * 10.0 + time * 3.0 + seed) * 0.03;

  // Filament centerline angle at this radius
  float filAngle = targetAngle + noiseDisp;

  // Angular distance to filament
  float angleDist = abs(angle - filAngle);
  // Wrap around
  angleDist = min(angleDist, 6.2832 - angleDist);

  // Width decreases toward center, increases with thickness param
  float width = thickness * (0.02 + r * 0.03);

  // Core: bright narrow line
  float core = exp(-angleDist * angleDist / (width * width * 0.3)) * smoothstep(0.0, 0.05, r);

  // Glow: softer wider falloff
  float glow = exp(-angleDist / (width * 2.0)) * 0.3 * smoothstep(0.0, 0.1, r);

  // Fade at sphere edge
  float edgeFade = smoothstep(1.0, 0.8, r);
  // Brighten near sphere edge (plasma concentrates)
  float edgeBright = smoothstep(0.3, 0.9, r) * 0.5 + 0.5;

  return (core + glow) * edgeFade * edgeBright;
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  float time = uTime * (uSpeed * 3.0);
  vec2 center = (vUv - 0.5) * (uZoom * 1.5 + 1.5);

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity * 1.3;
  float onsetVal = uOnset * uSensitivity * 1.5;
  float kickVal = uKick * uSensitivity * 1.4;
  float energyVal = uEnergy * uSensitivity;

  float r = length(center);

  // Glass sphere mask — enlarged to fill screen
  float sphereR = 1.2;
  float inSphere = smoothstep(sphereR + 0.02, sphereR - 0.02, r);

  // Number of filaments: 4 to 12
  float numFil = floor(4.0 + uFilamentCount * 8.0);
  float thickness = 1.0 + bassVal * 1.5;
  float branchDetail = uBranchDepth * 2.0 + trebleVal * 1.5;

  // Attractor angles driven by spectrum bands
  float attract0 = sin(time * 0.5) * 3.14 + uSpectrum0 * uSensitivity * 2.0;
  float attract1 = cos(time * 0.4) * 3.14 + uSpectrum1 * uSensitivity * 2.0;
  float attract2 = sin(time * 0.6 + 2.0) * 3.14 + uSpectrum2 * uSensitivity * 1.5;
  float attract3 = cos(time * 0.35 + 4.0) * 3.14 + uSpectrum3 * uSensitivity * 1.5;
  float attract4 = sin(time * 0.45 + 1.0) * 3.14 + uSpectrum4 * uSensitivity * 1.0;
  float attract5 = cos(time * 0.55 + 3.0) * 3.14 + uSpectrum5 * uSensitivity * 1.0;
  float attract6 = sin(time * 0.3 + 5.0) * 3.14 + uSpectrum6 * uSensitivity * 0.8;
  float attract7 = cos(time * 0.5 + 6.0) * 3.14 + uSpectrum7 * uSensitivity * 0.8;

  // Beat spawns new random positions
  float beatJitter = beatPulse * 1.5;

  // Accumulate filament glow
  float totalGlow = 0.0;

  // Filament 0
  totalGlow += filament(center, attract0 + beatJitter * 0.3, 1.0, time, thickness, branchDetail);
  // Filament 1
  totalGlow += filament(center, attract1 - beatJitter * 0.2, 2.0, time, thickness, branchDetail);
  // Filament 2
  totalGlow += filament(center, attract2 + beatJitter * 0.4, 3.0, time, thickness, branchDetail);
  // Filament 3
  totalGlow += filament(center, attract3, 4.0, time, thickness, branchDetail);
  // Filament 4 (conditional)
  float w4 = smoothstep(4.5, 5.5, numFil);
  totalGlow += filament(center, attract4 + beatJitter * 0.1, 5.0, time, thickness, branchDetail) * w4;
  // Filament 5
  float w5 = smoothstep(5.5, 6.5, numFil);
  totalGlow += filament(center, attract5 - beatJitter * 0.3, 6.0, time, thickness, branchDetail) * w5;
  // Filament 6
  float w6 = smoothstep(6.5, 7.5, numFil);
  totalGlow += filament(center, attract6, 7.0, time, thickness, branchDetail) * w6;
  // Filament 7
  float w7 = smoothstep(7.5, 8.5, numFil);
  totalGlow += filament(center, attract7 + beatJitter * 0.2, 8.0, time, thickness, branchDetail) * w7;

  // Extra filaments from chaos
  float w8 = smoothstep(8.5, 9.5, numFil) * uChaos;
  totalGlow += filament(center, attract0 + 3.14 + sin(time * 0.7) * 0.5, 9.0, time, thickness * 0.7, branchDetail) * w8;
  float w9 = smoothstep(9.5, 10.5, numFil) * uChaos;
  totalGlow += filament(center, attract2 - 1.57 + cos(time * 0.6) * 0.5, 10.0, time, thickness * 0.6, branchDetail) * w9;

  // Central core glow
  float coreGlow = exp(-r * r * 20.0) * (0.5 + bassVal * 0.5 + kickVal * 0.8);
  totalGlow += coreGlow;

  // Plasma color: purple-blue core, pink-white at bright spots
  float hueShift = uPalette * 0.15;
  vec3 plasmaCol = vec3(0.4 + hueShift, 0.1, 0.8);
  vec3 brightCol = vec3(0.9 + hueShift * 0.3, 0.5, 1.0);
  vec3 whiteHot = vec3(1.0, 0.9, 1.0);

  vec3 col = mix(plasmaCol, brightCol, smoothstep(0.2, 0.8, totalGlow));
  col = mix(col, whiteHot, smoothstep(0.8, 1.5, totalGlow));
  col *= totalGlow;

  // Apply sphere mask
  col *= inSphere;

  // Glass sphere effects
  // Rim highlight (Fresnel)
  float rim = pow(smoothstep(sphereR - 0.3, sphereR, r), 2.0) * uGlassReflection;
  vec3 rimCol = vec3(0.3, 0.3, 0.4) * rim * inSphere;
  col += rimCol;

  // Glass edge line
  float edge = smoothstep(sphereR + 0.02, sphereR, r) * smoothstep(sphereR - 0.04, sphereR, r);
  col += vec3(0.15, 0.15, 0.2) * edge * uGlassReflection;

  // Specular highlight on glass
  vec2 specPos = vec2(-0.25, 0.3);
  float specDist = length(center - specPos);
  float spec = exp(-specDist * specDist * 8.0) * uGlassReflection * 0.5 * inSphere;
  col += vec3(spec);

  // Beat brightness
  col += col * beatPulse * 0.3;

  // Onset flash
  col += vec3(onsetVal * 0.15) * inSphere;

  // Energy
  col *= 1.0 + energyVal * 0.2;

  // Background outside sphere — subtle plasma glow extends beyond glass
  float outerGlow = exp(-max(r - sphereR, 0.0) * 4.0) * totalGlow * 0.15;
  vec3 bgCol = vec3(0.01, 0.01, 0.015) + vec3(0.2, 0.05, 0.4) * outerGlow;
  col = mix(bgCol, col, inSphere);

  float brightness = uIntensity * 1.7;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmVal(vec2 p, int oct) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= oct) break;
    val += amp * noiseVal(p * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Plasma density function with vortex
float plasmaDensity(vec2 p, float time, float bassVal) {
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Vortex rotation
  float vortex = angle + time * 0.5 + sin(r * 3.0 - time) * 0.5;
  vec2 vortexP = vec2(cos(vortex), sin(vortex)) * r;

  // Multi-layer plasma
  float plasma = 0.0;
  plasma += sin(vortexP.x * 3.0 + time * 1.5) * 0.5 + 0.5;
  plasma += sin(vortexP.y * 2.5 - time * 1.2) * 0.5 + 0.5;
  plasma += sin((vortexP.x + vortexP.y) * 2.0 + time * 0.8) * 0.5 + 0.5;
  plasma += sin(r * 5.0 - time * 2.0) * 0.5 + 0.5;
  plasma *= 0.25;

  // Bass intensifies density
  plasma = pow(plasma, 1.0 - bassVal * 0.4);
  return plasma;
}

// Magnetic field lines
float fieldLines(vec2 p, float time) {
  // Two magnetic poles
  vec2 pole1 = vec2(sin(time * 0.3) * 0.8, cos(time * 0.4) * 0.5);
  vec2 pole2 = vec2(-sin(time * 0.35) * 0.7, -cos(time * 0.45) * 0.6);

  vec2 d1 = p - pole1;
  vec2 d2 = p - pole2;
  float r1 = length(d1);
  float r2 = length(d2);

  float angle1 = atan(d1.y, d1.x);
  float angle2 = atan(d2.y, d2.x);

  float field = sin(angle1 * 5.0 - angle2 * 5.0 + time) * 0.5 + 0.5;
  field *= smoothstep(0.0, 0.3, r1) * smoothstep(0.0, 0.3, r2);
  return field;
}

// Lightning arc between points
float lightningArc(vec2 p, vec2 arcStart, vec2 arcEnd, float time, float chaosVal) {
  vec2 dir = arcEnd - arcStart;
  float dirLen = length(dir);
  vec2 norm = normalize(dir);
  vec2 perp = vec2(-norm.y, norm.x);

  vec2 rel = p - arcStart;
  float along = dot(rel, norm) / dirLen;
  float across = dot(rel, perp);

  if (along < 0.0 || along > 1.0) return 0.0;

  // Jagged displacement
  float disp = 0.0;
  disp += noiseVal(vec2(along * 10.0, time * 15.0)) * 0.15;
  disp += noiseVal(vec2(along * 30.0, time * 25.0)) * 0.05;
  disp *= chaosVal + 0.5;

  float thickness = 0.01 + 0.02 * (1.0 - abs(along - 0.5) * 2.0);
  float arcDist = abs(across - disp);
  float arcGlow = thickness / (arcDist + 0.001);
  return clamp(arcGlow, 0.0, 3.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Plasma density
  float plasma = plasmaDensity(p, time, bassVal);

  // Domain warp the plasma
  vec2 warp = vec2(
    fbmVal(p + time * 0.2, 5),
    fbmVal(p + vec2(5.0) + time * 0.15, 5)
  ) * (0.5 + uChaos * 0.8);
  float warpedPlasma = plasmaDensity(p + warp, time, bassVal);

  // Magnetic field lines
  float field = fieldLines(p, time);

  // Color: blue core to red edges
  float r = length(p);
  vec3 coreColor = vec3(0.2, 0.4, 1.0);
  vec3 midColor = vec3(0.8, 0.2, 0.9);
  vec3 edgeColor = vec3(1.0, 0.3, 0.1);
  float palShift = uPalette * 0.2;

  vec3 plasmaColor = mix(coreColor, midColor, smoothstep(0.0, 0.7, r + palShift));
  plasmaColor = mix(plasmaColor, edgeColor, smoothstep(0.5, 1.5, r + palShift));

  vec3 col = plasmaColor * (warpedPlasma * 0.7 + plasma * 0.3);

  // Field lines overlay
  col += vec3(0.5, 0.7, 1.0) * field * 0.2;

  // Lightning arcs on onset
  vec2 pole1 = vec2(sin(time * 0.3) * 0.8, cos(time * 0.4) * 0.5);
  vec2 pole2 = vec2(-sin(time * 0.35) * 0.7, -cos(time * 0.45) * 0.6);
  float lightning = lightningArc(p, pole1, pole2, time, uChaos);
  float onsetVal = uOnset * uSensitivity * 1.5;
  col += vec3(0.7, 0.8, 1.0) * lightning * (0.1 + onsetVal * 0.9);

  // Additional arcs on kick
  vec2 pole3 = vec2(cos(time * 0.25) * 0.6, -sin(time * 0.3) * 0.7);
  float lightning2 = lightningArc(p, pole1, pole3, time * 1.3, uChaos);
  col += vec3(1.0, 0.6, 0.8) * lightning2 * uKick * uSensitivity * 0.8;

  // Central glow
  float coreGlow = exp(-r * r * 2.0);
  col += coreColor * coreGlow * (0.3 + bassVal * 0.5);

  // Treble sparkle
  float sparkle = noiseVal(p * 20.0 + time * 5.0);
  sparkle = pow(sparkle, 8.0) * trebleVal;
  col += vec3(1.0) * sparkle * 0.5;

  // BPM pulse
  col *= 1.0 + uBpmSin * 0.1 * uSensitivity;

  // Harmonicity modulates color warmth
  float warm = uHarmonicity * uSensitivity * 0.2;
  col = mix(col, col * vec3(1.2, 1.0, 0.8), warm);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
