__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Mobius transform in the Poincare disk
vec2 mobiusTranslate(vec2 z, vec2 a) {
  // (z + a) / (1 + conj(a) * z)
  // complex multiply: (x1+iy1)(x2+iy2) = (x1x2-y1y2) + i(x1y2+x2y1)
  vec2 conjA = vec2(a.x, -a.y);
  vec2 num = z + a;
  // 1 + conj(a)*z
  float denR = 1.0 + conjA.x * z.x - conjA.y * z.y;
  float denI = conjA.x * z.y + conjA.y * z.x;
  // complex division
  float denSq = denR * denR + denI * denI;
  return vec2(
    (num.x * denR + num.y * denI) / denSq,
    (num.y * denR - num.x * denI) / denSq
  );
}

// Hyperbolic distance from origin
float hyperbolicDist(vec2 z) {
  float r = length(z);
  r = clamp(r, 0.0, 0.999);
  return log((1.0 + r) / (1.0 - r));
}

// Tessellation: fold point into fundamental domain
vec3 tessellate(vec2 p, float time, float chaosVal) {
  float r = length(p);
  if (r >= 1.0) return vec3(0.0, 0.0, -1.0);

  float depth = 0.0;
  vec2 z = p;

  // Apply rotation
  float rotAngle = time * 0.1;
  mat2 rot = mat2(cos(rotAngle), -sin(rotAngle), sin(rotAngle), cos(rotAngle));
  z = rot * z;

  // Repeated Mobius inversions to find tiling cell
  for (int i = 0; i < 26; i++) {
    // Inversion across circles to create hyperbolic tiling
    float angle = atan(z.y, z.x);
    float sector = 3.14159 / 3.0; // 6-fold symmetry (p,q) = (3,7)
    angle = mod(angle + 3.14159, sector * 2.0) - sector;
    z = vec2(cos(angle), sin(angle)) * length(z);

    // Translate toward ideal vertices
    float tileR = 0.5 + chaosVal * 0.15;
    vec2 tileCenter = vec2(tileR, 0.0);

    if (length(z - tileCenter) < tileR * 0.8) {
      z = mobiusTranslate(z, -tileCenter * 0.5);
      depth += 1.0;
    } else {
      break;
    }
  }

  return vec3(z, depth);
}

// Psychedelic tile coloring
vec3 tileColor(float depth, float cellAngle, float cellR, float time, float palShift) {
  float hue = fract(depth * 0.12 + cellAngle * 0.5 / 3.14159 + time * 0.08 + palShift + sin(time * 0.3) * 0.15);
  float sat = 0.6 + 0.4 * sin(depth * 0.5 + time);
  float val = 0.3 + 0.6 * exp(-depth * 0.15);

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;

  // Scale to unit disk
  vec2 diskP = p * 0.45;

  // Audio warps the geometry
  float warpAngle = atan(diskP.y, diskP.x);
  float warpR = length(diskP);
  warpR *= 1.0 + bassVal * 0.15 * sin(warpAngle * 3.0 + time);
  diskP = vec2(cos(warpAngle), sin(warpAngle)) * warpR;

  float r = length(diskP);

  // Outside disk: dark border with glow
  if (r >= 1.0) {
    float borderGlow = exp(-(r - 1.0) * 10.0);
    vec3 glowCol = vec3(0.3, 0.1, 0.5) * borderGlow;
    glowCol *= uIntensity;
    gl_FragColor = vec4(clamp(glowCol, 0.0, 1.0), 1.0);
    return;
  }

  // Tessellate the hyperbolic space
  vec3 tessResult = tessellate(diskP, time, uChaos);
  vec2 cellZ = tessResult.xy;
  float depth = tessResult.z;

  // Cell properties
  float cellAngle = atan(cellZ.y, cellZ.x);
  float cellR = length(cellZ);

  // Tile colors by depth
  float palShift = uPalette * 0.3;
  vec3 col = tileColor(depth, cellAngle, cellR, time, palShift);

  // Tile edges
  float edgeFactor = smoothstep(0.0, 0.05, cellR) * smoothstep(0.5, 0.45, cellR);
  vec3 edgeCol = vec3(1.0, 0.9, 0.8) * 0.5;
  col = mix(edgeCol, col, edgeFactor);

  // Hyperbolic distance shading - tiles fade toward boundary
  float hDist = hyperbolicDist(diskP);
  col *= exp(-hDist * 0.1);

  // Central mandala glow
  float centerGlow = exp(-r * r * 5.0);
  col += vec3(0.5, 0.3, 0.8) * centerGlow * 0.3;

  // Beat triggers color shift across all tiles
  float beatShift = uBeat * uSensitivity * 0.5;
  col = mix(col, col.gbr, beatShift);

  // Kick pulses the disk inward
  col *= 1.0 + uKick * uSensitivity * 0.3 * (1.0 - r);

  // Onset flash at deep tiles
  col += vec3(1.0, 0.8, 0.5) * uOnset * uSensitivity * 0.3 * smoothstep(3.0, 8.0, depth);

  // Treble sparkle on edges
  col += vec3(0.8, 0.9, 1.0) * trebleVal * (1.0 - edgeFactor) * 0.5;

  // Spectral centroid shifts hue temperature
  float centroidShift = uSpectralCentroid * uSensitivity;
  col = mix(col, col * vec3(1.0, 0.8, 1.2), centroidShift * 0.2);

  // BPM rotation pulse
  col *= 1.0 + uBpmSin * 0.08 * uSensitivity;

  // Disk boundary glow
  float boundaryGlow = smoothstep(0.85, 1.0, r);
  col += vec3(0.4, 0.2, 0.7) * boundaryGlow * 0.5 * (1.0 + bassVal);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
