__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridDensity;
uniform float uSurpriseStrength;
uniform float uViolationType;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Hexagonal grid
vec4 hexGrid(vec2 p) {
  vec2 s = vec2(1.0, 1.732);
  vec2 h = s * 0.5;
  vec2 a = mod(p, s) - h;
  vec2 b = mod(p - h, s) - h;
  vec2 g;
  if (dot(a, a) < dot(b, b)) {
    g = a;
  } else {
    g = b;
  }
  float edgeDist = 0.5 - max(abs(g.x), abs(g.y * 0.577 + abs(g.x) * 0.5));
  vec2 cellId = p - g;
  return vec4(g.x, g.y, edgeDist, hash(cellId));
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  // Golden ratio surprise gate
  float beatCount = floor(time * uBpm / 60.0);
  float surpriseGate = step(1.0 - uChaos * 0.3, fract(beatCount * 0.618033));
  float surprise = surpriseGate * onsetVal * uSurpriseStrength;

  // Grid scale
  float gridScale = 4.0 + uGridDensity * 8.0;

  // Predictable rotation (slow, steady)
  float predictableRot = time * 0.2;
  // Surprise rotation (sudden 60/90/180 degree snaps)
  float snapAngle = floor(hash(vec2(beatCount, 0.0)) * 3.0) * 1.0472; // 60 degrees
  float violationRot = surprise * snapAngle * uSurpriseStrength;

  float rot = predictableRot + violationRot;
  float cs = cos(rot), sn = sin(rot);
  p = mat2(cs, -sn, sn, cs) * p;

  // Scale with zoom and bass
  p *= gridScale * (1.0 + uZoom) * (1.0 - bassVal * 0.1);

  // Hexagonal grid
  vec4 hex = hexGrid(p);
  float edge = hex.z;
  float cellHash = hex.w;

  // Predictable cell coloring: smooth cycling
  float cellHue = cellHash * 0.3 + time * 0.05 + uPalette * 0.3;
  vec3 predictColor = 0.5 + 0.5 * cos(6.2832 * (cellHue + vec3(0.0, 0.33, 0.67)));

  // Fill cells with pulsing pattern
  float cellPulse = sin(cellHash * 20.0 + time * 2.0) * 0.5 + 0.5;
  float cellFill = smoothstep(0.05, 0.15, edge) * (0.3 + cellPulse * 0.7);

  // === SURPRISE VIOLATIONS ===
  vec3 surpriseColor = predictColor;
  float surpriseFill = cellFill;

  // Violation type 1: Color inversion
  float v1 = step(uViolationType, 0.33);
  surpriseColor = mix(surpriseColor, 1.0 - surpriseColor, surprise * v1);

  // Violation type 2: Negative space swap (fill <-> edge)
  float v2 = step(0.33, uViolationType) * step(uViolationType, 0.67);
  surpriseFill = mix(surpriseFill, 1.0 - surpriseFill, surprise * v2);

  // Violation type 3: Channel rotation (RGB shift)
  float v3 = step(0.67, uViolationType);
  surpriseColor = mix(surpriseColor, surpriseColor.gbr, surprise * v3);

  // All violations: brightness flash
  surpriseColor += surprise * 0.4;

  // Edge glow (predictable)
  float edgeGlow = smoothstep(0.08, 0.0, edge);
  vec3 edgeColor = vec3(0.6, 0.8, 1.0) + trebleVal * vec3(0.4, 0.2, 0.0);

  // Combine
  vec3 col = surpriseColor * surpriseFill + edgeColor * edgeGlow;

  // Beat pulse on grid edges
  col += edgeGlow * uBpmSin * 0.3 * vec3(0.3, 0.5, 1.0);

  // Spectral flux jitter
  col += fluxVal * 0.1 * vec3(hash(p + time), hash(p + time + 100.0), hash(p + time + 200.0));

  // Mids drive mid-range color warmth
  col.r += midsVal * 0.08;

  // Energy overall brightness
  col *= 1.0 + uEnergy * uSensitivity * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

