__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uDispersion;
uniform float uBeamWidth;
uniform float uRefractAngle;
uniform float uRainbowSpread;

void main() {
  // Full-screen coordinates: no viewport centering constraint
  vec2 p = vUv * 2.0 - 1.0;
  p = psychedelicUV(p); // breathing morph
  // Apply zoom as a scale on the full-screen space
  p *= (uZoom * 2.0 + 0.5);
  float time = uTime * (uSpeed * 2.0);

  // Audio-reactive modulators
  float bassDisperse = bass() * uSensitivity * 0.6;
  float midsRotate = mids() * uSensitivity * 0.8;
  float energyBright = uEnergy * uSensitivity;
  float onsetFlash = uOnset * uSensitivity * 2.0;

  // Prism rotation angle: base angle + mids rotation + time drift
  float angle = uRefractAngle + midsRotate * 3.14159 + time * 0.1;

  // Rotate coordinates around center
  float cosA = cos(angle);
  float sinA = sin(angle);
  float rx = p.x * cosA - p.y * sinA;
  float ry = p.x * sinA + p.y * cosA;

  // === MULTIPLE LIGHT BEAMS (fill the screen with prismatic rays) ===
  // Beam width scaled to fill screen; wider profile, no hard falloff
  float beamW = uBeamWidth + 0.3;

  // Primary beam
  float beamProfile0 = smoothstep(beamW + 0.15, 0.0, abs(ry));
  // Secondary beams at offsets for full-screen coverage
  float beamProfile1 = smoothstep(beamW + 0.1, 0.0, abs(ry - 0.6 - sin(time * 0.3) * 0.15)) * 0.7;
  float beamProfile2 = smoothstep(beamW + 0.1, 0.0, abs(ry + 0.6 + cos(time * 0.25) * 0.15)) * 0.7;
  float beamProfile3 = smoothstep(beamW + 0.08, 0.0, abs(ry - 1.2 - sin(time * 0.2 + 1.0) * 0.1)) * 0.45;
  float beamProfile4 = smoothstep(beamW + 0.08, 0.0, abs(ry + 1.2 + cos(time * 0.22 + 2.0) * 0.1)) * 0.45;

  // Combine beams -- no edge falloff so light extends to screen edges
  float beam = beamProfile0 + beamProfile1 + beamProfile2 + beamProfile3 + beamProfile4;
  beam = clamp(beam, 0.0, 1.5);

  // Soft radial vignette instead of hard falloff (keeps edges visible)
  float radialDist = length(p) * 0.3;
  float vignette = 1.0 - smoothstep(1.5, 3.5, radialDist);
  beam *= mix(0.5, 1.0, vignette);

  // === CHROMATIC DISPERSION ===
  float totalDispersion = uDispersion * 0.2 + bassDisperse * 0.12 + onsetFlash * 0.1;
  float spreadAmount = uRainbowSpread * totalDispersion;

  // Red channel
  float ryR = ry - spreadAmount * 1.0;
  float beamR = smoothstep(beamW + 0.15, 0.0, abs(ryR))
    + smoothstep(beamW + 0.1, 0.0, abs(ryR - 0.6)) * 0.7
    + smoothstep(beamW + 0.1, 0.0, abs(ryR + 0.6)) * 0.7
    + smoothstep(beamW + 0.08, 0.0, abs(ryR - 1.2)) * 0.45
    + smoothstep(beamW + 0.08, 0.0, abs(ryR + 1.2)) * 0.45;

  // Green channel (center)
  float ryG = ry;
  float beamG = beam;

  // Blue channel
  float ryB = ry + spreadAmount * 1.0;
  float beamB = smoothstep(beamW + 0.15, 0.0, abs(ryB))
    + smoothstep(beamW + 0.1, 0.0, abs(ryB - 0.6)) * 0.7
    + smoothstep(beamW + 0.1, 0.0, abs(ryB + 0.6)) * 0.7
    + smoothstep(beamW + 0.08, 0.0, abs(ryB - 1.2)) * 0.45
    + smoothstep(beamW + 0.08, 0.0, abs(ryB + 1.2)) * 0.45;

  // === SPECTRAL RAINBOW BANDS (full-screen) ===
  float specPos = ry * (uRainbowSpread * 3.0 + 1.0);
  float specHue = fract(specPos * 0.5 + 0.5 + uPalette * 0.1 + time * 0.02);

  float specR = abs(fract(specHue + 1.0) * 6.0 - 3.0) - 1.0;
  float specG = abs(fract(specHue + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float specB = abs(fract(specHue + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;

  float specColR = clamp(specR, 0.0, 1.0);
  float specColG = clamp(specG, 0.0, 1.0);
  float specColB = clamp(specB, 0.0, 1.0);

  float specIntensity = beam * (totalDispersion * 5.0);

  // === INTERFERENCE / CAUSTIC PATTERNS (edge-to-edge) ===
  float caustic1 = sin(rx * 6.0 + time * 1.2 + ry * 10.0) * 0.5 + 0.5;
  float caustic2 = sin(rx * 10.0 - time * 0.8 + ry * 6.0) * 0.5 + 0.5;
  float caustic3 = sin(rx * 3.0 + time * 0.5 - ry * 4.0) * 0.5 + 0.5;
  float causticPattern = caustic1 * caustic2 + caustic3 * 0.3;
  float causticEffect = causticPattern * (uChaos * 0.5 + 0.15);

  // === REFRACTION RAYS (full-screen light rays) ===
  float rayAngle = atan(p.y, p.x);
  float rayR = length(p);
  float rays = sin(rayAngle * 8.0 + time * 0.5 + bassDisperse * 3.0) * 0.5 + 0.5;
  rays *= smoothstep(0.0, 0.3, rayR);
  float rayEffect = rays * 0.2 * (1.0 + energyBright * 0.5);

  // === COMBINE ===
  float brightness = uIntensity * 1.5 + energyBright * 0.5;

  float colorR = beamR * brightness + specColR * specIntensity * brightness + causticEffect * 0.3 + rayEffect * 0.8;
  float colorG = beamG * brightness + specColG * specIntensity * brightness + causticEffect * 0.3 + rayEffect * 0.5;
  float colorB = beamB * brightness + specColB * specIntensity * brightness + causticEffect * 0.3 + rayEffect * 1.0;

  // Onset flash: white burst across the whole screen
  float flashAmount = onsetFlash * 0.4;

  float finalR = colorR + flashAmount;
  float finalG = colorG + flashAmount;
  float finalB = colorB + flashAmount;

  // Beat pulse: overall brightness kick (not constrained to beam area)
  float beatPulse = uBeat * uSensitivity * 0.12;

  // Ambient prismatic fill to prevent dead black areas
  float ambientR = 0.02 + causticEffect * 0.1 + specColR * 0.03;
  float ambientG = 0.01 + causticEffect * 0.08 + specColG * 0.03;
  float ambientB = 0.03 + causticEffect * 0.12 + specColB * 0.03;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR + beatPulse + ambientR, 0.0, 1.0),
    clamp(finalG + beatPulse + ambientG, 0.0, 1.0),
    clamp(finalB + beatPulse + ambientB, 0.0, 1.0),
    1.0
  );
}

