uniform float uIntensity;
uniform float uChaos;

uniform float uSplitAngle;
uniform float uBeamFocus;
uniform float uSpectrumWidth;
uniform float uCausticStrength;

// Physical wavelength (380-780nm normalized to 0-1) to RGB
// More accurate than simple HSV for prism/rainbow simulation
vec3 wavelengthToRGB(float t) {
  // t=0 -> violet (380nm), t=1 -> red (780nm)
  float w = 380.0 + t * 400.0;
  vec3 color;
  if (w < 440.0) {
    color = vec3(-(w - 440.0) / 60.0, 0.0, 1.0);
  } else if (w < 490.0) {
    color = vec3(0.0, (w - 440.0) / 50.0, 1.0);
  } else if (w < 510.0) {
    color = vec3(0.0, 1.0, -(w - 510.0) / 20.0);
  } else if (w < 580.0) {
    color = vec3((w - 510.0) / 70.0, 1.0, 0.0);
  } else if (w < 645.0) {
    color = vec3(1.0, -(w - 645.0) / 65.0, 0.0);
  } else {
    color = vec3(1.0, 0.0, 0.0);
  }
  // Intensity correction at edges of visible spectrum
  float factor;
  if (w < 420.0) {
    factor = 0.3 + 0.7 * (w - 380.0) / 40.0;
  } else if (w > 700.0) {
    factor = 0.3 + 0.7 * (780.0 - w) / 80.0;
  } else {
    factor = 1.0;
  }
  return color * factor;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio-reactive modulators
  float bassSplit = bass() * uSensitivity * 0.6;
  float midsRotate = mids() * uSensitivity * 0.4;
  float trebleDetail = treble() * uSensitivity * 0.3;
  float onsetFlash = uOnset * uSensitivity * 2.0;
  float energyBright = uEnergy * uSensitivity;
  float kickBurst = uKick * uSensitivity;

  // === PRISM POSITION — audio-reactive rotation ===
  float prismAngle = time * 0.05 + midsRotate * 0.5
    + sin(time * 0.08) * bassSplit * 0.6;
  float cosP = cos(prismAngle);
  float sinP = sin(prismAngle);

  // Rotate coordinates around prism
  float rx = p.x * cosP - p.y * sinP;
  float ry = p.x * sinP + p.y * cosP;

  // === INCOMING WHITE BEAM ===
  float inBeamY = smoothstep(uBeamFocus * 0.08 + 0.02, 0.0, abs(ry));
  float inBeamX = smoothstep(0.0, -0.8, rx);
  float inBeam = inBeamY * inBeamX;

  // === SPECTRAL DISPERSION (wider fan, audio-swept) ===
  // Bass widens the split, treble tightens sub-bands
  float fanAngle = uSplitAngle * 0.8 + bassSplit * 0.4
    + sin(time * 0.12) * 0.15;
  float spreadFactor = rx * fanAngle * uSpectrumWidth * 1.5;

  // Only visible on the dispersed side
  float dispersedMask = smoothstep(0.0, 0.1, rx);

  // === MULTI-BEAM SPECTRAL SAMPLING (full rainbow with sub-beams) ===
  // Sample N spectral bands across the full visible range
  vec3 spectrumColor = vec3(0.0);
  float spectrumIntensity = 0.0;
  float numBands = 12.0;

  for (float i = 0.0; i < 12.0; i += 1.0) {
    // Each band has a target angle within the fan
    float bandT = i / (numBands - 1.0);
    // Full rainbow: 0=violet, 1=red
    float bandAngle = (bandT - 0.5) * spreadFactor * 2.0;

    // Audio-reactive individual band sweep
    float audioSweep = sin(time * 0.3 + bandT * 6.28) * bassSplit * 0.15;
    bandAngle += audioSweep;

    // How close is this pixel to this band's angle?
    float bandWidth = abs(spreadFactor) * 0.12 + 0.005
      + trebleDetail * 0.01; // treble sharpens bands
    float bandDist = abs(ry - bandAngle);
    float bandIntensity = smoothstep(bandWidth, bandWidth * 0.2, bandDist)
      * dispersedMask;

    // Distance-based falloff along beam length
    float beamLength = smoothstep(0.0, 0.05, rx) * smoothstep(2.5, 0.2, rx);
    bandIntensity *= beamLength;

    // Physical spectral color for this band position
    vec3 bandColor = wavelengthToRGB(bandT);

    spectrumColor += bandColor * bandIntensity;
    spectrumIntensity += bandIntensity;
  }

  // === SECONDARY REFRACTION (internal reflections) ===
  float secAngle = prismAngle + 0.4 + bassSplit * 0.2;
  float cosS = cos(secAngle);
  float sinS = sin(secAngle);
  float srx = p.x * cosS - p.y * sinS;
  float sry = p.x * sinS + p.y * cosS;
  float secSpread = srx * fanAngle * uSpectrumWidth * 0.8;
  float secMask = smoothstep(0.0, 0.15, srx);
  float secBand = smoothstep(abs(secSpread) * 0.3 + 0.01, 0.0, abs(sry)) * secMask;
  float secHue = fract(sry / (secSpread + 0.01) * 0.5 + 0.5 + time * 0.02);
  vec3 secColor = wavelengthToRGB(clamp(secHue, 0.0, 1.0)) * secBand * 0.35;

  // === CAUSTIC PATTERNS (more intricate) ===
  float c1 = sin(rx * 15.0 + ry * 20.0 + time * 0.8) * 0.5 + 0.5;
  float c2 = cos(rx * 12.0 - ry * 18.0 + time * 0.6) * 0.5 + 0.5;
  float c3 = sin(rx * 25.0 + ry * 10.0 - time * 0.4) * 0.5 + 0.5;
  float caustic = c1 * c2 * uCausticStrength * spectrumIntensity * dispersedMask
    + c3 * c2 * uCausticStrength * 0.3 * dispersedMask;

  // === PRISM BODY ===
  float prismGlow = smoothstep(0.15, 0.0, abs(rx) + abs(ry) * 0.8);
  // Rainbow refraction at prism surface
  vec3 prismRefract = wavelengthToRGB(fract(atan(ry, rx) / 6.28 + time * 0.01))
    * prismGlow * 0.3;

  // === COMBINE ===
  float brightness = uIntensity * 1.4 + energyBright * 0.4;

  // White incoming beam
  float whiteBeam = inBeam * brightness;

  // Full spectrum dispersed beams
  vec3 dispersed = spectrumColor * brightness + vec3(caustic * 0.3);

  // Combine: white beam + dispersed spectrum + secondary + prism glow
  vec3 finalColor = vec3(whiteBeam * 0.9) + dispersed + secColor * brightness
    + prismRefract;

  // Onset flash: bright burst at prism
  float flash = onsetFlash * (prismGlow + inBeam + spectrumIntensity * 0.5) * 0.3;

  // Kick: widens a burst momentarily
  float kickWiden = kickBurst * spectrumIntensity * 0.15;

  // Beat pulse
  float beatPulse = uBeat * uSensitivity * 0.08;

  // Chaos: caustic shimmer
  float shimmer = sin(time * 6.0 + uChaos * 5.0) * uChaos * 0.04 * spectrumIntensity;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.r + flash + beatPulse + shimmer + kickWiden, 0.0, 1.0),
    clamp(finalColor.g + flash + beatPulse + shimmer + kickWiden, 0.0, 1.0),
    clamp(finalColor.b + flash + beatPulse + shimmer + kickWiden, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRingCount;
uniform float uPetalDetail;
uniform float uSpiralTrails;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Kaleidoscopic fold for mandala symmetry
vec2 mandalaFold(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float bpmSync = uBpmSin * uSensitivity;

  vec3 col = vec3(0.0);

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Extra domain warping
  p += vec2(sin(p.y * 3.0 + time * 0.5) * 0.05, cos(p.x * 3.5 + time * 0.4) * 0.05) * (1.0 + bassVal * 0.4);

  // Kick expansion — 2x
  float expansion = 1.0 + kickVal * 0.3 + bassVal * 0.2;
  vec2 ep = p / expansion;
  float er = length(ep);
  float ea = atan(ep.y, ep.x);

  // BPM-synced rotation
  float bpmRot = time * 0.2 + bpmSync * 0.3;

  // === CONCENTRIC RINGS ===
  for (int i = 0; i < 12; i++) {
    if (float(i) >= uRingCount) break;
    float fi = float(i);
    float ringR = (fi + 1.0) / uRingCount * 0.9;
    float ringPulse = sin(beatPulse * 3.14 + fi * 0.5) * 0.03;
    float ringDist = abs(er - ringR - ringPulse);
    float ringGlow = exp(-ringDist * (40.0 + fi * 5.0)) * 0.4;
    float ringHue = fi / uRingCount + uPalette * 0.1 + time * 0.1 + beatPulse * 0.2 + sin(uTime * 0.3) * 0.2;
    vec3 ringCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * ringHue + vec3(0.0, 0.15, 0.35)));
    col += ringCol * ringGlow;
  }

  // === PETAL LAYERS ===
  for (int layer = 0; layer < 4; layer++) {
    float fl = float(layer);
    float petalFolds = 6.0 + fl * 2.0 + uChaos * 3.0;
    float layerRot = bpmRot * (0.5 + fl * 0.3) + fl * 0.5;
    float clr = cos(layerRot); float slr = sin(layerRot);
    vec2 rp = vec2(ep.x * clr - ep.y * slr, ep.x * slr + ep.y * clr);
    vec2 kp = mandalaFold(rp, petalFolds);

    float kr = length(kp);
    float ka = atan(kp.y, kp.x);

    float petalR = 0.15 + fl * 0.1 + bassVal * 0.15 * uPetalDetail;
    float petal = abs(cos(ka * petalFolds * 0.5));
    petal = pow(petal, 0.5 + fl * 0.2);
    float petalDist = kr - petal * petalR;

    float petalGlow = smoothstep(0.01, -0.03, petalDist) * (1.0 - fl * 0.2);
    float edgeGlow = exp(-abs(petalDist) * (30.0 + trebleVal * 80.0)) * 0.3;

    float innerPattern = sin(kr * (30.0 + trebleVal * 20.0) + time * 2.0);
    innerPattern *= sin(ka * (petalFolds * 2.0) + time);
    innerPattern = innerPattern * 0.5 + 0.5;

    float hue = fl * 0.2 + midsVal * 0.6 + uPalette * 0.1 + time * 0.08 + sin(uTime * 0.25) * 0.15;
    vec3 petalCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.2, 0.4)));
    col += petalCol * petalGlow * innerPattern * 0.4 * uPetalDetail;
    col += petalCol * edgeGlow * uPetalDetail;
  }

  // === INNER SACRED GEOMETRY ===
  float sacred = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float sAngle = fi * 1.0472;
    vec2 sCenter = vec2(cos(sAngle + bpmRot), sin(sAngle + bpmRot)) * 0.5;
    float sDist = abs(length(ep * 5.0 - sCenter) - 0.5);
    sacred += exp(-sDist * 20.0);
  }
  float sacredR = er * 5.0;
  sacred += exp(-abs(sacredR - 0.5) * 20.0);
  col += vec3(1.0, 0.9, 0.7) * sacred * 0.15;

  // === SPIRAL LIGHT TRAILS ===
  float spiralAmt = uSpiralTrails * (0.5 + onsetFlash * 1.0);
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float spiralAngle = ea - er * (5.0 + fi) + time * (1.0 + fi * 0.3) + fi * 0.785;
    float spiralWave = sin(spiralAngle * 3.0);
    float spiralGlow = exp(-abs(spiralWave) * (5.0 + (1.0 - spiralAmt) * 10.0));
    spiralGlow *= smoothstep(0.8, 0.1, er);
    spiralGlow *= spiralAmt;
    float spiralHue = fi * 0.125 + time * 0.1 + er * 0.5;
    vec3 spiralCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * spiralHue + vec3(0.0, 0.33, 0.67)));
    col += spiralCol * spiralGlow * 0.15;
  }

  // Center core
  float coreGlow = exp(-er * er * 15.0) * (0.4 + beatPulse * 0.3 + kickVal * 0.2);
  col += vec3(1.0, 0.95, 0.85) * coreGlow;

  col *= 1.0 + beatPulse * 0.4;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

// Psychedelic HSV conversion
vec3 pfl_hsv2rgb(vec3 c) {
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

vec3 templeGem(float t) {
  // Continuously cycling gem colors instead of 4 fixed colors
  float phase = t + uTime * 0.15;
  return pfl_hsv2rgb(vec3(fract(phase * 0.3), 0.85, 0.9));
}

vec3 templePalette(float t, float shift) {
  // More psychedelic palette with time-varying offsets
  float timeShift = uTime * 0.06;
  return 0.5 + 0.5 * cos(6.2832 * (t + shift + timeShift + vec3(0.0, 0.15, 0.35)));
}

float sdBoxPFL(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdColumnPFL(vec3 p, float r, float h) {
  vec2 d = abs(vec2(length(p.xz), p.y)) - vec2(r, h);
  return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

float ornatePattern(vec3 p, float scale) {
  vec3 q = abs(mod(p * scale, 2.0) - 1.0);
  return (min(min(q.x, q.y), q.z) - 0.2) / scale;
}

float templeMap(vec3 p, float bassVal, float trebleVal) {
  float scene = 100.0;
  float floorDist = p.y + 1.0;
  scene = min(scene, floorDist);
  float ceilingBase = -(p.y - 3.0);
  float ornate = ornatePattern(p + vec3(0.0, 3.0, 0.0), 4.0 + trebleVal * 2.0);
  float ceiling = max(ceilingBase, ornate);
  scene = min(scene, ceiling);
  vec3 colP = p;
  colP.xz = mod(colP.xz + 2.0, 4.0) - 2.0;
  float columnHeight = 2.0 + bassVal * 0.5;
  float column = sdColumnPFL(colP - vec3(0.0, columnHeight - 1.0, 0.0), 0.2, columnHeight);
  float capital = sdBoxPFL(colP - vec3(0.0, columnHeight * 2.0 - 1.0, 0.0), vec3(0.35, 0.1, 0.35));
  column = min(column, capital);
  float base = sdBoxPFL(colP - vec3(0.0, -0.9, 0.0), vec3(0.35, 0.1, 0.35));
  column = min(column, base);
  scene = min(scene, column);
  float altar = sdBoxPFL(p - vec3(0.0, -0.3, 0.0), vec3(0.8, 0.7, 0.8));
  float altarOrnate = ornatePattern(p, 8.0);
  altar = max(altar, altarOrnate * 0.5);
  scene = min(scene, altar);
  return scene;
}

vec3 templeNormal(vec3 p, float bassVal, float trebleVal) {
  float eps = 0.001;
  float d = templeMap(p, bassVal, trebleVal);
  return normalize(vec3(
    templeMap(p + vec3(eps, 0.0, 0.0), bassVal, trebleVal) - d,
    templeMap(p + vec3(0.0, eps, 0.0), bassVal, trebleVal) - d,
    templeMap(p + vec3(0.0, 0.0, eps), bassVal, trebleVal) - d
  ));
}

void main() {
  vec2 uv = (vUv - 0.5) * 2.0;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  float camZ = time * 2.0 + uZoom * 3.0;
  vec3 ro = vec3(sin(time * 0.3) * 1.0, 0.5 + sin(time * 0.2) * 0.3, camZ);
  vec3 lookAt = ro + vec3(sin(time * 0.15) * 0.5, 0.0, 1.0);
  vec3 fwd = normalize(lookAt - ro);
  vec3 rgt = normalize(cross(vec3(0.0, 1.0, 0.0), fwd));
  vec3 up = cross(fwd, rgt);
  vec3 rd = normalize(uv.x * rgt + uv.y * up + 1.5 * fwd);

  float totalDist = 0.0;
  float hitDist = 0.0;
  vec3 hitPos = ro;
  bool hit = false;

  for (float i = 0.0; i < 64.0; i += 1.0) {
    hitPos = ro + rd * totalDist;
    hitDist = templeMap(hitPos, bassVal, trebleVal);
    if (hitDist < 0.002) { hit = true; break; }
    if (totalDist > 30.0) break;
    totalDist += hitDist * 0.8;
  }

  vec3 col = vec3(0.0);

  if (hit) {
    vec3 normal = templeNormal(hitPos, bassVal, trebleVal);
    vec3 lightDir1 = normalize(vec3(sin(time * 0.5), 1.0, cos(time * 0.3)));
    vec3 lightDir2 = normalize(vec3(-0.5, 0.3, 1.0));
    float diff1 = max(dot(normal, lightDir1), 0.0);
    float diff2 = max(dot(normal, lightDir2), 0.0);
    vec3 viewDir = normalize(ro - hitPos);
    vec3 halfDir = normalize(lightDir1 + viewDir);
    float spec = pow(max(dot(normal, halfDir), 0.0), 32.0);

    // Psychedelic material color — continuously cycling hue
    float matId = fract(hitPos.x * 0.5 + hitPos.z * 0.3 + hitPos.y * 0.7);
    float psychHue = fract(matId + time * 0.08 + uPalette * 0.3);
    vec3 matColor = pfl_hsv2rgb(vec3(psychHue, 0.7 + midsVal * 0.2, 0.8));
    // Blend with cycling palette
    vec3 palColor = templePalette(matId + uPalette * 0.2, time * 0.05);
    matColor = mix(matColor, palColor, 0.4 + 0.2 * sin(time * 0.3));

    // Gem sections — cycling psychedelic colors
    float gemPattern = sin(hitPos.x * 8.0) * sin(hitPos.y * 8.0) * sin(hitPos.z * 8.0);
    if (gemPattern > 0.4) {
      vec3 gemCol = templeGem(hitPos.x + hitPos.z + time * 0.3);
      matColor = mix(matColor, gemCol, 0.7);
    }

    // Psychedelic lighting — color-shifted light sources
    vec3 light1Col = pfl_hsv2rgb(vec3(fract(time * 0.04), 0.5, 1.0));
    vec3 light2Col = pfl_hsv2rgb(vec3(fract(time * 0.04 + 0.33), 0.4, 0.8));
    col = matColor * (diff1 * light1Col + diff2 * light2Col * 0.4);
    // Specular with color shift
    vec3 specColor = pfl_hsv2rgb(vec3(fract(time * 0.07 + 0.5), 0.3, 1.0));
    col += specColor * spec * 0.6;

    // Psychedelic fog — color cycling
    float fog = exp(-totalDist * 0.08);
    vec3 fogColor = pfl_hsv2rgb(vec3(fract(time * 0.03 + 0.7), 0.4, 0.12));
    col = mix(fogColor, col, fog);

    // Color-shifting light beams
    float beamAngle = fract(hitPos.x * 0.25 + hitPos.z * 0.25);
    float beam = smoothstep(0.48, 0.5, beamAngle) * smoothstep(0.52, 0.5, beamAngle);
    vec3 beamColor = pfl_hsv2rgb(vec3(fract(time * 0.15 + beamAngle), 0.8, 1.0));
    col += beamColor * beam * beatVal * 2.5;

    // Gem glow with audio reactivity
    if (gemPattern > 0.4) {
      col += templeGem(hitPos.x + hitPos.z + time * 0.3) * midsVal * 0.5;
    }

    // Iridescent sheen based on view angle
    float fresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 3.0);
    vec3 iridescentColor = pfl_hsv2rgb(vec3(fract(fresnel * 0.5 + time * 0.06), 0.9, 0.8));
    col += iridescentColor * fresnel * 0.2;

    // Extreme psychedelic color saturation boost — 2x mids
    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(vec3(lum), col, 2.0 + midsVal * 0.6);

  } else {
    // Background — psychedelic color wash
    float bgGlow = exp(-length(uv) * 0.8);
    vec3 bgCol = pfl_hsv2rgb(vec3(fract(time * 0.05 + length(uv) * 0.1), 0.6, 0.08));
    col = bgCol * bgGlow;
    col += templePalette(uv.x * 0.2 + time * 0.05, uPalette * 0.2) * 0.05;
  }

  // Kick flash — color-shifting — 2x
  vec3 kickColor = pfl_hsv2rgb(vec3(fract(time * 0.2), 0.6, 0.5));
  col += kickColor * kickVal * 0.6;
  // Onset beam — psychedelic — 2x
  vec3 onsetColor = pfl_hsv2rgb(vec3(fract(time * 0.3 + 0.5), 0.7, 1.0));
  col += onsetColor * exp(-abs(uv.x) * 4.0) * onsetVal * 1.0;
  // Sparkle with color variation — 2x treble
  float sparkle = sin(uv.x * 40.0 + time * 6.0) * sin(uv.y * 40.0 - time * 5.0);
  sparkle = pow(max(sparkle, 0.0), 15.0);
  vec3 sparkleCol = pfl_hsv2rgb(vec3(fract(uv.x * 0.5 + uv.y * 0.3 + time * 0.2 + sin(uTime * 0.3) * 0.2), 0.7, 1.0));
  col += sparkleCol * sparkle * trebleVal * 0.4;

  // Global color pulse on energy — 2x
  col *= 1.0 + uEnergy * uSensitivity * 0.3;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

vec3 rainbowHue(float h) {
  return 0.5 + 0.5 * cos(6.2832 * (h + vec3(0.0, 0.33, 0.67)));
}

float hashPS(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noisePS(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashPS(i);
  float b = hashPS(i + vec2(1.0, 0.0));
  float c = hashPS(i + vec2(0.0, 1.0));
  float d = hashPS(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.6;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  float specBands[8];
  specBands[0] = uSpectrum0;
  specBands[1] = uSpectrum1;
  specBands[2] = uSpectrum2;
  specBands[3] = uSpectrum3;
  specBands[4] = uSpectrum4;
  specBands[5] = uSpectrum5;
  specBands[6] = uSpectrum6;
  specBands[7] = uSpectrum7;

  vec3 col = vec3(0.01, 0.01, 0.02);

  for (float i = 0.0; i < 12.0; i += 1.0) {
    int bandIdx = int(mod(i, 8.0));
    float bandVal = specBands[bandIdx] * uSensitivity;
    float bandHue = i / 12.0 + uPalette * 0.15 + time * 0.04 + sin(uTime * 0.3) * 0.15;
    float baseY = (i / 11.0 - 0.5) * 2.0;
    float freq = 1.5 + i * 0.3;
    float phase = time * (0.5 + i * 0.1) + i * 1.2;
    float waveY = baseY + sin(p.x * freq + phase) * 0.3;
    waveY += sin(p.x * freq * 2.3 + phase * 0.7) * 0.1;
    waveY += cos(p.x * freq * 0.5 + phase * 1.3) * 0.15;
    waveY += sin(p.x * 8.0 + time * 2.0 + i * 3.0) * uChaos * 0.08;

    float bandWidth = 0.06 + bassVal * 0.08 + bandVal * 0.16;
    float dist = abs(p.y - waveY);
    float bandShape = exp(-dist * dist / (bandWidth * bandWidth));
    float edgeGlow = exp(-dist * dist / (bandWidth * bandWidth * 4.0));
    vec3 bandColor = rainbowHue(bandHue);
    float brightness = 0.5 + 0.5 * sin(p.x * 3.0 + time * (1.0 + i * 0.2) + i);
    brightness = mix(0.4, 1.0, brightness);
    brightness *= 0.5 + bandVal * 1.0;
    float coreLine = exp(-dist * dist / (0.003 + bandVal * 0.005));

    col += bandColor * bandShape * brightness * 0.15;
    col += bandColor * edgeGlow * 0.04;
    col += (bandColor + vec3(0.3)) * coreLine * 0.1;
  }

  for (float i = 0.0; i < 4.0; i += 1.0) {
    float crossHue = i * 0.25 + 0.5 + uPalette * 0.1;
    float baseX = (i / 3.0 - 0.5) * 2.0;
    float crossWave = baseX + sin(p.y * 2.0 + time * 0.8 + i * 2.5) * 0.4;
    float crossDist = abs(p.x - crossWave);
    float crossBand = exp(-crossDist * crossDist / 0.01);
    int crossBandIdx = int(mod(i * 2.0 + 1.0, 8.0));
    float crossBandVal = specBands[crossBandIdx] * uSensitivity;
    vec3 crossColor = rainbowHue(crossHue);
    col += crossColor * crossBand * crossBandVal * 0.15;
  }

  col *= 1.0 + kickVal * 0.8;
  float streak = exp(-abs(p.y) * 3.0) * onsetVal * 0.6;
  col += rainbowHue(p.x * 0.2 + time * 0.1) * streak;
  col *= 1.0 + beatVal * 0.08;

  float sparkle = noisePS(p * 30.0 + time * 3.0);
  sparkle = pow(sparkle, 8.0);
  col += vec3(0.8, 0.85, 1.0) * sparkle * trebleVal * 0.15;

  float shimmer = sin(p.x * 15.0 + p.y * 10.0 + time * 4.0) * 0.5 + 0.5;
  shimmer = pow(shimmer, 4.0);
  col += rainbowHue(time * 0.05 + p.y * 0.3) * shimmer * midsVal * 0.05;

  float dust = noisePS(p * 5.0 + time * 0.1);
  dust = pow(dust, 3.0);
  col += vec3(0.03, 0.02, 0.05) * dust;

  float centerGlow = exp(-length(p) * 0.5) * 0.05;
  col += rainbowHue(time * 0.02 + length(p) * 0.1) * centerGlow;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBeamWidth;
uniform float uRotationSync;
uniform float uFieldStrength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.8;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetPulse = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Pulsar rotation: mix free rotation with BPM-synced rotation
  float freeRotation = time * 3.0;
  float bpmRotation = uBpmSin * 3.14159;
  float rotAngle = mix(freeRotation, bpmRotation, uRotationSync);

  // Beam angle relative to current rotation
  float beamAngle1 = rotAngle;
  float beamAngle2 = rotAngle + 3.14159; // opposite pole

  float beamW = uBeamWidth * (0.3 + bassVal * 0.4);

  // === NEUTRON STAR CORE ===
  float starRadius = 0.06;
  float starGlow = exp(-r * r / (starRadius * starRadius * 2.0));
  float surfaceDetail = noise(vec2(angle * 10.0 + time * 5.0, r * 50.0)) * 0.3;
  vec3 starColor = vec3(0.9, 1.0, 1.0) * starGlow * (2.0 + surfaceDetail);
  starColor += vec3(0.4, 0.6, 1.0) * exp(-r * r * 800.0); // hot core

  // === BEAMS ===
  float angleDiff1 = abs(mod(angle - beamAngle1 + 3.14159, 6.28318) - 3.14159);
  float angleDiff2 = abs(mod(angle - beamAngle2 + 3.14159, 6.28318) - 3.14159);

  float beam1 = smoothstep(beamW, beamW * 0.2, angleDiff1) *
                smoothstep(0.0, 0.1, r) *
                (1.0 / (r * 2.0 + 0.1));
  float beam2 = smoothstep(beamW, beamW * 0.2, angleDiff2) *
                smoothstep(0.0, 0.1, r) *
                (1.0 / (r * 2.0 + 0.1));

  // Beam internal structure
  float beamNoise1 = noise(vec2(r * 20.0 - time * 10.0, angleDiff1 * 30.0));
  float beamNoise2 = noise(vec2(r * 20.0 - time * 10.0, angleDiff2 * 30.0));
  beam1 *= (0.7 + beamNoise1 * 0.3);
  beam2 *= (0.7 + beamNoise2 * 0.3);

  // Beam power from bass
  float beamPower = 1.0 + bassVal * 3.0 + beatPulse * 1.6;
  beam1 *= beamPower;
  beam2 *= beamPower;

  // Beam colors: hot blue-white core, purple-pink edges
  vec3 beamCore = vec3(0.9, 1.0, 1.0);
  vec3 beamEdge = vec3(1.0, 0.4, 1.0);
  float edgeFactor1 = smoothstep(beamW * 0.1, beamW * 0.8, angleDiff1);
  float edgeFactor2 = smoothstep(beamW * 0.1, beamW * 0.8, angleDiff2);
  vec3 beamCol1 = mix(beamCore, beamEdge, edgeFactor1) * beam1;
  vec3 beamCol2 = mix(beamCore, beamEdge, edgeFactor2) * beam2;

  // === MAGNETIC FIELD LINES ===
  float fieldVis = uFieldStrength * (1.0 + kickPulse * 1.0);
  vec3 fieldCol = vec3(0.0);

  // Dipole field lines: r = sin^2(theta) in magnetic coordinates
  for (int i = 0; i < 8; i++) {
    float fi = float(i) + 1.0;
    float fieldScale = fi * 0.08;
    // Magnetic field line in rotated frame
    float magAngle = angle - rotAngle;
    float sinA = sin(magAngle);
    float expectedR = fieldScale * sinA * sinA;
    float fieldDist = abs(r - expectedR);
    float fieldLine = exp(-fieldDist * fieldDist * 500.0) * fieldVis * 0.3;
    fieldLine *= smoothstep(0.0, 0.02, abs(sinA)); // fade at poles
    fieldCol += vec3(0.3, 0.6, 1.0) * fieldLine / fi;
  }

  // === MAGNETOSPHERE GLOW ===
  float magGlow = exp(-r * 3.0) * 0.25 * (1.0 + midsVal * 1.0);
  vec3 magCol = vec3(0.15, 0.2, 0.45) * magGlow;

  // === SURFACE SPARKS (treble) ===
  float sparkle = 0.0;
  if (r < 0.15) {
    float sparkNoise = noise(vec2(angle * 20.0 + time * 30.0, r * 100.0));
    sparkle = smoothstep(0.7, 0.9, sparkNoise) * trebleVal * exp(-r * 20.0);
  }
  vec3 sparkCol = vec3(1.0, 0.95, 0.85) * sparkle * 3.0;

  // === BACKGROUND: dark space with faint nebula ===
  float bgNoise = noise(p * 3.0 + time * 0.05) * 0.03;
  vec3 bg = vec3(0.01 + bgNoise * 0.5, 0.005 + bgNoise * 0.3, 0.02 + bgNoise);

  // Stars
  float starGrid = 100.0;
  vec2 starCell = floor(p * starGrid);
  float starH = hash(starCell);
  if (starH > 0.985) {
    vec2 starFrac = fract(p * starGrid) - vec2(hash(starCell + 5.0), hash(starCell + 11.0));
    float sDist = dot(starFrac, starFrac);
    bg += vec3(0.6, 0.7, 0.9) * exp(-sDist * 1500.0) * 0.3;
  }

  // === ONSET FLASH: pulse from core ===
  vec3 onsetCol = vec3(0.9, 0.95, 1.0) * onsetPulse * 0.6 * exp(-r * 4.0);

  // Palette shift
  float palShift = uPalette * 0.25;

  // === COMBINE ===
  vec3 col = bg + starColor + beamCol1 + beamCol2 + fieldCol + magCol + sparkCol + onsetCol;

  // Palette rotation
  col = vec3(
    col.r * cos(palShift) + col.b * sin(palShift),
    col.g,
    -col.r * sin(palShift) + col.b * cos(palShift)
  );

  // Chaos adds jitter to beams
  col += vec3(0.1, 0.05, 0.15) * uChaos * noise(vec2(angle * 5.0 + time * 10.0, r * 8.0)) * 0.2;

  col *= (0.8 + uEnergy * uSensitivity * 0.6);
  col *= uIntensity * 1.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBeamWidth;
uniform float uRotationSync;
uniform float uJetIntensity;
uniform float uFieldLines;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / max(uZoom * 0.8 + 0.3, 0.1);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float bpmVal = uBpmSin;
  float bpm2Val = uBpmSin2;
  float energyVal = uEnergy * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Space background
  vec3 col = vec3(0.003, 0.002, 0.008);

  // Stars
  for (float i = 0.0; i < 50.0; i++) {
    vec2 star = vec2(hash(vec2(i, 3.0)), hash(vec2(3.0, i))) * 2.0 - 1.0;
    float sd = length(p - star);
    col += vec3(0.7, 0.7, 1.0) * exp(-sd * 200.0) * 0.08;
  }

  // Neutron star core
  float coreR = 0.05;
  float core = exp(-r / coreR * 3.0);
  col += vec3(0.9, 0.95, 1.0) * core * 2.0;

  // Magnetosphere (purple/blue halo)
  float magnetoR = 0.4 + bassVal * 0.2;
  float magneto = exp(-abs(r - magnetoR) * 8.0) * 0.3;
  magneto += exp(-r * 3.0) * 0.15;
  col += vec3(0.45, 0.15, 0.85) * magneto;

  // Magnetic field lines (dipole pattern)
  if (uFieldLines > 0.1) {
    for (float i = 0.0; i < 12.0; i++) {
      float fieldAngle = i * 0.524 + time * 0.02;
      // Dipole field line: r = R * cos^2(theta)
      float theta = angle - fieldAngle;
      float fieldR = 0.5 * pow(cos(theta), 2.0);
      float fieldDist = abs(r - fieldR);
      float field = exp(-fieldDist * 30.0) * uFieldLines * 0.15;
      col += vec3(0.3, 0.15, 0.7) * field * (0.5 + midsVal * 1.0);
    }
  }

  // Lighthouse beam rotation — synced to BPM
  float beamAngle = mix(time * 3.0, bpmVal * 3.14159, uRotationSync);
  float beamW = uBeamWidth * 0.3 + bassVal * 0.3;

  // Two opposing beams
  for (float b = 0.0; b < 2.0; b++) {
    float bAngle = beamAngle + b * 3.14159;
    float angleDiff = abs(mod(angle - bAngle + 3.14159, 6.28318) - 3.14159);

    // Beam cone
    float beam = smoothstep(beamW, 0.0, angleDiff);
    beam *= smoothstep(0.0, 0.1, r); // Not at center
    beam *= exp(-r * 1.5); // Fade with distance

    // Beam brightens at sweep
    float sweep = 1.0 + onsetVal * 4.0;

    // Beam color: white center, blue edges
    vec3 beamCol = mix(vec3(0.5, 0.8, 1.0), vec3(1.0, 1.0, 0.95), beam);
    beamCol += vec3(0.1, 0.0, 0.2) * uPalette * 0.2;

    col += beamCol * beam * 1.2 * sweep;

    // Beam edge glow
    float edgeGlow = exp(-abs(angleDiff - beamW) * 20.0) * exp(-r * 2.0);
    col += vec3(0.4, 0.6, 1.0) * edgeGlow * 0.5;
  }

  // Polar jets along rotation axis
  vec2 jetAxis = vec2(cos(beamAngle + 1.5708), sin(beamAngle + 1.5708));
  float jetProj = dot(p, jetAxis);
  float jetPerp = length(p - jetAxis * jetProj);

  float jetWidth = 0.04 + trebleVal * 0.02;
  float jet = exp(-jetPerp / jetWidth) * smoothstep(0.0, 0.1, abs(jetProj));
  jet *= exp(-abs(jetProj) * 2.0) * uJetIntensity;

  // Jet particles
  float jetParticles = noise(vec2(jetProj * 20.0, time * 5.0)) * jet;
  col += vec3(0.7, 0.9, 1.0) * jet * 0.8;
  col += vec3(0.9, 1.0, 1.0) * jetParticles * 0.5 * trebleVal;

  // Pulse timing ring (radio emission)
  float pulseRing = exp(-abs(r - fract(time * 0.5) * 1.5) * 30.0);
  pulseRing *= smoothstep(0.0, 0.3, fract(time * 0.5));
  col += vec3(0.3, 0.45, 1.0) * pulseRing * 0.4 * energyVal;

  // Kick flash — radio burst
  col = mix(col, col * 2.5 + vec3(0.08, 0.12, 0.3), kickVal * 0.6);

  // BPM2 ambient pulse
  col += vec3(0.01, 0.01, 0.03) * max(bpm2Val, 0.0) * 0.2;

  col *= uIntensity * 1.5;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmVal(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    val += amp * noiseVal(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return val;
}

// Star position from index (deterministic scatter)
vec2 starPos(float idx) {
  float angle = idx * 2.399963; // golden angle
  float radius = sqrt(idx / 36.0) * 1.3;
  return vec2(cos(angle), sin(angle)) * radius;
}

// Get audio level for a star based on index
float starAudioLevel(float idx) {
  float band = mod(idx, 8.0);
  if (band < 1.0) return uSpectrum0;
  if (band < 2.0) return uSpectrum1;
  if (band < 3.0) return uSpectrum2;
  if (band < 4.0) return uSpectrum3;
  if (band < 5.0) return uSpectrum4;
  if (band < 6.0) return uSpectrum5;
  if (band < 7.0) return uSpectrum6;
  return uSpectrum7;
}

// Distance from point to line segment
float distToSegment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float t = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  vec2 closest = a + t * ba;
  return length(p - closest);
}

// Shooting star
float shootingStar(vec2 p, float time, float idx) {
  float startTime = hashVal(vec2(idx, 99.0)) * 10.0;
  float t = mod(time - startTime, 3.0 + hashVal(vec2(idx, 88.0)) * 5.0);
  float progress = clamp(t * 0.5, 0.0, 1.0);

  vec2 startP = vec2(
    hashVal(vec2(idx, 1.0)) * 3.0 - 1.5,
    hashVal(vec2(idx, 2.0)) * 1.0 + 0.5
  );
  vec2 dir = normalize(vec2(
    hashVal(vec2(idx, 3.0)) - 0.5,
    -0.3 - hashVal(vec2(idx, 4.0)) * 0.5
  ));

  vec2 headPos = startP + dir * progress * 2.0;
  vec2 tailPos = startP + dir * max(0.0, progress - 0.15) * 2.0;

  float dist = distToSegment(p, tailPos, headPos);
  float streak = 0.003 / (dist + 0.002);

  // Fade at head and tail
  float fade = smoothstep(0.0, 0.1, progress) * smoothstep(1.0, 0.7, progress);
  return streak * fade;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Nebula background
  float nebula1 = fbmVal(p * 1.5 + time * 0.05);
  float nebula2 = fbmVal(p * 2.0 - time * 0.03 + vec2(5.0));
  float nebula3 = fbmVal(p * 0.8 + vec2(sin(time * 0.1), cos(time * 0.08)));

  vec3 nebulaCol = vec3(0.07, 0.03, 0.14);
  nebulaCol += vec3(0.22, 0.08, 0.3) * nebula1;
  nebulaCol += vec3(0.08, 0.15, 0.3) * nebula2;
  nebulaCol += vec3(0.15, 0.03, 0.08) * nebula3;

  vec3 col = nebulaCol;

  // Stars and constellation lines
  float constellationGlow = 0.0;
  float totalStarGlow = 0.0;

  for (int i = 0; i < 36; i++) {
    float fi = float(i);
    vec2 sPos = starPos(fi);

    // Gentle drift
    sPos += vec2(
      sin(time * 0.1 + fi * 0.7) * 0.05,
      cos(time * 0.12 + fi * 0.9) * 0.05
    ) * uChaos;

    // Star glow
    float dist = length(p - sPos);
    float audioLvl = starAudioLevel(fi) * uSensitivity;
    float starSize = 0.01 + audioLvl * 0.03;
    float glow = starSize / (dist * dist + 0.001);

    // Star color based on audio band
    float hue = fract(fi * 0.08 + uPalette * 0.2 + time * 0.02);
    vec3 starCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.33, 0.67)));
    starCol = mix(vec3(1.0), starCol, 0.5 + audioLvl * 0.5);

    col += starCol * glow * 0.22;
    totalStarGlow += glow;

    // Constellation lines to nearby stars
    for (int j = 0; j < 36; j++) {
      if (j <= i) continue;
      float fj = float(j);
      vec2 sPos2 = starPos(fj);
      sPos2 += vec2(
        sin(time * 0.1 + fj * 0.7) * 0.05,
        cos(time * 0.12 + fj * 0.9) * 0.05
      ) * uChaos;

      float starDist = length(sPos - sPos2);
      if (starDist < 0.7) {
        float lineDist = distToSegment(p, sPos, sPos2);
        float lineGlow = 0.001 / (lineDist + 0.002);
        float lineAlpha = smoothstep(0.7, 0.3, starDist);
        float avgAudio = (starAudioLevel(fi) + starAudioLevel(fj)) * 0.5 * uSensitivity;
        constellationGlow += lineGlow * lineAlpha * (0.2 + avgAudio * 0.8);
      }
    }
  }

  // Constellation line color
  col += vec3(0.4, 0.65, 1.0) * constellationGlow * 0.05;

  // Shooting stars on onset
  float shootingIntensity = 0.0;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float star = shootingStar(p, time, fi);
    shootingIntensity += star;
  }
  col += vec3(1.0, 0.95, 0.85) * shootingIntensity * (0.05 + uOnset * uSensitivity * 1.0);

  // Kick pulse — all stars flash
  col += vec3(0.3, 0.4, 0.65) * uKick * uSensitivity * totalStarGlow * 0.01;

  // BPM breathing on nebula
  col *= 1.0 + uBpmSin * 0.08 * uSensitivity;

  // Spectral centroid shifts nebula temperature
  float centroidWarm = uSpectralCentroid * uSensitivity;
  col = mix(col, col * vec3(1.1, 0.95, 1.15), centroidWarm * 0.3);

  // Warmth adds amber to background
  col += vec3(0.1, 0.05, 0.0) * uWarmth * uSensitivity * 0.3;

  // Beat adds subtle constellation pulse
  col += vec3(0.15, 0.22, 0.35) * constellationGlow * uBeat * uSensitivity * 0.04;

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFoamScale;
uniform float uFluctuationRate;
uniform float uEnergyContrast;

// Hash for Voronoi cell points
vec3 cellHash(float cx, float cy, float seed) {
  float h1 = fract(sin(cx * 127.1 + cy * 311.7 + seed * 41.3) * 43758.5453);
  float h2 = fract(sin(cx * 269.5 + cy * 183.3 + seed * 73.1) * 43758.5453);
  return vec3(h1, h2, fract((h1 + h2) * 17.31));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 3.0);

  // Audio-reactive modulators
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  float fluctTime = time * uFluctuationRate;

  // Accumulate energy across scales
  float totalEnergy = 0.0;
  float edgeAccum = 0.0;
  float hotSpotAccum = 0.0;

  // === VORONOI SCALE 0: Large-scale foam (bass-driven) ===
  float s0 = uFoamScale * 2.5 + bassVal * 3.0;
  float gp0x = p.x * s0;
  float gp0y = p.y * s0;
  float ci0x = floor(gp0x);
  float ci0y = floor(gp0y);
  float cf0x = fract(gp0x) - 0.5;
  float cf0y = fract(gp0y) - 0.5;

  // Current cell
  vec3 h00 = cellHash(ci0x, ci0y, 0.0);
  float pt00x = h00.x - 0.5 + sin(fluctTime * 0.7 + h00.z * 6.28) * 0.3;
  float pt00y = h00.y - 0.5 + cos(fluctTime * 0.6 + h00.z * 6.28) * 0.3;
  float d00 = (cf0x - pt00x) * (cf0x - pt00x) + (cf0y - pt00y) * (cf0y - pt00y);
  float minD0 = d00;

  // Neighbor (-1, -1)
  vec3 h0nn = cellHash(ci0x - 1.0, ci0y - 1.0, 0.0);
  float pt0nnx = h0nn.x - 0.5 - 1.0 + sin(fluctTime * 0.7 + h0nn.z * 6.28) * 0.3;
  float pt0nny = h0nn.y - 0.5 - 1.0 + cos(fluctTime * 0.6 + h0nn.z * 6.28) * 0.3;
  float d0nn = (cf0x - pt0nnx) * (cf0x - pt0nnx) + (cf0y - pt0nny) * (cf0y - pt0nny);
  minD0 = mix(minD0, d0nn, smoothstep(0.0, 0.001, minD0 - d0nn));

  // Neighbor (0, -1)
  vec3 h0n0 = cellHash(ci0x, ci0y - 1.0, 0.0);
  float pt0n0x = h0n0.x - 0.5 + sin(fluctTime * 0.7 + h0n0.z * 6.28) * 0.3;
  float pt0n0y = h0n0.y - 0.5 - 1.0 + cos(fluctTime * 0.6 + h0n0.z * 6.28) * 0.3;
  float d0n0 = (cf0x - pt0n0x) * (cf0x - pt0n0x) + (cf0y - pt0n0y) * (cf0y - pt0n0y);
  minD0 = mix(minD0, d0n0, smoothstep(0.0, 0.001, minD0 - d0n0));

  // Neighbor (1, -1)
  vec3 h0pn = cellHash(ci0x + 1.0, ci0y - 1.0, 0.0);
  float pt0pnx = h0pn.x - 0.5 + 1.0 + sin(fluctTime * 0.7 + h0pn.z * 6.28) * 0.3;
  float pt0pny = h0pn.y - 0.5 - 1.0 + cos(fluctTime * 0.6 + h0pn.z * 6.28) * 0.3;
  float d0pn = (cf0x - pt0pnx) * (cf0x - pt0pnx) + (cf0y - pt0pny) * (cf0y - pt0pny);
  minD0 = mix(minD0, d0pn, smoothstep(0.0, 0.001, minD0 - d0pn));

  // Neighbor (-1, 0)
  vec3 h0n1 = cellHash(ci0x - 1.0, ci0y, 0.0);
  float pt0n1x = h0n1.x - 0.5 - 1.0 + sin(fluctTime * 0.7 + h0n1.z * 6.28) * 0.3;
  float pt0n1y = h0n1.y - 0.5 + cos(fluctTime * 0.6 + h0n1.z * 6.28) * 0.3;
  float d0n1 = (cf0x - pt0n1x) * (cf0x - pt0n1x) + (cf0y - pt0n1y) * (cf0y - pt0n1y);
  minD0 = mix(minD0, d0n1, smoothstep(0.0, 0.001, minD0 - d0n1));

  // Neighbor (1, 0)
  vec3 h0p1 = cellHash(ci0x + 1.0, ci0y, 0.0);
  float pt0p1x = h0p1.x - 0.5 + 1.0 + sin(fluctTime * 0.7 + h0p1.z * 6.28) * 0.3;
  float pt0p1y = h0p1.y - 0.5 + cos(fluctTime * 0.6 + h0p1.z * 6.28) * 0.3;
  float d0p1 = (cf0x - pt0p1x) * (cf0x - pt0p1x) + (cf0y - pt0p1y) * (cf0y - pt0p1y);
  minD0 = mix(minD0, d0p1, smoothstep(0.0, 0.001, minD0 - d0p1));

  float voronoi0 = sqrt(minD0);
  float energy0 = 1.0 / (voronoi0 * s0 + 0.1);
  totalEnergy += energy0 * 0.4;
  edgeAccum += smoothstep(0.08, 0.03, voronoi0) * 0.5;

  // === VORONOI SCALE 1: Medium foam (mids-driven) ===
  float s1 = uFoamScale * 5.0 + midsVal * 4.0;
  float gp1x = p.x * s1 + 17.0;
  float gp1y = p.y * s1 + 31.0;
  float ci1x = floor(gp1x);
  float ci1y = floor(gp1y);
  float cf1x = fract(gp1x) - 0.5;
  float cf1y = fract(gp1y) - 0.5;

  vec3 h10 = cellHash(ci1x, ci1y, 7.0);
  float pt10x = h10.x - 0.5 + sin(fluctTime * 1.1 + h10.z * 6.28) * 0.25;
  float pt10y = h10.y - 0.5 + cos(fluctTime * 0.9 + h10.z * 6.28) * 0.25;
  float d10 = (cf1x - pt10x) * (cf1x - pt10x) + (cf1y - pt10y) * (cf1y - pt10y);
  float minD1 = d10;

  vec3 h11 = cellHash(ci1x + 1.0, ci1y, 7.0);
  float pt11x = h11.x - 0.5 + 1.0 + sin(fluctTime * 1.1 + h11.z * 6.28) * 0.25;
  float pt11y = h11.y - 0.5 + cos(fluctTime * 0.9 + h11.z * 6.28) * 0.25;
  float d11 = (cf1x - pt11x) * (cf1x - pt11x) + (cf1y - pt11y) * (cf1y - pt11y);
  minD1 = mix(minD1, d11, smoothstep(0.0, 0.001, minD1 - d11));

  vec3 h12 = cellHash(ci1x, ci1y + 1.0, 7.0);
  float pt12x = h12.x - 0.5 + sin(fluctTime * 1.1 + h12.z * 6.28) * 0.25;
  float pt12y = h12.y - 0.5 + 1.0 + cos(fluctTime * 0.9 + h12.z * 6.28) * 0.25;
  float d12 = (cf1x - pt12x) * (cf1x - pt12x) + (cf1y - pt12y) * (cf1y - pt12y);
  minD1 = mix(minD1, d12, smoothstep(0.0, 0.001, minD1 - d12));

  vec3 h13 = cellHash(ci1x + 1.0, ci1y + 1.0, 7.0);
  float pt13x = h13.x - 0.5 + 1.0 + sin(fluctTime * 1.1 + h13.z * 6.28) * 0.25;
  float pt13y = h13.y - 0.5 + 1.0 + cos(fluctTime * 0.9 + h13.z * 6.28) * 0.25;
  float d13 = (cf1x - pt13x) * (cf1x - pt13x) + (cf1y - pt13y) * (cf1y - pt13y);
  minD1 = mix(minD1, d13, smoothstep(0.0, 0.001, minD1 - d13));

  float voronoi1 = sqrt(minD1);
  float energy1 = 1.0 / (voronoi1 * s1 + 0.15);
  totalEnergy += energy1 * 0.3;
  edgeAccum += smoothstep(0.06, 0.02, voronoi1) * 0.4;

  // === VORONOI SCALE 2: Fine quantum noise (treble-driven) ===
  float s2 = uFoamScale * 10.0 + trebleVal * 6.0;
  float gp2x = p.x * s2 + 53.0;
  float gp2y = p.y * s2 + 97.0;
  float ci2x = floor(gp2x);
  float ci2y = floor(gp2y);
  float cf2x = fract(gp2x) - 0.5;
  float cf2y = fract(gp2y) - 0.5;

  vec3 h20 = cellHash(ci2x, ci2y, 13.0);
  float jitter2 = uChaos * 0.2 + 0.2;
  float pt20x = h20.x - 0.5 + sin(fluctTime * 1.5 + h20.z * 6.28) * jitter2;
  float pt20y = h20.y - 0.5 + cos(fluctTime * 1.3 + h20.z * 6.28) * jitter2;
  float d20 = (cf2x - pt20x) * (cf2x - pt20x) + (cf2y - pt20y) * (cf2y - pt20y);

  vec3 h21 = cellHash(ci2x + 1.0, ci2y, 13.0);
  float pt21x = h21.x - 0.5 + 1.0 + sin(fluctTime * 1.5 + h21.z * 6.28) * jitter2;
  float pt21y = h21.y - 0.5 + cos(fluctTime * 1.3 + h21.z * 6.28) * jitter2;
  float d21 = (cf2x - pt21x) * (cf2x - pt21x) + (cf2y - pt21y) * (cf2y - pt21y);
  float minD2a = mix(d20, d21, smoothstep(0.0, 0.001, d20 - d21));

  vec3 h22 = cellHash(ci2x, ci2y + 1.0, 13.0);
  float pt22x = h22.x - 0.5 + sin(fluctTime * 1.5 + h22.z * 6.28) * jitter2;
  float pt22y = h22.y - 0.5 + 1.0 + cos(fluctTime * 1.3 + h22.z * 6.28) * jitter2;
  float d22 = (cf2x - pt22x) * (cf2x - pt22x) + (cf2y - pt22y) * (cf2y - pt22y);
  float minD2 = mix(minD2a, d22, smoothstep(0.0, 0.001, minD2a - d22));

  float voronoi2 = sqrt(minD2);
  float energy2 = 1.0 / (voronoi2 * s2 + 0.2);
  totalEnergy += energy2 * 0.2;
  edgeAccum += smoothstep(0.04, 0.01, voronoi2) * 0.3;

  // --- Hot spot: cell birth/annihilation events ---
  float hotPhase = sin(fluctTime * 3.0 + voronoi0 * 20.0) * 0.5 + 0.5;
  float hotSpot = smoothstep(0.9, 1.0, hotPhase) * energy0 * 0.8;
  hotSpotAccum += hotSpot;

  // Onset triggers "pair production"
  float pairFlash = onsetFlash * 4.0 * smoothstep(0.7, 1.0, hotPhase);
  hotSpotAccum += pairFlash;

  // === COLOR: cool scientific palette ===
  float energyMapped = clamp(totalEnergy * uEnergyContrast * 0.15, 0.0, 1.0);

  float paletteShift = uPalette * 0.1;
  // Electric blue base
  float baseR = 0.08 + paletteShift * 0.15;
  float baseG = 0.22 + paletteShift * 0.08;
  float baseB = 0.75 + paletteShift * 0.12;
  // White-blue highlight for edges
  float edgeR = 0.9;
  float edgeG = 0.95;
  float edgeB = 1.0;
  // Purple accent for hot spots
  float hotR = 0.8 + paletteShift * 0.2;
  float hotG = 0.2;
  float hotB = 1.0;

  // Mix: base energy color
  float energyR = mix(0.01, baseR, energyMapped);
  float energyG = mix(0.01, baseG, energyMapped);
  float energyB = mix(0.02, baseB, energyMapped);

  // Add edge highlights
  float edgeAmount = clamp(edgeAccum, 0.0, 1.0);
  float withEdgeR = energyR + edgeR * edgeAmount * 0.5;
  float withEdgeG = energyG + edgeG * edgeAmount * 0.5;
  float withEdgeB = energyB + edgeB * edgeAmount * 0.5;

  // Add hot spots
  float hotAmount = clamp(hotSpotAccum, 0.0, 1.0);
  float withHotR = withEdgeR + hotR * hotAmount;
  float withHotG = withEdgeG + hotG * hotAmount;
  float withHotB = withEdgeB + hotB * hotAmount;

  // Intensity and energy brightness
  float energyBright = uEnergy * uSensitivity * 0.5 + 0.75;
  float brightScale = uIntensity * 1.4 * energyBright;

  // Beat pulse brightness boost
  float beatBright = beatPulse * 0.24;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(withHotR, withHotG, withHotB)); withHotR = _pc.r; withHotG = _pc.g; withHotB = _pc.b; }
  gl_FragColor = vec4(
    clamp(withHotR * brightScale + beatBright, 0.0, 1.0),
    clamp(withHotG * brightScale + beatBright, 0.0, 1.0),
    clamp(withHotB * brightScale + beatBright, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Hydrogen-like orbital probability density
// n=quantum number, l=angular momentum, m=magnetic
float orbitalDensity(vec2 p, float time, float n, float lVal, float m) {
  float r = length(p);
  float theta = atan(p.y, p.x);

  // Radial part: Laguerre-like decay
  float radial = pow(r * 2.0 / n, lVal) * exp(-r / n);

  // Angular part: spherical harmonic-like
  float angular = 1.0;
  if (abs(m) > 0.5) {
    angular = cos(m * theta + time * 0.5);
  }
  if (lVal > 0.5) {
    angular *= (0.5 + 0.5 * cos(lVal * theta));
  }

  return radial * angular * angular;
}

// Standing wave pattern
float standingWave(vec2 p, float time, float freq) {
  float wave = sin(p.x * freq + time) * cos(p.y * freq - time * 0.7);
  wave *= cos(length(p) * freq * 0.5 - time * 1.3);
  return wave * 0.5 + 0.5;
}

// Quantum barrier (potential wall)
float barrier(vec2 p, float wallX, float wallWidth) {
  return smoothstep(wallWidth * 0.5, 0.0, abs(p.x - wallX));
}

// Tunneling wavefunction: exponential decay through barrier
float tunneling(vec2 p, float wallX, float wallWidth, float energy, float time) {
  float relX = p.x - wallX;
  float insideBarrier = barrier(p, wallX, wallWidth);

  // Incident wave
  float incident = 0.0;
  if (p.x < wallX - wallWidth * 0.5) {
    incident = (sin(p.x * 8.0 + time * 3.0) * 0.5 + 0.5);
    incident *= exp(-abs(p.y) * 2.0);
  }

  // Tunneled wave (exponentially decayed)
  float tunneled = 0.0;
  if (p.x > wallX + wallWidth * 0.5) {
    float decay = exp(-(p.x - wallX - wallWidth * 0.5) * (1.0 - energy));
    tunneled = (sin(p.x * 8.0 + time * 3.0) * 0.5 + 0.5) * decay * energy;
    tunneled *= exp(-abs(p.y) * 2.0);
  }

  // Inside barrier: evanescent wave
  float evanescent = 0.0;
  if (insideBarrier > 0.0) {
    evanescent = exp(-abs(relX) * 3.0 * (1.0 - energy)) * insideBarrier;
    evanescent *= exp(-abs(p.y) * 2.0);
    evanescent *= (sin(time * 3.0) * 0.3 + 0.7);
  }

  return incident + tunneled + evanescent;
}

// Interference pattern (double slit-like)
float interferencePattern(vec2 p, float time) {
  float slit1 = sin(length(p - vec2(0.0, 0.3)) * 20.0 - time * 4.0);
  float slit2 = sin(length(p - vec2(0.0, -0.3)) * 20.0 - time * 4.0);
  float combined = (slit1 + slit2) * 0.5;
  return combined * combined;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  vec3 col = vec3(0.0);

  // Multiple orbital overlays
  float orb1 = orbitalDensity(p, time, 2.0, 1.0, 1.0);
  float orb2 = orbitalDensity(p * 0.8, time * 0.7, 3.0, 2.0, 2.0);
  float orb3 = orbitalDensity(p * 1.2, time * 1.1, 3.0, 1.0, 0.0);

  // Audio drives orbital mixing
  float orbMix = orb1 * (0.5 + bassVal) + orb2 * (0.3 + midsVal) + orb3 * (0.2 + trebleVal);
  orbMix = clamp(orbMix, 0.0, 1.0);

  // Standing wave overlays
  float wave1 = standingWave(p, time, 6.0 + bassVal * 3.0);
  float wave2 = standingWave(p * 1.5, time * 0.8, 10.0 + midsVal * 5.0);

  // Quantum tunneling
  float wallX = 0.3 + sin(time * 0.2) * 0.2;
  float tunnelEnergy = 0.3 + bassVal * 0.5 + uChaos * 0.2;
  float tunnel = tunneling(p, wallX, 0.15, tunnelEnergy, time);

  // Interference
  float interf = interferencePattern(p, time);

  // Color palette: neon cyan/violet/white
  vec3 cyan = vec3(0.0, 0.9, 1.0);
  vec3 violet = vec3(0.6, 0.2, 1.0);
  vec3 white = vec3(1.0, 0.95, 1.0);
  vec3 deepBlue = vec3(0.02, 0.01, 0.08);
  float palShift = uPalette * 0.3;

  // Orbital clouds
  vec3 orbColor = mix(violet, cyan, orbMix + palShift);
  col += orbColor * orbMix * 0.6;

  // Standing waves
  col += mix(cyan, white, wave1) * wave1 * 0.15;
  col += violet * wave2 * 0.1;

  // Tunneling visualization
  vec3 tunnelColor = mix(cyan, white, tunnel);
  col += tunnelColor * tunnel * 0.4;

  // Barrier walls glow
  float barrierGlow = barrier(p, wallX, 0.15);
  col += vec3(0.3, 0.1, 0.4) * barrierGlow * 0.5;

  // Interference fringes
  col += mix(cyan, violet, interf + palShift) * interf * 0.15;

  // Probability cloud noise
  float cloudNoise = noiseVal(p * 5.0 + time * 0.5);
  col += deepBlue * cloudNoise * 0.3;

  // Kick: probability collapse flash
  col += white * uKick * uSensitivity * 0.4 * exp(-length(p) * 2.0);

  // Onset: tunneling burst
  col += cyan * uOnset * uSensitivity * 0.5 * tunnel;

  // Beat: orbital pulse
  col *= 1.0 + uBeat * uSensitivity * 0.15;

  // Spectral flux adds quantum uncertainty
  float uncertainty = uSpectralFlux * uSensitivity;
  vec2 jitter = vec2(noiseVal(p * 30.0 + time * 10.0) - 0.5) * uncertainty * 0.1;
  col += abs(col - vec3(orbitalDensity(p + jitter, time, 2.0, 1.0, 1.0))) * uncertainty;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.08 * uSensitivity;

  // Harmonicity brightens standing waves
  col += white * wave1 * uHarmonicity * uSensitivity * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBarCount;
uniform float uBarWidth;
uniform float uWaveAmplitude;
uniform float uMetallicSheen;

vec3 hsvToRgb(float h, float s, float v) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(vec3(h) + K.xyz) * 6.0 - K.www);
  return v * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), s);
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.02, 0.01, 0.05); // Dark background

  float totalBars = uBarCount + 2.0;

  for (float i = 0.0; i < 16.0; i++) {
    if (i >= totalBars) break;

    float phase = i / totalBars;

    // Bar vertical position: sinusoidal bounce
    float bounceFreq = 1.5 + i * 0.3;
    float bouncePhase = time * bounceFreq + i * 0.8;
    float baseY = 0.5 + sin(bouncePhase) * 0.3;

    // Beat bounce
    baseY += uBpmSin * 0.05 * (1.0 + i * 0.1);

    // Kick expansion
    float barH = 0.02 + uBarWidth * 0.04 + kickVal * 0.03;

    // Horizontal wave distortion
    float waveX = sin(p.x * 8.0 + time * 3.0 + i * 1.5) * uWaveAmplitude * 0.05;
    waveX += sin(p.x * 15.0 - time * 2.0) * uChaos * 0.02;
    float barY = baseY + waveX;

    // Distance to bar center
    float dist = abs(p.y - barY);

    // Bar mask with soft edges
    float bar = smoothstep(barH, barH * 0.3, dist);

    // Metallic gradient across bar width
    float metalGrad = (p.y - barY + barH) / (barH * 2.0);
    metalGrad = clamp(metalGrad, 0.0, 1.0);
    float metallic = 0.5 + sin(metalGrad * 3.14159) * uMetallicSheen * 0.5;

    // Spectrum-driven brightness per bar
    float specIdx = mod(i, 8.0);
    float specVal = 0.0;
    if (specIdx < 1.0) specVal = uSpectrum0;
    else if (specIdx < 2.0) specVal = uSpectrum1;
    else if (specIdx < 3.0) specVal = uSpectrum2;
    else if (specIdx < 4.0) specVal = uSpectrum3;
    else if (specIdx < 5.0) specVal = uSpectrum4;
    else if (specIdx < 6.0) specVal = uSpectrum5;
    else if (specIdx < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    float specBright = 0.6 + specVal * uSensitivity * 0.6;

    // Rainbow color per bar
    float hue = phase + uPalette * 0.2 + time * 0.05;
    vec3 barColor = hsvToRgb(hue, 0.85, 1.0);

    // Apply metallic sheen (bright center highlight)
    barColor *= metallic;
    barColor += vec3(1.0) * pow(metallic, 4.0) * uMetallicSheen * 0.3;

    // Copper bar effect (horizontal color variation)
    float copper = sin(p.x * 20.0 + time * 2.0 + i) * 0.1 + 0.9;
    barColor *= copper;

    // Add to composite
    col += bar * barColor * specBright * uIntensity;

    // Glow halo around bar
    float glow = exp(-dist * 40.0) * 0.15 * specBright;
    col += glow * barColor;
  }

  // Scrolling starfield background
  for (float i = 0.0; i < 3.0; i++) {
    vec2 starUV = p * (20.0 + i * 10.0);
    starUV.x += time * (1.0 + i * 0.5);
    vec2 starCell = floor(starUV);
    float starH = fract(sin(dot(starCell, vec2(127.1, 311.7))) * 43758.5453);
    float star = step(0.96, starH);
    vec2 starFract = fract(starUV) - 0.5;
    float starDist = length(starFract);
    col += smoothstep(0.05, 0.0, starDist) * star * vec3(0.3, 0.3, 0.5) * 0.3;
  }

  // Scanline overlay (C64 style)
  float scan = sin(p.y * 400.0) * 0.5 + 0.5;
  col *= 0.9 + scan * 0.1;

  // Beat pulse
  col += uBeat * uSensitivity * vec3(0.03, 0.02, 0.04);

  // Border
  float borderDist = min(min(p.x, 1.0 - p.x), min(p.y, 1.0 - p.y));
  float border = smoothstep(0.02, 0.0, borderDist);
  col = mix(col, vec3(0.3, 0.3, 0.4), border * 0.5);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
