__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBeamCount;
uniform float uFogDensity;
uniform float uBeamWidth;
uniform float uSweepRange;

#define PI 3.14159265

float hash(float n) {
  return fract(sin(n * 78.233) * 43758.5453);
}

// Distance from point to line segment
float lineDistSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Volumetric fog noise
float fogNoise(vec2 p, float time) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(dot(i, vec2(1.0, 157.0)));
  float b = hash(dot(i + vec2(1.0, 0.0), vec2(1.0, 157.0)));
  float c = hash(dot(i + vec2(0.0, 1.0), vec2(1.0, 157.0)));
  float d = hash(dot(i + vec2(1.0, 1.0), vec2(1.0, 157.0)));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Laser beam color
vec3 laserColor(float idx, float palette, float time) {
  float hue = fract(idx * 0.27 + palette * 0.15 + time * 0.02);
  // HSV to RGB
  vec3 c = vec3(hue, 0.95, 1.0);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 uv = (vUv - 0.5) * (1.5 + uZoom);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.75;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float kickVal = uKick * uSensitivity * 1.4;
  float beatVal = uBeat * uSensitivity * 1.3;
  float energyVal = uEnergy * uSensitivity * 1.2;

  int numBeams = int(uBeamCount + 2.0);
  float bWidth = (uBeamWidth * 0.015 + 0.003) + bassVal * 0.005;
  float sweep = uSweepRange * PI * 0.6;

  // Fog layer
  float fogBase = fogNoise(uv * 3.0 + time * 0.3, time) * 0.5 +
                  fogNoise(uv * 7.0 - time * 0.2, time) * 0.3;
  float fog = fogBase * (uFogDensity * 0.8 + 0.2 + midsVal * 0.3);

  vec3 totalLight = vec3(0.0);
  vec3 totalFlare = vec3(0.0);

  for (int i = 0; i < 12; i++) {
    if (i >= numBeams) break;
    float idx = float(i);
    float beamHash = hash(idx * 3.7 + 0.5);

    // Beam origin — from top/sides
    vec2 origin;
    float side = mod(idx, 3.0);
    if (side < 1.0) {
      origin = vec2(-0.5 + beamHash * 1.0, 0.75); // from top
    } else if (side < 2.0) {
      origin = vec2(-0.75, -0.3 + beamHash * 0.8); // from left
    } else {
      origin = vec2(0.75, -0.3 + beamHash * 0.8); // from right
    }

    // Sweep angle
    float sweepPhase = time * (0.3 + beamHash * 0.7) + idx * 1.3;
    float sweepAngle = sin(sweepPhase + beatVal * PI) * sweep;

    // Add chaos jitter
    sweepAngle += sin(time * 3.0 + idx * 7.0) * uChaos * 0.5;

    // Beam direction
    vec2 dir = vec2(sin(sweepAngle), -cos(sweepAngle));
    if (side >= 1.0 && side < 2.0) dir = vec2(cos(sweepAngle * 0.5), sin(sweepAngle));
    if (side >= 2.0) dir = vec2(-cos(sweepAngle * 0.5), sin(sweepAngle));

    vec2 beamEnd = origin + dir * 3.0;

    // Distance from pixel to beam line
    float d = lineDistSeg(uv, origin, beamEnd);

    // Beam glow with volumetric scattering
    float beamGlow = exp(-d * d / (bWidth * bWidth));

    // Fog scattering makes beam visible through fog
    float scatter = beamGlow * (0.3 + fog * 0.7);

    // Core beam (thin bright center)
    float core = exp(-d * d / (bWidth * bWidth * 0.1)) * 0.5;

    // Treble shimmer
    float shimmer = 1.0 + trebleVal * sin(d * 200.0 + time * 10.0) * 0.3;

    vec3 beamCol = laserColor(idx, uPalette, time);
    totalLight += beamCol * (scatter + core) * shimmer;

    // Flare at beam intersections
    for (int j = 0; j < 12; j++) {
      if (j >= numBeams || j <= i) continue;
      float jdx = float(j);
      float jHash = hash(jdx * 3.7 + 0.5);
      vec2 jOrigin;
      float jSide = mod(jdx, 3.0);
      if (jSide < 1.0) jOrigin = vec2(-0.5 + jHash * 1.0, 0.75);
      else if (jSide < 2.0) jOrigin = vec2(-0.75, -0.3 + jHash * 0.8);
      else jOrigin = vec2(0.75, -0.3 + jHash * 0.8);

      float jSweepPhase = time * (0.3 + jHash * 0.7) + jdx * 1.3;
      float jSweepAngle = sin(jSweepPhase + beatVal * PI) * sweep;
      vec2 jDir = vec2(sin(jSweepAngle), -cos(jSweepAngle));
      if (jSide >= 1.0 && jSide < 2.0) jDir = vec2(cos(jSweepAngle * 0.5), sin(jSweepAngle));
      if (jSide >= 2.0) jDir = vec2(-cos(jSweepAngle * 0.5), sin(jSweepAngle));

      // Approximate intersection
      float dj = lineDistSeg(uv, jOrigin, jOrigin + jDir * 3.0);
      float intersection = exp(-(d * d + dj * dj) / (bWidth * 4.0));
      vec3 flareCol = (beamCol + laserColor(jdx, uPalette, time)) * 0.5;
      totalFlare += flareCol * intersection * 0.3;
    }
  }

  // Kick flash
  totalLight *= 1.0 + kickVal * 2.0;
  totalFlare *= 1.0 + kickVal * 1.5;

  // Combine
  vec3 color = vec3(0.01, 0.01, 0.02); // dark venue
  color += totalLight * uIntensity;
  color += totalFlare * uIntensity;

  // Ambient fog glow
  color += fog * vec3(0.02, 0.02, 0.04) * uIntensity;

  // Energy
  color *= 0.7 + energyVal * 0.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPatternScale;
uniform float uActivatorRate;
uniform float uInhibitorRate;

// Cosine palette for organic chemical coloring
vec3 cosinePalette(float t, float offset) {
  float tau = 6.28318;
  float shifted = t + offset * 0.1;
  float r = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.0));
  float g = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.33));
  float b = 0.5 + 0.5 * cos(tau * (1.0 * shifted + 0.67));
  return vec3(r, g, b);
}

// 2D hash noise
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Smooth value noise
float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - f * 2.0);

  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio influences
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  // Base coordinates with bass-driven scale shift
  float scaleBase = uPatternScale + bassVal * 2.0;
  vec2 baseP = p * scaleBase;

  // Time-varying seed offset for morphing
  vec2 timeOffset = vec2(time * 0.08, time * 0.06);

  // --- Scale 1: coarse activator pattern ---
  float s1 = 1.0;
  vec2 p1 = baseP * s1 + timeOffset;
  float n1Point = valueNoise(p1);
  float n1Avg = (
    valueNoise(p1 + vec2(uInhibitorRate * 0.5, 0.0)) +
    valueNoise(p1 + vec2(0.0, uInhibitorRate * 0.5)) +
    valueNoise(p1 - vec2(uInhibitorRate * 0.5, 0.0)) +
    valueNoise(p1 - vec2(0.0, uInhibitorRate * 0.5))
  ) * 0.25;
  float react1 = (n1Point - n1Avg) * uActivatorRate;

  // --- Scale 2: medium pattern ---
  float s2 = 2.3 + midsVal * 0.5;
  vec2 p2 = baseP * s2 + timeOffset * 1.3 + vec2(17.3, 31.7);
  float n2Point = valueNoise(p2);
  float n2Avg = (
    valueNoise(p2 + vec2(uInhibitorRate * 0.3, 0.0)) +
    valueNoise(p2 + vec2(0.0, uInhibitorRate * 0.3)) +
    valueNoise(p2 - vec2(uInhibitorRate * 0.3, 0.0)) +
    valueNoise(p2 - vec2(0.0, uInhibitorRate * 0.3))
  ) * 0.25;
  float react2 = (n2Point - n2Avg) * (uActivatorRate * 0.8);

  // --- Scale 3: fine detail, stripe-dominant at high mids ---
  float s3 = 4.7 + midsVal * 1.0;
  vec2 p3 = baseP * s3 + timeOffset * 0.7 + vec2(53.1, 97.2);
  float n3Point = valueNoise(p3);
  float n3Avg = (
    valueNoise(p3 + vec2(uInhibitorRate * 0.2, 0.0)) +
    valueNoise(p3 + vec2(0.0, uInhibitorRate * 0.2)) +
    valueNoise(p3 - vec2(uInhibitorRate * 0.2, 0.0)) +
    valueNoise(p3 - vec2(0.0, uInhibitorRate * 0.2))
  ) * 0.25;
  float react3 = (n3Point - n3Avg) * (uActivatorRate * 0.6);

  // --- Scale 4: very fine, adds texture ---
  float s4 = 8.1;
  vec2 p4 = baseP * s4 + timeOffset * 1.7 + vec2(71.4, 43.8);
  float n4Point = valueNoise(p4);
  float n4Avg = (
    valueNoise(p4 + vec2(uInhibitorRate * 0.15, 0.0)) +
    valueNoise(p4 + vec2(0.0, uInhibitorRate * 0.15)) +
    valueNoise(p4 - vec2(uInhibitorRate * 0.15, 0.0)) +
    valueNoise(p4 - vec2(0.0, uInhibitorRate * 0.15))
  ) * 0.25;
  float react4 = (n4Point - n4Avg) * (uActivatorRate * 0.4);

  // --- Scale 5: ultra-fine shimmer driven by treble ---
  float s5 = 14.0;
  vec2 p5 = baseP * s5 + timeOffset * 2.3 + vec2(113.5, 137.9);
  float n5Point = valueNoise(p5);
  float react5 = n5Point * (trebleVal * 0.3);

  // Combine reaction-diffusion layers
  float reaction = react1 * 0.35 + react2 * 0.25 + react3 * 0.2 + react4 * 0.12 + react5 * 0.08;

  // Map to 0-1 range with activator boost
  float pattern = clamp(reaction + 0.5 + uChaos * 0.2, 0.0, 1.0);

  // Beat ripple disturbance: concentric rings from center
  float distFromCenter = p.x * p.x + p.y * p.y;
  float ripple = sin(distFromCenter * 20.0 - time * 4.0) * 0.5 + 0.5;
  float beatRipple = ripple * (beatPulse * 0.4);
  float disturbed = clamp(pattern + beatRipple, 0.0, 1.0);

  // Color: cosine palette
  float palT = disturbed + time * 0.03;
  vec3 col = cosinePalette(palT, uPalette);

  // Intensity and brightness
  float brightness = uIntensity * 1.3 + uEnergy * uSensitivity * 0.25;
  float litR = col.x * brightness;
  float litG = col.y * brightness;
  float litB = col.z * brightness;

  // Beat pulse brightness flash
  float flash = beatPulse * 0.15;
  float finalR = litR + flash;
  float finalG = litG + flash;
  float finalB = litB + flash;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPetalLayers;
uniform float uBloomRate;
uniform float uCenterGlow;

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float n = i.x + i.y * 57.0;
  return mix(
    mix(hash(n), hash(n + 1.0), f.x),
    mix(hash(n + 57.0), hash(n + 58.0), f.x),
    f.y
  );
}

// Petal shape function: cardioid-like
float petalShape(float angle, float petalCount, float phase) {
  float a = mod(angle + phase, 6.2832 / petalCount) * petalCount;
  return pow(abs(cos(a * 0.5)), 1.5);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickPulse = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  float angle = atan(p.y, p.x);
  float radius = length(p);

  // === BREATHING RHYTHM ===
  float breath = sin(time * uBloomRate * 2.0) * 0.5 + 0.5;
  breath += bassVal * 0.3 + kickPulse * 0.4;
  breath = clamp(breath, 0.0, 1.0);
  float bloomScale = 0.7 + breath * 0.5;

  // Adjust radius by bloom
  float adjRadius = radius / bloomScale;

  // === PETAL LAYERS ===
  vec3 col = vec3(0.01, 0.005, 0.02);
  float layers = floor(uPetalLayers + 1.0);

  for (int i = 0; i < 8; i++) {
    if (float(i) >= layers) break;
    float fi = float(i);
    float layerIdx = fi / layers;

    // Each layer has different petal count and rotation
    float petalCount = 6.0 + fi * 2.0;
    float layerPhase = fi * 0.5 + time * (0.1 + fi * 0.02);
    float layerRotation = time * 0.05 * (1.0 + fi * 0.3) + midsVal * 0.2 * fi;

    float petal = petalShape(angle + layerRotation, petalCount, layerPhase);

    // Layer radius band — expanded to fill screen
    float innerR = 0.02 + fi * 0.18;
    float outerR = innerR + 0.22 + breath * 0.12;
    float layerMask = smoothstep(innerR, innerR + 0.04, adjRadius) *
                      smoothstep(outerR + 0.04, outerR, adjRadius);

    // Petal intensity
    float petalVal = petal * layerMask;

    // Color per layer: cycle through jewel palette
    float hue = uPalette * 0.3 + fi * 0.15 + time * 0.03 + midsVal * 0.2;
    vec3 petalColor = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * hue + vec3(0.0, 0.15, 0.35)));

    // Brighten outer petals more
    petalColor *= (0.6 + fi * 0.08);

    // Edge shimmer from treble
    float edgeShimmer = smoothstep(0.02, 0.0, abs(adjRadius - outerR)) * trebleVal * 1.5;
    petalColor += vec3(1.0, 0.9, 0.8) * edgeShimmer;

    col += petalColor * petalVal;
  }

  // === CENTER GLOW (divine light) ===
  float centerDist = adjRadius;
  float glow = exp(-centerDist * (6.0 - uCenterGlow * 3.0));
  glow *= (0.8 + beatVal * 0.5 + kickPulse * 0.5);

  // Center color: warm gold to white
  vec3 centerColor = mix(
    vec3(1.0, 0.85, 0.4),
    vec3(1.0, 1.0, 0.95),
    glow
  );
  col += centerColor * glow * uCenterGlow;

  // === MANDALA LINES — extended to screen edges ===
  float radialLines = abs(sin(angle * 12.0 + time * 0.2));
  radialLines = smoothstep(0.97, 1.0, radialLines);
  radialLines *= smoothstep(0.02, 0.1, adjRadius);
  col += vec3(1.0, 0.9, 0.7) * radialLines * 0.15;

  // Circular rings — extended to screen edges
  float rings = abs(sin(adjRadius * 14.0 - time * 0.5));
  rings = smoothstep(0.97, 1.0, rings);
  rings *= smoothstep(0.02, 0.1, adjRadius);
  col += vec3(0.9, 0.8, 1.0) * rings * 0.12;

  // === BACKGROUND AMBIENT — fills entire screen ===
  float bgGlow = exp(-radius * 0.8) * 0.15;
  col += vec3(0.15, 0.05, 0.2) * bgGlow;

  // Outer ambient glow so edges are never pure black
  float outerGlow = 0.04 + 0.03 * sin(angle * 6.0 + time * 0.3);
  col += vec3(0.08, 0.03, 0.12) * outerGlow;

  // Onset flash
  col += vec3(1.0, 0.95, 0.85) * onsetFlash * 0.3 * smoothstep(1.2, 0.0, radius);

  // Chaos: noise overlay
  float chaosNoise = noise(p * 10.0 + time) * uChaos * 0.15;
  col += col * chaosNoise;

  // Global intensity
  col *= uIntensity * 1.1 + energyVal * 0.2;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col.r, 0.0, 1.0), clamp(col.g, 0.0, 1.0), clamp(col.b, 0.0, 1.0), 1.0);
}

