__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRecursionDepth;
uniform float uRotPerLevel;
uniform float uColorDrift;
uniform float uZoomAccel;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// Content pattern for each recursion level
vec3 levelPattern(vec2 uv, float level, float time, float bassVal, float midsVal) {
  // Psychedelic swirl pattern
  float angle = atan(uv.y, uv.x);
  float radius = length(uv);

  float pattern = sin(angle * 6.0 + radius * 8.0 - time * 2.0 + level * 1.5);
  pattern += sin(angle * 3.0 - radius * 12.0 + time * 1.5) * 0.5;
  pattern += noise(uv * 4.0 + time * 0.3 + level) * 0.3;

  // Audio modulation
  pattern += bassVal * sin(radius * 10.0 - time * 3.0) * 0.4;
  pattern += midsVal * sin(angle * 8.0 + time * 2.0) * 0.3;

  float t = pattern * 0.3 + 0.5;

  // Color based on level and pattern
  float hue = t + level * 0.15 + time * 0.04 + sin(time * 0.3) * 0.15;
  vec3 col = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.0, 0.33, 0.67)));

  // Intensity variation
  col *= 0.5 + t * 0.5;

  return col;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;

  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float kickVal = uKick * uSensitivity * 1.5;
  float energyVal = uEnergy * uSensitivity * 1.5;

  // Continuous zoom
  float zoomSpeed = 0.5 + energyVal * 1.5 + kickVal * uZoomAccel * 2.0;
  float totalZoom = time * zoomSpeed;

  // Which recursion level we're at (logarithmic)
  float logZoom = totalZoom;
  float level = floor(logZoom);
  float levelFract = fract(logZoom);

  // Scale factor between levels
  float scaleFactor = 3.0 + uZoom;
  float currentScale = pow(scaleFactor, levelFract);

  int maxLevels = int(4.0 + uRecursionDepth * 6.0);

  vec3 col = vec3(0.0);

  // Render multiple recursion levels
  for (int i = 0; i < 10; i++) {
    if (i >= maxLevels) break;
    float li = float(i);
    float thisLevel = level + li;

    // Scale UV for this level
    float scale = currentScale * pow(scaleFactor, li);
    vec2 levelUV = p / scale;

    // Rotation per level
    float rot = thisLevel * uRotPerLevel * 0.5 + uBpmSin * 0.2;
    float cr = cos(rot), sr = sin(rot);
    levelUV = vec2(levelUV.x * cr - levelUV.y * sr, levelUV.x * sr + levelUV.y * cr);

    // Check if within the "frame" at this level
    float frame = max(abs(levelUV.x), abs(levelUV.y));

    if (frame < 0.9) {
      // Inner area — recursive content
      float borderDist = 0.9 - frame;
      float borderGlow = smoothstep(0.1, 0.0, borderDist);

      // Content for this level
      vec3 levelCol = levelPattern(levelUV, thisLevel, time, bassVal, midsVal);

      // Color drift per level
      float drift = thisLevel * uColorDrift * 0.1;
      levelCol = mix(levelCol, levelCol.gbr, fract(drift));

      // Depth fade (deeper levels dimmer)
      float depthFade = 1.0 / (1.0 + li * 0.3);

      // Frame border
      vec3 borderColor = 0.5 + 0.5 * cos(6.2832 * (thisLevel * 0.1 + uPalette + vec3(0.0, 0.33, 0.67)));
      levelCol = mix(levelCol, borderColor * 1.5, borderGlow * 0.5);

      col += levelCol * depthFade * (1.0 / float(i + 1));
    } else if (frame < 1.0) {
      // Frame border area
      vec3 borderColor = 0.5 + 0.5 * cos(6.2832 * (thisLevel * 0.1 + uPalette + vec3(0.0, 0.33, 0.67)));
      float borderMask = smoothstep(1.0, 0.9, frame);
      col += borderColor * borderMask * 0.3 / (1.0 + li * 0.5);
    }
