  // Normalize accumulated color
  col = clamp(col, 0.0, 1.5);

  // Tunnel depth effect — radial acceleration feel
  float tunnelEffect = exp(-length(p) * 0.5) * 0.1;
  col += tunnelEffect * vec3(0.5, 0.3, 0.8) * energyVal;

  // Beat pulse
  col += uBeat * uSensitivity * col * 0.15;

  // Kick zoom flash
  col += kickVal * vec3(0.2, 0.1, 0.3) * 0.3 * exp(-length(p) * 2.0);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

