  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

// Dendrite branch pattern using polar fractal
float dendrite(vec2 p, float time, float branches, float depth) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float result = 0.0;

  float amp = 1.0;
  float freq = branches;
  for (float i = 0.0; i < 6.0; i++) {
    if (i >= depth * 6.0) break;

    // Branch splitting at each level
    float branchAngle = abs(sin(a * freq + i * 1.5 + time * 0.3));
    float branchDist = abs(r - 0.22 * (i + 1.0));

    // Thin branch line
    float branch = exp(-branchDist * branchDist * (120.0 + i * 60.0));
    branch *= branchAngle;
    branch *= amp;

    result += branch;
    amp *= 0.7;
    freq *= 2.0;
  }
  return result;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  float r = length(p);
  float a = atan(p.y, p.x);

  vec3 col = vec3(0.01, 0.005, 0.02); // Deep dark background

  // Number of main branches
  float branches = floor(5.0 + uDendriteDensity * 8.0);

  // Signal propagation wave (from center outward)
  float propSpeed = uPropagationSpeed * 4.0 + 1.0;
  float signalWave = fract(time * propSpeed * 0.3);
  float signalFront = signalWave * 2.0;

  // Activation: kick triggers a new cascade
  float activation = kickVal * 2.0;

  // Multiple dendrite layers for depth
  for (float layer = 0.0; layer < 4.0; layer++) {
    float layerRot = layer * 0.7 + time * 0.1;
    float cs = cos(layerRot), sn = sin(layerRot);
    vec2 rp = mat2(cs, -sn, sn, cs) * p;

    // Scale per layer
    rp *= 1.0 + layer * 0.3;

    float d = dendrite(rp, time, branches, uBranchDepth);

    // Signal propagation: light travels outward from center
    float layerR = length(rp);
    float signalActive = smoothstep(signalFront - 0.3, signalFront, layerR);
    signalActive *= smoothstep(signalFront + 0.1, signalFront, layerR);
    signalActive += activation * exp(-layerR * 3.0);

    // Map spectral bands to branch families
    float spectrumIndex = mod(layer * 2.0, 8.0);
    float spectrumVal = 0.5;
    if (spectrumIndex < 2.0) spectrumVal = bassVal;
    else if (spectrumIndex < 5.0) spectrumVal = midsVal;
    else spectrumVal = trebleVal;

    // Color: electric blue / gold
    vec3 blueGlow = vec3(0.2, 0.5, 1.0);
    vec3 goldGlow = vec3(1.0, 0.8, 0.3);
    float colorMix = layer / 4.0 + uPalette * 0.3;
    vec3 branchColor = mix(blueGlow, goldGlow, fract(colorMix));

    // Brightness: dendrite pattern * signal activation * spectrum
    float brightness = d * (0.2 + signalActive * 0.8) * (0.5 + spectrumVal);
    brightness *= 1.0 / (1.0 + layer * 0.3);

    col += brightness * branchColor;
  }

  // Soma (cell body) glow at center
  float soma = exp(-r * r * 8.0);
  vec3 somaColor = mix(vec3(0.3, 0.6, 1.0), vec3(1.0, 0.9, 0.4), energyVal);
  col += soma * somaColor * (0.5 + activation);

  // Synaptic sparkles at branch tips
  float sparkle = pow(noise(p * 30.0 + time * 5.0), 6.0) * trebleVal;
  col += sparkle * vec3(0.8, 0.9, 1.0) * 0.3;

  // Flux-driven ambient glow
  col += fluxVal * 0.05 * vec3(0.3, 0.4, 0.8);

  // BPM breathing
  col *= 0.9 + (uBpmSin * 0.5 + 0.5) * 0.15;

  // Chaos: organic noise overlay
  col *= 1.0 + (noise(p * 8.0 + time) - 0.5) * uChaos * 0.3;

  // Mids: warmth in mid-branches
  col += midsVal * 0.04 * vec3(0.7, 0.5, 0.3);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Ring density with particle variation
float ringDensity(float r, float ringR, float ringWidth, float angle, float time, float idx) {
  float dist = abs(r - ringR);
  float profile = smoothstep(ringWidth, ringWidth * 0.3, dist);

  // Particle density variation along the ring
  float particles = noiseVal(vec2(angle * 5.0 + idx * 10.0, time * 0.5 + idx));
  particles = 0.5 + 0.5 * particles;

  // Gaps (Cassini-like divisions)
  float gaps = 1.0;
  float gapFreq = 3.0 + idx * 2.0;
  gaps *= smoothstep(0.0, 0.02, abs(sin(r * gapFreq * 10.0)));

  return profile * particles * gaps;
}

// Ring color based on index and audio
vec3 ringColor(float idx, float totalRings, float audioLvl, float palShift) {
  float hue = fract(idx / totalRings * 0.7 + palShift * 0.3 + 0.1);
  float sat = 0.5 + 0.3 * sin(idx * 1.5);
  float val = 0.6 + 0.4 * audioLvl;

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

// Backlight glow effect
vec3 backlightGlow(vec2 p, float time) {
  vec2 lightPos = vec2(0.0, -0.5 + sin(time * 0.2) * 0.3);
  float dist = length(p - lightPos);
  vec3 glow = vec3(1.0, 0.75, 1.0) * 0.45 / (dist * dist + 0.1);
  return glow;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Tilt the ring plane (3D to 2D projection)
  float tiltAngle = 0.35 + sin(time * 0.1) * 0.1 + bassVal * 0.2;
  vec2 ringP = vec2(p.x, p.y / (0.3 + tiltAngle));

  float r = length(ringP);
  float angle = atan(ringP.y, ringP.x);

  // Background: deep space
  vec3 col = vec3(0.01, 0.005, 0.02);

  // Central planet body
  float planetR = 0.35 + bassVal * 0.16;
  float planetDist = length(p);
  if (planetDist < planetR) {
    float planetSurface = noiseVal(p * 5.0 + time * 0.1);
    vec3 planetCol = mix(vec3(0.4, 0.25, 0.15), vec3(0.65, 0.5, 0.3), planetSurface);
    // Atmospheric banding
    planetCol += vec3(0.1) * sin(p.y * 30.0 + time * 0.5);
    float planetEdge = smoothstep(planetR, planetR - 0.05, planetDist);
    col = mix(col, planetCol, planetEdge);
  }

  // Ring shadow on planet
  float shadowAngle = sin(time * 0.15) * 0.3;
  float shadow = 0.0;

  // Concentric rings (12 rings)
  float totalRings = 12.0;
  float ringAccum = 0.0;
  vec3 ringCol = vec3(0.0);

  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    float ringR = 0.5 + fi * 0.12 + sin(fi * 0.8) * 0.03;

    // Audio modulates ring spacing
    ringR += bassVal * 0.04 * sin(fi * 1.5);
    ringR += midsVal * 0.02 * cos(fi * 2.0);

    float ringWidth = 0.035 + fi * 0.005;

    // Each ring rotates at different speed
    float rotSpeed = (0.2 + fi * 0.05) * (mod(fi, 2.0) < 1.0 ? 1.0 : -1.0);
    float rotAngle = angle + time * rotSpeed;

    // Ring audio level from spectrum
    float audioLvl = 0.0;
    if (fi < 2.0) audioLvl = uSpectrum0;
    else if (fi < 4.0) audioLvl = uSpectrum1;
    else if (fi < 5.0) audioLvl = uSpectrum2;
    else if (fi < 6.0) audioLvl = uSpectrum3;
    else if (fi < 8.0) audioLvl = uSpectrum4;
    else if (fi < 9.0) audioLvl = uSpectrum5;
    else if (fi < 10.0) audioLvl = uSpectrum6;
    else audioLvl = uSpectrum7;
    audioLvl *= uSensitivity;

    float density = ringDensity(r, ringR, ringWidth, rotAngle, time, fi);
    vec3 rCol = ringColor(fi, totalRings, audioLvl, uPalette);

    // Ring brightness modulated by audio
    density *= 0.5 + audioLvl * 2.0;

    ringCol += rCol * density;
    ringAccum += density;
  }

  col += ringCol;

  // Backlit glow (behind rings)
  vec3 backlight = backlightGlow(p, time);
  col += backlight * (0.2 + ringAccum * 0.1);

  // Ring interference patterns (Moire)
  float moire = sin(r * 80.0 + angle * 3.0 + time) * 0.5 + 0.5;
  col += vec3(0.15, 0.08, 0.22) * moire * ringAccum * 0.35;

  // Dust particles in gaps
  float dust = noiseVal(ringP * 20.0 + time * 0.3);
  dust = pow(dust, 5.0) * trebleVal;
  col += vec3(0.65, 0.5, 0.4) * dust * 0.45;

  // Kick: ring flash
  col += vec3(0.4, 0.3, 0.65) * uKick * uSensitivity * 0.6 * ringAccum;

  // Onset: new ring wave
  float onsetWave = sin(r * 30.0 - uOnset * 40.0) * uOnset * uSensitivity;
  col += vec3(0.65, 0.85, 1.0) * max(0.0, onsetWave) * 0.4;

  // BPM pulse
  col *= 1.0 + uBpmSin * 0.06 * uSensitivity;

  // Edge glow on outer ring
  float outerGlow = smoothstep(1.8, 2.0, r) * smoothstep(2.5, 2.0, r);
  col += vec3(0.3, 0.15, 0.55) * outerGlow * (0.3 + bassVal * 2.0);

  // Spectral centroid shifts ring color temperature
  col = mix(col, col * vec3(0.9, 1.0, 1.2), uSpectralCentroid * uSensitivity * 0.2);

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSymmetry;
uniform float uRingCount;
uniform float uLineWidth;
uniform float uRotationRate;

// Cosine palette
vec3 cosinePalette(float t, float phase) {
  float TWO_PI = 6.28318530718;
  float shifted = t + phase;
  float r = 0.5 + 0.5 * cos(TWO_PI * (1.0 * shifted + 0.0));
  float g = 0.5 + 0.5 * cos(TWO_PI * (1.0 * shifted + 0.33));
  float b = 0.5 + 0.5 * cos(TWO_PI * (1.0 * shifted + 0.67));
  return vec3(r, g, b);
}

void main() {
  // Center UV and apply zoom -- scale up shapes (smaller divisor = bigger shapes)
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // --- Audio-reactive modulation ---
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  float bassExpand = bassVal * 0.3;
  float midRotation = midsVal * 0.5;

  // --- Organic breathing (strong, continuous) ---
  float breathAmt = 0.15 + bassVal * 0.2;
  float breathScale = 1.0 + breathAmt * sin(time * 0.6 + bassVal * 2.0)
                     + 0.05 * sin(time * 1.3);

  vec3 bp = vec3(p.x * breathScale, p.y * breathScale, 0.0);

  // --- Polar coordinates ---
  float radius = pow(bp.x * bp.x + bp.y * bp.y, 0.5);
  float angle = atan(bp.y, bp.x);

  // Organic edge wobble
  float wobbleFreq = 7.0 + uChaos * 5.0;
  float wobbleAmt = 0.015 + uChaos * 0.02 + bassVal * 0.01;
  float wobble = sin(angle * wobbleFreq + time * 1.5) * wobbleAmt
    + sin(angle * (wobbleFreq * 1.7) - time * 2.3) * (wobbleAmt * 0.5);
  float r = radius + wobble - bassExpand * 0.1;

  // Rotate with time + mids
  float rotAngle = angle + time * uRotationRate + midRotation;

  // --- Color cycling base ---
  float colorTime = time * 0.12 + uPalette * 0.25 + bassVal * 0.15;

  // --- Rotational symmetry ---
  float PI = 3.141592653589793;
  float TWO_PI = PI * 2.0;

  float n = max(floor(uSymmetry + 0.5), 2.0);
  float sectorAngle = TWO_PI / n;
  float halfSector = sectorAngle * 0.5;

  // Use mod that handles negative angles properly (GLSL mod can return negative)
  float localAngle = rotAngle - floor(rotAngle / sectorAngle) * sectorAngle;
  // Ensure positive range
  localAngle = localAngle - floor(localAngle / sectorAngle) * sectorAngle;
  float folded = abs(localAngle - halfSector);

  float toroidal = folded * PI / halfSector;
  float toroidalX = cos(toroidal) * r;
  float toroidalY = sin(toroidal) * r;

  // --- Concentric rings ---
  float ringPhase = r * (uRingCount + bassExpand * 2.0);
  float ringPattern = fract(ringPhase);
  float ringDist = abs(ringPattern - 0.5);
  float rings = smoothstep(uLineWidth + 0.01, uLineWidth, ringDist);

  // --- Radial lines (use folded sector angle for seamless symmetry) ---
  float radialDist = abs(sin(folded * n));
  float radials = smoothstep(uLineWidth * 2.0 + 0.01, uLineWidth * 2.0, radialDist)
    * smoothstep(0.05, 0.15, r);

  // --- Flower of Life: 7 overlapping circles (scaled up) ---
  float flowerR = 0.40 + uChaos * 0.05
    + bassVal * 0.10
    + sin(time * 0.5) * 0.04;

  // Center circle
  float d0 = pow(bp.x * bp.x + bp.y * bp.y, 0.5);
  float edge0 = abs(d0 - flowerR);
  float ring0 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge0);

  // Circle 1: angle 0
  float c1x = flowerR * cos(0.0);
  float c1y = flowerR * sin(0.0);
  float d1 = pow((bp.x - c1x) * (bp.x - c1x) + (bp.y - c1y) * (bp.y - c1y), 0.5);
  float edge1 = abs(d1 - flowerR);
  float ring1 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge1);

  // Circle 2: angle PI/3
  float a2 = PI / 3.0;
  float c2x = flowerR * cos(a2);
  float c2y = flowerR * sin(a2);
  float d2 = pow((bp.x - c2x) * (bp.x - c2x) + (bp.y - c2y) * (bp.y - c2y), 0.5);
  float edge2 = abs(d2 - flowerR);
  float ring2 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge2);

  // Circle 3: angle 2*PI/3
  float a3 = PI * 2.0 / 3.0;
  float c3x = flowerR * cos(a3);
  float c3y = flowerR * sin(a3);
  float d3 = pow((bp.x - c3x) * (bp.x - c3x) + (bp.y - c3y) * (bp.y - c3y), 0.5);
  float edge3 = abs(d3 - flowerR);
  float ring3 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge3);

  // Circle 4: angle PI
  float c4x = flowerR * cos(PI);
  float c4y = flowerR * sin(PI);
  float d4 = pow((bp.x - c4x) * (bp.x - c4x) + (bp.y - c4y) * (bp.y - c4y), 0.5);
  float edge4 = abs(d4 - flowerR);
  float ring4 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge4);

  // Circle 5: angle 4*PI/3
  float a5 = PI * 4.0 / 3.0;
  float c5x = flowerR * cos(a5);
  float c5y = flowerR * sin(a5);
  float d5 = pow((bp.x - c5x) * (bp.x - c5x) + (bp.y - c5y) * (bp.y - c5y), 0.5);
  float edge5 = abs(d5 - flowerR);
  float ring5 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge5);

  // Circle 6: angle 5*PI/3
  float a6 = PI * 5.0 / 3.0;
  float c6x = flowerR * cos(a6);
  float c6y = flowerR * sin(a6);
  float d6 = pow((bp.x - c6x) * (bp.x - c6x) + (bp.y - c6y) * (bp.y - c6y), 0.5);
  float edge6 = abs(d6 - flowerR);
  float ring6 = smoothstep(uLineWidth + 0.005, uLineWidth * 0.3, edge6);

  // Combined Flower of Life
  float flowerGeom = clamp(
    ring0 + ring1 + ring2 + ring3 + ring4 + ring5 + ring6,
    0.0, 1.0
  );

  // --- Interference at circle overlaps ---
  float inside0 = smoothstep(flowerR + 0.01, flowerR - 0.01, d0);
  float inside1 = smoothstep(flowerR + 0.01, flowerR - 0.01, d1);
  float inside2 = smoothstep(flowerR + 0.01, flowerR - 0.01, d2);
  float inside3 = smoothstep(flowerR + 0.01, flowerR - 0.01, d3);
  float inside4 = smoothstep(flowerR + 0.01, flowerR - 0.01, d4);
  float inside5 = smoothstep(flowerR + 0.01, flowerR - 0.01, d5);
  float inside6 = smoothstep(flowerR + 0.01, flowerR - 0.01, d6);
  float overlap = inside0 + inside1 + inside2 + inside3 + inside4 + inside5 + inside6;
  float interference = smoothstep(1.5, 2.5, overlap) * 0.6;
  float sparkle = interference * (trebleVal * 1.5 + 0.5);

  // --- Hexagonal lattice ---
  float hexScale = 4.0 + uChaos * 2.0;
  float hx = bp.x * hexScale;
  float hy = bp.y * hexScale;
  float hexQ = hx * 0.6667 - hy * 0.3333;
  float hexR2 = hy * 0.6667;
  float hexFracQ = fract(hexQ + 0.5) - 0.5;
  float hexFracR = fract(hexR2 + 0.5) - 0.5;
  float hexDist = (abs(hexFracQ) + abs(hexFracR) + abs(hexFracQ + hexFracR)) * 0.5;
  float hexEdge = smoothstep(0.48, 0.44, hexDist);
  float hexBreath = hexEdge * (0.3 + sin(time * 0.6 + radius * 3.0) * 0.15);

  // --- Sacred geometry (scaled up, morphing between polygon SDFs) ---
  float morphT = sin(time * 0.3) * 0.5 + 0.5;
  float morphT2 = sin(time * 0.2 + 1.0) * 0.5 + 0.5; // second morph phase

  // Morphing polygon SDF: interpolate between triangle and hexagon
  // Triangle SDF in folded space
  float triAngle = folded;
  float triSides = 3.0;
  float triSector = TWO_PI / triSides;
  float triFolded = abs(triAngle - floor(triAngle / triSector + 0.5) * triSector);
  float triDist = r * cos(triFolded) / cos(triSector * 0.5);
  float triR = 0.35 + sin(time * 0.6) * 0.05 + bassVal * 0.08;
  float triShape = smoothstep(triR + 0.015, triR, triDist);

  // Hexagon SDF in folded space
  float hexSides = 6.0;
  float hexSector2 = TWO_PI / hexSides;
  float hexFolded2 = abs(triAngle - floor(triAngle / hexSector2 + 0.5) * hexSector2);
  float hexDist2 = r * cos(hexFolded2) / cos(hexSector2 * 0.5);
  float hexR2b = 0.38 + sin(time * 0.5 + 0.5) * 0.04 + bassVal * 0.06;
  float hexShape = smoothstep(hexR2b + 0.015, hexR2b, hexDist2);

  // Morph between triangle and hexagon
  float polyMorph = mix(triShape, hexShape, morphT2);

  float innerTx = toroidalX - 0.4 * cos(PI * 0.5);
  float innerTy = toroidalY - 0.4 * sin(PI * 0.5);
  float innerFlower = innerTx * innerTx + innerTy * innerTy;
  float innerFlowerR = 0.32 + uChaos * 0.06 + sin(time * 0.7) * 0.04;
  float flower1 = smoothstep(innerFlowerR + 0.01, innerFlowerR, pow(innerFlower, 0.5));

  float outerTx = toroidalX - 0.7 * cos(PI * 0.5);
  float outerTy = toroidalY - 0.7 * sin(PI * 0.5);
  float outerFlower = outerTx * outerTx + outerTy * outerTy;
  float outerFlowerR = 0.32 + uChaos * 0.06 + sin(time * 0.5) * 0.04;
  float flower2 = smoothstep(outerFlowerR + 0.01, outerFlowerR, pow(outerFlower, 0.5));

  float sacredMorph = mix(flower1 * 0.6, flower2 * 0.4, morphT) + polyMorph * 0.5;

  // --- Metatron's cube: connecting diagonals ---
  float diagAngle = toroidal + time * 0.1 * (uChaos + 0.2);
  float diagPattern = abs(sin(diagAngle * 3.0 + r * 6.0));
  float diagonals = smoothstep(uLineWidth * 3.0 + 0.01, uLineWidth * 3.0, diagPattern)
    * smoothstep(0.1, 0.3, r)
    * smoothstep(0.8, 0.6, r);

  // --- Combine geometry layers ---
  float geometry = clamp(
    rings * 0.7
      + radials * 0.5
      + flowerGeom * 0.8
      + sparkle
      + hexBreath * 0.4
      + sacredMorph
      + diagonals * 0.4,
    0.0,
    1.0
  );

  // --- Beat burst ---
  float burstRadius = uBeat * uSensitivity * 0.8;
  float burstDist = abs(r - burstRadius);
  float burst = smoothstep(0.08, 0.01, burstDist) * uBeat * uSensitivity;

  // --- Multi-phase cosine rainbow color cycling ---
  float ringColorPhase = colorTime + r * 0.3;
  float flowerColorPhase = colorTime + 0.25 + radius * 0.2 + midsVal * 0.1;
  float hexColorPhase = colorTime + 0.5 + folded / sectorAngle * 0.3;
  float sacredColorPhase = colorTime + 0.75 + trebleVal * 0.2;
  float burstColorPhase = colorTime + 0.15 + uBeat * 0.3;

  vec3 ringColor = cosinePalette(fract(ringColorPhase), uPalette * 0.1);
  vec3 flowerColor = cosinePalette(fract(flowerColorPhase), uPalette * 0.1 + 0.15);
  vec3 hexColor = cosinePalette(fract(hexColorPhase), uPalette * 0.1 + 0.33);
  vec3 sacredColor = cosinePalette(fract(sacredColorPhase), uPalette * 0.1 + 0.5);
  vec3 burstColor = cosinePalette(fract(burstColorPhase), uPalette * 0.1 + 0.67);

  float ringWeight = rings * 0.7 + radials * 0.5;
  float flowerWeight = flowerGeom * 0.8 + sparkle;
  float hexWeight = hexBreath * 0.4;
  float sacredWeight = sacredMorph + diagonals * 0.4;
  float burstWeight = burst;

  float totalWeight = ringWeight + flowerWeight + hexWeight + sacredWeight + burstWeight + 0.001;

  float blendedR = (ringColor.x * ringWeight
    + flowerColor.x * flowerWeight
    + hexColor.x * hexWeight
    + sacredColor.x * sacredWeight
    + burstColor.x * burstWeight) / totalWeight;
  float blendedG = (ringColor.y * ringWeight
    + flowerColor.y * flowerWeight
    + hexColor.y * hexWeight
    + sacredColor.y * sacredWeight
    + burstColor.y * burstWeight) / totalWeight;
  float blendedB = (ringColor.z * ringWeight
    + flowerColor.z * flowerWeight
    + hexColor.z * hexWeight
    + sacredColor.z * sacredWeight
    + burstColor.z * burstWeight) / totalWeight;

  vec3 blendedColor = vec3(blendedR, blendedG, blendedB);

  // Pure black background
  vec3 dark = vec3(0.0, 0.0, 0.0);

  float luminance = geometry + burst * 0.8;
  vec3 finalColor = mix(dark, blendedColor, luminance);

  float energyBright = uEnergy * uSensitivity * 0.3 + 0.7;
  float brightScale = uIntensity * energyBright;

  float beatBright = uBeat * uSensitivity * 0.12;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.x * brightScale + beatBright, 0.0, 1.0),
    clamp(finalColor.y * brightScale + beatBright, 0.0, 1.0),
    clamp(finalColor.z * brightScale + beatBright, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM with variable roughness (persistence controls texture feel)
float fbmRough(vec2 p, float persistence, int octaves) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  float total = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    val += amp * noiseVal(p * freq);
    total += amp;
    amp *= persistence;
    freq *= 2.0;
  }
  return val / total;
}

// Domain warped roughness
float warpedRoughness(vec2 p, float time, float roughness) {
  vec2 q = vec2(
    fbmRough(p + vec2(0.0, 0.0) + time * 0.1, roughness, 6),
    fbmRough(p + vec2(5.2, 1.3) + time * 0.08, roughness, 6)
  );
  vec2 r = vec2(
    fbmRough(p + 4.0 * q + vec2(1.7, 9.2) + time * 0.06, roughness, 6),
    fbmRough(p + 4.0 * q + vec2(8.3, 2.8) + time * 0.05, roughness, 6)
  );
  return fbmRough(p + 4.0 * r, roughness, 6);
}

// Compute normal from height field using finite differences
vec3 computeNormal(vec2 p, float time, float roughness) {
  float eps = 0.005;
  float center = warpedRoughness(p, time, roughness);
  float dx = warpedRoughness(p + vec2(eps, 0.0), time, roughness) - center;
  float dy = warpedRoughness(p + vec2(0.0, eps), time, roughness) - center;
  vec3 normal = normalize(vec3(-dx * 20.0, -dy * 20.0, 1.0));
  return normal;
}

// Lighting with moving light source
vec3 lightSurface(vec3 normal, vec2 p, float time, vec3 baseColor) {
  // Two light sources orbiting
  vec3 lightDir1 = normalize(vec3(
    sin(time * 0.3) * 1.5,
    cos(time * 0.4) * 1.5,
    1.5
  ));
  vec3 lightDir2 = normalize(vec3(
    -cos(time * 0.25) * 1.0,
    sin(time * 0.35) * 1.0,
    2.0
  ));

  float diff1 = max(dot(normal, lightDir1), 0.0);
  float diff2 = max(dot(normal, lightDir2), 0.0);

  // Specular
  vec3 viewDir = vec3(0.0, 0.0, 1.0);
  vec3 halfDir1 = normalize(lightDir1 + viewDir);
  float spec1 = pow(max(dot(normal, halfDir1), 0.0), 32.0);

  vec3 lightCol1 = vec3(1.0, 0.9, 0.8);
  vec3 lightCol2 = vec3(0.4, 0.5, 0.8);

  vec3 ambient = baseColor * 0.15;
  vec3 diffuse = baseColor * (diff1 * lightCol1 + diff2 * lightCol2 * 0.5);
  vec3 specular = vec3(1.0) * spec1 * 0.5;

  return ambient + diffuse + specular;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Roughness varies across surface and with audio
  float baseRoughness = 0.4 + uChaos * 0.3;
  float roughnessVariation = sin(p.x * 2.0 + time * 0.3) * cos(p.y * 1.5 - time * 0.2) * 0.5 + 0.5;
  float roughness = baseRoughness + roughnessVariation * 0.3;

  // Bass makes rougher (more fractal), treble makes smoother
  roughness += bassVal * 0.15;
  roughness -= trebleVal * 0.1;
  roughness = clamp(roughness, 0.2, 0.85);

  // Height field
  float height = warpedRoughness(p, time, roughness);

  // Second pass at different scale for detail
  float detail = warpedRoughness(p * 3.0, time * 1.2, roughness * 0.8) * 0.3;

  float totalHeight = height + detail;

  // Compute surface normal for lighting
  vec3 normal = computeNormal(p, time, roughness);

  // Perturb normal with audio
  normal.xy += vec2(bassVal, midsVal) * 0.1;
  normal = normalize(normal);

  // Base color from spectral centroid and roughness
  float centroidVal = uSpectralCentroid * uSensitivity;
  float hue = fract(totalHeight * 0.5 + centroidVal * 0.5 + uPalette * 0.2);

  // Smooth surfaces: metallic/cool, rough surfaces: warm/organic
  float sat = 0.4 + roughness * 0.4;
  float val = 0.5 + totalHeight * 0.5;

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  vec3 baseColor = c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);

  // Apply lighting
  vec3 col = lightSurface(normal, p, time, baseColor);

  // Roughness visualization overlay (subtle texture grain)
  float grain = noiseVal(p * 50.0 + time * 2.0);
  col = mix(col, col * (0.8 + grain * 0.4), roughness * 0.3);

  // Edge detection on height for extra definition
  float edgeX = abs(dFdx(totalHeight)) * 30.0;
  float edgeY = abs(dFdy(totalHeight)) * 30.0;
  float edge = clamp(edgeX + edgeY, 0.0, 1.0);
  col += vec3(0.5, 0.6, 0.8) * edge * 0.15;

  // Kick: emboss flash
  col += vec3(0.3) * uKick * uSensitivity * (0.5 + totalHeight);

  // Onset: surface crack reveal
  float crack = pow(noiseVal(p * 15.0 + time * 3.0), 6.0);
  col += vec3(1.0, 0.5, 0.2) * crack * uOnset * uSensitivity * 2.0;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.06 * uSensitivity;

  // Warmth drives color temperature
  col = mix(col, col * vec3(1.2, 1.0, 0.8), uWarmth * uSensitivity * 0.3);

  // Harmonicity adds iridescence
  float iridescence = sin(totalHeight * 20.0 + time) * 0.5 + 0.5;
  col += vec3(0.1, 0.2, 0.3) * iridescence * uHarmonicity * uSensitivity * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSymmetryFold;
uniform float uTunnelSpeed;

// Hash noise
float hash21(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

// 2D value noise
float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  fx = fx * fx * (3.0 - 2.0 * fx);
  fy = fy * fy * (3.0 - 2.0 * fy);
  float a = hash21(ix, iy);
  float b = hash21(ix + 1.0, iy);
  float c = hash21(ix, iy + 1.0);
  float d = hash21(ix + 1.0, iy + 1.0);
  return mix(mix(a, b, fx), mix(c, d, fx), fy);
}

// FBM for pattern complexity
float fbm(float x, float y) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * noise2d(x * freq, y * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Cosine palette
vec3 cosPalette(float t, float shift) {
  return vec3(
    0.5 + 0.5 * cos(6.2832 * (1.0 * t + 0.0 + shift)),
    0.5 + 0.5 * cos(6.2832 * (1.0 * t + 0.33 + shift)),
    0.5 + 0.5 * cos(6.2832 * (1.0 * t + 0.67 + shift))
  );
}

// Triangle wave for geometric patterns
float tri(float x) {
  return abs(fract(x) - 0.5) * 2.0;
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // === POLAR COORDINATES ===
  float radius = sqrt(p.x * p.x + p.y * p.y) + 0.001;
  float angle = atan(p.y, p.x);

  // === KALEIDOSCOPE FOLD ===
  // Number of folds: 6 to 16 based on symmetryFold
  float foldCount = floor(6.0 + uSymmetryFold * 10.0);
  float TAU = 6.2832;
  float sectorSize = TAU / foldCount;

  // Fold the angle into one sector
  float foldedAngle = mod(angle + TAU, sectorSize);
  // Mirror within the sector
  foldedAngle = abs(foldedAngle - sectorSize * 0.5);

  // === TUNNEL Z-DEPTH ===
  float forwardSpeed = uTunnelSpeed * 3.0 + beatPulse * 2.5 + kickVal * 1.0;
  float tunnelZ = 1.0 / (radius + 0.05) + time * forwardSpeed;

  // Bass pulses tunnel diameter (modifies effective radius)
  float bassPulse = 1.0 + bassVal * 0.5 * sin(time * 3.0);
  float effectiveRadius = radius * bassPulse;
  float tunnelZPulsed = 1.0 / (effectiveRadius + 0.05) + time * forwardSpeed;

  // === TUNNEL WALL UV ===
  float wallU = foldedAngle * foldCount / TAU;
  float wallV = tunnelZPulsed;

  // === LAYERED PATTERNS ON TUNNEL WALLS ===
  // Layer 1: Geometric pattern (triangle waves creating diamonds/hexagons)
  float geom1 = tri(wallU * 6.0 + wallV * 0.7);
  float geom2 = tri(wallU * 5.0 - wallV * 1.0 + time * 0.2);
  float geom3 = tri(wallU * 8.0 + wallV * 0.3 - time * 0.15);
  float geometric = geom1 * geom2 * 0.7 + geom3 * 0.3;

  // Layer 2: Noise-based organic pattern
  float noiseDetail = 1.0 + trebleVal * 3.0;
  float n1 = fbm(wallU * 3.0 * noiseDetail + time * 0.15, wallV * 0.8 + time * 0.05);
  float n2 = fbm(wallU * 5.0 * noiseDetail - time * 0.1, wallV * 1.2 - time * 0.08);
  float organic = n1 * 0.6 + n2 * 0.4;

  // Layer 3: Hexagonal grid highlights
  float hexU = wallU * 6.0;
  float hexV = wallV * 2.0;
  float hexCellX = fract(hexU) - 0.5;
  float hexCellY = fract(hexV) - 0.5;
  float hexDist = sqrt(hexCellX * hexCellX + hexCellY * hexCellY);
  float hexRing = smoothstep(0.35, 0.3, hexDist) - smoothstep(0.3, 0.25, hexDist);
  hexRing += smoothstep(0.15, 0.1, hexDist) * 0.5;

  // Combine pattern layers
  float pattern = geometric * 0.35 + organic * 0.4 + hexRing * 0.25 * (1.0 + trebleVal);

  // Chaos adds noise displacement
  pattern += (noise2d(wallU * 8.0 + time * 0.3, wallV * 4.0 - time * 0.2) - 0.5) * uChaos * 0.4;

  // === COLORING ===
  // Color based on depth (tunnelZ), angle, and pattern
  float colorT = pattern * 0.6 + tunnelZ * 0.03 + foldedAngle * 0.5 + midsVal * 0.6;
  float paletteShift = uPalette * 0.25;
  vec3 col1 = cosPalette(colorT, paletteShift);
  vec3 col2 = cosPalette(colorT * 0.7 + 0.3, paletteShift + 0.5);
  vec3 tunnelColor = mix(col1, col2, organic);

  // Saturate the colors
  float lum = dot(tunnelColor, vec3(0.299, 0.587, 0.114));
  tunnelColor = mix(vec3(lum), tunnelColor, 2.0);
  tunnelColor = clamp(tunnelColor, 0.0, 1.0);

  // === DEPTH SHADING (tunnel darkness in distance) ===
  float depthFade = smoothstep(0.0, 0.3, radius);
  tunnelColor *= depthFade;

  // Central glow (looking into the tunnel)
  float centerGlow = smoothstep(0.3, 0.0, radius) * 0.2;
  vec3 glowColor = cosPalette(time * 0.05, paletteShift + 0.3);
  tunnelColor += centerGlow * glowColor;

  // === FOLD EDGE HIGHLIGHTS ===
  float edgeDist = abs(foldedAngle - sectorSize * 0.5);
  float edgeGlow = smoothstep(sectorSize * 0.05, 0.0, edgeDist) * 0.3;
  tunnelColor += edgeGlow * (1.0 + trebleVal);

  // === AUDIO EFFECTS ===
  // Beat: flash acceleration (bright ring at certain depth)
  float beatRing = sin(tunnelZ * 3.0 - time * 10.0) * 0.5 + 0.5;
  tunnelColor += beatPulse * beatRing * 0.2;

  // Onset: color shift burst
  tunnelColor = mix(tunnelColor, tunnelColor.gbr, onsetVal * 0.3);

  // Energy brightness
  tunnelColor += energyVal * 0.06;

  // Intensity
  tunnelColor *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  tunnelColor = psychedelicColor(tunnelColor);
  gl_FragColor = vec4(
    clamp(tunnelColor.r, 0.0, 1.0),
    clamp(tunnelColor.g, 0.0, 1.0),
    clamp(tunnelColor.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uNodeGlow;
uniform float uTriangleLayers;
uniform float uRotationSpeed;

#define PI 3.14159265
#define TAU 6.28318530

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// SDF for equilateral triangle
float sdTriangle(vec2 p, float r) {
  const float k = sqrt(3.0);
  p.x = abs(p.x) - r;
  p.y = p.y + r / k;
  if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
  p.x -= clamp(p.x, -2.0 * r, 0.0);
  return -length(p) * sign(p.y);
}

vec2 rotate2d(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Draw a triangle outline
float triangleLine(vec2 p, float size, float thick) {
  float d = abs(sdTriangle(p, size)) - thick;
  return smoothstep(0.01, 0.0, d);
}

// Energy node at intersection point
float energyNode(vec2 p, vec2 nodePos, float radius, float pulse) {
  float d = length(p - nodePos);
  float core = exp(-d * d / (radius * radius * 0.5)) * pulse;
  float halo = exp(-d * d / (radius * radius * 2.0)) * pulse * 0.4;
  return core + halo;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float aspect = 1.0;
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;

  float zoomFactor = 1.0 + uZoom * 0.5;
  p *= zoomFactor;

  int layers = 5 + int(uTriangleLayers * 6.0);
  float lineThick = 0.005 + trebleVal * 0.003;

  vec3 col = vec3(0.0);

  // Draw concentric triangles
  for (int i = 0; i < 11; i++) {
    if (i >= layers) break;
    float fi = float(i);
    float size = 0.12 + fi * 0.09;
    float rotDir = mod(fi, 2.0) < 1.0 ? 1.0 : -1.0;
    float rot = time * uRotationSpeed * rotDir * 0.5 + uBpmSin * 0.25 * rotDir;

    vec2 rp = rotate2d(p, rot);

    // Upward triangle
    float triUp = triangleLine(rp, size, lineThick);
    // Downward triangle (flip)
    float triDown = triangleLine(vec2(rp.x, -rp.y), size * 0.9, lineThick);

    // Color per layer — more variation between segments
    float hue = fi / float(layers) + uPalette * 0.4 + time * 0.08;
    vec3 triCol = vec3(0.0);
    // Gold/crimson/deep blue/violet palette with more variation
    triCol.r = 0.8 + 0.2 * sin(hue * TAU + fi * 0.5);
    triCol.g = 0.3 + 0.4 * sin(hue * TAU + 1.2 + fi * 0.3);
    triCol.b = 0.2 + 0.7 * sin(hue * TAU + 2.8 + fi * 0.7);

    float brightness = 0.6 + bassVal * 0.6 + beatPulse * 0.5;
    col += triCol * triUp * brightness;
    col += triCol * triDown * brightness * 0.8;

    // Energy nodes at triangle vertices
    float nodeR = 0.03 + uNodeGlow * 0.02;
    float nodePulse = 0.6 + beatPulse * 1.2 + bassVal * 0.7;
    for (int j = 0; j < 3; j++) {
      float angle = float(j) * TAU / 3.0 + rot;
      vec2 nodePos = vec2(cos(angle), sin(angle)) * size;
      float node = energyNode(p, nodePos, nodeR, nodePulse);
      col += vec3(1.0, 0.85, 0.4) * node * uNodeGlow;
    }
  }

  // Central bindu point
  float bindu = exp(-dot(p, p) * 80.0) * (1.0 + beatPulse * 2.0);
  col += vec3(1.0, 0.9, 0.7) * bindu * 2.0;

  // Outer circle
  float outerRing = abs(length(p) - 0.95) - 0.003;
  col += vec3(0.7, 0.5, 0.2) * smoothstep(0.005, 0.0, outerRing) * 0.5;

  // Spectral flux sparkle
  float sparkle = hash(p * 50.0 + time) * uSpectralFlux * uSensitivity * 0.3;
  col += vec3(1.0, 0.95, 0.8) * sparkle;

  // Background glow
  float bgGlow = exp(-dot(p, p) * 0.5) * 0.08;
  col += vec3(0.15, 0.05, 0.25) * bgGlow;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCircleRings;
uniform float uLineGlow;
uniform float uMetatronBlend;

#define PI 3.14159265
#define TAU 6.28318530

vec3 sacredPalette(float t, float offset) {
  return vec3(
    0.5 + 0.5 * cos(TAU * (t + 0.0 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.33 + offset * 0.25)),
    0.5 + 0.5 * cos(TAU * (t + 0.67 + offset * 0.25))
  );
}

// Circle wireframe: returns distance to circle edge
float circleLine(vec2 p, vec2 center, float radius, float width) {
  float d = abs(length(p - center) - radius);
  return smoothstep(width, 0.0, d);
}

// Line segment SDF
float lineSDF(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

float lineGlow(vec2 p, vec2 a, vec2 b, float width) {
  float d = lineSDF(p, a, b);
  return smoothstep(width, 0.0, d);
}

void main() {
  float time = uTime * (uSpeed * 1.0);
  vec2 p = (vUv - 0.5) * 2.0 * (uZoom * 1.5 + 0.5);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Faster rotation
  float rotAngle = time * 0.25 + beatPulse * 0.5;
  float ca = cos(rotAngle);
  float sa = sin(rotAngle);
  p = vec2(p.x * ca - p.y * sa, p.x * sa + p.y * ca);

  // Line width from glow param
  float lw = 0.005 + uLineGlow * 0.02;
  float glowW = lw * (3.5 + bassVal * 6.0);

  // Base radius with bass pulse — expanded to fill screen
  float baseR = 0.7 + bassVal * 0.15;

  // Expansion wave from kick
  float expandWave = kickVal * 0.2;

  float rings = 1.0 + uCircleRings * 3.0;
  int numRings = int(rings);

  float wireframe = 0.0;
  float intersectionGlow = 0.0;

  // Center circle
  wireframe += circleLine(p, vec2(0.0), baseR + expandWave, glowW);

  // Seed of Life: 6 circles around center
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * TAU / 6.0;
    vec2 center = vec2(cos(angle), sin(angle)) * baseR;
    wireframe += circleLine(p, center, baseR + expandWave, glowW);

    // Intersection sparkle points
    for (int j = 0; j < 6; j++) {
      if (j <= i) continue;
      float angle2 = float(j) * TAU / 6.0;
      vec2 center2 = vec2(cos(angle2), sin(angle2)) * baseR;
      vec2 midpoint = (center + center2) * 0.5;
      float sparkDist = length(p - midpoint);
      intersectionGlow += smoothstep(0.03, 0.0, sparkDist) * trebleVal;
    }
  }

  // Additional rings (Flower of Life expansion)
  if (numRings >= 2) {
    for (int i = 0; i < 6; i++) {
      float angle = float(i) * TAU / 6.0 + TAU / 12.0;
      vec2 center = vec2(cos(angle), sin(angle)) * baseR * 1.732;
      wireframe += circleLine(p, center, baseR + expandWave, glowW);
    }
    for (int i = 0; i < 6; i++) {
      float angle = float(i) * TAU / 6.0;
      vec2 center = vec2(cos(angle), sin(angle)) * baseR * 2.0;
      wireframe += circleLine(p, center, baseR + expandWave, glowW);
    }
  }

  if (numRings >= 3) {
    // Third ring
    for (int i = 0; i < 12; i++) {
      float angle = float(i) * TAU / 12.0;
      vec2 center = vec2(cos(angle), sin(angle)) * baseR * 2.5;
      wireframe += circleLine(p, center, baseR + expandWave, glowW * 0.7);
    }
  }

  // Fourth ring for extra detail
  if (numRings >= 4) {
    for (int i = 0; i < 18; i++) {
      float angle = float(i) * TAU / 18.0 + TAU / 36.0;
      vec2 center = vec2(cos(angle), sin(angle)) * baseR * 3.0;
      wireframe += circleLine(p, center, baseR + expandWave, glowW * 0.5);
    }
  }

  // Metatron's Cube: lines connecting circle centers
  float metatron = 0.0;
  if (uMetatronBlend > 0.01) {
    float metaLw = glowW * 0.5;

    // Inner hexagon vertices
    vec2 v0 = vec2(0.0);
    for (int i = 0; i < 6; i++) {
      float a1 = float(i) * TAU / 6.0;
      vec2 vi = vec2(cos(a1), sin(a1)) * baseR;

      // Lines from center to each vertex
      metatron += lineGlow(p, v0, vi, metaLw);

      // Lines between adjacent vertices
      float a2 = float(i + 1) * TAU / 6.0;
      vec2 vj = vec2(cos(a2), sin(a2)) * baseR;
      metatron += lineGlow(p, vi, vj, metaLw);

      // Lines between opposite vertices (star pattern)
      float a3 = float(i + 3) * TAU / 6.0;
      vec2 vk = vec2(cos(a3), sin(a3)) * baseR;
      metatron += lineGlow(p, vi, vk, metaLw);

      // Outer hexagon connections
      float a4 = float(i) * TAU / 6.0;
      vec2 vo = vec2(cos(a4), sin(a4)) * baseR * 2.0;
      metatron += lineGlow(p, vi, vo, metaLw * 0.6);
    }

    // Outer hexagon
    for (int i = 0; i < 6; i++) {
      float a1 = float(i) * TAU / 6.0;
      float a2 = float(i + 1) * TAU / 6.0;
      vec2 vi = vec2(cos(a1), sin(a1)) * baseR * 2.0;
      vec2 vj = vec2(cos(a2), sin(a2)) * baseR * 2.0;
      metatron += lineGlow(p, vi, vj, metaLw * 0.6);
    }
  }

  // Combine wireframe and metatron
  float combined = wireframe + metatron * uMetatronBlend;
  combined = min(combined, 3.0); // clamp accumulation

  // Color based on position and audio — more variation
  float colorT = length(p) * 0.7 + midsVal * 0.5 + time * 0.08 + atan(p.y, p.x) * 0.15;
  vec3 glowColor = sacredPalette(colorT, uPalette);

  // Wireframe color
  vec3 color = glowColor * combined * 0.8;

  // Intersection sparkle
  color += intersectionGlow * vec3(1.0, 0.9, 0.7) * 0.6;

  // Background: subtle radial gradient filling screen
  float bgGrad = exp(-length(p) * 0.3) * 0.08;
  vec3 bgColor = sacredPalette(time * 0.02 + 0.5, uPalette);
  color += bgGrad * bgColor;

  // Outer ambient so edges are never pure black
  color += sacredPalette(time * 0.01, uPalette) * 0.02;

  // Chaos: add subtle rotation wobble (already applied) and color noise
  float chaosNoise = fract(sin(dot(p, vec2(12.9898, 78.233)) + time) * 43758.5) * uChaos * 0.05;
  color += chaosNoise;

  // Beat brightness
  color += beatPulse * combined * 0.25;

  // Onset color shift
  color = mix(color, color.gbr, onsetVal * 0.25);

  // Intensity
  color *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

