uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Molecular node position
vec2 moleculePos(float idx, float time) {
  float angle = idx * 2.399963 + sin(time * 0.2 + idx) * 0.3;
  float radius = 0.3 + sqrt(idx / 20.0) * 1.0;
  vec2 base = vec2(cos(angle), sin(angle)) * radius;
  // Brownian drift
  base += vec2(
    sin(time * 0.15 + idx * 3.7) * 0.2,
    cos(time * 0.12 + idx * 2.3) * 0.2
  );
  return base;
}

// Atom rendering (circle with electron cloud)
float atomGlow(vec2 p, vec2 center, float size) {
  float dist = length(p - center);
  float core = smoothstep(size, size * 0.3, dist);
  float cloud = size * 0.5 / (dist * dist + size * 0.1);
  return core + cloud * 0.3;
}

// Bond between two atoms
float bondLine(vec2 p, vec2 a, vec2 b, float time) {
  vec2 ab = b - a;
  float abLen = length(ab);
  vec2 abNorm = ab / abLen;
  vec2 ap = p - a;
  float t = clamp(dot(ap, abNorm) / abLen, 0.0, 1.0);
  vec2 closest = a + abNorm * t * abLen;
  float dist = length(p - closest);

  // Double bond effect
  float bond = 0.003 / (dist + 0.002);

  // Electron flow along bond
  float flow = sin(t * 20.0 - time * 5.0) * 0.5 + 0.5;
  bond *= 0.7 + flow * 0.3;

  return bond;
}

// Pleasure wave ripple
float pleasureWave(vec2 p, vec2 center, float time, float birthTime) {
  float age = time - birthTime;
  if (age < 0.0 || age > 3.0) return 0.0;
  float radius = age * 0.8;
  float dist = length(p - center);
  float wave = sin((dist - radius) * 25.0) * exp(-abs(dist - radius) * 8.0);
  wave *= exp(-age * 1.5);
  return max(0.0, wave);
}

// Hexagonal ring (benzene-like)
float hexRing(vec2 p, vec2 center, float size, float time) {
  vec2 rel = p - center;
  float angle = atan(rel.y, rel.x);
  float r = length(rel);
  float hex = cos(angle * 3.0) * 0.15 + 0.85;
  float ring = abs(r - size * hex) - 0.01;
  float glow = 0.005 / (abs(ring) + 0.003);
  // Delocalized electrons
  glow += 0.003 / (abs(r - size * 0.6) + 0.005) * (sin(angle * 6.0 + time * 3.0) * 0.5 + 0.5) * 0.5;
  return glow;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  // Warm background glow
  float bgNoise = noiseVal(p * 0.8 + time * 0.05);
  vec3 col = vec3(0.05, 0.03, 0.01) + vec3(0.03, 0.02, 0.01) * bgNoise;

  // Serotonin molecular fragments
  float totalMolecGlow = 0.0;
  float totalBondGlow = 0.0;

  // 16 molecular nodes
  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    vec2 mPos = moleculePos(fi, time);

    // Chaos makes molecules wander more
    mPos += vec2(
      noiseVal(vec2(fi, time * 0.3)) - 0.5,
      noiseVal(vec2(fi + 50.0, time * 0.3)) - 0.5
    ) * uChaos * 0.5;

    float atomSize = 0.04 + 0.02 * sin(fi * 1.5 + time);
    atomSize *= 1.0 + bassVal * 0.3;

    float ag = atomGlow(p, mPos, atomSize);
    totalMolecGlow += ag;

    // Bonds to nearby molecules
    for (int j = 0; j < 16; j++) {
      if (j <= i) continue;
      float fj = float(j);
      vec2 mPos2 = moleculePos(fj, time);
      mPos2 += vec2(
        noiseVal(vec2(fj, time * 0.3)) - 0.5,
        noiseVal(vec2(fj + 50.0, time * 0.3)) - 0.5
      ) * uChaos * 0.5;

      float bondDist = length(mPos - mPos2);
      if (bondDist < 0.6) {
        float bg = bondLine(p, mPos, mPos2, time);
        float bondStrength = smoothstep(0.6, 0.2, bondDist);
        totalBondGlow += bg * bondStrength;
      }
    }
  }

  // Hexagonal rings (indole + pyrrole parts of serotonin)
  vec2 hex1Pos = vec2(sin(time * 0.1) * 0.3, cos(time * 0.08) * 0.2);
  vec2 hex2Pos = hex1Pos + vec2(0.25, 0.15);
  float hexGlow = hexRing(p, hex1Pos, 0.15 + bassVal * 0.03, time);
  hexGlow += hexRing(p, hex2Pos, 0.12 + midsVal * 0.02, time);

  // Golden molecular color
  vec3 gold = vec3(1.0, 0.85, 0.3);
  vec3 amber = vec3(0.9, 0.6, 0.15);
  vec3 warmWhite = vec3(1.0, 0.95, 0.85);
  float palShift = uPalette * 0.2;

  // Atom glow color
  vec3 atomCol = mix(gold, warmWhite, clamp(totalMolecGlow * 0.3 + palShift, 0.0, 1.0));
  col += atomCol * totalMolecGlow * 0.08;

  // Bond glow color
  vec3 bondCol = mix(amber, gold, totalBondGlow * 0.5);
  col += bondCol * totalBondGlow * 0.03;

  // Hex ring color
  col += mix(gold, warmWhite, 0.5) * hexGlow * 0.06;

  // Pleasure wave ripples from connections
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    vec2 waveCenter = moleculePos(fi * 3.0, time);
    float birthTime = floor(time * 0.5 + fi) * 2.0;
    float wave = pleasureWave(p, waveCenter, time, birthTime);
    col += gold * wave * 0.4 * (0.5 + bassVal);
  }

  // Warm radial glow (center of bliss)
  float radialGlow = exp(-length(p) * length(p) * 0.5);
  col += vec3(0.15, 0.1, 0.03) * radialGlow * (1.0 + midsVal * 0.5);

  // Kick: golden flash burst
  col += warmWhite * uKick * uSensitivity * 0.4 * exp(-length(p) * 1.5);

  // Onset: new bond formation flash
  col += gold * uOnset * uSensitivity * 0.3 * totalBondGlow * 0.1;

  // Beat: pulse warmth
  col *= 1.0 + uBeat * uSensitivity * 0.12;

  // BPM breathing
  col *= 1.0 + uBpmSin * 0.08 * uSensitivity;

  // Warmth uniform adds extra golden glow
  col += vec3(0.1, 0.07, 0.02) * uWarmth * uSensitivity;

  // Harmonicity enhances ring glow (resonance)
  col += vec3(0.2, 0.15, 0.05) * hexGlow * uHarmonicity * uSensitivity * 0.05;

  // Spectral flux sparkle
  float sparkle = pow(noiseVal(p * 30.0 + time * 8.0), 10.0);
  col += warmWhite * sparkle * uSpectralFlux * uSensitivity * 0.5;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

