uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashVal(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseVal(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashVal(i);
  float b = hashVal(i + vec2(1.0, 0.0));
  float c = hashVal(i + vec2(0.0, 1.0));
  float d = hashVal(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Sierpinski gasket via iterative subdivision
// Returns: x = inside (0/1), y = depth level, z = which triangle
vec3 sierpinski(vec2 p, int iterations) {
  float depth = 0.0;
  float triIndex = 0.0;

  // Transform to equilateral triangle coordinates
  vec2 v0 = vec2(0.0, 1.0);
  vec2 v1 = vec2(-0.866, -0.5);
  vec2 v2 = vec2(0.866, -0.5);

  for (int i = 0; i < 12; i++) {
    if (i >= iterations) break;

    vec2 mid01 = (v0 + v1) * 0.5;
    vec2 mid12 = (v1 + v2) * 0.5;
    vec2 mid02 = (v0 + v2) * 0.5;

    // Determine which sub-triangle the point is in
    // Using barycentric-like test
    float d0 = dot(p - mid12, vec2(0.0, 1.0));
    float d1 = dot(p - mid02, normalize(v1 - v0));
    float d2 = dot(p - mid01, normalize(v2 - v0));

    if (d0 > 0.0) {
      // Top triangle
      v1 = mid01;
      v2 = mid02;
      triIndex = triIndex * 3.0 + 0.0;
    } else if (d1 < 0.0) {
      // Bottom-left
      v0 = mid01;
      v2 = mid12;
      triIndex = triIndex * 3.0 + 1.0;
    } else if (d2 > 0.0) {
      // Bottom-right
      v0 = mid02;
      v1 = mid12;
      triIndex = triIndex * 3.0 + 2.0;
    } else {
      // Removed center triangle
      return vec3(0.0, depth, triIndex);
    }
    depth += 1.0;
  }

  return vec3(1.0, depth, triIndex);
}

// Stained glass coloring per level
vec3 stainedGlassColor(float depth, float triIndex, float time, float palShift) {
  float hue = fract(depth * 0.11 + triIndex * 0.0037 + time * 0.06 + palShift + sin(time * 0.3) * 0.15);
  float sat = 0.7 + 0.3 * sin(depth * 1.2 + time * 0.5);
  float val = 0.5 + 0.4 * cos(depth * 0.8);

  // Make it jewel-toned
  sat = clamp(sat, 0.5, 1.0);
  val = clamp(val, 0.3, 0.9);

  // HSV to RGB
  vec3 c = vec3(hue, sat, val);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 px = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(px - K.xxx, 0.0, 1.0), c.y);
}

// God rays from behind the glass
float godRays(vec2 p, float time) {
  vec2 lightSrc = vec2(0.0, 0.5 + sin(time * 0.15) * 0.3);
  vec2 toLight = lightSrc - p;
  float angle = atan(toLight.y, toLight.x);
  float dist = length(toLight);

  float rays = 0.0;
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float rayAngle = fi * 0.785 + time * 0.1;
    float diff = abs(mod(angle - rayAngle + 3.14159, 6.28318) - 3.14159);
    rays += smoothstep(0.15, 0.0, diff) * exp(-dist * 0.8);
  }
  return rays;
}

// Lead came (dark lines between glass pieces)
float leadCame(vec2 p, float depth) {
  // Edge detection using the fractal structure
  float eps = 0.005;
  vec3 s1 = sierpinski(p + vec2(eps, 0.0), 8);
  vec3 s2 = sierpinski(p - vec2(eps, 0.0), 8);
  vec3 s3 = sierpinski(p + vec2(0.0, eps), 8);
  vec3 s4 = sierpinski(p - vec2(0.0, eps), 8);

  float edge = 0.0;
  edge += abs(s1.y - s2.y);
  edge += abs(s3.y - s4.y);
  edge += abs(s1.x - s2.x) * 5.0;
  edge += abs(s3.x - s4.x) * 5.0;

  return clamp(edge, 0.0, 1.0);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;

  // Gentle rotation
  float rotAngle = time * 0.05 + uChaos * sin(time * 0.1) * 0.2;
  mat2 rot = mat2(cos(rotAngle), -sin(rotAngle), sin(rotAngle), cos(rotAngle));
  vec2 rp = rot * p;

  // Audio warps the fractal space
  rp += vec2(
    sin(rp.y * 3.0 + time) * bassVal * 0.05,
    cos(rp.x * 3.0 + time) * midsVal * 0.05
  );

  // Sierpinski fractal
  int iters = 8;
  vec3 sierpResult = sierpinski(rp, iters);
  float inside = sierpResult.x;
  float depth = sierpResult.y;
  float triIndex = sierpResult.z;

  // Stained glass color
  float palShift = uPalette * 0.3;
  vec3 glassColor = stainedGlassColor(depth, triIndex, time, palShift);

  // Light transmission (brighter where glass is thinner / higher depth)
  float transmission = 0.3 + 0.7 * (depth / 8.0);
  transmission *= 1.0 + bassVal * 0.3;

  // God rays behind the glass
  float rays = godRays(p, time);

  // Lead came (dark outlines)
  float lead = leadCame(rp, depth);

  // Compose
  vec3 col = vec3(0.02, 0.01, 0.03); // Dark background

  // Glass panels
  if (inside > 0.5) {
    col = glassColor * transmission;
    // Light streaming through
    col += vec3(1.0, 0.95, 0.8) * rays * 0.3 * transmission;
  } else {
    // Void area (removed triangles) - let more light through
    col += vec3(0.8, 0.7, 0.5) * rays * 0.5;
    // Subtle glow in void areas
    col += vec3(0.05, 0.03, 0.08) * (1.0 + bassVal * 0.5);
  }

  // Lead came overlay
  col = mix(col, vec3(0.02), lead * 0.8);

  // Depth-based shimmer
  float shimmer = sin(depth * 5.0 + time * 2.0 + triIndex * 0.1) * 0.5 + 0.5;
  col += glassColor * shimmer * inside * 0.1;

  // Kick: divine flash through all glass
  float kickFlash = uKick * uSensitivity;
  col += vec3(1.0, 0.95, 0.8) * kickFlash * 0.5 * (inside * 0.7 + 0.3);

  // Onset: color shift across depth levels
  float onsetVal = uOnset * uSensitivity;
  col = mix(col, col.gbr, onsetVal * 0.3);

  // Beat: pulsing glow
  col *= 1.0 + uBeat * uSensitivity * 0.3;

  // Treble: sparkle on high-depth glass
  float sparkle = pow(hashVal(rp * 100.0 + time), 20.0);
  col += vec3(1.0) * sparkle * trebleVal * (depth / 8.0) * 0.5;

  // BPM breathing on light rays
  float breathe = 1.0 + uBpmSin * 0.1 * uSensitivity;
  col *= breathe;

  // Spectral centroid warms/cools the light
  float centroidVal = uSpectralCentroid * uSensitivity;
  col = mix(col, col * vec3(1.1, 0.95, 0.85), centroidVal * 0.3);

  // Harmonicity enhances glass resonance
  col += glassColor * uHarmonicity * uSensitivity * 0.05 * inside;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

