#define PI 3.14159265
#define TAU 6.28318530

// Sierpinski tetrahedron distance estimator via IFS folds
float sierpinskiDE(vec3 p, float time, float bassVal, float chaos, int maxIter) {
  float scale = 2.0;
  float offset = 1.0 + bassVal * 0.1;

  // Tetrahedron vertices
  vec3 a1 = vec3(1.0, 1.0, 1.0) * offset;
  vec3 a2 = vec3(-1.0, -1.0, 1.0) * offset;
  vec3 a3 = vec3(1.0, -1.0, -1.0) * offset;
  vec3 a4 = vec3(-1.0, 1.0, -1.0) * offset;

  float trap = 0.0;
  float d;

  for (int i = 0; i < 16; i++) {
    if (i >= maxIter) break;

    float fi = float(i);

    // Chaos-driven vertex wobble
    float wobble = chaos * sin(time * 0.3 + fi * 0.7) * 0.1;

    // Fold toward nearest vertex
    vec3 c = a1;
    d = length(p - a1);

    float dt = length(p - a2);
    if (dt < d) { c = a2; d = dt; }

    dt = length(p - a3);
    if (dt < d) { c = a3; d = dt; }

    dt = length(p - a4);
    if (dt < d) { c = a4; d = dt; }

    // Scale and translate toward nearest vertex
    p = scale * p - c * (scale - 1.0 + wobble);

    trap += d;
  }

  // Distance estimate
  return (length(p) - 1.5) * pow(scale, -float(maxIter));
}

// Orbit trap coloring
vec3 sierpinskiColor(float trap, float iter, float palette, float time) {
  float t = fract(trap * 0.1 + iter * 0.15 + time * 0.03);
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(0.0 + palette * 0.1, 0.1, 0.2);
  return a + b * cos(TAU * (c * t + d));
}

void main() {
  vec2 uv = (vUv - 0.5) * 2.0;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.9;

  // Audio (boosted)
  float bassVal = bass() * uSensitivity * 2.0;
  float midsVal = mids() * uSensitivity * 1.8;
  float trebleVal = treble() * uSensitivity * 1.8;
  float beatPulse = uBeat * uSensitivity * 1.5;
  float onset = uOnset * uSensitivity * 1.5;
  float kick = uKick * uSensitivity * 1.5;
  float energy = uEnergy * uSensitivity * 1.5;

  int maxIter = int(uFoldIterations * 8.0 + 6.0);

  // Camera setup — closer for full-screen fill
  float orbitSpeed = uCameraOrbit * 0.5 + 0.2;
  float camDist = (uZoom * 1.5 + 1.8) - beatPulse * 0.5;
  float camAngle = time * orbitSpeed;
  float camElev = sin(time * orbitSpeed * 0.3) * 0.5 + 0.3;

  vec3 camPos = vec3(
    cos(camAngle) * cos(camElev) * camDist,
    sin(camElev) * camDist,
    sin(camAngle) * cos(camElev) * camDist
  );

  vec3 target = vec3(0.0);
  vec3 forward = normalize(target - camPos);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);

  // Ray direction
  vec3 rd = normalize(forward + uv.x * right + uv.y * up);

  // Fractal rotation
  float rotAngle = time * 0.2 + uChaos * sin(time * 0.1) * 0.5;
  float cRot = cos(rotAngle), sRot = sin(rotAngle);

  // Raymarch
  vec3 col = vec3(0.0);
  float totalDist = 0.0;
  float minDist = 1e10;
  float trapAccum = 0.0;
  bool hit = false;

  for (int i = 0; i < 100; i++) {
    vec3 p = camPos + rd * totalDist;

    // Rotate the fractal
    p.xz = vec2(p.x * cRot - p.z * sRot, p.x * sRot + p.z * cRot);

    float d = sierpinskiDE(p, time, bassVal, uChaos, maxIter);
    minDist = min(minDist, d);
    trapAccum += exp(-d * 10.0);

    if (d < 0.001) {
      hit = true;

      // Normal estimation
      vec2 e = vec2(0.001, 0.0);
      vec3 pp = p;
      vec3 n = normalize(vec3(
        sierpinskiDE(pp + e.xyy, time, bassVal, uChaos, maxIter) - sierpinskiDE(pp - e.xyy, time, bassVal, uChaos, maxIter),
        sierpinskiDE(pp + e.yxy, time, bassVal, uChaos, maxIter) - sierpinskiDE(pp - e.yxy, time, bassVal, uChaos, maxIter),
        sierpinskiDE(pp + e.yyx, time, bassVal, uChaos, maxIter) - sierpinskiDE(pp - e.yyx, time, bassVal, uChaos, maxIter)
      ));

      // Lighting
      vec3 lightDir = normalize(vec3(1.0, 1.0, -0.5));
      float diff = max(dot(n, lightDir), 0.0);
      float spec = pow(max(dot(reflect(-lightDir, n), -rd), 0.0), 32.0);

      // Color from depth/position
      float colorT = fract(length(pp) * 0.3 + time * 0.08 + sin(uTime * 0.2) * 0.15);
      vec3 matCol = sierpinskiColor(trapAccum, float(maxIter), uPalette, time);

      col = matCol * (0.15 + diff * 0.7);
      col += vec3(1.0, 0.9, 0.8) * spec * (0.3 + trebleVal * 0.7);

      // AO approximation
      float ao = 1.0 - float(i) / 80.0;
      col *= ao * ao;

      break;
    }

    totalDist += d;
    if (totalDist > 20.0) break;
  }

  // Glow for near-misses — enhanced for fullscreen fill
  if (!hit) {
    float glow = exp(-minDist * 3.0) * 1.2;
    float glowT = fract(trapAccum * 0.05 + time * 0.02);
    col = sierpinskiColor(glowT, 0.5, uPalette, time) * glow;

    // Background gradient — fills screen
    float bgGrad = dot(rd, vec3(0.0, 1.0, 0.0)) * 0.5 + 0.5;
    col += sierpinskiColor(bgGrad, 0.0, uPalette, time) * 0.05;
  }

  // Volume glow from accumulated near-surface passes
  col += sierpinskiColor(fract(trapAccum * 0.02), 0.3, uPalette, time) * trapAccum * 0.003;

  // Beat flash
  col *= 1.0 + beatPulse * 0.5;

  // Onset
  col += vec3(onset * 0.1, onset * 0.06, onset * 0.12);

  // Kick
  col *= 1.0 + kick * 0.2;

  // Intensity and energy
  col *= uIntensity * 1.5;
  col *= 1.0 + energy * 0.2;

  // Vignette — softened for full-screen fill
  float vig = 1.0 - smoothstep(0.7, 1.5, length(vUv - 0.5) * 1.1);
  col *= vig;

  col += vec3(0.008, 0.005, 0.012);

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbmSlit(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 6; i++) {
    v += a * vnoise(p);
    p = p * 2.1 + vec2(1.7, 3.2);
    a *= 0.5;
  }
  return v;
}

// Generate the base fractal pattern at a given time
vec3 fractalPattern(vec2 p, float t, float pal) {
  vec2 warp1 = vec2(fbmSlit(p * 2.0 + t * 0.3), fbmSlit(p * 2.0 + vec2(5.0, 3.0) + t * 0.25));
  vec2 warp2 = vec2(fbmSlit(p * 3.0 + warp1 + t * 0.2), fbmSlit(p * 3.0 + warp1 + vec2(8.0, 2.0) + t * 0.15));

  vec2 warped = p + warp1 * 0.4 + warp2 * 0.2;

  float pattern = 0.0;
  pattern += sin(warped.x * 5.0 + t) * cos(warped.y * 4.0 - t * 0.7) * 0.5 + 0.5;
  pattern += sin(length(warped) * 8.0 - t * 1.5) * 0.3;
  float spiral = atan(warped.y, warped.x) + length(warped) * 3.0;
  pattern += sin(spiral * 3.0 + t) * 0.2;
  pattern = clamp(pattern, 0.0, 1.0);

  float warpMag = length(warp1) + length(warp2) * 0.5;
  float hue = pattern * 0.4 + warpMag * 0.3 + t * 0.02;

  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 1.0, 1.0);
  vec3 d = vec3(0.0 + pal * 0.15, 0.1, 0.2);
  vec3 col = a + b * cos(6.2832 * (c * hue + d));

  col *= pattern;
  return col;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;

  // Slit-scan: each horizontal band has a different time offset
  float numSlits = 30.0 + trebleVal * 20.0;
  float slitY = floor(p.y * numSlits) / numSlits;
  float slitFract = fract(p.y * numSlits);

  float maxTimeOffset = 1.5 + bassVal * 3.0 + uChaos * 2.0;
  float timeOffset = slitY * maxTimeOffset;

  // Add wave-like time displacement
  float timeWave = sin(slitY * 10.0 + time * 2.0) * 0.3;
  timeOffset += timeWave;

  // Flux creates random time jitter per slit
  float jitter = hash21(vec2(slitY, floor(time * 5.0))) * fluxVal * 0.5;
  timeOffset += jitter;

  // Sample the fractal pattern at the displaced time
  float sampleTime = time + timeOffset;
  vec3 col = fractalPattern(p, sampleTime, uPalette);

  // Slit edge highlighting
  float slitEdge = smoothstep(0.05, 0.0, slitFract) + smoothstep(0.95, 1.0, slitFract);
  col += vec3(0.3, 0.2, 0.4) * slitEdge * 0.2;

  // Horizontal scan line effect
  float scanX = fract(time * 0.5);
  float scanDist = abs(p.x / 1.5 - scanX * 2.0 + 1.0);
  float scanLine = smoothstep(0.05, 0.0, scanDist);
  col += vec3(0.5, 0.8, 1.0) * scanLine * 0.3;

  // Kick: compress time (all slits momentarily show same time)
  float kickCompress = kickVal * 0.8;
  vec3 kickCol = fractalPattern(p, time, uPalette);
  col = mix(col, kickCol, kickCompress);

  // Mids: color saturation boost
  float gray = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(gray), col, 1.0 + midsVal * 0.5);

  // Vertical smear trails
  float smearNoise = vnoise(vec2(p.x * 5.0, time * 2.0));
  float smearAmount = smearNoise * bassVal * 0.2;
  vec3 smearCol = fractalPattern(p + vec2(0.0, smearAmount), sampleTime + 0.1, uPalette);
  col = mix(col, smearCol, 0.2);

  // Time seam flash
  float seamFlash = pow(1.0 - abs(fract(time * 0.5) - 0.5) * 2.0, 8.0);
  col += vec3(0.8, 0.7, 1.0) * seamFlash * 0.1;

  // BPM breathing
  col *= 0.85 + uBpmSin * 0.15;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGranulation;
uniform float uProminenceHeight;
uniform float uMagneticStrength;
uniform float uCoronaGlow;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) { v += a * noise(p); p = rot * p * 2.0; a *= 0.5; }
  return v;
}

// Voronoi for granulation cells
float voronoiCell(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float d = 10.0;
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      vec2 n = vec2(float(x), float(y));
      vec2 cell = n + hash(i + n) * 0.8 - f;
      d = min(d, dot(cell, cell));
    }
  }
  return sqrt(d);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / max(uZoom * 0.8 + 0.3, 0.1);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float warmthVal = uWarmth * uSensitivity;
  float bpmVal = uBpmSin;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Solar disc
  float solarR = 0.55;
  float discMask = 1.0 - smoothstep(solarR - 0.02, solarR + 0.02, r);

  // Background: dark space
  vec3 col = vec3(0.005, 0.002, 0.005);

  // Corona
  float corona = exp(-(r - solarR) * 3.0 / uCoronaGlow) * step(solarR * 0.8, r);
  vec3 coronaCol = mix(vec3(1.0, 0.7, 0.3), vec3(1.0, 0.4, 0.15), (r - solarR) * 2.0);
  col += coronaCol * corona * 0.6 * (0.7 + energyVal * 0.6);

  // Streamers in corona
  for (float i = 0.0; i < 8.0; i++) {
    float sAngle = i * 0.785 + time * 0.05;
    float angleDist = abs(mod(angle - sAngle + 3.14159, 6.28318) - 3.14159);
    float streamer = exp(-angleDist * 8.0) * exp(-(r - solarR) * 4.0) * step(solarR, r);
    col += vec3(1.0, 0.8, 0.4) * streamer * 0.35 * uMagneticStrength;
  }

  // Solar surface
  if (discMask > 0.01) {
    // Granulation — convection cells
    float gran = voronoiCell(p * 8.0 + time * 0.2);
    float granEdge = smoothstep(0.1, 0.3, gran);
    vec3 surfCol = mix(vec3(1.0, 0.85, 0.3), vec3(0.9, 0.6, 0.15), granEdge * uGranulation);

    // Turbulence driven by spectral flux
    float turb = fbm(p * 5.0 + time * (0.3 + fluxVal * 0.5));
    surfCol = mix(surfCol, vec3(1.0, 0.9, 0.5), turb * 0.3);

    // Sunspots (dark regions)
    float spot1 = smoothstep(0.15, 0.1, length(p - vec2(0.15, 0.1)));
    float spot2 = smoothstep(0.1, 0.07, length(p - vec2(-0.2, -0.15)));
    surfCol = mix(surfCol, vec3(0.3, 0.1, 0.05), (spot1 + spot2) * 0.5);

    // Limb darkening
    float limb = 1.0 - pow(r / solarR, 2.0) * 0.4;
    surfCol *= limb;

    // Bass pulsing brightness
    surfCol *= 1.0 + bassVal * 0.4;

    col = mix(col, surfCol, discMask);
  }

  // Prominences
  for (float i = 0.0; i < 6.0; i++) {
    float promAngle = i * 1.047 + time * 0.03 + sin(i * 3.0) * 0.5;
    vec2 base = vec2(cos(promAngle), sin(promAngle)) * solarR;

    // Arc shape
    float height = uProminenceHeight * (0.3 + kickVal * 1.0 + bassVal * 0.4);
    float arcWidth = 0.15 + sin(time + i * 2.0) * 0.05;

    // Parametric arc
    for (float t = 0.0; t < 1.0; t += 0.02) {
      vec2 arcPos = base + vec2(cos(promAngle + 1.57), sin(promAngle + 1.57)) * sin(t * 3.14159) * arcWidth;
      arcPos += vec2(cos(promAngle), sin(promAngle)) * t * height;

      // Turbulent displacement
      arcPos += vec2(noise(vec2(t * 10.0, time + i)) - 0.5, noise(vec2(time + i, t * 10.0)) - 0.5) * 0.05 * uChaos;

      float d = length(p - arcPos);
      float prom = exp(-d * 30.0);
      vec3 promCol = mix(vec3(1.0, 0.4, 0.15), vec3(1.0, 0.15, 0.08), t);
      promCol += vec3(0.3, 0.15, 0.0) * midsVal;
      col += promCol * prom * 0.5 * (0.5 + kickVal * 2.0);
    }
  }

  // Solar flare on kick
  if (kickVal > 0.1) {
    float flareAngle = time * 0.7;
    vec2 flareDir = vec2(cos(flareAngle), sin(flareAngle));
    float flareDot = max(dot(normalize(p), flareDir), 0.0);
    float flare = pow(flareDot, 20.0) * kickVal * 2.0 * exp(-(r - solarR) * 3.0);
    col += vec3(1.0, 0.95, 0.7) * flare;
  }

  // Warmth intensifies overall color temperature
  col += vec3(0.03, 0.01, 0.0) * warmthVal;

  // Treble → hot particle ejection
  col += vec3(1.0, 0.85, 0.4) * trebleVal * 0.04;

  col *= uIntensity * 1.5;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFlareStrength;
uniform float uStreamCount;
uniform float uPlasmaTemp;
uniform float uCoronalSize;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 6; i++) {
    val += amp * noise(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return val;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.05;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;

  // Polar coordinates from center (solar disc at origin)
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Solar disc — bright white/yellow core
  float discRadius = 0.12 + bassVal * 0.06;
  float disc = smoothstep(discRadius + 0.02, discRadius - 0.01, r);
  vec3 discColor = mix(vec3(1.0, 0.9, 0.6), vec3(1.0, 1.0, 0.95), disc);

  // Corona — soft glow around disc
  float coronaR = uCoronalSize + bassVal * 0.2;
  float corona = exp(-r / (coronaR * 0.5)) * 0.8;
  // Corona turbulence
  float coronaNoise = fbm(vec2(angle * 3.0 + time * 0.5, r * 10.0 - time * 2.0));
  corona *= 0.6 + coronaNoise * 0.6;
  corona *= (1.0 + beatPulse * 1.0);
  vec3 coronaColor = mix(vec3(1.0, 0.6, 0.15), vec3(1.0, 0.9, 0.4), coronaNoise) * corona;

  // Solar wind streams — spiraling outward
  float streams = 0.0;
  float streamCount = uStreamCount + 2.0;
  for (int i = 0; i < 8; i++) {
    if (float(i) >= streamCount) break;
    float fi = float(i);
    float baseAngle = fi * 6.2832 / streamCount + time * 0.15;
    // Spiral: angle offset increases with distance
    float spiral = baseAngle + r * 2.0 * (1.0 + uChaos);
    // Angular proximity
    float angleDiff = abs(mod(angle - spiral + 3.14159, 6.2832) - 3.14159);
    float streamWidth = 0.15 + fi * 0.02 + bassVal * 0.1;
    float stream = exp(-angleDiff * angleDiff / (streamWidth * streamWidth * 0.01));
    // Fade in from corona, fade out at distance
    stream *= smoothstep(discRadius, discRadius + 0.2, r);
    stream *= exp(-r * 0.8);
    // Turbulence along stream
    float turbNoise = noise(vec2(r * 8.0 - time * 3.0 + fi * 5.0, angle * 2.0));
    stream *= 0.5 + turbNoise * 0.7;
    // Flare strength modulation
    stream *= uFlareStrength + beatPulse * 0.8;
    streams += stream;
  }

  // Stream color — temperature dependent
  vec3 coolStream = vec3(0.4, 0.7, 1.0);  // Blue
  vec3 warmStream = vec3(1.0, 0.75, 0.15);  // Orange
  vec3 hotStream = vec3(1.0, 1.0, 0.9);  // White
  float temp = uPlasmaTemp + midsVal * 0.3;
  vec3 streamColor = mix(coolStream, warmStream, smoothstep(0.0, 0.5, temp));
  streamColor = mix(streamColor, hotStream, smoothstep(0.5, 1.0, temp));
  streamColor += vec3(uPalette * 0.05);

  // Particle sparkle in streams
  float sparkle = 0.0;
  float sparkGrid = 60.0;
  vec2 sparkUv = vec2(r * sparkGrid, angle * sparkGrid * 0.5);
  vec2 sparkId = floor(sparkUv);
  float sparkH = hash(sparkId);
  float sparkOn = step(0.93 - trebleVal * 0.05, sparkH);
  vec2 sparkF = fract(sparkUv) - 0.5;
  float sparkDist = length(sparkF);
  sparkle = sparkOn * exp(-sparkDist * sparkDist * 800.0);
  sparkle *= sin(time * 6.0 + sparkH * 12.0) * 0.5 + 0.5;
  sparkle *= smoothstep(discRadius, discRadius + 0.3, r) * exp(-r * 1.5);

  // Coronal mass ejection (CME) — beat triggered blob
  float cmeAngle = sin(time * 0.3) * 3.14159;
  float cmeDir = abs(mod(angle - cmeAngle + 3.14159, 6.2832) - 3.14159);
  float cmeR = r - 0.2 - beatPulse * 0.5;
  float cme = exp(-cmeDir * cmeDir * 8.0) * exp(-cmeR * cmeR * 3.0);
  cme *= beatPulse * 3.0;
  float cmeNoise = fbm(vec2(angle * 5.0 + time * 2.0, r * 8.0 - time * 4.0));
  cme *= 0.5 + cmeNoise * 0.5;
  vec3 cmeColor = vec3(1.0, 0.85, 0.3) * cme;

  // Onset flare — radial flash
  float flareBurst = onsetFlash * exp(-r * 2.0) * 1.2;
  vec3 flareColor = vec3(1.0, 0.9, 0.5) * flareBurst;

  // Background — dark space with subtle stars
  vec3 bg = vec3(0.005, 0.003, 0.01);
  float starGrid = 100.0;
  vec2 starUv = p * starGrid;
  vec2 starId = floor(starUv);
  float starH = hash(starId + 200.0);
  float starOn = step(0.99, starH);
  vec2 starF = fract(starUv) - 0.5;
  float star = starOn * exp(-dot(starF, starF) * 3000.0) * 0.2;
  bg += vec3(star);

  // Combine
  vec3 finalColor = bg;
  finalColor += discColor * disc;
  finalColor += coronaColor;
  finalColor += streamColor * streams * uIntensity * 1.5;
  finalColor += vec3(0.9, 1.0, 1.0) * sparkle * 0.8;
  finalColor += cmeColor;
  finalColor += flareColor;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(clamp(finalColor, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
