__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uWaveHeight;
uniform float uRowCount;
uniform float uFoamAmount;
uniform float uPerspectiveDepth;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Water color with depth
vec3 oceanColor(float depth, float foam, float palette, float time) {
  vec3 deepBlue = vec3(0.02, 0.05, 0.15);
  vec3 midBlue = vec3(0.05, 0.2, 0.5);
  vec3 shallowCyan = vec3(0.1, 0.6, 0.8);
  vec3 foamWhite = vec3(0.85, 0.95, 1.0);

  float shift = palette * 0.2;
  deepBlue += vec3(shift * 0.1, 0.0, shift * 0.05);
  shallowCyan += vec3(shift * 0.1, -shift * 0.05, 0.0);

  vec3 waterBase = mix(shallowCyan, deepBlue, depth);
  waterBase = mix(waterBase, midBlue, sin(time * 0.1 + depth * 3.0) * 0.3 + 0.3);
  return mix(waterBase, foamWhite, foam);
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.6;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Spectrum bands for per-row wave height
  float spec[8];
  spec[0] = uSpectrum0 * uSensitivity;
  spec[1] = uSpectrum1 * uSensitivity;
  spec[2] = uSpectrum2 * uSensitivity;
  spec[3] = uSpectrum3 * uSensitivity;
  spec[4] = uSpectrum4 * uSensitivity;
  spec[5] = uSpectrum5 * uSensitivity;
  spec[6] = uSpectrum6 * uSensitivity;
  spec[7] = uSpectrum7 * uSensitivity;

  float numRows = 12.0 + uRowCount * 20.0;
  float waveAmp = uWaveHeight * 0.15;
  float perspStr = uPerspectiveDepth;

  vec3 color = vec3(0.01, 0.02, 0.06); // dark sky/deep
  float closestRow = -1.0;

  // Draw rows from back to front
  for (int i = 0; i < 32; i++) {
    float row = float(i);
    if (row >= numRows) break;

    float rowNorm = row / numRows; // 0 = front, 1 = back
    float depth = 1.0 - rowNorm;

    // Perspective: back rows are higher, closer together
    float perspScale = pow(depth, 1.0 + perspStr);
    float rowY = 0.1 + rowNorm * 0.75 * perspScale + (1.0 - perspScale) * 0.3;

    // Wave shape for this row
    float xFreq = 3.0 + row * 0.3;
    float waveX = uv.x * xFreq + time * (0.5 + row * 0.1);

    // Get spectrum band for this row
    int bandIdx = int(mod(row, 8.0));
    float specVal = 0.0;
    // Unrolled spectrum lookup
    if (bandIdx == 0) specVal = spec[0];
    else if (bandIdx == 1) specVal = spec[1];
    else if (bandIdx == 2) specVal = spec[2];
    else if (bandIdx == 3) specVal = spec[3];
    else if (bandIdx == 4) specVal = spec[4];
    else if (bandIdx == 5) specVal = spec[5];
    else if (bandIdx == 6) specVal = spec[6];
    else specVal = spec[7];

    float wave = sin(waveX) * waveAmp * (0.5 + specVal * 1.5);
    wave += sin(waveX * 2.3 + 1.5) * waveAmp * 0.3 * (1.0 + trebleVal);
    wave += sin(waveX * 0.5 - time * 0.3) * waveAmp * 0.5 * bassVal;

    // Chaos adds noise to wave
    wave += noise(vec2(waveX, row + time * 0.2)) * uChaos * waveAmp;

    float waveTop = rowY + wave;

    // Row height/thickness decreases with distance
    float rowThickness = 0.03 * (1.0 - rowNorm * 0.5);

    // Check if pixel is in this row's water body
    float belowWave = smoothstep(waveTop, waveTop - rowThickness, uv.y);
    float abovePrev = 1.0; // always above for layering

    if (belowWave > 0.01) {
      // Foam at crest
      float crestDist = abs(uv.y - waveTop);
      float foam = smoothstep(rowThickness * uFoamAmount, 0.0, crestDist);
      foam *= 0.5 + specVal * 1.0 + kickVal * 0.5;

      vec3 rowColor = oceanColor(rowNorm, clamp(foam, 0.0, 1.0), uPalette, time);
      rowColor *= uIntensity * (1.0 + beatVal * 0.3);

      // Spray particles on kick
      if (kickVal > 0.1) {
        float sprayY = waveTop + kickVal * 0.1;
        float sprayDist = abs(uv.y - sprayY);
        float spray = exp(-sprayDist * 30.0) * hash(vec2(uv.x * 50.0, row)) * kickVal;
        rowColor += vec3(spray * 0.8, spray * 0.9, spray);
      }

      color = mix(color, rowColor, belowWave * (0.7 + rowNorm * 0.3));
    }
  }

  // Sky gradient at top
  float skyMix = smoothstep(0.7, 1.0, uv.y);
  vec3 skyColor = mix(vec3(0.02, 0.04, 0.12), vec3(0.0, 0.01, 0.05), uv.y);
  color = mix(color, skyColor, skyMix);

  // Energy global brightness
  color *= 0.8 + energyVal * 0.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCoreSize;
uniform float uShockwaveForce;

// Hash
float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float hash2d(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Smooth noise
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash2d(i);
  float b = hash2d(i + vec2(1.0, 0.0));
  float c = hash2d(i + vec2(0.0, 1.0));
  float d = hash2d(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM (fractal Brownian motion)
float fbm(vec2 p, float time) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * noise(p * freq + time * (0.3 + float(i) * 0.1));
    freq *= 2.1;
    amp *= 0.48;
  }
  return val;
}

// Color temperature: hot white -> yellow -> orange -> red -> purple -> dark
vec3 heatColor(float t) {
  // t: 1.0 = hottest (white), 0.0 = coolest (dark purple)
  t = clamp(t, 0.0, 1.0);
  vec3 white = vec3(1.0, 0.95, 0.85);
  vec3 yellow = vec3(1.0, 0.85, 0.2);
  vec3 orange = vec3(1.0, 0.45, 0.05);
  vec3 red = vec3(0.9, 0.1, 0.05);
  vec3 purple = vec3(0.5, 0.05, 0.4);
  vec3 dark = vec3(0.1, 0.02, 0.12);

  vec3 col = dark;
  col = mix(col, purple, smoothstep(0.0, 0.15, t));
  col = mix(col, red, smoothstep(0.15, 0.35, t));
  col = mix(col, orange, smoothstep(0.35, 0.55, t));
  col = mix(col, yellow, smoothstep(0.55, 0.75, t));
  col = mix(col, white, smoothstep(0.75, 1.0, t));
  return col;
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 1.5;

  // Audio
  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatVal = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Centered coords
  vec2 center = vec2(0.5);
  vec2 p = (uv - center) * (2.0 + uZoom);
  float dist = length(p);
  float angle = atan(p.y, p.x);

  // === CORE ===
  float coreRadius = uCoreSize * 0.3 * (1.0 + bassVal * 0.4);

  // Turbulent edge: displace radius with noise
  float turbulence = 0.15 + energyVal * 0.15 + uChaos * 0.1;
  float noiseDisp = fbm(vec2(angle * 2.0, dist * 3.0), time * 2.0) * turbulence;
  float noiseDisp2 = fbm(vec2(angle * 3.0 + 100.0, dist * 5.0), time * 1.5 + 50.0) * turbulence * 0.5;

  float coreEdge = coreRadius + noiseDisp + noiseDisp2;

  // Core glow: bright center fading out
  float coreGlow = smoothstep(coreEdge, coreEdge * 0.2, dist);
  // Soft outer glow
  float outerGlow = exp(-dist * 3.0 / max(coreRadius, 0.01)) * 0.6;

  // Core heat: hottest at center
  float coreHeat = smoothstep(coreEdge * 1.2, 0.0, dist);
  vec3 coreColor = heatColor(coreHeat * 0.9 + 0.1);
  coreColor *= coreGlow + outerGlow * 0.5;

  // === PLASMA TENDRILS ===
  float tendrilNoise = fbm(vec2(angle * 4.0 + time * 0.8, dist * 6.0 - time * 0.5), time);
  float tendrilMask = smoothstep(coreEdge * 3.0, coreEdge * 0.5, dist);
  float tendrilGlow = tendrilNoise * tendrilMask * 0.7;
  // Tendrils are orange-red
  vec3 tendrilColor = heatColor(tendrilGlow * 0.5 + 0.2) * tendrilGlow;

  // === SHOCKWAVE RINGS ===
  vec3 ringTotal = vec3(0.0);
  float ringSpeed = 0.8 + beatVal * 0.5;
  float maxExpansion = 1.5 + uShockwaveForce;

  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float phase = fract(time * ringSpeed * 0.3 + fi * 0.25);
    float ringRadius = phase * maxExpansion;
    float expansion = phase; // 0=just born, 1=fully expanded

    // Ring distance
    float ringDist = abs(dist - ringRadius);
    float ringWidth = 0.03 + expansion * 0.02;
    float ringGlow = smoothstep(ringWidth, 0.0, ringDist) * (1.0 - expansion);

    // Beat amplifies rings
    ringGlow *= (0.5 + beatVal * 2.0) * uShockwaveForce;

    // Ring cools as it expands
    float ringHeat = (1.0 - expansion) * 0.8;
    vec3 ringColor = heatColor(ringHeat);

    ringTotal += ringColor * ringGlow;
  }

  // === ELECTRIC ARCS ===
  float arcCount = 6.0 + uChaos * 8.0;
  float arcGlow = 0.0;
  for (int j = 0; j < 3; j++) {
    float fj = float(j);
    float arcAngle = angle * (arcCount + fj * 2.0) + time * (1.0 + fj * 0.3);
    float arcLine = pow(1.0 - abs(fract(arcAngle / 6.28318) - 0.5) * 2.0, 25.0);
    float arcFade = smoothstep(coreEdge * 4.0, coreEdge * 0.3, dist);
    arcGlow += arcLine * arcFade * 0.4;
  }
  arcGlow *= trebleVal;
  vec3 arcColor = vec3(0.5, 0.7, 1.0) * arcGlow; // electric blue

  // === BACKGROUND ===
  // Very dark with warm ambient near core
  vec3 bgColor = vec3(0.01, 0.005, 0.02);
  float warmGlow = exp(-dist * 2.0) * 0.15;
  bgColor += vec3(0.15, 0.04, 0.06) * warmGlow * (1.0 + energyVal * 0.5);

  // Subtle radial pattern in bg
  float bgPattern = sin(angle * 6.0 + time * 0.3) * 0.02 * (1.0 - smoothstep(0.0, 1.5, dist));
  bgColor += vec3(0.05, 0.02, 0.08) * max(bgPattern, 0.0);

  // === COMPOSITE ===
  vec3 finalColor = bgColor;
  finalColor += coreColor;
  finalColor += tendrilColor;
  finalColor += ringTotal;
  finalColor += arcColor;

  // Kick flash: bright white burst from core
  float kickFlash = kickVal * exp(-dist * 5.0) * 0.6;
  finalColor += vec3(1.0, 0.9, 0.8) * kickFlash;

  // Onset: screen-wide flash
  finalColor += vec3(0.2, 0.1, 0.15) * onsetVal * 0.3;

  // Mids add warmth
  finalColor += vec3(0.1, 0.05, 0.0) * midsVal * 0.15 * (1.0 - smoothstep(0.0, 1.0, dist));

  // Palette shift
  float palAngle = uPalette * 6.28318;
  finalColor.r += sin(palAngle) * 0.05;
  finalColor.g += sin(palAngle + 2.094) * 0.05;
  finalColor.b += sin(palAngle + 4.189) * 0.05;

  // Intensity
  finalColor *= uIntensity * 1.3;

  // Vignette
  float vignette = smoothstep(2.0, 0.8, dist);
  finalColor *= vignette * 0.3 + 0.7;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.r, 0.0, 1.0),
    clamp(finalColor.g, 0.0, 1.0),
    clamp(finalColor.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbmTerrain(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = p * 2.1 + vec2(1.7, 1.3);
    a *= 0.5;
  }
  return v;
}

float getSpectrumAt(float x) {
  float bandF = x * 7.0;
  int bandLow = int(floor(bandF));
  float frac = fract(bandF);

  float valLow, valHigh;
  if (bandLow == 0) { valLow = uSpectrum0; valHigh = uSpectrum1; }
  else if (bandLow == 1) { valLow = uSpectrum1; valHigh = uSpectrum2; }
  else if (bandLow == 2) { valLow = uSpectrum2; valHigh = uSpectrum3; }
  else if (bandLow == 3) { valLow = uSpectrum3; valHigh = uSpectrum4; }
  else if (bandLow == 4) { valLow = uSpectrum4; valHigh = uSpectrum5; }
  else if (bandLow == 5) { valLow = uSpectrum5; valHigh = uSpectrum6; }
  else if (bandLow == 6) { valLow = uSpectrum6; valHigh = uSpectrum7; }
  else { valLow = uSpectrum7; valHigh = uSpectrum7; }

  return mix(valLow, valHigh, frac);
}

vec3 terrainPalette(float height, float pal) {
  vec3 deep = vec3(0.05, 0.02, 0.15);
  vec3 low = vec3(0.1, 0.15, 0.4);
  vec3 mid = vec3(0.2, 0.5, 0.3);
  vec3 high = vec3(0.9, 0.6, 0.2);
  vec3 peak = vec3(1.0, 0.3, 0.5);

  float h = clamp(height, 0.0, 1.0);
  h = fract(h + pal * 0.2);
  if (h < 0.25) return mix(deep, low, h * 4.0);
  else if (h < 0.5) return mix(low, mid, (h - 0.25) * 4.0);
  else if (h < 0.75) return mix(mid, high, (h - 0.5) * 4.0);
  else return mix(high, peak, (h - 0.75) * 4.0);
}

vec3 auroraSky(vec2 p, float time) {
  float aurora = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float wave = sin(p.x * (2.0 + fi) + time * (0.3 + fi * 0.1)) * 0.3;
    float band = smoothstep(0.1, 0.0, abs(p.y - 0.6 - wave - fi * 0.08));
    aurora += band * (0.3 - fi * 0.05);
  }
  vec3 auroraCol = mix(vec3(0.1, 0.8, 0.4), vec3(0.3, 0.2, 0.9), sin(time * 0.2 + p.x) * 0.5 + 0.5);
  auroraCol = mix(auroraCol, vec3(0.9, 0.2, 0.5), sin(time * 0.15 + p.x * 2.0) * 0.5 + 0.5);
  return auroraCol * aurora;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // Sky background with aurora
  vec3 skyCol = mix(vec3(0.02, 0.01, 0.05), vec3(0.05, 0.02, 0.1), vUv.y);
  skyCol += auroraSky(p, time);

  // Stars
  float starField = hash21(floor(p * 30.0));
  float starBright = step(0.97, starField) * (0.5 + 0.5 * sin(time * 3.0 + starField * 100.0));
  skyCol += vec3(0.8, 0.8, 1.0) * starBright * 0.5;

  col = skyCol;

  // Terrain raymarching (simplified 2.5D)
  float terrainHit = 0.0;
  vec3 terrainCol = vec3(0.0);

  for (int row = 0; row < 40; row++) {
    float fi = float(row);
    float rowDepth = 0.5 + fi * 0.15;
    float perspScale = 1.0 / rowDepth;
    float terrainX = p.x * rowDepth * 0.5;

    float terrainZ = rowDepth + time * 0.5;

    float xNorm = clamp(terrainX * 0.5 + 0.5, 0.0, 1.0);
    float specHeight = getSpectrumAt(xNorm) * uSensitivity * 1.5;

    float noise = fbmTerrain(vec2(terrainX * 2.0, terrainZ * 2.0)) * 0.3;
    noise += fbmTerrain(vec2(terrainX * 5.0, terrainZ * 5.0)) * 0.1 * uChaos;

    float totalHeight = specHeight + noise;

    float screenY = -0.3 + fi * 0.04 + totalHeight * perspScale * 0.8 - 0.3;

    if (p.y < screenY && terrainHit < 0.5) {
      terrainHit = 1.0;

      terrainCol = terrainPalette(totalHeight, uPalette);

      float fog = exp(-rowDepth * 0.15);
      terrainCol *= fog;

      float peakGlow = smoothstep(0.5, 1.0, specHeight);
      terrainCol += vec3(0.5, 0.3, 0.8) * peakGlow * 0.4;

      float gridX = smoothstep(0.05, 0.0, abs(fract(terrainX * 2.0) - 0.5) * 2.0 - 0.9);
      float gridZ = smoothstep(0.05, 0.0, abs(fract(terrainZ * 2.0) - 0.5) * 2.0 - 0.9);
      terrainCol += vec3(0.3, 0.5, 0.8) * (gridX + gridZ) * 0.15 * fog;
    }
  }

  col = mix(col, terrainCol, terrainHit);

  // Kick: terrain flash
  col += vec3(0.2, 0.15, 0.3) * kickVal * 0.2 * terrainHit;

  // Energy: overall brightness
  col *= 0.8 + energyVal * 0.3;

  // Mids: color warmth
  col *= 1.0 + midsVal * vec3(0.1, 0.05, 0.0);

  // BPM breathing
  col *= 0.85 + uBpmSin * 0.15;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSpiralTwist;
uniform float uTunnelDepth;
uniform float uRingCount;
uniform float uWarpStrength;

vec3 tunnelPalette(float t, float offset) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.5);
  vec3 c = vec3(1.0, 0.7, 0.4);
  vec3 d = vec3(0.0 + offset, 0.15 + offset, 0.20 + offset);
  return a + b * cos(6.2832 * (c * t + d));
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Polar coordinates
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Tunnel depth mapping: 1/r creates infinite tunnel
  float depth = 1.0 / (r + 0.05);
  depth *= uTunnelDepth;

  // Forward motion through tunnel
  float tunnelZ = depth - time * 2.0 - kickVal * 1.5;

  // Spiral twist: angle rotates with depth
  float twist = uSpiralTwist + bassVal * 1.5;
  float spiralAngle = angle + tunnelZ * twist * 0.3;

  // Warp the tunnel walls
  float warp = uWarpStrength + onsetVal * 0.3;
  spiralAngle += sin(tunnelZ * 2.0 + time * 0.5) * warp;
  float warpedZ = tunnelZ + cos(angle * 3.0 + time * 0.3) * warp * 0.5;

  // Ring pattern along tunnel depth
  float ringPattern = sin(warpedZ * uRingCount) * 0.5 + 0.5;

  // Spiral pattern along tunnel walls
  float spiralPattern = sin(spiralAngle * 4.0 + warpedZ * 3.0) * 0.5 + 0.5;

  // Checkerboard-like tunnel pattern
  float checker = sin(spiralAngle * 6.0) * sin(warpedZ * uRingCount * 0.5);
  checker = smoothstep(-0.1, 0.1, checker);

  // Combine patterns
  float combined = ringPattern * 0.3 + spiralPattern * 0.4 + checker * 0.3;

  // Chaos adds turbulence
  combined += sin(spiralAngle * 8.0 + warpedZ * 5.0 + time) * uChaos * 0.15;

  // Mids-reactive wobble
  combined += sin(angle * 2.0 + time * 3.0) * midsVal * 0.15;

  // Color: shift hue with depth and spiral position
  float hue = fract(combined * 0.4 + tunnelZ * 0.02 + uPalette * 0.1 + time * 0.01);
  vec3 color = tunnelPalette(hue, uPalette * 0.05);
  color *= combined;

  // Depth fog: darken edges (far away is already at center)
  float depthFog = smoothstep(0.0, 0.6, r);
  color *= 0.4 + depthFog * 0.6;

  // Center glow (the tunnel opening)
  float centerGlow = exp(-r * 3.0);
  vec3 glowColor = tunnelPalette(time * 0.03 + bassVal * 0.2, uPalette * 0.1 + 0.3);
  color += glowColor * centerGlow * 0.5 * (1.0 + kickVal);

  // Edge glow — fill screen edges with tunnel wall color
  float edgeGlow = smoothstep(0.3, 0.9, r) * 0.2;
  color += tunnelPalette(time * 0.02 + r * 0.5, uPalette * 0.1) * edgeGlow;

  // Treble sparkle on ring edges
  float sparkle = abs(sin(warpedZ * uRingCount * 3.14159));
  sparkle = pow(sparkle, 8.0);
  color += vec3(sparkle * trebleVal * 0.3);

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.06);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.2));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
