__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uUnfoldDepth;
uniform float uFacetCount;
uniform float uDispersion;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Kaleidoscopic fold: N-fold rotational symmetry
vec2 kaleidoFold(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

// SDF for a hexagonal shape
float hexSDF(vec2 p) {
  p = abs(p);
  return max(p.x * 0.866025 + p.y * 0.5, p.y) - 1.0;
}

// Flower of life pattern
float flowerOfLife(vec2 p, float scale) {
  float d = 1e10;
  for (int i = 0; i < 6; i++) {
    float angle = float(i) * 1.0472;
    vec2 center = vec2(cos(angle), sin(angle)) * scale;
    d = min(d, abs(length(p - center) - scale));
  }
  d = min(d, abs(length(p) - scale));
  return d;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.4;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);
  float r = length(p);
  float angle = atan(p.y, p.x);

  // === EXTRA DOMAIN WARPING ===
  p += vec2(sin(p.y * 3.0 + time * 0.6) * 0.05, cos(p.x * 3.5 + time * 0.5) * 0.05) * (1.0 + bassVal * 0.5);

  // === ENTITY BREATHING === — 2x
  float breathe = 1.0 + sin(time * 1.5) * 0.1 + beatPulse * 0.2;
  p *= breathe;

  // === KALEIDOSCOPIC FOLDING ===
  vec2 kp = kaleidoFold(p, uFacetCount);

  // === RECURSIVE GEOMETRIC UNFOLDING ===
  vec2 unfoldP = kp;
  float totalDetail = 0.0;

  for (int i = 0; i < 8; i++) {
    if (float(i) >= uUnfoldDepth) break;
    float fi = float(i);
    float scale = 1.0 + fi * 0.5;
    float rotTime = time * (0.3 + fi * 0.1);

    // Rotate at each level
    float ra = rotTime + fi * 0.5;
    float cr = cos(ra); float sr = sin(ra);
    unfoldP = vec2(unfoldP.x * cr - unfoldP.y * sr, unfoldP.x * sr + unfoldP.y * cr);

    // Fold again
    unfoldP = kaleidoFold(unfoldP, uFacetCount - fi);

    // Scale — 2x bass
    unfoldP *= 1.5 + bassVal * 0.4;
    unfoldP -= vec2(1.0 + fi * 0.3, 0.0);

    // Compute detail at this unfolding level
    float hexD = hexSDF(unfoldP * (0.5 + fi * 0.2));
    float lineGlow = exp(-abs(hexD) * (10.0 + fi * 5.0)) * (1.0 - fi / 8.0);

    // Flower of life pattern
    float flowerD = flowerOfLife(unfoldP * 0.3, 0.5);
    float flowerGlow = exp(-flowerD * (15.0 + fi * 3.0)) * 0.5;

    totalDetail += lineGlow + flowerGlow;

    // Color per level — faster cycling
    float levelHue = fi / uUnfoldDepth + uPalette * 0.1 + time * 0.1 + sin(uTime * 0.3) * 0.2;
    vec3 levelCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * levelHue + vec3(0.0, 0.15, 0.35)));
    col += levelCol * (lineGlow + flowerGlow) * 0.5;
  }

  // === JEWELED FACETS: chromatic dispersion ===
  // Shift UV slightly per color channel for gem-like effect
  for (int c = 0; c < 3; c++) {
    float fc = float(c);
    float dispShift = (fc - 1.0) * uDispersion * 0.02 * (1.0 + trebleVal * 2.0);
    vec2 dispP = kaleidoFold(p * (1.0 + dispShift), uFacetCount);
    float dispR = length(dispP);
    float facetPattern = sin(dispR * 30.0 + time * 2.0) * sin(atan(dispP.y, dispP.x) * uFacetCount * 2.0);
    float facetGlow = smoothstep(0.8, 1.0, facetPattern) * 0.3;
    if (c == 0) col.r += facetGlow * (1.0 + midsVal * 1.0);
    if (c == 1) col.g += facetGlow * (1.0 + midsVal * 0.6);
    if (c == 2) col.b += facetGlow * (1.0 + midsVal * 1.4);
  }

  // === CENTRAL SEED: bright glowing core === — 2x bass
  float coreGlow = exp(-r * r * 8.0) * (0.5 + bassVal * 0.6);
  vec3 coreCol = vec3(1.0, 0.9, 0.8);
  col += coreCol * coreGlow;

  // === CRYSTALLINE SPARKLE ===
  float sparkle = 0.0;
  for (int i = 0; i < 20; i++) {
    float fi = float(i);
    float sparkAngle = fi * 0.618033 * 6.2832 + time * 0.5;
    float sparkR = 0.2 + fi * 0.04 + sin(time * 2.0 + fi * 1.3) * 0.05;
    vec2 sparkPos = vec2(cos(sparkAngle), sin(sparkAngle)) * sparkR;
    float d = length(p - sparkPos);
    sparkle += exp(-d * d * 500.0) * trebleVal * 0.3;
  }
  col += vec3(0.9, 0.95, 1.0) * sparkle;

  // Onset flash — 2x
  col += vec3(1.0, 0.85, 0.7) * onsetFlash * 0.4;

  // Beat pulse — 2x
  col *= 1.0 + beatPulse * 0.4;

  // Extreme contrast
  col = pow(col, vec3(0.85));
  col = smoothstep(vec3(0.0), vec3(0.9), col);

  // Overall intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uLayerCount;
uniform float uGlowWidth;
uniform float uRotationDelta;

#define PI 3.14159265
#define TAU 6.28318530

vec3 yantraPalette(float t, float offset) {
  // Warm golden/saffron tones with deep reds and purples
  return vec3(
    0.55 + 0.45 * cos(TAU * (t + 0.0 + offset * 0.2)),
    0.4 + 0.35 * cos(TAU * (t + 0.1 + offset * 0.2)),
    0.35 + 0.4 * cos(TAU * (t + 0.5 + offset * 0.2))
  );
}

// Triangle edge SDF: returns distance to edges of triangle
float triangleSDF(vec2 p, vec2 a, vec2 b, vec2 c) {
  vec2 e0 = b - a;
  vec2 e1 = c - b;
  vec2 e2 = a - c;

  vec2 v0 = p - a;
  vec2 v1 = p - b;
  vec2 v2 = p - c;

  // Distance to each edge
  float d0 = abs(v0.x * e0.y - v0.y * e0.x) / length(e0);
  float d1 = abs(v1.x * e1.y - v1.y * e1.x) / length(e1);
  float d2 = abs(v2.x * e2.y - v2.y * e2.x) / length(e2);

  // Clamp to segment (approximate)
  float t0 = clamp(dot(v0, e0) / dot(e0, e0), 0.0, 1.0);
  float t1 = clamp(dot(v1, e1) / dot(e1, e1), 0.0, 1.0);
  float t2 = clamp(dot(v2, e2) / dot(e2, e2), 0.0, 1.0);

  float seg0 = length(v0 - e0 * t0);
  float seg1 = length(v1 - e1 * t1);
  float seg2 = length(v2 - e2 * t2);

  return min(min(seg0, seg1), seg2);
}

// Glow from a triangle wireframe
float triangleGlow(vec2 p, vec2 a, vec2 b, vec2 c, float width) {
  float d = triangleSDF(p, a, b, c);
  return smoothstep(width, 0.0, d);
}

// Equilateral triangle vertices at given radius and rotation
void triVerts(float radius, float rotation, out vec2 v0, out vec2 v1, out vec2 v2) {
  v0 = vec2(cos(rotation + PI * 0.5), sin(rotation + PI * 0.5)) * radius;
  v1 = vec2(cos(rotation + PI * 0.5 + TAU / 3.0), sin(rotation + PI * 0.5 + TAU / 3.0)) * radius;
  v2 = vec2(cos(rotation + PI * 0.5 + TAU * 2.0 / 3.0), sin(rotation + PI * 0.5 + TAU * 2.0 / 3.0)) * radius;
}

// Circle wireframe
float circleGlow(vec2 p, float radius, float width) {
  return smoothstep(width, 0.0, abs(length(p) - radius));
}

// Lotus petal at angle
float lotusPetal(vec2 p, float angle, float innerR, float outerR, float width) {
  float a = atan(p.y, p.x) - angle;
  float r = length(p);
  // Petal shape: elliptical
  float petalR = innerR + (outerR - innerR) * cos(a * 4.0) * cos(a * 4.0);
  float petalD = abs(r - mix(innerR, petalR, smoothstep(-0.4, 0.0, cos(a * 4.0))));
  return smoothstep(width, 0.0, petalD) * smoothstep(0.4, 0.0, abs(a));
}

void main() {
  float time = uTime * (uSpeed * 1.0);
  vec2 p = (vUv - 0.5) * 2.0 * (uZoom * 1.5 + 0.5);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float gw = 0.003 + uGlowWidth * 0.015;
  float glowW = gw * (2.5 + bassVal * 5.0);

  vec3 color = vec3(0.0);

  int layers = int(2.0 + uLayerCount * 7.0); // 2-9 triangle layers

  // Sri Yantra: interlocking upward and downward triangles at varying scales — expanded
  float baseScale = 0.9 + bassVal * 0.12;

  for (int i = 0; i < 9; i++) {
    if (i >= layers) break;
    float fi = float(i);

    // Alternating up/down triangles
    float isDown = mod(fi, 2.0);
    float triRotation = isDown * PI; // flip for downward

    // Each layer has slightly different scale (creating the nested pattern) — expanded
    float layerScale = baseScale * (0.3 + fi * 0.12);

    // Layer rotation animation (each layer at different speed) — faster
    float layerRot = time * (0.08 + fi * uRotationDelta * 0.04);
    layerRot += beatPulse * 0.4 * (1.0 - fi * 0.08);

    vec2 v0, v1, v2;
    triVerts(layerScale, triRotation + layerRot, v0, v1, v2);

    float triG = triangleGlow(p, v0, v1, v2, glowW);

    // Color per layer — more color segments
    float colorT = fi * 0.15 + midsVal * 0.5 + time * 0.06 + sin(fi * 1.5) * 0.1;
    vec3 layerColor = yantraPalette(colorT, uPalette);

    color += triG * layerColor * 0.4;

    // Vertex glow (treble)
    float v0glow = smoothstep(0.04, 0.0, length(p - v0));
    float v1glow = smoothstep(0.04, 0.0, length(p - v1));
    float v2glow = smoothstep(0.04, 0.0, length(p - v2));
    color += (v0glow + v1glow + v2glow) * layerColor * trebleVal * 0.5;
  }

  // Concentric circles (bounding rings) — expanded
  color += circleGlow(p, baseScale * 1.1, glowW * 0.8) * yantraPalette(time * 0.02, uPalette) * 0.3;
  color += circleGlow(p, baseScale * 0.85, glowW * 0.6) * yantraPalette(time * 0.02 + 0.3, uPalette) * 0.2;
  color += circleGlow(p, baseScale * 1.4, glowW * 0.5) * yantraPalette(time * 0.02 + 0.6, uPalette) * 0.15;

  // Lotus petals around outer ring — larger, more petals
  float petalGlow = 0.0;
  for (int i = 0; i < 24; i++) {
    float pAngle = float(i) * TAU / 24.0 + time * 0.04;
    petalGlow += lotusPetal(p, pAngle, baseScale * 0.95, baseScale * 1.35, glowW * 1.5);
  }
  color += petalGlow * yantraPalette(time * 0.08 + 0.5, uPalette) * 0.2;

  // Bindu (central point) — pulsing with kick
  float bindu = smoothstep(0.05, 0.0, length(p)) * (0.8 + kickVal * 2.0);
  color += bindu * yantraPalette(time * 0.1, uPalette + 0.5);

  // Background ambient — fill screen
  float bgGlow = 0.03 + 0.02 * sin(atan(p.y, p.x) * 6.0 + time * 0.2);
  color += yantraPalette(time * 0.01, uPalette) * bgGlow;

  // Chaos: subtle wobble
  float chaosOff = uChaos * 0.03 * sin(length(p) * 10.0 + time * 2.0);
  color += chaosOff;

  // Beat brightness
  color += beatPulse * 0.1;

  // Onset color shift
  color = mix(color, color.brg, onsetVal * 0.2);

  // Intensity
  color *= uIntensity * 1.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCoherence;
uniform float uPatternFreq;
uniform float uNoiseGrain;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash3(vec3 p) {
  p = fract(p * vec3(443.897, 441.423, 437.195));
  p += dot(p, p.yzx + 19.19);
  return fract((p.x + p.y) * p.z);
}

// Value noise
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// FBM
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p *= 2.1;
    a *= 0.5;
  }
  return v;
}

// Symmetrical face-like pattern via mirrored coordinates
float facePattern(vec2 p, float time) {
  // Mirror horizontally for bilateral symmetry
  vec2 mp = vec2(abs(p.x), p.y);

  // Eye-like circles
  float eye1 = smoothstep(0.08, 0.05, length(mp - vec2(0.15, 0.1)));
  float eye2 = smoothstep(0.04, 0.02, length(mp - vec2(0.15, 0.1)));

  // Mouth-like arc
  float mouthY = -0.15 + mp.x * mp.x * 0.5;
  float mouth = smoothstep(0.03, 0.01, abs(p.y - mouthY)) * step(abs(p.x), 0.2);

  // Face outline: oval
  float oval = smoothstep(0.35, 0.33, length(p * vec2(1.0, 0.8)));
  float outline = smoothstep(0.35, 0.33, length(p * vec2(1.0, 0.8))) -
                  smoothstep(0.33, 0.31, length(p * vec2(1.0, 0.8)));

  return (eye1 - eye2 * 0.5 + mouth + outline) * oval;
}

// Geometric pattern: concentric rings + radial lines
float geometricPattern(vec2 p, float time) {
  float r = length(p);
  float a = atan(p.y, p.x);

  // Concentric rings
  float rings = sin(r * 20.0 - time * 2.0) * 0.5 + 0.5;
  rings = smoothstep(0.4, 0.6, rings);

  // Radial lines
  float sectors = 8.0;
  float radial = smoothstep(0.02, 0.0, abs(sin(a * sectors)));

  return rings * 0.5 + radial * 0.3;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // === PURE STATIC NOISE ===
  float grain = uNoiseGrain * (200.0 + trebleVal * 100.0);
  vec2 noiseCoord = floor(p * grain + uZoom * 50.0) / grain;
  float timeQuantized = floor(time * 30.0); // 30fps static refresh
  float staticNoise = hash(noiseCoord + timeQuantized);

  // Slight scanline effect
  float scanline = sin(vUv.y * grain * 3.14159) * 0.1 + 0.9;
  staticNoise *= scanline;

  // === ORGANIZED PATTERNS ===
  // Coherence oscillates over time: moments of organization then dissolution
  float coherenceCycle = sin(time * uPatternFreq * 0.3) * 0.5 + 0.5;
  coherenceCycle = pow(coherenceCycle, 2.0); // sharper peaks
  float effectiveCoherence = uCoherence * (coherenceCycle + bassVal * 0.5 + beatPulse * 0.8);
  effectiveCoherence = clamp(effectiveCoherence, 0.0, 1.0);

  // Pattern selection cycles
  float patternPhase = fract(time * uPatternFreq * 0.1);

  // Face pattern
  float face = facePattern(p * (0.8 + uZoom * 0.5), time);

  // Geometric pattern
  float geom = geometricPattern(p * (1.0 + uZoom * 0.5), time);

  // FBM organic pattern
  float organic = fbm(p * 3.0 + time * 0.2);

  // Blend between patterns based on phase
  float pattern = 0.0;
  if (patternPhase < 0.33) {
    pattern = mix(face, geom, smoothstep(0.25, 0.33, patternPhase) * 3.0);
  } else if (patternPhase < 0.66) {
    pattern = mix(geom, organic, (patternPhase - 0.33) * 3.0);
  } else {
    pattern = mix(organic, face, (patternPhase - 0.66) * 3.0);
  }

  // === MIX STATIC AND PATTERN ===
  float mixed = mix(staticNoise, pattern, effectiveCoherence);

  // Kick: burst of pure static
  mixed = mix(mixed, hash(noiseCoord + kickPulse * 100.0), kickPulse * 0.7);

  // Color: mostly grayscale with subtle color based on palette + mids
  vec3 col = vec3(mixed);

  // Subtle color tinting during organized moments
  float colorAmount = effectiveCoherence * 0.4;
  float hue = fract(time * 0.05 + uPalette * 0.1 + midsVal * 0.2);
  vec3 tint = 0.5 + 0.5 * cos(6.283 * (hue + vec3(0.0, 0.33, 0.67)));
  col = mix(col, col * tint, colorAmount);

  // Chromatic aberration during high chaos
  float aberration = uChaos * 0.01 * (1.0 + kickPulse * 3.0);
  float rShift = hash(floor((p + vec2(aberration, 0.0)) * grain + timeQuantized) / grain + timeQuantized);
  float bShift = hash(floor((p - vec2(aberration, 0.0)) * grain + timeQuantized) / grain + timeQuantized);
  col.r = mix(col.r, mix(rShift, pattern, effectiveCoherence), aberration * 30.0);
  col.b = mix(col.b, mix(bShift, pattern, effectiveCoherence), aberration * 30.0);

  // CRT curvature
  float vig = 1.0 - pow(length(p * 0.6), 2.0) * 0.3;
  col *= vig;

  // Horizontal noise band (VHS-like)
  float band = smoothstep(0.0, 0.02, abs(p.y - sin(time * 3.0) * 0.8)) * 0.3 + 0.7;
  col *= band;

  // Intensity
  col *= uIntensity * 1.5;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPillarDensity;
uniform float uStarCount;
uniform float uEmissionStrength;
uniform float uGasScale;

// 2D hash for star placement
float hash2(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

float hash1(float n) {
  return fract(sin(n) * 43758.5453);
}

// 2D value noise with smooth interpolation
float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  float ux = fx * fx * (3.0 - fx * 2.0);
  float uy = fy * fy * (3.0 - fy * 2.0);
  float n00 = hash2(ix, iy);
  float n10 = hash2(ix + 1.0, iy);
  float n01 = hash2(ix, iy + 1.0);
  float n11 = hash2(ix + 1.0, iy + 1.0);
  float nx0 = mix(n00, n10, ux);
  float nx1 = mix(n01, n11, ux);
  return mix(nx0, nx1, uy);
}

// 4-octave FBM in 2D
float fbm2d(float x, float y) {
  float acc = 0.0;
  acc += noise2d(x, y) * 0.5;
  acc += noise2d(x * 2.03, y * 2.03) * 0.25;
  acc += noise2d(x * 4.01, y * 4.01) * 0.125;
  acc += noise2d(x * 8.05, y * 8.05) * 0.0625;
  return acc;
}

// Star lifecycle phases:
// 0.00-0.10: Nebula condensation (dim glow, gas collapsing)
// 0.10-0.20: Protostar (growing brightness, reddish)
// 0.20-0.60: Main sequence (bright, stable, white-yellow)
// 0.60-0.75: Red giant (expanding, reddening)
// 0.75-0.82: Supernova explosion (massive flash + expanding shell)
// 0.82-1.00: Remnant (fading nebula remnant, dim)

// Star color based on lifecycle phase
vec3 starLifecycleColor(float phase) {
  // Nebula condensation: dim blue-violet
  vec3 nebulaCol = vec3(0.3, 0.2, 0.7);
  // Protostar: warm orange-red
  vec3 protoCol = vec3(1.0, 0.4, 0.15);
  // Main sequence: bright white-yellow
  vec3 mainCol = vec3(1.0, 1.0, 0.9);
  // Red giant: deep red-orange
  vec3 giantCol = vec3(1.0, 0.4, 0.08);
  // Supernova: white-blue flash
  vec3 supernovaCol = vec3(1.0, 1.0, 0.95);
  // Remnant: dim blue-purple
  vec3 remnantCol = vec3(0.2, 0.15, 0.45);

  vec3 col = nebulaCol;
  col = mix(col, protoCol, smoothstep(0.08, 0.15, phase));
  col = mix(col, mainCol, smoothstep(0.15, 0.25, phase));
  col = mix(col, giantCol, smoothstep(0.55, 0.7, phase));
  col = mix(col, supernovaCol, smoothstep(0.74, 0.77, phase));
  col = mix(col, remnantCol, smoothstep(0.82, 0.9, phase));
  return col;
}

// Star size/brightness based on lifecycle phase
float starLifecycleBrightness(float phase) {
  float nebula = smoothstep(0.0, 0.1, phase) * 0.15;
  float proto = smoothstep(0.1, 0.2, phase) * 0.5;
  float main = smoothstep(0.2, 0.3, phase) * 1.0;
  float giant = 1.0 + smoothstep(0.6, 0.72, phase) * 1.5;
  float supernova = 1.0 + smoothstep(0.74, 0.77, phase) * 8.0;
  float postSN = 1.0 - smoothstep(0.77, 0.85, phase) * 0.9;
  float remnant = 0.1 * (1.0 - smoothstep(0.9, 1.0, phase));

  float brightness = nebula;
  brightness = max(brightness, proto * (1.0 - smoothstep(0.15, 0.2, phase)));
  brightness = mix(brightness, main, smoothstep(0.18, 0.25, phase));
  brightness = mix(brightness, giant, smoothstep(0.55, 0.7, phase));
  brightness = mix(brightness, supernova, smoothstep(0.74, 0.78, phase));
  brightness *= postSN;
  brightness = max(brightness, remnant);
  return brightness;
}

// Star visual radius based on lifecycle
float starLifecycleRadius(float phase) {
  float r = 0.01;
  r = mix(r, 0.02, smoothstep(0.0, 0.1, phase));    // nebula condensing
  r = mix(r, 0.015, smoothstep(0.1, 0.2, phase));    // protostar compact
  r = mix(r, 0.012, smoothstep(0.2, 0.3, phase));    // main sequence tight
  r = mix(r, 0.04, smoothstep(0.6, 0.72, phase));    // red giant expands
  r = mix(r, 0.15, smoothstep(0.74, 0.78, phase));   // supernova blast
  r = mix(r, 0.06, smoothstep(0.8, 0.85, phase));    // shell expanding
  r = mix(r, 0.03, smoothstep(0.85, 1.0, phase));    // remnant fading
  return r;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio influences
  float bassUndulate = bass() * uSensitivity;
  float midsBalance = mids() * uSensitivity;
  float trebleStars = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // === GAS PILLAR LAYER ===
  float pillarShiftX = sin(time * 0.45) * (bassUndulate * 0.8);
  float pillarShiftY = cos(time * 0.3) * (bassUndulate * 0.6);

  float gasX = p.x * uGasScale + pillarShiftX + 17.3;
  float gasY = p.y * uGasScale + pillarShiftY + 31.7;
  float gasDensity = fbm2d(gasX, gasY);

  float gas2X = p.x * (uGasScale * 1.7) - pillarShiftX * 0.5 + 53.1;
  float gas2Y = p.y * (uGasScale * 1.5) + pillarShiftY * 0.3 + 97.3;
  float gasDensity2 = fbm2d(gas2X, gas2Y);

  float dustX = p.x * (uGasScale * 3.0) + time * 0.05;
  float dustY = p.y * (uGasScale * 3.5) - time * 0.03;
  float dustDensity = fbm2d(dustX, dustY);

  float combinedGas = gasDensity * 0.5 + gasDensity2 * 0.3 + dustDensity * 0.2;
  float pillarThreshold = 0.5 - uPillarDensity * 0.2 - uChaos * 0.1;
  float pillarMask = smoothstep(pillarThreshold, pillarThreshold + 0.15, combinedGas);

  // === NEBULAR EMISSION ===
  float haR = 1.0; float haG = 0.2; float haB = 0.16;
  float o3R = 0.08; float o3G = 0.85; float o3B = 0.75;

  float emissionMix = clamp(midsBalance * 0.5 + 0.4 + uPalette * 0.05, 0.0, 1.0);
  float emR = mix(haR, o3R, emissionMix);
  float emG = mix(haG, o3G, emissionMix);
  float emB = mix(haB, o3B, emissionMix);

  float edgeGlow = smoothstep(pillarThreshold - 0.1, pillarThreshold + 0.05, combinedGas)
    * (1.0 - smoothstep(pillarThreshold + 0.05, pillarThreshold + 0.25, combinedGas));
  float emissionBright = (1.0 - pillarMask * 0.7) * uEmissionStrength + edgeGlow * 0.5;

  // === BACKGROUND STARFIELD ===
  float starGridScale = uStarCount;
  float starGx = p.x * starGridScale;
  float starGy = p.y * starGridScale;
  float starCellX = fract(starGx) - 0.5;
  float starCellY = fract(starGy) - 0.5;
  float starIdX = starGx - starCellX - 0.5;
  float starIdY = starGy - starCellY - 0.5;

  float sh1 = hash2(starIdX, starIdY);
  float sh2 = hash2(starIdX + 37.0, starIdY + 73.0);
  float starOffX = (sh1 - 0.5) * 0.6;
  float starOffY = (sh2 - 0.5) * 0.6;
  float starDx = starCellX - starOffX;
  float starDy = starCellY - starOffY;
  float starD = starDx * starDx + starDy * starDy;

  float starThreshold = 0.004 + trebleStars * 0.003;
  float starBright = smoothstep(starThreshold, 0.0, starD) * sh1;
  float starObscured = starBright * (1.0 - pillarMask * 0.9);

  // === LIFECYCLE STARS — 10 stars across full screen with full birth-death cycles ===
  float lifecycleR = 0.0;
  float lifecycleG = 0.0;
  float lifecycleB = 0.0;

  for (int si = 0; si < 10; si++) {
    float fi = float(si);
    // Deterministic position from hash — spread across full screen
    float seed1 = hash1(fi * 73.17 + 19.3);
    float seed2 = hash1(fi * 137.3 + 43.7);
    float seed3 = hash1(fi * 251.7 + 89.1);
    float seed4 = hash1(fi * 311.1 + 127.3);

    // Each star has a unique cycle duration
    float cycleDuration = 12.0 + seed3 * 18.0; // 12-30 second cycles
    float offset = seed4 * cycleDuration;        // staggered

    // Position: unique per generation (changes after each death)
    float generation = floor((time + offset) / cycleDuration);
    float genSeed1 = hash1(fi * 47.3 + generation * 13.7);
    float genSeed2 = hash1(fi * 89.1 + generation * 23.1);

    float starX = (seed1 - 0.5) * 2.5 + (genSeed1 - 0.5) * 0.4;
    float starY = (seed2 - 0.5) * 2.5 + (genSeed2 - 0.5) * 0.4;

    // Lifecycle phase
    float phase = fract((time + offset) / cycleDuration);

    // Bass triggers supernova earlier when star is in late main sequence
    float bassBoost = bassUndulate * 0.05 * smoothstep(0.5, 0.7, phase);
    phase = min(phase + bassBoost, 0.99);

    // Treble accelerates nebula condensation (new star formation)
    float trebleBoost = trebleStars * 0.03 * smoothstep(0.0, 0.1, phase) * (1.0 - smoothstep(0.1, 0.2, phase));
    phase = min(phase + trebleBoost, 0.99);

    float brightness = starLifecycleBrightness(phase);
    float radius = starLifecycleRadius(phase);
    vec3 sColor = starLifecycleColor(phase);

    // Beat enhances brightness
    brightness *= 1.0 + beatPulse * 0.6;

    // Distance from this pixel to the star
    float dx = p.x - starX;
    float dy = p.y - starY;
    float distSq = dx * dx + dy * dy + 0.0001;
    float dist = sqrt(distSq);

    // Point light glow
    float glow = brightness * 0.015 / distSq;

    // Supernova expanding shell (phase 0.75-0.85)
    float snPhase = smoothstep(0.74, 0.78, phase) * (1.0 - smoothstep(0.8, 0.88, phase));
    float shellRadius = smoothstep(0.74, 0.85, phase) * 0.25;
    float shellDist = abs(dist - shellRadius);
    float shell = exp(-shellDist * 30.0) * snPhase * 2.0;

    // Nebula condensation cloud (phase 0.0-0.15) — soft glow
    float nebulaPhase = smoothstep(0.0, 0.05, phase) * (1.0 - smoothstep(0.1, 0.2, phase));
    float nebulaCloud = exp(-distSq * 50.0) * nebulaPhase * 0.5;
    float nebulaSwirl = fbm2d(p.x * 8.0 + starX * 10.0, p.y * 8.0 + starY * 10.0 + time * 0.5);
    nebulaCloud *= 0.5 + nebulaSwirl * 0.5;

    // Remnant nebula (phase 0.82-1.0) — expanding colored shell
    float remnantPhase = smoothstep(0.82, 0.88, phase) * (1.0 - smoothstep(0.92, 1.0, phase));
    float remnantRadius = smoothstep(0.82, 1.0, phase) * 0.15;
    float remnantDist = abs(dist - remnantRadius);
    float remnant = exp(-remnantDist * 15.0) * remnantPhase * 0.6;
    vec3 remnantCol = vec3(0.2, 0.1, 0.4) + vec3(0.1, 0.3, 0.0) * sin(atan(dy, dx) * 3.0 + time);

    // Obscure behind gas pillars
    float obscure = 1.0 - pillarMask * 0.7;

    // Accumulate
    lifecycleR += (glow * sColor.r + shell * 1.0 + nebulaCloud * 0.2 + remnant * remnantCol.r) * obscure;
    lifecycleG += (glow * sColor.g + shell * 0.8 + nebulaCloud * 0.15 + remnant * remnantCol.g) * obscure;
    lifecycleB += (glow * sColor.b + shell * 0.9 + nebulaCloud * 0.4 + remnant * remnantCol.b) * obscure;
  }

  lifecycleR = clamp(lifecycleR, 0.0, 3.0);
  lifecycleG = clamp(lifecycleG, 0.0, 3.0);
  lifecycleB = clamp(lifecycleB, 0.0, 3.0);

  // === ABSORPTION LANES ===
  float absorption = smoothstep(0.7, 0.85, combinedGas);

  // === COMBINE ===
  float finalR = 0.01;
  float finalG = 0.005;
  float finalB = 0.015;

  // Emission nebula background
  finalR += emR * emissionBright * uIntensity;
  finalG += emG * emissionBright * uIntensity;
  finalB += emB * emissionBright * uIntensity;

  // Lifecycle stars
  finalR += lifecycleR * uIntensity;
  finalG += lifecycleG * uIntensity;
  finalB += lifecycleB * uIntensity;

  // Apply absorption
  finalR *= (1.0 - absorption * 0.85);
  finalG *= (1.0 - absorption * 0.85);
  finalB *= (1.0 - absorption * 0.85);

  // Background stars
  finalR += starObscured * 1.0;
  finalG += starObscured * 0.95;
  finalB += starObscured * 0.85;

  // Beat pulse brightness
  float pulse = beatPulse * 0.3;
  finalR += pulse * (emR * 0.3 + 0.05);
  finalG += pulse * (emG * 0.3 + 0.05);
  finalB += pulse * (emB * 0.3 + 0.05);

  // Onset stellar flash
  float flash = onsetFlash * 0.6;
  finalR += flash * 0.15;
  finalG += flash * 0.12;
  finalB += flash * 0.1;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(finalR, finalG, finalB)); finalR = _pc.r; finalG = _pc.g; finalB = _pc.b; }
  gl_FragColor = vec4(
    clamp(finalR, 0.0, 1.0),
    clamp(finalG, 0.0, 1.0),
    clamp(finalB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSnapRate;
uniform float uSmoothBlend;
uniform float uFreezeDepth;
uniform float uStrobeSharp;

vec2 rotate2d(vec2 p, float a) {
  float s = sin(a);
  float c = cos(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Generate a complex geometric pattern
float frozenPattern(vec2 p, float t, float depth) {
  float result = 0.0;

  // Layer 1: rotating hexagonal cells
  for (float i = 0.0; i < 4.0; i += 1.0) {
    if (i >= depth) break;
    float scale = 2.0 + i * 1.5;
    vec2 rp = rotate2d(p, t * (0.3 + i * 0.1));
    vec2 q = rp * scale;

    // Hex distance
    vec2 r = fract(q) - 0.5;
    float hex = max(abs(r.x) * 0.866 + abs(r.y) * 0.5, abs(r.y));
    float cell = smoothstep(0.4, 0.38, hex);

    // Internal pattern
    float inner = sin(atan(r.y, r.x) * 3.0 + t * 2.0 + i) * 0.5 + 0.5;
    inner *= smoothstep(0.4, 0.1, hex);

    result += (cell * 0.4 + inner * 0.6) / (1.0 + i * 0.5);
  }

  // Add pulsing rings
  float ringDist = length(p);
  float rings = sin(ringDist * 8.0 - t * 3.0) * 0.5 + 0.5;
  rings *= exp(-ringDist * 1.5);
  result += rings * 0.3;

  return result;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Stroboscopic time: snap to discrete steps
  float snapFreq = uSnapRate + bassVal * 4.0;
  float continuousPhase = time * snapFreq;
  float snappedPhase = floor(continuousPhase);
  float fracPhase = fract(continuousPhase);

  // Sharp snap transition (power curve for hard edges)
  float snapCurve = pow(fracPhase, uStrobeSharp);

  // Blend between snapped and continuous time
  float blend = uSmoothBlend + kickVal * 0.3;
  float displayTime = mix(snappedPhase / snapFreq, time, blend);

  // Smooth rotation happens independently of the snap
  float smoothRotation = time * 0.2;
  vec2 rp = rotate2d(p, smoothRotation);

  // Generate the frozen pattern
  float pattern = frozenPattern(rp, displayTime, uFreezeDepth);

  // Strobe brightness modulation
  float strobeFlash = smoothstep(0.0, 0.15, fracPhase) * smoothstep(1.0, 0.7, fracPhase);
  strobeFlash = mix(1.0, strobeFlash, 0.3 + onsetVal * 0.4);

  // Color from pattern
  float hue = fract(pattern * 0.5 + displayTime * 0.05 + uPalette * 0.1 + midsVal * 0.15);
  float sat = 0.7 + pattern * 0.25;
  float val = pattern * strobeFlash * 0.8;

  // Chaos adds hue jitter between snap frames
  hue += sin(snappedPhase * 7.13) * uChaos * 0.15;

  vec3 color = hsv2rgb(vec3(hue, clamp(sat, 0.0, 1.0), clamp(val, 0.0, 1.0)));

  // Flash on snap transitions
  float snapFlash = 1.0 - smoothstep(0.0, 0.1, fracPhase);
  color += vec3(snapFlash * 0.15 * kickVal);

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat pulse
  color += vec3(uBeat * uSensitivity * 0.06);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.3));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRingCount;
uniform float uRingWidth;

vec3 palette(float t) {
  float r = 0.5 + 0.5 * cos(6.28318 * (t + 0.0));
  float g = 0.5 + 0.5 * cos(6.28318 * (t + 0.33));
  float b = 0.5 + 0.5 * cos(6.28318 * (t + 0.67));
  return vec3(r, g, b);
}

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.8;

  // Audio
  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetPulse = uOnset * uSensitivity;
  float kickPulse = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Distance from center
  float dist = length(p);

  // Ring parameters
  int numRings = int(uRingCount * 10.0) + 4; // 4-14 rings
  float baseWidth = uRingWidth * 0.06 + 0.015; // 0.015 - 0.075
  float maxRadius = 1.8;
  float ringSpeed = 0.3 + energyVal * 0.1;

  // Bass thickens rings
  float width = baseWidth + bassVal * 0.03;

  // Accumulate ring colors
  vec3 ringAccum = vec3(0.0);

  for (int i = 0; i < 14; i++) {
    if (i >= numRings) break;

    float fi = float(i);
    float spacing = 1.0 / float(numRings);

    // Each ring has its own phase (expanding outward)
    float ringPhase = fract(time * ringSpeed - fi * spacing);
    float ringRadius = ringPhase * maxRadius;

    // Ring brightness: smoothstep band, fades as it expands
    float ringDist = abs(dist - ringRadius);

    // Treble sharpens the ring edges (smaller effective width = sharper)
    float effectiveWidth = width * (1.0 - trebleVal * 0.3);
    effectiveWidth = max(effectiveWidth, 0.005);

    float ringBright = smoothstep(effectiveWidth, effectiveWidth * 0.2, ringDist);

    // Fade as ring expands outward
    float fadeFactor = 1.0 - ringPhase;
    fadeFactor = fadeFactor * fadeFactor; // quadratic fade
    ringBright *= fadeFactor;

    // Beat brightens all rings
    ringBright *= (1.0 + beatPulse * 0.6);

    // Each ring gets a unique color from palette
    vec3 ringCol = palette(fi * 0.12 + uPalette * 0.15 + time * 0.03);

    // Saturate the color more
    ringCol = ringCol * 1.3;

    ringAccum += ringCol * ringBright;
  }

  // === KICK/ONSET SPECIAL RING ===
  float specialPhase = fract(time * 0.5);
  float specialRadius = specialPhase * maxRadius * 0.8;
  float specialDist = abs(dist - specialRadius);
  float specialBright = smoothstep(width * 0.5, 0.0, specialDist) * (1.0 - specialPhase);
  specialBright *= (kickPulse * 0.8 + onsetPulse * 0.6);
  vec3 specialCol = vec3(1.0, 0.95, 0.9) * specialBright;

  // === BACKGROUND: Dark with subtle radial texture ===
  float radialNoise = hash(floor(atan(p.y, p.x) * 20.0 + time * 0.5) + floor(dist * 15.0) * 7.0);
  float bgTexture = radialNoise * 0.02;

  // Subtle radial gradient
  float bgGrad = smoothstep(1.5, 0.0, dist) * 0.03;

  // Subtle rotating spoke pattern
  float angle = atan(p.y, p.x);
  float spokes = sin(angle * 12.0 + time * 0.2) * 0.5 + 0.5;
  spokes *= smoothstep(0.0, 0.3, dist) * smoothstep(1.5, 0.5, dist);
  float spokeColor = spokes * 0.025 * (1.0 + midsVal * 0.5);

  vec3 bg = vec3(0.01, 0.01, 0.02) + bgTexture + bgGrad + spokeColor * palette(angle * 0.16 + uPalette * 0.1);

  // === COMBINE ===
  vec3 col = bg + ringAccum + specialCol;

  // Overall intensity
  col *= uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uMassScale;
uniform float uJetPower;
uniform float uLensRadius;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    val += amp * noise(p);
    p *= 2.1;
    amp *= 0.5;
  }
  return val;
}

// Accretion disk color based on temperature
vec3 accretionTemp(float temp, float angle) {
  float doppler = sin(angle) * 0.3;
  float t = clamp(temp + doppler, 0.0, 1.0);
  vec3 cool = vec3(0.55, 0.04, 0.0);
  vec3 warm = vec3(1.0, 0.55, 0.08);
  vec3 hot = vec3(1.0, 0.95, 1.0);
  vec3 col = mix(cool, warm, smoothstep(0.0, 0.5, t));
  col = mix(col, hot, smoothstep(0.5, 1.0, t));
  return col;
}

void main() {
  vec2 p = (vUv - 0.5) * (1.5 + uZoom * 1.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.65;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Gravitational lensing: warp coordinates — stronger for bigger effect
  float mass = uMassScale * (1.0 + bassVal * 1.0);
  float lensR = uLensRadius * 0.3;
  float lensStrength = mass * 0.4 / (r * r + lensR * lensR);
  vec2 lensedP = p + normalize(p + 0.0001) * lensStrength;

  // Event horizon — much larger, fills significant portion of screen
  float eventHorizonR = 0.35 * mass;
  float eventHorizon = smoothstep(eventHorizonR * 1.5, eventHorizonR, r);

  // Photon sphere (bright ring at 1.5x event horizon)
  float photonR = eventHorizonR * 1.5;
  float photonRing = exp(-pow((r - photonR) / 0.012, 2.0)) * 2.0;

  // Accretion disk (torus seen at angle) — expands with larger event horizon
  float diskInner = eventHorizonR * 1.8;
  float diskOuter = eventHorizonR * 8.0;
  float diskY = abs(p.y) * 3.0; // Flatten to disk shape
  float diskR = length(vec2(p.x, diskY));
  float inDisk = smoothstep(diskOuter, diskOuter - 0.05, diskR)
               * smoothstep(diskInner - 0.02, diskInner, diskR);
  float diskThinness = exp(-p.y * p.y * 100.0); // Thin disk in y

  // Disk temperature (hotter near center)
  float diskTemp = clamp(1.0 - (diskR - diskInner) / (diskOuter - diskInner), 0.0, 1.0);
  float diskAngle = atan(diskY * sign(p.y), p.x) + time * 2.0;

  // Disk turbulence
  float diskTurb = sin(diskAngle * 5.0 + diskR * 30.0 + time) * 0.1 + 0.9;
  diskTurb += noise(vec2(diskAngle * 2.0, diskR * 10.0) + time * 0.5) * midsVal * 0.4;

  vec3 diskColor = accretionTemp(diskTemp, diskAngle) * inDisk * diskThinness * diskTurb * 2.2;

  // Frame-dragging ergosphere spirals — extended outward from larger horizon
  float frameDrag = sin(angle * 3.0 - r * 10.0 + time * 3.0) * 0.5 + 0.5;
  frameDrag *= smoothstep(eventHorizonR * 5.0, eventHorizonR * 1.5, r);
  frameDrag *= smoothstep(eventHorizonR, eventHorizonR * 1.5, r);
  frameDrag = pow(frameDrag, 2.0) * 0.5;
  vec3 ergosphereColor = vec3(0.3, 0.45, 1.0) * frameDrag;

  // Relativistic jets (bipolar beams from poles) — wider and longer
  float jetAxis = abs(p.y); // Jet along vertical
  float jetWidth = 0.06 + jetAxis * 0.04;
  float jetShape = exp(-p.x * p.x / (jetWidth * jetWidth));
  float jetLength = step(eventHorizonR * 2.0, jetAxis);
  float jetFade = exp(-jetAxis * 0.8);
  float jetBright = jetShape * jetLength * (1.0 - jetFade);
  jetBright *= uJetPower * (0.7 + trebleVal * 1.0 + beatPulse * 1.0);

  // Jet internal structure
  float jetStructure = sin(jetAxis * 40.0 - time * 8.0) * 0.3 + 0.7;
  float jetKnots = pow(sin(jetAxis * 15.0 - time * 4.0) * 0.5 + 0.5, 4.0);
  jetBright *= jetStructure;

  vec3 jetColor = mix(vec3(0.4, 0.7, 1.0), vec3(0.9, 1.0, 1.0), jetFade) * jetBright;
  jetColor += vec3(1.0, 0.9, 0.7) * jetKnots * jetBright * 0.8;

  // Background stars (warped by lensing)
  vec3 starField = vec3(0.0);
  float starGrid = 100.0;
  vec2 starUV = lensedP * starGrid;
  vec2 starCell = floor(starUV);
  float starH = hash(starCell);
  if (starH > 0.97) {
    vec2 starF = fract(starUV) - 0.5;
    vec2 starOff = vec2(hash(starCell + 10.0), hash(starCell + 20.0)) - 0.5;
    float starDist = length(starF - starOff * 0.3);
    float star = exp(-starDist * starDist * 2000.0) * 0.5;
    float starTemp = hash(starCell + 30.0);
    starField = vec3(0.6 + starTemp * 0.3, 0.7 + starTemp * 0.2, 0.9) * star;
  }

  // Faint nebulosity in background — stronger to fill screen
  float nebula = fbm(lensedP * 2.0 + time * 0.05);
  float nebula2 = fbm(lensedP * 1.0 - time * 0.03);
  vec3 nebulaColor = vec3(0.12, 0.05, 0.18) * nebula + vec3(0.05, 0.03, 0.09) * nebula2;

  // Combine
  vec3 col = nebulaColor + starField;
  col += diskColor;
  col += ergosphereColor;
  col += jetColor;
  col += vec3(0.9, 0.95, 1.0) * photonRing;

  // Event horizon darkening
  col *= (1.0 - eventHorizon * 0.98);

  // Beat accretion flare
  col += vec3(0.4, 0.2, 0.08) * beatPulse * 0.3 * inDisk;

  // Kick jet flare
  col += vec3(0.3, 0.45, 0.8) * kickPulse * 0.4 * jetBright;

  // Energy and intensity
  col *= (0.7 + uEnergy * uSensitivity * 0.8);
  col *= uIntensity * 1.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uBlastRadius;
uniform float uCoreHeat;
uniform float uNebulaFormation;
uniform float uShockWidth;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) { v += a * noise(p); p = rot * p * 2.0; a *= 0.5; }
  return v;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / max(uZoom * 0.8 + 0.3, 0.1);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float fluxVal = uSpectralFlux * uSensitivity;
  float bpm2 = uBpmSin2;

  // Deep space background
  vec3 col = vec3(0.005, 0.003, 0.01);

  // Starfield
  for (float i = 0.0; i < 60.0; i++) {
    vec2 star = vec2(hash(vec2(i, 1.0)), hash(vec2(1.0, i))) * 2.0 - 1.0;
    float sd = length(p - star);
    col += vec3(1.0, 0.95, 1.0) * exp(-sd * 300.0) * 0.15;
  }

  // Multiple explosion events
  for (float e = 0.0; e < 3.0; e++) {
    vec2 center = vec2(
      sin(e * 2.4 + time * 0.1) * 0.3,
      cos(e * 3.1 + time * 0.08) * 0.2
    );

    float r = length(p - center);
    float angle = atan(p.y - center.y, p.x - center.x);

    // Explosion phase — cycles with energy
    float phase = fract(time * 0.22 * (1.0 + energyVal * 1.0) + e * 0.333);

    // Shockwave ring expanding outward
    float shockR = phase * uBlastRadius * 1.5;
    float shockW = uShockWidth * 0.08 * (1.0 + kickVal * 2.0);
    float shock = exp(-pow(r - shockR, 2.0) / (shockW * shockW * 2.0));
    shock *= smoothstep(0.0, 0.1, phase) * (1.0 - smoothstep(0.8, 1.0, phase));

    // Shockwave color: white-hot to blue
    vec3 shockCol = mix(vec3(1.0, 0.95, 0.9), vec3(0.4, 0.5, 1.0), phase);
    shockCol += vec3(0.3, 0.15, 0.0) * uPalette * 0.3;
    col += shockCol * shock * 2.2;

    // Core remnant — white-hot fading
    float coreGlow = exp(-r * (8.0 + phase * 20.0)) * uCoreHeat;
    coreGlow *= (1.0 - phase * 0.8);
    vec3 coreCol = mix(vec3(1.0, 1.0, 0.95), vec3(1.0, 0.6, 0.3), phase * 0.5);
    col += coreCol * coreGlow;

    // Nebula formation behind shockwave
    if (r < shockR) {
      float nebulaT = (shockR - r) / max(shockR, 0.01);
      float nebulaNoise = fbm(p * 3.0 + vec2(time * 0.1, e * 5.0));
      nebulaNoise += fbm(p * 6.0 - time * 0.05) * 0.5;

      vec3 nebulaCol = mix(
        vec3(0.55, 0.15, 0.7),
        vec3(0.3, 0.4, 1.0),
        nebulaNoise
      );
      nebulaCol = mix(nebulaCol, vec3(1.0, 0.4, 0.15), sin(angle * 3.0 + e) * 0.5 + 0.5);

      float nebulaAlpha = nebulaT * phase * uNebulaFormation * 0.4;
      nebulaAlpha *= nebulaNoise * 0.8 + 0.2;
      col += nebulaCol * nebulaAlpha * (0.5 + midsVal * 1.0);
    }

    // Ejected debris/filaments
    for (float f = 0.0; f < 8.0; f++) {
      float fAngle = f * 0.785 + e * 2.0 + time * 0.1;
      vec2 filDir = vec2(cos(fAngle), sin(fAngle));
      float filDist = dot(p - center, filDir);
      float filPerp = length(p - center - filDir * filDist);

      if (filDist > 0.0 && filDist < shockR * 1.1) {
        float filament = exp(-filPerp * 40.0) * exp(-abs(filDist - shockR * 0.5) * 5.0);
        filament *= phase * (1.0 - phase);
        col += vec3(1.0, 0.7, 0.3) * filament * 0.5;
      }
    }
  }

  // Kick triggers bright flash
  col += vec3(0.3, 0.2, 0.15) * kickVal * 0.8;

  // Treble sparkle — hot debris
  float sparkle = noise(p * 30.0 + time * 5.0);
  sparkle = pow(max(sparkle, 0.0), 15.0);
  col += vec3(1.0, 0.85, 0.6) * sparkle * trebleVal * 0.5;

  // Spectral flux drives turbulence brightness
  col += col * fluxVal * 0.5;

  // BPM pulse
  col += col * max(bpm2, 0.0) * 0.15;

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRingCount;
uniform float uExpansionRate;
uniform float uRayIntensity;
uniform float uShockWidth;

// Supernova color palette
vec3 supernovaColor(float t, float paletteOffset) {
  float shifted = clamp(t + paletteOffset * 0.05, 0.0, 1.0);

  vec3 core = vec3(1.0, 1.0, 0.95);
  vec3 orange = vec3(1.0, 0.6, 0.15);
  vec3 red = vec3(0.95, 0.15, 0.08);
  vec3 outer = vec3(0.35, 0.15, 0.7);

  float toOrange = smoothstep(0.0, 0.3, shifted);
  float toRed = smoothstep(0.3, 0.6, shifted);
  float toOuter = smoothstep(0.6, 1.0, shifted);

  vec3 step1 = mix(core, orange, toOrange);
  vec3 step2 = mix(step1, red, toRed);
  return mix(step2, outer, toOuter);
}

void main() {
  // Use centered UVs spanning [-0.5, 0.5] -- NO zoom scaling so effect fills entire screen
  vec2 p = vUv - 0.5;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio modulators
  float onsetPulse = uOnset * uSensitivity;
  float bassThick = bass() * uSensitivity;
  float energyBright = uEnergy * uSensitivity;
  float beatSync = uBeat * uSensitivity;

  // Radial distance from center -- max ~0.707 at corners
  float radius = pow(p.x * p.x + p.y * p.y, 0.5);
  float angle = atan(p.y, p.x);

  // Normalize radius so the full screen diagonal maps to [0, 1]
  float radiusNorm = clamp(radius / 0.707, 0.0, 1.0);

  // --- Expanding shockwave rings (scaled to full screen) ---
  float ringWidth = uShockWidth + bassThick * 0.1;
  // Rings expand across the full radius range [0, 0.707]
  float ringScale = 0.707;

  // Ring layer 1: fast expansion
  float ring1Pos = fract(time * (uExpansionRate * 0.3) + onsetPulse * 0.2) * ringScale;
  float ring1Dist = abs(radius - ring1Pos);
  float ring1 = smoothstep(ringWidth, ringWidth * 0.2, ring1Dist);

  // Ring layer 2
  float ring2Pos = fract(time * (uExpansionRate * 0.22) + 0.33 + onsetPulse * 0.15) * ringScale;
  float ring2Dist = abs(radius - ring2Pos);
  float ring2 = smoothstep(ringWidth * 0.9, ringWidth * 0.15, ring2Dist);

  // Ring layer 3
  float ring3Pos = fract(time * (uExpansionRate * 0.17) + 0.66 + onsetPulse * 0.1) * ringScale;
  float ring3Dist = abs(radius - ring3Pos);
  float ring3 = smoothstep(ringWidth * 0.8, ringWidth * 0.1, ring3Dist);

  // Ring layer 4
  float ring4Pos = fract(time * (uExpansionRate * 0.12) + 0.15) * ringScale;
  float ring4Dist = abs(radius - ring4Pos);
  float ring4 = smoothstep(ringWidth * 1.2, ringWidth * 0.2, ring4Dist);

  // Ring layer 5: beat-synced
  float ring5Pos = beatSync * 0.8 * ringScale;
  float ring5Dist = abs(radius - ring5Pos);
  float ring5 = smoothstep(ringWidth * 1.5, ringWidth * 0.1, ring5Dist) * beatSync;

  // Combine rings
  float ringCountNorm = clamp(uRingCount * 0.2, 0.0, 1.0);
  float rings = ring1 + ring2 * ringCountNorm
    + ring3 * (ringCountNorm * 0.8)
    + ring4 * (ringCountNorm * 0.6)
    + ring5;

  // --- Radial light rays (extend to full screen) ---
  float rayFreq = 8.0 + uChaos * 4.0;
  float ray1 = sin(angle * rayFreq + time * 0.5) * 0.5 + 0.5;
  float ray2 = sin(angle * (rayFreq * 1.7) - time * 0.3) * 0.5 + 0.5;
  float rays = ray1 * ray2;

  // Rays fade toward edges but extend across the whole screen
  float rayBrightness = rays * uRayIntensity
    * smoothstep(1.0, 0.05, radiusNorm)
    * (0.5 + energyBright * 0.5);

  // --- Core glow (scaled to full screen proportions) ---
  float coreGlow = smoothstep(0.4, 0.0, radiusNorm)
    * (2.0 + onsetPulse * 4.0);

  // --- Combine all layers ---
  float totalBrightness = rings + rayBrightness + coreGlow;

  vec3 col = supernovaColor(radiusNorm, uPalette);

  float brightness = totalBrightness * (uIntensity * 1.6) + energyBright * 0.4;
  vec3 litCol = vec3(
    col.x * brightness,
    col.y * brightness,
    col.z * brightness
  );

  // Core override (scaled proportionally)
  vec3 coreWhite = vec3(1.0, 0.97, 0.9);
  float coreMix = smoothstep(0.2, 0.0, radiusNorm) * (coreGlow * 0.5);
  vec3 withCore = mix(litCol, coreWhite, clamp(coreMix, 0.0, 1.0));

  // Beat flash
  float flashAmount = beatSync * 0.3 * totalBrightness;
  vec3 finalCol = withCore + vec3(flashAmount, flashAmount, flashAmount);

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashSM(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseSM(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashSM(i);
  float b = hashSM(i + vec2(1.0, 0.0));
  float c = hashSM(i + vec2(0.0, 1.0));
  float d = hashSM(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmSM(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 6; i++) {
    val += amp * noiseSM(p * freq);
    amp *= 0.5;
    freq *= 2.0;
  }
  return val;
}

// Terrain height with audio influence
float terrainHeight(vec2 p, float time, float bassVal, float midsVal, float trebleVal) {
  float base = fbmSM(p * 2.0 + time * 0.05);
  // Bass creates massive peaks
  float bassPeaks = fbmSM(p * 0.8 + vec2(time * 0.02, 0.0)) * bassVal * 1.5;
  // Mids create rolling hills
  float midHills = sin(p.x * 3.0 + time * 0.3) * cos(p.y * 2.5 + time * 0.2) * midsVal * 0.3;
  // Treble adds fine detail
  float trebleDetail = noiseSM(p * 8.0 + time * 0.5) * trebleVal * 0.15;
  return base + bassPeaks + midHills + trebleDetail;
}

// Contour line function
float contourLine(float height, float spacing, float lineWidth) {
  float contour = fract(height / spacing);
  float line = smoothstep(0.0, lineWidth, contour) * smoothstep(lineWidth * 2.0, lineWidth, contour);
  return line;
}

// Earth-to-neon color ramp
vec3 topoColor(float height, float paletteShift, float centroidVal) {
  // Low: deep earth, mid: forest, high: neon peaks
  vec3 deepEarth = vec3(0.1, 0.06, 0.03);
  vec3 forest = vec3(0.05, 0.2, 0.08);
  vec3 highland = vec3(0.6, 0.4, 0.1);
  vec3 neonPeak = vec3(0.1, 0.8, 1.0);
  vec3 hotSpot = vec3(1.0, 0.3, 0.5);

  float h = clamp(height, 0.0, 1.0);
  vec3 col = mix(deepEarth, forest, smoothstep(0.0, 0.25, h));
  col = mix(col, highland, smoothstep(0.25, 0.5, h));
  col = mix(col, neonPeak, smoothstep(0.5, 0.75, h));
  col = mix(col, hotSpot, smoothstep(0.75, 1.0, h));

  // Palette shift rotates the color
  float shift = paletteShift * 0.3 + centroidVal * 0.5;
  col = vec3(
    col.r * cos(shift) - col.g * sin(shift) * 0.3,
    col.g * cos(shift * 0.7) + col.b * sin(shift * 0.5),
    col.b * cos(shift * 1.3) + col.r * sin(shift * 0.8)
  );
  return max(col, 0.0);
}

// Isometric projection
vec2 isoProject(vec2 p) {
  return vec2(p.x - p.y, (p.x + p.y) * 0.5);
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float centroidVal = uSpectralCentroid * uSensitivity;

  // Isometric terrain coordinates
  vec2 isoP = isoProject(p);
  isoP += vec2(time * 0.1, 0.0); // Slowly pan across landscape

  // Compute terrain height
  float height = terrainHeight(isoP, time, bassVal, midsVal, trebleVal);

  // Shadow/lighting from pseudo-3D
  float heightDx = terrainHeight(isoP + vec2(0.01, 0.0), time, bassVal, midsVal, trebleVal);
  float heightDy = terrainHeight(isoP + vec2(0.0, 0.01), time, bassVal, midsVal, trebleVal);
  float slopeX = (heightDx - height) * 50.0;
  float slopeY = (heightDy - height) * 50.0;

  // Base terrain color
  vec3 col = topoColor(height, uPalette, centroidVal);

  // Lighting
  vec3 lightDir = normalize(vec3(0.5, 0.8, 0.6));
  vec3 normal = normalize(vec3(-slopeX, -slopeY, 1.0));
  float diffuse = max(dot(normal, lightDir), 0.0);
  col *= 0.4 + diffuse * 0.6;

  // Multiple contour line levels
  float contour1 = contourLine(height, 0.1, 0.02);
  float contour2 = contourLine(height, 0.05, 0.01);
  float contour3 = contourLine(height, 0.025, 0.005);

  // Contour line colors
  vec3 contourCol = topoColor(height + 0.1, uPalette + 0.2, centroidVal) * 2.0;
  col = mix(col, contourCol, contour1 * 0.8);
  col = mix(col, contourCol * 0.7, contour2 * 0.4);
  col += contourCol * contour3 * trebleVal * 0.5;

  // Bass peaks glow
  float peakGlow = smoothstep(0.6, 0.9, height) * bassVal * 0.5;
  col += vec3(0.3, 0.1, 0.5) * peakGlow;

  // Valley shimmer from treble
  float valleyShimmer = smoothstep(0.3, 0.1, height) * trebleVal * 0.4;
  col += vec3(0.0, 0.3, 0.4) * valleyShimmer * sin(isoP.x * 20.0 + time * 3.0);

  // Kick impact - ripple wave across terrain
  float kickRipple = sin(length(isoP) * 10.0 - time * 5.0) * kickVal * 0.15;
  col += topoColor(height + kickRipple, uPalette + 0.5, centroidVal) * abs(kickRipple);

  // Onset flash
  col += vec3(0.15, 0.1, 0.05) * onsetVal * 0.4;

  // Chaos adds terrain distortion
  float chaosWarp = sin(isoP.x * 5.0 + isoP.y * 3.0 + time) * uChaos * 0.15;
  col += col * chaosWarp;

  // Harmonicity glow
  col += col * uHarmonicity * uSensitivity * 0.15;

  // Beat pulse
  col *= 1.0 + uBeat * uSensitivity * 0.12;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashSH(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Neon grid on the ground plane
vec3 neonGrid(vec2 groundUV, float time, float bassVal, float midsVal) {
  vec3 col = vec3(0.0);
  // Main grid lines
  float gridX = abs(fract(groundUV.x) - 0.5);
  float gridY = abs(fract(groundUV.y * 0.5) - 0.5);
  float lineX = smoothstep(0.02, 0.0, gridX);
  float lineY = smoothstep(0.02, 0.0, gridY);
  // Neon cyan grid
  col += vec3(0.0, 0.8, 1.0) * lineX * 0.6;
  col += vec3(0.0, 0.6, 0.9) * lineY * 0.4;
  // Sub-grid
  float subGridX = abs(fract(groundUV.x * 4.0) - 0.5);
  float subLine = smoothstep(0.04, 0.0, subGridX) * 0.15;
  col += vec3(0.3, 0.0, 0.5) * subLine;
  // Bass pulse on grid
  col *= 1.0 + bassVal * 0.5;
  // Grid glow
  col += vec3(0.02, 0.01, 0.04);
  return col;
}

// Mountain silhouette
float mountainSilhouette(float x, float seed) {
  float h = 0.0;
  h += sin(x * 1.5 + seed) * 0.3;
  h += sin(x * 3.7 + seed * 2.3) * 0.15;
  h += sin(x * 7.1 + seed * 4.1) * 0.08;
  return h;
}

// Pyramid wireframe
float pyramid(vec2 p, vec2 center, float sz) {
  vec2 d = p - center;
  float base = abs(d.x) - sz * (1.0 - d.y / (sz * 2.0));
  float top = d.y - sz * 2.0;
  float bottom = -d.y;
  float shape = max(base, max(top, bottom));
  float wireframe = min(abs(d.x - sz * (1.0 - d.y / (sz * 2.0))),
                        abs(d.x + sz * (1.0 - d.y / (sz * 2.0))));
  wireframe = min(wireframe, abs(d.y));
  wireframe = min(wireframe, abs(d.y - sz * 2.0));
  return smoothstep(0.015, 0.0, wireframe) * step(shape, 0.01);
}

// Sun with horizontal bands
vec3 retroSun(vec2 p, float time, float energyVal) {
  float r = length(p);
  float sunR = 0.35 + energyVal * 0.05;
  float sunMask = smoothstep(sunR + 0.02, sunR - 0.02, r);
  // Horizontal scan lines through sun
  float bands = sin(p.y * 40.0 - time * 2.0) * 0.5 + 0.5;
  bands = step(0.3, bands);
  // Color gradient: top magenta, bottom orange
  vec3 sunTop = vec3(1.0, 0.2, 0.8);
  vec3 sunBottom = vec3(1.0, 0.5, 0.0);
  float grad = clamp((p.y + sunR) / (sunR * 2.0), 0.0, 1.0);
  vec3 sunCol = mix(sunBottom, sunTop, grad);
  sunCol *= sunMask * bands;
  // Sun glow
  float glow = exp(-r * 2.5) * 0.4;
  sunCol += mix(sunBottom, sunTop, 0.5) * glow;
  return sunCol;
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float kickVal = uKick * uSensitivity * 1.4;
  float onsetVal = uOnset * uSensitivity;

  vec3 col = vec3(0.0);

  // Horizon line
  float horizon = 0.0;

  // Sky gradient: dark purple top, deep magenta at horizon
  float skyGrad = clamp((p.y - horizon) / 1.5, 0.0, 1.0);
  vec3 skyTop = vec3(0.02, 0.0, 0.08);
  vec3 skyHorizon = vec3(0.15, 0.0, 0.2);
  vec3 sky = mix(skyHorizon, skyTop, skyGrad);

  // Stars in sky
  for (float i = 0.0; i < 30.0; i += 1.0) {
    vec2 starPos = vec2(hashSH(vec2(i, 0.0)) * 3.0 - 1.5, hashSH(vec2(i, 1.0)) * 1.2 + 0.2);
    float starBright = hashSH(vec2(i, 2.0));
    float twinkle = sin(time * 2.0 + i * 3.7) * 0.3 + 0.7;
    float star = exp(-length(p - starPos) * 80.0) * starBright * twinkle;
    sky += vec3(0.8, 0.8, 1.0) * star;
  }

  // Retrowave sun at horizon
  vec2 sunPos = vec2(0.0, 0.15);
  vec3 sun = retroSun(p - sunPos, time, uEnergy * uSensitivity);

  // Mountains/pyramids silhouette
  float mountainL = mountainSilhouette(p.x * 2.0 - 1.0, 0.0) * 0.3 + 0.05;
  float mountainR = mountainSilhouette(p.x * 2.0 + 1.0, 3.0) * 0.25 + 0.08;
  float mountains = max(step(p.y, mountainL), step(p.y, mountainR));

  // Wireframe pyramids
  float pyr1 = pyramid(p, vec2(-0.8, 0.0), 0.15);
  float pyr2 = pyramid(p, vec2(0.9, 0.0), 0.12);
  float pyr3 = pyramid(p, vec2(0.3, 0.0), 0.08);

  // Ground plane (below horizon)
  if (p.y < horizon) {
    // Perspective projection to ground
    float depth = -0.3 / (p.y - 0.001);
    float speed = 3.0 + bassVal * 5.0 + kickVal * 8.0; // Bass drives speed
    float groundX = p.x * depth;
    float groundZ = depth + time * speed;
    vec2 groundUV = vec2(groundX, groundZ);
    vec3 ground = neonGrid(groundUV, time, bassVal, midsVal);
    // Fog with distance
    float fogAmount = smoothstep(0.0, 15.0, depth);
    ground = mix(ground, vec3(0.05, 0.0, 0.1), fogAmount);
    col = ground;
  } else {
    col = sky;
    col += sun;
    // Mountain silhouette
    col = mix(col, vec3(0.02, 0.0, 0.05), mountains);
    // Pyramid wireframes glow
    col += vec3(1.0, 0.0, 0.6) * pyr1 * (1.0 + midsVal);
    col += vec3(0.0, 0.8, 1.0) * pyr2 * (1.0 + midsVal);
    col += vec3(0.8, 0.0, 1.0) * pyr3 * (1.0 + trebleVal);
  }

  // Speed lines (horizontal streaks)
  float speedLines = 0.0;
  for (float i = 0.0; i < 12.0; i += 1.0) {
    float ly = hashSH(vec2(i, 5.0)) * 2.0 - 1.0;
    float lx = fract(hashSH(vec2(i, 6.0)) + time * (2.0 + bassVal * 3.0));
    float lineLen = 0.1 + hashSH(vec2(i, 7.0)) * 0.15;
    float lineY = abs(p.y - ly);
    float lineX = smoothstep(0.0, lineLen, p.x - (lx * 4.0 - 2.0));
    lineX *= smoothstep(lineLen * 1.5, lineLen, p.x - (lx * 4.0 - 2.0));
    speedLines += smoothstep(0.01, 0.0, lineY) * lineX;
  }
  col += vec3(0.8, 0.3, 1.0) * speedLines * 0.3 * (1.0 + kickVal);

  // Onset turbo burst
  float burstR = length(p - vec2(0.0, -0.5));
  float burst = exp(-burstR * 3.0) * onsetVal * 0.4;
  col += vec3(0.0, 1.0, 1.0) * burst;

  // Chaos adds chromatic shift
  float chaosShift = sin(p.x * 10.0 + time * 3.0) * uChaos * 0.05;
  col.r += col.g * chaosShift;
  col.b -= col.r * chaosShift * 0.5;

  // Beat pulse
  col *= 1.0 + uBeat * uSensitivity * 0.15;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
