__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFluidViscosity;
uniform float uTemperatureRange;
uniform float uConvectionStrength;
uniform float uEmissive;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 6; i++) {
    v += a * noise(p);
    p = rot * p * 2.0;
    a *= 0.5;
  }
  return v;
}

vec3 lavaColor(float t) {
  vec3 c1 = vec3(0.1, 0.0, 0.0);
  vec3 c2 = vec3(0.8, 0.1, 0.0);
  vec3 c3 = vec3(1.0, 0.5, 0.0);
  vec3 c4 = vec3(1.0, 0.9, 0.3);
  if (t < 0.33) return mix(c1, c2, t / 0.33);
  if (t < 0.66) return mix(c2, c3, (t - 0.33) / 0.33);
  return mix(c3, c4, (t - 0.66) / 0.34);
}

vec3 iceColor(float t) {
  vec3 c1 = vec3(0.05, 0.08, 0.15);
  vec3 c2 = vec3(0.2, 0.4, 0.7);
  vec3 c3 = vec3(0.5, 0.75, 1.0);
  vec3 c4 = vec3(0.9, 0.95, 1.0);
  if (t < 0.33) return mix(c1, c2, t / 0.33);
  if (t < 0.66) return mix(c2, c3, (t - 0.33) / 0.33);
  return mix(c3, c4, (t - 0.66) / 0.34);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float temperature = clamp(uSpectralCentroid * uTemperatureRange * uSensitivity, 0.0, 1.0);
  temperature = mix(temperature, temperature + uWarmth * 0.3, uSensitivity);
  temperature = clamp(temperature, 0.0, 1.0);

  float viscosity = uFluidViscosity * (1.0 + (1.0 - temperature) * 0.5);
  vec2 flow = vec2(
    fbm(p * 3.0 + time * 0.3 / viscosity + bass() * uSensitivity),
    fbm(p * 3.0 + vec2(5.0) + time * 0.2 / viscosity)
  ) - 0.5;

  flow *= uConvectionStrength;
  flow.y += temperature * 0.3 * uConvectionStrength;

  vec2 warped = p + flow * 0.5;

  float fluid = fbm(warped * 2.0 + time * 0.1 + uChaos * flow);
  float detail = fbm(warped * 6.0 - time * 0.15);
  float pattern = mix(fluid, detail, 0.3 + uSpectralFlux * uSensitivity * 0.3);

  vec3 warmCol = lavaColor(pattern);
  vec3 coolCol = iceColor(pattern);
  vec3 col = mix(warmCol, coolCol, temperature);

  float paletteShift = uPalette * 0.3;
  col = mix(col, col * (0.7 + 0.3 * cos(vec3(0.0, 0.4, 0.8) + paletteShift * 6.28)), 0.2);

  float glow = pow(pattern, 2.0) * uEmissive;
  col += col * glow * mix(2.0, 0.5, temperature);

  col *= 1.0 + uKick * uSensitivity * 0.5;
  col *= 1.0 + uEnergy * uSensitivity * 0.3;

  float edge = fbm(warped * 12.0 + time * 0.05);
  float edgeLine = smoothstep(0.48, 0.52, edge);
  col += vec3(1.0) * edgeLine * 0.1 * uSpectralBandwidth * uSensitivity;

