uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCoilTightness;
uniform float uReleaseForce;
uniform float uSpringLayers;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1,0)), f.x),
             mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Compression phase: bpmSin drives spring compression
  float compressionPhase = uBpmSin * 0.5 + 0.5; // 0 to 1
  float compression = pow(compressionPhase, 1.0 + uCoilTightness * 3.0);

  // Release detection: kick triggers explosion
  float release = kickVal * uReleaseForce * 3.0;
  float expansion = release * exp(-fract(time) * 4.0);

  // Spring radius modulation
  float r = length(p);
  float a = atan(p.y, p.x);

  // Multiple coil layers
  int layers = int(2.0 + uSpringLayers * 4.0);
  vec3 col = vec3(0.0);

  for (int i = 0; i < 6; i++) {
    if (i >= layers) break;
    float layerOffset = float(i) * 1.2;
    float layerPhase = float(i) * 0.4;

    // Spiral equation with compression
    float spiralFreq = 6.0 + uCoilTightness * 12.0;
    float spiralR = a * spiralFreq / 6.2832 + time * 2.0 + layerOffset;
    spiralR *= (1.0 - compression * 0.6 + expansion * 2.0);

    // Spring wire distance — spread across full screen
    float springWire = sin(spiralR * 3.14159) * (0.3 + bassVal * 0.2);
    float wireDist = abs(r - fract(spiralR) * (1.6 + expansion * 1.5));
    float wire = smoothstep(0.12 + trebleVal * 0.05, 0.0, wireDist);
    wire *= smoothstep(0.0, 0.1, abs(springWire));

    // Coil ring glow — larger radii to fill screen
    float ringDist = abs(r - (0.15 + float(i) * 0.22) * (1.0 - compression * 0.5 + expansion));
    float ring = exp(-ringDist * ringDist * 40.0);

    // Color: tension red → release cyan
    float tensionAmount = compression * (1.0 - release);
    vec3 tensionColor = vec3(0.9, 0.1, 0.05) * (1.0 + float(i) * 0.1);
    vec3 releaseColor = vec3(0.05, 0.8, 0.9);
    vec3 layerColor = mix(releaseColor, tensionColor, tensionAmount);

    // Palette shift
    layerColor = 0.5 + 0.5 * cos(6.2832 * (layerColor + uPalette * 0.3 + layerPhase));

    col += (wire * 0.6 + ring * 0.4) * layerColor / float(layers) * 3.0;
  }

  // Radial energy waves on release — wider reach
  float wave = sin(r * 12.0 - time * 15.0 - release * 10.0) * 0.5 + 0.5;
  wave *= exp(-r * 0.8) * release;
  col += wave * vec3(0.3, 0.8, 1.0);

  // Compression vignette — much softer to preserve edges
  float vignette = 1.0 - compression * 0.2 * r;
  col *= max(vignette, 0.5);

  // Chaos: add noise displacement
  col += noise(p * 10.0 + time) * uChaos * 0.15 * vec3(0.5, 0.3, 0.8);

  // Energy brightness
  col *= 1.0 + energyVal * 0.3;

  // Mids color temperature shift
  col.r += midsVal * 0.1;
  col.b += (1.0 - midsVal) * 0.05;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
