__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFoldAngle;
uniform float uDimensionCount;
uniform float uEdgeGlow;
uniform float uRotationSpeed;

// 2D hash for noise
float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

// Smooth 2D value noise
float noise2(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - f * 2.0);

  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// 3-octave FBM
float fbm3(vec2 p, float t) {
  float n1 = noise2(p + vec2(t * 0.13, t * 0.17));
  float n2 = noise2(p * 2.0 + vec2(t * 0.09, -t * 0.11));
  float n3 = noise2(p * 4.0 + vec2(-t * 0.07, t * 0.05));
  return n1 * 0.5 + n2 * 0.3 + n3 * 0.2;
}

// Plasma gradient
vec3 plasmaGradient(float t, float paletteOffset, float colorShift) {
  float shifted = clamp(t + paletteOffset * 0.05 + colorShift * 0.1, 0.0, 1.0);

  vec3 outerGlow = vec3(0.6, 0.1, 0.9);
  vec3 midBeam = vec3(0.1, 0.7, 1.0);
  vec3 hotCore = vec3(1.0, 0.95, 0.85);

  float lowMix = smoothstep(0.0, 0.4, shifted);
  float highMix = smoothstep(0.4, 1.0, shifted);

  vec3 midColor = mix(outerGlow, midBeam, lowMix);
  return mix(midColor, hotCore, highMix);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 1.5);

  // Audio-reactive modulators
  float foldTrigger = uKick * uSensitivity;
  float axisShift = bass() * uSensitivity;
  float glowColor = uSpectralCentroid * uSensitivity;
  float vertexSparkle = treble() * uSensitivity;

  // Organic breathing — deeper
  float breathe = sin(time * 0.9) * 0.2 + sin(time * 1.4) * 0.15 + 1.0;

  float x = p.x;
  float y = p.y;

  // 4D rotation angles
  float wobble1 = sin(time * 0.3) * 0.2 + sin(time * 0.47) * 0.1;
  float wobble2 = cos(time * 0.23) * 0.15 + sin(time * 0.53) * 0.08;
  float angle1 = time * (uRotationSpeed * 0.5) + axisShift * 2.0 + wobble1;
  float angle2 = time * (uRotationSpeed * 0.35) + uFoldAngle * 3.14 + wobble2;
  float angle3 = time * (uRotationSpeed * 0.25) + foldTrigger * 3.14;

  // Fold transformation: successive 2D rotations
  // Rotation 1: XY plane
  float r1x = x * cos(angle1) - y * sin(angle1);
  float r1y = x * sin(angle1) + y * cos(angle1);

  // Rotation 2: XZ-like plane
  float foldDepth = sin(angle2) * (uFoldAngle + foldTrigger * 0.5);
  float r2x = r1x * cos(angle2) - foldDepth * sin(angle2);
  float r2y = r1y;

  // Rotation 3: YW-like plane
