  float edgeNoise = fbm3(noiseCoord, time * 0.5);

  // Edge layer 1: primary grid
  float gridScale1 = uDimensionCount * 1.5 + 1.0;
  float gridX1 = fract(r3x * gridScale1 + 0.5);
  float gridY1 = fract(r3y * gridScale1 + 0.5);
  float edgeDistX1 = abs(gridX1 - 0.5);
  float edgeDistY1 = abs(gridY1 - 0.5);

  float baseEdgeWidth = 0.03 * (uEdgeGlow + 0.3);
  float wobbleWidth = baseEdgeWidth * (1.0 + (edgeNoise - 0.5) * 0.6) * breathe;

  float glowWidth = wobbleWidth * 3.5;

  float edge1XSharp = smoothstep(wobbleWidth, 0.0, edgeDistX1);
  float edge1YSharp = smoothstep(wobbleWidth, 0.0, edgeDistY1);
  float edges1Sharp = clamp(edge1XSharp + edge1YSharp, 0.0, 1.0);

  float edge1XGlow = exp(-edgeDistX1 * (1.0 / glowWidth * 4.0));
  float edge1YGlow = exp(-edgeDistY1 * (1.0 / glowWidth * 4.0));
  float edges1Glow = clamp(edge1XGlow + edge1YGlow, 0.0, 1.0);

  // Edge layer 2: secondary grid
  float gridScale2 = uDimensionCount * 2.0 + 0.5;
  float angle4 = time * (uRotationSpeed * 0.15) + uFoldAngle * 1.57;
  float s2x = r3x * cos(angle4) - r3y * sin(angle4);
  float s2y = r3x * sin(angle4) + r3y * cos(angle4);
  float gridX2 = fract(s2x * gridScale2 + 0.5);
  float gridY2 = fract(s2y * gridScale2 + 0.5);
  float edgeDistX2 = abs(gridX2 - 0.5);
  float edgeDistY2 = abs(gridY2 - 0.5);

  float wobbleWidth2 = wobbleWidth * 0.7;
  float glowWidth2 = wobbleWidth2 * 3.0;

  float edge2XSharp = smoothstep(wobbleWidth2, 0.0, edgeDistX2);
  float edge2YSharp = smoothstep(wobbleWidth2, 0.0, edgeDistY2);
  float edges2Sharp = clamp(edge2XSharp + edge2YSharp, 0.0, 1.0) * 0.6;

  float edge2XGlow = exp(-edgeDistX2 * (1.0 / glowWidth2 * 4.0));
  float edge2YGlow = exp(-edgeDistY2 * (1.0 / glowWidth2 * 4.0));
  float edges2Glow = clamp(edge2XGlow + edge2YGlow, 0.0, 1.0) * 0.4;

  // Edge layer 3: diagonal connections
  float diagAngle = time * (uRotationSpeed * 0.4) + uChaos * 3.14;
  float dx = (r3x + r3y) * cos(diagAngle) * uDimensionCount;
  float dy = (r3x - r3y) * sin(diagAngle) * uDimensionCount;
  float diagGrid = fract((dx + dy) * 1.5 + 0.5);
  float diagDist = abs(diagGrid - 0.5);
  float diagEdgeSharp = smoothstep(wobbleWidth * 0.5, 0.0, diagDist);
  float diagEdgeGlow = exp(-diagDist * (1.0 / (glowWidth * 0.5) * 4.0));
  float edges3Sharp = diagEdgeSharp * (uChaos + 0.2) * 0.4;
  float edges3Glow = diagEdgeGlow * (uChaos + 0.2) * 0.3;

  // Combine edges
  float allEdgesSharp = clamp(edges1Sharp + edges2Sharp + edges3Sharp, 0.0, 1.0);
  float allEdgesGlow = clamp(edges1Glow + edges2Glow + edges3Glow, 0.0, 1.0);

  float allEdges = clamp(allEdgesSharp + allEdgesGlow * 0.4, 0.0, 1.0);

  // Vertex sparkle
  float vertDist = edgeDistX1 + edgeDistY1;
  float vertexPoint = smoothstep(0.08, 0.0, vertDist);
  float sparkleVal = vertexPoint * (vertexSparkle * 0.8)
    * (sin(time * 8.0 + r3x * 20.0) * 0.5 + 0.5);

  // Plasma color
  vec3 coreColor = plasmaGradient(allEdgesSharp, uPalette, glowColor);
  vec3 glowColorVec = plasmaGradient(allEdgesGlow * 0.4, uPalette, glowColor);

  vec3 blendedColor = mix(glowColorVec, coreColor, allEdgesSharp);

  float brightness = uIntensity * 1.3 * (uEdgeGlow + 0.5);
  vec3 litCol = vec3(
    blendedColor.x * brightness,
    blendedColor.y * brightness,
    blendedColor.z * brightness
  );

  // Add vertex sparkle
  vec3 sparkleCol = litCol + vec3(sparkleVal, sparkleVal, sparkleVal * 0.8);

  // Kick fold flash
  float foldFlash = foldTrigger * 0.15 * allEdges;
  vec3 flashCol = vec3(
    sparkleCol.x + foldFlash,
    sparkleCol.y + foldFlash,
    sparkleCol.z + foldFlash * 1.5
  );

  // Chromatic aberration — stronger
  float aberrationAmount = 0.005 * (uEdgeGlow + 0.3) * (sin(time * 1.5) * 0.4 + 1.0);
  vec2 uvBase = vUv - 0.5;
  vec2 uvDir = uvBase * (1.0 / max(0.001, pow(dot(uvBase, uvBase), 0.5)));

  float rShift = flashCol.x * (1.0 + aberrationAmount * (uvDir.x + uvDir.y) * allEdgesGlow);
  float gShift = flashCol.y;
  float bShift = flashCol.z * (1.0 + (-aberrationAmount) * (uvDir.x - uvDir.y) * allEdgesGlow);

  // Alpha: transparent where no beams
  float edgeAlpha = clamp(allEdgesSharp + allEdgesGlow * 0.5, 0.0, 1.0);
  float sparkleAlpha = clamp(sparkleVal * 2.0, 0.0, 1.0);
  float finalAlpha = clamp(edgeAlpha + sparkleAlpha + foldFlash, 0.0, 1.0);

  float alpha = pow(finalAlpha, 0.8) * (uIntensity + 0.3);

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(rShift, gShift, bShift)); rShift = _pc.r; gShift = _pc.g; bShift = _pc.b; }
  gl_FragColor = vec4(
    clamp(rShift, 0.0, 1.0),
    clamp(gShift, 0.0, 1.0),
    clamp(bShift, 0.0, 1.0),
    clamp(alpha, 0.0, 1.0)
  );
}

