// 4D rotation in XW plane
vec4 rotXW(vec4 p, float a) {
  float c = cos(a), s = sin(a);
  return vec4(p.x * c - p.w * s, p.y, p.z, p.x * s + p.w * c);
}
// 4D rotation in YZ plane
vec4 rotYZ(vec4 p, float a) {
  float c = cos(a), s = sin(a);
  return vec4(p.x, p.y * c - p.z * s, p.y * s + p.z * c, p.w);
}
// 4D rotation in XY plane
vec4 rotXY(vec4 p, float a) {
  float c = cos(a), s = sin(a);
  return vec4(p.x * c - p.y * s, p.x * s + p.y * c, p.z, p.w);
}
// 4D rotation in ZW plane
vec4 rotZW(vec4 p, float a) {
  float c = cos(a), s = sin(a);
  return vec4(p.x, p.y, p.z * c - p.w * s, p.z * s + p.w * c);
}

// Project 4D to 2D via stereographic-like projection
vec2 project4Dto2D(vec4 v, float depth) {
  float w = 2.0 + depth * 2.0;
  float scale = w / (w - v.w);
  float scale2 = (w - 0.5) / (w - 0.5 - v.z);
  return vec2(v.x * scale * scale2, v.y * scale * scale2);
}

// Distance from point to line segment
float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;

  p *= 1.0 + uZoom;

  // Tesseract: 16 vertices of a 4D hypercube
  vec3 col = vec3(0.0);
  float edgeAccum = 0.0;
  float nodeAccum = 0.0;

  // Rotation angles driven by audio — faster
  float aXW = time * 0.6 * uRotationW + uBpmSin * 0.5;
  float aYZ = time * 0.5 + uSpectralCentroid * 3.0;
  float aXY = time * 0.35 + uKick * 2.0;
  float aZW = time * 0.5 + midsVal * 0.8;

  // Generate 16 vertices and project them
  vec2 projected[16];
  for (int i = 0; i < 16; i++) {
    vec4 v = vec4(
      float((i >> 0) & 1) * 2.0 - 1.0,
      float((i >> 1) & 1) * 2.0 - 1.0,
      float((i >> 2) & 1) * 2.0 - 1.0,
      float((i >> 3) & 1) * 2.0 - 1.0
    ) * 0.5;

    v = rotXW(v, aXW);
    v = rotYZ(v, aYZ);
    v = rotXY(v, aXY);
    v = rotZW(v, aZW);

    projected[i] = project4Dto2D(v, uProjectionDepth);

    // Node glow at vertices
    float nd = length(p - projected[i]);
    nodeAccum += exp(-nd * nd * 200.0) * (0.6 + uBeat * uSensitivity * 1.2);
  }

  // Draw edges: two vertices share an edge if they differ in exactly 1 bit
  for (int i = 0; i < 16; i++) {
    for (int j = i + 1; j < 16; j++) {
      int diff = i ^ j;
      // Check if exactly one bit differs (power of 2)
      if (diff == 1 || diff == 2 || diff == 4 || diff == 8) {
        float d = segDist(p, projected[i], projected[j]);
        float thick = 0.006 + bassVal * 0.003;
        float edge = smoothstep(thick, thick * 0.3, d);
        float edgeBand = float(diff == 1) * uSpectrum0 + float(diff == 2) * uSpectrum2
                       + float(diff == 4) * uSpectrum4 + float(diff == 8) * uSpectrum6;
        edgeAccum += edge * (0.4 + edgeBand * uSensitivity * 0.8);
      }
    }
  }

  // Neon green/cyan/magenta wireframe — more color cycling
  vec3 edgeColor = mix(
    mix(vec3(0.1, 1.0, 0.4), vec3(1.0, 0.2, 0.8), 0.5 + 0.5 * sin(time * 0.5)),
    vec3(0.0, 0.8, 1.0),
    0.5 + 0.5 * sin(time * 0.4 + uPalette * 3.0)
  );

  col += edgeColor * edgeAccum * uEdgeGlow;
  col += vec3(0.8, 1.0, 0.9) * nodeAccum * 1.5;

  // Kick flash
  col += vec3(0.2, 0.5, 0.3) * uKick * uSensitivity * 0.3;

  // Subtle grid background
  vec2 grid = abs(fract(p * 5.0) - 0.5);
  float gridLine = smoothstep(0.48, 0.5, max(grid.x, grid.y));
  col += vec3(0.02, 0.05, 0.03) * gridLine;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFilmThickness;
uniform float uFlowSpeed;
uniform float uGrainSize;

float hash21(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * valueNoise(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

// Thin-film interference: convert optical path difference to RGB
// Based on the interference equation: I = cos^2(pi * d / lambda)
vec3 thinFilmColor(float thickness) {
  // Wavelengths for R, G, B in normalized units
  float lambdaR = 0.65;
  float lambdaG = 0.53;
  float lambdaB = 0.45;

  float pi = 3.14159265;

  // Interference intensity per channel
  float iR = cos(pi * thickness / lambdaR);
  iR = iR * iR;
  float iG = cos(pi * thickness / lambdaG);
  iG = iG * iG;
  float iB = cos(pi * thickness / lambdaB);
  iB = iB * iB;

  return vec3(iR, iG, iB);
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  float flowT = time * uFlowSpeed;
  float grainScale = 2.0 + uGrainSize * 6.0;

  // Flowing thickness field via domain-warped FBM
  vec2 q = vec2(
    fbm(p * grainScale + vec2(flowT * 0.3, flowT * 0.2)),
    fbm(p * grainScale + vec2(flowT * 0.2 + 5.2, flowT * 0.3 + 1.3))
  );

  vec2 r2 = vec2(
    fbm(p * grainScale + q * 4.0 + vec2(1.7, 9.2) + flowT * 0.15),
    fbm(p * grainScale + q * 4.0 + vec2(8.3, 2.8) + flowT * 0.1)
  );

  float thickness = fbm(p * grainScale + r2 * 2.0);

  // Base thickness offset
  float baseThick = uFilmThickness * 2.0 + 0.5;
  thickness = thickness * 1.5 + baseThick;

  // Bass shifts entire thickness (shifts colors)
  thickness += bassVal * 0.4;

  // Beat creates radial ripple in thickness
  float dist = length(p);
  float beatRipple = sin(dist * 15.0 - time * 6.0) * beatPulse * 0.15;
  thickness += beatRipple;

  // Treble adds fine grain
  float fineGrain = valueNoise(p * 30.0 + time * 2.0) * trebleVal * 0.2;
  thickness += fineGrain;

  // Onset: burst wave
  float onsetWave = sin(dist * 10.0 - time * 8.0) * onsetVal * 0.3;
  thickness += onsetWave;

  // Chaos adds randomness
  thickness += (valueNoise(p * 10.0 + time * 3.0) - 0.5) * uChaos * 0.3;

  // Palette rotation shifts the base thickness
  thickness += uPalette * 0.2;

  // Convert thickness to interference color
  vec3 col = thinFilmColor(thickness);

  // Add specular-like highlight for soap bubble look
  float specular = pow(max(0.0, 1.0 - dist * 0.5), 3.0) * 0.3;
  col += vec3(specular);

  // Metallic sheen: darken at edges
  float fresnel = pow(1.0 - abs(dot(normalize(vec3(p, 0.5)), vec3(0.0, 0.0, 1.0))), 2.0);
  col *= 0.7 + fresnel * 0.5;

  // Energy boost
  col *= 1.0 + energyVal * 0.3;

  // Onset flash
  col += vec3(onsetVal * 0.15);

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFoldCount;
uniform float uJuliaCx;
uniform float uJuliaCy;
uniform float uIterations;
uniform float uEyeSize;
uniform float uBlinkRate;
uniform float uStareChance;
uniform float uIrisHueShift;

// HSV to RGB
vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

void main() {
  // Center UV to [-0.5, 0.5] and apply zoom
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);
  float rawTime = uTime;

  // --- Kaleidoscopic folding ---
  float radius = pow(p.x * p.x + p.y * p.y, 0.5);
  float angle = atan(p.y, p.x);

  float beatFoldShift = uOnset * uSensitivity * 2.0;
  float effectiveFolds = uFoldCount + beatFoldShift;
  float sectorAngle = 3.14159265 * 2.0 / effectiveFolds;

  float foldedAngle = abs(fract(angle / sectorAngle) * 2.0 - 1.0) * (sectorAngle * 0.5);
  float rotatedAngle = foldedAngle + (time * 0.1 + uChaos * sin(time * 0.3));

  float zx = cos(rotatedAngle) * radius;
  float zy = sin(rotatedAngle) * radius;

  // --- Julia set iteration ---
  float bassInfluence = bass() * uSensitivity * 0.15;
  float trebleInfluence = treble() * uSensitivity * 0.1;
  float cx = uJuliaCx + bassInfluence + sin(time * 0.2) * (uChaos * 0.05);
  float cy = uJuliaCy + trebleInfluence + cos(time * 0.15) * (uChaos * 0.05);

  float escape = 0.0;

  // Iteration 1
  float newZx = zx * zx - zy * zy + cx;
  float newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  float magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 2
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 3
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 4
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 5
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 6
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 7
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Iteration 8
  newZx = zx * zx - zy * zy + cx;
  newZy = zx * zy * 2.0 + cy;
  zx = newZx; zy = newZy;
  magSq = zx * zx + zy * zy;
  escape += smoothstep(4.0, 0.0, magSq);

  // Normalize escape
  float normalizedEscape = escape / uIterations;

  // --- HSV Color Palette ---
  float hue = normalizedEscape * 0.6
    + uPalette * 0.1
    + time * 0.03
    + uEnergy * uSensitivity * 0.08;

  float sat = 0.6
    + normalizedEscape * 0.3
    + uEnergy * uSensitivity * 0.2;

  float val = normalizedEscape * (uIntensity * 1.5)
    + uOnset * uSensitivity * 0.25;

  vec3 col = hsvToRgb(fract(hue), clamp(sat, 0.0, 1.0), clamp(val, 0.0, 1.0));

  float beatPulse = uBeat * uSensitivity * 0.15;
  vec3 fractalCol = col + vec3(beatPulse, beatPulse, beatPulse);

  // =================================================================
  // LIVING EYE -- composited at screen center on top of the fractal
  // =================================================================

  // Eye coordinates: centered UV, unaffected by fractal zoom
  float eyeUV_x = vUv.x - 0.5;
  float eyeUV_y = vUv.y - 0.5;

  // Audio helpers
  float bassVal = bass();
  float trebleVal = treble();

  // --- EYE GAZE: Lissajous scanning pattern ---
  float gazeFreqX = 0.37;
  float gazeFreqY = 0.53;

  float bassErratic = bassVal * uSensitivity * 0.4;
  float erraticX = sin(rawTime * 7.3) * bassErratic * 0.15;
  float erraticY = cos(rawTime * 5.7) * bassErratic * 0.15;

  float gazeBaseX = sin(rawTime * gazeFreqX * 6.2832) * 0.35;
  float gazeBaseY = cos(rawTime * gazeFreqY * 6.2832) * 0.25;

  // --- STARE ---
  float stareCycle = rawTime * 0.13 + uChaos * sin(rawTime * 0.07);
  float stareWave = sin(stareCycle * 6.2832);
  float stareThreshold = 1.0 - uStareChance * 0.6;
  float stareRaw = smoothstep(stareThreshold, stareThreshold + 0.05, stareWave);
  float stareFactor = stareRaw * stareRaw * (3.0 - stareRaw * 2.0);

  float gazeX = mix(gazeBaseX + erraticX, 0.0, stareFactor);
  float gazeY = mix(gazeBaseY + erraticY, 0.0, stareFactor);

  // --- BLINK CYCLE: open ~90% of the time with brief blinks ---
  // Use a sharp periodic pulse for blink: eye is open most of the time
  float blinkCycle = rawTime * uBlinkRate * 0.4; // slow cycle
  float blinkPhase = fract(blinkCycle);
  // Blink is a narrow spike: closed only when blinkPhase is in [0.0, 0.1]
  float blinkPulse = smoothstep(0.0, 0.03, blinkPhase) * smoothstep(0.10, 0.07, blinkPhase);
  // Add a second occasional blink (double-blink) offset by half cycle
  float blinkPhase2 = fract(blinkCycle + 0.5);
  float blinkPulse2 = smoothstep(0.0, 0.03, blinkPhase2) * smoothstep(0.08, 0.05, blinkPhase2) * 0.5;
  // Onset can force a quick blink
  float onsetBlink = uOnset * uSensitivity * 0.8;
  // blinkAmount = 1 means fully closed, 0 means fully open
  float blinkAmount = clamp(max(max(blinkPulse, blinkPulse2), onsetBlink), 0.0, 1.0);

  // --- SCLERA ---
  float scleraRadX = uEyeSize * 1.0;
  float scleraRadY = uEyeSize * 0.55;

  float scleraWobble = sin(rawTime * 1.2) * 0.008 + cos(rawTime * 0.9) * 0.005;

  float scleraNormX = eyeUV_x / (scleraRadX + scleraWobble);
  float scleraNormY = eyeUV_y / (scleraRadY + scleraWobble * 0.5);
  float scleraDist = scleraNormX * scleraNormX + scleraNormY * scleraNormY;

  float scleraMask = smoothstep(1.05, 0.9, scleraDist);

  float veinTint = smoothstep(0.3, 0.95, scleraDist);
  float scleraR = 0.97 - veinTint * 0.12;
  float scleraG = 0.95 - veinTint * 0.18;
  float scleraB = 0.93 - veinTint * 0.08;

  float veinPattern1 = sin(eyeUV_x * 80.0 + eyeUV_y * 40.0) * 0.5 + 0.5;
  float veinPattern2 = sin(eyeUV_x * 30.0 - eyeUV_y * 70.0 + rawTime * 0.3) * 0.5 + 0.5;
  float veinIntensity = veinPattern1 * veinPattern2 * veinTint * 0.15;
  float scleraFinalR = scleraR + veinIntensity * 0.4;
  float scleraFinalG = scleraG - veinIntensity * 0.15;
  float scleraFinalB = scleraB - veinIntensity * 0.1;

  // --- IRIS (pulsing with audio, shifting hues) ---
  float irisRange = uEyeSize * 0.3;
  float irisCenterX = gazeX * irisRange;
  float irisCenterY = gazeY * irisRange;

  // Iris radius pulses with bass — contracts when quiet, expands with bass
  float irisPulse = bassVal * uSensitivity * 0.15 + uEnergy * uSensitivity * 0.08;
  float irisRadius = uEyeSize * (0.36 + irisPulse * 0.06);
  float irisDx = eyeUV_x - irisCenterX;
  float irisDy = eyeUV_y - irisCenterY;
  float irisDist = irisDx * irisDx + irisDy * irisDy;
  float irisRadSq = irisRadius * irisRadius;

  float irisMask = smoothstep(irisRadSq * 1.1, irisRadSq * 0.7, irisDist);

  // Iris hue shifts faster with audio energy
  float irisHueBase = rawTime * (0.05 + uEnergy * uSensitivity * 0.03) + uPalette * 0.15 + uIrisHueShift;
  float irisRadialT = clamp(irisDist / (irisRadSq + 0.0001), 0.0, 1.0);

  // Rotating iris pattern — the iris itself slowly rotates
  float irisRotation = rawTime * 0.15 + bassVal * uSensitivity * 0.5;
  float irisHue = fract(irisHueBase + irisRadialT * 0.15 + sin(rawTime * 0.3) * 0.05);
  float irisColR = cos(irisHue * 6.2832) * 0.4 + 0.5;
  float irisColG = cos(irisHue * 6.2832 - 2.094) * 0.35 + 0.4;
  float irisColB = cos(irisHue * 6.2832 - 4.189) * 0.45 + 0.5;

  float irisAngle = atan(irisDy, irisDx) + irisRotation;
  float fiberPattern = sin(irisAngle * 24.0 + irisRadialT * 8.0) * 0.5 + 0.5;
  float fiberPattern2 = sin(irisAngle * 37.0 - rawTime * 0.2 + trebleVal * uSensitivity * 2.0) * 0.5 + 0.5;
  float fiberMix = fiberPattern * fiberPattern2 * 0.25;

  // Limbal ring pulses with beat
  float limbalDarken = smoothstep(0.5, 1.0, irisRadialT) * (0.4 - uBeat * uSensitivity * 0.1);

  float irisFinalR = clamp(irisColR + fiberMix * 0.15 - limbalDarken, 0.0, 1.0);
  float irisFinalG = clamp(irisColG + fiberMix * 0.1 - limbalDarken, 0.0, 1.0);
  float irisFinalB = clamp(irisColB + fiberMix * 0.2 - limbalDarken, 0.0, 1.0);

  // --- MULTIPLE PUPILS (3 orbiting pupils that expand/contract) ---
  float bassDilation = bassVal * uSensitivity * 0.5;
  float quietConstrict = 1.0 - smoothstep(0.0, 0.15, bassVal + mids() * 0.5) * 0.4;
  float pupilBaseRadius = uEyeSize * 0.11;
  float pupilRadius = pupilBaseRadius * (1.0 + bassDilation) * quietConstrict;
  float pupilRadSq = pupilRadius * pupilRadius;

  // Orbit parameters — pupils rotate around the iris center
  float orbitSpeed = rawTime * 0.8;
  float orbitRadius = uEyeSize * 0.06 + bassVal * uSensitivity * 0.03;
  // Figure-8 (lemniscate) path for main pupil
  float fig8X = sin(orbitSpeed) * orbitRadius;
  float fig8Y = sin(orbitSpeed * 2.0) * orbitRadius * 0.5;

  // Pupil 1: main — traces figure-8 orbit around iris center
  float p1CX = irisCenterX + fig8X;
  float p1CY = irisCenterY + fig8Y;
  float p1Dx = eyeUV_x - p1CX;
  float p1Dy = eyeUV_y - p1CY;
  float p1Dist = p1Dx * p1Dx + p1Dy * p1Dy;
  float pupilMask1 = smoothstep(pupilRadSq * 1.15, pupilRadSq * 0.6, p1Dist);

  // Pupil 2: orbits 120 degrees offset, smaller, circular path
  float orbit2Angle = orbitSpeed * 1.2 + 2.094; // 120 degrees offset
  float orbit2Radius = uEyeSize * 0.07 + trebleVal * uSensitivity * 0.02;
  float p2OffX = irisCenterX + cos(orbit2Angle) * orbit2Radius;
  float p2OffY = irisCenterY + sin(orbit2Angle) * orbit2Radius;
  float p2Dx = eyeUV_x - p2OffX;
  float p2Dy = eyeUV_y - p2OffY;
  float p2Dist = p2Dx * p2Dx + p2Dy * p2Dy;
  float p2RadSq = pupilRadSq * 0.7;
  float pupilMask2 = smoothstep(p2RadSq * 1.15, p2RadSq * 0.6, p2Dist);

  // Pupil 3: orbits 240 degrees offset, smallest
  float orbit3Angle = orbitSpeed * 0.9 + 4.189; // 240 degrees offset
  float orbit3Radius = uEyeSize * 0.05 + mids() * uSensitivity * 0.02;
  float p3OffX = irisCenterX + cos(orbit3Angle) * orbit3Radius;
  float p3OffY = irisCenterY + sin(orbit3Angle) * orbit3Radius;
  float p3Dx = eyeUV_x - p3OffX;
  float p3Dy = eyeUV_y - p3OffY;
  float p3Dist = p3Dx * p3Dx + p3Dy * p3Dy;
  float p3RadSq = pupilRadSq * 0.6;
  float pupilMask3 = smoothstep(p3RadSq * 1.15, p3RadSq * 0.6, p3Dist);

  // Combined pupil mask
  float pupilMask = clamp(pupilMask1 + pupilMask2 * 0.9 + pupilMask3 * 0.85, 0.0, 1.0);

  float pupilR = 0.02;
  float pupilG = 0.01;
  float pupilB = 0.04;

  // Specular highlights — track orbiting pupils
  float specOffX = p1CX + uEyeSize * 0.05;
  float specOffY = p1CY + uEyeSize * 0.06;
  float specDx = eyeUV_x - specOffX;
  float specDy = eyeUV_y - specOffY;
  float specDist = specDx * specDx + specDy * specDy;
  float specRadius = uEyeSize * 0.04;
  float specMask = smoothstep(specRadius * specRadius, 0.0, specDist) * 0.7;

  float spec2OffX = p2OffX + uEyeSize * 0.03;
  float spec2OffY = p2OffY + uEyeSize * 0.04;
  float spec2Dx = eyeUV_x - spec2OffX;
  float spec2Dy = eyeUV_y - spec2OffY;
  float spec2Dist = spec2Dx * spec2Dx + spec2Dy * spec2Dy;
  float spec2Radius = uEyeSize * 0.02;
  float spec2Mask = smoothstep(spec2Radius * spec2Radius, 0.0, spec2Dist) * 0.4;

  float spec3OffX = p3OffX + uEyeSize * 0.03;
  float spec3OffY = p3OffY + uEyeSize * 0.04;
  float spec3Dx = eyeUV_x - spec3OffX;
  float spec3Dy = eyeUV_y - spec3OffY;
  float spec3Dist = spec3Dx * spec3Dx + spec3Dy * spec3Dy;
  float spec3Radius = uEyeSize * 0.015;
  float spec3Mask = smoothstep(spec3Radius * spec3Radius, 0.0, spec3Dist) * 0.3;

  // --- EYELIDS (top lid on top, bottom lid on bottom) ---
  // Top lid descends from above: when blinkAmount=1, topLidEdge=0 (fully closed)
  // when blinkAmount=0, topLidEdge=scleraRadY (fully open, lid retracted up)
  float topLidEdge = scleraRadY * (1.0 - blinkAmount);
  // Top lid covers pixels where eyeUV_y > topLidEdge (above the edge)
  float topLidMask = smoothstep(
    topLidEdge - uEyeSize * 0.01,
    topLidEdge + uEyeSize * 0.02,
    eyeUV_y
  );

  // Bottom lid rises from below: when blinkAmount=1, bottomLidEdge=0 (closed)
  // when blinkAmount=0, bottomLidEdge=-scleraRadY (fully open, retracted down)
  float bottomLidEdge = -(scleraRadY * (1.0 - blinkAmount));
  // Bottom lid covers pixels where eyeUV_y < bottomLidEdge (below the edge)
  float bottomLidMask = smoothstep(
    bottomLidEdge + uEyeSize * 0.01,
    bottomLidEdge - uEyeSize * 0.02,
    eyeUV_y
  );

  float lidCover = max(topLidMask, bottomLidMask);

  float lidSkinR = 0.45 + sin(rawTime * 0.1) * 0.03;
  float lidSkinG = 0.28 + cos(rawTime * 0.13) * 0.02;
  float lidSkinB = 0.22;

  float creaseTop = smoothstep(
    topLidEdge - uEyeSize * 0.01,
    topLidEdge + uEyeSize * 0.04,
    eyeUV_y
  ) * 0.3;
  float creaseBottom = smoothstep(
    bottomLidEdge + uEyeSize * 0.01,
    bottomLidEdge - uEyeSize * 0.04,
    eyeUV_y
  ) * bottomLidMask * 0.2;

  // --- COMPOSE THE EYE ---
  // Start with sclera
  float eyeR0 = scleraFinalR;
  float eyeG0 = scleraFinalG;
  float eyeB0 = scleraFinalB;

  // Each pupil zone gets its own iris tint for a multi-iris effect
  // Pupil 2 iris: shifted hue (green/emerald)
  float iris2Hue = fract(irisHueBase + 0.33);
  float iris2R = cos(iris2Hue * 6.2832) * 0.35 + 0.4;
  float iris2G = cos(iris2Hue * 6.2832 - 2.094) * 0.45 + 0.55;
  float iris2B = cos(iris2Hue * 6.2832 - 4.189) * 0.3 + 0.35;
  // Pupil 3 iris: shifted hue (violet/amber)
  float iris3Hue = fract(irisHueBase + 0.67);
  float iris3R = cos(iris3Hue * 6.2832) * 0.45 + 0.55;
  float iris3G = cos(iris3Hue * 6.2832 - 2.094) * 0.3 + 0.35;
  float iris3B = cos(iris3Hue * 6.2832 - 4.189) * 0.4 + 0.5;

  // Blend iris colors based on proximity to each pupil center
  float irisBlend2 = smoothstep(irisRadSq * 0.9, irisRadSq * 0.3, p2Dist) * 0.5;
  float irisBlend3 = smoothstep(irisRadSq * 0.9, irisRadSq * 0.3, p3Dist) * 0.5;
  float irisBlendTotal = clamp(irisBlend2 + irisBlend3, 0.0, 1.0);

  float irisMixR = mix(irisFinalR, mix(iris2R, iris3R, irisBlend3 / max(irisBlendTotal, 0.001)), irisBlendTotal);
  float irisMixG = mix(irisFinalG, mix(iris2G, iris3G, irisBlend3 / max(irisBlendTotal, 0.001)), irisBlendTotal);
  float irisMixB = mix(irisFinalB, mix(iris2B, iris3B, irisBlend3 / max(irisBlendTotal, 0.001)), irisBlendTotal);

  // Composite iris
  float eyeR1 = mix(eyeR0, irisMixR, irisMask);
  float eyeG1 = mix(eyeG0, irisMixG, irisMask);
  float eyeB1 = mix(eyeB0, irisMixB, irisMask);

  // Composite pupil
  float eyeR2 = mix(eyeR1, pupilR, pupilMask);
  float eyeG2 = mix(eyeG1, pupilG, pupilMask);
  float eyeB2 = mix(eyeB1, pupilB, pupilMask);

  // Add specular highlights
  float specTotal = clamp(specMask + spec2Mask + spec3Mask, 0.0, 1.0);
  float eyeR3 = eyeR2 + specTotal * 0.9;
  float eyeG3 = eyeG2 + specTotal * 0.9;
  float eyeB3 = eyeB2 + specTotal * 0.85;

  // Apply eyelid coverage
  float eyeR4 = mix(eyeR3, lidSkinR - creaseTop - creaseBottom, lidCover);
  float eyeG4 = mix(eyeG3, lidSkinG - creaseTop * 0.7 - creaseBottom * 0.6, lidCover);
  float eyeB4 = mix(eyeB3, lidSkinB - creaseTop * 0.5 - creaseBottom * 0.4, lidCover);

  // Eye shadow
  float shadowDist = scleraDist;
  float shadowRing = smoothstep(0.7, 1.3, shadowDist) * smoothstep(2.0, 1.3, shadowDist);
  float shadowIntensityVal = shadowRing * 0.3;

  // --- FINAL COMPOSITE ---
  float eyeRegion = smoothstep(1.6, 0.85, scleraDist);

  float shadowedFractalR = fractalCol.x - shadowIntensityVal * eyeRegion;
  float shadowedFractalG = fractalCol.y - shadowIntensityVal * eyeRegion;
  float shadowedFractalB = fractalCol.z - shadowIntensityVal * eyeRegion;

  float compositeR = mix(shadowedFractalR, eyeR4, scleraMask);
  float compositeG = mix(shadowedFractalG, eyeG4, scleraMask);
  float compositeB = mix(shadowedFractalB, eyeB4, scleraMask);

  float trebleSparkle = trebleVal * uSensitivity * 0.2;
  float sparkleR = compositeR + trebleSparkle * specTotal * scleraMask;
  float sparkleG = compositeG + trebleSparkle * specTotal * scleraMask;
  float sparkleB = compositeB + trebleSparkle * specTotal * scleraMask * 0.8;

  float starePulseVal = stareFactor * (sin(rawTime * 4.0) * 0.02 + 0.03);
  float stareGlowR = sparkleR + starePulseVal * pupilMask * scleraMask;
  float stareGlowG = sparkleG + starePulseVal * pupilMask * scleraMask * 0.3;
  float stareGlowB = sparkleB + starePulseVal * pupilMask * scleraMask * 0.6;

  float fractalBeatPulse = uBeat * uSensitivity * 0.08;

  // === PSYCHEDELIC ENHANCEMENT ===
  { vec3 _pc = psychedelicColor(vec3(stareGlowR, stareGlowG, stareGlowB)); stareGlowR = _pc.r; stareGlowG = _pc.g; stareGlowB = _pc.b; }
  gl_FragColor = vec4(
    clamp(stareGlowR + fractalBeatPulse * (1.0 - scleraMask), 0.0, 1.0),
    clamp(stareGlowG + fractalBeatPulse * (1.0 - scleraMask), 0.0, 1.0),
    clamp(stareGlowB + fractalBeatPulse * (1.0 - scleraMask), 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashTP(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseTP(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashTP(i);
  float b = hashTP(i + vec2(1.0, 0.0));
  float c = hashTP(i + vec2(0.0, 1.0));
  float d = hashTP(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Amoeba metaball organism
float amoeba(vec2 p, vec2 center, float sz, float time, float idx) {
  vec2 d = p - center;
  float r = length(d);
  float angle = atan(d.y, d.x);
  // Organic deformation
  float deform = 0.0;
  deform += sin(angle * 3.0 + time * 2.0 + idx * 4.0) * 0.2;
  deform += sin(angle * 5.0 - time * 1.5 + idx * 7.0) * 0.12;
  deform += sin(angle * 7.0 + time * 3.0 + idx * 2.0) * 0.06;
  float amoebaR = sz * (1.0 + deform);
  float body = smoothstep(amoebaR, amoebaR * 0.6, r);
  // Nucleus
  float nucleusR = sz * 0.25;
  float nucleusOffset = sz * 0.15;
  vec2 nucleusPos = center + vec2(cos(time * 0.5 + idx), sin(time * 0.4 + idx)) * nucleusOffset;
  float nucleus = smoothstep(nucleusR, nucleusR * 0.3, length(p - nucleusPos));
  return body + nucleus * 0.3;
}

// Diatom geometric pattern (radial symmetry)
float diatom(vec2 p, vec2 center, float sz, float time) {
  vec2 d = p - center;
  float r = length(d);
  float angle = atan(d.y, d.x);
  // Hexagonal radial symmetry
  float seg = mod(angle + 3.14159, 1.0472) - 0.5236;
  float segR = r / sz;
  // Concentric rings
  float rings = sin(segR * 15.0 + time * 0.5) * 0.5 + 0.5;
  rings *= smoothstep(1.2, 0.8, segR);
  // Radial spokes
  float spokes = smoothstep(0.03, 0.0, abs(seg)) * smoothstep(1.0, 0.2, segR);
  // Outer rim
  float rim = smoothstep(0.05, 0.0, abs(segR - 1.0));
  return (rings * 0.4 + spokes * 0.3 + rim * 0.5) * smoothstep(1.3, 1.0, segR);
}

// Caustic refraction pattern
float causticPattern(vec2 p, float time) {
  float c1 = noiseTP(p * 4.0 + time * 0.5);
  float c2 = noiseTP(p * 6.0 - time * 0.3 + vec2(3.0, 1.0));
  float c3 = noiseTP(p * 8.0 + time * 0.4 + vec2(7.0, 5.0));
  float caustic = sin(c1 * 6.2832) + sin(c2 * 6.2832) + sin(c3 * 6.2832);
  caustic = caustic / 3.0 * 0.5 + 0.5;
  return caustic * caustic;
}

// Microorganism color palette
vec3 tidalColor(float t, float paletteShift) {
  // Aqua / gold / magenta
  vec3 a = vec3(0.05, 0.25, 0.2);
  vec3 b = vec3(0.45, 0.35, 0.35);
  vec3 c = vec3(1.0, 1.0, 0.8);
  vec3 d = vec3(0.2 + paletteShift * 0.15, 0.5, 0.65);
  return a + b * cos(6.2832 * (c * t + d));
}

void main() {
  vec2 p = (vUv - 0.5) * 3.0 * (1.0 + uZoom);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.4) * 0.07;
  p *= breathe;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // Warm water background
  vec3 col = vec3(0.02, 0.05, 0.06);

  // Caustic light layer
  float caust = causticPattern(p, time);
  vec3 causticCol = vec3(0.15, 0.25, 0.2) * caust;
  causticCol *= 1.0 + trebleVal * 1.5; // Treble makes caustics dance
  col += causticCol;

  // Secondary caustic layer (deeper)
  float caust2 = causticPattern(p * 0.7 + vec2(2.0, 1.0), time * 0.7);
  col += vec3(0.05, 0.08, 0.12) * caust2 * 0.5;

  // Diatom background pattern (4 diatoms)
  for (float i = 0.0; i < 4.0; i += 1.0) {
    vec2 dCenter = vec2(
      sin(i * 2.5 + time * 0.05) * 0.8 + cos(time * 0.08 + i * 1.3) * 0.3,
      cos(i * 1.8 + time * 0.04) * 0.6 + sin(time * 0.06 + i * 2.1) * 0.3
    );
    float dSz = 0.2 + hashTP(vec2(i, 0.0)) * 0.15;
    float diat = diatom(p, dCenter, dSz, time);
    float hue = i * 0.25 + uPalette * 0.2 + time * 0.01;
    vec3 diatCol = tidalColor(hue, uPalette);
    col += diatCol * diat * (0.3 + midsVal * 0.2);
  }

  // Amoeba organisms (6 organisms)
  for (float i = 0.0; i < 6.0; i += 1.0) {
    float seed = hashTP(vec2(i, 1.0));
    vec2 aCenter = vec2(
      sin(time * 0.15 + i * 2.0) * 1.0,
      cos(time * 0.12 + i * 1.5) * 0.8
    );
    // Kick division effect: split into two briefly
    float divPhase = kickVal * sin(time * 4.0 + i * 3.0);
    vec2 splitOffset = vec2(cos(i * 5.0), sin(i * 5.0)) * divPhase * 0.1;

    float sz = 0.14 + seed * 0.1 + bassVal * 0.1;
    float org1 = amoeba(p, aCenter + splitOffset, sz, time, i);
    float org2 = amoeba(p, aCenter - splitOffset, sz * 0.8, time + 1.0, i + 10.0) * step(0.3, kickVal);

    float hue = seed + uPalette * 0.15 + time * 0.02;
    vec3 orgCol = tidalColor(hue + 0.3, uPalette);
    // Translucent membrane glow
    orgCol *= 1.7 + bassVal * 0.7;
    // Inner glow
    float innerGlow = exp(-length(p - aCenter) * 5.0) * 0.2;
    col += orgCol * (org1 + org2) * 0.5;
    col += orgCol * innerGlow;
  }

  // Floating particles (debris/plankton)
  for (float i = 0.0; i < 25.0; i += 1.0) {
    vec2 partPos = vec2(
      sin(time * 0.3 + i * 4.7) * 1.3 + cos(time * 0.1 + i * 2.3) * 0.5,
      cos(time * 0.25 + i * 3.1) * 1.0 + sin(time * 0.15 + i * 5.7) * 0.3
    );
    float partDist = length(p - partPos);
    float particle = exp(-partDist * 60.0);
    float hue = hashTP(vec2(i, 5.0)) + time * 0.05;
    vec3 partCol = tidalColor(hue, uPalette + 0.5);
    col += partCol * particle * 0.3 * (1.0 + trebleVal * 0.5);
  }

  // Water surface ripple from above
  float ripple = sin(length(p) * 8.0 - time * 2.0) * 0.5 + 0.5;
  ripple *= sin(length(p + vec2(0.5, -0.3)) * 6.0 - time * 1.5) * 0.5 + 0.5;
  col += vec3(0.05, 0.1, 0.08) * ripple * 0.15;

  // Onset burst - ink cloud
  float inkR = length(p);
  float ink = exp(-inkR * 2.0) * onsetVal * 0.3;
  col += tidalColor(time * 0.3, uPalette + 0.7) * ink;

  // Chaos: current distortion
  float current = sin(p.x * 5.0 + p.y * 3.0 + time * 2.0) * uChaos * 0.1;
  col += col * current;

  // Warmth modulation
  col += col * uWarmth * uSensitivity * 0.1;

  // Beat pulse
  col *= 1.0 + uBeat * uSensitivity * 0.12;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSpiralTightness;
uniform float uColorBands;
uniform float uBleedAmount;
uniform float uFabricTexture;

#define PI 3.14159265
#define TAU 6.28318530

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.1 + vec2(1.3, 1.7);
    a *= 0.5;
  }
  return v;
}

// Tie-dye saturated colors
vec3 tieDyeColor(float t, float palette) {
  // Bright saturated tie-dye palette
  float h = fract(t + palette * 0.2);
  float s = 0.85 + sin(t * TAU) * 0.1;
  float v = 0.9 + sin(t * TAU * 2.0) * 0.1;

  // HSV to RGB
  vec3 c = vec3(h, s, v);
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  vec2 uv = (vUv - 0.5) * (2.0 + uZoom * 1.5);
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float beatVal = uBeat * uSensitivity;

  // Polar coordinates — seamless angle via sin/cos to avoid atan discontinuity
  float r = length(uv);
  float angle = atan(uv.y, uv.x); // raw angle for reference

  // Use sin/cos of angle directly for seamless spiral computation
  // This avoids the PI/-PI discontinuity that causes the seam
  float cosA = uv.x / (r + 0.0001);
  float sinA = uv.y / (r + 0.0001);

  // Spiral: continuous angular coordinate using sin/cos combination
  // Instead of angle/TAU which has a seam, we use a smooth periodic function
  float spiralTight = uSpiralTightness * 8.0 + 2.0 + kickVal * 4.0;

  // Rotation from audio
  float rotation = time + midsVal * 2.0 + beatVal * 0.5;

  // Seamless spiral: atan2 has a 2*PI discontinuity which maps to exactly 1.0
  // in normalized space, so fract() on the entire expression absorbs it perfectly
  float shiftedAngle = atan(uv.y, uv.x) + rotation;
  // Do NOT fract the angle alone — let the full spiral expression wrap via fract later
  float spiral = shiftedAngle / TAU + r * spiralTight;

  // Bass expands the rings
  float ringR = r * (1.0 - bassVal * 0.3);

  // Concentric rings — fract() on full expression absorbs atan discontinuity
  float bands = uColorBands * 3.0 + 2.0;
  float ringPattern = fract(ringR * bands + spiral);

  // Bleed — soften band transitions using noise
  float bleed = uBleedAmount * 0.5;
  vec2 bleedOffset = vec2(
    fbm(uv * 3.0 + time * 0.2) - 0.5,
    fbm(uv * 3.0 + vec2(5.0) + time * 0.15) - 0.5
  ) * bleed;

  float bleedRing = fract((ringR + bleedOffset.x * 0.3) * bands + (spiral + bleedOffset.y));

  // Multiple tie-dye centers (fold points) — also use seamless coords
  float fold1Dist = length(uv - vec2(0.3, 0.2));
  float fold2Dist = length(uv - vec2(-0.2, -0.3));
  float fold3Dist = length(uv + vec2(0.1, 0.4));

  // Fold spirals use their own local angles (no seam because they are offset from center)
  float fold1Angle = atan(uv.y - 0.2, uv.x - 0.3);
  float fold2Angle = atan(uv.y + 0.3, uv.x + 0.2);
  float fold3Angle = atan(uv.y - 0.4, uv.x + 0.1);

  float fold1 = fold1Dist * bands * 0.5 + fract(fold1Angle / TAU + rotation * 0.3) * 2.0;
  float fold2 = fold2Dist * bands * 0.4 + fract(fold2Angle / TAU - rotation * 0.2) * 2.0;
  float fold3 = fold3Dist * bands * 0.3 + fract(fold3Angle / TAU + rotation * 0.15) * 2.0;

  float foldPattern = fract(fold1) * 0.3 +
                      fract(fold2) * 0.3 +
                      fract(fold3) * 0.3;

  // Combine spiral ring and fold patterns
  float pattern = mix(bleedRing, foldPattern, 0.4 + uChaos * 0.3);

  // Fabric texture
  float fabricX = noise(uv * 40.0 + time * 0.1) * uFabricTexture * 0.15;
  float fabricY = noise(uv * 35.0 + vec2(10.0) - time * 0.08) * uFabricTexture * 0.12;
  float fabric = (fabricX + fabricY) * trebleVal * 2.0 + fabricX + fabricY;

  // Color from pattern value
  float colorT = pattern + time * 0.02 + uPalette * 0.1;
  vec3 color = tieDyeColor(colorT, uPalette);

  // Second color layer for depth
  vec3 color2 = tieDyeColor(colorT + 0.33, uPalette + 1.0);
  float layerMix = fbm(uv * 2.0 + time * 0.1);
  color = mix(color, color2, layerMix * 0.4);

  // Fabric wrinkle darkening
  float wrinkle = fbm(uv * 8.0 + time * 0.05);
  color *= 0.85 + wrinkle * 0.3;

  // Add fabric texture highlights
  color += fabric * 0.2;

  // Beat pulse — brighten and saturate
  float lum = dot(color, vec3(0.299, 0.587, 0.114));
  color = mix(vec3(lum), color, 1.0 + beatVal * 0.3);
  color *= 1.0 + beatVal * 0.2;

  // Kick tightens — flash white center
  float kickFlash = kickVal * exp(-r * 3.0) * 0.4;
  color += kickFlash;

  // Intensity
  color *= uIntensity * 1.3;

  // Soft vignette
  float vig = 1.0 - r * 0.3;
  color *= clamp(vig, 0.3, 1.0);

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSpiralCenters;
uniform float uBleedAmount;
uniform float uSaturationBoost;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// HSV to RGB
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Single tie-dye spiral contribution
float spiralPattern(vec2 p, vec2 center, float rotation, float tightness) {
  vec2 d = p - center;
  float angle = atan(d.y, d.x);
  float r = length(d);
  return fract((angle / 6.2832 + r * tightness + rotation) * 3.0);
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.3;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Number of spiral centers (2-6)
  int numCenters = 2 + int(uSpiralCenters * 4.0);

  // Bleed amount modulated by mids
  float bleed = uBleedAmount * (1.0 + midsVal * 0.4);

  // Pre-define spiral centers
  vec2 centers[6];
  float rotations[6];
  float hueOffsets[6];

  centers[0] = vec2(0.0, 0.0) + vec2(sin(time * 0.2), cos(time * 0.15)) * uChaos * 0.3;
  centers[1] = vec2(0.4, 0.3) + vec2(cos(time * 0.18), sin(time * 0.22)) * uChaos * 0.2;
  centers[2] = vec2(-0.3, 0.4) + vec2(sin(time * 0.25 + 1.0), cos(time * 0.2 + 1.0)) * uChaos * 0.25;
  centers[3] = vec2(0.3, -0.4) + vec2(cos(time * 0.15 + 2.0), sin(time * 0.25 + 2.0)) * uChaos * 0.2;
  centers[4] = vec2(-0.4, -0.2) + vec2(sin(time * 0.22 + 3.0), cos(time * 0.18 + 3.0)) * uChaos * 0.22;
  centers[5] = vec2(0.0, -0.5) + vec2(cos(time * 0.2 + 4.0), sin(time * 0.15 + 4.0)) * uChaos * 0.18;

  // Rotation speeds affected by bass
  float rotBase = time * (0.5 + bassVal * 0.8);
  rotations[0] = rotBase;
  rotations[1] = rotBase * 0.8 + 1.0;
  rotations[2] = rotBase * 1.2 + 2.0;
  rotations[3] = rotBase * 0.9 + 3.0;
  rotations[4] = rotBase * 1.1 + 4.0;
  rotations[5] = rotBase * 0.7 + 5.0;

  hueOffsets[0] = 0.0 + uPalette * 0.5;
  hueOffsets[1] = 0.15 + uPalette * 0.5;
  hueOffsets[2] = 0.33 + uPalette * 0.5;
  hueOffsets[3] = 0.5 + uPalette * 0.5;
  hueOffsets[4] = 0.67 + uPalette * 0.5;
  hueOffsets[5] = 0.82 + uPalette * 0.5;

  // Beat shifts centers
  centers[0] += vec2(beatPulse * 0.05, -beatPulse * 0.03);
  centers[1] += vec2(-beatPulse * 0.04, beatPulse * 0.04);

  // Accumulate spiral contributions
  vec3 col = vec3(0.0);
  float totalWeight = 0.0;
  float tightness = 2.0 + uZoom;

  for (int i = 0; i < 6; i++) {
    if (i >= numCenters) break;
    float pattern = spiralPattern(p, centers[i], rotations[i], tightness);

    // Create color bands
    float hue = fract(pattern * 2.0 + hueOffsets[i]);
    float sat = 0.7 + uSaturationBoost * 0.3;
    float val = 0.8 + pattern * 0.2;
    vec3 dyeColor = hsv2rgb(vec3(hue, sat, val));

    // Weight by distance with bleed
    float dist = length(p - centers[i]);
    float weight = 1.0 / (dist * dist * (3.0 - bleed * 2.5) + 0.1);

    // Fabric texture modulation
    float fabricTex = noise(p * 30.0 + float(i) * 10.0) * 0.1 + 0.95;
    dyeColor *= fabricTex;

    col += dyeColor * weight;
    totalWeight += weight;
  }
  col /= totalWeight;

  // Fabric texture overlay (creases and folds)
  float crease1 = abs(sin(p.x * 20.0 + p.y * 15.0 + noise(p * 5.0) * 3.0));
  float crease2 = abs(sin(p.x * 15.0 - p.y * 22.0 + noise(p * 4.0 + 10.0) * 2.5));
  float creases = pow(min(crease1, crease2), 0.3) * 0.15 + 0.85;
  col *= creases;

  // Treble sparkle (dye crystallization)
  float sparkle = noise(p * 60.0 + time * 2.0);
  sparkle = pow(sparkle, 8.0) * trebleVal * 1.5;
  col += vec3(sparkle);

  // Beat flash
  col += vec3(0.3, 0.25, 0.2) * beatPulse * 0.15;

  // Kick saturate
  col = mix(col, col * 1.3, kickPulse * 0.3);

  // Energy and intensity
  col *= (0.7 + uEnergy * uSensitivity * 0.4);
  col *= uIntensity * 1.2;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

