uniform float uIntensity;
uniform float uChaos;

uniform float uHarmonics;
uniform float uPhaseDepth;
uniform float uSymmetryFolds;
uniform float uShimmer;

vec2 kaleidoFold(vec2 p, float folds) {
  float angle = atan(p.y, p.x);
  float sector = 6.2832 / folds;
  angle = mod(angle, sector);
  angle = abs(angle - sector * 0.5);
  float r = length(p);
  return vec2(cos(angle), sin(angle)) * r;
}

vec3 crystalPalette(float t, float offset) {
  // Icy/prismatic palette
  vec3 a = vec3(0.5, 0.5, 0.6);
  vec3 b = vec3(0.5, 0.5, 0.4);
  vec3 c = vec3(1.0, 1.0, 1.5);
  vec3 d = vec3(0.0 + offset, 0.15 + offset, 0.35);
  return a + b * cos(6.2832 * (c * t + d));
