void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // Apply kaleidoscopic symmetry
  float folds = max(uSymmetryFolds + bassVal * 2.0, 2.0);
  vec2 kp = kaleidoFold(p, folds);

  // Temporal crystal: sum oscillations at prime-ratio sub-periods
  float crystal = 0.0;
  float totalWeight = 0.0;
  float maxHarm = min(uHarmonics, 8.0);

  // Prime-like frequency ratios for quasiperiodic behavior
  float freqs[8];
  freqs[0] = 1.0;
  freqs[1] = 1.618033; // golden ratio
  freqs[2] = 2.414;    // silver ratio
  freqs[3] = 3.302;
  freqs[4] = 0.618033; // 1/phi
  freqs[5] = 2.236;    // sqrt(5)
  freqs[6] = 1.732;    // sqrt(3)
  freqs[7] = 0.414;    // silver - 1

  for (float i = 0.0; i < 8.0; i += 1.0) {
    if (i >= maxHarm) break;

    float freq = freqs[int(i)];
    float subTime = time * freq;

    // Phase interaction: each harmonic's spatial pattern
    float phaseOffset = uPhaseDepth * sin(subTime * 0.3 + i * 1.23);
    phaseOffset += onsetVal * sin(i * 2.1) * 0.5;

    // Spatial pattern at this temporal frequency
    float spatial = sin(kp.x * (4.0 + i * 1.5) + subTime + phaseOffset);
    spatial += cos(kp.y * (3.5 + i * 1.3) - subTime * 0.7 + phaseOffset * 0.8);
    spatial += sin((kp.x + kp.y) * (2.0 + i) + subTime * 0.5);
    spatial *= 0.333;

    // Shimmer: high-frequency sparkle on later harmonics
    float sparkle = sin(subTime * 12.0 + length(kp) * 20.0 + i * 5.0) * uShimmer * (i / maxHarm);

    float weight = 1.0 / (1.0 + i * 0.3);
    crystal += (spatial + sparkle) * weight;
    totalWeight += weight;
  }

  crystal /= max(totalWeight, 0.001);

  // Add chaos: perturb with irregular oscillation
  crystal += sin(crystal * 5.0 + time * 0.7) * uChaos * 0.3;
  crystal += midsVal * sin(crystal * 3.0 + time) * 0.2;

  // Map to color
  float colorVal = crystal * 0.5 + 0.5;
  vec3 color = crystalPalette(colorVal, uPalette * 0.1);

  // Faceted edges: sharpen around crystal boundaries
  float edge = abs(fract(crystal * 3.0) - 0.5) * 2.0;
  edge = smoothstep(0.3, 0.5, edge);
  color *= 0.6 + edge * 0.5;

  // Treble-reactive sparkle overlay
  float sparkleField = sin(kp.x * 30.0 + time * 5.0) * sin(kp.y * 30.0 - time * 4.0);
  sparkleField = smoothstep(0.85, 1.0, sparkleField);
  color += vec3(sparkleField * trebleVal * 0.5);

  // Intensity and energy
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.3;

  // Beat pulse
  color += vec3(uBeat * uSensitivity * 0.07);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.25));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

