uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPetalCount;
uniform float uBloomRate;
uniform float uLayerCount;
uniform float uOrganicWarp;

vec3 bloomPalette(float t, float offset) {
  // Warm organic palette: pinks, greens, golds
  vec3 a = vec3(0.6, 0.4, 0.4);
  vec3 b = vec3(0.4, 0.4, 0.3);
  vec3 c = vec3(1.0, 0.8, 0.6);
  vec3 d = vec3(0.0 + offset, 0.25 + offset, 0.5 + offset);
  return a + b * cos(6.2832 * (c * t + d));
}

// Single bloom shape at a given lifecycle phase
float bloomShape(vec2 p, float lifecycle, float petals, float warp) {
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Lifecycle: 0 = bud, 0.5 = full bloom, 1.0 = wilted
  float openness = sin(lifecycle * 3.14159); // peaks at 0.5
  float wiltDroop = max(0.0, lifecycle - 0.6) * 2.5; // starts at 0.6

  // Petal shape: modulated radius
  float petalWave = sin(angle * petals + lifecycle * 2.0) * 0.5 + 0.5;
  petalWave = pow(petalWave, 1.0 - openness * 0.5); // sharper when closed

  // Bloom radius grows and shrinks with lifecycle — larger blooms
  float bloomRadius = openness * 0.6 + 0.08;
  bloomRadius += petalWave * openness * 0.35;

  // Organic warping
  float warpAngle = sin(angle * 3.0 + lifecycle * 5.0) * warp * openness * 0.1;
  bloomRadius += warpAngle;

  // Wilt: petals droop downward
  bloomRadius -= wiltDroop * (sin(angle) * 0.5 + 0.5) * 0.15;

  // Distance from bloom edge
  float bloom = smoothstep(bloomRadius + 0.02, bloomRadius - 0.02, r);

  // Inner detail: stamen/pistil
  float inner = exp(-r * 8.0) * openness;

  // Petal veins
  float veins = sin(angle * petals * 2.0 + r * 15.0) * 0.5 + 0.5;
  veins *= smoothstep(bloomRadius, 0.0, r) * 0.3;

  return bloom * 0.6 + inner * 0.25 + veins * 0.15;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 2.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  float rate = uBloomRate + bassVal * 0.5;
  float maxLayers = min(uLayerCount, 10.0);

  vec3 color = vec3(0.0);

  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= maxLayers) break;

    // Each layer has a different position, scale, and lifecycle offset
    float layerSeed = i * 2.37 + uChaos * sin(i * 1.7);
    float phaseOffset = i / maxLayers; // stagger lifecycle phases

    // Bloom center position — spread across entire screen
    vec2 center = vec2(
      sin(time * 0.1 + layerSeed * 3.0) * 0.85,
      cos(time * 0.08 + layerSeed * 2.0) * 0.85
    );

    // Scale varies per layer — closer/bigger blooms
    float scale = 1.0 + i * 0.2 + midsVal * 0.3;

    vec2 lp = (p - center) * scale;

    // Organic warping
    float warp = uOrganicWarp + onsetVal * 0.2;
    lp.x += sin(lp.y * 3.0 + time * 0.5 + i) * warp * 0.15;
    lp.y += cos(lp.x * 2.5 + time * 0.4 + i) * warp * 0.15;

    // Lifecycle phase for this bloom
    float lifecycle = fract(time * rate * 0.2 + phaseOffset);

    // Number of petals varies slightly per layer
    float petals = uPetalCount + sin(layerSeed * 5.0) * 1.5;

    float bloom = bloomShape(lp, lifecycle, petals, warp);

    // Color shifts through lifecycle: green bud -> colorful bloom -> brown wilt
    float hueShift = lifecycle * 0.3 + i * 0.12 + uPalette * 0.1;
    float sat = 0.6 + sin(lifecycle * 3.14159) * 0.35; // most saturated at peak bloom
    vec3 layerColor = bloomPalette(bloom * 0.3 + hueShift, uPalette * 0.05);

    // Wilt desaturation
    float wiltFade = max(0.0, lifecycle - 0.7) * 3.3;
    layerColor = mix(layerColor, vec3(0.3, 0.2, 0.1), wiltFade * 0.5);

    color += layerColor * bloom * (1.0 / (1.0 + i * 0.3));
  }

  // Background: lush dark garden — fills entire screen
  float bgPattern = sin(p.x * 5.0 + time * 0.1) * sin(p.y * 5.0 + time * 0.08);
  float bgPattern2 = sin(p.x * 8.0 - time * 0.07) * sin(p.y * 7.0 + time * 0.05);
  vec3 bgColor = vec3(0.03, 0.06, 0.03) + vec3(0.015) * bgPattern + vec3(0.01, 0.02, 0.01) * bgPattern2;
  color = max(color, bgColor);

  // Vine-like background tendrils filling screen
  float vine = sin(p.x * 12.0 + p.y * 8.0 + time * 0.3) * sin(p.y * 10.0 - p.x * 6.0 + time * 0.2);
  vine = pow(max(vine, 0.0), 4.0) * 0.08;
  color += vec3(0.02, 0.06, 0.02) * vine;

  // Treble sparkle (pollen/fireflies) — more particles
  float sparkle = sin(p.x * 30.0 + time * 3.0) * sin(p.y * 30.0 - time * 2.5);
  sparkle = pow(max(sparkle, 0.0), 12.0);
  color += vec3(sparkle * trebleVal * 0.5, sparkle * trebleVal * 0.4, sparkle * trebleVal * 0.15);

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat pulse
  color += vec3(uBeat * uSensitivity * 0.05);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.15));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

