uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

float hashTC(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noiseTC(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hashTC(i);
  float b = hashTC(i + vec2(1.0, 0.0));
  float c = hashTC(i + vec2(0.0, 1.0));
  float d = hashTC(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbmTC(vec2 p) {
  float val = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 5; i++) {
    val += amp * noiseTC(p);
    amp *= 0.5;
    p *= 2.1;
  }
  return val;
}

// Spiral arm function
float spiralArm(float angle, float r, float time, float arms, float tightness) {
  float spiral = angle * arms + r * tightness - time;
  return sin(spiral) * 0.5 + 0.5;
}

// Lightning bolt
float lightning(vec2 p, vec2 start, vec2 end, float time, float seed) {
  vec2 dir = end - start;
  float dirLen = length(dir);
  vec2 n = normalize(dir);
  vec2 toP = p - start;
  float proj = dot(toP, n);
  float perp = dot(toP, vec2(-n.y, n.x));

  if (proj < 0.0 || proj > dirLen) return 0.0;

  // Jagged displacement
  float jag = 0.0;
  jag += sin(proj * 20.0 + seed * 10.0 + time * 50.0) * 0.03;
  jag += sin(proj * 40.0 + seed * 20.0 + time * 80.0) * 0.015;
  jag += sin(proj * 80.0 + seed * 40.0) * 0.008;

  float bolt = exp(-pow(perp - jag, 2.0) * 2000.0);
  // Glow
  float glow = exp(-pow(perp - jag, 2.0) * 200.0) * 0.4;
  return bolt + glow;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * (1.0 + uZoom * 0.5);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  // Vortex tightening with bass
  float vortexTight = 6.0 + bassVal * 8.0;

  vec3 col = vec3(0.0);

  // Multiple vortex layers — expanded radii to fill screen
  for (float layer = 0.0; layer < 4.0; layer += 1.0) {
    float layerSpeed = time * (1.5 + layer * 0.5);
    float arms = 3.0 + layer;
    float tightness = vortexTight * (1.0 + layer * 0.3);

    // Spiral density
    float spiral = spiralArm(angle, r, layerSpeed, arms, tightness);
    spiral = pow(spiral, 2.0 + layer);

    // Layer radius mask — much wider outer radius to fill screen
    float innerR = 0.03 + layer * 0.08;
    float outerR = 3.0 - layer * 0.15;
    float mask = smoothstep(innerR, innerR + 0.15, r) * smoothstep(outerR, outerR - 0.5, r);

    // Noise turbulence in the vortex
    vec2 rotP = vec2(cos(angle + layerSpeed * 0.3) * r, sin(angle + layerSpeed * 0.3) * r);
    float turb = fbmTC(rotP * 3.0 + layer * 10.0);

    spiral *= mask * (0.5 + turb * 0.5);

    // Layer colors: dark violet -> electric blue -> white at center
    float hue = layer * 0.15 + uPalette * 0.2 + r * 0.1;
    vec3 layerCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.6, 0.3, 0.8)));
    layerCol *= 1.0 + midsVal * (1.0 - layer * 0.2);

    col += layerCol * spiral * (0.4 - layer * 0.04);
  }

  // Debris particles spinning in the vortex — larger orbit radii
  for (float i = 0.0; i < 40.0; i += 1.0) {
    float seed = hashTC(vec2(i, 0.0));
    float debrisR = 0.15 + seed * 1.8;
    float debrisAngle = seed * 6.2832 + time * (3.0 / (debrisR + 0.1));
    debrisAngle += kickVal * sin(i * 7.0) * 0.5; // Kick bursts

    vec2 debrisPos = vec2(cos(debrisAngle), sin(debrisAngle)) * debrisR;
    // Add turbulent displacement
    debrisPos += vec2(
      sin(time * 2.0 + i * 3.7) * 0.05,
      cos(time * 1.5 + i * 5.1) * 0.05
    ) * uChaos;

    float dist = length(p - debrisPos);
    float debris = exp(-dist * 50.0);

    float hue = seed + time * 0.05 + uPalette * 0.1;
    vec3 debrisCol = 0.5 + 0.5 * cos(6.2832 * (hue + vec3(0.5, 0.3, 0.7)));
    debrisCol *= 2.0;
    col += debrisCol * debris * 0.5;

    // Debris trail
    float trailAngle = debrisAngle - 0.3;
    vec2 trailPos = vec2(cos(trailAngle), sin(trailAngle)) * debrisR;
    float trail = exp(-length(p - trailPos) * 25.0) * 0.3;
    col += debrisCol * trail * 0.2;
  }

  // Eye of the storm - dark center with faint glow
  float eyeGlow = exp(-r * 6.0) * 0.15;
  col += vec3(0.3, 0.2, 0.5) * eyeGlow;
  // Dark center
  float eyeDark = smoothstep(0.1, 0.0, r);
  col *= 1.0 - eyeDark * 0.8;

  // Cloud wall texture — pushed further out
  float cloudWall = fbmTC(vec2(angle * 3.0, r * 3.0 - time * 0.5));
  float wallMask = smoothstep(1.5, 2.0, r) * smoothstep(3.5, 2.5, r);
  col += vec3(0.05, 0.03, 0.08) * cloudWall * wallMask * 2.0;

  // Lightning on onset — wider bolts
  if (onsetVal > 0.1) {
    for (float i = 0.0; i < 3.0; i += 1.0) {
      float boltAngle = hashTC(vec2(floor(time * 2.0), i)) * 6.2832;
      vec2 boltStart = vec2(cos(boltAngle), sin(boltAngle)) * 0.2;
      vec2 boltEnd = vec2(cos(boltAngle + 0.3), sin(boltAngle + 0.3)) * 1.8;
      float bolt = lightning(p, boltStart, boltEnd, time, i + floor(time));
      col += vec3(0.7, 0.8, 1.0) * bolt * onsetVal;
    }
  }

  // Kick tightens + flash
  col += vec3(0.08, 0.05, 0.12) * kickVal * 0.3;

  // Spectral flux energy
  col += col * uSpectralFlux * uSensitivity * 0.2;

  // Beat pulse
  col *= 1.0 + uBeat * uSensitivity * 0.15;

  // Vignette from vortex wall — much softer, barely visible
  float vig = smoothstep(3.5, 1.0, r);
  col *= vig;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

