uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTrailLength;
uniform float uTrailCount;
uniform float uCurvature;
uniform float uFadeRate;

vec3 palette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.33, 0.67)));
}

// Compute the pattern at a given time offset
float tracePattern(vec2 p, float t, float curv, float chaos) {
  float accum = 0.0;
  for (float i = 0.0; i < 6.0; i += 1.0) {
    if (i >= uTrailCount) break;
    float phase = i * 0.618033 + chaos * sin(t * 0.3 + i);
    float cx = sin(t * 0.7 + phase * 3.14) * curv;
    float cy = cos(t * 0.5 + phase * 2.71) * curv;
    vec2 center = vec2(cx, cy);
    float dist = length(p - center);
    float wave = sin(dist * 8.0 - t * 3.0 + i * 1.5) * 0.5 + 0.5;
    wave *= exp(-dist * 2.0);
    accum += wave;
  }
  return accum;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;

  // Accumulate multiple time-offset samples (ghost trail effect)
  vec3 color = vec3(0.0);
  float totalWeight = 0.0;
  float trailSpan = uTrailLength * 2.0 + bassVal * 0.5;

  for (float s = 0.0; s < 12.0; s += 1.0) {
    float frac = s / 12.0;
    if (frac > 1.0) break;
    float timeOffset = frac * trailSpan;
    float sampleTime = time - timeOffset;

    float curv = uCurvature + sin(sampleTime * 0.2) * uChaos * 0.5 + onsetVal * 0.3;
    float pattern = tracePattern(p, sampleTime, curv, uChaos);

    // Each time sample gets a slightly shifted hue
    float hueShift = frac * 0.3 + uPalette * 0.1 + midsVal * 0.2;
    vec3 sampleColor = palette(pattern * 0.5 + sampleTime * 0.05, hueShift);
    sampleColor *= pattern;

    // Exponential fade for older samples
    float weight = exp(-frac * uFadeRate * 5.0);
    color += sampleColor * weight;
    totalWeight += weight;
  }

  color /= max(totalWeight, 0.001);

  // Brightness and energy boost
  color *= uIntensity * 1.2 + uEnergy * uSensitivity * 0.4;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.08);

  // Onset spike: brief white flash
  color = mix(color, vec3(1.0), onsetVal * 0.15);

  // Contrast curve
  color = pow(clamp(color, 0.0, 1.0), vec3(1.3));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCityDensity;
uniform float uFlightHeight;
uniform float uWireGlow;
uniform float uTrailLength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash3(vec3 p) {
  return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453);
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float kickVal = uKick * uSensitivity * 1.4;
  float energyVal = uEnergy * uSensitivity;

  // Camera setup — looking down at angle
  float camHeight = 0.4 + uFlightHeight * 0.4;
  float flightZ = time * 2.0 + uBpmSin * 0.5;

  vec2 screenPos = (p - 0.5) * 2.0;

  // Ground plane raycast
  float horizon = 0.1 - uFlightHeight * 0.2;
  float belowHorizon = step(p.y, 0.5 + horizon);

  // Perspective ground mapping
  float groundY = max(0.5 + horizon - p.y, 0.001);
  float perspZ = camHeight / groundY * uZoom;
  float groundX = screenPos.x * perspZ;
  float groundZ = perspZ + flightZ;

  // === GROUND GRID ===
  float gridScale = uCityDensity * 2.0;
  vec2 gridCell = floor(vec2(groundX, groundZ) * gridScale);
  vec2 gridFract = fract(vec2(groundX, groundZ) * gridScale);

  // Grid lines
  float gridLineX = smoothstep(0.03, 0.0, min(gridFract.x, 1.0 - gridFract.x));
  float gridLineZ = smoothstep(0.03, 0.0, min(gridFract.y, 1.0 - gridFract.y));
  float grid = clamp(gridLineX + gridLineZ, 0.0, 1.0);

  float depthFade = exp(-groundY * 4.0);
  vec3 gridColor = mix(vec3(0.0, 0.6, 1.0), vec3(1.0, 0.5, 0.0), uPalette * 0.5);
  vec3 groundCol = grid * gridColor * uWireGlow * depthFade * 0.6;

  // === BUILDINGS ===
  float bHash = hash(gridCell);
  float buildingPresent = step(0.4, bHash); // 60% of cells have buildings
  float buildingHeight = bHash * 0.6 * (1.0 + bassVal * 0.5);

  // Building wireframe from top-down perspective
  float inBuilding = buildingPresent;
  float bEdgeX = min(gridFract.x, 1.0 - gridFract.x);
  float bEdgeZ = min(gridFract.y, 1.0 - gridFract.y);
  float bInset = 0.1;
  float insideBuilding = step(bInset, bEdgeX) * step(bInset, bEdgeZ);

  // Building walls visible from angle
  float wallVis = (1.0 - insideBuilding) * buildingPresent;
  float wallBright = smoothstep(0.0, 0.1, min(bEdgeX, bEdgeZ));

  // Building top face
  float heightVis = smoothstep(0.0, buildingHeight * 0.5, camHeight - buildingHeight * 0.3);
  float topFace = insideBuilding * buildingPresent * heightVis;

  // Wireframe edges of building
  float wireEdge = smoothstep(0.02, 0.0, abs(bEdgeX - bInset)) + smoothstep(0.02, 0.0, abs(bEdgeZ - bInset));
  wireEdge *= buildingPresent;

  vec3 buildColor = mix(vec3(0.0, 0.8, 1.0), vec3(1.0, 0.4, 0.0), hash(gridCell + 99.0));
  buildColor *= (1.0 + midsVal * 0.3);

  vec3 buildCol = vec3(0.0);
  buildCol += wireEdge * buildColor * uWireGlow * depthFade;
  buildCol += topFace * buildColor * 0.1 * depthFade;
  // Window lights
  float windowGrid = step(0.5, fract(gridFract.x * 4.0)) * step(0.5, fract(gridFract.y * 4.0));
  float windowLit = step(0.6, hash(gridCell * 3.0 + floor(gridFract * 4.0)));
  buildCol += windowGrid * windowLit * insideBuilding * buildingPresent * vec3(1.0, 0.8, 0.3) * 0.2 * depthFade;

  // === LIGHT TRAILS (on streets) ===
  float trails = 0.0;
  for (float i = 0.0; i < 8.0; i++) {
    float trailZ = fract(flightZ * 0.3 + i * 0.125);
    float trailX = (hash(vec2(i, 42.0)) - 0.5) * 2.0;
    float trailDepth = trailZ * 10.0;
    float trailScreenY = 0.5 + horizon - camHeight / (trailDepth + 0.1);
    float trailScreenX = trailX / (trailDepth + 0.1) + 0.5;
    vec2 td = vec2(p.x - trailScreenX, p.y - trailScreenY);
    // Elongated trail
    float trailDist = length(td * vec2(1.0, 5.0 / (1.0 + uTrailLength * 3.0)));
    trails += smoothstep(0.02, 0.0, trailDist) * trebleVal * step(0.0, trailScreenY);
  }

  // === SKY ===
  vec3 skyCol = mix(vec3(0.0, 0.02, 0.06), vec3(0.0, 0.0, 0.02), p.y);
  // Horizon glow
  float hGlow = exp(-abs(p.y - 0.5 - horizon) * 30.0) * 0.4;
  skyCol += hGlow * gridColor;

  // === COMPOSITE ===
  vec3 col = skyCol;
  col = mix(col, groundCol + buildCol, belowHorizon);
  col += trails * vec3(1.0, 0.3, 0.1) * belowHorizon;

  // Kick flash
  col += kickVal * 0.1 * gridColor;

  // Energy ambient
  col += energyVal * 0.05 * vec3(0.0, 0.2, 0.4);

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFacetCount;
uniform float uDispersion;

// Rotation matrices
mat3 rotY(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c);
}

mat3 rotX(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c);
}

mat3 rotZ(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0);
}

// Octahedron SDF (diamond shape)
float sdOctahedron(vec3 p, float s) {
  p = abs(p);
  return (p.x + p.y + p.z - s) * 0.57735;
}

// Faceted diamond: octahedron with extra cuts
float sdDiamond(vec3 p, float size, float facets) {
  float base = sdOctahedron(p, size);
  // Add facet cuts via repeating planes
  float cuts = 0.0;
  float facetScale = 3.0 + facets * 8.0;
  vec3 ap = abs(p);
  // Top and bottom pyramid cuts
  cuts = max(cuts, ap.y - size * 0.85);
  // Side facets
  float side1 = dot(ap, normalize(vec3(1.0, 0.5, 0.0))) - size * 0.75;
  float side2 = dot(ap, normalize(vec3(0.0, 0.5, 1.0))) - size * 0.75;
  float side3 = dot(ap, normalize(vec3(1.0, 0.5, 1.0))) - size * 0.78;
  cuts = max(cuts, max(side1, max(side2, side3)));
  // Blend between smooth octahedron and faceted version
  return max(base, cuts * facets);
}

// Simple noise for background
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise2d(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Background color field for refraction
vec3 bgField(vec3 rd, float time) {
  float angle = atan(rd.z, rd.x);
  float elevation = asin(clamp(rd.y, -1.0, 1.0));
  // Spiral color pattern
  float spiral = sin(angle * 3.0 + elevation * 5.0 + time * 0.5) * 0.5 + 0.5;
  float rings = sin(elevation * 8.0 - time * 0.3) * 0.5 + 0.5;
  // Rich color palette
  vec3 c1 = vec3(0.8, 0.1, 0.4); // magenta
  vec3 c2 = vec3(0.1, 0.4, 0.9); // blue
  vec3 c3 = vec3(0.1, 0.9, 0.5); // green
  vec3 c4 = vec3(0.9, 0.6, 0.1); // amber
  vec3 col = mix(mix(c1, c2, spiral), mix(c3, c4, rings), sin(angle * 2.0 + time * 0.2) * 0.5 + 0.5);
  return col * 0.6;
}

void main() {
  vec2 uv = vUv;
  uv = psychedelicUV(uv); // breathing morph
  float time = uTime * uSpeed * 1.5;

  // Audio
  float bassVal = bass() * uSensitivity * 1.3;
  float trebleVal = treble() * uSensitivity * 1.2;
  float midsVal = mids() * uSensitivity * 1.2;
  float beatVal = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Ray setup
  vec2 p = (uv - 0.5) * 2.0;
  p.x *= 1.0; // aspect ratio assumed ~1:1 for fullscreen quad
  p *= (1.5 - uZoom * 0.8); // zoom control

  vec3 ro = vec3(0.0, 0.0, 3.5); // camera position
  vec3 rd = normalize(vec3(p, -2.0)); // ray direction

  // Rotation: slowly rotate diamond
  float rotAngleY = time * 0.4 + uChaos * sin(time * 0.15) * 0.5;
  float rotAngleX = time * 0.25 + sin(time * 0.3) * 0.2;
  float rotAngleZ = sin(time * 0.17) * 0.15;
  mat3 rot = rotY(rotAngleY) * rotX(rotAngleX) * rotZ(rotAngleZ);

  // Diamond size pulses with bass
  float diamondSize = 1.0 + bassVal * 0.15;

  // Raymarch
  float totalDist = 0.0;
  float hit = 0.0;
  vec3 hitPos = vec3(0.0);
  float minDist = 999.0;

  for (int i = 0; i < 30; i++) {
    vec3 pos = ro + rd * totalDist;
    vec3 rotPos = rot * pos;
    float d = sdDiamond(rotPos, diamondSize, uFacetCount);
    minDist = min(minDist, d);
    if (d < 0.002) {
      hit = 1.0;
      hitPos = pos;
      break;
    }
    if (totalDist > 10.0) break;
    totalDist += d * 0.8; // slightly conservative step
  }

  vec3 finalColor = vec3(0.0);

  // Background: dark with ambient glow
  float distFromCenter = length(p);
  vec3 bgColor = vec3(0.01, 0.01, 0.03);
  // Ambient glow around diamond (based on closest approach)
  float glowRadius = exp(-minDist * 3.0) * 0.5;
  vec3 glowColor = vec3(0.15 + uPalette * 0.05, 0.1, 0.3 + uPalette * 0.1);
  bgColor += glowColor * glowRadius * (1.0 + energyVal * 0.5);

  if (hit > 0.5) {
    // Normal via gradient
    vec2 e = vec2(0.001, 0.0);
    vec3 rp = rot * hitPos;
    float dx = sdDiamond(rp + e.xyy, diamondSize, uFacetCount) - sdDiamond(rp - e.xyy, diamondSize, uFacetCount);
    float dy = sdDiamond(rp + e.yxy, diamondSize, uFacetCount) - sdDiamond(rp - e.yxy, diamondSize, uFacetCount);
    float dz = sdDiamond(rp + e.yyx, diamondSize, uFacetCount) - sdDiamond(rp - e.yyx, diamondSize, uFacetCount);
    vec3 normal = normalize(vec3(dx, dy, dz));
    // Transform normal back from diamond space
    normal = transpose(rot) * normal;
    // Actually we compute normal in rotated space, keep in world space
    // Re-derive in world space for lighting
    vec3 worldNormal = normalize(vec3(dx, dy, dz));
    worldNormal = transpose(rot) * worldNormal;

    // Lighting
    vec3 lightDir = normalize(vec3(1.0, 1.5, 1.0));
    vec3 lightDir2 = normalize(vec3(-1.0, 0.5, -0.5));
    float diff = max(dot(worldNormal, lightDir), 0.0) * 0.6;
    float diff2 = max(dot(worldNormal, lightDir2), 0.0) * 0.3;

    // Specular (Blinn-Phong)
    vec3 viewDir = normalize(ro - hitPos);
    vec3 halfVec = normalize(lightDir + viewDir);
    vec3 halfVec2 = normalize(lightDir2 + viewDir);
    float spec = pow(max(dot(worldNormal, halfVec), 0.0), 64.0);
    float spec2 = pow(max(dot(worldNormal, halfVec2), 0.0), 32.0);

    // Surface sparkle from treble
    float sparkle = pow(max(dot(worldNormal, halfVec), 0.0), 128.0) * trebleVal * 3.0;
    sparkle += pow(max(dot(worldNormal, halfVec2), 0.0), 96.0) * trebleVal * 2.0;

    // Prismatic refraction: sample background at 3 different refraction angles for R, G, B
    float ior = 1.8; // diamond-like
    float dispAmt = uDispersion * 0.08 + 0.02;
    vec3 refractR = refract(rd, worldNormal, 1.0 / (ior - dispAmt));
    vec3 refractG = refract(rd, worldNormal, 1.0 / ior);
    vec3 refractB = refract(rd, worldNormal, 1.0 / (ior + dispAmt));

    // If total internal reflection, use reflection instead
    vec3 reflDir = reflect(rd, worldNormal);
    if (length(refractR) < 0.01) refractR = reflDir;
    if (length(refractG) < 0.01) refractG = reflDir;
    if (length(refractB) < 0.01) refractB = reflDir;

    float refR = bgField(refractR, time).r;
    float refG = bgField(refractG, time).g;
    float refB = bgField(refractB, time).b;
    vec3 refractedColor = vec3(refR, refG, refB);

    // Reflection color
    vec3 reflColor = bgField(reflDir, time) * 0.5;

    // Fresnel
    float fresnel = pow(1.0 - max(dot(viewDir, worldNormal), 0.0), 3.0);

    // Internal glow based on depth into diamond
    float depth = totalDist;
    vec3 innerGlow = vec3(0.3 + sin(time) * 0.1, 0.1, 0.5 + cos(time * 0.7) * 0.2);
    innerGlow *= energyVal * 0.5 + 0.3;

    // Combine
    vec3 surfaceColor = mix(refractedColor, reflColor, fresnel * 0.5);
    surfaceColor += innerGlow * 0.3;
    surfaceColor += (diff + diff2) * vec3(0.8, 0.85, 1.0) * 0.3;
    surfaceColor += spec * vec3(1.0, 0.95, 0.9) * 1.5;
    surfaceColor += spec2 * vec3(0.7, 0.8, 1.0) * 0.8;
    surfaceColor += sparkle * vec3(1.0, 1.0, 1.0);

    // Beat flash: bright white specular burst
    surfaceColor += beatVal * spec * 3.0 * vec3(1.0, 0.9, 0.95);

    // Kick: color burst
    surfaceColor += kickVal * 0.3 * vec3(0.8, 0.2, 0.5);

    // Palette shift
    float palAngle = uPalette * 6.28318;
    surfaceColor.r += sin(palAngle) * 0.08;
    surfaceColor.g += sin(palAngle + 2.094) * 0.08;
    surfaceColor.b += sin(palAngle + 4.189) * 0.08;

    finalColor = surfaceColor * uIntensity;
  } else {
    finalColor = bgColor;
    // Subtle star-like sparkles in background
    float starNoise = noise2d(p * 50.0 + time * 0.1);
    float starMask = step(0.97, starNoise) * 0.3;
    finalColor += vec3(starMask * 0.5, starMask * 0.4, starMask * 0.8);
  }

  // Vignette
  float vignette = smoothstep(1.8, 0.5, distFromCenter);
  finalColor *= vignette * 0.3 + 0.7;

  // Onset flash
  finalColor += vec3(0.2, 0.15, 0.3) * onsetVal * 0.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  finalColor = psychedelicColor(finalColor);
  gl_FragColor = vec4(
    clamp(finalColor.r, 0.0, 1.0),
    clamp(finalColor.g, 0.0, 1.0),
    clamp(finalColor.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPetalCount;
uniform float uFoldDepth;
uniform float uBloomRate;

vec3 chrysanthemumPalette(float t, float offset) {
  float tau = 6.28318;
  return vec3(
    0.5 + 0.5 * cos(tau * (t + 0.0 + offset * 0.25)),
    0.5 + 0.5 * cos(tau * (t + 0.33 + offset * 0.25)),
    0.5 + 0.5 * cos(tau * (t + 0.67 + offset * 0.25))
  );
}

float petalSDF(vec2 p, float petals, float phase) {
  float r = length(p);
  float a = atan(p.y, p.x);
  float petal = cos(a * petals + phase) * 0.5 + 0.5;
  petal = pow(petal, 2.0);
  return r - petal * 0.7;
}

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

void main() {
  float time = uTime * (uSpeed * 1.5);
  vec2 p = (vUv - 0.5) * 2.0 * (uZoom * 1.2 + 0.5);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float r = length(p);
  float angle = atan(p.y, p.x);

  float petals = floor(6.0 + uPetalCount * 14.0);
  float bloomPhase = time * uBloomRate * 2.0;
  float foldLayers = 2.0 + uFoldDepth * 4.0;

  vec3 color = vec3(0.0);
  float totalWeight = 0.0;

  // Layered petals with decreasing scale (recursive chrysanthemum)
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float layerScale = 1.0 / (1.0 + fi * 0.35);
    if (fi >= foldLayers) break;

    // Each layer rotates and scales
    float layerRot = bloomPhase * (0.5 + fi * 0.15) + fi * 0.4;
    layerRot += bassVal * 0.3 * sin(time + fi);

    float ca = cos(layerRot);
    float sa = sin(layerRot);
    vec2 rp = vec2(p.x * ca - p.y * sa, p.x * sa + p.y * ca) / layerScale;

    // Fold the coordinates for this layer
    float foldAngle = atan(rp.y, rp.x);
    float foldR = length(rp);

    // Petal pattern for this layer
    float layerPetals = petals + fi * 2.0;
    float petalPhase = bloomPhase * (1.0 + fi * 0.3) + beatPulse * 3.14159;
    float d = petalSDF(rp, layerPetals, petalPhase);

    // Unfold animation: petals curl outward over time — expanded
    float unfold = sin(bloomPhase + fi * 1.0 + bassVal * 2.0) * 0.5 + 0.5;
    d -= unfold * 0.25;

    // Edge shimmer from treble
    float edgeShimmer = sin(foldAngle * layerPetals * 2.0 + time * 5.0) * trebleVal * 0.05;
    d += edgeShimmer;

    // Petal mask
    float petalMask = smoothstep(0.02, -0.02, d);

    // Color per layer
    float colorT = fi * 0.15 + foldAngle * 0.1 + midsVal * 0.3 + time * 0.05;
    vec3 layerColor = chrysanthemumPalette(colorT, uPalette);

    // Inner glow within each petal
    float innerGlow = smoothstep(0.2, -0.1, d) * 0.5;
    layerColor += innerGlow * 0.3;

    // Edge highlight
    float edge = smoothstep(0.02, 0.0, abs(d)) * (1.0 + trebleVal);
    layerColor += edge * 0.4;

    float layerAlpha = petalMask * layerScale * (0.7 + fi * 0.05);
    color += layerColor * layerAlpha;
    totalWeight += layerAlpha;
  }

  if (totalWeight > 0.001) {
    color /= totalWeight;
  }

  // Center glow
  float centerGlow = exp(-r * 3.0) * (0.5 + kickVal * 1.5);
  vec3 glowColor = chrysanthemumPalette(time * 0.1, uPalette + 0.5);
  color += centerGlow * glowColor;

  // Radial dissolve at edges (petals dissolve into fractals at edge) — pushed outward
  float dissolveNoise = fract(sin(angle * 20.0 + r * 15.0 + time) * 43758.5);
  float dissolve = smoothstep(1.2 + uChaos * 0.3, 1.8, r + dissolveNoise * 0.2);
  color = mix(color, color * dissolveNoise * 0.3, dissolve);

  // Background ambient fill — no pure black edges
  color += chrysanthemumPalette(time * 0.02, uPalette) * 0.03;

  // Beat flash
