uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSunSize;
uniform float uGridDensity;
uniform float uPalmSway;
uniform float uFlareCount;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float palmTree(vec2 uv, float x, float sway, float time) {
  // Trunk
  float trunkX = x + sin(uv.y * 4.0 + time * 0.5) * sway * 0.02;
  float trunk = smoothstep(0.012, 0.0, abs(uv.x - trunkX)) * step(0.25, uv.y) * step(uv.y, 0.65);
  // Fronds
  float frondBase = 0.65;
  float frond = 0.0;
  for (float i = 0.0; i < 5.0; i++) {
    float angle = (i - 2.0) * 0.35 + sin(time * 0.7 + i) * sway * 0.15;
    vec2 d = uv - vec2(trunkX, frondBase);
    float rotX = d.x * cos(angle) - d.y * sin(angle);
    float rotY = d.x * sin(angle) + d.y * cos(angle);
    float leaf = smoothstep(0.008, 0.0, abs(rotY)) * smoothstep(0.18, 0.0, rotX) * step(0.0, rotX);
    frond = max(frond, leaf);
  }
  return clamp(trunk + frond, 0.0, 1.0);
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float kickVal = uKick * uSensitivity * 1.4;

  float horizon = 0.45;
  float sx = p.x - 0.5;
  float sy = p.y;

  // === SKY GRADIENT ===
  vec3 skyBot = vec3(1.0, 0.4, 0.2);   // orange
  vec3 skyMid = vec3(0.9, 0.15, 0.5);  // pink
  vec3 skyTop = vec3(0.2, 0.05, 0.4);  // dark purple
  float skyT = clamp((sy - horizon) / (1.0 - horizon), 0.0, 1.0);
  vec3 sky = mix(skyBot, skyMid, smoothstep(0.0, 0.4, skyT));
  sky = mix(sky, skyTop, smoothstep(0.3, 0.9, skyT));

  // Palette shift
  sky = mix(sky, sky.gbr, uPalette * 0.3);

  // === SUN ===
  vec2 sunCenter = vec2(0.0, 0.05);
  float sunDist = length(vec2(sx, sy - horizon - sunCenter.y));
  float sunRadius = uSunSize * (1.0 + bassVal * 0.15);
  float sun = smoothstep(sunRadius + 0.01, sunRadius - 0.01, sunDist);

  // Sun horizontal slice lines
  float slices = 0.0;
  float sliceCount = uFlareCount;
  for (float i = 1.0; i <= 8.0; i++) {
    if (i > sliceCount) break;
    float sliceY = horizon + sunCenter.y + sunRadius * (1.0 - i / (sliceCount + 1.0));
    float sliceGap = 0.004 + i * 0.002;
    slices += step(abs(sy - sliceY), sliceGap) * sun;
  }
  sun *= (1.0 - slices);

  vec3 sunColor = mix(vec3(1.0, 0.85, 0.2), vec3(1.0, 0.3, 0.5), smoothstep(0.0, sunRadius, sunDist));
  float sunGlow = exp(-sunDist * 8.0) * 0.4;

  // Sun flare lines
  float flare = 0.0;
  for (float i = 0.0; i < 6.0; i++) {
    float fy = horizon + sunCenter.y + (i - 2.5) * 0.04;
    flare += exp(-abs(sy - fy) * 200.0) * exp(-abs(sx) * 3.0) * 0.3;
  }

  // === PERSPECTIVE GRID ===
  float belowHorizon = step(sy, horizon);
  float rawDepth = horizon - sy;
  float safeDepth = max(rawDepth, 0.001);
  float perspZ = 1.0 / safeDepth * uZoom;

  float scrollSpeed = uBpmSin * 0.5 + time * 0.5;
  float gridX = sx * perspZ * uGridDensity;
  float gridY = perspZ * uGridDensity + scrollSpeed + kickVal * 2.0;

  float hLine = 1.0 - abs(fract(gridY) - 0.5) * 2.0;
  hLine = pow(clamp(hLine, 0.0, 1.0), 3.0 + bassVal * 2.0);
  float vLine = 1.0 - abs(fract(gridX) - 0.5) * 2.0;
  vLine = pow(clamp(vLine, 0.0, 1.0), 3.0);

  float gridGlow = clamp(hLine + vLine, 0.0, 1.0);
  float depthFade = smoothstep(0.0, 0.15, safeDepth);
  gridGlow *= depthFade * (1.0 + bassVal * 0.6);

  vec3 gridColor = mix(vec3(0.0, 0.9, 1.0), vec3(1.0, 0.1, 0.8), uBpmSin2 * 0.5 + 0.5);
  vec3 gridFinal = gridColor * gridGlow * uIntensity * 1.5;

  // Horizon glow
  float hGlow = exp(-abs(sy - horizon) * 60.0) * 0.6;

  // === PALM SILHOUETTES ===
  float palm = 0.0;
  palm = max(palm, palmTree(p, -0.38, uPalmSway, time));
  palm = max(palm, palmTree(p, 0.42, uPalmSway, time + 2.0));
  palm = max(palm, palmTree(vec2(p.x, p.y * 0.9 + 0.05), -0.44, uPalmSway * 0.7, time + 1.0));

  // === COMPOSITE ===
  vec3 col = vec3(0.02, 0.0, 0.04);
  col = mix(col, sky, step(horizon, sy));
  col += sunColor * sun * step(horizon, sy);
  col += sunGlow * vec3(1.0, 0.5, 0.3) * step(horizon, sy);
  col += flare * vec3(1.0, 0.6, 0.8);
  col += gridFinal * belowHorizon;
  col += hGlow * gridColor;

  // Palm silhouette (dark cutout)
  col = mix(col, vec3(0.01, 0.0, 0.02), palm);

  // Energy glow
  col *= 0.8 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  col += vec3(0.05, 0.02, 0.08) * uBeat * uSensitivity;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uPersistence;
uniform float uLineWidth;
uniform float uShapeCount;
uniform float uRotationSpeed;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Distance to line segment
float sdSegment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// Rotate point
vec2 rot(vec2 p, float a) {
  float c = cos(a), s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Draw a regular polygon wireframe
float polygon(vec2 p, vec2 center, float radius, float sides, float rotation) {
  float minDist = 10.0;
  for (float i = 0.0; i < 12.0; i++) {
    if (i >= sides) break;
    float a1 = (i / sides) * 6.2832 + rotation;
    float a2 = ((i + 1.0) / sides) * 6.2832 + rotation;
    vec2 v1 = center + vec2(cos(a1), sin(a1)) * radius;
    vec2 v2 = center + vec2(cos(a2), sin(a2)) * radius;
    float d = sdSegment(p, v1, v2);
    minDist = min(minDist, d);
  }
  return minDist;
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 * uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  float lineW = (0.003 + uLineWidth * 0.008) * (1.0 + bassVal * 0.5);
  float thinLine = lineW * (0.3 + trebleVal * 0.3);

  float brightness = 0.0;

  // === VECTOR SHAPES ===
  for (float i = 0.0; i < 8.0; i++) {
    if (i >= uShapeCount) break;

    float phase = i / uShapeCount;
    float orbitAngle = time * uRotationSpeed * (0.5 + phase * 0.5) + i * 1.2;
    float orbitRadius = 0.3 + sin(time * 0.3 + i) * 0.15;

    // Spectrum-driven radius
    float specIdx = mod(i, 8.0);
    float specVal = 0.0;
    if (specIdx < 1.0) specVal = uSpectrum0;
    else if (specIdx < 2.0) specVal = uSpectrum1;
    else if (specIdx < 3.0) specVal = uSpectrum2;
    else if (specIdx < 4.0) specVal = uSpectrum3;
    else if (specIdx < 5.0) specVal = uSpectrum4;
    else if (specIdx < 6.0) specVal = uSpectrum5;
    else if (specIdx < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    vec2 center = vec2(cos(orbitAngle), sin(orbitAngle)) * orbitRadius;
    float shapeRadius = 0.1 + specVal * uSensitivity * 0.3;
    float sides = 3.0 + mod(i, 6.0); // Triangle to octagon
    float shapeRot = time * uRotationSpeed * (1.0 + i * 0.3);

    float d = polygon(p, center, shapeRadius, sides, shapeRot);

    // Phosphor glow (thick near line, thin bloom)
    float sharp = smoothstep(lineW, 0.0, d);
    float bloom = exp(-d * 80.0 / (1.0 + uPersistence)) * 0.4;

    brightness += sharp + bloom;
  }

  // === SPECTRUM WAVEFORM ===
  float waveY = 0.0;
  for (float i = 0.0; i < 8.0; i++) {
    float x = (i / 7.0) * 2.0 - 1.0;
    float specVal = 0.0;
    if (i < 1.0) specVal = uSpectrum0;
    else if (i < 2.0) specVal = uSpectrum1;
    else if (i < 3.0) specVal = uSpectrum2;
    else if (i < 4.0) specVal = uSpectrum3;
    else if (i < 5.0) specVal = uSpectrum4;
    else if (i < 6.0) specVal = uSpectrum5;
    else if (i < 7.0) specVal = uSpectrum6;
    else specVal = uSpectrum7;

    float nextSpec = (i < 7.0) ? specVal : uSpectrum7;
    float t = clamp((p.x - x) * 3.5 + 0.5, 0.0, 1.0);
    float h = specVal * uSensitivity * 0.4;
    float nextH = nextSpec * uSensitivity * 0.4;
    waveY += mix(h, nextH, t) * step(abs(p.x - x), 0.18);
  }
  float waveDist = abs(p.y + 0.7 - waveY);
  brightness += smoothstep(thinLine, 0.0, waveDist) * 0.6;
  brightness += exp(-waveDist * 100.0) * 0.2;

  // === CROSSHAIR / RETICLE ===
  float reticleSize = 0.05 + kickVal * 0.1;
  float crossH = smoothstep(thinLine, 0.0, abs(p.y)) * step(abs(p.x), reticleSize);
  float crossV = smoothstep(thinLine, 0.0, abs(p.x)) * step(abs(p.y), reticleSize);
  float circle = abs(length(p) - reticleSize);
  float reticle = crossH + crossV + smoothstep(thinLine, 0.0, circle);
  brightness += reticle * 0.3;

  // === BORDER FRAME ===
  vec2 absP = abs(p);
  float border = smoothstep(thinLine * 2.0, 0.0, abs(absP.x - 0.95)) * step(absP.y, 0.95);
  border += smoothstep(thinLine * 2.0, 0.0, abs(absP.y - 0.95)) * step(absP.x, 0.95);
  brightness += border * 0.2;

  // === PHOSPHOR COLOR ===
  vec3 phosphorGreen = vec3(0.15, 1.0, 0.3);
  vec3 phosphorBlue = vec3(0.2, 0.5, 1.0);
  vec3 phosphorAmber = vec3(1.0, 0.7, 0.15);
  vec3 phosphor = mix(phosphorGreen, phosphorBlue, uPalette * 0.5);
  phosphor = mix(phosphor, phosphorAmber, max(0.0, uPalette - 0.5) * 2.0);

  vec3 col = phosphor * brightness;

  // Scanline effect
  float scan = sin(vUv.y * 600.0) * 0.5 + 0.5;
  col *= 0.85 + scan * 0.15;

  // CRT vignette
  vec2 vigUV = vUv * 2.0 - 1.0;
  col *= 1.0 - dot(vigUV, vigUV) * 0.2;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

