__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTrackingStrength;
uniform float uScanLineCount;
uniform float uNoiseAmount;
uniform float uColorBleed;

float hash11(float n) {
  return fract(sin(n * 43758.5453123) * 43758.5453);
}

float hash21(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  float ux = fx * fx * (3.0 - fx * 2.0);
  float uy = fy * fy * (3.0 - fy * 2.0);
  float n00 = hash21(ix, iy);
  float n10 = hash21(ix + 1.0, iy);
  float n01 = hash21(ix, iy + 1.0);
  float n11 = hash21(ix + 1.0, iy + 1.0);
  float nx0 = mix(n00, n10, ux);
  float nx1 = mix(n01, n11, ux);
  return mix(nx0, nx1, uy);
}

float fbm2d(float x, float y) {
  float acc = 0.0;
  acc += noise2d(x, y) * 0.5;
  acc += noise2d(x * 2.03, y * 2.03) * 0.25;
  acc += noise2d(x * 4.01, y * 4.01) * 0.125;
  return acc;
}

void main() {
  vec2 p = vUv;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);

  // Audio-reactive modulators
  float bassWidth = bass() * uSensitivity;
  float trebleNoise = treble() * uSensitivity;
  float beatGlitch = uBeat * uSensitivity;
  float onsetGlitch = uOnset * uSensitivity;
  float energySpeed = uEnergy * uSensitivity;

  // === TRACKING BAND ===
  float bandCenter = fract(time * 0.08 + uChaos * 0.2);
  float bandHalfWidth = 0.08 + bassWidth * 0.06 + onsetGlitch * 0.12;
  float distFromBand = abs(p.y - bandCenter);
  float distFromBandWrap = abs(p.y - (bandCenter + 1.0));
  float distFromBandWrap2 = abs(p.y - (bandCenter - 1.0));
  float bandDist1 = smoothstep(bandHalfWidth, 0.0, distFromBand);
  float bandDist2 = smoothstep(bandHalfWidth, 0.0, distFromBandWrap);
  float bandDist3 = smoothstep(bandHalfWidth, 0.0, distFromBandWrap2);
