              palA < 1.5 ? coolNeon :
              palA < 2.5 ? classicNTSC :
              palA < 3.5 ? sepia :
              palA < 4.5 ? acidColors : blueNoir;

  vec3 colB = palB < 0.5 ? warmRetro :
              palB < 1.5 ? coolNeon :
              palB < 2.5 ? classicNTSC :
