  gl_FragColor = vec4(
    clamp(outR, 0.0, 1.0),
    clamp(outG, 0.0, 1.0),
    clamp(outB, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uStringDensity;
uniform float uHarmonics;
uniform float uVibrationAmp;
uniform float uQuantumFoam;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float hash1(float p) {
  return fract(sin(p * 127.1) * 43758.5453);
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.8;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetFlash = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  vec3 col = vec3(0.0);

  // === QUANTUM FOAM BACKGROUND ===
  float foam = 0.0;
  for (int i = 0; i < 4; i++) {
    float fi = float(i);
    float scale = 20.0 + fi * 15.0;
    vec2 fp = p * scale + time * (0.5 + fi * 0.3);
    vec2 fId = floor(fp);
    vec2 ff = fract(fp) - 0.5;
    float h = hash(fId);
    float flicker = sin(time * (10.0 + h * 20.0) + h * 100.0) * 0.5 + 0.5;
    foam += exp(-dot(ff, ff) * (30.0 + fi * 10.0)) * flicker * 0.02;
  }
  col += vec3(0.1, 0.08, 0.15) * foam * uQuantumFoam;

  // === VIBRATING STRINGS FIELD ===
  // Multiple orientations of strings for a dense web
  for (int orient = 0; orient < 3; orient++) {
    float forient = float(orient);
    float rotAngle = forient * 1.0472 + time * 0.05 * uChaos; // 60 degree rotations
    float cr = cos(rotAngle);
    float sr = sin(rotAngle);
    vec2 rp = vec2(p.x * cr - p.y * sr, p.x * sr + p.y * cr);

    // String index
    float stringIdx = rp.y * uStringDensity;
    float stringId = floor(stringIdx);
    float stringFrac = fract(stringIdx) - 0.5;

    // Each string vibrates
    float stringHash = hash1(stringId + forient * 100.0);
    float baseFreq = 1.0 + stringHash * 4.0;

    // Displacement from harmonics
    float displacement = 0.0;
    float amp = uVibrationAmp * (1.0 + bassVal * 0.5);

    for (int h = 0; h < 8; h++) {
      if (float(h) >= uHarmonics) break;
      float fh = float(h) + 1.0;
      float harmFreq = baseFreq * fh;
      float harmPhase = time * harmFreq * 3.0 + stringHash * 6.2832;
      // Standing wave: sin(n*pi*x/L) * cos(w*t)
      float standing = sin(rp.x * harmFreq * 3.14159 + harmPhase);
      // Amplitude decreases with harmonic number
      float harmAmp = amp / fh;
      // Treble boosts higher harmonics
      if (h >= 3) harmAmp *= (1.0 + trebleVal * 2.0);
      displacement += standing * harmAmp;
    }

    // Beat resonance: burst of extra displacement
    displacement += sin(rp.x * baseFreq * 6.28 + time * 10.0) * beatPulse * amp * 2.0;

    // Distance from displaced string position
    float dist = abs(stringFrac / uStringDensity - displacement);
    float stringThickness = 0.0008 + energyVal * 0.0003;

    // String glow
    float stringGlow = exp(-dist * dist / (stringThickness * stringThickness));
    // Vibration energy determines brightness
    float vibEnergy = abs(displacement) / (amp * 2.0 + 0.001);

    // Color by string frequency and orientation
    float colorT = stringHash + forient * 0.33 + uPalette * 0.1;
    vec3 stringCol = 0.5 + 0.5 * cos(6.2832 * (vec3(1.0) * colorT + vec3(0.0, 0.33, 0.67)));
    // Hotter strings (more vibration) shift toward white
    stringCol = mix(stringCol, vec3(1.0), vibEnergy * 0.4);

    col += stringCol * stringGlow * (0.3 + vibEnergy * 0.7);
  }

  // === INTERFERENCE NODES ===
  // Where strings from different orientations cross, show bright nodes
  float nodePattern = 0.0;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float a1 = fi * 1.0472 + time * 0.05 * uChaos;
    float c1 = cos(a1); float s1 = sin(a1);
    vec2 r1 = vec2(p.x * c1 - p.y * s1, p.x * s1 + p.y * c1);
    float idx1 = sin(r1.y * uStringDensity * 3.14159);
    nodePattern += abs(idx1);
  }
  nodePattern = pow(1.0 - nodePattern / 3.0, 4.0);
  col += vec3(0.8, 0.9, 1.0) * nodePattern * 0.2 * (0.5 + midsVal);

  // === RESONANCE CASCADE on onset ===
  float cascade = onsetFlash * exp(-length(p) * 2.0) * 0.3;
  col += vec3(1.0, 0.9, 0.7) * cascade;

  // Overall intensity
  col *= uIntensity * 1.2;

  // Beat brightness pulse
  col *= 1.0 + beatPulse * 0.15;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSpinRate;
uniform float uGrooveDepth;
uniform float uDiffractionStrength;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

void main() {
  vec2 p = (vUv - 0.5) * (2.0 + uZoom * 2.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 0.5;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float kickPulse = uKick * uSensitivity;

  // Record spinning
  float spin = time * uSpinRate * 2.0 * (1.0 + bassVal * 0.3);
  float ca = cos(spin);
  float sa = sin(spin);
  vec2 rotP = vec2(p.x * ca - p.y * sa, p.x * sa + p.y * ca);

  float r = length(rotP);
  float angle = atan(rotP.y, rotP.x);

  // Record body (circular disc)
  float discEdge = smoothstep(0.95, 0.93, r);
  float labelEdge = smoothstep(0.15, 0.17, r); // Center label hole

  // Vinyl base color (near-black)
  vec3 vinylColor = vec3(0.03, 0.03, 0.04);

  // Groove pattern (concentric rings)
  float grooveFreq = 200.0 + uGrooveDepth * 200.0;
  float groove = sin(r * grooveFreq) * 0.5 + 0.5;
  groove = pow(groove, 0.5);

  // Audio data encoded in grooves (wobble)
  float audioWobble = sin(angle * 3.0 + r * 50.0) * midsVal * 0.02;
  audioWobble += sin(angle * 7.0 + r * 80.0) * trebleVal * 0.01;
  groove += audioWobble * uGrooveDepth;

  // Groove lighting (subtle highlights on ridge edges)
  float grooveHighlight = pow(abs(cos(r * grooveFreq)), 8.0) * uGrooveDepth * 0.3;
  grooveHighlight *= (1.0 + midsVal * 0.5);

  // Rainbow diffraction from grooves
  float diffAngle = angle + spin; // viewing angle relative to light
  float diffraction = sin(r * grooveFreq * 0.5 + diffAngle * 2.0) * 0.5 + 0.5;
  float diffStrength = uDiffractionStrength * (0.6 + trebleVal * 0.6);
  // Rainbow: map to hue
  float diffHue = fract(r * 5.0 + diffAngle * 0.5 + uPalette * 0.3);
  vec3 rainbowColor = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + diffHue));
  vec3 diffractionColor = rainbowColor * diffraction * diffStrength * 0.3;

  // Light source reflection (specular spot that sweeps across)
  vec2 lightDir = vec2(cos(time * 0.5), sin(time * 0.5));
  float specAngle = dot(normalize(rotP + 0.001), lightDir);
  float specular = pow(max(0.0, specAngle), 20.0) * 0.4;
  specular *= smoothstep(0.15, 0.3, r) * discEdge; // Not on label

  // Stylus / needle position
  float stylusAngle = -time * uSpinRate * 2.0 * (1.0 + bassVal * 0.3); // counter-rotate to appear stationary
  vec2 stylusPos = vec2(cos(stylusAngle), sin(stylusAngle)) * (0.55 + sin(time * 0.1) * 0.15);
  float stylusDist = length(p - stylusPos);
  float stylusGlow = exp(-stylusDist * stylusDist * 200.0) * 0.8;
  stylusGlow *= (1.0 + beatPulse * 1.0);
  vec3 stylusColor = vec3(1.0, 0.95, 0.8) * stylusGlow;

  // Stylus light cone (beam from stylus creating local diffraction)
  float stylusCone = exp(-stylusDist * 3.0) * 0.2;
  diffractionColor += rainbowColor * stylusCone * diffStrength * 0.5;

  // Center label
  float labelMask = 1.0 - labelEdge;
  vec3 labelColor = vec3(0.0);
  if (labelMask > 0.0) {
    // Colored label
    float labelHue = fract(uPalette * 0.5);
    labelColor = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.33, 0.67) + labelHue));
    labelColor *= 0.6;
    // Label text rings
    float labelRing = smoothstep(0.005, 0.0, abs(r - 0.1));
    labelRing += smoothstep(0.005, 0.0, abs(r - 0.06));
    labelColor += vec3(0.3) * labelRing;
    // Center spindle hole
    float spindleHole = smoothstep(0.02, 0.015, r);
    labelColor *= (1.0 - spindleHole);
  }

  // Combine
  vec3 col = vinylColor;
  col += vec3(grooveHighlight) * 0.5;
  col += diffractionColor;
  col += vec3(specular);

  // Apply disc and label masks
  col *= discEdge * labelEdge;
  col += labelColor * labelMask * discEdge;
  col += stylusColor;

  // Edge bevel highlight
  float edgeHighlight = smoothstep(0.93, 0.94, r) * smoothstep(0.96, 0.94, r);
  col += vec3(0.15) * edgeHighlight;

  // Turntable surface outside disc
  float outsideDisc = 1.0 - discEdge;
  col += vec3(0.08, 0.08, 0.1) * outsideDisc;

  // Beat pulse
  col += vec3(0.05, 0.04, 0.06) * beatPulse * 0.2;

  // Chaos adds noise to grooves
  col += vec3(noise(rotP * 100.0)) * uChaos * 0.02 * discEdge;

  // Energy and intensity
  col *= (0.7 + uEnergy * uSensitivity * 0.4);
  col *= uIntensity * 1.2;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSurfaceTension;
uniform float uShockStrength;
uniform float uColorSaturation;
uniform float uFlowScale;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}

float fbm(vec2 p, int octaves) {
  float v = 0.0, a = 0.5;
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    v += a * noise(p);
    p = rot * p * 2.0;
    a *= 0.5;
  }
  return v;
}

vec2 curlNoise(vec2 p, float visc) {
  float eps = 0.01 * (1.0 + visc * 2.0);
  float n1 = fbm(p + vec2(0.0, eps), 5);
  float n2 = fbm(p - vec2(0.0, eps), 5);
  float n3 = fbm(p + vec2(eps, 0.0), 5);
  float n4 = fbm(p - vec2(eps, 0.0), 5);
  return vec2(n1 - n2, n4 - n3) / (2.0 * eps);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.4;
  float breathe = 1.0 + sin(uTime * 0.35) * 0.07;
  p *= breathe;

  float centroidVal = uSpectralCentroid * uSensitivity;
  float viscosity = mix(5.0, 0.2, clamp(centroidVal, 0.0, 1.0));
  float tension = uSpectralFlatness * uSensitivity * uSurfaceTension;
  float kickShock = uKick * uSensitivity * uShockStrength;

  float flowSpeed = 1.0 / viscosity;
  vec2 flowP = p * uFlowScale * 3.0;

  vec2 curl = curlNoise(flowP + time * 0.1 * flowSpeed, viscosity * 0.1);
  flowP += curl * 0.3 * flowSpeed;

  float shock = kickShock * exp(-length(p) * 2.0);
  flowP += normalize(p + 0.001) * shock * 0.5;

  flowP += vec2(sin(time * 0.2), cos(time * 0.15)) * 0.3 * flowSpeed;

  int oct = int(mix(3.0, 7.0, tension));
  float fluid = fbm(flowP + time * 0.05 * flowSpeed, oct);
  float detail = fbm(flowP * 2.0 - time * 0.08 * flowSpeed + vec2(5.0), oct);

  float pattern = fluid * 0.6 + detail * 0.4;
  pattern += uChaos * noise(flowP * 8.0 + time * 0.3) * 0.2;

  vec3 honey = vec3(0.95, 0.65, 0.15);
  vec3 amber = vec3(0.8, 0.5, 0.08);
  vec3 water = vec3(0.35, 0.7, 0.95);
  vec3 clear = vec3(0.75, 0.9, 1.0);

  vec3 thickCol = mix(amber, honey, pattern);
  vec3 thinCol = mix(water, clear, pattern);
  vec3 col = mix(thickCol, thinCol, clamp(centroidVal, 0.0, 1.0));

  col *= uColorSaturation + (1.0 - uColorSaturation) * 0.5;

  float paletteShift = uPalette * 0.5;
  col = mix(col, col * (0.6 + 0.4 * cos(vec3(0.0, 0.3, 0.7) + paletteShift * 6.28)), 0.2);

  float highlight = pow(pattern, 3.0) * mix(0.3, 1.0, 1.0 / viscosity);
  col += vec3(1.0, 0.95, 0.85) * highlight;

  float edgeFlow = length(curl) * 0.5;
  col += vec3(0.3, 0.2, 0.1) * edgeFlow * (1.0 - centroidVal);
  col += vec3(0.1, 0.2, 0.4) * edgeFlow * centroidVal;

  col *= 1.0 + uEnergy * uSensitivity * 0.3;
  col += vec3(0.1) * uOnset * uSensitivity;
  col *= 1.0 + bass() * uSensitivity * 0.35;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCellCount;
uniform float uEdgeGlow;
uniform float uMorphSpeed;
uniform float uVoidDepth;

// Discrete 6-color jewel-tone palette
vec3 discretePalette(float index, float paletteShift) {
  float shifted = fract(index + paletteShift);
  float slot = floor(shifted * 6.0);

  float r = step(slot, 1.5) + step(4.5, slot);
  float g = step(0.5, slot) * step(slot, 3.5);
  float b = step(2.5, slot);

  return vec3(clamp(r, 0.0, 1.0), clamp(g, 0.0, 1.0), clamp(b, 0.0, 1.0));
}

// HSV to RGB conversion
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p2 = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p2 - K.xxx, 0.0, 1.0), c.y);
}

// RGB to HSV conversion
vec3 rgb2hsv(vec3 c) {
  vec4 K2 = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p3 = mix(vec4(c.bg, K2.wz), vec4(c.gb, K2.xy), step(c.b, c.g));
  vec4 q2 = mix(vec4(p3.xyw, c.r), vec4(c.r, p3.yzx), step(p3.x, c.r));
  float d2 = q2.x - min(q2.w, q2.y);
  float e2 = 1.0e-10;
  return vec3(abs(q2.z + (q2.w - q2.y) / (6.0 * d2 + e2)), d2 / (q2.x + e2), q2.x);
}

void main() {
  vec2 _psychUv = psychedelicUV(vUv); // breathing morph
  float time = uTime * (uSpeed * 2.0);
  float morphTime = time * uMorphSpeed;
  float bassVal0 = bass() * uSensitivity;

  // --- Organic UV warping (mescaline distortion) ---
  vec2 rawUv = vUv - 0.5;
  // Multi-frequency sinusoidal warping for organic feel
  float warpStr = 0.03 + uChaos * 0.04 + bassVal0 * 0.02;
  float wx = rawUv.x + sin(rawUv.y * 8.0 + time * 0.7) * warpStr
           + cos(rawUv.y * 13.0 - time * 0.5) * warpStr * 0.5
           + sin(rawUv.x * 5.0 + rawUv.y * 7.0 + time * 0.3) * warpStr * 0.3;
  float wy = rawUv.y + cos(rawUv.x * 9.0 - time * 0.6) * warpStr
           + sin(rawUv.x * 11.0 + time * 0.4) * warpStr * 0.5
           + cos(rawUv.x * 6.0 - rawUv.y * 8.0 + time * 0.35) * warpStr * 0.3;
  // Breathing / pulsing distortion
  float breathe = sin(time * 0.5) * 0.02 + sin(time * 0.8) * 0.01;
  float pulseDist = sqrt(wx * wx + wy * wy);
  wx *= 1.0 + breathe * sin(pulseDist * 10.0 - time * 1.2);
  wy *= 1.0 + breathe * cos(pulseDist * 10.0 - time * 1.2);

  vec2 scaledUv = vec2(wx, wy) * (uZoom * 4.0 + 1.0);
  vec2 cellUv = scaledUv * uCellCount;

  // Fractional position within the current cell
  float cellX = fract(cellUv.x) - 0.5;
  float cellY = fract(cellUv.y) - 0.5;

  // Base integer cell coordinates
  float baseIx = cellUv.x - cellX - 0.5;
  float baseIy = cellUv.y - cellY - 0.5;

  // --- 3x3 Voronoi neighborhood scan ---

  // Neighbor (-1, -1)
  float ix00 = baseIx - 1.0;
  float iy00 = baseIy - 1.0;
  float h00 = fract(sin(ix00 * 127.1 + iy00 * 311.7) * 43758.5453);
  float h00b = fract(sin(ix00 * 269.5 + iy00 * 183.3) * 43758.5453);
  float px00 = cos(morphTime + h00 * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float py00 = sin(morphTime * 1.3 + h00b * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float dx00 = cellX - px00;
  float dy00 = cellY - py00;
  float d00 = dx00 * dx00 + dy00 * dy00;

  // Neighbor (-1, 0)
  float ix01 = baseIx - 1.0;
  float iy01 = baseIy;
  float h01 = fract(sin(ix01 * 127.1 + iy01 * 311.7) * 43758.5453);
  float h01b = fract(sin(ix01 * 269.5 + iy01 * 183.3) * 43758.5453);
  float px01 = cos(morphTime + h01 * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float py01 = sin(morphTime * 1.3 + h01b * 6.2831) * 0.5 * (uChaos + 0.3);
  float dx01 = cellX - px01;
  float dy01 = cellY - py01;
  float d01 = dx01 * dx01 + dy01 * dy01;

  // Neighbor (-1, +1)
  float ix02 = baseIx - 1.0;
  float iy02 = baseIy + 1.0;
  float h02 = fract(sin(ix02 * 127.1 + iy02 * 311.7) * 43758.5453);
  float h02b = fract(sin(ix02 * 269.5 + iy02 * 183.3) * 43758.5453);
  float px02 = cos(morphTime + h02 * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float py02 = sin(morphTime * 1.3 + h02b * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float dx02 = cellX - px02;
  float dy02 = cellY - py02;
  float d02 = dx02 * dx02 + dy02 * dy02;

  // Neighbor (0, -1)
  float ix10 = baseIx;
  float iy10 = baseIy - 1.0;
  float h10 = fract(sin(ix10 * 127.1 + iy10 * 311.7) * 43758.5453);
  float h10b = fract(sin(ix10 * 269.5 + iy10 * 183.3) * 43758.5453);
  float px10 = cos(morphTime + h10 * 6.2831) * 0.5 * (uChaos + 0.3);
  float py10 = sin(morphTime * 1.3 + h10b * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float dx10 = cellX - px10;
  float dy10 = cellY - py10;
  float d10 = dx10 * dx10 + dy10 * dy10;

  // Neighbor (0, 0) -- center cell
  float ix11 = baseIx;
  float iy11 = baseIy;
  float h11 = fract(sin(ix11 * 127.1 + iy11 * 311.7) * 43758.5453);
  float h11b = fract(sin(ix11 * 269.5 + iy11 * 183.3) * 43758.5453);
  float px11 = cos(morphTime + h11 * 6.2831) * 0.5 * (uChaos + 0.3);
  float py11 = sin(morphTime * 1.3 + h11b * 6.2831) * 0.5 * (uChaos + 0.3);
  float dx11 = cellX - px11;
  float dy11 = cellY - py11;
  float d11 = dx11 * dx11 + dy11 * dy11;

  // Neighbor (0, +1)
  float ix12 = baseIx;
  float iy12 = baseIy + 1.0;
  float h12 = fract(sin(ix12 * 127.1 + iy12 * 311.7) * 43758.5453);
  float h12b = fract(sin(ix12 * 269.5 + iy12 * 183.3) * 43758.5453);
  float px12 = cos(morphTime + h12 * 6.2831) * 0.5 * (uChaos + 0.3);
  float py12 = sin(morphTime * 1.3 + h12b * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float dx12 = cellX - px12;
  float dy12 = cellY - py12;
  float d12 = dx12 * dx12 + dy12 * dy12;

  // Neighbor (+1, -1)
  float ix20 = baseIx + 1.0;
  float iy20 = baseIy - 1.0;
  float h20 = fract(sin(ix20 * 127.1 + iy20 * 311.7) * 43758.5453);
  float h20b = fract(sin(ix20 * 269.5 + iy20 * 183.3) * 43758.5453);
  float px20 = cos(morphTime + h20 * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float py20 = sin(morphTime * 1.3 + h20b * 6.2831) * 0.5 * (uChaos + 0.3) + (-1.0);
  float dx20 = cellX - px20;
  float dy20 = cellY - py20;
  float d20 = dx20 * dx20 + dy20 * dy20;

  // Neighbor (+1, 0)
  float ix21 = baseIx + 1.0;
  float iy21 = baseIy;
  float h21 = fract(sin(ix21 * 127.1 + iy21 * 311.7) * 43758.5453);
  float h21b = fract(sin(ix21 * 269.5 + iy21 * 183.3) * 43758.5453);
  float px21 = cos(morphTime + h21 * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float py21 = sin(morphTime * 1.3 + h21b * 6.2831) * 0.5 * (uChaos + 0.3);
  float dx21 = cellX - px21;
  float dy21 = cellY - py21;
  float d21 = dx21 * dx21 + dy21 * dy21;

  // Neighbor (+1, +1)
  float ix22 = baseIx + 1.0;
  float iy22 = baseIy + 1.0;
  float h22 = fract(sin(ix22 * 127.1 + iy22 * 311.7) * 43758.5453);
  float h22b = fract(sin(ix22 * 269.5 + iy22 * 183.3) * 43758.5453);
  float px22 = cos(morphTime + h22 * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float py22 = sin(morphTime * 1.3 + h22b * 6.2831) * 0.5 * (uChaos + 0.3) + 1.0;
  float dx22 = cellX - px22;
  float dy22 = cellY - py22;
  float d22 = dx22 * dx22 + dy22 * dy22;

  // --- Find nearest cell via pairwise min ---
  float sel01 = step(0.0, d00 - d01);
  float min01 = mix(d00, d01, sel01);
  float id01 = mix(h00, h01, sel01);

  float sel02 = step(0.0, min01 - d02);
  float min02 = mix(min01, d02, sel02);
  float id02 = mix(id01, h02, sel02);

  float sel10 = step(0.0, min02 - d10);
  float min10 = mix(min02, d10, sel10);
  float id10 = mix(id02, h10, sel10);

  float sel11 = step(0.0, min10 - d11);
  float min11 = mix(min10, d11, sel11);
  float id11 = mix(id10, h11, sel11);

  float sel12 = step(0.0, min11 - d12);
  float min12 = mix(min11, d12, sel12);
  float id12 = mix(id11, h12, sel12);

  float sel20 = step(0.0, min12 - d20);
  float min20 = mix(min12, d20, sel20);
  float id20 = mix(id12, h20, sel20);

  float sel21 = step(0.0, min20 - d21);
  float min21 = mix(min20, d21, sel21);
  float id21 = mix(id20, h21, sel21);

  float sel22 = step(0.0, min21 - d22);
  float minDist = mix(min21, d22, sel22);
  float cellId = mix(id21, h22, sel22);

  // --- Coloring ---
  float distNorm = minDist * 4.0;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float midsGlow = mids() * uSensitivity * 0.5;
  float edgeWidth = uEdgeGlow + midsGlow;

  float bassGlow = bassVal * 0.4;

  float beatCollapse = uBeat * uSensitivity * 0.3;
  float collapsedEdge = smoothstep(0.0, edgeWidth + beatCollapse, distNorm);

  // Discrete color from cellId hash
  float colorIndex = floor(cellId * 6.0) / 6.0;

  // Cell flip-flop
  float flipRate = uSpeed + 0.5;
  float flipToggle = step(0.5, fract(time * flipRate * 0.3 + cellId * 3.7));

  float complementaryOffset = flipToggle * 0.5;
  float paletteRotation = uPalette * 0.1;
  float finalIndex = fract(colorIndex + complementaryOffset);

  vec3 cellColor = discretePalette(finalIndex, paletteRotation);

  // Brightness from audio
  float energyBloom = uEnergy * uSensitivity * 0.5;
  float bloomBrightness = uIntensity * 1.5 + energyBloom;

  float bassBrightness = 1.0 + bassGlow;

  float cellVal = mix(
    1.0 - uVoidDepth + beatCollapse,
    bloomBrightness,
    collapsedEdge
  );

  float brightness = clamp(cellVal * bassBrightness, 0.0, 1.0);
  vec3 litColor = vec3(
    cellColor.x * brightness,
    cellColor.y * brightness,
    cellColor.z * brightness
  );

  float glowStrength = collapsedEdge * bloomBrightness * 0.3;
  vec3 baseCol = litColor + vec3(glowStrength, glowStrength, glowStrength);

  // --- PLASMA LAYERS ---
  // Use original UV (not cell UV) for full-screen plasma
  vec2 plasmaUV = scaledUv;

  // Plasma layer 1: large slow waves
  float plasma1 = sin(plasmaUV.x * 4.0 + time * 0.8) * cos(plasmaUV.y * 3.0 - time * 0.7);
  plasma1 += sin(sqrt(plasmaUV.x * plasmaUV.x + plasmaUV.y * plasmaUV.y) * 5.0 - time * 1.2) * 0.5;

  // Plasma layer 2: medium rotating waves
  float plasma2 = sin(plasmaUV.x * 6.0 * cos(time * 0.3) + plasmaUV.y * 5.0 * sin(time * 0.2)) * 0.7;
  plasma2 += cos(plasmaUV.y * 7.0 + time * 0.9 + sin(plasmaUV.x * 3.0)) * 0.5;

  // Plasma layer 3: fine detail, fast
  float plasma3 = sin(plasmaUV.x * 10.0 - time * 1.5 + plasmaUV.y * 8.0) * 0.4;
  plasma3 += cos(plasmaUV.x * 8.0 + plasmaUV.y * 12.0 + time * 1.1) * 0.3;

  // Bass pulses plasma intensity, treble shifts speed
  float plasmaIntensity = 0.35 + bassVal * 0.3;
  float combinedPlasma = (plasma1 + plasma2 + plasma3) * plasmaIntensity;

  // --- COLOR CYCLING: rotating hue palette ---
  // Treble shifts color cycle speed
  float hueSpeed = 0.1 + trebleVal * 0.08;
  float hueBase = time * hueSpeed + combinedPlasma * 0.15 + uPalette * 0.25;

  // HSV-style cycling for vivid saturated colors
  float plasmaHue = fract(hueBase);
  float pr = abs(fract(plasmaHue + 1.0) * 6.0 - 3.0) - 1.0;
  float pg = abs(fract(plasmaHue + 0.6667) * 6.0 - 3.0) - 1.0;
  float pb = abs(fract(plasmaHue + 0.3333) * 6.0 - 3.0) - 1.0;
  // High saturation, vivid colors
  vec3 plasmaColor = vec3(
    clamp(pr, 0.0, 1.0) * 0.9 + 0.1,
    clamp(pg, 0.0, 1.0) * 0.85 + 0.1,
    clamp(pb, 0.0, 1.0) * 0.95 + 0.1
  );

  // Neon-hot accents: boost near plasma peaks
  float neonAccent = smoothstep(0.3, 0.8, combinedPlasma * 0.5 + 0.5) * 0.3;
  plasmaColor += vec3(neonAccent * 1.2, neonAccent * 0.4, neonAccent * 0.8);

  // Plasma overlay strength (modulated by plasma field itself)
  float plasmaStrength = clamp(combinedPlasma * 0.5 + 0.5, 0.0, 1.0) * 0.45;

  // Layer plasma ON TOP of existing voronoi bloom
  vec3 finalCol = mix(baseCol, baseCol + plasmaColor * plasmaStrength, plasmaStrength);
  // Boost overall saturation
  float lum = dot(finalCol, vec3(0.299, 0.587, 0.114));
  finalCol = mix(vec3(lum), finalCol, 1.6);

  // --- HSV hue rotation over time (psychedelic color cycling) ---
  vec3 hsvCol = rgb2hsv(finalCol);
  hsvCol.x = fract(hsvCol.x + time * 0.06 + uPalette * 0.15 + bassVal * 0.05);
  // Boost saturation for vivid psychedelic colors
  hsvCol.y = clamp(hsvCol.y * 1.3 + 0.15, 0.0, 1.0);
  // Organic pulsing brightness
  float orgPulse = sin(time * 0.7 + pulseDist * 6.0) * 0.08 + sin(time * 1.1) * 0.05;
  hsvCol.z = clamp(hsvCol.z + orgPulse + bassVal * 0.1, 0.0, 1.0);
  finalCol = hsv2rgb(hsvCol);

  // --- Psychedelic rainbow overlay from distance field ---
  float rainbowHue = fract(distNorm * 0.5 + time * 0.08 + cellId * 0.3);
  vec3 rainbow = hsv2rgb(vec3(rainbowHue, 0.9, 0.7));
  float rainbowMix = 0.15 + bassVal * 0.1;
  finalCol = mix(finalCol, rainbow, rainbowMix * (1.0 - collapsedEdge));

  // === PSYCHEDELIC ENHANCEMENT ===
  finalCol = psychedelicColor(finalCol);
  gl_FragColor = vec4(
    clamp(finalCol.x, 0.0, 1.0),
    clamp(finalCol.y, 0.0, 1.0),
    clamp(finalCol.z, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uCorridorWidth;
uniform float uRepeatLength;
uniform float uGlowIntensity;

// HSV to RGB for neon coloring
vec3 hsvToRgb(float h, float s, float v) {
  float r = abs(fract(h + 1.0) * 6.0 - 3.0) - 1.0;
  float g = abs(fract(h + 2.0 / 3.0) * 6.0 - 3.0) - 1.0;
  float b = abs(fract(h + 1.0 / 3.0) * 6.0 - 3.0) - 1.0;
  return vec3(
    mix(1.0, clamp(r, 0.0, 1.0), s) * v,
    mix(1.0, clamp(g, 0.0, 1.0), s) * v,
    mix(1.0, clamp(b, 0.0, 1.0), s) * v
  );
}

// Cross-section distance: morphs between square, circle, hexagon.
float crossSectionDist(float px, float py, float width, float morphT) {
  float squareDist = max(abs(px), abs(py)) - width;
  float circleDist = length(vec3(px, py, 0.0)) - width;
  float absPx = abs(px);
  float absPy = abs(py);
  float hexDist = max(absPx, absPx * 0.5 + absPy * 0.866025) - width;
  float roundedDist = mix(squareDist, circleDist, 0.4);

  float phase = fract(morphT * 4.0);
  float blend01 = mix(squareDist, circleDist, clamp(phase, 0.0, 1.0));
  float blend12 = mix(circleDist, hexDist, clamp(phase, 0.0, 1.0));
  float blend23 = mix(hexDist, roundedDist, clamp(phase, 0.0, 1.0));
  float blend30 = mix(roundedDist, squareDist, clamp(phase, 0.0, 1.0));

  float seg = morphT * 4.0;
  float result = mix(
    mix(blend01, blend12, clamp(seg - 0.5, 0.0, 1.0) * 2.0 * 0.5),
    mix(blend23, blend30, clamp(seg - 2.5, 0.0, 1.0) * 2.0 * 0.5),
    clamp((seg - 1.5) * 2.0, 0.0, 1.0) * 0.5
  );

  // Simplified: use the cascaded blend from the original
  result = mix(
    mix(blend01, blend12, clamp((seg - 0.5) * 2.0, 0.0, 1.0)),
    mix(blend23, blend30, clamp((seg - 2.5) * 2.0, 0.0, 1.0)),
    clamp((seg - 1.5) * 2.0, 0.0, 1.0)
  );

  return result;
}

// Arch distance: morphs between semicircular, Gothic pointed, flat, ogee.
float archDist(float px, float archY, float archRepZ, float width, float archMorphT) {
  float semiR = width * 0.6;
  float semiDist = length(vec3(px, archY, archRepZ)) - semiR;

  float gothicOffset = width * 0.3;
  float gothicLeft = length(vec3(px + gothicOffset, archY, archRepZ)) - semiR * 1.1;
  float gothicRight = length(vec3(px - gothicOffset, archY, archRepZ)) - semiR * 1.1;
  float gothicDist = max(gothicLeft, gothicRight);

  float flatHeight = width * 0.15;
  float flatArch = max(abs(px) - width * 0.8, abs(archY) - flatHeight);
  float flatDist = min(flatArch, length(vec3(px, archY, archRepZ)) - width * 0.9);

  float ogeeUpper = length(vec3(px, archY - width * 0.2, archRepZ)) - semiR * 0.5;
  float ogeeLower = length(vec3(px, archY + width * 0.1, archRepZ)) - semiR * 0.9;
  float ogeeDist = min(ogeeUpper, ogeeLower);

  float seg = archMorphT * 4.0;
  float blendA = mix(
    mix(semiDist, gothicDist, clamp(seg, 0.0, 1.0)),
    mix(gothicDist, flatDist, clamp(seg - 1.0, 0.0, 1.0)),
    clamp((seg - 0.5) * 2.0, 0.0, 1.0)
  );
  float blendB = mix(
    mix(flatDist, ogeeDist, clamp(seg - 2.0, 0.0, 1.0)),
    mix(ogeeDist, semiDist, clamp(seg - 3.0, 0.0, 1.0)),
    clamp((seg - 2.5) * 2.0, 0.0, 1.0)
  );
  return mix(blendA, blendB, clamp((seg - 1.5) * 2.0, 0.0, 1.0));
}

// Corridor SDF: infinite repeating morphing corridor with evolving columns.
// Returns vec3(distance, wallDist, columnDist).
vec3 corridorSDF(vec3 pos, float bassVal, float midsVal, float trebleVal, float beatW, float time) {
  float px = pos.x;
  float py = pos.y;
  float pz = pos.z;

  // --- Domain warping: twist and warp the space ---
  // Distance from corridor center for twist amount
  float distFromCenter = sqrt(px * px + py * py);

  // Slow twist: rotate XY plane by angle that varies with Z and time
  float twistAngle = pz * 0.08 + sin(pz * 0.03 + time * 0.15) * 0.4 + time * 0.05;
  float cTw = cos(twistAngle);
  float sTw = sin(twistAngle);
  float twistedX = px * cTw - py * sTw;
  float twistedY = px * sTw + py * cTw;
  px = twistedX;
  py = twistedY;

  // Sinusoidal domain warp: offset XY by waves that vary with Z
  float warpAmt = 0.3 + midsVal * 0.2;
  px += sin(pz * 0.15 + time * 0.2) * warpAmt + sin(pz * 0.07 - time * 0.1) * (warpAmt * 0.5);
  py += cos(pz * 0.12 + time * 0.15) * warpAmt * 0.7 + cos(pz * 0.05 + time * 0.08) * (warpAmt * 0.4);

  // Width breathing
  float breathe = sin(time * 0.15) * 0.2 + sin(time * 0.07) * 0.1;
  float bassExpand = bassVal * 0.4;
  float width = uCorridorWidth + beatW * 0.3 + breathe + bassExpand;

  // Morphing cross-section with time-varying evolution
  float morphT = fract(time * 0.05 + sin(time * 0.02) * 0.3);

  // Undulating walls (slower spatial frequency for less repetition)
  float undulateAmp = midsVal * 0.35 + 0.05;
  float wave1 = sin(pz * 0.4 - time * 0.5) * undulateAmp;
  float wave2 = sin(pz * 0.8 + time * 0.3) * (undulateAmp * 0.5);
  float wave3 = sin(pz * 0.2 - time * 0.15 + px * 0.8) * (undulateAmp * 0.3);
  float undulation = wave1 + wave2 + wave3;

  float undulatedWidth = width + undulation;
  float wallDist = crossSectionDist(px, py, undulatedWidth, morphT);

  float warpedWall = wallDist + sin(pz * 0.5) * (bassVal * 0.2)
    + sin(pz * 2.0 + px * 1.5) * (trebleVal * 0.05);

  // Repeating columns along Z
  float repZ = (fract(pz / uRepeatLength + 0.5) - 0.5) * uRepeatLength;

  // Column morph cycle
  float colMorphT = fract(time * 0.06);

  // Column radius breathes with bass
  float colRadiusBase = 0.15;
  float colRadius = colRadiusBase + bassVal * 0.08 + sin(time * 0.5) * 0.03;

  // Column orbital offset
  float orbitAngle = time * 0.2 + pz * 0.1;
  float orbitRadius = 0.12 * (sin(time * 0.1) * 0.5 + 0.5);
  float orbitX = cos(orbitAngle) * orbitRadius;
  float orbitY = sin(orbitAngle) * orbitRadius;

  // Base column positions at corners with orbital drift
  float c1x = width * 0.8 + orbitX;
  float c1y = width * 0.8 + orbitY;
  float c2x = width * -0.8 - orbitX;
  float c2y = width * 0.8 + orbitY;
  float c3x = width * 0.8 + orbitX;
  float c3y = width * -0.8 - orbitY;
  float c4x = width * -0.8 - orbitX;
  float c4y = width * -0.8 - orbitY;

  // Round pillar SDF
  float roundCol1 = length(vec3(px - c1x, py - c1y, repZ)) - colRadius;
  float roundCol2 = length(vec3(px - c2x, py - c2y, repZ)) - colRadius;
  float roundCol3 = length(vec3(px - c3x, py - c3y, repZ)) - colRadius;
  float roundCol4 = length(vec3(px - c4x, py - c4y, repZ)) - colRadius;
  float roundColDist = min(min(roundCol1, roundCol2), min(roundCol3, roundCol4));

  // Twisted spiral columns
  float twistRate = 3.0 + sin(time * 0.3) * 1.5;
  float twistAngle1 = py * twistRate + time * 0.5;
  float twist1dx = (px - c1x) * cos(twistAngle1) - repZ * sin(twistAngle1);
  float twist1dz = (px - c1x) * sin(twistAngle1) + repZ * cos(twistAngle1);
  float twistedCol1 = length(vec3(twist1dx, py - c1y, twist1dz)) - colRadius * 0.8;

  float twistAngle2 = py * twistRate + time * 0.5;
  float twist2dx = (px - c2x) * cos(twistAngle2) - repZ * sin(twistAngle2);
  float twist2dz = (px - c2x) * sin(twistAngle2) + repZ * cos(twistAngle2);
  float twistedCol2 = length(vec3(twist2dx, py - c2y, twist2dz)) - colRadius * 0.8;

  float twistAngle3 = py * twistRate + time * 0.5;
  float twist3dx = (px - c3x) * cos(twistAngle3) - repZ * sin(twistAngle3);
  float twist3dz = (px - c3x) * sin(twistAngle3) + repZ * cos(twistAngle3);
  float twistedCol3 = length(vec3(twist3dx, py - c3y, twist3dz)) - colRadius * 0.8;

  float twistAngle4 = py * twistRate + time * 0.5;
  float twist4dx = (px - c4x) * cos(twistAngle4) - repZ * sin(twistAngle4);
  float twist4dz = (px - c4x) * sin(twistAngle4) + repZ * cos(twistAngle4);
  float twistedCol4 = length(vec3(twist4dx, py - c4y, twist4dz)) - colRadius * 0.8;
  float twistedColDist = min(min(twistedCol1, twistedCol2), min(twistedCol3, twistedCol4));

  // Crystalline prism columns (hexagonal cross-section)
  float prismCol1dx = abs(px - c1x);
  float prismCol1dz = abs(repZ);
  float prismCol1 = max(prismCol1dx, prismCol1dx * 0.5 + prismCol1dz * 0.866025) - colRadius * 1.1;
  float prismCol1Full = max(prismCol1, abs(py - c1y) - width * 0.9);

  float prismCol2dx = abs(px - c2x);
  float prismCol2dz = abs(repZ);
  float prismCol2 = max(prismCol2dx, prismCol2dx * 0.5 + prismCol2dz * 0.866025) - colRadius * 1.1;
  float prismCol2Full = max(prismCol2, abs(py - c2y) - width * 0.9);

  float prismCol3dx = abs(px - c3x);
  float prismCol3dz = abs(repZ);
  float prismCol3 = max(prismCol3dx, prismCol3dx * 0.5 + prismCol3dz * 0.866025) - colRadius * 1.1;
  float prismCol3Full = max(prismCol3, abs(py - c3y) - width * 0.9);

  float prismCol4dx = abs(px - c4x);
  float prismCol4dz = abs(repZ);
  float prismCol4 = max(prismCol4dx, prismCol4dx * 0.5 + prismCol4dz * 0.866025) - colRadius * 1.1;
  float prismCol4Full = max(prismCol4, abs(py - c4y) - width * 0.9);
  float prismColDist = min(min(prismCol1Full, prismCol2Full), min(prismCol3Full, prismCol4Full));

  // Blend between column shapes
  float colSeg = colMorphT * 3.0;
  float colBlendA = mix(roundColDist, twistedColDist, clamp(colSeg, 0.0, 1.0));
  float colBlendB = mix(twistedColDist, prismColDist, clamp(colSeg - 1.0, 0.0, 1.0));
  float colBlendC = mix(prismColDist, roundColDist, clamp(colSeg - 2.0, 0.0, 1.0));
  float columnDist = mix(
    mix(colBlendA, colBlendB, clamp((colSeg - 0.5) * 2.0, 0.0, 1.0)),
    colBlendC,
    clamp((colSeg - 1.5) * 2.0, 0.0, 1.0)
  );

  // Arch evolution
  float archRepZ = repZ;
  float archY = py - width * 0.5;
  float archMorphT = fract(time * 0.05);
  float archD = archDist(px, archY, archRepZ, width, archMorphT);

  // Combine
  float corridorInside = -warpedWall;
  float structures = min(columnDist, archD);

  return vec3(min(corridorInside, structures), abs(warpedWall), columnDist);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * (uSpeed * 2.0);
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onset = uOnset * uSensitivity;
  float kick = uKick * uSensitivity;

  // Camera: fly forward through the corridor
  float camZ = time * 1.5;
  float camX = sin(time * 0.2) * 0.3 + sin(time * 0.07) * (uChaos * 0.5);
  float camY = cos(time * 0.15) * 0.2;
  vec3 ro = vec3(camX, camY, camZ);

  // Ray direction
  float fov = (uZoom + 0.5) * 1.3;
  float swayX = sin(time * 0.1) * 0.05;
  float swayY = cos(time * 0.12) * 0.03;
  vec3 rd = normalize(vec3(p.x * fov + swayX, p.y * fov + swayY, 1.0));

  // Sphere trace: 30 steps (3 x 10)
  float t = 0.01;
  float wallGlow = 0.0;
  float colGlow = 0.0;
  float minDist = 100.0;

  for (int i = 0; i < 10; i++) {
    vec3 pos = ro + rd * t;
    vec3 result = corridorSDF(pos, bassVal, midsVal, trebleVal, beatPulse, time);
    float d = max(result.x, 0.001);
    minDist = min(minDist, d);
    wallGlow += 0.02 / (result.y + 0.1);
    colGlow += 0.01 / (result.z + 0.1);
    t += d * 0.6;
  }
  for (int i = 0; i < 10; i++) {
    vec3 pos = ro + rd * t;
    vec3 result = corridorSDF(pos, bassVal, midsVal, trebleVal, beatPulse, time);
    float d = max(result.x, 0.001);
    minDist = min(minDist, d);
    wallGlow += 0.02 / (result.y + 0.1);
    colGlow += 0.01 / (result.z + 0.1);
    t += d * 0.6;
  }
  for (int i = 0; i < 10; i++) {
    vec3 pos = ro + rd * t;
    vec3 result = corridorSDF(pos, bassVal, midsVal, trebleVal, beatPulse, time);
    float d = max(result.x, 0.001);
    minDist = min(minDist, d);
    wallGlow += 0.02 / (result.y + 0.1);
    colGlow += 0.01 / (result.z + 0.1);
    t += d * 0.6;
  }

  // Neon wall glow color
