  final3 = psychedelicColor(final3);
  gl_FragColor = vec4(
    clamp(final3.x, 0.0, 1.0),
    clamp(final3.y, 0.0, 1.0),
    clamp(final3.z, 0.0, 1.0),
    1.0
  );
}

