// Box SDF
float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// Rotation matrix around Y axis
mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Scene SDF: repeating monoliths in a grid
float sceneSDF(vec3 p, float time, float bassVal, float midsVal) {
  float spacing = 6.0;
  vec3 rep = vec3(spacing, 0.0, spacing);

  // Domain repetition
  vec3 q = p;
  q.xz = mod(q.xz + rep.xz * 0.5, rep.xz) - rep.xz * 0.5;

  // Unique ID per cell for variation
  vec2 cellId = floor((p.xz + rep.xz * 0.5) / rep.xz);
  float cellHash = hash(vec3(cellId, 0.0));

  // Monolith dimensions: tall, thin pillars with variation
  float height = (3.0 + cellHash * 5.0) * uMonolithScale * (1.0 + bassVal * 0.3);
  float width = (0.4 + cellHash * 0.4) * uMonolithScale;
  float depth = (0.3 + fract(cellHash * 7.13) * 0.5) * uMonolithScale;

  // Slow rotation per monolith
  float rotAngle = time * uDriftSpeed * (0.5 + cellHash * 0.5) + cellHash * 6.283;
  rotAngle += midsVal * 0.5;
  q.xz *= rot2(rotAngle);

  // Vertical drift
  float yOffset = sin(time * 0.2 + cellHash * 6.283) * 1.5;
  q.y -= yOffset;

  // Box SDF
  float d = sdBox(q, vec3(width, height, depth));

  // Slight chamfer on edges
  d -= 0.02;

