    vec3 pos = ro + rd * t;
    float d = sceneSDF(pos, time, bassVal, midsVal);
    minDist = min(minDist, d);
    if (d < 0.01) { hit = true; break; }
    t += d * 0.8;
    if (t > 60.0) break;
  }

