  vec3 col = vec3(0.0);

  if (hit) {
    vec3 hitPos = ro + rd * t;

    // Normal estimation via central differences
    float eps = 0.01;
    float nx = sceneSDF(hitPos + vec3(eps, 0.0, 0.0), time, bassVal, midsVal) -
               sceneSDF(hitPos - vec3(eps, 0.0, 0.0), time, bassVal, midsVal);
    float ny = sceneSDF(hitPos + vec3(0.0, eps, 0.0), time, bassVal, midsVal) -
               sceneSDF(hitPos - vec3(0.0, eps, 0.0), time, bassVal, midsVal);
    float nz = sceneSDF(hitPos + vec3(0.0, 0.0, eps), time, bassVal, midsVal) -
               sceneSDF(hitPos - vec3(0.0, 0.0, eps), time, bassVal, midsVal);
    vec3 normal = normalize(vec3(nx, ny, nz));

    // Concrete-like surface: monochromatic blue-gray
    float paletteShift = uPalette * 0.1;
    vec3 baseColor = vec3(0.06 + paletteShift * 0.02, 0.08 + paletteShift * 0.01, 0.14 + paletteShift * 0.03);

    // Surface grain
    float grain = hash(hitPos * 50.0) * 0.05;
    baseColor += grain;

    // Treble shimmer on surface
    float shimmer = trebleVal * 0.15 * sin(hitPos.y * 20.0 + time * 5.0);
    baseColor += shimmer;

    // Directional lighting: cold overhead light
    vec3 lightDir = normalize(vec3(0.3, 1.0, 0.5));
    float diff = max(dot(normal, lightDir), 0.0);
    float ambient = 0.15;
    float light = ambient + diff * 0.6;

    // Edge glow on kick
    float edgeFresnel = 1.0 - abs(dot(normal, -rd));
    float edgeGlow = pow(edgeFresnel, 3.0) * (0.3 + kickPulse * 1.5);
