float hash(vec3 p) {
  p = fract(p * 0.3183099 + 0.1);
  p *= 17.0;
  return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float noise3D(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);

  return mix(
    mix(mix(hash(i + vec3(0,0,0)), hash(i + vec3(1,0,0)), f.x),
        mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
    mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x),
        mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y),
    f.z
  );
}

float fbm3D(vec3 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise3D(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.5);
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Camera ray
  vec3 ro = vec3(0.0, 0.0, -2.0 + sin(time * 0.1) * 0.3);
  vec3 rd = normalize(vec3(p, 1.0));

  // Light sources (move with audio)
  vec3 light1 = vec3(
    sin(time * 0.3 + onsetVal * 3.0) * 1.5,
    cos(time * 0.2) * 0.8 + 0.5,
    1.0 + sin(time * 0.15) * 0.5
  );
  vec3 light2 = vec3(
    cos(time * 0.25) * 1.2,
    sin(time * 0.35) * 0.6 - 0.3,
    0.5 + cos(time * 0.2) * 0.3
  );

  // Raymarch through fog
  float density = uFogDensity * 1.5 + 0.3 + bassVal * 0.5;
  vec3 accColor = vec3(0.0);
  float accAlpha = 0.0;
  float stepSize = 0.08;
  int steps = 40;

  for (int i = 0; i < 40; i++) {
    float t = float(i) * stepSize;
    vec3 pos = ro + rd * t;

    // Fog density from 3D noise
    float fogNoise = fbm3D(pos * 1.5 + vec3(time * 0.1, time * 0.05, time * 0.08));
    fogNoise += uChaos * noise3D(pos * 3.0 + time * 0.3) * 0.3;
    float localDensity = max(0.0, fogNoise - (1.0 - density * 0.7)) * density;

    if (localDensity > 0.01) {
      // Light contribution from both sources
      vec3 toLight1 = light1 - pos;
      float dLight1 = length(toLight1);
      float atten1 = 1.0 / (1.0 + dLight1 * dLight1 * 0.5);

      vec3 toLight2 = light2 - pos;
      float dLight2 = length(toLight2);
      float atten2 = 1.0 / (1.0 + dLight2 * dLight2 * 0.7);

      // God ray: check if ray direction aligns with light direction (phase function)
      float phase1 = pow(max(0.0, dot(rd, normalize(toLight1))), 4.0);
      float phase2 = pow(max(0.0, dot(rd, normalize(toLight2))), 4.0);

      float lightContrib = (atten1 * (1.0 + phase1 * 3.0) + atten2 * (1.0 + phase2 * 2.0)) * uRayIntensity;

      // Beat pulses light intensity
      lightContrib *= 1.0 + beatPulse * 0.8 + kickVal * 0.5;

      // Scatter color: warm near light, cool at distance
      float warmth = mix(1.0, 0.0, uScatterColor) + midsVal * 0.2;
      vec3 warmCol = vec3(1.0, 0.7, 0.3);
      vec3 coolCol = vec3(0.3, 0.5, 1.0);
      vec3 scatterCol = mix(coolCol, warmCol, warmth * atten1);

      // Palette shift
      float hueRot = uPalette * 0.2;
