        scatterCol.r * cos(hueRot) - scatterCol.g * sin(hueRot),
        scatterCol.r * sin(hueRot) + scatterCol.g * cos(hueRot),
        scatterCol.b
      );

      vec3 fogCol = scatterCol * lightContrib;

      // Treble sparkle: bright point particles in fog
      float sparkle = step(0.97, noise3D(pos * 20.0 + time * 5.0)) * trebleVal * 3.0;
      fogCol += vec3(sparkle);

      // Accumulate with Beer-Lambert
      float alpha = 1.0 - exp(-localDensity * stepSize * 3.0);
      accColor += fogCol * alpha * (1.0 - accAlpha);
      accAlpha += alpha * (1.0 - accAlpha);
    }

    if (accAlpha > 0.95) break;
  }

  // Background: dark with subtle gradient
  vec3 bgCol = vec3(0.02, 0.02, 0.04) + vec3(0.01) * (1.0 - vUv.y);
  vec3 col = mix(bgCol, accColor, accAlpha);

  // Onset flash
  col += vec3(onsetVal * 0.2);

  // Energy vibrancy
  col *= 1.0 + energyVal * 0.2;

  float brightness = uIntensity * 1.3;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r * brightness, 0.0, 1.0),
    clamp(col.g * brightness, 0.0, 1.0),
    clamp(col.b * brightness, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uRippleSpeed;
uniform float uChromeSharpness;

// Simple 2D noise for surface detail
float hash21(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  fx = fx * fx * (3.0 - 2.0 * fx);
  fy = fy * fy * (3.0 - 2.0 * fy);
  float a = hash21(ix, iy);
  float b = hash21(ix + 1.0, iy);
  float c = hash21(ix, iy + 1.0);
  float d = hash21(ix + 1.0, iy + 1.0);
  return mix(mix(a, b, fx), mix(c, d, fx), fy);
}

// FBM for turbulent surface
float fbm(float x, float y, float t) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * noise2d(x * freq + t * 0.3 * freq, y * freq - t * 0.2 * freq);
    amp *= 0.5;
    freq *= 2.1;
  }
  return val;
}

// Compute surface height from layered waves
float surfaceHeight(float x, float y, float time, float bassV, float trebleV, float onsetV) {
  float h = 0.0;

  // Large slow waves
  h += sin(x * 3.0 + time * 0.7) * cos(y * 2.5 - time * 0.5) * 0.15;
  h += sin(x * 1.5 - y * 2.0 + time * 0.9) * 0.1;
  h += cos(x * 4.0 + y * 3.0 + time * 0.6) * 0.08;

  // Radial ripples from center (bass-driven)
  float dist = sqrt(x * x + y * y);
  h += sin(dist * 12.0 - time * 4.0) * bassV * 0.18;
  h += sin(dist * 18.0 - time * 6.0) * bassV * 0.1;

  // Fine perturbations (treble-driven)
  h += sin(x * 15.0 + time * 2.0) * sin(y * 12.0 - time * 1.5) * trebleV * 0.04;
  h += sin(x * 22.0 - time * 3.0) * cos(y * 20.0 + time * 2.5) * trebleV * 0.025;

  // Onset splash: sharp radial burst
  h += sin(dist * 25.0 - time * 8.0) * onsetV * 0.08 * exp(-dist * 2.0);

  // Turbulent noise
  h += (fbm(x * 2.0, y * 2.0, time * 0.5) - 0.5) * 0.1;

  return h;
}

// Cosine palette for environment
vec3 envPalette(float t, float shift) {
  return vec3(
    0.5 + 0.5 * cos(6.2832 * (t + 0.0 + shift)),
    0.5 + 0.5 * cos(6.2832 * (t + 0.33 + shift)),
    0.5 + 0.5 * cos(6.2832 * (t + 0.67 + shift))
  );
}

void main() {
  float time = uTime * (uSpeed * 2.8) * uRippleSpeed;
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Chaos warps position
  float cx = p.x + sin(p.y * 3.0 + time * 0.4) * uChaos * 0.1;
  float cy = p.y + cos(p.x * 2.5 - time * 0.3) * uChaos * 0.1;

  // === SURFACE NORMAL via finite differences ===
  float eps = 0.005;
  float hC = surfaceHeight(cx, cy, time, bassVal, trebleVal, onsetVal);
  float hR = surfaceHeight(cx + eps, cy, time, bassVal, trebleVal, onsetVal);
  float hU = surfaceHeight(cx, cy + eps, time, bassVal, trebleVal, onsetVal);

  float nx = (hC - hR) / eps;
  float ny = (hC - hU) / eps;
  // Normalize the normal vector (nz points up)
  float nLen = sqrt(nx * nx + ny * ny + 1.0);
  nx /= nLen;
  ny /= nLen;
  float nz = 1.0 / nLen;

  // === CHROME REFLECTION ===
  // View direction is straight down (0, 0, -1)
  // Reflect: r = v - 2*dot(v,n)*n, simplified for v=(0,0,-1)
  float rx = 2.0 * nz * nx;
  float ry = 2.0 * nz * ny;
  float rz = 2.0 * nz * nz - 1.0;

  // Chrome sharpness: pow on the reflection lookup to create sharper highlights
  float sharpness = 2.0 + uChromeSharpness * 8.0;

  // === PSYCHEDELIC ENVIRONMENT ===
  // Use reflected direction to look up procedural environment
  float envAngle = atan(ry, rx);
  float envDist = sqrt(rx * rx + ry * ry);

  // Swirling concentric rings + spiral
  float rings = sin(envDist * 8.0 + time * 1.5 + envAngle * 2.0) * 0.5 + 0.5;
  float spiral = sin(envAngle * 4.0 + envDist * 12.0 - time * 2.0) * 0.5 + 0.5;

  // Color from palette
  float paletteShift = uPalette * 0.25 + midsVal * 0.3;
  float envT = rings * 0.5 + spiral * 0.3 + envDist * 0.2 + time * 0.05;
  vec3 envCol = envPalette(envT, paletteShift);

  // Second layer for more complexity
  float rings2 = sin(envDist * 15.0 - time * 2.5 + envAngle * 3.0) * 0.5 + 0.5;
  vec3 envCol2 = envPalette(rings2 + time * 0.03, paletteShift + 0.5);
  envCol = mix(envCol, envCol2, 0.4);

  // Saturate the environment colors
  float envLum = dot(envCol, vec3(0.299, 0.587, 0.114));
  envCol = mix(vec3(envLum), envCol, 1.8);
  envCol = clamp(envCol, 0.0, 1.0);

  // === FRESNEL (glancing angle = brighter) ===
  float fresnel = 1.0 - nz;
  fresnel = fresnel * fresnel;
  fresnel = 0.3 + 0.7 * fresnel;

  // === METALLIC CHROME COLORING ===
  // Chrome reflects environment with metallic tint
  vec3 metalTint = vec3(0.9, 0.93, 0.97); // Brighter blue-silver
  vec3 chrome = envCol * metalTint * fresnel;

  // Specular highlights: sharp bright spots
  float spec = pow(max(nz, 0.0), sharpness * 4.0);
  chrome += spec * 0.3;

  // Height-based shading: darker in troughs, brighter on crests
  float heightShade = hC * 2.0 + 0.5;
  heightShade = clamp(heightShade, 0.3, 1.0);
  chrome *= heightShade;

  // === AUDIO-REACTIVE ADDITIONS ===
  // Bass: add warm radial glow
  float dist2 = sqrt(p.x * p.x + p.y * p.y);
  float bassGlow = bassVal * 0.15 * smoothstep(1.5, 0.0, dist2);
  chrome.r += bassGlow * 0.6;
  chrome.g += bassGlow * 0.3;
  chrome.b += bassGlow * 0.8;

  // Beat: brightness flash
  chrome += beatPulse * 0.12;

  // Energy ambient glow
  chrome += energyVal * 0.06;

  // Apply intensity
  chrome *= uIntensity * 1.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  chrome = psychedelicColor(chrome);
  gl_FragColor = vec4(
    clamp(chrome.r, 0.0, 1.0),
    clamp(chrome.g, 0.0, 1.0),
    clamp(chrome.b, 0.0, 1.0),
    1.0
  );
}

