  float streakLen = uStreakLength * warpSpeed;

  // Radial coordinates
  float r = length(p);
  float angle = atan(p.y, p.x);

  // Tunnel blue glow at edges
  float tunnelGlow = pow(r, 2.0) * uTunnelDepth;
  col += vec3(0.03, 0.06, 0.22) * tunnelGlow;

  // Star streaks — layered for depth
  float numStars = uStarDensity * 200.0;
  for (float layer = 0.0; layer < 4.0; layer++) {
    float layerDepth = 1.0 + layer * 0.5;
    float layerSpeed = warpSpeed * layerDepth;

    for (float i = 0.0; i < 50.0; i++) {
      if (i + layer * 50.0 >= numStars) break;
      float id = i + layer * 50.0;

      // Star position in polar coordinates
      float starAngle = hash21(vec2(id, 0.0)) * 6.2832;
      float starR = hash21(vec2(0.0, id));

      // Depth cycling
      float depth = fract(starR + time * layerSpeed * 0.2);
      float z = depth;

      // Project to screen
      float projR = (1.0 - z) * 1.5;
      vec2 starPos = vec2(cos(starAngle), sin(starAngle)) * projR;

      // Streak direction (radial from center)
      vec2 streakDir = normalize(starPos);
      float streakL = streakLen * (1.0 - z) * 0.3;

      // Distance from pixel to streak line
      vec2 toP = p - starPos;
      float along = dot(toP, streakDir);
      float perp = length(toP - streakDir * along);

      // Streak visibility
      float streak = 0.0;
      if (along > -streakL && along < 0.02) {
        streak = exp(-perp * (80.0 + z * 100.0));
        streak *= smoothstep(-streakL, -streakL * 0.5, along);
        streak *= (1.0 - z); // Closer = brighter
      }

      // Star point at end
      float starDist = length(p - starPos);
      float star = exp(-starDist * (60.0 + z * 80.0)) * (1.0 - z);

      // Color: white near, blue far
      vec3 starCol = mix(vec3(1.0, 0.95, 0.9), vec3(0.4, 0.6, 1.0), z);
      starCol = mix(starCol, vec3(0.65, 0.4, 1.0), uPalette * 0.3);

      // Chromatic shift with centroid
      starCol += vec3(0.3, 0.0, -0.15) * centroidVal * (1.0 - z);

      col += starCol * (streak * 0.5 + star * 0.3) / layerDepth;
    }
  }

  // Central bright point (destination)
  float centerGlow = exp(-r * 15.0) * (0.3 + energyVal * 0.6);
  col += vec3(0.9, 0.95, 1.0) * centerGlow;

  // Warp ring flash on kick
  float warpRing = exp(-abs(r - 0.5 - kickVal * 0.6) * 30.0) * kickVal;
  col += vec3(0.6, 0.8, 1.0) * warpRing * 1.0;

  // Chromatic aberration at edges during warp
  float aberration = r * warpSpeed * 0.02;
  col.r += col.r * aberration;
  col.b -= col.b * aberration * 0.5;

  // Bass pulse — space warping
  col += vec3(0.02, 0.04, 0.1) * bassVal * 2.0 * r;

  // Treble shimmer
  col += vec3(0.6, 0.7, 1.0) * trebleVal * 0.04;

  // BPM engine hum
  col += vec3(0.02, 0.03, 0.06) * max(bpmVal, 0.0) * 0.2;

  // Kick flash
  col = mix(col, col * 2.2 + vec3(0.08, 0.12, 0.22), kickVal * 0.6);

  col *= uIntensity * 1.4;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

