uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uTunnelRadius;
uniform float uRingDensity;
uniform float uWarpBurst;
uniform float uStreakLength;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

void main() {
  vec2 p = (vUv - 0.5) * 2.0 / uZoom;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed;

  float bassVal = bass() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float kickVal = uKick * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Tunnel coordinates
  float dist = length(p);
  float angle = atan(p.y, p.x);

  // Dynamic tunnel radius
  float radius = uTunnelRadius + bassVal * 0.2 - trebleVal * 0.1;
  radius = max(radius, 0.2);

  // Warp speed
  float baseSpeed = 1.0 + energyVal * 3.0;
  float warpSpeed = baseSpeed + kickVal * uWarpBurst;

  // Depth coordinate (infinite tunnel)
  float depth = 1.0 / (dist + 0.001);
  float tunnelZ = depth - time * warpSpeed;

  // Ring pattern
  float ringSpacing = 1.0 / uRingDensity;
  float ringPhase = fract(tunnelZ * uRingDensity + uBpmSin * 0.3);
  float ring = smoothstep(0.1, 0.0, abs(ringPhase - 0.5) - 0.4);

  // Tunnel wall
  float wallDist = abs(dist - radius * (1.0 / (depth * 0.3 + 1.0)));
  float wall = smoothstep(0.05, 0.0, wallDist);

  // Ring colors: neon blue/purple/white
  float ringIdx = floor(tunnelZ * uRingDensity);
  float hue = fract(ringIdx * 0.17 + uPalette * 0.3);
  vec3 neonBlue = vec3(0.1, 0.4, 1.0);
  vec3 neonPurple = vec3(0.6, 0.1, 1.0);
  vec3 neonWhite = vec3(0.9, 0.9, 1.0);
  vec3 ringCol;
  if (hue < 0.33) ringCol = mix(neonBlue, neonPurple, hue * 3.0);
  else if (hue < 0.66) ringCol = mix(neonPurple, neonWhite, (hue - 0.33) * 3.0);
  else ringCol = mix(neonWhite, neonBlue, (hue - 0.66) * 3.0);

  // Brightness fades with depth
  float depthFade = exp(-depth * 0.05);
  float brightness = ring * depthFade * (0.5 + kickVal * 0.5);

  vec3 col = vec3(0.0);

  // Tunnel rings
  col += ringCol * brightness;

  // Wall glow
  float wallGlow = exp(-abs(dist - 0.3) * 8.0) * depthFade;
  col += ringCol * wallGlow * 0.3 * ring;

  // Motion streaks (radial lines)
  float streaks = 0.0;
  float streakAngle = angle * 20.0;
  float streak = abs(sin(streakAngle)) * uStreakLength;
  streak *= depthFade * warpSpeed * 0.1;
  streaks = smoothstep(0.5, 1.0, streak) * 0.3;
  col += neonBlue * streaks * energyVal;

  // Center vanishing point glow
  float centerGlow = exp(-dist * 10.0) * (0.3 + warpSpeed * 0.1);
  col += neonWhite * centerGlow;

  // Radial light rays
  float rays = abs(sin(angle * 8.0 + time * 0.5));
  rays = pow(rays, 4.0) * exp(-dist * 3.0) * 0.2;
