  col += ringCol * uOnset * uSensitivity * 0.3 * exp(-dist * 5.0);
  col *= 1.0 + uSpectralFlux * uSensitivity * 0.2;
  col += col * uChaos * sin(tunnelZ * 20.0 + angle * 3.0) * 0.1;

  col *= uIntensity;
  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
