__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSourceCount;
uniform float uWaveFreq;
uniform float uDamping;
uniform float uPhaseSpeed;

vec3 wavePalette(float t, float offset) {
  return 0.5 + 0.5 * cos(6.2832 * (t + offset + vec3(0.0, 0.12, 0.24)));
}

vec2 sourceHash(float n) {
  return fract(sin(vec2(n * 127.1 + 1.0, n * 269.5 + 2.0)) * 43758.5453);
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 3.0 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  float numSources = min(uSourceCount, 10.0);

  // Accumulate wave displacement from all sources
  float totalWave = 0.0;
  float totalAmp = 0.0;

  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= numSources) break;

    // Source position drifts slowly
    vec2 basePos = sourceHash(i) * 1.6 - 0.8;
    vec2 drift = vec2(
      sin(time * 0.2 + i * 2.1) * 0.2,
      cos(time * 0.15 + i * 1.7) * 0.2
    );
    drift += vec2(sin(i * 3.0), cos(i * 2.0)) * uChaos * 0.15;
    vec2 sourcePos = basePos + drift;

    // Distance from pixel to source
    float dist = length(p - sourcePos);

    // Audio modulates amplitude per source
    float frac = i / numSources;
    float audioAmp = mix(bassVal, trebleVal, frac) * 0.3 + midsVal * 0.2;
    audioAmp += onsetVal * 0.3 * exp(-i * 0.3);
    float amp = 0.5 + audioAmp;

    // Concentric wave: sin(freq * dist - time * speed)
    float wavePhase = dist * uWaveFreq - time * uPhaseSpeed * 3.0;

    // Add unique phase offset per source
    wavePhase += i * 1.0;

    float wave = sin(wavePhase) * amp;

    // Damping with distance
    float damp = exp(-dist * uDamping * 2.0);
    wave *= damp;

    totalWave += wave;
    totalAmp += damp * amp;
  }

  // Normalize
  totalWave /= max(numSources * 0.5, 1.0);

  // Convert wave displacement to visual
  // Positive peaks are bright, negative peaks are dark, zero crossings are mid
  float brightness = totalWave * 0.5 + 0.5;

  // Map to color using palette
  float hue = brightness * 0.5 + time * 0.02 + uPalette * 0.1;
  vec3 color = wavePalette(hue, uPalette * 0.05);

  // Modulate brightness
  color *= brightness * 0.8 + 0.2;

  // Edge glow at wave peaks (where |wave| is high)
  float peakGlow = pow(abs(totalWave), 2.0) * 0.5;
  vec3 peakColor = wavePalette(hue + 0.2, uPalette * 0.05 + 0.1);
  color += peakColor * peakGlow;

  // Source point glow
  for (float i = 0.0; i < 10.0; i += 1.0) {
    if (i >= numSources) break;

    vec2 basePos = sourceHash(i) * 1.6 - 0.8;
    vec2 drift = vec2(
      sin(time * 0.2 + i * 2.1) * 0.2,
      cos(time * 0.15 + i * 1.7) * 0.2
    ) + vec2(sin(i * 3.0), cos(i * 2.0)) * uChaos * 0.15;
    vec2 sourcePos = basePos + drift;

    float dist = length(p - sourcePos);
    float sourceGlow = exp(-dist * 15.0);
    float sourceCore = exp(-dist * 40.0);

    float srcHue = i / numSources + uPalette * 0.1;
    vec3 srcColor = wavePalette(srcHue, uPalette * 0.05);

    color += srcColor * (sourceCore * 1.5 + sourceGlow * 0.3);
  }

  // Treble sparkle
  float sparkle = sin(p.x * 50.0 + time * 5.0) * sin(p.y * 50.0 - time * 4.5);
  sparkle = pow(max(sparkle, 0.0), 20.0);
  color += vec3(sparkle * trebleVal * 0.2);

  // Intensity and energy
  color *= uIntensity * 1.1 + uEnergy * uSensitivity * 0.3;

  // Beat flash
  color += vec3(uBeat * uSensitivity * 0.05);

  // Kick punch
  color = mix(color, color * 1.4, kickVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.15));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
