__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uGridDensity;
uniform float uLineWidth;
uniform float uPerspectiveDepth;

mat2 rot2(float a) {
  float c = cos(a), s = sin(a);
  return mat2(c, -s, s, c);
}

// Grid line function: returns brightness for a grid at given scale
float gridLine(vec2 p, float scale, float width) {
  vec2 g = abs(fract(p * scale) - 0.5);
  float line = min(g.x, g.y);
  return smoothstep(width, width * 0.3, line);
}

// Wireframe box: edges only
float wireBox(vec3 p, vec3 size, float lineW) {
  vec3 d = abs(p) - size;

  // Each edge is the intersection of two face planes
  float ex1 = max(abs(d.y + size.y), abs(d.z + size.z)); // edges along X
  float ex2 = max(abs(d.y + size.y), abs(d.z - size.z));
  float ex3 = max(abs(d.y - size.y), abs(d.z + size.z));
  float ex4 = max(abs(d.y - size.y), abs(d.z - size.z));

  float ey1 = max(abs(d.x + size.x), abs(d.z + size.z));
  float ey2 = max(abs(d.x + size.x), abs(d.z - size.z));
  float ey3 = max(abs(d.x - size.x), abs(d.z + size.z));
  float ey4 = max(abs(d.x - size.x), abs(d.z - size.z));

  float ez1 = max(abs(d.x + size.x), abs(d.y + size.y));
  float ez2 = max(abs(d.x + size.x), abs(d.y - size.y));
  float ez3 = max(abs(d.x - size.x), abs(d.y + size.y));
  float ez4 = max(abs(d.x - size.x), abs(d.y - size.y));

  float edges = min(min(min(ex1, ex2), min(ex3, ex4)),
                 min(min(min(ey1, ey2), min(ey3, ey4)),
                     min(min(ez1, ez2), min(ez3, ez4))));

  return smoothstep(lineW, lineW * 0.2, edges);
}

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 1.5;
  float bassVal = bass() * uSensitivity * 1.3;
  float midsVal = mids() * uSensitivity * 1.2;
  float trebleVal = treble() * uSensitivity * 1.2;
  float beatPulse = uBeat * uSensitivity * 1.3;
  float kickPulse = uKick * uSensitivity * 1.4;

  // Wireframe color: green -> cyan -> blue based on mids + palette
  float hueBase = 0.33 + midsVal * 0.15 + uPalette * 0.05; // green range
  vec3 wireColor = vec3(0.0);
  wireColor.r = max(0.0, sin(hueBase * 6.283) * 0.3);
  wireColor.g = 0.6 + midsVal * 0.3;
  wireColor.b = 0.3 + uPalette * 0.1 + midsVal * 0.2;

  float totalBrightness = 0.0;

  // === PERSPECTIVE GROUND GRID ===
  // Transform to perspective view
  float depth = uPerspectiveDepth;
  float horizon = 0.1;

  // Ground plane grid (looking down at angle)
  if (p.y < horizon) {
    float perspY = 1.0 / (horizon - p.y + 0.001) * depth * 0.5;
    float perspX = p.x * perspY;
    float perspZ = perspY + time * 3.0;

    // Primary grid
    float density = uGridDensity * (1.0 + trebleVal * 0.5);
    float lw = uLineWidth * (1.0 + bassVal * 0.5);
    float grid1 = gridLine(vec2(perspX, perspZ), density * 0.5, lw);

    // Sub-grid (treble detail)
    float grid2 = gridLine(vec2(perspX, perspZ), density * 2.0, lw * 0.5) * trebleVal * 0.5;

    // Fade with distance
    float distFade = exp(-perspY * 0.04);
    totalBrightness += (grid1 + grid2) * distFade;

    // Scanline effect along Z
    float scanline = smoothstep(0.48, 0.5, fract(perspZ * 0.3)) * 0.3;
    totalBrightness += scanline * distFade;
  }

  // === CEILING GRID (mirror of ground) ===
  if (p.y > -horizon) {
    float perspY = 1.0 / (p.y + horizon + 0.001) * depth * 0.5;
    float perspX = p.x * perspY;
    float perspZ = perspY + time * 3.0;

    float density = uGridDensity * 0.7;
    float lw = uLineWidth * 0.8;
    float grid1 = gridLine(vec2(perspX, perspZ), density * 0.5, lw);
    float distFade = exp(-perspY * 0.05);
    totalBrightness += grid1 * distFade * 0.5;
  }

  // === FLOATING WIREFRAME OBJECTS ===
  // Object 1: rotating cube
  vec3 objPos1 = vec3(p.x * 2.0 - sin(time * 0.3) * 0.8, p.y * 2.0 + 0.3, 2.0);
  objPos1.xy *= rot2(time * 0.4);
  objPos1.xz *= rot2(time * 0.3 + uChaos);
  float cube1 = wireBox(objPos1, vec3(0.4 + beatPulse * 0.15), uLineWidth * 3.0);
  totalBrightness += cube1 * 0.8;

  // Object 2: smaller cube orbiting
  float orbitAngle = time * 0.7;
  vec3 objPos2 = vec3(
    p.x * 2.0 - cos(orbitAngle) * 1.2,
    p.y * 2.0 - sin(orbitAngle) * 0.6,
    2.0
  );
  objPos2.xy *= rot2(time * -0.6);
  objPos2.yz *= rot2(time * 0.5);
  float cube2 = wireBox(objPos2, vec3(0.2 + bassVal * 0.1), uLineWidth * 2.5);
  totalBrightness += cube2 * 0.6;

  // Object 3: large background cube
  vec3 objPos3 = vec3(p.x * 3.0 + sin(time * 0.1) * 0.5, p.y * 3.0 + cos(time * 0.08) * 0.3, 4.0);
  objPos3.xy *= rot2(time * 0.15);
  objPos3.xz *= rot2(time * 0.12);
  float cube3 = wireBox(objPos3, vec3(0.8), uLineWidth * 2.0);
  totalBrightness += cube3 * 0.3;

  // === VERTICAL SCAN LINES ===
  float scanV = smoothstep(0.49, 0.5, fract(p.x * 20.0 + time * 0.5)) * 0.1;
  totalBrightness += scanV;

  // === HORIZONTAL SCANLINE SWEEP ===
  float sweep = smoothstep(0.01, 0.0, abs(p.y - fract(time * 0.2) * 2.0 + 1.0)) * 0.5;
  totalBrightness += sweep;

  // Apply wireframe color
  vec3 col = wireColor * totalBrightness;

  // Kick flash: bright white edges
  col += vec3(0.5, 0.8, 0.6) * kickPulse * totalBrightness * 0.5;

  // Beat scale pulse glow
  col += wireColor * 0.05 * beatPulse;

  // CRT-like vignette
  float vig = 1.0 - length(p * 0.7);
  col *= max(vig, 0.3);

  // Intensity
  col *= uIntensity * 1.8;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

