uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uSmokeDensity;
uniform float uCurlStrength;

// Hash function
float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(float x, float y) {
  return fract(sin(x * 127.1 + y * 311.7) * 43758.5453);
}

// 2D value noise
float noise2d(float x, float y) {
  float ix = floor(x);
  float iy = floor(y);
  float fx = fract(x);
  float fy = fract(y);
  fx = fx * fx * (3.0 - 2.0 * fx);
  fy = fy * fy * (3.0 - 2.0 * fy);
  float a = hash21(ix, iy);
  float b = hash21(ix + 1.0, iy);
  float c = hash21(ix, iy + 1.0);
  float d = hash21(ix + 1.0, iy + 1.0);
  return mix(mix(a, b, fx), mix(c, d, fx), fy);
}

// FBM for turbulence
float fbm(float x, float y) {
  float val = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    val += amp * noise2d(x * freq, y * freq);
    amp *= 0.5;
    freq *= 2.1;
  }
  return val;
}

// Cosine palette for tendril colors
vec3 tendrilPalette(float t, float shift) {
  return vec3(
    0.5 + 0.5 * cos(6.2832 * (0.8 * t + 0.0 + shift)),
    0.5 + 0.5 * cos(6.2832 * (0.8 * t + 0.33 + shift)),
    0.5 + 0.5 * cos(6.2832 * (0.8 * t + 0.67 + shift))
  );
}

// Compute a single smoke tendril's contribution
// Returns: vec4(r, g, b, intensity)
vec4 smokeTendril(
  float px, float py,
  float pathSeedA, float pathSeedB, float pathSeedC,
  float hueOffset, float time,
  float width, float curlAmt,
  float bassV, float trebleV, float beatV, float onsetV,
  float paletteShift
) {
  // Tendril path: sinusoidal curve
  float pathY = sin(px * pathSeedA + time * 0.8 + pathSeedC) * 0.3
    + sin(px * pathSeedB * 0.7 - time * 0.5) * 0.15
    + cos(px * pathSeedA * 0.3 + time * 0.3) * 0.1;

  // Curl displacement via noise
  float curlX = (fbm(px * 2.0 + pathSeedA * 10.0 + time * 0.4,
                      py * 2.0 + pathSeedB * 10.0) - 0.5) * curlAmt;
  float curlY = (fbm(px * 2.0 + pathSeedB * 10.0 - time * 0.3,
                      py * 2.0 + pathSeedA * 10.0 + time * 0.2) - 0.5) * curlAmt;

  float displPx = px + curlX;
  float displPy = py + curlY;

  // Distance from point to tendril path
  float perpDist = displPy - pathY - curlY * 0.5;

  // Tendril width (bass thickens)
  float tendrilWidth = width * (1.0 + bassV * 1.6);

  // Treble sharpens edges
  float edgeSharpness = mix(0.0, tendrilWidth * 0.3, trebleV * 0.5 + 0.5);
  float smokeIntensity = smoothstep(tendrilWidth, edgeSharpness, abs(perpDist));

  // Add wispy detail from noise
  float detail = noise2d(displPx * 8.0 + time * 0.5 + pathSeedC * 5.0,
                         displPy * 6.0 - time * 0.3);
  smokeIntensity *= 0.6 + detail * 0.6;

  // Dissipation at extremes (edges of screen)
  float dissipate = smoothstep(1.8, 0.8, abs(displPx));
  smokeIntensity *= dissipate;

  // Beat: flash this tendril brighter
  float beatFlash = beatV * step(0.7, hash11(pathSeedA * 7.0 + floor(time * 4.0)));
  smokeIntensity *= (1.0 + beatFlash * 4.0);

  // Onset: burst of extra width
  float onsetBurst = onsetV * 0.3;
  float burstIntensity = smoothstep(tendrilWidth + onsetBurst, edgeSharpness,
                                     abs(perpDist)) * onsetV;
  smokeIntensity += burstIntensity * 0.5;

  // Color for this tendril
  vec3 col = tendrilPalette(hueOffset + time * 0.02, paletteShift);
  // Saturate
  float colLum = dot(col, vec3(0.299, 0.587, 0.114));
  col = mix(vec3(colLum), col, 1.8);
  col = clamp(col, 0.0, 1.0);

  // Inner glow: brighter core
  float coreDist = abs(perpDist) / (tendrilWidth + 0.001);
  float coreGlow = exp(-coreDist * coreDist * 4.0);
  col += coreGlow * 0.2;

  return vec4(col * smokeIntensity, smokeIntensity);
}

void main() {
  float time = uTime * (uSpeed * 2.0);
  vec2 p = (vUv - 0.5) * (uZoom * 4.0 + 1.0);
  p = psychedelicUV(p); // breathing morph

  // Audio
  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float energyVal = uEnergy * uSensitivity;

  // Base width and curl from params
  float baseWidth = 0.06 + uSmokeDensity * 0.12;
  float curlAmt = uCurlStrength * 0.4 + uChaos * 0.2;

  float paletteShift = uPalette * 0.25 + midsVal * 0.2;

  // === DARK BACKGROUND ===
  vec3 bg = vec3(0.01, 0.01, 0.02);
  // Subtle ambient glow in center
  float centerDist = sqrt(p.x * p.x + p.y * p.y);
  bg += vec3(0.02, 0.01, 0.03) * smoothstep(1.5, 0.0, centerDist);

  vec3 col = bg;

  // === TENDRIL 1: Blue-purple, sweeping left to right ===
  vec4 t1 = smokeTendril(p.x, p.y,
    2.3, 1.7, 0.0, 0.0, time,
    baseWidth, curlAmt,
    bassVal, trebleVal, beatPulse, onsetVal, paletteShift);
  col += t1.rgb * t1.a;

  // === TENDRIL 2: Cyan-green, opposite phase ===
  vec4 t2 = smokeTendril(p.x, p.y,
    1.8, 2.4, 1.5, 0.33, time * 0.9,
    baseWidth * 0.9, curlAmt * 1.1,
    bassVal, trebleVal, beatPulse, onsetVal, paletteShift);
  col += t2.rgb * t2.a;

  // === TENDRIL 3: Orange-pink, diagonal ===
  float t3x = p.x * 0.85 + p.y * 0.5;
  float t3y = p.y * 0.85 - p.x * 0.5;
  vec4 t3 = smokeTendril(t3x, t3y,
    3.1, 1.3, 3.0, 0.6, time * 1.1,
    baseWidth * 0.85, curlAmt * 0.9,
    bassVal, trebleVal, beatPulse, onsetVal, paletteShift);
  col += t3.rgb * t3.a;

  // === TENDRIL 4: Deep violet, vertical-ish ===
  float t4x = p.x * 0.3 + p.y * 0.95;
  float t4y = p.y * 0.3 - p.x * 0.95;
  vec4 t4 = smokeTendril(t4x, t4y,
    2.0, 2.8, 5.0, 0.8, time * 0.8,
    baseWidth * 1.1, curlAmt * 1.2,
    bassVal, trebleVal, beatPulse, onsetVal, paletteShift);
  col += t4.rgb * t4.a;

  // === TENDRIL 5: Emerald, slow and wide ===
  vec4 t5 = smokeTendril(p.x, p.y,
    1.2, 3.5, 7.0, 0.45, time * 0.7,
    baseWidth * 1.3, curlAmt * 0.8,
    bassVal, trebleVal, beatPulse, onsetVal, paletteShift);
  col += t5.rgb * t5.a;

  // === GLOBAL EFFECTS ===
  // Energy ambient brightness
  col += energyVal * 0.04;

  // Beat overall pulse
  col += beatPulse * 0.05;

  // Apply intensity
  col *= uIntensity * 1.7;

  // === PSYCHEDELIC ENHANCEMENT ===
  col = psychedelicColor(col);
  gl_FragColor = vec4(
    clamp(col.r, 0.0, 1.0),
    clamp(col.g, 0.0, 1.0),
    clamp(col.b, 0.0, 1.0),
    1.0
  );
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uWeaveScale;
uniform float uColorSteps;
uniform float uThreadWidth;

#define TAU 6.28318530

// Stepped/quantized value for textile look
float quantize(float v, float steps) {
  return floor(v * steps + 0.5) / steps;
}

// Aztec/tribal pattern generator
float aztecPattern(vec2 p, float time) {
  // Diamond pattern
  float diamond = abs(p.x) + abs(p.y);
  diamond = fract(diamond);

  // Stepped zigzag
  float zigzag = abs(fract(p.x * 0.5 + p.y * 0.5) - 0.5) * 2.0;

  // Cross motif
  float crossH = smoothstep(0.4, 0.35, abs(fract(p.y) - 0.5));
  float crossV = smoothstep(0.4, 0.35, abs(fract(p.x) - 0.5));
  float crossMotif = max(crossH * step(abs(fract(p.x) - 0.5), 0.15),
                         crossV * step(abs(fract(p.y) - 0.5), 0.15));

  // Combine with time animation
  float pattern = mix(diamond, zigzag, sin(time * 0.3) * 0.5 + 0.5);
  pattern = mix(pattern, crossMotif, 0.3);

  return pattern;
}

// Weave over/under determination
float weaveOverUnder(vec2 cell, float threadW) {
  vec2 f = fract(cell);
  float overH = step(0.5 - threadW, f.y) * step(f.y, 0.5 + threadW);
  float overV = step(0.5 - threadW, f.x) * step(f.x, 0.5 + threadW);

  // Checkerboard determines which thread is on top
  vec2 id = floor(cell);
  float checker = mod(id.x + id.y, 2.0);

  if (overH > 0.0 && overV > 0.0) {
    return checker;
  }
  return -1.0; // no crossing
}

vec3 tapestryPalette(float t, float offset, float steps) {
  // Warm earth tones with saturated accents (Navajo/Aztec feel)
  vec3 base = vec3(
    0.5 + 0.45 * cos(TAU * (t * 0.8 + 0.0 + offset * 0.2)),
    0.4 + 0.35 * cos(TAU * (t * 0.8 + 0.15 + offset * 0.2)),
    0.3 + 0.3 * cos(TAU * (t * 0.8 + 0.4 + offset * 0.2))
  );

  // Quantize for textile stepped-color effect
  float q = max(3.0, steps * 12.0);
  base.r = floor(base.r * q + 0.5) / q;
  base.g = floor(base.g * q + 0.5) / q;
  base.b = floor(base.b * q + 0.5) / q;

  // Boost saturation
  float lum = dot(base, vec3(0.299, 0.587, 0.114));
  base = mix(vec3(lum), base, 1.8);

  return clamp(base, 0.0, 1.0);
}

void main() {
  float time = uTime * (uSpeed * 1.0);
  vec2 p = (vUv - 0.5) * 2.0;
  p = psychedelicUV(p); // breathing morph

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float beatPulse = uBeat * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  // Weave grid scale
  float scale = 4.0 + uWeaveScale * 12.0 + beatPulse * 2.0;
  vec2 wv = p * scale * (uZoom * 2.0 + 0.5);

  // Thread width
  float threadW = 0.15 + uThreadWidth * 0.3;

  // Slow scroll animation
  wv += vec2(time * 0.2, time * 0.15);

  // Chaos: add subtle distortion
  wv += vec2(sin(wv.y * 0.5 + time), cos(wv.x * 0.5 + time)) * uChaos * 0.3;

  // Cell coordinates
  vec2 cellId = floor(wv);
  vec2 cellF = fract(wv);

  // Determine warp and weft threads
  float isWarp = step(0.5 - threadW, cellF.x) * step(cellF.x, 0.5 + threadW);
  float isWeft = step(0.5 - threadW, cellF.y) * step(cellF.y, 0.5 + threadW);

  // Over/under at crossings
  float checker = mod(cellId.x + cellId.y, 2.0);

  // Aztec/tribal pattern for thread coloring
  float pattern = aztecPattern(wv * 0.25, time);
  float patternStepped = quantize(pattern, 3.0 + uColorSteps * 8.0);

  // Thread colors - warp and weft have different palette offsets
  float warpColorT = patternStepped + cellId.y * 0.1 + midsVal * 0.3;
  float weftColorT = patternStepped + cellId.x * 0.1 + 0.5 + midsVal * 0.3;

  vec3 warpColor = tapestryPalette(warpColorT, uPalette, uColorSteps);
  vec3 weftColor = tapestryPalette(weftColorT, uPalette + 0.5, uColorSteps);

  vec3 color = vec3(0.05, 0.04, 0.03); // Dark background between threads

  // Draw threads with over/under
  if (isWarp > 0.0 && isWeft > 0.0) {
    // Crossing point: checker determines which is on top
    color = checker > 0.5 ? warpColor : weftColor;

    // Shadow at crossing edge
    float crossEdge = min(
      min(abs(cellF.x - (0.5 - threadW)), abs(cellF.x - (0.5 + threadW))),
      min(abs(cellF.y - (0.5 - threadW)), abs(cellF.y - (0.5 + threadW)))
    );
    color *= 0.8 + 0.2 * smoothstep(0.0, 0.05, crossEdge);
  } else if (isWarp > 0.0) {
    color = warpColor;
    // Thread texture: subtle stripe along thread
    float threadTex = sin(cellF.y * 30.0 + bassVal * 5.0) * 0.05;
    color += threadTex;
  } else if (isWeft > 0.0) {
    color = weftColor;
    float threadTex = sin(cellF.x * 30.0 + bassVal * 5.0) * 0.05;
    color += threadTex;
  }

  // Thread shimmer from treble
  float shimmer = sin((cellF.x + cellF.y) * 40.0 + time * 5.0) * trebleVal * 0.1;
  color += shimmer * max(isWarp, isWeft);

  // Beat pulse
  color += beatPulse * 0.08;

  // Onset shifts pattern
  color = mix(color, color.brg, onsetVal * 0.2);

  // Kick highlights
  color += kickVal * 0.05;

  // Intensity
  color *= uIntensity * 1.4;

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

varying vec2 vUv;
__SA_DECLS__
__SA_FUNCS__

uniform float uSensitivity;
uniform float uPalette;
uniform float uSpeed;
uniform float uZoom;
uniform float uIntensity;
uniform float uChaos;

uniform float uFrameCount;
uniform float uSlitWidth;
uniform float uAnimPhase;
uniform float uDiscLayers;

vec3 zoetropePalette(float t, float offset) {
  // Warm vintage palette (sepia-ish with neon accents)
  vec3 a = vec3(0.5, 0.4, 0.3);
  vec3 b = vec3(0.5, 0.4, 0.4);
  vec3 c = vec3(1.0, 0.8, 0.7);
  vec3 d = vec3(0.1 + offset, 0.3 + offset, 0.5 + offset);
  return a + b * cos(6.2832 * (c * t + d));
}

// Draw an animated figure at a specific frame
float animFrame(vec2 p, float frameIdx, float totalFrames, float phase) {
  float t = frameIdx / totalFrames * phase;

  // Simple animated figure: a bouncing/morphing shape
  float bounceY = sin(t * 6.2832) * 0.15;
  float squash = 1.0 + cos(t * 6.2832) * 0.3;

  // Morphing shape: circle to star to circle
  float r = length(p - vec2(0.0, bounceY));
  float angle = atan(p.y - bounceY, p.x);

  // Star/circle morph
  float starPhase = sin(t * 6.2832 * 2.0) * 0.5 + 0.5;
  float starArms = 5.0;
  float starMod = 1.0 + sin(angle * starArms + t * 6.2832) * 0.3 * starPhase;
  float shapeRadius = 0.12 * starMod / squash;

  float shape = smoothstep(shapeRadius + 0.01, shapeRadius - 0.01, r);

  // Motion lines (speed streaks)
  float speedLines = 0.0;
  float velY = cos(t * 6.2832) * 0.3;
  if (abs(velY) > 0.1) {
    float lineY = p.y - bounceY;
    float linePattern = sin(lineY * 40.0) * 0.5 + 0.5;
    linePattern *= smoothstep(0.2, 0.05, abs(p.x));
    linePattern *= step(0.0, -sign(velY) * lineY);
    linePattern *= smoothstep(0.0, 0.15, abs(lineY));
    speedLines = linePattern * abs(velY) * 0.3;
  }

  return shape + speedLines;
}

void main() {
  vec2 p = (vUv - 0.5) * (uZoom * 1.5 + 1.0);
  p = psychedelicUV(p); // breathing morph
  float time = uTime * uSpeed * 2.0;

  float bassVal = bass() * uSensitivity;
  float midsVal = mids() * uSensitivity;
  float trebleVal = treble() * uSensitivity;
  float onsetVal = uOnset * uSensitivity;
  float kickVal = uKick * uSensitivity;

  vec3 color = vec3(0.0);
  float maxLayers = min(uDiscLayers, 4.0);

  for (float layer = 0.0; layer < 4.0; layer += 1.0) {
    if (layer >= maxLayers) break;

    // Each layer is a concentric ring — expanded for full-screen fill
    float innerR = 0.08 + layer * 0.22;
    float outerR = innerR + 0.20;

    float r = length(p);
    float angle = atan(p.y, p.x);

    // Check if pixel is in this ring
    float ringMask = smoothstep(innerR - 0.01, innerR + 0.01, r) *
                     smoothstep(outerR + 0.01, outerR - 0.01, r);

    if (ringMask < 0.01) continue;

    // Disc rotation (different speed per layer)
    float rotSpeed = 1.0 + layer * 0.3 + bassVal * 0.5;
    float discAngle = angle - time * rotSpeed;

    // Frame index: which animation frame are we looking at
    float frames = uFrameCount + layer * 2.0;
    float sector = 6.2832 / frames;
    float frameIdx = floor((discAngle + 3.14159) / sector);
    float frameFrac = fract((discAngle + 3.14159) / sector);

    // Slit mask: only show through narrow slits
    float slitMask = smoothstep(0.5 - uSlitWidth * 0.5, 0.5 - uSlitWidth * 0.5 + 0.05, frameFrac) *
                     smoothstep(0.5 + uSlitWidth * 0.5 + 0.05, 0.5 + uSlitWidth * 0.5, frameFrac);

    // Local coordinates within the frame
    float localAngle = (frameFrac - 0.5) * sector * 2.0;
    float localR = (r - innerR) / (outerR - innerR) - 0.5;
    vec2 localP = vec2(localAngle, localR);

    // Animation phase: audio controls animation speed
    float phase = uAnimPhase + kickVal * 0.3 + layer * 0.2;

    // Draw the animated figure
    float figure = animFrame(localP, frameIdx, frames, phase);

    // Chaos: occasional frame glitches
    float glitch = step(0.9, sin(frameIdx * 13.37 + time * 0.1)) * uChaos;
    figure = mix(figure, 1.0 - figure, glitch);

    // Color per layer
    float hue = layer * 0.25 + uPalette * 0.1 + midsVal * 0.1;
    vec3 frameColor = zoetropePalette(figure * 0.3 + hue, uPalette * 0.05);

    // Apply the slit mask and ring mask
    float visible = figure * slitMask * ringMask;

    // Frame border glow
    float borderGlow = smoothstep(0.01, 0.0, abs(frameFrac - 0.5 - uSlitWidth * 0.5)) +
                       smoothstep(0.01, 0.0, abs(frameFrac - 0.5 + uSlitWidth * 0.5));
    borderGlow *= trebleVal * 0.3;

    color += frameColor * visible + vec3(borderGlow * 0.1, borderGlow * 0.15, borderGlow * 0.2) * ringMask;
  }

  // Disc structure lines (ring boundaries)
  float r = length(p);
  for (float layer = 0.0; layer < 4.0; layer += 1.0) {
    if (layer >= maxLayers) break;
    float ringR = 0.08 + layer * 0.22;
    float ringLine = exp(-pow((r - ringR) * 50.0, 2.0));
    color += vec3(ringLine * 0.15);
  }

  // Center hub
  float hubGlow = exp(-r * 5.0);
  color += zoetropePalette(time * 0.05, uPalette * 0.1) * hubGlow * 0.3;

  // Outer glow to fill screen edges
  float outerGlow = smoothstep(0.5, 0.9, r) * 0.06;
  color += zoetropePalette(time * 0.03 + r, uPalette * 0.1) * outerGlow;

  // Intensity and energy
  color *= uIntensity * 1.3 + uEnergy * uSensitivity * 0.3;

  // Beat pulse
  color += vec3(uBeat * uSensitivity * 0.05);

  // Onset flash
  color = mix(color, color + vec3(0.1, 0.08, 0.05), onsetVal * 0.3);

  // Contrast
  color = pow(clamp(color, 0.0, 1.0), vec3(1.2));

  // === PSYCHEDELIC ENHANCEMENT ===
  color = psychedelicColor(color);
  gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}
